function state.craftQuantity(target,owned,balance,reserve,price,give,capacity)
    for _,value in ipairs({target,owned,balance,reserve,price,give,capacity}) do
        if type(value)~="number" or value~=value or value<0 then return 0 end
    end
    if price<1 or give<1 or price==math.huge or give==math.huge then return 0 end
    return math.max(0,math.min(1000,math.floor(target/give),math.floor((balance-reserve)/price),math.floor((capacity-owned)/give)))
end
function state.craftReceiptStatus(receipt,owned,balance,now)
    if owned>receipt.stock then return "confirmed" end
    if balance<receipt.balance then return "consumed_unconfirmed" end
    if balance>receipt.balance or owned<receipt.stock then return "changed" end
    return now-receipt.at>=15 and "unknown" or "waiting"
end


-- Order quantities are additional units, never an inventory stock target.
function state.orderCredit(setting,receipt,stock,bought)
    if receipt.quantityVersion~=2 or not setting then return 0 end
    local expected=tonumber(receipt.expected) or 0
    local prior=tonumber(receipt.credited) or 0
    local gain=math.max(0,stock-receipt.stock,((bought or receipt.bought or 0)-(receipt.bought or 0))*(receipt.give or 1))
    local confirmed=math.min(expected,gain)
    local delta=math.max(0,confirmed-prior)
    receipt.credited=math.max(prior,confirmed)
    setting.target=math.max(0,setting.target-delta)
    return delta
end
function state.orderBatch(mode)
    return (mode=="MAX" or mode=="1000x") and 1000 or mode=="100x" and 100 or mode=="10x" and 10 or 1
end

function state.craftBatchChoices(category)
    if category=="Gems" then return {"1x","MAX"} end
    if category=="Keys" then return {"1x"} end
    if category=="Tokens" then return {"1x","10x","100x","1000x","MAX"} end
    return {"1x","10x","1000x"}
end
function state.craftBatchMode(category,selected)
    if selected=="MAX" and category~="Tokens" and category~="Keys" and category~="Gems" then return "1000x" end
    for _,mode in ipairs(state.craftBatchChoices(category)) do if mode==selected then return mode end end
    return "1x"
end
function state.craftRecipeLabel(recipe,nameOf)
