function state.craftOperationAmount(remaining,stock,capacity,give,affordable,batch,maximum)
    for _,n in ipairs({remaining,stock,capacity,give,affordable,batch,maximum}) do
        if type(n)~="number" or n~=n or n<0 then return 0 end
    end
    if give<1 or give==math.huge then return 0 end
    return math.max(0,math.floor(math.min(remaining/give,(capacity-stock)/give,affordable,batch,maximum)))
end
function state.craftTokenOptions(deps,family,side)
    local options={}
    if family=="Gacha" and deps.gacha then
        local g=deps.gacha
        if side=="source" then options[#options+1]={id=g.CONFIG.GenericSource,name=g.TokenName(g.CONFIG.GenericToken),currency=g.CONFIG.GenericToken} end
        for _,entry in ipairs(g.List()) do
            if side~="source" or clientData.Get("Gachas",entry.Id)~=nil then
                options[#options+1]={id=entry.Id,name=entry.Info.Name.." · "..g.TokenName(entry.Info.Currency),currency=entry.Info.Currency}
            end
        end
    elseif family=="Upgrade" and deps.upgrade then
        local u=deps.upgrade
        if side=="source" then options[#options+1]={id=u.GENERIC_SOURCE,name=u.ItemName(u.GENERIC_TOKEN),currency=u.GENERIC_TOKEN} end
        for id,info in pairs(u.UPGRADES) do
            if info.Currency and u.WorldOpen(info) and (side~="source" or info.Currency~=u.GENERIC_TOKEN) then
                options[#options+1]={id=id,name=(info.Name or id).." · "..u.ItemName(info.Currency),currency=info.Currency}
            end
        end
    end
    table.sort(options,function(a,b) return a.name<b.name end)
    return options
end
function state.discoverCraftCatalog(deps,tokens,data)
    local entries={}
    -- Classify by resource family, but obtain every product/cost from the live shop.
    for _,item in ipairs(deps.shop.Load("ExchangeShop")) do
        local source=item.PriceType
        local category=source:match("^Ench") and item.Real:match("^Ench") and "Dust"
            or source:match("^Upg") and item.Real:match("^Upg") and "Cores"
        local price=tonumber(item.Price)
        if category and item.Kind=="Item" and price and price>0 then
            -- Native aliases identify reverse offers and their actual output quantity.
            local rank={Common=1,Uncommon=2,Rare=3,Epic=4,Legendary=5,Mythical=6,Secret=7,Monarch=8}
            local from=deps.items[source] or {}
            local to=deps.items[item.Real] or {}
            local forward=(rank[to.Rarity] or 0)>(rank[from.Rarity] or 100)
            local mythicalDustToLegendary=source=="EnchMythical" and item.Real=="EnchLegendary"
                and item.PriceInfo.Item=="EnchLegendary"
            local mythicalCoreToLegendary=source=="UpgMonarch" and item.Real=="UpgMythic"
                and item.PriceInfo.Item=="UpgMythic"
            if forward or mythicalDustToLegendary or mythicalCoreToLegendary then
                entries[#entries+1]={key=item.Id,id=item.Id,output=item.Real,source=source,kind="Shop",category=category,
                    name=item.Name,image=item.Image,give=tonumber(item.PriceInfo.GiveAmount) or 1,max=deps.shop.MAX_AMOUNT or 1000,
                    costs={[source]=price},item=item}
            end
        end
    end
    for id,native in pairs(deps.recipes) do
        if type(native)~="table" then continue end
        local result=native.Craft
        if type(native)=="table" and (native.Type=="Keys" or native.Type=="Gems") and not native.Forge and not native.Pets
            and type(result)=="table" and result.Type=="Items" and type(result.Name)=="string" then
            entries[#entries+1]={key=(native.Type=="Gems" and "Gem:" or "Key:")..id,id=id,output=result.Name,kind=native.Type=="Gems" and "Gem" or "Key",category=native.Type,
                name=native.Name or result.Name,image=native.Icon,give=tonumber(result.Amount) or 1,
                max=native.Type=="Gems" and (tonumber(deps.maxCraftRepeats) or 1) or 1,costs=native.Items,native=native,release=native.Release,order=native.Order or 0}
        end
    end
    for _,family in ipairs({"Gacha","Upgrade"}) do
        local pair=tokens[family]
        if not pair then continue end
        local from,to
        for _,entry in ipairs(state.craftTokenOptions(deps,family,"source")) do if entry.id==pair.source then from=entry end end
        for _,entry in ipairs(state.craftTokenOptions(deps,family,"destination")) do if entry.id==pair.destination then to=entry end end
        if from and to and from.currency~=to.currency then
            local rate=family=="Gacha" and deps.gacha.CONFIG.ExchangeRate or deps.upgrade.EXCHANGE_RATE
            local maximum=family=="Gacha" and deps.gacha.CONFIG.MaxExchange or deps.upgrade.MAX_EXCHANGE
            if type(rate)=="number" and rate>0 and type(maximum)=="number" and maximum>0 then
                entries[#entries+1]={key="Token:"..family..":"..from.id..":"..to.id,id=to.currency,output=to.currency,
                    source=from.currency,kind="Token",category="Tokens",family=family,origin=from.id,destination=to.id,
                    name=from.name.." -> "..to.name,give=1,max=maximum,costs={[from.currency]=rate}}
            end
        end
    end
    table.sort(entries,function(a,b)
        if a.category~=b.category then return a.category<b.category end
        if (a.order or 0)~=(b.order or 0) then return (a.order or 0)<(b.order or 0) end
        return a.key<b.key
    end)
    return entries
end
function state.craftReceiptCredit(setting, receipt, owned, bought, allowStock)
    -- Observe gains between updates, even after the output was consumed elsewhere.
    local previous = receipt.observedStock or receipt.stock
    receipt.observedGain = (receipt.observedGain or 0) + math.max(0, owned - previous)
    receipt.observedStock = owned
    return state.orderCredit(setting, receipt, receipt.stock + (allowStock==false and 0 or receipt.observedGain), bought)
end
function state.craftReceiptDebited(recipe, receipt, balance, now)
    if recipe.kind ~= "Shop" or recipe.source == recipe.output or now - receipt.at < 15 then return false end
    local cost = recipe.costs[recipe.source]
    local operations = (receipt.expected or 0) / (receipt.give or 1)
    if type(cost) ~= "number" or cost <= 0 or cost >= math.huge
        or operations <= 0 or operations % 1 ~= 0 then return false end
    return receipt.balance - balance >= operations * cost
end
function state.craftHasCycle(recipe,catalog,items)
    if recipe.kind=="Key" or recipe.kind=="Gem" then return false end
    local function reaches(currency,goal,visited)
        if currency==goal then return true end
        if visited[currency] then return false end
        visited[currency]=true
        for _,other in ipairs(catalog) do
            local setting=items[other.key]
            if other~=recipe and other.kind~="Key" and other.source==currency
                and setting and state.craftOrderActive(setting) then
                if reaches(other.output,goal,visited) then return true end
            end
        end
        return false
    end
    return reaches(recipe.output,recipe.source,{})
end

