function state.buyReceiptCredit(settings, receipt, owned, bought)
    local finite = settings and settings.target > 0
    local delta = state.orderCredit(settings, receipt, owned, bought)
    if finite and delta > 0 and settings.target == 0 then settings.enabled = false end
    return delta
