function state.buyContinuousReceiptSettled(settings, receipt, now)
    return settings ~= nil and settings.target == 0 and receipt.quantityVersion == 2
        and (tonumber(receipt.credited) or 0) > 0
        and now - (tonumber(receipt.at) or now) >= 30
end
function state.gearTomePurchasePending(buy)
    local function waiting(receipt)
        if not receipt then return false end
        return not (receipt.quantityVersion==2 and (tonumber(receipt.expected) or 0)>0
            and (tonumber(receipt.credited) or 0)>=(tonumber(receipt.expected) or 0))
    end
    local function isTome(receipt)
        return receipt and type(receipt.key)=="string" and receipt.key:match(":GearTome$")~=nil
    end
    if isTome(buy.pending) and waiting(buy.pending) then return true end
    for _,receipt in pairs(buy.unconfirmed or {}) do
        if isTome(receipt) and waiting(receipt) then return true end
    end
    return false
end
function state.gearTomeBlocksPurchase(itemId)
    return itemId=="GearTome" and (state.gearTomes.pending~=nil
        or state.gearTomes.enabled==true and state.gearTomeUseTurn==true)
end
-- An explicit off/on cycle resets only this item's local receipt wait.
function state.toggleBuyItem(buy, key, now)
    local settings = buy.items[key]
    if not settings then return false end
    settings.enabled = not settings.enabled
    if settings.enabled then
        local pending = buy.pending and buy.pending.key == key and buy.pending or nil
        local uncertain = buy.unconfirmed[key]
        if pending or uncertain then
            settings.resetReceipt = {at=now, pending=pending, unconfirmed=uncertain}
            settings.resetUntil = now + 30
            if pending then buy.pending = nil end
            buy.unconfirmed[key] = nil
        end
    end
    return true
end
