-- Only shared inputs/outputs can invalidate an infusion's balance-based receipt.
function state.buyTouchesInfusion(item,costs,payment)
    if type(item)~="table" or type(costs)~="table" then return false end
    if item.PriceType and costs[item.PriceType] then return true end
    if payment=="Gems" and item.PriceType=="Gems" then return true end
    return item.Kind=="Item" and costs[item.Real]~=nil
end
function state.buyInfusionBlocked(item)
    local prefs=state.craft.infusion
    local pending=prefs and prefs.pending
    return pending~=nil and state.buyTouchesInfusion(item,pending.costs,pending.payment)
end

-- A craft may change an infusion receipt only through a shared input/output.
function state.craftInfusionBlocked(recipe,inputs)
    local prefs=state.craft.infusion
    local pending=prefs and prefs.pending
    if not pending then return false end
    if type(pending.costs)~="table" or type(inputs)~="table" then return true end
    for id in pairs(pending.costs) do
        if inputs[id]~=nil or recipe.output==id then return true end
    end
    return pending.payment=="Gems" and (inputs.Gems~=nil or recipe.output=="Gems")
end

-- RESPONSIVE WINDOW POLICY: geometry only; gameplay preferences are not changed.
function state.responsiveDefaultSize(viewWidth, viewHeight)
    local availableWidth, availableHeight = math.max(1, viewWidth - 24), math.max(1, viewHeight - 24)
    local width = math.clamp(availableWidth, 480, 980)
    local unit = math.min(1, availableWidth / width)
    local height = math.clamp(availableHeight / math.max(unit, 0.001), 360, viewWidth > viewHeight and 620 or 820)
    unit = math.min(unit, availableHeight / height)
    return width, height, unit
end
function state.responsiveColumns(width)
    return width >= 740 and 2 or 1
end
function state.responsivePack(entries, width, columns, gap)
    gap = gap or 10
    local columnWidth = (width - gap * (columns - 1)) / columns
    local levels, result = {}, {}
    for column = 1, columns do levels[column] = 0 end
    for _, item in ipairs(entries) do
        local column = 1
        if not item.span then
            if item.column and item.column <= columns then column = item.column
            else for c = 2, columns do if levels[c] < levels[column] then column = c end end end
        end
        local top = levels[column]
        if item.span then for c = 1, columns do top = math.max(top, levels[c]) end end
        result[item.id] = {x = item.span and 0 or (column - 1) * (columnWidth + gap), y = top,
            w = item.span and width or columnWidth, h = item.height}
        if item.span then for c = 1, columns do levels[c] = top + item.height + gap end
        else levels[column] = top + item.height + gap end
    end
    local bottom = 0
    for _, level in ipairs(levels) do bottom = math.max(bottom, level) end
    return result, math.max(0, bottom - gap)
end
