-- REBIRTH POLICY
local function canRebirth(level, count, balance)
    if type(level) ~= "number" or type(count) ~= "number" or level ~= level or count ~= count
        or count < 0 or count >= balance.MaxRebirth then return false end
    local required = math.floor(balance.MaxLevel + (count >= 1 and count * balance.RebirthLevelIncrease or 0))
    return level >= required, required
end
local function nextStatAllocation(config, current, points, maximum)
    if not config.distribute or type(points) ~= "number" or points ~= points or points < 1 then return nil end
    for _, id in ipairs(config.order) do
        local goal = config.autoMax and config.autoMax[id] == true and maximum or math.min(config.targets[id] or 0, maximum)
        local owned = tonumber(current[id]) or 0
        local amount = math.floor(math.min(points, goal - owned))
        if amount > 0 then return id, amount end
    end
    return nil
end
