-- Stable rank values in profiles; independent of JSON object/array key handling.
do
    function state.sellRankSelection(value)
        local result = {}
        if type(value) ~= "table" then return result end
        if type(value.selectedRankIds) == "table" then
            for _, id in pairs(value.selectedRankIds) do
                local n = tonumber(id)
                if n and n >= 1 and n == math.floor(n) then result[tostring(n)] = true end
            end
        else
            for id, selected in pairs(type(value.ranks) == "table" and value.ranks or {}) do
                local n = tonumber(id)
                if selected == true and n and n >= 1 and n == math.floor(n) then result[tostring(n)] = true end
            end
        end
        return result
    end
    function state.sellProfile(config)
        local function section(value)
            local ids = {}
            for id, selected in pairs(value.ranks) do
                local n = tonumber(id)
                if selected == true and n and n >= 1 and n == math.floor(n) then table.insert(ids, n) end
            end
            table.sort(ids)
            local ranks = {}
            for _, id in ipairs(ids) do ranks[tostring(id)] = true end
            return {enabled = value.enabled == true, stacks = value.stacks ~= false,
                ranks = ranks, selectedRankIds = ids}
        end
        local result = section(config)
        result.bulk = config.bulk == true
        result.weapons = section(config.weapons)
        return result
    end
    -- Compare persisted choices, not table identity or JSON key ordering.
    function state.sellProfilesEqual(expected, actual)
        if type(expected) ~= "table" or type(actual) ~= "table" then return false end
        local function sameSection(left, right, swords)
            if type(left) ~= "table" or type(right) ~= "table" then return false end
            if (left.enabled == true) ~= (right.enabled == true) then return false end
            if swords and (left.stacks ~= false) ~= (right.stacks ~= false) then return false end
            local leftRanks = state.sellRankSelection(left)
            local rightRanks = state.sellRankSelection(right)
            for id in pairs(leftRanks) do if not rightRanks[id] then return false end end
            for id in pairs(rightRanks) do if not leftRanks[id] then return false end end
            return true
        end
        return sameSection(expected, actual, false)
            and (expected.bulk == true) == (actual.bulk == true)
            and sameSection(expected.weapons, actual.weapons, true)
    end
end

