-- RAID JOURNEY SCHEMA: JSON only; deadlines use server time across teleports.
function state.restoreRaidTravel(value, now)
    if type(value)~="table" or not state.openRaids[value.kind]
        or (value.phase~="going" and value.phase~="arrived" and value.phase~="returning") then return nil end
    local world, deadline=tonumber(value.originWorld),tonumber(value.expiresAt)
    local eventUntil=tonumber(value.eventUntil)
    if not world or world%1~=0 or world<1 or world>3 or not deadline or not eventUntil
        or deadline~=deadline or eventUntil~=eventUntil or deadline<=now or deadline>now+3600 then return nil end
    local position=value.originPosition
    if type(position)~="table" then return nil end
    for _,key in ipairs({"x","y","z"}) do
        local n=position[key]
        if type(n)~="number" or n~=n or math.abs(n)>1000000 then return nil end
    end
    return {kind=value.kind, phase=value.phase, originWorld=world,
        originPosition={x=position.x,y=position.y,z=position.z},
        originMap=type(value.originMap)=="string" and value.originMap or nil,
        eventUntil=eventUntil,expiresAt=deadline,attempts=math.clamp(tonumber(value.attempts) or 0,0,3),
        nextAttemptAt=math.min(tonumber(value.nextAttemptAt) or 0,now+20)}
end
function state.closeOpenRaid(kind, now)
    local raid=state.openRaids[kind]
    if not raid then return end
    state.raidClosures=state.raidClosures or {}
    state.raidClosures[kind]=math.max(raid.untilAt or 0,now+30)
    raid.untilAt,raid.closed,raid.closedAt,raid.ended=0,true,now,true
    raid.travelStatus,raid.retryAt=nil,nil
end
function state.openRaidProfile()
    local values={}
    for _,kind in ipairs(state.openRaidOrder) do values[kind]=state.openRaids[kind].enabled==true end
    return values
end
function state.openRaidEnabled(kind)
    local raid=state.openRaids[kind]
    if state.questPriorityActive and state.questPriorityActive() then return raid~=nil and state.questWantsEvent(kind) end
    return raid ~= nil and (raid.enabled == true or state.questWantsEvent and state.questWantsEvent(kind)==true)
end
function state.openRaidCandidate(raid, id, shield)
    local ids=raid and (raid.combatIds or raid.ids)
    if raid and raid.kind=="giants" and state.giantsMode=="legia" then
        if shield==true then return nil end
        if state.giantsInvaderIds[id] then return 2 end
        if id=="GiantArmor" then return 3 end
    end
    if not ids or not ids[id] then return nil end
    if shield == true or (id=="JJ3" and raid.queenShield==true) then return nil end
    return ids[id]
end
function state.openRaidAvailable(raid, world, now, present)
    if not state.openRaidEnabled(raid.kind) or tonumber(world)~=raid.world or raid.closed then return false end
    if now < (raid.retryAt or 0) then return false end
    return present==true or (raid.untilAt or 0)>now
end
function state.openRaidObserve(raid, now, present)
    local suppressed=state.raidClosures and state.raidClosures[raid.kind]
    if suppressed and now<suppressed then raid.closed=true return end
    if suppressed then state.raidClosures[raid.kind]=nil end
    if raid.closed then
        if not present and now-(raid.closedAt or now)>5 then
            raid.closed,raid.ended,raid.hadMarkers,raid.queenShield=nil,nil,nil,nil
        end
        return
    end
    if present and not raid.hadMarkers and (raid.untilAt or 0)<=now then raid.untilAt=now+900
    elseif present and raid.hadMarkers and (raid.untilAt or 0)>0 and now>=raid.untilAt then
        raid.closed,raid.closedAt=true,now
    end
    raid.hadMarkers=present
end
function state.openRaidPacket(packet, now)
    if type(packet)~="table" then return end
    if packet.Event=="QueenShield" then
        if type(packet.Active)=="boolean" then
            state.openRaids.dedu.queenShield=packet.Active
            if packet.Active and events.active=="dedu" and state.target and state.target:GetAttribute("Id")=="JJ3" then
                state.target,state.searchPosition=nil,nil
                generation+=1
            end
        end
        return
    end
    for kind,raid in pairs(state.openRaids) do
        if packet.Event==raid.finish then
            raid.untilAt,raid.closed,raid.closedAt,raid.queenShield=0,true,now,nil
            raid.hadMarkers=nil
            raid.travelStatus,raid.retryAt=nil,nil
            if events.active==kind then raid.ended=true end
        end
    end
end
