-- PURCHASE POLICY
local function purchaseAmount(target, stock, balance, reserve, price, bought, limit, multiple, unique)
    if type(price) ~= "number" or price <= 0 or price ~= price then return 0 end
    local goal = unique and math.min(target, 1) or target
    local amount = math.min(math.floor(goal - stock), math.floor((balance - reserve) / price), 30)
    if limit then amount = math.min(amount, math.floor(limit - bought)) end
    if not multiple then amount = math.min(amount, 1) end
    return math.max(0, amount)
end
local function claimableDays(data, total)
    local days = {}
    for day = 1, math.min(tonumber(data.Streak) or 0, total) do
        if not (data.Reward or {})[day] and not (data.Reward or {})[tostring(day)] then table.insert(days, day) end
    end
    return days
end
local function claimablePassRewards(data, info, missing)
    local ready = {}
    for tier = 1, math.min(tonumber(data.Level) or 0, info.MaxLevel or 0) do
        local rewards = (info.Rewards or {})[tier] or {}
        local claimed = (data.Rewards or {})[tier] or (data.Rewards or {})[tostring(tier)] or {}
        for _, track in ipairs({"Free", "Premium"}) do
            if type(rewards[track]) == "table" and not claimed[track] and (track == "Free" or data.Premium == true)
                and missing(rewards[track]) == nil then table.insert(ready, tier .. track) end
        end
    end
    return ready
end
-- END PURCHASE POLICY
-- SHADOW CRAFT POLICY: selections are UIDs; opening the interface never starts a purchase.
do
function state.shadowCraftRestore(value)
    value=type(value)=="table" and value or {}
    local function integer(key,default,low,high)
        local n=tonumber(value[key]);return n and n==n and n<math.huge and math.clamp(math.floor(n),low,high) or default
    end
    local result={scope=value.scope=="all" and "all" or "selected",selected={},targets={},
        targetRank=integer("targetRank",0,0,99),limit=integer("limit",1,1,500),stopMode="target",
        reserveTickets=0,reserveMaterials=0,reserveCores=0,allowHigh=value.allowHigh==true,rankSelected={}}
    if value.rankScope=="one" or value.rankScope=="all" then result.rankScope=value.rankScope end
    if type(value.rankName)=="string" and #value.rankName<=150 then result.rankName=value.rankName end
    result.rankFrom=integer("rankFrom",0,0,99)
    for id,on in pairs(type(value.rankSelected)=="table" and value.rankSelected or {}) do
        if type(id)=="string" and #id<=150 and on==true then result.rankSelected[id]=true end
    end
    for id,on in pairs(type(value.selected)=="table" and value.selected or {}) do
        if type(id)=="string" and #id<=150 and on==true then result.selected[id]=true end
    end
    for _,key in ipairs({"Power","UltDamage","Speed","AtkSpeed"}) do
        local n=tonumber(type(value.targets)=="table" and value.targets[key]);result.targets[key]=n and n==n and math.clamp(math.floor(n),0,13) or 0
    end
    if type(value.detail)=="string" and #value.detail<=150 then result.detail=value.detail end
    result.finished={}
    for uid,on in pairs(type(value.finished)=="table" and value.finished or {}) do
        if type(uid)=="string" and #uid<=150 and on==true then result.finished[uid]=true end
    end
    -- Keep unfinished receipts opaque on reload; they block new operations until reconciled.
    if type(value.pending)=="table" and (value.pending.kind=="rank" or value.pending.kind=="reroll")
        and type(value.pending.at)=="number" and value.pending.at==value.pending.at and value.pending.at<math.huge
        and type(value.pending.costs)=="table" and type(value.pending.before)=="table" then result.pending=value.pending end
    return result
end
function state.shadowCraftPrefs()
    if not state.craft.shadows then state.craft.shadows=state.shadowCraftRestore(nil) end
    return state.craft.shadows
end
function state.shadowTargetsMet(entry,prefs)
    local any=false
    for _,key in ipairs({"Power","UltDamage","Speed","AtkSpeed"}) do
        local goal=prefs.targets[key] or 0
        if goal>0 then any=true;if ((entry.pet.Stats or {})[key] or 0)<goal then return false end end
    end
    return any
end
function state.shadowCraftEntries(inventory,equipped,pets)
    local entries={}
    for uid,pet in pairs(type(inventory)=="table" and inventory or {}) do
        local info=type(pet)=="table" and pets[pet.Name]
        local id=tostring(uid)
        if info then table.insert(entries,{uid=id,pet=pet,info=info,equipped=equipped[id]==true,
            eligible=not pet.Locked and not pet.InExp and not equipped[id] and not (state.craftSalePending and state.craftSalePending(id))}) end
    end
    table.sort(entries,function(a,b)
        if a.pet.Name~=b.pet.Name then return a.pet.Name<b.pet.Name end
        if a.pet.Rank~=b.pet.Rank then return (tonumber(a.pet.Rank) or 0)>(tonumber(b.pet.Rank) or 0) end
        return a.uid<b.uid
    end)
    return entries
end
function state.shadowCraftRankGroups(entries,balance)
    local map,list={},{}
    local cap=tonumber(balance.MaxSUpgrade) or 0
    for _,e in ipairs(entries) do
        local rank=tonumber(e.pet.Rank)
        if rank and rank>=1 and rank<cap then
            local source=rank<=6 and 0 or rank
            local id=e.pet.Name..":"..source
            local g=map[id]
            if not g then g={id=id,name=e.pet.Name,source=source,info=e.info,total=0,available=0,protected=0,ids={},counts={}};map[id]=g;table.insert(list,g) end
            g.total+=1
            if e.eligible then
                g.available+=1;table.insert(g.ids,e.uid);g.counts[rank]=(g.counts[rank] or 0)+1
            else g.protected+=1 end
        end
    end
    for _,g in ipairs(list) do
        g.groups=math.floor(g.available/6)
        if g.source==0 then
            g.groups=math.huge;g.distinct=0
            for rank=1,6 do g.groups=math.min(g.groups,g.counts[rank] or 0);if g.counts[rank] then g.distinct+=1 end end
        end
    end
    return list
end
function state.shadowCraftRankLimit(balance,playerRank)
    local ranks=balance.IndexerRanks or {}
    local cap=tonumber(balance.MaxSUpgrade) or 0
    local msr,msrPlus=tonumber(ranks.MSR) or 31,tonumber(ranks["MSR+"]) or 32
    local hl,hlPlus=tonumber(ranks.HL) or 47,tonumber(ranks["HL+"]) or 48
    if not playerRank or playerRank<hl then return math.min(cap,msr-1),msr,msrPlus,hl,hlPlus end
    if playerRank<hlPlus then return math.min(cap,msrPlus-1),msr,msrPlus,hl,hlPlus end
    return cap,msr,msrPlus,hl,hlPlus
end
function state.shadowCraftPlan(entries,prefs,balance,count,playerRank)
    local groups,ordered={},{}
    local cap=tonumber(balance.MaxSUpgrade)
    if not cap then return nil,"Limite nativo indisponível." end
    local allowed,msr,msrPlus=state.shadowCraftRankLimit(balance,playerRank)
    local target=prefs.targetRank==0 and allowed or math.min(prefs.targetRank,cap)
    if target>allowed then
        if not playerRank then return nil,"Aguardando o rank do jogador sincronizar." end
        return nil,state.shadowCraftText("Para evoluir para %s, seu jogador precisa de rank %s.",target>=msrPlus and "MSR+" or "MSR",target>=msrPlus and "HL+" or "HL")
    end
    if prefs.rankScope=="one" and not prefs.rankName then return nil,"Escolha a shadow e o rank atual para montar os grupos." end
    if prefs.rankScope=="one" and not next(prefs.rankSelected) then
        local locked=0
        for _,e in ipairs(entries) do
            local rank=tonumber(e.pet.Rank) or 0
            if e.pet.Name==prefs.rankName and (rank==prefs.rankFrom or prefs.rankFrom==0 and rank>=1 and rank<=6) and not e.eligible then locked+=1 end
        end
        if locked>0 then return nil,state.shadowCraftText("As %d cópias estão equipadas, bloqueadas ou em expedição.",locked) end
    end
    local included,below,protected,playerBlocked=0,0,0,0
    for _,entry in ipairs(entries) do
        local rank=tonumber(entry.pet.Rank)
        local selected=prefs.rankScope=="all" or prefs.rankScope=="one" and prefs.rankSelected[entry.uid] or not prefs.rankScope and (prefs.scope=="all" or prefs.selected[entry.uid])
        if selected and entry.eligible and rank==allowed and rank<cap then playerBlocked+=1 end
        if selected and rank then included+=1;if rank<target then below+=1;if not entry.eligible then protected+=1 end end end
        if entry.eligible and rank and rank>=1 and rank<target and selected then
            local first=rank<=6
            local key=entry.pet.Name..":"..(first and "first" or tostring(rank))
            if not groups[key] then
                groups[key]={kind="rank",name=entry.pet.Name,rank=first and 7 or rank+1,first=first,ids={},byRank={},rarity=entry.info.Rarity}
                table.insert(ordered,groups[key])
            end
            local group=groups[key]
            if first then
                if not group.byRank[tostring(rank)] then group.byRank[tostring(rank)]=entry.uid;table.insert(group.ids,entry.uid) end
            elseif #group.ids<6 then table.insert(group.ids,entry.uid) end
        end
    end
    local blocked,best
    for _,group in ipairs(ordered) do
        if not best or #group.ids>#best.ids then best=group end
        if #group.ids==6 and group.rank<=target then
            local prices=group.first and balance.UpgraderShadowPrice[group.rarity] or balance.RanksUpgradePrice[tostring(group.rank)]
            if prices then
                group.costs={}
                if group.first then group.costs.Ticket=prices.Ticket else for key,n in pairs(prices) do if n>0 then group.costs[key]=n end end end
                if not count or state.shadowCraftAffordable(group,prefs,count) then return group end
                blocked=blocked or group
            end
        end
    end
    if blocked then return blocked end
    if not best and playerBlocked>0 then
        if not playerRank then return nil,"Aguardando o rank do jogador sincronizar." end
        return nil,state.shadowCraftText("Para evoluir para %s, seu jogador precisa de rank %s.",allowed+1>=msrPlus and "MSR+" or "MSR",allowed+1>=msrPlus and "HL+" or "HL")
    end
    if prefs.rankScope then
        if included>0 and below==0 then return nil,"Rank desejado atingido para as shadows escolhidas." end
        if protected>0 and not best then return nil,"As cópias estão equipadas, bloqueadas ou em expedição." end
        if best then return nil,state.shadowCraftText("Faltam %d cópias elegíveis para formar outro grupo de seis.",math.max(0,6-#best.ids)) end
        return nil,"Nenhuma cópia elegível disponível para o grupo escolhido."
    end
    return nil,"Sem grupo elegível de seis cópias para o rank desejado."
end
function state.shadowRerollPlan(entries,prefs)
    local available=0
    for _,entry in ipairs(entries) do
        if prefs.selected[entry.uid] and not entry.pet.InExp then
            available+=1
            for _,key in ipairs({"Power","UltDamage","Speed","AtkSpeed"}) do
                local goal=prefs.targets[key] or 0
                local current=tonumber((entry.pet.Stats or {})[key]) or 0
                if goal>0 and current<goal then
                    if current>=12 and not prefs.allowHigh and prefs.stopMode=="limit" then return nil,"Autorize substituir notas N/M para continuar." end
                    return {kind="reroll",uid=entry.uid,name=entry.pet.Name,label=entry.info.Name or entry.pet.Name,stat=key,old=current,costs={ShadowUpgrader=4}}
                end
            end
        end
    end
    if available>0 then
        for _,goal in pairs(prefs.targets) do
            if goal>0 then return nil,"Metas atingidas para todas as shadows disponíveis selecionadas." end
        end
    end
    return nil,"Selecione shadows e metas; as metas atuais já podem estar atingidas."
end
function state.shadowCraftAffordable(plan,prefs,count)
    for key,price in pairs(plan.costs) do
        if type(price)~="number" or price~=price or price<=0 or price==math.huge then return false end
        if count(key)<price then return false end
    end
    return true
end
end
-- END SHADOW CRAFT POLICY
-- Infusion is independent from rank fusion and four-stat reroll.
do
state.infusionKeys={"UmbralPower","SpecterAgility","PhantomSwiftness","SoulScholar","CursedFortune","AbyssalFocus","EternalAscension"}
function state.infusionRestore(value)
    value=type(value)=="table" and value or {}
    local result={payment=value.payment=="Ticket" and "Ticket" or "Gems",targets={},locks={},selected={},locksByUid={}}
    local defaults={10,3,5,5,0,0,0}
    for i,key in ipairs(state.infusionKeys) do
        local n=type(value.targets)=="table" and tonumber(value.targets[key])
        result.targets[key]=n and n==n and n<math.huge and math.clamp(math.floor(n),0,99) or defaults[i]
        result.locks[key]=type(value.locks)=="table" and value.locks[key]==true or nil
    end
    if type(value.uid)=="string" and #value.uid<=150 then result.uid=value.uid end
    if type(value.selected)=="table" then
        for uid,on in pairs(value.selected) do if type(uid)=="string" and #uid<=150 and on==true then result.selected[uid]=true end end
    elseif result.uid then result.selected[result.uid]=true end
    result.finished={}
    for uid,on in pairs(type(value.finished)=="table" and value.finished or {}) do
        if type(uid)=="string" and #uid<=150 and on==true then result.finished[uid]=true end
    end
    for uid,locks in pairs(type(value.locksByUid)=="table" and value.locksByUid or {}) do
        if type(uid)=="string" and #uid<=150 and type(locks)=="table" then
            local clean={};for _,key in ipairs(state.infusionKeys) do if locks[key]==true then clean[key]=true end end
            result.locksByUid[uid]=clean
        end
    end
    if result.uid then
        if result.locksByUid[result.uid] then result.locks=result.locksByUid[result.uid]
        else result.locksByUid[result.uid]=result.locks end
    end
    local p=value.pending
    if type(p)=="table" and type(p.uid)=="string" and type(p.name)=="string" and type(p.at)=="number"
        and p.at==p.at and p.at<math.huge and type(p.before)=="table" and type(p.costs)=="table"
        and type(p.enchants)=="table" and type(p.signature)=="string" and #p.signature<=300
        and (p.payment=="Gems" or p.payment=="Ticket") then
        local valid,nextCost=true,false
        for id,cost in pairs(p.costs) do
            if type(id)~="string" or #id>100 or type(cost)~="number" or cost~=cost or cost<=0 or cost==math.huge
                or type(p.before[id])~="number" or p.before[id]~=p.before[id] or p.before[id]<0 or p.before[id]==math.huge then valid=false end
            nextCost=true
        end
        if valid and nextCost then result.pending=p end
    end
    result.unconfirmed={}
    for i,past in ipairs(type(value.unconfirmed)=="table" and value.unconfirmed or {}) do
        if i>8 then break end
        local receipt=state.infusionRestore({pending=past}).pending
        if receipt then table.insert(result.unconfirmed,receipt) end
    end
    return result
end
function state.infusionPrefs()
    if not state.craft.infusion then state.craft.infusion=state.infusionRestore(nil) end
    return state.craft.infusion
end
function state.infusionSignature(pet)
    local parts={pet.Enchanted==true and "1" or "0"}
    for _,key in ipairs(state.infusionKeys) do parts[#parts+1]=tostring((pet.Enchants or {})[key] or 0) end
    return table.concat(parts,":")
end
function state.infusionTargetsMet(entry,prefs)
    local any=false
    for _,key in ipairs(state.infusionKeys) do
        local goal=prefs.targets[key] or 0
        if goal>0 then any=true;if ((entry.pet.Enchants or {})[key] or 0)<goal then return false end end
    end
    return any
end
function state.infusionUniqueProblem(prefs,catalog)
    local chosen
    for _,key in ipairs(state.infusionKeys) do
        if catalog[key] and catalog[key].Unique and (tonumber(prefs.targets[key]) or 0)>0 then
            if chosen then return "Escolha somente um bônus UNIQUE por sombra." end
            chosen=key
        end
    end
end
function state.infusionSetTarget(prefs,key,level,catalog)
    local info=catalog[key]
    if not info or not info.Level then return false end
    level=math.clamp(math.floor(tonumber(level) or 0),0,tonumber(info.Level.Max) or 0)
    if info.Unique and level>0 then
        for _,other in ipairs(state.infusionKeys) do
            if other~=key and catalog[other] and catalog[other].Unique then
                prefs.targets[other]=0
                if prefs.locks then prefs.locks[other]=nil end
                for uid in pairs(prefs.selected or {}) do
                    if prefs.locksByUid and prefs.locksByUid[uid] then prefs.locksByUid[uid][other]=nil end
                end
            end
        end
    end
    prefs.targets[key]=level
    return true
end
function state.infusionPlan(entry,prefs,catalog,balance)
    local uniqueProblem=state.infusionUniqueProblem(prefs,catalog)
    if uniqueProblem then return nil,uniqueProblem end
    if not entry then return nil,"Escolha uma sombra para infundir." end
    if entry.pet.InExp then return nil,"Esta sombra está em expedição." end
    local levels=entry.pet.Enchants or {}
    local manual=prefs.locksByUid and prefs.locksByUid[entry.uid] or (not prefs.uid or prefs.uid==entry.uid) and prefs.locks or {}
    local locks,targets={},{}
    local total,reached,locked=0,0,0
    local unique
    for _,key in ipairs(state.infusionKeys) do
        local info=catalog[key]
        if not info or not info.Level then return nil,"Dados de infusão indisponíveis." end
        local max=tonumber(info.Level.Max)
        if not max or max<1 then return nil,"Dados de infusão indisponíveis." end
        local goal=math.clamp(tonumber(prefs.targets[key]) or 0,0,max)
        local current=tonumber(levels[key]) or 0
        if goal>0 then total+=1;targets[key]=goal;if current>=goal then reached+=1;locks[key]=true end end
        if manual[key] then
            if current<1 then return nil,state.infusionText("O bônus %s ainda não existe para travar.",info.Name or key) end
            if goal>current then return nil,state.infusionText("Destrave %s para alcançar a meta maior.",info.Name or key) end
            locks[key]=true
        end
        if info.Unique and (goal>0 or locks[key]) then
            if unique then return nil,"Escolha somente um bônus UNIQUE por sombra." end
            unique=key
        end
    end
    if total==0 then return nil,"Ative pelo menos uma meta de infusão." end
    if reached==total then return nil,"Todas as metas de infusão foram atingidas." end
    for _ in pairs(locks) do locked+=1 end
    local base=balance.EnchantShadowPrice and balance.EnchantShadowPrice[entry.info.Rarity]
    if not base or type(base.Item)~="string" then return nil,"Preço de infusão indisponível para esta raridade." end
    for _,key in ipairs({"Amount","Gems","Ticket"}) do
        local n=tonumber(base[key]);if not n or n~=n or n<=0 or n==math.huge then return nil,"Preço de infusão indisponível para esta raridade." end
    end
    local level=tonumber(entry.pet.Level) or 1
    if level~=level or level<1 or level==math.huge then return nil,"Nível da sombra indisponível." end
    return {uid=entry.uid,name=entry.pet.Name,locks=locks,targets=targets,total=total,reached=reached,locked=locked,
        payment=prefs.payment,item=base.Item,items=math.floor(base.Amount*(1+0.25*locked)),
        gemsBase=base.Gems,gemsLevel=level,gemsLocks=math.clamp(3*locked,1,99999),tickets=base.Ticket+10*locked}
end
function state.infusionQueue(entries,prefs,catalog,balance,focus)
    local counts={total=0,complete=0,available=0}
    local selected=prefs.selected
    if type(selected)~="table" then selected=prefs.uid and {[prefs.uid]=true} or {} end
    for _,on in pairs(selected) do if on then counts.total+=1 end end
    local candidate,plan,problem
    for _,entry in ipairs(entries or {}) do
        if selected[entry.uid] and not entry.pet.InExp then
            counts.available+=1
            local p,why=state.infusionPlan(entry,prefs,catalog,balance)
            if entry.uid==focus and not p and why~="Todas as metas de infusão foram atingidas." then return nil,nil,why,counts end
            if p and (not candidate or entry.uid==focus) then candidate,plan=entry,p
            elseif why=="Todas as metas de infusão foram atingidas." then counts.complete+=1
            elseif not p then problem=problem or why end
        end
    end
    if candidate then return candidate,plan,nil,counts end
    if counts.total==0 then problem="Escolha uma sombra para infundir."
    elseif counts.complete==counts.total then problem="Todas as metas de infusão foram atingidas."
    elseif counts.available<counts.total then problem="Aguardando as sombras selecionadas ficarem disponíveis." end
    return nil,nil,problem,counts
end
end
local questRuntime = {combat = false}
-- AUTO QUEST POLICY
local function nextQuest(catalog, completed, island)
    for _, entry in ipairs(catalog) do
        if (not island or entry.map == island) and completed[entry.id] ~= true then return entry end
    end
end
local function questGoal(record, definition)
    local keys = {}
    for id in pairs(definition.Goals or {}) do table.insert(keys, id) end
    table.sort(keys)
    for _, id in ipairs(keys) do
        local goal = definition.Goals[id]
        local progress = record.Progress and record.Progress[id]
        local current = type(progress) == "table" and tonumber(progress.Current) or 0
        local maximum = type(progress) == "table" and tonumber(progress.Max) or nil
        maximum = maximum or goal.Max or 1
        if (current or 0) < maximum then return id, goal, current or 0, maximum end
    end
end
-- QUEST/CASTLE POLICY: native counters and catalogs, no guessed completion.
function state.castleCounter(message)
    if type(message) ~= "string" then return nil end
    message = message:gsub("<[^>]*>", ""):gsub("^%s+", ""):gsub("%s+$", "")
    local kind, left, total = message:lower():match("^(%a+)%s+left%s*:%s*(%d+)%s*/%s*(%d+)%s*$")
    kind, left, total = kind and kind:lower(), tonumber(left), tonumber(total)
    if (kind ~= "enemies" and kind ~= "bosses") or not left or not total or total < 1 or left > total then return nil end
    return left, total
end
function state.castleAdvanceReady(room, message, now)
    if type(room) ~= "number" or room < 1 or room ~= math.floor(room) then return false end
    local progress = state.castleProgress
    if not progress then
        progress = {room = room, message = message, fresh = true}
        state.castleProgress = progress
    elseif progress.room ~= room then
        progress = {room = room, message = message, fresh = message ~= progress.message}
        state.castleProgress = progress
    elseif progress.message ~= message then
        progress.message, progress.fresh, progress.zeroAt = message, true, nil
    end
    local left = state.castleCounter(message)
    if left and left > 0 then progress.fresh, progress.zeroAt = true, nil return false end
    if left ~= 0 or not progress.fresh then progress.zeroAt = nil return false end
    progress.zeroAt = progress.zeroAt or now
    return now - progress.zeroAt >= 0.4
end
-- CASTLE EMPTY-ROOM RECOVERY: require a stable empty client, a loaded room,
-- an enabled current-room portal and a completed streaming request.
function state.castleRecoveryReady(room, root, now, hasEnemy, portalReady, streamed)
    if type(room) ~= "number" or room < 1 or room % 1 ~= 0 or not root or hasEnemy or not portalReady then
        state.castleRecovery = nil
        return false
    end
    local recovery = state.castleRecovery
    if not recovery or recovery.room ~= room or recovery.root ~= root then
        recovery = {room = room, root = root, emptyAt = now}
        state.castleRecovery = recovery
    end
    if not streamed then recovery.streamedAt = nil return false end
    recovery.streamedAt = recovery.streamedAt or now
    return now - recovery.emptyAt >= 8 and now - recovery.streamedAt >= 2
end
-- END CASTLE EMPTY-ROOM RECOVERY
function state.questWorldRune(map, catalog, stock)
    local candidates = {}
    for id, info in pairs(catalog) do
        local rule = type(info) == "table" and info.Dungeon
        if type(info) == "table" and info.Type == "DungeonItem" and type(rule) == "table" and rule.Type == "WorldRune" and rule.World == map then
            table.insert(candidates, id)
        end
    end
    table.sort(candidates)
    for _, id in ipairs(candidates) do if (stock(id) or 0) > 0 then return id end end
end
function state.questWeaponShop(map, maps, shops)
    local weapons = maps[map] and maps[map].Weapons and maps[map].Weapons.Normal
    if type(weapons) ~= "table" or #weapons == 0 then return nil end
    for shop, info in pairs(shops) do
        if shop:match("^WeaponShop") then
            local matches = 0
            for _, id in ipairs(weapons) do if info.Items and info.Items[id] then matches += 1 end end
            if matches == #weapons then return shop, weapons end
        end
    end
end
-- END QUEST/CASTLE POLICY

-- WORLD QUEST POLICY
state.worldQuestPolicy = {}
function state.worldQuestPolicy.goal(goal, maps)
    if type(goal) ~= "string" then return nil end
    local rank = tonumber(goal:match("^Rank(%d+)$"))
    if rank then return {mode = "ranktest", rank = rank} end
    local map = goal:match("^(.-)Completed$")
    if map and maps[map] then return {mode = "portal", map = map, world = maps[map].World} end
end
function state.worldQuestPolicy.candidates(definitions, records, completed, maps)
    local jobs, claims = {}, {}
    for id, record in pairs(records) do
        local name = type(record) == "table" and (record.Name or id)
        local definition = name and definitions[name]
        if definition and definition.IsSub == true and definition.NeedClaim == true and not definition.DontShow
            and completed[id] ~= true and completed[name] ~= true
            and (not definition.NeedQuest or completed[definition.NeedQuest] == true) then
            if record.Completed == true then table.insert(claims, tostring(id))
            else
                local goal = questGoal(record, definition)
                local job = state.worldQuestPolicy.goal(goal, maps)
                if job then
                    job.id, job.definitionId, job.goal = tostring(id), name, goal
                    job.name, job.release = definition.Name, definition.Release
                    table.insert(jobs, job)
                end
            end
        end
    end
    table.sort(jobs, function(a, b)
        if a.mode ~= b.mode then return a.mode == "ranktest" end
        if a.rank and b.rank and a.rank ~= b.rank then return a.rank < b.rank end
        return a.id < b.id
    end)
    table.sort(claims)
    return jobs, claims
end
function state.worldQuestPolicy.portalMatches(job, info, world)
    return job and job.mode == "portal" and type(info) == "table" and info.ID ~= nil
        and tostring(info.World) == "World" .. tostring(world)
        and ((info.Dungeon == job.map and job.world == world) or type(job.rune) == "string")
end
-- END WORLD QUEST POLICY

local function questEnemyMatches(filter, id, map, info)
    if not filter or not info then return false end
    if tostring(map) ~= tostring(filter.order) and map ~= filter.map then return false end
    if filter.kind == "boss" then return info.TypeG == "BossesDefeated" or info.TypeC == "Boss" end
    if filter.kind == "brute" then return info.TypeG == "BrutesDefeated" end
    if filter.kind == "enemy" then return id == filter.enemy end
    if filter.kind == "arise" then return info.Arise ~= nil end
    return filter.kind == "normal" and info.TypeC == "Normal"
end
-- END AUTO QUEST POLICY
-- Recurring objectives are read from active Progress.Max, never rolled from template ranges.
do
local api={buckets={Daily=true,Weekly=true,PassDaily=true,PassWeekly=true}}
state.recurringQuestPolicy=api
local actions={
    PlayTime={kind="passive",activity="time"},
    EnemiesDefeated={kind="farm",activity="enemies",filter="normal"},
    BrutesDefeated={kind="farm",activity="brutes",filter="brute"},
    ShadowsArised={kind="farm",activity="arise",filter="arise"},
    BossesDefeated={kind="farm",activity="bosses",filter="boss"},
    DungeonClear={kind="mode",activity="portal",mode="portal"},
    FloorCompleted={kind="mode",activity="infernal",mode="infernal",partial=true},
    HeavenFloorCompleted={kind="mode",activity="heavenly",mode="heavenly",partial=true},
    CompletedWave={kind="mode",activity="desert",mode="desert",partial=true},
    TimeTrialRoom={kind="mode",activity="trial",mode="trial",partial=true},
    BossRushKill={kind="mode",activity="bossrush",mode="bossrush",partial=true},
    EclipseCourtClear={kind="mode",activity="eclipse",mode="eclipse"},
    KeyRaidClear={kind="mode",activity="key",mode="key"},
    WBDefeated={kind="event",activity="boss"},
    ExpeditionClaimed={kind="manual",activity="expedition"},
}
for _,id in ipairs({"JJ1","JJ2","JJ3","JJ4"}) do actions[id.."Defeated"]={kind="event",activity="dedu"} end
for _,id in ipairs({"WElf1","WElf2","WBear","WIron","WBoss","WBoss2"}) do actions[id.."Defeated"]={kind="event",activity="winter"} end
for _,id in ipairs({"WareWolf","HomemLobo","Keran"}) do actions[id.."Defeated"]={kind="event",activity="jungle"} end
for _,id in ipairs({"Giant","GiantArmor","Legia","Querah"}) do actions[id.."Defeated"]={kind="event",activity="giants"} end
function api.action(goal) return actions[goal] end
function api.stage(group)
    if group.kind=="farm" then return 1 end
    if group.kind=="mode" and (group.mode=="portal" or group.mode=="key") then return 2 end
    if group.kind=="event" then return 3 end
    if group.kind=="mode" then return 4 end
    return 5
end
function api.matches(job,read)
    local map=read("DungeonMap")
    if job.mode=="heavenly" then return read("IsHeavenCastle")==true end
    if job.mode=="infernal" then return read("IsCastle")==true and read("IsHeavenCastle")~=true end
    if job.mode=="trial" then return read("InTimeTrial")==true end
    if job.mode=="bossrush" then return read("InBossRush")==true or read("InRush")==true end
    if job.mode=="desert" then return read("InInfiniteMode")==true or read("InInfinite")==true and read("InInfiniteC")~=true and read("InInfiniteL")~=true end
    if job.mode=="eclipse" then return map=="EclipseCourtRaid" end
    if job.mode=="portal" then return map=="DarkDungeon" end
    if job.mode=="key" then return type(job.expectedMap)=="string" and map==job.expectedMap end
    return false
end
function api.enabled(settings)
    if state.questProfiles then return settings.enabled==true and state.questProfiles.recurring(settings) end
    return settings.enabled==true and (settings.scope=="all" or settings.scope=="recurring")
end
local function finite(v)
    local n=tonumber(v)
    return n and n==n and n>=0 and n<math.huge and n or nil
end
function api.scan(definitions,read,settings)
    local groups,claims,blocked={},{},{}
    for _,bucket in ipairs({"Daily","Weekly","PassDaily","PassWeekly"}) do
        if settings and state.questProfiles and not state.questProfiles.bucket(settings,bucket) then continue end
        local records=read("Quests",bucket)
        if type(records)~="table" then blocked[#blocked+1]={bucket=bucket,reason="loading"};continue end
        for id,record in pairs(records) do
            if type(record)~="table" then continue end
            local name=record.Name or id
            if settings and settings.splitQuests and state.limitBreaker and not state.limitBreaker.selected(settings,bucket,name) then continue end
            local definition=definitions[bucket] and definitions[bucket][name]
            if not definition or definition.DontShow then continue end
            if record.Completed==true then
                if definition.NeedClaim==true then claims[#claims+1]={bucket=bucket,id=tostring(id),name=definition.Name or name} end
                continue
            end
            if type(record.Progress)~="table" then blocked[#blocked+1]={bucket=bucket,id=tostring(id),reason="progress"};continue end
            for goal,progress in pairs(record.Progress) do
                if type(progress)~="table" then continue end
                local current,maximum=finite(progress.Current or 0),finite(progress.Max)
                if not current or not maximum or maximum<=0 then blocked[#blocked+1]={bucket=bucket,id=tostring(id),goal=goal,reason="progress"};continue end
                if current>=maximum then continue end
                local action=definition.Goals and definition.Goals[goal] and actions[goal]
                if not action then blocked[#blocked+1]={bucket=bucket,id=tostring(id),goal=goal,reason="unsupported"};continue end
                local group=groups[action.activity]
                if not group then
                    group={kind=action.kind,activity=action.activity,mode=action.mode,filter=action.filter,partial=action.partial,refs={}}
                    groups[action.activity]=group
                end
                group.refs[#group.refs+1]={bucket=bucket,id=tostring(id),definitionId=name,goal=goal,current=current,maximum=maximum,
                    name=definition.Name or name,rank=definition.NeedRank,release=definition.Release}
            end
        end
    end
    local list={}
    for _,group in pairs(groups) do
        table.sort(group.refs,function(a,b)
            if settings and settings.splitQuests and state.limitBreaker then
                local x,y=state.limitBreaker.priority(settings,a),state.limitBreaker.priority(settings,b)
                if x~=y then return x<y end
            end
            return a.bucket..":"..a.id..":"..a.goal<b.bucket..":"..b.id..":"..b.goal
        end)
        list[#list+1]=group
    end
    table.sort(list,function(a,b)
        if settings and settings.splitQuests and state.limitBreaker then
            local x,y=math.huge,math.huge
            for _,ref in ipairs(a.refs) do x=math.min(x,state.limitBreaker.priority(settings,ref)) end
            for _,ref in ipairs(b.refs) do y=math.min(y,state.limitBreaker.priority(settings,ref)) end
            if x~=y then return x<y end
        end
        local x,y=api.stage(a),api.stage(b)
        if x~=y then return x<y end
        if #a.refs~=#b.refs then return #a.refs>#b.refs end
        return a.activity<b.activity
    end)
    table.sort(claims,function(a,b) return a.bucket..":"..a.id<b.bucket..":"..b.id end)
    return list,claims,blocked
end
function api.validJourney(job)
    if type(job)=="table" and job.bucket=="TicketFarm" then
        return job.id=="tickets" and job.definitionId=="TicketFarm" and job.goal=="TicketFull" and job.mode=="trial" and (job.phase=="entry" or job.phase=="inside")
    end
    if type(job)~="table" or not api.buckets[job.bucket] or type(job.id)~="string" or type(job.definitionId)~="string"
        or (job.phase~="entry" and job.phase~="inside") then return false end
    local action=actions[job.goal]
    return action~=nil and action.kind=="mode" and action.mode==job.mode
end
end
-- Saved per-definition priorities; active quest progress remains authoritative.
do
local api={}
state.limitBreaker=api
-- Same goal precedence and asset IDs as the native NewUI Quests/Common modules.
function api.icon(definition)
    local goals={};for goal in pairs(definition.Goals or {}) do goals[#goals+1]=goal end;table.sort(goals)
    local first=goals[1] or ""
    local rules={{"^PlayTime","137504361633657"},{"^Brutes","95254773789707"},{"^ShadowsArised","104278863001328"},{"^Dungeon","105767317646901"},{"Castle","106302265444532"},{"Floor","106302265444532"},{"Wave","106302265444532"},{"^LevelReached","126007391909587"},{"^Rank","77124394846585"},{"^Awaken","77124394846585"},{"^WB","98234924459437"},{"Defeated","87217064840638"}}
    for _,rule in ipairs(rules) do if string.find(first,rule[1]) then return "rbxassetid://"..rule[2] end end
    return "rbxassetid://124774896626261"
end
function api.objective(definition,language)
    local labels={
        PlayTime={"Permanecer online","Remain online","Permanecer conectado"},
        EnemiesDefeated={"Derrotar inimigos","Defeat enemies","Derrotar enemigos"},
        BrutesDefeated={"Derrotar brutos","Defeat brutes","Derrotar brutos"},
        ShadowsArised={"Extrair sombras","Arise shadows","Extraer sombras"},
        DungeonClear={"Concluir dungeons","Complete dungeons","Completar dungeons"},
        FloorCompleted={"Pisos do Castelo Infernal","Infernal Castle floors","Pisos del Castillo Infernal"},
        HeavenFloorCompleted={"Pisos do Castelo Celestial","Heavenly Castle floors","Pisos del Castillo Celestial"},
        CompletedWave={"Ondas do Deserto Infinito","Infinite Desert waves","Oleadas del Desierto Infinito"},
        EclipseCourtClear={"Eclipse Court","Eclipse Court","Eclipse Court"},
        KeyRaidClear={"Dungeons de chave","Key dungeons","Dungeons de llave"},
        TimeTrialRoom={"Salas da Trial","Trial rooms","Salas de Trial"}}
    local goals={};for goal in pairs(definition.Goals or {}) do goals[#goals+1]=goal end;table.sort(goals)
    for _,goal in ipairs(goals) do
        local label=labels[goal]
        if label then return label[language=="PT" and 1 or language=="ES" and 3 or 2] end
        local action=state.recurringQuestPolicy and state.recurringQuestPolicy.action(goal)
        if action and action.kind=="event" then
            local raids={winter="Winter Raid",dedu="Dedu Raid",jungle="Jungle Raid",giants="Giants Raid",boss="World Boss"}
            if raids[action.activity] then return raids[action.activity] end
        end
    end
    return definition.Desc or (language=="PT" and "Objetivo da missão" or language=="ES" and "Objetivo de la misión" or "Quest objective")
end
function api.enabled(q) return q.splitQuests==true and q.limitBreakerEnabled==true end
function api.selected(q,bucket,id)
    local settings=q.missionSelection
    return not settings or not settings[bucket] or settings[bucket][id]~=false
end
function api.rank(q,bucket,id)
    local order=q.missionOrder and q.missionOrder[bucket]
    for index,value in ipairs(order or {}) do if value==id then return index end end
    return 10000
end
function api.priority(q,ref)
    local rank=api.rank(q,ref.bucket,ref.definitionId)
    local strategy=q.missionStrategy or "interleave"
    if strategy=="daily" then return (ref.bucket=="Daily" and 0 or 20000)+rank end
    if strategy=="weekly" then return (ref.bucket=="Weekly" and 0 or 20000)+rank end
    return rank*2+(ref.bucket=="Weekly" and 1 or 0)
end
function api.restore(q,saved)
    if saved.splitQuests~=true then return end
    q.splitQuests=true;q.progressionEnabled=saved.progressionEnabled==true;q.limitBreakerEnabled=saved.limitBreakerEnabled==true
    q.missionStrategy=saved.missionStrategy=="daily" and "daily" or saved.missionStrategy=="weekly" and "weekly" or "interleave"
    q.missionSelection={};q.missionOrder={}
    for _,bucket in ipairs({"Daily","Weekly"}) do
        q.missionSelection[bucket]={};q.missionOrder[bucket]={}
        for id,value in pairs(type(saved.missionSelection)=="table" and type(saved.missionSelection[bucket])=="table" and saved.missionSelection[bucket] or {}) do
            if type(id)=="string" and type(value)=="boolean" then q.missionSelection[bucket][id]=value end
        end
        local seen={}
        for _,id in ipairs(type(saved.missionOrder)=="table" and type(saved.missionOrder[bucket])=="table" and saved.missionOrder[bucket] or {}) do
            if type(id)=="string" and not seen[id] and #q.missionOrder[bucket]<150 then seen[id]=true;table.insert(q.missionOrder[bucket],id) end
        end
    end
    if type(saved.resetSelectedSeen)=="table" then q.resetSelectedSeen={Daily=saved.resetSelectedSeen.Daily==true,Weekly=saved.resetSelectedSeen.Weekly==true} end
end
end
-- Quest objectives: preserve legacy scopes while routing new profiles through explicit groups.
do
local api={}
state.questProfiles=api
function api.profile(q)
    if q.splitQuests then return q.limitBreakerEnabled and "limitbreaker" or "progression" end
    if q.profile=="progression" or q.profile=="limitbreaker" or q.profile=="custom" then return q.profile end
    return q.scope=="islands" and "progression" or "custom"
end
function api.progression(q)
    if q.progression=="islands" or q.progression=="world" or q.progression=="both" then return q.progression end
    return q.scope=="all" and "both" or "islands"
end
function api.groups(q)
    local profile=api.profile(q)
    if profile=="progression" then
        local which=api.progression(q)
        return {islands=which~="world",world=which~="islands",daily=false,weekly=false,pass=false}
    elseif profile=="limitbreaker" then
        return {islands=false,world=false,daily=q.resetScope~="weekly",weekly=q.resetScope~="daily",pass=false}
    end
    if type(q.questGroups)=="table" then
        local groups={}
        for _,key in ipairs({"islands","world","daily","weekly","pass"}) do groups[key]=q.questGroups[key]==true end
        return groups
    end
    return {islands=q.scope=="all",world=q.scope=="all",daily=true,weekly=true,pass=true}
end
function api.bucket(q,bucket)
    local groups=api.groups(q)
    return bucket=="Daily" and groups.daily or bucket=="Weekly" and groups.weekly or (bucket=="PassDaily" or bucket=="PassWeekly") and groups.pass or false
end
function api.recurring(q) if q.splitQuests then return q.limitBreakerEnabled==true end;local g=api.groups(q);return g.daily or g.weekly or g.pass end
function api.resetAllowed(q)
    if q.splitQuests then return q.limitBreakerEnabled==true end
    local g=api.groups(q);return api.profile(q)~="progression" and (g.daily or g.weekly)
end
function api.refill(q) return api.resetAllowed(q) and q.refillTickets~=false end
function api.owns(q,job)
    if not job then return true end
    if job.bucket=="TicketFarm" then return api.refill(q) end
    if job.bucket then return api.bucket(q,job.bucket) and (not q.splitQuests or state.limitBreaker.selected(q,job.bucket,job.definitionId)) end
    return api.groups(q).world
end
function api.restore(q,saved)
    state.limitBreaker.restore(q,saved)
    q.fixedIslandEnabled=saved.fixedIslandEnabled==true
    if type(saved.fixedIsland)=="string" and #saved.fixedIsland>0 and #saved.fixedIsland<=150 then q.fixedIsland=saved.fixedIsland end
    if saved.profile=="progression" or saved.profile=="limitbreaker" or saved.profile=="custom" then q.profile=saved.profile end
    if saved.progression=="islands" or saved.progression=="world" or saved.progression=="both" then q.progression=saved.progression end
    if type(saved.questGroups)=="table" then
        local result,any={},false
        for _,key in ipairs({"islands","world","daily","weekly","pass"}) do result[key]=saved.questGroups[key]==true;any=any or result[key] end
        if any then q.questGroups=result end
    end
    if type(saved.refillTickets)=="boolean" then q.refillTickets=saved.refillTickets end
    if type(saved.refillConfig)=="table" then
        q.refillConfig={}
        for _,key in ipairs({"difficulty","farmTeam","returnTeam"}) do local v=saved.refillConfig[key];if type(v)=="string" and #v>0 and #v<=150 then q.refillConfig[key]=v end end
    end
    local teamPending=saved.refillTeamPending
    if type(teamPending)=="table" and type(teamPending.id)=="string" and #teamPending.id<=150 and (teamPending.phase=="farm" or teamPending.phase=="return") then
        local at,attempts=tonumber(teamPending.at),tonumber(teamPending.attempts)
        if not at or at~=at or at<0 or at==math.huge then at=0 end
        if not attempts or attempts~=attempts or attempts<0 or attempts==math.huge then attempts=0 end
        q.refillTeamPending={id=teamPending.id,phase=teamPending.phase,at=at,attempts=math.clamp(attempts,0,3)}
    end
end
function api.syncScope(q)
    if q.splitQuests then q.enabled=q.progressionEnabled or q.limitBreakerEnabled;q.profile=q.limitBreakerEnabled and "limitbreaker" or "progression" end
    local g=api.groups(q)
    q.scope=g.world and "all" or (g.daily or g.weekly or g.pass) and "recurring" or "islands"
end
end
local sellRanks = {}
-- NATIVE SELL RANKS: discover until the native catalog ends, without a fixed rank cap.
do
    function state.nativeSellRankList(getter)
        local result, names, rank = {}, {}, 1
        while true do
            local valid, name, color = pcall(getter, rank)
            if not valid or type(name) ~= "string" or name == "" or names[name] then break end
            names[name] = true
            table.insert(result, {id = rank, name = name, color = color})
            rank += 1
        end
        return result
    end
    function state.refreshSellRanks()
        local extra = require(shared.ExtraFunctions)
        for _, rank in ipairs(state.nativeSellRankList(extra.GetRankInfo)) do
            local previous = sellRanks[rank.id]
            if previous then previous.name, previous.color = rank.name, rank.color
            else table.insert(sellRanks, rank) end
        end
    end
    state.refreshSellRanks()
end
-- END NATIVE SELL RANKS
-- AUTO SELL POLICY
function state.sellableShadow(id,shadow,equipped,selected)
    return type(shadow)=="table" and type(shadow.Rank)=="number" and selected[tostring(shadow.Rank)]==true
        and not equipped[id] and not shadow.Locked and not shadow.InExp
        and not (state.craftReserved and state.craftReserved(id))
end
local function sellableShadows(inventory, equipped, selected, bulk)
    -- Native NewUI.Common.FireList measures each UID as #tostring(id) + 4.
    -- Keep one native-sized chunk in flight so Stop and protection changes are immediate.
    local ids, bytes = {}, 0
    for id, shadow in pairs(inventory) do
        if state.sellableShadow(id,shadow,equipped,selected) then
            local cost = #tostring(id) + 4
            if #ids > 0 and bytes + cost > 6000 then break end
            table.insert(ids, id)
            bytes += cost
            if not bulk and #ids == 30 then break end
        end
    end
    return ids
end
-- END AUTO SELL POLICY
-- GUILD AND SWORDS POLICY
do
    function state.guildBossKey(boss, guildId)
        if type(boss) ~= "table" or type(guildId) ~= "string" or guildId == ""
            or type(boss.BossId) ~= "string" then return nil end
        local endsAt = tonumber(boss.EndsAt)
        if not endsAt or endsAt ~= endsAt or endsAt <= 0 or endsAt == math.huge then return nil end
        return guildId .. ":" .. boss.BossId .. ":" .. tostring(math.floor(endsAt))
    end
    function state.guildShareNotice(message)
        if type(message) ~= "string" then return false end
        local text = message:gsub("<[^>]+>", ""):gsub("%s+", " "):lower()
        return text:find("already dealt 25%", 1, true) ~= nil and text:find("boss", 1, true) ~= nil
            and text:find("guildmates", 1, true) ~= nil
    end
    function state.guildDecision(config, context, definitions)
        if not config.enabled then return nil, "off" end
        if context.inside then return nil, "dungeon" end
        if not context.open then return nil, "release" end
        if not context.inGuild then return nil, "no_guild" end
        if not context.synced then return nil, "sync" end
        if context.boss then return "join", context.boss.BossId end
        if not context.canStart then return nil, "permission" end
        if context.now < context.nextAt then return nil, "cooldown" end
        local selected = config.bossId
        if selected == "Auto" then
            selected = nil
            for _, id in ipairs(definitions.Order or {}) do
                if context.level >= (tonumber(definitions[id].Level) or math.huge) then selected = id end
            end
        end
        local info = selected and definitions[selected]
        if not info or context.level < (tonumber(info.Level) or math.huge) then return nil, "level" end
        return "summon", selected
    end
    function state.guildClaimable(list)
        local result = {}
        for _, record in pairs(type(list) == "table" and list or {}) do
            if type(record) == "table" and type(record.Id) == "string" and record.Helped == true
                and record.Claimed ~= true and (record.Done == true
                    or (tonumber(record.Progress) or 0) >= (tonumber(record.Target) or math.huge)) then
                table.insert(result, record.Id)
            end
        end
        table.sort(result)
        return result
    end
    function state.sellableSwords(inventory, equips, selected, definitions, stacks, includeStacks, excluded)
        local ids = {}
        for id, weapon in pairs(type(inventory) == "table" and inventory or {}) do
            if type(weapon) ~= "table" then continue end
            local rank = tonumber(weapon.Level or 1)
            local info = definitions[weapon.Name]
            local gems = weapon.Gems
            local hasGems = gems ~= nil and gems ~= false and (type(gems) ~= "table" or next(gems) ~= nil)
            if rank and rank == math.floor(rank) and rank >= 1 and selected[tostring(rank)] == true
                and type(info) == "table" and info.CanSell == true
                and not equips[id] and weapon.Locked ~= true and (weapon.Art == nil or weapon.Art == false)
                and weapon.Enchanted ~= true and not hasGems and not excluded[id]
                and (includeStacks or not stacks[id]) then table.insert(ids, id) end
        end
        table.sort(ids, function(a, b) return tostring(a) < tostring(b) end)
        while #ids > 30 do table.remove(ids) end
        return ids
    end
    function state.swordReceipts(inventory, pending, blocked, now)
        local confirmed, unconfirmed = 0, false
        for id, at in pairs(pending) do
            if inventory[id] == nil then pending[id] = nil confirmed += 1
            elseif now - at >= 30 then pending[id], blocked[id], unconfirmed = nil, now + 60, true end
        end
        return confirmed, unconfirmed
    end
end
-- END GUILD AND SWORDS POLICY
-- MODOS DE DUNGEON: registro. Cada arquivo em src/dungeon/modos/<modo>.lua guarda os dados daquele modo
-- (policy = lista de modos; speed = controle de velocidade; replay = replay nativo) e se registra aqui.
state.modeData = {}
function state.modeList(slot, order)
    local list = {}
    for _, id in ipairs(order) do
        local entry = state.modeData[id][slot]
        assert(entry, "modo sem dados: " .. id .. "/" .. slot)
        list[#list + 1] = entry
    end
    return list
end
-- Ganchos de logica por modo (opcionais). Os arquivos em src/dungeon/modos-logica/ registram aqui:
--   state.modeHooks[id].entryStep(mode, inside) -> true encerra a volta atual do controlador de entrada
--   state.modeHooks[id].entryReset()            -> zera o estado do modo quando a partida muda de contexto
state.modeHooks = {}
function state.modeEntryReset()
    for _, hooks in pairs(state.modeHooks) do
        if hooks.entryReset then hooks.entryReset() end
    end
end
