local dungeonModes = state.modeList("policy", {"portal", "key", "infernal", "heavenly", "infcastle", "desert", "labyrinth", "bossrush", "trial", "ranktest", "hospital", "trickortreat", "manor", "architect", "dragon", "eclipse", "rift"})
local dungeon = {utilities = {collapsed=true, highestHP=false, switchTeams=false, keyA="One", keyB="Three", secondsA=10, secondsB=5},runes = {enabled = false, reuseLast = false, slots = {}, last = {}}, raidKeys = {}, autoKeys = false, enabled = false, autoLeave = false, mode = "infernal", difficulty = "Easy", checkpoint = 0, key = ""}
local function dungeonPlan(mode, config, context)
    if context.inside then return nil, "Partida em andamento. Auto Dungeon permanece ligado." end
    if not context.open then return nil, "Aguardando a abertura do modo..." end
    if mode.kind == "castle" then
        return {Event = mode.event, Action = "Join", Castle = mode.castle, Check = config.checkpoint > 0, Floor = config.checkpoint > 0 and tostring(config.checkpoint) or nil}, "Entrando no castelo..."
    end
    if mode.kind == "test" or mode.kind == "hospital" then
        return {Event = mode.event, Action = mode.kind == "test" and "TestEnter" or "Join"}, "Solicitando entrada..."
    end
    local room = context.room
    if mode.keys and not table.find(mode.keys, config.key) then return nil, "Escolha a chave ou dificuldade deste modo." end
    if mode.keys and room and room.DungeonKey ~= config.key then return nil, "O grupo está com outra chave. Saia dele antes de trocar o modo." end
    if mode.kind=="key" and not mode.key and room and room.DungeonKey~=config.key then return nil,"O grupo está com outra chave; não iniciarei a dungeon errada." end
    if mode.key and room and room.DungeonKey ~= mode.key then return nil, "O grupo está com outro passe. Saia dele antes de iniciar este modo." end
    if not room then
        if mode.kind == "key" and not mode.key and config.key == "" then return nil, "Selecione uma chave para entrar." end
        return {Event = mode.event, Action = mode.kind == "key" and "SelectKey" or "Create", Key = mode.kind == "key" and (mode.key or config.key) or nil}, "Criando grupo..."
    end
    if room.Leader ~= context.userId then return nil, "Aguardando o lider iniciar o grupo." end
    if room.Locked then return nil, "Grupo iniciando. Aguardando teleporte..." end
    return {Event = mode.event, Action = "Start", Dungeon = room.Leader, Diff = mode.kind == "difficulty" and config.difficulty or nil, Check = mode.kind == "wave" and config.checkpoint > 0 and tostring(config.checkpoint) or nil}, "Iniciando a partida..."
end
local function castleCheckpoints(best)
    local options = {{id = 0, name = "Inicio  /  Andar 1"}}
    best = tonumber(best)
    if not best or best ~= best then return options end
    for floor = 10, math.min(math.floor(best), 1000) do
        if floor % 10 == 0 or floor % 25 == 0 then
            table.insert(options, {id = floor, name = "Andar " .. floor .. (floor % 25 == 0 and "  /  Boss" or "  /  Checkpoint")})
        end
    end
    return options
end
-- END DUNGEON POLICY
do
    local api={}
    state.rift=api
    dungeon.rift={level=1,maxLevel=false,autoNext=false,autoIslands=false,target=50,islands={}}
    function api.restore(value)
        value=type(value)=="table" and value or {}
        local level=tonumber(value.level)
        local target=tonumber(value.target)
        local result={level=level and level==level and math.clamp(math.floor(level),1,50) or 1,
            maxLevel=value.maxLevel==true,autoNext=value.autoNext==true,autoIslands=value.autoIslands==true,
            target=target and target==target and math.clamp(math.floor(target),1,50) or 50,islands={}}
        local count=0
        for key,selected in pairs(type(value.islands)=="table" and value.islands or {}) do
            if type(key)=="string" and #key<=100 and selected==true and count<100 then result.islands[key]=true;count+=1 end
        end
        return result
    end
    -- Matches the native Party.Rooms RiftLevels list, including its eight-choice cap.
    function api.levels(best,maximum)
        best=tonumber(best)
        if not best or best~=best or best<0 or best>50 then return nil end
        best=math.floor(best)
        maximum=tonumber(maximum)
        if not maximum or maximum~=maximum or maximum<1 or maximum>50 then return nil end
        maximum=math.floor(maximum)
        local out,seen={},{}
        local function add(value)
            if value>=1 and value<=maximum and not seen[value] and #out<8 then seen[value]=true;out[#out+1]=value end
        end
        add(1);add(best)
        for _,delta in ipairs({1,2,3,5,8,10}) do add(best+delta) end
        table.sort(out)
        return out
    end
    function api.select(config,levels)
        if not levels or #levels==0 then return nil end
        if config.autoNext or config.maxLevel then return levels[#levels] end
        for _,level in ipairs(levels) do if level==config.level then return level end end
        return nil
    end
    function api.routePlan(config,catalog)
        local plan={rows={},completed=0,total=0}
        for _,island in ipairs(catalog) do
            if config.islands[island.key] then
                plan.total+=1
                plan.rows[#plan.rows+1]=island
                if island.best>=config.target then plan.completed+=1
                elseif not plan.next then plan.next=island end
            end
        end
        plan.done=plan.total>0 and plan.completed==plan.total
        return plan
    end
    function api.routeLevel(config,choices)
        local chosen
        for _,level in ipairs(choices or {}) do if level<=config.target then chosen=level end end
        return chosen
    end
    function api.inRun()
        -- Player.InIslandRift is also set for lobby membership; never use it here.
        return storage:GetAttribute("InIslandRift")==true
    end
end
-- MISC POLICY: mesmos valores e indicadores usados pela interface nativa.
local miscModes = state.modeList("speed", {"infernal", "heavenly", "desert", "infcastle", "labyrinth"})
function state.activeSpeedMode(read)
    local candidates={}
    if read("IsHeavenCastle")==true then candidates[#candidates+1]=miscModes[2]
    elseif read("IsCastle")==true then candidates[#candidates+1]=miscModes[1] end
    local primary={{"InInfiniteMode",3},{"InInfiniteCastle",4},{"InInfiniteLabyrinth",5}}
    local waves={}
    for _,entry in ipairs(primary) do if read(entry[1])==true then waves[#waves+1]=miscModes[entry[2]] end end
    if #waves==0 then
        for i=3,5 do if read(miscModes[i].flag)==true then waves[#waves+1]=miscModes[i] end end
    end
    for _,mode in ipairs(waves) do candidates[#candidates+1]=mode end
    if #candidates==1 then return candidates[1] end
    return nil,#candidates>1
end
local function miscDecision(config, progress, mode)
    if type(progress) ~= "number" or progress ~= progress or progress < 1 or progress == math.huge then return nil end
    if config.exitEnabled and config.exitAt > 0 and progress >= config.exitAt then return "leave" end
    if not config.speedEnabled then return nil end
    local selected, threshold = nil, -1
    for index = 1, #mode.values do
        local at = config["at" .. index]
        if type(at) == "number" and at > 0 and progress >= at and at >= threshold then selected, threshold = index, at end
    end
    if selected then return "speed", selected end
    return nil
end
-- END MISC POLICY
local function insideDungeon()
    if state.rift and state.rift.inRun() then return true end
    if storage:GetAttribute("ManorDoor") ~= nil then return true end
    for _, flag in ipairs({"InDungeon", "InBossRush", "InInfiniteMode", "InInfiniteCastle", "InInfiniteLabyrinth"}) do
        if storage:GetAttribute(flag) == true then return true end
    end
    if storage:GetAttribute("Dungeon") == true or storage:GetAttribute("InRush") == true or storage:GetAttribute("InTimeTrial") == true or storage:GetAttribute("HLRaid") == true then return true end
    for _, mode in ipairs(miscModes) do if storage:GetAttribute(mode.flag) == true then return true end end
    return false
end
local function farmEnabled()
    if state.panic then return false end
    if state.autoLeaving then return false end
    if state.questPriorityActive and state.questPriorityActive() then
        if state.limitBreakerPortalOwnsRun and state.limitBreakerPortalOwnsRun() then return true end
        if insideDungeon() then return autoQuest.journey~=nil and autoQuest.journey.enterRequested==true and (not autoQuest.journey.bucket or state.recurringRunMatches(autoQuest.journey)) end
        if events.active then return state.questWantsEvent(events.active) end
