function state.restoreDungeonUtilities(value)
    local u=dungeon.utilities
    if type(value)~="table" then return end
    u.collapsed=value.collapsed~=false;u.highestHP=value.highestHP==true;u.switchTeams=value.switchTeams==true
    for _,side in ipairs({"A","B"}) do
        if state.teamSwitchKeys[value["key"..side]] then u["key"..side]=value["key"..side] end
        local n=tonumber(value["seconds"..side])
        if n and n==n and n>=1 and n<=3600 then u["seconds"..side]=math.floor(n*10+0.5)/10 end
    end
    if u.keyA==u.keyB then u.switchTeams=false end
end
local function hpKey(raw)
    local text=tostring(raw):gsub("^%s+",""):gsub("%s+$",""):gsub("^%+","")
    local mantissa,exponent=text:match("^([%d%.]+)[eE]([%+%-]?%d+)$")
    if not mantissa then mantissa,exponent=text,"0" end
    local whole,fraction=mantissa:match("^(%d*)%.(%d*)$")
    if not whole then whole,fraction=mantissa,"" end
    if not whole:match("^%d*$") or not fraction:match("^%d*$") then return nil end
    local digits=whole..fraction;local significant=digits:gsub("^0+","");local e=tonumber(exponent)
    if significant=="" or not e or math.abs(e)>1000000000 then return nil end
    return #whole-(#digits-#significant)-1+e,significant
end
function state.compareEnemyHP(a,b)
    local ae,ad=hpKey(a);local be,bd=hpKey(b)
    if not ae then return be and -1 or 0 end
    if not be then return 1 end
    if ae~=be then return ae>be and 1 or -1 end
    local n=math.max(#ad,#bd);ad=ad..string.rep("0",n-#ad);bd=bd..string.rep("0",n-#bd)
    if ad==bd then return 0 end
    return ad>bd and 1 or -1
end
function state.newTeamSwitchCycle() return {side=nil,remaining=0,last=nil} end
function state.stepTeamSwitch(c,now,enabled,inside,ready,u)
    local previous=c.last;c.last=now
    if not enabled or not inside then c.side=nil;c.remaining=0;c.paused=false;return nil end
    if not ready then c.paused=true;return nil end
    local elapsed=not c.paused and previous and math.max(0,now-previous) or 0;c.paused=false
    if not c.side then c.side="A";c.remaining=u.secondsA;return u.keyA end
    c.remaining=math.max(0,c.remaining-elapsed)
    if c.remaining>0 then return nil end
    c.side=c.side=="A" and "B" or "A";c.remaining=u["seconds"..c.side];return u["key"..c.side]
end
end
