            and type(seq.expires) == "number" and seq.expires > workspace:GetServerTimeNow()
            and seq.expires < workspace:GetServerTimeNow() + 120 then
            dungeon.entrySequence = {mode = seq.mode, world = seq.world, expires = seq.expires}
        end
    end
    if type(saved.ui) == "table" then
        if type(saved.ui.fastClickEnabled)=="boolean" then uiState.fastClickEnabled=saved.ui.fastClickEnabled end
        if saved.ui.fastClickSpeed==2 or saved.ui.fastClickSpeed==4 then uiState.fastClickSpeed=saved.ui.fastClickSpeed end
        if saved.ui.language == "PT" or saved.ui.language == "EN" or saved.ui.language == "ES" then uiState.language = saved.ui.language end
        if type(saved.ui.farmCollapsed)=="table" then
            uiState.farmCollapsed={}
            for _,key in ipairs({"Combat","Progress","Raids","Events","GearTomeSettings","Activity"}) do
                if saved.ui.farmCollapsed[key]==true then uiState.farmCollapsed[key]=true end
            end
        end
        uiState.reconnect, uiState.antiAFK = saved.ui.reconnect == true, saved.ui.antiAFK == true
        uiState.maskName = saved.ui.maskName == true
        local miniSize = tonumber(saved.ui.miniSize)
        if miniSize and miniSize == miniSize and miniSize >= 0 and miniSize <= 60 then
            uiState.miniSize = miniSize == 0 and 0 or math.clamp(math.floor(miniSize), 25, 60)
        end
        local userScale = tonumber(saved.ui.userScale)
        if userScale and userScale == userScale then uiState.userScale = math.clamp(userScale, 0.85, 1.15) end
        for _, field in ipairs({"width", "height"}) do
            local value = tonumber(saved.ui[field])
            if value and value == value then uiState[field] = math.clamp(value, field == "width" and 480 or 360, field == "width" and 1280 or 1250) end
        end
        uiState.hideTotal = saved.ui.hideTotal == true
        uiState.uiSounds, uiState.showFps, uiState.compact = saved.ui.uiSounds == true, saved.ui.showFps == true, saved.ui.compact == true
        for _, field in ipairs({"compactWidth", "compactHeight"}) do
            local value = tonumber(saved.ui[field])
            if value and value == value then uiState[field] = math.clamp(value, field == "compactWidth" and 480 or 600, field == "compactWidth" and 720 or 1250) end
        end
        for _, key in ipairs({"x", "y", "ox", "oy", "miniX", "miniY", "miniOX", "miniOY"}) do
            local number = tonumber(saved.ui[key])
            if number and number == number and math.abs(number) <= 10000 then uiState[key] = number end
        end
        if saved.ui.tab == "Farm" or saved.ui.tab == "Dungeon" or saved.ui.tab == "Auto Sell" or saved.ui.tab == "Auto Claim" or saved.ui.tab == "Auto Buy" or saved.ui.tab == "Misc" then uiState.tab = saved.ui.tab end
        if saved.ui.tab == "Sell / Buy" or saved.ui.tab == "Craft" then uiState.tab = saved.ui.tab end
        if table.find({"Original", "NewHub", "Horizontal", "Compact"}, saved.ui.layout) then uiState.layout = saved.ui.layout == "Original" and "NewHub" or saved.ui.layout end
        uiState.responsiveSizes = {}
        for _, key in ipairs({"desktop", "mobileLandscape", "mobilePortrait"}) do
            local v = type(saved.ui.responsiveSizes) == "table" and saved.ui.responsiveSizes[key]
            if type(v) == "table" and type(v.width) == "number" and type(v.height) == "number"
                and v.width == v.width and v.height == v.height and v.width >= 480 and v.width <= 1280
                and v.height >= 360 and v.height <= 1250 then
                uiState.responsiveSizes[key] = {width = v.width, height = v.height}
            end
        end
        uiState.responsiveVersion = saved.ui.responsiveVersion == 1 and 1 or nil
        if type(saved.ui.portraitSize) == "table" then
            local v = saved.ui.portraitSize
            if type(v.width) == "number" and type(v.height) == "number" and v.width >= 480 and v.width <= 1280
                and v.height >= 360 and v.height <= 1250 then uiState.portraitSize = {width = v.width, height = v.height} end
        end
        uiState.tradeMode = saved.ui.tradeMode == "Buy" and "Buy" or "Sell"
        if uiState.tab == "Auto Sell" or uiState.tab == "Auto Buy" then
            uiState.tradeMode = uiState.tab == "Auto Buy" and "Buy" or "Sell"
            uiState.tab = "Sell / Buy"
        end
        if type(saved.ui.minimizeKey) == "string" then
            local valid, key = pcall(function() return Enum.KeyCode[saved.ui.minimizeKey] end)
            if valid and key and key ~= Enum.KeyCode.Unknown and key ~= Enum.KeyCode.Escape then uiState.minimizeKey = key.Name end
        end
    end
    if type(saved.dungeon) == "table" then
        local value = saved.dungeon
        dungeon.rift=state.rift.restore(value.rift)
        dungeon.enabled = value.enabled == true
        dungeon.repeatGems = value.repeatGems == true or value.repeatTrial == true
        state.restoreDungeonUtilities(value.utilities)
        dungeon.autoLeave = value.autoLeave == true
        dungeon.autoKeys = value.autoKeys == true
        if type(value.runes) == "table" then
            if type(value.runes.restoreLast) == "table" then
                dungeon.runes.restoreLast = {}
                for slot = 1, 9 do
                    local id = value.runes.restoreLast[tostring(slot)]
                    if type(id) == "string" then dungeon.runes.restoreLast[tostring(slot)] = id end
                end
            end
            dungeon.runes.enabled, dungeon.runes.reuseLast = value.runes.enabled == true, false
            dungeon.runes.replayPending, dungeon.runes.lastKnown = value.runes.replayPending == true, value.runes.lastKnown == true
            for _, group in ipairs({"slots", "last"}) do
                for key, item in pairs(type(value.runes[group]) == "table" and value.runes[group] or {}) do
                    local slot = tonumber(key)
                    if slot and slot == math.floor(slot) and slot >= 1 and slot <= 9 and type(item) == "string" and #item <= 160 then
                        dungeon.runes[group][tostring(slot)] = item
                    end
                end
            end
        end
        if type(value.gemResetPending) == "string" then dungeon.gemResetPending = value.gemResetPending end
        if type(value.castleGemResetPending) == "string" then dungeon.castleGemResetPending = value.castleGemResetPending end
        if value.trickChoice == "Trick" then dungeon.trickChoice = "Trick" end
        for _, mode in ipairs(dungeonModes) do if value.mode == mode.id then dungeon.mode = value.mode end end
        if type(value.difficulty) == "string" then dungeon.difficulty = value.difficulty end
        if type(value.key) == "string" then dungeon.key = value.key end
        for _, mode in ipairs(dungeonModes) do
            local key = type(value.raidKeys) == "table" and value.raidKeys[mode.id]
            if mode.keys and table.find(mode.keys, key) then dungeon.raidKeys[mode.id] = key end
        end
        local number = tonumber(value.checkpoint)
        if number and number == number and number >= 0 and number <= 1000000 then dungeon.checkpoint = math.floor(number) end
        if type(value.waveBest) == "table" then
            dungeon.waveBest = {}
            for _, id in ipairs({"desert", "infcastle"}) do
                local best = tonumber(value.waveBest[id])
                if best and best == best and best >= 0 and best <= 1000000 then dungeon.waveBest[id] = math.floor(best) end
            end
        end
    end
    for _, mode in ipairs(miscModes) do
        local value = type(saved.misc) == "table" and saved.misc[mode.id]
        if type(value) == "table" then
            local config = misc[mode.id]
            config.speedEnabled, config.exitEnabled = value.speedEnabled == true, value.exitEnabled == true
            for _, key in ipairs({"at1", "at2", "at3", "at4", "exitAt"}) do
                local number = tonumber(value[key])
                if number and number == number and number >= 0 and number <= 1000000
                    and (key == "exitAt" or saved.speedRulesVersion == 1) then
                    config[key] = math.min(mode.everyone and 1000 or 1000000, math.floor(number))
                end
            end
        end
    end
end
end -- profile loading scope
local function save()
    if state.resetting then return true end
    if type(writefile) ~= "function" then return false, "Executor sem arquivos locais" end
    return pcall(function()
        if type(makefolder) == "function" then pcall(makefolder, "VykronHub") end
        writefile(profilePath, Http:JSONEncode({userId = player.UserId, panic = state.panic, eclipseDodge = state.eclipseDodge, gearTomes = state.gearTomes, enabled = state.enabled, misc = misc, dungeon = dungeon,
            autoExecute = autoExecute, ui = uiState, pumpkinEnabled = pumpkin.enabled, pumpkinKingEnabled = state.pumpkinKing.enabled, trialCards = trialCards, trialSelected = state.trialSelected, speedRulesVersion = 1, rebirth = rebirth, autoSell = state.sellProfile(autoSell), autoQuest = autoQuest,keyAFKOriginal=state.keyAFKOriginal,
            worldBossEnabled = worldBoss.enabled, kamishEnabled = state.kamish.enabled, kamishSuspendUntil = state.kamish.suspendUntil, kamishHandledSpawn = state.kamish.handledSpawn, kamishLastOutcome = state.kamish.lastOutcome, castleAFKOriginal = state.castleAFK.original, stormEnabled = storm.enabled, openRaids = state.openRaidProfile(), giantsMode = state.giantsMode~="auto" and state.giantsMode or nil, raidTravel = state.raidTravel, raidClosures = state.raidClosures, guild = state.guild, autoClaim = autoClaim, codeClaims = state.codeClaims, autoBuy = autoBuy, craft = state.craft,
            houses = {enabled = state.houses.enabled, choice = state.houses.choice, visited = state.houses.visited, cooldownSources = state.houses.cooldownSources, route = state.houses.route}}))
    end)
end
-- AUTO SELL SAVE CHECK: keep UI and runtime consistent with confirmed disk data.
function state.sellSaveMessage()
    local prefix = uiState.language == "PT" and "Auto Sell: falha ao salvar. Tente novamente. "
        or uiState.language == "ES" and "Auto Sell: no se pudo guardar. Intenta de nuevo. "
        or "Auto Sell: could not save. Please retry. "
    return prefix .. tostring(state.sellSaveProblem or "")
end
function state.commitSellPreference(target, key, value)
    if state.resetting or state.stopped then return false, "Hub is restarting or stopped" end
    local previous = target[key]
    target[key] = value
    local expected = state.sellProfile(autoSell)
    local savedOK, problem = save()
    if savedOK then
        savedOK, problem = pcall(function()
            local confirmed = Http:JSONDecode(readfile(profilePath))
            assert(type(confirmed) == "table" and confirmed.userId == player.UserId,
                "Auto Sell profile/account could not be verified")
            assert(state.sellProfilesEqual(expected, confirmed.autoSell),
                "Auto Sell disk preferences differ from the selected options")
        end)
    end
    if not savedOK then
        -- A failed write must not silently enable destructive automatic selling.
        target[key] = previous
        state.sellSaveProblem = tostring(problem)
        local restored, restoreProblem = save()
        if not restored then
            state.sellSaveProblem = state.sellSaveProblem .. " | Restore: " .. tostring(restoreProblem)
        end
        warn("[VykronHub] " .. state.sellSaveMessage())
        return false, state.sellSaveProblem
    end
    state.sellSaveProblem = nil
    return true
end
-- END AUTO SELL SAVE CHECK
local function connect(signal, callback)
    local c = signal:Connect(callback)
    connections[#connections + 1] = c
    return c
end
-- UI INPUT POLICY
local function canInteract(control)
    if not alive then return false end
    local node = control
    while node do
        if node:IsA("GuiObject") and not node.Visible then return false end
        if node:IsA("ScreenGui") then return node.Enabled end
        node = node.Parent
    end
    return false
end
-- END UI INPUT POLICY
state.uiHandlers = setmetatable({}, {__mode = "k"})
local function connectUI(control, callback, signal, group)
    state.uiHandlers[control] = callback
    local connection = (signal or control.Activated):Connect(function(...)
        if canInteract(control) then
            if state.onUiActivated then pcall(state.onUiActivated, control) end
            callback(...)
        end
    end)
    table.insert(group or connections, connection)
    return connection
end
local function enemyFolder()
    local main = workspace:FindFirstChild("__Main")
    local enemies = main and main:FindFirstChild("__Enemies")
    return enemies and enemies:FindFirstChild("Server")
end
local function living(enemy, folder)
    if not enemy or not folder or enemy.Parent ~= folder or not enemy:IsA("BasePart")
        or not enemy:GetAttribute("Id") then return false end
    if enemyState.Dead(enemy) then return false end
    -- Native EnemyLocal.HP falls back to the replicated HP attribute.
    -- A missing Dead attribute/cache entry does not invalidate a positive HP value.
    local hp = enemyState.HP(enemy)
    if hp == nil then return false end
    local number = tonumber(hp)
    if number then return number == number and number > 0 end
    -- O jogo representa vidas muito grandes como strings, alem do limite de double.
    return type(hp) == "string" and hp:match("^%d") ~= nil and hp ~= "0"
end
-- Nightmare Kamish is confirmed only by a live replicated enemy marker.
function state.kamishBoss()
    local folder = enemyFolder()
    if not folder then return nil end
    for _, enemy in ipairs(folder:GetChildren()) do
        if enemy:GetAttribute("Id") == "NightmareKamish" and living(enemy, folder) then return enemy end
    end
    return nil
end
-- Spawn cycles are anchored at :27 and repeat every 30 minutes (:27 / :57).
function state.kamishCycleAt(now)
    return math.floor((now - 27 * 60) / 1800) * 1800 + 27 * 60
end
function state.kamishNextSpawn(serverNow)
    return state.kamishCycleAt(serverNow) + 1800
end
function state.kamishSpawnMinute(spawn)
    return string.format(":%02d", math.floor(spawn / 60) % 60)
end
function state.kamishPrepareMinute(spawn)
    return string.format(":%02d", (math.floor(spawn / 60) - 1) % 60)
end
function state.kamishClock()
    local now = workspace:GetServerTimeNow()
    local seconds = math.max(0, math.ceil(state.kamishNextSpawn(now) - now))
    return string.format("%02d:%02d", math.floor(seconds / 60), seconds % 60)
end
function state.kamishWindow(now)
    local previous = state.kamishCycleAt(now)
    local nextSpawn = previous + 1800
    -- Reserve the arena two minutes before either scheduled spawn.
    if now >= nextSpawn - 120 then return nextSpawn end
    if now < previous + 720 then return previous end
    return nil
end
function state.kamishScheduleDue(config,now,bossPresent)
    if not config.enabled or now < (config.suspendUntil or 0) then return false end
    if bossPresent then return true end
    local spawn=state.kamishWindow(now)
    return spawn~=nil and config.handledSpawn~=spawn
end
function state.kamishDue()
    if state.questPriorityActive and state.questPriorityActive() then return false end
    return state.kamishScheduleDue(state.kamish,workspace:GetServerTimeNow(),state.kamishBoss()~=nil)
end
-- Follow the true replicated Baizen marker; clone HP snapshots are mirrored.
function state.baizenClonePriority(folder, position)
    state.baizenProbe = nil
    if not folder or storage:GetAttribute("Dungeon") ~= true
        or (storage:GetAttribute("RaidTitle") ~= "THE ECLIPSE COURT" and storage:GetAttribute("DungeonMap") ~= "EclipseCourtRaid") then return nil end
    local selected,distance
    for _,enemy in ipairs(folder:GetChildren()) do
        if enemy:GetAttribute("Id")=="EclipseAizenBoss" and living(enemy,folder)
            and enemy:GetAttribute("Shield")~=true then
            local d=(enemy.Position-position).Magnitude
            if not distance or d<distance then selected,distance=enemy,d end
        end
    end
    return selected
end
-- END BAIZEN CLONE PRIORITY
-- Halloween room 9: a living Arlecchino clone takes precedence over boss/HP locks.
do
    local cachedRoom,cachedFrame,cachedSize,cachedAt
    function state.halloweenClonePriority(folder,position)
        if not folder or storage:GetAttribute("Dungeon")~=true
            or (storage:GetAttribute("HalloweenRaidActive")~=true and storage:GetAttribute("DungeonMap")~="HalloweenRaid"
                and storage:GetAttribute("RaidTitle")~="HALLOWEEN RAID")
            or tonumber(storage:GetAttribute("CurrentRoom"))~=9 then return nil end
        local main=workspace:FindFirstChild("__Main")
        local world=main and main:FindFirstChild("__World")
        local map=world and world:FindFirstChild("HalloweenRaid")
        local room=map and map:FindFirstChild("Room_9")
        if not room or not room:IsA("Model") then return nil end
        local now=os.clock()
        if cachedRoom~=room or not cachedAt or now-cachedAt>=0.5 then
            local ok,frame,size=pcall(room.GetBoundingBox,room)
            if not ok then return nil end
            cachedRoom,cachedFrame,cachedSize,cachedAt=room,frame,size,now
        end
        local function eligible(enemy,ignoreProtection)
            if not living(enemy,folder) or enemy:GetAttribute("Type")~="HalloweenRaid"
                or (not ignoreProtection and (enemy:GetAttribute("Shield")==true or enemy:GetAttribute("Invulnerable")==true
                or enemy:GetAttribute("Untargetable")==true)) then return false end
            local explicit=tonumber(enemy:GetAttribute("RoomId") or enemy:GetAttribute("Room"))
            if explicit and explicit~=9 then return false end
            local offset=cachedFrame:PointToObjectSpace(enemy.Position)
            return math.abs(offset.X)<=cachedSize.X/2 and math.abs(offset.Z)<=cachedSize.Z/2
                and math.abs(offset.Y)<=cachedSize.Y/2+6
        end
        local boss,selected,distance
        for _,enemy in ipairs(folder:GetChildren()) do
            local id=enemy:GetAttribute("Id")
            if id=="HLBeru" and eligible(enemy,true) then
                boss=true
            elseif id=="HLBeruC" and eligible(enemy) then
                if enemy==state.target then selected=enemy;distance=-1
                else local d=(enemy.Position-position).Magnitude
                    if not distance or d<distance then selected,distance=enemy,d end
                end
            end
        end
        return boss and selected or nil
    end
end
-- Only select boss adds within the currently replicated Eclipse room.
function state.eclipseKnightPriority(folder, position)
    if not folder or storage:GetAttribute("Dungeon") ~= true
        or (storage:GetAttribute("RaidTitle") ~= "THE ECLIPSE COURT"
            and storage:GetAttribute("DungeonMap") ~= "EclipseCourtRaid") then return nil end
    local roomNumber = tonumber(storage:GetAttribute("CurrentRoom"))
    if not roomNumber then return nil end
    local main = workspace:FindFirstChild("__Main")
    local world = main and main:FindFirstChild("__World")
    local court = world and world:FindFirstChild("EclipseCourtRaid")
    local room = court and court:FindFirstChild("Room_" .. tostring(math.floor(roomNumber)))
    if not room or not room:IsA("Model") then return nil end
    local cache = state.eclipseKnightRoom
    if not cache or cache.room ~= room or cache.number ~= roomNumber or os.clock() - cache.at >= 0.5 then
        local ok, frame, size = pcall(room.GetBoundingBox, room)
        if not ok then return nil end
        cache = {room = room, number = roomNumber, at = os.clock(), frame = frame, size = size}
        state.eclipseKnightRoom = cache
    end
    local function inRoom(enemy)
        local explicit = tonumber(enemy:GetAttribute("RoomId") or enemy:GetAttribute("Room"))
        if explicit and explicit ~= roomNumber then return false end
        local offset = cache.frame:PointToObjectSpace(enemy.Position)
        return math.abs(offset.X) <= cache.size.X / 2
            and math.abs(offset.Z) <= cache.size.Z / 2
            and math.abs(offset.Y) <= cache.size.Y / 2 + 6
    end
    local bossIds = {EclipseSaberBoss=true, EclipseKokushiboBoss=true,
        EclipseMakimaBoss=true, EclipseNatsuBoss=true, EclipseMadaraBoss=true}
    local bossPresent = false
    local selected, distance
    for _, enemy in ipairs(folder:GetChildren()) do
        if living(enemy, folder) and inRoom(enemy) then
            local id = enemy:GetAttribute("Id")
            -- Baizen keeps its dedicated true-marker mechanic, including shield phases.
            if id == "EclipseAizenBoss" then return nil end
            if bossIds[id] then bossPresent = true end
            if id == "EclipseKnight" and enemy:GetAttribute("Shield") ~= true then
                local d = (enemy.Position - position).Magnitude
                if not distance or d < distance then selected, distance = enemy, d end
            end
        end
    end
    return bossPresent and selected or nil
end
-- OPEN WORLD RAID TARGETS: never fall back to ordinary island enemies.
function state.openRaidNearest(folder, position, kind, includeShield)
    local raid=state.openRaids[kind]
    local selected,bestRank,bestDistance
    if not raid or not folder then return nil end
    for _,enemy in ipairs(folder:GetChildren()) do
        if living(enemy,folder) then
            local id=enemy:GetAttribute("Id")
            if raid.finalIds[id] then raid.finalUID=enemy.Name end
            local evidence=(raid.evidenceIds or raid.ids)[id]
            if includeShield and kind=="giants" and state.giantsMode=="legia" and state.giantsInvaderIds[id] then evidence=3 end
            local rank=includeShield and evidence or state.openRaidCandidate(raid,id,enemy:GetAttribute("Shield"))
            if rank then
                local distance=(enemy.Position-position).Magnitude
                if not selected or rank<bestRank or (rank==bestRank and distance<bestDistance) then
                    selected,bestRank,bestDistance=enemy,rank,distance
                end
            end
        end
    end
    return selected
end
function state.openRaidFinalDeath(packet)
    local kind=events.active
    local raid=state.openRaids[kind]
    if not raid then return false end
    local folder=enemyFolder()
    if packet and packet.Event~="EnemyDeath" then return false end
    if packet and raid.finalUID and tostring(packet.Enemy)==raid.finalUID then
        state.closeOpenRaid(kind,workspace:GetServerTimeNow());save();return true
    end
    for _,enemy in ipairs(folder and folder:GetChildren() or {}) do
        if raid.finalIds[enemy:GetAttribute("Id")] then
            local nativeDeath=packet and tostring(packet.Enemy)==enemy.Name
            local hp=enemyState.HP(enemy)
            local dead=enemyState.Dead(enemy) or (hp~=nil and tonumber(hp)==0)
            if nativeDeath or dead then
                state.closeOpenRaid(kind,workspace:GetServerTimeNow())
                save()
                return true
            end
        end
    end
    return false
end
-- END OPEN WORLD RAID TARGETS
local function nearest(folder, position, map, quest)
    if state.openRaids[events.active] then return state.openRaidNearest(folder,position,events.active) end
    local selected, distance, selectedHP
    local highest=dungeon.utilities.highestHP and insideDungeon()
    local currentRoom=highest and tonumber(storage:GetAttribute("CurrentRoom"))
    if not folder then return nil end
    for _, enemy in ipairs(folder:GetChildren()) do
        if living(enemy, folder) and (not state.architectEnemyAllowed or state.architectEnemyAllowed(enemy)) and not (enemy:GetAttribute("Id") == "EclipseAizenClone" and (storage:GetAttribute("RaidTitle") == "THE ECLIPSE COURT" or storage:GetAttribute("DungeonMap") == "EclipseCourtRaid"))
            and not (state.openRaids.giants.enabled and state.giantsMode=="querah" and state.giantsInvaderIds[enemy:GetAttribute("Id")])
            and not state.guildEnemyIds[enemy:GetAttribute("Id")] and (not map or tostring(enemy:GetAttribute("MapId")) == map)
            and (not quest or questEnemyMatches(quest, enemy:GetAttribute("Id"), enemy:GetAttribute("MapId"), quest.info[enemy:GetAttribute("Id")])) then
            local room=tonumber(enemy:GetAttribute("RoomId") or enemy:GetAttribute("Room"))
            if highest and (enemy:GetAttribute("Shield")==true or enemy:GetAttribute("Invulnerable")==true
                or enemy:GetAttribute("Untargetable")==true or (room and currentRoom and room~=currentRoom)) then continue end
            local value=(enemy.Position-position).Magnitude
            local hp=highest and enemyState.HP(enemy)
            local comparison=highest and state.compareEnemyHP(hp,selectedHP) or 0
            if not selected or (highest and comparison>0) or (comparison==0 and value<distance) then
                selected,distance,selectedHP=enemy,value,hp
            end
        end
    end
    return selected
end
function state.highestDungeonTarget(folder,position)
    if not dungeon.utilities.highestHP or not insideDungeon() then state.highestHPLocked=nil;return nil end
    local locked=state.highestHPLocked
    local currentRoom=tonumber(storage:GetAttribute("CurrentRoom"))
    local room=locked and tonumber(locked:GetAttribute("RoomId") or locked:GetAttribute("Room"))
    if living(locked,folder) and locked:GetAttribute("Shield")~=true
        and locked:GetAttribute("Invulnerable")~=true and locked:GetAttribute("Untargetable")~=true
        and not (room and currentRoom and room~=currentRoom) then return locked end
    -- HP chooses a new target only after the previous enemy dies/disappears or becomes ineligible.
    state.highestHPLocked=nearest(folder,position,nil,nil)
    return state.highestHPLocked
end
local function nearestWorldBoss(folder, position, world)
    local selected, distance
    for _, enemy in ipairs(folder and folder:GetChildren() or {}) do
        local info = worldBossIds[enemy:GetAttribute("Id")]
        if info and ((world == "pumpkinking") == (enemy:GetAttribute("Id") == "PumpkinKing")) and living(enemy, folder) then
            local value = (enemy.Position - position).Magnitude
            if not distance or value < distance then selected, distance = enemy, value end
        end
    end
    return selected
end
-- DUNGEON SEARCH: visit generated rooms to load distant enemy markers.
local function dungeonSearchPoints(world, currentRoom, onlyCurrent)
    local rooms, points = {}, {}
    if not world or type(currentRoom) ~= "number" then return points end
    for _, room in ipairs(world:GetChildren()) do
        local index = tonumber(room.Name:match("^Room_(%d+)$"))
        if index and index <= currentRoom and (not onlyCurrent or index == currentRoom or index == currentRoom - 1) then table.insert(rooms, {model = room, index = index}) end
    end
    table.sort(rooms, function(a, b)
        if a.index == b.index then return false end
        if a.index == currentRoom then return true end
        if b.index == currentRoom then return false end
        return a.index > b.index
    end)
    for _, item in ipairs(rooms) do
        local room = item.model
        local spawnFolder = room:FindFirstChild("EnemiesSpawn")
        for _, spawn in ipairs(spawnFolder and spawnFolder:GetDescendants() or {}) do
            if spawn:IsA("BasePart") then table.insert(points, spawn.Position + Vector3.new(0, 4, 0)) end
        end
        local entrance, exit = room:FindFirstChild("Entrace"), room:FindFirstChild("Exit")
        local center = room:FindFirstChild("Floor")
        if not spawnFolder and not entrance and center and center:IsA("BasePart") then
            table.insert(points, center.Position + Vector3.new(0, 4, 0))
        end
        local floor = room:GetAttribute("MinY")
        if entrance and entrance:IsA("BasePart") and exit and exit:IsA("BasePart") and type(floor) == "number" then
            for _, fraction in ipairs({0.8, 0.5, 0.2}) do
                local position = entrance.Position:Lerp(exit.Position, fraction)
                table.insert(points, Vector3.new(position.X, floor + 4, position.Z))
            end
        end
    end
    return points
end
-- END DUNGEON SEARCH
local function castlePortal(world, position, currentRoom, used)
    if not world or type(currentRoom) ~= "number" then return nil end
    local room = world:FindFirstChild("Room_" .. tostring(math.floor(currentRoom)))
    if not room then
        for _, candidate in ipairs(world:GetChildren()) do
            if tonumber(candidate.Name:match("^Room_(%d+)$")) == currentRoom then room = candidate break end
        end
    end
    if not room then return nil end
    local portal = room:FindFirstChild("FirePortal", true) or room:FindFirstChild("Portal", true)
    if not portal then return nil end
    local prompt = portal:FindFirstChildWhichIsA("ProximityPrompt", true)
    if not prompt or not prompt.Enabled then return nil end
    local parent = prompt.Parent
    local part = parent and parent:IsA("BasePart") and parent
        or parent and parent:IsA("Attachment") and parent.Parent and parent.Parent:IsA("BasePart") and parent.Parent
        or portal:IsA("BasePart") and portal
        or portal:IsA("Model") and (portal.PrimaryPart or portal:FindFirstChildWhichIsA("BasePart", true))
    if not part then return nil end
    local destination = parent:IsA("Attachment") and parent.WorldPosition or part.Position
    return part, prompt, currentRoom, destination
end
-- END CASTLE ENTRY
-- A missing/unknown HP marker is not evidence that a room is empty.
function state.castleHasEnemyEvidence(folder)
    if not folder then return true end
    for _, enemy in ipairs(folder:GetChildren()) do
        if enemy:IsA("BasePart") and enemy:GetAttribute("Id") and not state.guildEnemyIds[enemy:GetAttribute("Id")] then
            if living(enemy, folder) then return true end
            if not enemyState.Dead(enemy) and enemyState.HP(enemy) == nil then return true end
        end
    end
    return false
end
function state.castleRecoveryPoints(world, number)
    local room = world and world:FindFirstChild("Room_" .. tostring(number))
    if not room then return nil end
    -- Restrict streaming to this room even if previous rooms are still loaded.
    return dungeonSearchPoints({GetChildren = function() return {room} end}, number, true)
end
connect(storage:GetAttributeChangedSignal("CurrentRoom"), function()
    if storage:GetAttribute("IsCastle") == true then
        state.target, state.searchPosition, state.lastFarmPosition = nil, nil, nil
        state.entryUntil = math.max(state.entryUntil or 0, os.clock() + 0.8)
        generation += 1
    end
    state.castleRecovery, state.castleRecoveryStream, state.castleRecoveryStatus = nil, nil, nil
    if state.castleProgress then
        state.castleProgress = {room = tonumber(storage:GetAttribute("CurrentRoom")),
            message = storage:GetAttribute("DungeonMessage"), fresh = false}
    end
end)
local function rootPart()
    local char = player.Character
    local root = char and (char:FindFirstChild("HumanoidRootPart") or char.PrimaryPart)
    local human = char and char:FindFirstChildOfClass("Humanoid")
    return root and human and human.Health > 0 and root or nil
end
-- ENTRY READINESS: release only the entry request's hold after a native transition.
function state.refreshEntryWait()
    local pending = state.entryPending
    if not pending then return end
    local now = os.clock()
    if now >= (state.entryUntil or 0) then state.entryPending = nil return end
    local root = rootPart()
    if not insideDungeon() or not root or not enemyFolder() or player.GameplayPaused then pending.readyAt = nil return end
    local transitioned = not pending.inside or root ~= pending.root
        or storage:GetAttribute("CurrentRoom") ~= pending.room
        or (pending.completed and storage:GetAttribute("DungeonCompleted") ~= true)
    if not transitioned then pending.readyAt = nil return end
    pending.readyAt = pending.readyAt or now
    if now - pending.readyAt >= 0.25 then
        state.entryPending, state.entryUntil = nil, nil
        state.target, state.searchPosition, state.map = nil, nil, nil
        generation += 1
    end
end
-- END ENTRY READINESS
-- Saved Fast Click preference. Local combat coefficients do not prove server-side DPS gains.
do
local test={enabled=false,multiplier=2,playerMultiplier=uiState.fastClickSpeed==2 and 2 or 4,interval=0.05,nextAt=0}
state.fastClick=test
local installed
local preferencePath="VykronHub/FastClick-"..player.UserId..".json"
-- The currently published loader may rewrite an older profile without these UI keys.
-- Keep the same preference in an owned companion file so test reloads retain it.
do
    local ok,value=pcall(function() return Http:JSONDecode(readfile(preferencePath)) end)
    if ok and type(value)=="table" and value.userId==player.UserId and value.version==1
        and type(value.enabled)=="boolean" and (value.speed==2 or value.speed==4) then
        uiState.fastClickEnabled=value.enabled;uiState.fastClickSpeed=value.speed
        test.playerMultiplier=value.speed
    end
end
local function savePreferences(previousEnabled,previousSpeed)
    local previousOK,previous=pcall(readfile,preferencePath)
    if not save() then return false end
    local ok=pcall(function()
        if type(makefolder)=="function" then pcall(makefolder,"VykronHub") end
        local value={version=1,userId=player.UserId,enabled=uiState.fastClickEnabled==true,
            speed=uiState.fastClickSpeed==2 and 2 or 4}
        writefile(preferencePath,Http:JSONEncode(value))
        local confirmed=Http:JSONDecode(readfile(preferencePath))
        assert(confirmed.userId==value.userId and confirmed.version==1
            and confirmed.enabled==value.enabled and confirmed.speed==value.speed,"Fast Click preference not confirmed")
    end)
    if not ok then
        local rollback=previousOK and previous or Http:JSONEncode({version=1,userId=player.UserId,
            enabled=previousEnabled==true,speed=previousSpeed==2 and 2 or 4})
        pcall(writefile,preferencePath,rollback)
    end
    return ok
end
function state.fastClickDependencies()
    return require(shared:WaitForChild("ExtraFunctions")),require(shared:WaitForChild("PetsService"))
end
local function restore()
    if not installed then return end
    if installed.extra.FindTalent==installed.playerWrapper then installed.extra.FindTalent=installed.playerOriginal end
    if installed.pets.GetAttackDelay==installed.shadowWrapper then installed.pets.GetAttackDelay=installed.shadowOriginal end
    installed=nil
end
function state.fastClickSetSpeed(value)
    if value~=2 and value~=4 then return false end
    local previous=uiState.fastClickSpeed
    uiState.fastClickSpeed=value
    if not savePreferences(uiState.fastClickEnabled,test.playerMultiplier) then
        uiState.fastClickSpeed=previous;save()
        test.problem=uiState.language=="PT" and "Não foi possível salvar a velocidade."
            or uiState.language=="ES" and "No se pudo guardar la velocidad." or "Could not save the speed."
        return false
    end
    test.playerMultiplier=value;test.problem=nil
    return true
end
function state.fastClickSetEnabled(value)
    if not value then test.enabled=false;test.nextAt=0;test.attackAt=0;restore();return true end
    if test.enabled then return true end
    local ok,problem=pcall(function()
        local extra,pets=state.fastClickDependencies()
        assert(type(extra.FindTalent)=="function" and type(pets.GetAttackDelay)=="function","Native combat functions unavailable")
        local hooks={extra=extra,pets=pets,playerOriginal=extra.FindTalent,shadowOriginal=pets.GetAttackDelay}
        hooks.playerWrapper=function(who,key,...)
            if who~=player or key~="AttackSpeed" or not test.enabled or state.panic then return hooks.playerOriginal(who,key,...) end
            local result=hooks.playerOriginal(who,key,...)
            return type(result)=="number" and result>0 and result/test.playerMultiplier or result
        end
        hooks.shadowWrapper=function(...)
            local delay=hooks.shadowOriginal(...)
            if not test.enabled or state.panic or type(delay)~="number" then return delay end
            return math.max(0.05,delay/test.multiplier)
        end
        installed=hooks
        extra.FindTalent=hooks.playerWrapper
        pets.GetAttackDelay=hooks.shadowWrapper
    end)
    if not ok then
        test.enabled=false;pcall(restore);test.problem=tostring(problem);return false
    end
    test.problem=nil;test.nextAt=0;test.attackAt=0;test.enabled=true;return true
end
function state.fastClickCommitEnabled(value)
    if type(value)~="boolean" then return false end
    local previousEnabled,previousSaved=test.enabled,uiState.fastClickEnabled
    if not state.fastClickSetEnabled(value) then return false end
    uiState.fastClickEnabled=value
    if not savePreferences(previousSaved,test.playerMultiplier) then
        uiState.fastClickEnabled=previousSaved;save()
        state.fastClickSetEnabled(previousEnabled)
        test.problem=uiState.language=="PT" and "Não foi possível salvar o Fast Click."
            or uiState.language=="ES" and "No se pudo guardar Fast Click." or "Could not save Fast Click."
        return false
    end
    test.problem=nil
    return true
end
function state.fastClickRestore()
    if uiState.fastClickEnabled==true then state.fastClickSetEnabled(true) end
    if test.refresh then test.refresh() end
end
function state.fastClickStep()
    if not alive or not test.enabled or state.panic or os.clock()<test.nextAt then return end
    test.nextAt=os.clock()+test.interval
    if state.fastClickAttack then
        local ok,problem=pcall(state.fastClickAttack,state.target,rootPart())
        if not ok then test.problem=tostring(problem);state.fastClickSetEnabled(false) end
    end
end
connect(RunService.Heartbeat,state.fastClickStep)
table.insert(cleanupCallbacks,function() test.enabled=false;pcall(restore) end)
end
