local stats={
    Power={PT="Poder",EN="Power",ES="Poder"},
    UltDamage={PT="Dano Ultimate",EN="Ultimate Damage",ES="Daño Ultimate"},
    Speed={PT="Velocidade",EN="Speed",ES="Velocidad"},
    AtkSpeed={PT="Veloc. de ataque",EN="Attack Speed",ES="Veloc. de ataque"},
}
local tiers={
    SHADOW={PT="Sombra",EN="Shadow",ES="Sombra"},
    SOLDIER={PT="Soldado",EN="Soldier",ES="Soldado"},
    KNIGHT={PT="Cavaleiro",EN="Knight",ES="Caballero"},
    ["ELITE KNIGHT"]={PT="Cavaleiro de elite",EN="Elite Knight",ES="Caballero de élite"},
    GENERAL={PT="General",EN="General",ES="General"},
    MARSHAL={PT="Marechal",EN="Marshal",ES="Mariscal"},
    ["GRAND MARSHAL"]={PT="Grande marechal",EN="Grand Marshal",ES="Gran mariscal"},
    MONARCH={PT="Monarca",EN="Monarch",ES="Monarca"},
}
function state.shadowCraftText(key,...)
    local entry=stats[key] or messages[key]
    if key:sub(1,5)=="tier:" then key=key:sub(6);entry=tiers[key:upper()] end
    local language=uiState.language
    local template=entry and (language=="PT" and (entry.PT or key) or entry[language]) or key
    if select("#",...)==0 then return template or key end
    return string.format(template or key,...)
end
end
