-- UI LANGUAGE: native event names and editable text are preserved.
do
    local catalog = state.languageCatalog
    -- Resolve complete phrases in either source language. Replacements are emitted once,
    -- never fed back into the dictionary (prevents mixed/cascaded translations).
    local aliases, exact, trie = {}, {}, {}
    local function wordByte(byte)
        return byte and (byte >= 128 or (byte >= 48 and byte <= 57) or (byte >= 65 and byte <= 90)
            or (byte >= 97 and byte <= 122) or byte == 95)
    end
    function state.refreshLanguageCatalog()
    aliases, exact, trie = {}, {}, {}
    local keys = {}
    for key in pairs(catalog) do table.insert(keys, key) end
    table.sort(keys, function(a, b) return #a == #b and a < b or #a > #b end)
    for _, key in ipairs(keys) do
        local entry = catalog[key]
        local record = {PT = entry.PT or key, EN = entry.EN or key, ES = entry.ES or key, exactOnly=entry.exactOnly}
        exact[key] = record
        for _, language in ipairs({"PT", "EN", "ES"}) do
            local value = record[language]
            if value ~= "" and not aliases[value] then aliases[value] = record end
        end
    end
    -- Explicit source entries win over an ambiguous reverse alias.
    for key, record in pairs(exact) do aliases[key] = record end
    for key, record in pairs(aliases) do
        if record.exactOnly then continue end
        local node = trie
        for index = 1, #key do
            local byte = key:byte(index)
            node[byte] = node[byte] or {}
            node = node[byte]
        end
        node.record, node.key = record, key
    end
    end
    state.refreshLanguageCatalog()
    local nodes = setmetatable({}, {__mode = "k"})
    function state.translate(text)
        if type(text) ~= "string" or text == "" then return text end
        local language = uiState.language
        local entry = aliases[text]
        if entry then return entry[language] or text end
        local chunks, cursor = {}, 1
        while cursor <= #text do
            -- RichText markup is data, not text. Do not translate font names/colors/IDs.
            if text:sub(cursor, cursor) == "<" then
                local close = text:find(">", cursor, true)
                if close then table.insert(chunks, text:sub(cursor, close)) cursor = close + 1 continue end
            end
            local node, index, matched, after = trie, cursor, nil, nil
            while index <= #text do
                node = node[text:byte(index)]
                if not node then break end
                if node.record then
                    local key = node.key
                    local leftOK = not wordByte(key:byte(1)) or not wordByte(text:byte(cursor - 1))
                    local rightOK = not wordByte(key:byte(-1)) or not wordByte(text:byte(index + 1))
                    if leftOK and rightOK then matched, after = node.record, index + 1 end
                end
                index += 1
            end
            if matched then
                table.insert(chunks, matched[language] or text:sub(cursor, after - 1))
                cursor = after
            else
                table.insert(chunks, text:sub(cursor, cursor))
                cursor += 1
            end
        end
        return table.concat(chunks)
    end
    function state.sourceText(node, property)
        local record = nodes[node]
        if record and record.property == (property or "Text") then return record.source end
        return node[property or "Text"]
    end
    function state.setLocalizedText(node, text, property)
        property = property or "Text"
        local record = nodes[node]
        if record and record.property == property then
            record.source, record.rendered = text, state.translate(text)
            if node[property] ~= record.rendered then node[property] = record.rendered end
        else node[property] = text end
    end
    function state.bindLanguage(node, property)
        property = property or "Text"
        if type(node.IsA) == "function" then pcall(function() node.AutoLocalize = false end) end
        local existing = nodes[node]
        if existing and existing.property == property then return end
        local record = {source = node[property], property = property}
        nodes[node] = record
        local function update()
            if node[property] == record.rendered then return end
            record.source = node[property]
            record.rendered = state.translate(record.source)
            if node[property] ~= record.rendered then node[property] = record.rendered end
        end
        update()
        connect(node:GetPropertyChangedSignal(property), update)
        if type(node.IsA) == "function" then
            connect(node:GetPropertyChangedSignal("AutoLocalize"), function()
                if node.AutoLocalize then node.AutoLocalize = false end
            end)
        end
    end
    function state.localizeTree(root)
        state.refreshLanguageCatalog()
        local function bind(node)
            if node:IsA("GuiBase2d") then pcall(function() node.AutoLocalize = false end) end
            if node:IsA("TextLabel") or node:IsA("TextButton") then state.bindLanguage(node)
            elseif node:IsA("TextBox") then state.bindLanguage(node, "PlaceholderText") end
        end
        bind(root)
        for _, node in ipairs(root:GetDescendants()) do bind(node) end
        connect(root.DescendantAdded, bind)
    end
    function state.applyLanguage()
        state.refreshLanguageCatalog()
        -- Snapshot all canonical source values before mirrored controls update.
        local plan = {}
        for node, record in pairs(nodes) do table.insert(plan, {node, record, record.source}) end
        for _, item in ipairs(plan) do
            local node, record, source = item[1], item[2], item[3]
            record.source, record.rendered = source, state.translate(source)
            if node[record.property] ~= record.rendered then node[record.property] = record.rendered end
        end
    end
end
-- END UI LANGUAGE
-- LAYOUT SWITCHER: defer to the fully built interface; never destroy its controls.
function state.switchLayout(layoutName)
    if not alive then return false end
    if not table.find({"NewHub", "Horizontal", "Compact"}, layoutName) then return false end
    uiState.layout = layoutName
    if state.applyLayout then return state.applyLayout(layoutName) end
    return true
end
function state.installCompactHub() return state.switchLayout("Compact") end

-- Enfeites (cantos, bordas, degradê) dentro da janela ANTIGA não são criados: ela fica escondida e só guarda os controles de estado;
-- quem aparece é a interface nova. O objeto é devolvido solto (sem pai) para o código que ainda ajusta suas propriedades.
local make
do
local DECOR_ANTIGA = {UICorner = true, UIStroke = true, UIGradient = true}
function make(class, props, parent)
    local x = Instance.new(class)
    for k, v in pairs(props) do x[k] = v end
    if class == "TextLabel" or class == "TextButton" then state.bindLanguage(x) end
    if class == "TextBox" then state.bindLanguage(x, "PlaceholderText") end
    local antiga = state.janelaAntiga
    if DECOR_ANTIGA[class] and antiga and parent and (parent == antiga or parent:IsDescendantOf(antiga)) then return x end
    x.Parent = parent
    return x
end
end
