-- Collection priority never treats a running dungeon as completed.
-- HALLOWEEN POLICY: night is an observed server flag, never an inferred local schedule.
function state.isHalloweenNight()
    return workspace:GetAttribute("HalloweenNight") == true
end
function state.kingNotice(packet)
    local id = packet.Boss or packet.Id or packet.Enemy
    local text = tostring(packet.Message or ""):gsub("<[^>]+>", ""):lower()
    if id ~= "PumpkinKing" and not text:find("pumpkin king", 1, true) then return nil end
    for _, token in ipairs({"has ended", "has died", "defeated", "despawn", "derrotado", "terminou"}) do
        if text:find(token, 1, true) then return "ended" end
    end
    if id == "PumpkinKing" and packet.WType == "WorldBossAnnounce" then return "spawn" end
    for _, token in ipairs({"has risen", "spawned", "has appeared", "nasceu", "surgiu"}) do
        if text:find(token, 1, true) then return "spawn" end
    end
    return nil
end
function state.kingDue()
    if state.questPriorityActive and state.questPriorityActive() then return false end
    local config = state.pumpkinKing
    if not config.enabled then return false end
    if events.active == "pumpkinking" then return true end
    local root = rootPart()
    if root and nearestWorldBoss(enemyFolder(), root.Position, "pumpkinking") then return true end
    return config.world == tonumber(storage:GetAttribute("World")) and (config.untilAt or 0) > workspace:GetServerTimeNow()
end
-- END HALLOWEEN POLICY

function state.houseCollectionDue()
    if state.questPriorityActive and state.questPriorityActive() then return nil end
    local houses = state.houses
    if not houses.enabled then return false end
    if houses.route.returnWorld then return true end
    local untilAt = houses.route.waitUntil
    local now = tonumber(storage:GetAttribute("DateTime"))
    return untilAt == nil or (now ~= nil and untilAt <= now)
end
function state.pumpkinCollectionDue()
    if state.questPriorityActive and state.questPriorityActive() then return nil end
    if not pumpkin.enabled or not state.isHalloweenNight() or os.clock() < (state.pumpkinNextScan or 0) then return false end
    if state.pumpkinBusy then return true end
    local extra = workspace:FindFirstChild("__Extra")
    local folder = extra and extra:FindFirstChild("__Pumps")
    local world = tonumber(storage:GetAttribute("World"))
    for _, model in ipairs(folder and folder:GetChildren() or {}) do
        local prompt = model:FindFirstChildWhichIsA("ProximityPrompt", true)
        local ownWorld = tonumber(tostring(model:GetAttribute("World") or ""):match("%d+"))
        if (not ownWorld or ownWorld == world) and model:GetAttribute(tostring(player.UserId)) == nil
            and prompt and prompt.Enabled and os.clock() >= (state.pumpkinRejected[model] or 0) then return true end
    end
    return false
end
function state.collectionPriority()
    if state.questPriorityActive and state.questPriorityActive() then return nil end
    if state.kamishDue() then return "kamish" end
    if state.houseCollectionDue() then return "houses" end
    if state.kingDue() then return "pumpkinking" end
    if state.pumpkinCollectionDue() then return "pumpkins" end
    return nil
end
function state.replayAllowed()
    if state.questTrialRefillPending and state.questTrialRefillPending() then return not player.GameplayPaused and not state.panic end
    if state.limitBreakerPortalRequested and state.limitBreakerPortalRequested()
        and (not insideDungeon() or state.limitBreakerPortalOwnsRun()) then return dungeon.repeatGems==true end
    if state.questPriorityActive and state.questPriorityActive() then return false end
    if autoQuest.enabled and (autoQuest.scope == "all" or autoQuest.scope == "recurring") and autoQuest.journey then return false end
    if dungeon.mode=="key" and dungeon.enabled and dungeon.autoKeys and state.autoKeysCanReplay then
        -- Finish this key's stock before collection/replay exit arbitration takes over.
        return state.autoKeysCanReplay()
    end
    return (dungeon.repeatGems == true or dungeon.enabled and dungeon.mode=="key" and dungeon.autoKeys==true)
        and state.collectionPriority() == nil
end

local function availablePumpkin(model, folder, userId)
    if not folder or not model or model.Parent ~= folder or model:GetAttribute(tostring(userId)) ~= nil then return nil end
    local part = model:FindFirstChild("Main")
    local prompt = model:FindFirstChildWhichIsA("ProximityPrompt", true)
    if part and part:IsA("BasePart") and prompt and prompt.Enabled and prompt:IsDescendantOf(part) then return part, prompt end
    return nil
end
-- RESPONSIVE VIEWPORT PROFILES
function state.rememberResponsiveSize()
    if not state.responsiveWindow or not state.responsiveProfile then return end
    uiState.responsiveSizes = uiState.responsiveSizes or {}
    uiState.responsiveSizes[state.responsiveProfile] = {width = uiState.width, height = uiState.height}
end
function state.configureResponsiveViewport(force)
    if not state.responsiveWindow then return end
    local size = gui.AbsoluteSize
    if size.X <= 24 or size.Y <= 24 then return end
    local key = Input.TouchEnabled and (size.X > size.Y and "mobileLandscape" or "mobilePortrait") or "desktop"
    if state.responsiveProfile == key and not force then return end
    state.rememberResponsiveSize()
    uiState.responsiveSizes = uiState.responsiveSizes or {}
    local profile = uiState.responsiveSizes[key]
    if not profile then
        local width, height = state.responsiveDefaultSize(size.X, size.Y)
        profile = {width = width, height = height}
    end
    if not uiState.responsiveVersion then
        uiState.previousPanelSize = {width = uiState.width, height = uiState.height}
        uiState.responsiveVersion = 1
    end
    state.responsiveProfile = key
    uiState.width, uiState.height = profile.width, profile.height
    uiState.compact = false
    state.windowUnit = nil
    window:SetAttribute("SavedWidth", nil)
    state.rememberResponsiveSize()
    save()
end
-- END RESPONSIVE VIEWPORT PROFILES
-- AJUSTE DA JANELA: escala/posição da janela ativa (a interface nova depois que ela instala; antes disso, o contêiner provisório) a cada quadro.
local function fit()
    if state.resizeActive then return end
    if state.responsiveWindow then state.configureResponsiveViewport() end
    local size = gui.AbsoluteSize
    if size.X <= 24 or size.Y <= 24 then return end
    local width, height = uiState.width, uiState.height
    if not state.windowUnit or window:GetAttribute("CanvasWidth") ~= size.X or window:GetAttribute("CanvasHeight") ~= size.Y then
        state.windowUnit = state.responsiveWindow and math.min(1, (size.X - 24) / width, (size.Y - 24) / height)
            or math.min(1, (size.X - 24) / 500, (size.Y - 24) / 820, (size.X - 24) / width, (size.Y - 24) / height)
    end
    local newScale = state.windowUnit
    local resized = window:GetAttribute("CanvasWidth") ~= size.X or window:GetAttribute("CanvasHeight") ~= size.Y
        or window:GetAttribute("SavedWidth") ~= width or window:GetAttribute("SavedHeight") ~= height
    window.Size, scale.Scale = UDim2.fromOffset(width, state.collapsedHeight or height), newScale
    if not resized then return end
    window:SetAttribute("CanvasWidth", size.X) window:SetAttribute("CanvasHeight", size.Y)
    window:SetAttribute("SavedWidth", width) window:SetAttribute("SavedHeight", height)
    local halfX, halfY = width * newScale / 2, (state.collapsedHeight or height) * newScale / 2
    local centerX = window.Position.X.Scale * size.X + window.Position.X.Offset
    local centerY = window.Position.Y.Scale * size.Y + window.Position.Y.Offset
    local x = math.clamp(centerX, halfX + 8, size.X - halfX - 8)
    local y = math.clamp(centerY, halfY + 8, size.Y - halfY - 8)
    if x ~= centerX or y ~= centerY then
        window.Position = UDim2.fromOffset(x, y)
        uiState.x, uiState.y, uiState.ox, uiState.oy = 0, 0, x, y
        save()
    end
end
fit()
miniLogo.Position = uiState.miniX and UDim2.new(uiState.miniX, uiState.miniOX or 0, uiState.miniY or 0.5, uiState.miniOY or 0)
