        ["icone-recompensas-v1.png"] = "98669683118011",
        ["icone-loja-v1.png"] = "97609072531165",
        ["icone-configuracoes-v1.png"] = "108165970800990",
        ["farm-v2/sword-v2.png"] = "71771275636313",
        ["farm-v2/quest-v2.png"] = "114987314695284",
        ["farm-v2/rebirth-v2.png"] = "74655128711098",
        ["farm-v2/worldboss-v2.png"] = "108374055595521",
        ["farm-v2/storm-v2.png"] = "113719915782673",
        ["farm-v2/pumpkin-v2.png"] = "103135607757230",
        ["farm-v2/house-v2.png"] = "109028285140421",
        ["dungeon-interior-v1/01-auto-dungeon.png"] = "82508029888823",
        ["dungeon-interior-v1/02-auto-replay.png"] = "73828654320716",
