        ["dungeon-interior-v1/04-portal-cabecalho.png"] = "101924235844447",
    }
    if published[filename] then return "rbxassetid://" .. published[filename] end
    local path = "VykronHub/Assets/" .. filename
    local register = getcustomasset or getsynasset
    if type(register) ~= "function" or type(isfile) ~= "function" or not isfile(path) then return nil end
    local ok, image = pcall(register, path)
    return ok and type(image) == "string" and image or nil
end
