-- SELO DA LICENÇA: tempo restante da licença (nunca o da sessão curta), atualizado a cada segundo.
do
    -- LICENSE BADGE POLICY: show license lifetime, never the short session lifetime.
    local function licenseBadgeText(remaining, kind, language)
        if kind == "permanent" then
            return language == "EN" and "Permanent" or "Permanente", "normal"
        end
        if kind ~= "timed" and kind ~= "expired" then
            return language == "EN" and "Key active" or language == "ES" and "Key activa" or "Key ativa", "unknown"
        end
        if type(remaining) ~= "number" or remaining ~= remaining or remaining == math.huge then return "--:--:--", "unknown" end
        local seconds = math.max(0, math.ceil(remaining))
        local days = math.floor(seconds / 86400)
        local time = string.format("%02d:%02d:%02d", math.floor(seconds / 3600) % 24, math.floor(seconds / 60) % 60, seconds % 60)
        return (days > 0 and days .. "d " or "") .. time, seconds <= 600 and "urgent" or seconds <= 3600 and "warning" or "normal"
    end
    -- END LICENSE BADGE POLICY

    -- Só o rótulo com o tempo da licença: a interface nova copia o texto e a cor dele para o selo dela.
    local badge = make("Frame", {Name = "LicenseBadge"}, window)
    local countdown = state.controlLabel("LicenseRemaining", "--:--:--", badge)
    local nextUpdate = 0
    local function updateLicenseBadge()
        local auth = env.__VykronHubLicense
        local remaining, kind
        if auth and type(auth.getLicenseRemaining) == "function" then remaining, kind = auth:getLicenseRemaining() end
        local text, tone = licenseBadgeText(remaining, kind, uiState.language)
        countdown.Text = text
        local color = tone == "urgent" and Color3.fromRGB(255, 104, 110)
            or tone == "warning" and Color3.fromRGB(255, 196, 91)
            or tone == "unknown" and colors.muted or Color3.fromRGB(35, 235, 164)
        countdown.TextColor3 = color
    end
    updateLicenseBadge()
    connect(RunService.Heartbeat, function()
        if not alive or not gui.Parent then return end
        local now = os.clock()
        if now >= nextUpdate then nextUpdate = now + 1 updateLicenseBadge() end
    end)
end
