    distribution.Name = "AutoDistributeStats"
    local list = make("ScrollingFrame", {Name = "StatPriorityList"}, rebirthSettings)
    local footer = state.controlLabel("RebirthFooter", "", rebirthSettings)
    local currentLabels, rowConnections, maxButtons, targetFields = {}, {}, {}, {}
    refreshRebirth = function()
        toggleLook(rebirthToggle, rebirth.enabled)
        toggleLook(distribution, rebirth.distribute)
        local count = tonumber(clientData.Get("Rebirths")) or 0
        local maximum = balanceInfo.MaxStats + 75 * count
        footer.Text = "Pontos livres: " .. tostring(clientData.Get("SkillPoints") or 0) .. " · Limite por atributo: " .. maximum
        for id, text in pairs(currentLabels) do
            text.Text = "Atual: " .. tostring(clientData.Get("PlayerStats", id) or 0) .. " / " .. maximum .. " · Meta total:"
            local enabled = rebirth.autoMax[id] == true
            maxButtons[id].Text = "Auto Max: " .. (enabled and "ON" or "OFF")
            maxButtons[id]:SetAttribute("AutoMaxEnabled", enabled)
            targetFields[id].TextEditable = not enabled
            if not targetFields[id]:IsFocused() then targetFields[id].Text = tostring(enabled and maximum or rebirth.targets[id]) end
        end
    end
    function state.setStatAutoMax(id, value)
        if not statsInfo[id] then return false end
        rebirth.autoMax[id] = value == true
        save()
        refreshRebirth()
        return true
    end
    local function renderStats()
        for _, connection in ipairs(rowConnections) do connection:Disconnect() end
        table.clear(rowConnections) table.clear(currentLabels) table.clear(maxButtons) table.clear(targetFields)
        list:ClearAllChildren()
        for rank, id in ipairs(rebirth.order) do
            -- A interface nova ordena as linhas por posição (Y) e lê os três rótulos sem nome na ordem: posição, nome, "Atual: ..."
            local row = state.controlCard(id, list, {Position = UDim2.fromOffset(2, (rank - 1) * 170)})
            make("TextLabel", {Text = tostring(rank)}, row)
            make("TextLabel", {Text = statsInfo[id].Name}, row)
            currentLabels[id] = make("TextLabel", {Text = ""}, row)
            local field = make("TextBox", {Name = "Target_" .. id, Text = tostring(rebirth.targets[id]), PlaceholderText = "Meta de pontos",
                ClearTextOnFocus = false}, row)
            connectUI(field, function()
                local number = tonumber(field.Text)
                if not rebirth.autoMax[id] and number and number == number and number >= 0 and number <= 1000000 then
                    rebirth.targets[id] = math.floor(number)
                    save()
                end
                field.Text = tostring(rebirth.targets[id])
                refreshRebirth()
            end, field.FocusLost, rowConnections)
            targetFields[id] = field
            local autoMax = state.controlButton("AutoMax_" .. id, "Auto Max", row)
            maxButtons[id] = autoMax
            connectUI(autoMax, function() state.setStatAutoMax(id, rebirth.autoMax[id] ~= true) end, nil, rowConnections)
            for _, direction in ipairs({-1, 1}) do
                local arrow = state.controlButton(direction == -1 and "MoveUp" or "MoveDown", direction == -1 and "↑" or "↓", row)
                connectUI(arrow, function()
                    local destination = rank + direction
                    if destination < 1 or destination > #rebirth.order then return end
                    rebirth.order[rank], rebirth.order[destination] = rebirth.order[destination], rebirth.order[rank]
                    save() renderStats()
                end, nil, rowConnections)
            end
        end
        refreshRebirth()
    end
    connectUI(rebirthToggle, function() rebirth.enabled = not rebirth.enabled save() refreshRebirth() end)
    connectUI(distribution, function() rebirth.distribute = not rebirth.distribute save() refreshRebirth() end)
    table.insert(cleanupCallbacks, function() for _, connection in ipairs(rowConnections) do connection:Disconnect() end end)
    renderStats()
end
