local trialSettings
do
    local definitions = require(storage.Indexer.TimeTrialBuffs)
    local catalogs = {buffs = {}, curses = {}}
    for category, tiers in pairs({buffs = definitions.Buffs, curses = definitions.Curses}) do
        for tier, entries in pairs(tiers) do
            for _, entry in ipairs(entries) do
                catalogs[category][entry.Id] = {data = entry, tier = tier}
            end
        end
        trialCards[category] = normalizeCardOrder(trialCards[category], catalogs[category])
    end
    function state.trialPriority(category)
        local selected, rest = {}, {}
        for _, id in ipairs(trialCards[category]) do
            table.insert(state.trialSelected[category][id] and selected or rest, id)
        end
        for _, id in ipairs(rest) do table.insert(selected, id) end
        return selected
    end
    function state.toggleTrialSelection(category, id)
        if not catalogs[category] or not catalogs[category][id] then return false end
        local selected = state.trialSelected[category]
        selected[id] = not selected[id] or nil
        if selected[id] then
            local order = trialCards[category]
            local at = table.find(order, id)
            if at then table.remove(order, at) end
            local insertAt = 1
            for index, item in ipairs(order) do if selected[item] then insertAt = index + 1 end end
            table.insert(order, insertAt, id)
        end
        save()
        return true
    end
    local names = {
        DamageMult = "Dano das armas", ShadowDmg = "Dano das sombras", AllDmg = "Dano de armas e sombras",
        BossDmg = "Dano contra bosses", FinalDmgMult = "Todo o dano", CritChance = "Chance critica",
        CritDmg = "Dano critico", WeaponSkillCharge = "Carga da habilidade", DamageMultOff = "Reducao de dano",
        CoinMult = "Dinheiro", RewardMult = "Recompensas", GemChance = "Chance de gemas",
        TicketChance = "Chance de tickets", TimeAdd = "Tempo", TimeOnKill = "Tempo por morte",
        TimeBank = "Aproveitamento do tempo restante", EnemyReduce = "Menos inimigos por sala",
        ExtraEnemies = "Mais inimigos por sala", EnemyHpMult = "Vida dos inimigos", BossHpMult = "Vida dos bosses",
        CandyMult = "Soul Candy",
    }
    local special = {
        GlassCannon = "+200% de dano", SealShadows = "Zera o dano das sombras",
        SealWeapon = "Zera o dano da arma", SealRange = "Sela o alcance das sombras",
        RoomTimeMult = "Tempo por sala -20%",
    }
    local penalties = {GlassCannon = "-30% de tempo por sala", HLMonarchsNight = "+50% de vida dos inimigos"}
    local function describe(entry)
        local effect = special[entry.Stat]
        if entry.Id == "HLMonarchsNight" then effect = "Todo o dano x3" end
        if not effect then
            local low = definitions.FormatValue(entry.Display, entry.Min)
            local high = definitions.FormatValue(entry.Display, entry.Max)
            effect = (names[entry.Stat] or entry.Text or entry.Stat) .. " " .. low
            if low ~= high then effect ..= " a " .. high end
        end
        return effect
    end
    -- Controles "sem visual" da janela antiga (escondida): só o que o código e a interface nova leem/acionam.
    trialSettings = make("Frame", {Name = "TrialCardSettings", Visible = false}, window)
    connectUI(trialCardsShortcut, function() trialSettings.Visible = true end)
    local auto = state.controlRow("Auto Cards", "Penalidade primeiro; buff desempata.", trialSettings)
    auto.Name = "AutoTrialCards"
    toggleLook(auto, trialCards.enabled)
    local statusText = state.controlLabel("TrialCardsStatus", "Aguardando a próxima seleção da Trial.", trialSettings)
    local category, query = "buffs", ""
    local buffTab = state.controlButton("TrialTabBuffs", "Buffs", trialSettings)
    local curseTab = state.controlButton("TrialTabCurses", "Penalidades", trialSettings)
    local explanation = state.controlLabel("TrialCardsExplanation", "", trialSettings)
    local search = make("TextBox", {Name = "TrialCardSearch", PlaceholderText = "Buscar card...", Text = "", ClearTextOnFocus = false}, trialSettings)
    local list = make("ScrollingFrame", {Name = "TrialCardPriorityList"}, trialSettings)
    local rowConnections = {}
    local function render()
        for _, connection in ipairs(rowConnections) do connection:Disconnect() end
        table.clear(rowConnections)
        list:ClearAllChildren()
        -- A interface nova lê a cor do texto das abas: destaque = aba ativa.
        for _, item in ipairs({{buffTab, "buffs"}, {curseTab, "curses"}}) do
            item[1].TextColor3 = item[2] == category and colors.accent or colors.muted
        end
        explanation.Text = category == "buffs" and "Do buff mais desejado para o menos desejado."
            or "Da mais aceitavel para a mais prejudicial. Escolhas obrigatorias nao sao puladas."
        -- A interface nova ordena as linhas por posição (Y) e lê, nesta ordem: posição, nome, efeito (cor!) e nota (cor!), a arte (OriginalIcon) e as setas.
        local y = 0
        for rank, id in ipairs(trialCards[category]) do
            local item = catalogs[category][id]
            local entry = item.data
            if query == "" or string.find(string.lower(entry.Name .. " " .. describe(entry)), query, 1, true) then
                local row = make("Frame", {Name = id, Position = UDim2.fromOffset(2, y)}, list)
                row:SetAttribute("TrialCategory", category)
                make("TextLabel", {Text = tostring(rank)}, row)
                if entry.Icon then make("ImageLabel", {Name = "OriginalIcon", Image = entry.Icon}, row) end
                make("TextLabel", {Text = entry.Name}, row)
                local effect = make("TextLabel", {Text = describe(entry)}, row)
                effect.TextColor3 = category == "curses" and Color3.fromRGB(255, 115, 115) or Color3.fromRGB(125, 235, 155)
                local note = penalties[id] or entry.PenaltyText
                local extra = make("TextLabel", {Text = note or item.tier}, row)
                extra.TextColor3 = note and Color3.fromRGB(255, 115, 115) or colors.muted
                for _, direction in ipairs({-1, 1}) do
                    local arrow = make("TextButton", {Text = direction == -1 and "↑" or "↓"}, row)
                    local destination = rank + direction
                    arrow.Active = destination >= 1 and destination <= #trialCards[category]
                    connectUI(arrow, function()
                        local order = trialCards[category]
                        if destination < 1 or destination > #order then return end
                        order[rank], order[destination] = order[destination], order[rank]
                        save() render()
                    end, nil, rowConnections)
                end
                y += 134
            end
        end
    end
    connectUI(buffTab, function() category = "buffs" list.CanvasPosition = Vector2.zero render() end)
    connectUI(curseTab, function() category = "curses" list.CanvasPosition = Vector2.zero render() end)
    connect(search:GetPropertyChangedSignal("Text"), function() query = string.lower(search.Text) list.CanvasPosition = Vector2.zero render() end)
    table.insert(cleanupCallbacks, function() for _, connection in ipairs(rowConnections) do connection:Disconnect() end end)
    render()
    connectUI(auto, function()
        trialCards.enabled = not trialCards.enabled
        toggleLook(auto, trialCards.enabled)
        save()
        render()
        statusText.Text = trialCards.enabled and "Aguardando a proxima selecao da Trial." or "Auto Cards desligado."
        state.voteTrialRestart()
    end)
    state.trialUI = {status = statusText}
end
-- TRIAL CARDS: votação automática (Auto Cards e reinício da Trial). Os controles ficam em ui/antiga/cartas.lua.
do
    local statusText = state.trialUI.status
    local selection
    local function vote()
        if not alive or not selection or selection.sent
            or os.clock() >= selection.deadline or storage:GetAttribute("InTimeTrial") ~= true then return end
        local index
        if selection.kind == "Restart" then
            if not state.replayAllowed() or not selection.choices[1] then return end
            index = 1
        else
            if not trialCards.enabled then return end
            index = chooseTrialCard(selection.choices, state.trialPriority("buffs"), state.trialPriority("curses"))
        end
        if not index then return end
        local success, problem = pcall(function() general:Fire({Event = "TimeTrialAction", Action = "SelectBuff", Index = index}) end)
        if success then
            selection.sent = true
            if selection.kind == "Restart" then statusText.Text = "Voto enviado: reiniciar a Trial na sala 1." return end
            local choice = selection.choices[index]
            statusText.Text = "Voto enviado: " .. tostring(choice.Buff.Name or choice.Buff.Id)
                .. (choice.Curse and (" / " .. tostring(choice.Curse.Name or choice.Curse.Id)) or " / Sem maldicao")
        else statusText.Text = "Falha ao votar: " .. tostring(problem) end
    end
    state.voteTrialRestart = vote
    local subscription = require(storage.BridgeNet2).ReferenceBridge("TRIAL_EVENT"):Connect(function(packet)
        if not alive or type(packet) ~= "table" then return end
        if packet.Mode == "Raid" or packet.Mode == "Dungeon" then return end
        if packet.Event == "ShowBuffSelection" then
            if packet.Kind == "Restart" then state.finishedMode = "trial"
            elseif state.finishedMode == "trial" then state.finishedMode = nil end
            selection = nil
            if type(packet.Choices) ~= "table" or type(packet.Voters) ~= "table"
                or not table.find(packet.Voters, player.UserId) then return end
            selection = {kind = packet.Kind, choices = packet.Choices, deadline = os.clock() + (tonumber(packet.Time) or 15)}
            vote()
        elseif packet.Event == "CloseBuffSelection" or packet.Event == "BuffChosen" then
            selection = nil
        end
    end)
    table.insert(cleanupCallbacks, function() subscription:Disconnect() end)
end
-- Auto Sell: controles da janela antiga (liga/desliga, status e botões de rank). A lógica de venda está em src/sellbuy/auto-sell.lua.
do
