            if previous then
                previous.label.Text = rank.name
                if typeof(rank.color) == "Color3" then previous.label.TextColor3 = rank.color end
                previous.refresh()
                continue
            end
            local key = tostring(rank.id)
            -- A interface nova ordena por LayoutOrder e lê o nome (RankName, com a cor do rank), a marca (RankMark) e o atributo RankSelected.
            local item = state.controlButton("Rank_" .. key, "", list)
            item.LayoutOrder = rank.id
            local text = make("TextLabel", {Name = "RankName", Text = rank.name, TextColor3 = colors.text}, item)
            if typeof(rank.color) == "Color3" then text.TextColor3 = rank.color end
            local mark = state.controlLabel("RankMark", "", item)
            local function refreshRank()
                local selected = autoSell.ranks[key] == true
                item:SetAttribute("RankSelected", selected)
                mark.Text = selected and "✓" or "○"
            end
            rankButtons[rank.id] = {label = text, refresh = refreshRank}
            connectUI(item, function()
                local selected = autoSell.ranks[key] ~= true
                local savedOK = state.commitSellPreference(autoSell.ranks, key, selected and true or nil)
                refreshRank()
                if not savedOK then status.Text = state.sellSaveMessage() end
            end)
            refreshRank()
        end
    end
    refreshRankButtons()
    connectUI(sellToggle, function()
        local savedOK = state.commitSellPreference(autoSell, "enabled", not autoSell.enabled)
