-- Auto Sell: one batch in flight, inventory-confirmed counts and bounded receipt waits.
do
    local status,refreshRankButtons=state.sellUI.status,state.sellUI.refreshRanks
    state.languageCatalog["Venda solicitada. Aguardando atualização do inventário..."]={EN="Sale requested. Waiting for inventory update...",ES="Venta solicitada. Esperando actualización del inventario..."}
    state.languageCatalog["Sem confirmação de sombras. Nova tentativa automática após a espera."]={EN="Shadows unconfirmed. Retrying automatically after the wait.",ES="Sombras sin confirmar. Reintento automático tras la espera."}
    state.languageCatalog["pedido não enviado; nova tentativa automática."]={EN="request not sent; automatic retry.",ES="solicitud no enviada; reintento automático."}
    local run={pending={},receipts={},retry={},attempts={},sold=0,nextRanksAt=0,nextSendAt=0}
    state.autoSellRuntime=run
    function state.autoSellStep(petEvent)
        if not alive or state.panic or state.stopped then return end
        local now=os.clock()
        if now>=run.nextRanksAt then run.nextRanksAt=now+10;refreshRankButtons() end
        if state.sellSaveProblem then status.Text=state.sellSaveMessage();return end
        local inventory=clientData.Get("Inventory","Pets")
        if type(inventory)~="table" then status.Text="Aguardando inventário de sombras...";return end
        local equipped={}
        for key,id in pairs(clientData.Get("Equips","Pets") or {}) do
            if type(id)=="string" then equipped[id]=true elseif id==true then equipped[key]=true end
        end
        -- The native Sell Many screen also excludes every saved team's shadows.
        for _,team in pairs(clientData.Get("Teams") or {}) do
            if type(team)=="table" and type(team.Pets)=="table" then
                for _,id in pairs(team.Pets) do if type(id)=="string" then equipped[id]=true end end
            end
        end
        for id in pairs(run.receipts) do
            if inventory[id]==nil then
                run.receipts[id]=nil;run.pending[id]=nil;run.retry[id]=nil;run.attempts[id]=nil;run.sold+=1
            end
        end
        for id,at in pairs(run.pending) do
            if state.craftReserved and state.craftReserved(id) and inventory[id] and now-at<12 then
                -- A sale sent before Craft selection still needs time to settle.
            elseif not state.sellableShadow(id,inventory[id],equipped,autoSell.ranks) then run.pending[id]=nil
            elseif now-at>=12 then
                run.pending[id]=nil
                local attempts=run.attempts[id] or 1
                run.retry[id]=now+(attempts>=3 and 60 or attempts*4)
            end
        end
        if not autoSell.enabled then status.Text="Desligado. Somente os ranks marcados serão vendidos.";return end
        if player.GameplayPaused then status.Text="Aguardando carregamento...";return end
        if next(run.pending) then status.Text=state.translate("Venda solicitada. Aguardando atualização do inventário...");return end
        if not next(autoSell.ranks) then status.Text="Marque pelo menos um rank para vender.";return end
        if now<run.nextSendAt then return end
        local available,retryReady,waiting={},{},0
        for id,pet in pairs(inventory) do
            if state.sellableShadow(id,pet,equipped,autoSell.ranks) then
                if now<(run.retry[id] or 0) then waiting+=1
                elseif (run.attempts[id] or 0)>0 then retryReady[id]=pet
                else available[id]=pet end
            end
        end
        local ids=sellableShadows(available,equipped,autoSell.ranks,autoSell.bulk)
        -- Isolate unconfirmed UIDs so one server-rejected item cannot poison another full batch.
        if #ids==0 then for id in pairs(retryReady) do ids={id};break end end
        if #ids==0 then
            status.Text=waiting>0 and (state.translate("Sem confirmação de sombras. Nova tentativa automática após a espera.").." ("..waiting..")")
                or ("Nenhuma sombra disponível nos ranks marcados. Vendidas nesta sessão: "..run.sold)
            return
        end
        -- Recheck controls immediately before the send; a blocked/failed bridge creates no receipt.
        if state.panic or state.stopped or not autoSell.enabled or player.GameplayPaused then return end
        run.nextSendAt=now+(autoSell.bulk and 0.5 or 2)
        local ok,result=pcall(function() return petEvent:Fire({Event="SellPet",Pets=ids}) end)
        if not ok or result==false then
            status.Text="Venda em espera: "..(ok and state.translate("pedido não enviado; nova tentativa automática.") or tostring(result))
            return
        end
        for _,id in ipairs(ids) do run.pending[id]=now;run.receipts[id]=true;run.attempts[id]=(run.attempts[id] or 0)+1 end
        status.Text="Solicitando venda de "..#ids.." sombras..."
    end
    task.spawn(function()
        clientData.WaitForLoaded()
        local petEvent=state.pausableBridge(require(storage.BridgeNet2).ReferenceBridge("PET_EVENT"))
        while alive do
            task.wait(0.25)
            if not alive then break end
            local ok,problem=pcall(state.autoSellStep,petEvent)
            if not ok then status.Text="Venda em espera: "..tostring(problem) end
        end
    end)
end
