-- SWORDS RECEIPTS: venda automática de espadas (loop a cada 2 s). Escreve o status em AutoSellSwordsStatus.
-- Os controles (liga/desliga, stacks, status e botões de rank) são criados em src/ui/antiga/espadas.lua.
do
    local config = autoSell.weapons
    local swordStatus, refreshRanks = state.swordUI.status, state.swordUI.refreshRanks
    local pending, blocked = {}, {}
    local sold, nextRanks, weaponList = 0, 0, nil
    task.spawn(function()
        clientData.WaitForLoaded()
        local definitions = require(storage.Indexer.WeaponsInfo)
        while alive do
            task.wait(2)
            if not alive then break end
            if state.panic then continue end
            local ok, problem = pcall(function()
                local now = os.clock()
                if now >= nextRanks then nextRanks = now + 10 refreshRanks() end
                if state.sellSaveProblem then swordStatus.Text = state.sellSaveMessage() return end
                local inventory = clientData.Get("Inventory", "Weapons")
                if type(inventory) ~= "table" then swordStatus.Text = "Aguardando inventário de espadas..." return end
                if state.questPurchaseReceipt and autoQuest.purchasePending then state.questPurchaseReceipt() end
                local confirmed, unconfirmed = state.swordReceipts(inventory, pending, blocked, now)
                sold += confirmed
                if not config.enabled then swordStatus.Text = "Desligado. Somente os ranks marcados serão vendidos." return end
                local marked = false
                for _, enabled in pairs(config.ranks) do if enabled == true then marked = true break end end
                if not marked then swordStatus.Text = "Marque pelo menos um rank para vender." return end
                if next(pending) then swordStatus.Text = "Venda solicitada. Aguardando confirmação do jogo; sem repetir o pedido." return end
                if player.GameplayPaused then return end
                local equipped, excluded, stacks = {}, {}, {}
                local equips = clientData.Get("Equips") or {}
                if equips.Weapon then equipped[equips.Weapon] = true end
                if equips.DualWeapon then equipped[equips.DualWeapon] = true end
                for id, untilAt in pairs(blocked) do if now < untilAt then excluded[id] = true else blocked[id] = nil end end
                if autoQuest.purchasePending and autoQuest.purchasePending.kind == "Weapon" then
                    for id, item in pairs(inventory) do
                        if type(item) == "table" and item.Name == autoQuest.purchasePending.id then excluded[id] = true end
                    end
                end
                if not config.stacks then
                    if not weaponList then
                        local scripts = player:FindFirstChild("PlayerScripts")
                        local ui = scripts and scripts:FindFirstChild("NewUI", true)
                        weaponList = require(assert(ui and ui:FindFirstChild("GameData") and ui.GameData:FindFirstChild("WeaponList"), "Catálogo de stacks indisponível"))
                    end
                    weaponList.ForEach(function(entry)
                        if entry.IsStack == true then for id in pairs(entry.Copies or {}) do stacks[id] = true end end
                    end)
                end
                local ids = state.sellableSwords(inventory, equipped, config.ranks, definitions, stacks, config.stacks, excluded)
                if #ids == 0 then
                    swordStatus.Text = unconfirmed and "Sem confirmação. Nova tentativa após intervalo."
                        or ("Nenhuma espada elegível. Vendidas nesta sessão: " .. sold)
                    return
                end
                for _, id in ipairs(ids) do pending[id] = now end
                general:Fire({Event = "WeaponAction", Action = "Sell", Weapons = ids})
                swordStatus.Text = "Solicitando venda de " .. #ids .. " espadas..."
            end)
            if not ok then swordStatus.Text = "Venda em espera: " .. tostring(problem) end
        end
    end)
end
