-- SESSÃO: Anti-AFK e Auto Reconnect (lógica; os controles ficam em ui/antiga/misc-opcoes.lua)
do
    local reconnect, afk = state.sessionRows.reconnect, state.sessionRows.afk
    connect(player.Idled, function()
        if not alive or state.panic or not uiState.antiAFK then return end
        local ok = pcall(function()
            local virtual = game:GetService("VirtualUser")
            virtual:CaptureController()
            virtual:ClickButton2(Vector2.zero)
        end)
        afk.Caption.Text = ok and "Anti-AFK active." or "Anti-AFK unavailable in this executor."
    end)
    local teleport = game:GetService("TeleportService")
    local failure
    connect(teleport.TeleportInitFailed, function(who, _, message)
        if who == player then failure = tostring(message) end
    end)
    local function visible(node)
        local parent = node
        while parent do
            if parent:IsA("GuiObject") and not parent.Visible then return false end
            if parent:IsA("ScreenGui") and not parent.Enabled then return false end
            parent = parent.Parent
        end
        return node.AbsoluteSize.X > 0 and node.AbsoluteSize.Y > 0
    end
    -- Match a real Roblox reconnect control, independently of the numeric error code.
    local function normalized(text)
        return tostring(text or ""):lower():gsub("<[^>]*>", ""):gsub("[%s%p]", "")
    end
    local reconnectWords = {reconnect = true, reconectar = true, rejoin = true,
        volveraconectar = true, reconectarse = true, retry = true, tryagain = true,
        tentarnovamente = true, reintentar = true}
    local reconnectNames = {reconnect = true, reconnectbutton = true, rejoinbutton = true, retrybutton = true}
    local function reconnectControl(node)
        local isText = node:IsA("TextButton") or node:IsA("TextLabel")
        local byText = isText and reconnectWords[normalized(node.Text)]
        local byName = node:IsA("GuiButton") and reconnectNames[normalized(node.Name)]
        if not byText and not byName then return nil end
        local control = node:IsA("GuiButton") and node or node:FindFirstAncestorWhichIsA("GuiButton")
        if control and control.Active and visible(control) then return control end
        return nil
    end
    local function findReconnect()
        local core = game:GetService("CoreGui")
        local prompts = core:FindFirstChild("RobloxPromptGui", true)
        if prompts then
            for _, node in ipairs(prompts:GetDescendants()) do
                local control = reconnectControl(node)
                if control then return control end
            end
        end
        -- Newer layouts can put the native error dialog outside RobloxPromptGui.
        for _, node in ipairs(core:GetDescendants()) do
            local parent, inDialog = node.Parent, false
            while parent and parent ~= core do
                local name = normalized(parent.Name)
                if name == "errorprompt" or name == "disconnectdialog" or name == "disconnectedprompt"
                    or name == "reconnectdialog" then inDialog = true break end
                parent = parent.Parent
            end
            if inDialog then
                local control = reconnectControl(node)
                if control then return control end
            end
        end
    end
    task.spawn(function()
        while alive do
            task.wait(1)
            if not alive then break end
            if state.panic then continue end
            if not uiState.reconnect then continue end
            local readOK, control = pcall(findReconnect)
            if not readOK then reconnect.Caption.Text = "Cannot read the reconnect dialog in this executor." continue end
            if not control then
                state.reconnectAttempt, state.reconnectAt = 0, 0
                reconnect.Caption.Text = "Waiting for a Roblox reconnect button."
                continue
            end
            local attempt, now = state.reconnectAttempt or 0, os.clock()
            if now < (state.reconnectAt or 0) then
                reconnect.Caption.Text = "Reconnecting in " .. math.ceil(state.reconnectAt - now) .. "s…"
                continue
            end
            state.reconnectAttempt, state.reconnectAt = attempt + 1, now + math.min(60, 10 * (attempt + 1))
            -- Saving is best effort: a filesystem failure must not prevent reconnection.
            save()
            local sent = false
            local inspect = getconnections or env.getconnections
            if type(inspect) == "function" then
                local inspected, result = pcall(function()
                    for _, signal in ipairs({control.Activated, control.MouseButton1Click}) do
                        local fired = false
                        for _, callback in ipairs(inspect(signal)) do
                            if callback.Enabled ~= false and type(callback.Fire) == "function" then
                                local ok = pcall(function() callback:Fire() end)
                                fired = fired or ok
                            end
                        end
                        if fired then return true end
                    end
                    return false
                end)
                sent = inspected and result == true
            end
            -- A callback can return successfully without the native dialog responding.
            -- On later attempts try the visible button's screen coordinates as well.
            if not sent or attempt >= 1 then
                local clicked = pcall(function()
                    if not visible(control) then return end
                    local point = control.AbsolutePosition + control.AbsoluteSize / 2
                    local input = game:GetService("VirtualInputManager")
                    input:SendMouseButtonEvent(point.X, point.Y, 0, true, game, 0)
                    input:SendMouseButtonEvent(point.X, point.Y, 0, false, game, 0)
                end)
                sent = sent or clicked
            end
            -- Only with a still-visible real reconnect button: use normal rejoin if
            -- the native UI remained stuck. Never run for a Leave-only kick dialog.
            if attempt >= 1 and visible(control) then
                local requested, problem = pcall(function() teleport:Teleport(game.PlaceId, player) end)
                sent = sent or requested
                if not requested then failure = tostring(problem) end
            end
            reconnect.Caption.Text = sent and ("Reconnect requested · " .. (attempt + 1) .. ". Waiting for confirmation…")
                or ("Reconnect not available: " .. tostring(failure or "no supported dialog interaction"))
        end
    end)
end

