-- MINIMIZAR: o botão da interface nova, o botão "V" e a tecla de atalho chamam as mesmas funções (a janela ativa é `window`).
local setMinimized, toggleMinimize
do
local minimized = false
function setMinimized(value)
    capturingKeybind = false
    refreshKeybind()
    if state.cancelResize then state.cancelResize() end
    minimized = value
    window.Visible = not minimized
    window.Interactable = not minimized
    for _, control in ipairs(window:GetDescendants()) do
        if control:IsA("GuiButton") or control:IsA("TextBox") then control.Interactable = not minimized end
    end
    if minimized then
        local focused = Input:GetFocusedTextBox()
        if focused and focused:IsDescendantOf(window) then focused:ReleaseFocus(false) end
    end
    miniLogo.Visible = Input.TouchEnabled
end
function toggleMinimize()
    setMinimized(not minimized)
end
end
connectUI(hideTotalToggle, function()
    uiState.hideTotal = not uiState.hideTotal
    toggleLook(hideTotalToggle, uiState.hideTotal)
    save()
    setMinimized(uiState.hideTotal)
end)
toggleLook(hideTotalToggle, uiState.hideTotal)
-- Sempre aparece ao iniciar; a preferencia so vale ao minimizar manualmente.
setMinimized(false)
connect(Input.InputBegan, function(input, processed)
    if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
    if capturingKeybind then
        if input.KeyCode == Enum.KeyCode.Escape then
            capturingKeybind = false
        elseif input.KeyCode ~= Enum.KeyCode.Unknown then
            uiState.minimizeKey = input.KeyCode.Name
            capturingKeybind = false
            save()
        end
        refreshKeybind()
        return
    end
    if not processed and not Input:GetFocusedTextBox() and input.KeyCode.Name == uiState.minimizeKey then toggleMinimize() end
end)
