local function destroy()
    if not alive then return end
    savePositions()
    alive, generation, state.stopped = false, generation + 1, true
    state.target = nil
    for _, c in ipairs(connections) do c:Disconnect() end
    for _, unsubscribe in ipairs(cleanupCallbacks) do unsubscribe() end
    gui:Destroy()
    if env.__VykronHub and env.__VykronHub.state == state then env.__VykronHub = nil end
end
env.__VykronHub = {destroy = destroy, state = state, misc = misc, dungeon = dungeon, pumpkin = pumpkin, rebirth = rebirth, autoSell = autoSell, autoQuest = autoQuest, questRuntime = questRuntime,
    worldBoss = worldBoss, storm = storm, events = events, autoClaim = autoClaim, autoBuy = autoBuy}
-- PANIC CONTROL: do not change any automation's enabled preference.
-- O botão de pânico fica na interface nova (src/ui/abas/misc/panico.lua), que chama state.setPanic.
do
    function state.setPanic(value)
        state.panic = value == true
        generation += 1
        state.target, state.searchPosition, state.map = nil, nil, nil
        if state.cancelRuneWork then state.cancelRuneWork() end
        if state.panic then
            local root = rootPart()
            if root then root.AssemblyLinearVelocity = Vector3.zero end
            status.Text = "Pânico ativo: automações pausadas."
        else
            state.entryUntil, state.entryPending, state.attackRetryAt = 0, nil, nil
            if state.castleProgress then state.castleProgress.zeroAt = nil end
            status.Text = "Automações retomadas; verificando o estado do jogo."
        end
        save()
    end
end
