local refreshMisc
do
local selectedMode = 1
function refreshMisc()
    local mode = miscModes[selectedMode]
    local config = misc[mode.id]
    state.speedSelectedMode=mode.id
    modeButton.Text = mode.name .. "   v"
    toggleLook(autoExecuteToggle, autoExecute)
    toggleLook(speedToggle, config.speedEnabled)
    toggleLook(exitToggle, config.exitEnabled)
    for index = 1, 4 do
        local key = "at" .. index
        local value = mode.values[index]
        fields[key].Visible, labels[key].Visible = value ~= nil, value ~= nil
        if value then labels[key].Text = value .. "× a partir do " .. mode.unit end
    end
