local partyClient = require(shared:WaitForChild("PartyClient"))
local nativeModes, nativeSchedule, rushDifficulties = {}, nil, {}
local nativePartyShared, nativeGameData
-- NATIVE LOAD: retry transient loading failures without replacing working references.
local nativeOK, nativeProblem = false, nil
local loadNative
do
local nativeRetryAt = 0
function loadNative()
    if nativeOK or os.clock() < nativeRetryAt then return end
    nativeRetryAt = os.clock() + 2
    local ok, result = pcall(function()
        local scripts = player:FindFirstChild("PlayerScripts")
        local ui = scripts and scripts:FindFirstChild("NewUI", true)
        assert(ui and ui:FindFirstChild("Screens"), "Interface nativa ainda nao carregou")
        local config = require(ui.Screens.Modes.Config)
        local party = require(ui.Screens.Party.Shared)
        local data = require(ui.GameData)
        local modes, difficulties = {}, {}
        assert(type(config.Status) == "function" and type(config.MODES) == "table", "Configuração nativa incompleta")
        for _, mode in ipairs(config.MODES) do modes[mode.Id] = mode end
        for _, value in ipairs(require(ui.Screens.Party.Config).RUSH_DIFFS) do
            table.insert(difficulties, {id = value.Name, name = value.Name})
        end
        return {modes = modes, schedule = config.Status, party = party, data = data, difficulties = difficulties}
    end)
    nativeOK = ok
    if not ok then nativeProblem = tostring(result) return end
    nativeModes, nativeSchedule, nativePartyShared, nativeGameData = result.modes, result.schedule, result.party, result.data
    table.clear(rushDifficulties)
    for _, entry in ipairs(result.difficulties) do table.insert(rushDifficulties, entry) end
    nativeProblem = nil
end
end
loadNative()
-- END NATIVE LOAD
local trialDifficulties, keyChoices = {}, {}
do
    local pending
    local modes = state.modeList("replay", {"desert", "infcastle", "labyrinth", "bossrush"})
    local function replay()
        if not alive or not pending or pending.sent or not state.replayAllowed() or os.clock() >= pending.deadline then return end
        local mode, packet = pending.mode, pending.packet
        if storage:GetAttribute(mode.flag) ~= true then return end
        if mode.rank and (tonumber(clientData.Get("Rank")) or 0) < mode.rank then return end
        if not nativeOK then return end
        local ui = player.PlayerScripts:FindFirstChild("NewUI", true)
        local config = require(ui.Screens.Party.Config)
        local theme = mode.id == "labyrinth" and config.LabTheme() or nil
        local currency = theme and config.LAB_CURRENCY[theme] or "Ticket"
        local price = tonumber(packet.Price)
        if not price or price < 0 or price ~= price then dungeonStatus.Text = "Replay: aguardando preço confirmado pelo jogo." return end
        state.replayBlocked = state.replayBlocked or {}
        state.replayBlocked[mode.id] = nativeGameData.GetItemAmount(currency) < price or nil
        if state.replayBlocked[mode.id] then
            dungeonStatus.Text = "Replay: " .. currency .. " insuficiente (" .. tostring(price) .. ")."
            return
        end
        local checkpoint
        if mode.id ~= "bossrush" and mode.id ~= "labyrinth" and tonumber(packet.MaxWave) then
            local every = config.MODES[mode.id].Wave.Every
            checkpoint = math.floor(math.min(dungeon.checkpoint or 0, packet.MaxWave) / every) * every
            if checkpoint < every then checkpoint = nil end
        end
        pending.sent = true
        general:Fire({Event = mode.event, Action = "Reset", Check = checkpoint})
        dungeonStatus.Text = "Replay solicitado: " .. mode.id .. " · " .. price .. " " .. currency .. "."
    end
    state.voteWaveRestart = replay
    for _, mode in ipairs(modes) do
        local subscription = require(storage.BridgeNet2).ReferenceBridge(mode.bridge):Connect(function(packet)
            if not alive or type(packet) ~= "table" then return end
            if packet.Event == "ResetInfinite" then
                local reached = tonumber(packet.MaxWave)
                if (mode.id == "desert" or mode.id == "infcastle") and reached and reached == reached and reached > 0 and reached <= 1000000 then
                    dungeon.waveBest = dungeon.waveBest or {}
                    if reached > (dungeon.waveBest[mode.id] or 0) then dungeon.waveBest[mode.id] = math.floor(reached) save() end
                end
                if state.replayBlocked then state.replayBlocked[mode.id] = nil end
                state.finishedMode = mode.id
                pending = {mode = mode, packet = packet, deadline = os.clock() + 20}
                replay()
            elseif packet.Event == "ResetInfiniteEnd" or packet.Event == "Reseted" then
                if state.replayBlocked then state.replayBlocked[mode.id] = nil end
                if state.finishedMode == mode.id then state.finishedMode = nil end
                if pending and pending.mode == mode then pending = nil end
            end
        end)
        table.insert(cleanupCallbacks, function() subscription:Disconnect() end)
    end
end
for _, name in ipairs(require(storage.Indexer.TimeTrialInfo).Order) do table.insert(trialDifficulties, {id = name, name = name}) end
