do -- Keep Auto Execute helpers scoped; do not retain top-level registers.
local function setAutoExecute(enabled)
    local wasEnabled = autoExecute
    autoExecute = enabled == true
    local session = env.__AriseAutoSession
    if not autoExecute then
        local success, problem = save()
        if not success then autoExecute = wasEnabled return false, problem end
        if session and session.connection then session.connection:Disconnect() end
        env.__AriseAutoSession = nil
        state.autoExecuteReady,state.autoExecuteProblem,state.autoExecuteRetryAt=false,nil,nil
        return true
    end
    local success, problem = pcall(function()
        local savedOK, savedProblem = save()
        assert(savedOK, savedProblem)
        assert(type(readfile) == "function", "Executor sem arquivos locais")
        assert(type(readfile("VykronHub/Hub.luau")) == "string", "Execute o instalador atualizado")
        local start = assert(loadstring(readfile("VykronHub/AutoExecute.luau")))
        session = assert(start(player.UserId, false), "Executor sem continuidade por teleporte")
        -- Cached sessions may have failed their first queue call; arm them again.
        if not session.queued and type(session.arm)=="function" then session.arm() end
        assert(session.queued, session.problem or "Falha ao preparar Auto Execute")
        session.beforeTeleport = savePositions
    end)
    state.autoExecuteReady=success
    state.autoExecuteProblem=not success and tostring(problem) or nil
    state.autoExecuteRetryAt=not success and os.clock()+5 or nil
    -- A transport/setup failure is not a user request to disable the preference.
    return success, problem
end
local function autoExecuteCaption(success,problem)
    local language=uiState.language
    if not autoExecute then return language=="PT" and "Desligado. Não reabre no próximo teleporte."
        or language=="ES" and "Desactivado. No abre tras el próximo teletransporte."
        or "Off. Will not reopen after the next teleport." end
    if success then return language=="PT" and "Ativo. Continuidade por teleporte preparada."
        or language=="ES" and "Activo. Continuidad por teletransporte preparada."
        or "Enabled. Teleport continuity is ready." end
    return (language=="PT" and "Opção ligada; nova tentativa automática em 5s: "
        or language=="ES" and "Opción activa; nuevo intento automático en 5s: "
        or "Preference enabled; retrying automatically in 5s: ")..tostring(problem)
end

table.sort(keyChoices, function(a, b) return a.name < b.name end)
connectUI(autoExecuteToggle, function()
    local success, problem = setAutoExecute(not autoExecute)
    autoExecuteStatus.Text = autoExecuteCaption(success,problem)
    refreshMisc()
end)
if autoExecute then
    local success, problem = setAutoExecute(true)
    autoExecuteStatus.Text = autoExecuteCaption(success,problem)
    refreshMisc()
end
-- One retry worker per runtime; independent of gameplay pause and UI visibility.
task.spawn(function()
    while alive do
        task.wait(5)
        if not alive then break end
        if autoExecute and not state.resetting then
            local session=env.__AriseAutoSession
            if (state.autoExecuteProblem or not session or not session.queued)
                and os.clock()>=(state.autoExecuteRetryAt or 0) then
                local success,problem=setAutoExecute(true)
                autoExecuteStatus.Text=autoExecuteCaption(success,problem)
                refreshMisc()
            end
        end
    end
end)
end -- Auto Execute preference and retry scope
-- Layout selector: same chooser and style as the other Misc actions.
