        choose("Trocar layout", {{id = "NewHub", name = "Vertical Hub"}, {id = "Horizontal", name = "Horizontal (PC / Mobile)"},
            {id = "Compact", name = "Compacta"}}, function(id)
            state.switchLayout(id)
            state.refreshLayoutLabel()
