-- FACTORY RESET: only this account's hub profile is reset; license files are untouched.
do
    local resetButton = state.controlButton("RestoreHubDefaults", "Restaurar hub ao padrão", miscPage)
    local resetStatus = state.controlLabel("RestoreDefaultsStatus", "Desliga as automações e restaura posição, tamanho e preferências desta conta. Clique duas vezes para confirmar.", miscPage)
    local confirmUntil = 0
    function state.restoreDefaults()
        if state.resetting then return false, "Restauração já em andamento." end
        -- Read and compile before touching the profile, so a missing restart path leaves preferences intact.
        local auth = env.__VykronHubLicense
        local licensed = auth ~= nil and type(auth.isValid) == "function" and auth:isValid()
        local restartPath = licensed and "VykronHub/Loader.luau" or "VykronHub/Hub.luau"
        local readOK, source = pcall(readfile, restartPath)
        if not readOK or type(source) ~= "string" or source == "" then return false, "Reinício indisponível. Execute o instalador atualizado." end
        if not licensed and source:find('error("Abra pelo loader com uma key valida")', 1, true) then
            return false, "Abra pelo loader com uma key válida antes de restaurar."
        end
        local compiled, runner = pcall(loadstring, source, "VykronHubRestore")
        if not compiled or type(runner) ~= "function" then return false, "Falha ao preparar o reinício. Configurações preservadas." end
        local oldOK, oldProfile = pcall(readfile, profilePath)
        local fastPath="VykronHub/FastClick-"..player.UserId..".json"
        local fastOK,oldFast=pcall(readfile,fastPath)
        local fastDefaults=Http:JSONEncode({version=1,userId=player.UserId,enabled=false,speed=4})
        local encoded = Http:JSONEncode({userId = player.UserId})
        state.resetting = true
        local written, failure = pcall(function()
            if oldOK and type(oldProfile) == "string" then writefile(profilePath .. ".reset-backup.json", oldProfile) end
            writefile(profilePath, encoded)
            assert(readfile(profilePath) == encoded, "Profile reset could not be verified")
            if fastOK and type(oldFast)=="string" then
                writefile(fastPath..".reset-backup.json",oldFast)
                writefile(fastPath,fastDefaults)
                assert(readfile(fastPath)==fastDefaults,"Fast Click reset could not be verified")
            end
        end)
        if not written then
            if oldOK and type(oldProfile) == "string" then pcall(writefile, profilePath, oldProfile) end
            if fastOK and type(oldFast)=="string" then pcall(writefile,fastPath,oldFast) end
            state.resetting = nil
            return false, "Não foi possível restaurar o arquivo de configurações. Tente novamente."
        end
        -- Queued teleport bootstrap checks the profile; turning this session off prevents rearming.
        autoExecute = false
        local session = env.__AriseAutoSession
        if session and session.connection then pcall(function() session.connection:Disconnect() end) end
        env.__AriseAutoSession = nil
        local oldHub = env.__VykronHub
        pcall(destroy)
        if gui.Parent then gui:Destroy() end
        if env.__VykronHub == oldHub then env.__VykronHub = nil end
        task.defer(function()
            -- The licensed loader reuses the saved key through its normal validation, never bypassing it.
            local started, problem = pcall(runner, licensed)
            if not started then warn("[VykronHub] Reset complete; restart failed. Execute the loader again: " .. tostring(problem)) end
        end)
        return true
    end
    connectUI(resetButton, function()
        if state.resetting then return end
        local now = os.clock()
        if now >= confirmUntil then
            confirmUntil = now + 8
            resetButton.Text = "Confirmar restauração"
            resetStatus.Text = "Clique novamente em até 8 segundos. Sua key e seu tempo de acesso serão mantidos."
            task.delay(8, function()
                if alive and not state.resetting and os.clock() >= confirmUntil then
                    resetButton.Text = "Restaurar hub ao padrão"
                    resetStatus.Text = "Restauração cancelada. Configurações preservadas."
                end
            end)
            return
        end
        confirmUntil = 0
        local ok, problem = state.restoreDefaults()
        if not ok and alive then
            resetButton.Text = "Restaurar hub ao padrão"
            resetStatus.Text = problem
        end
    end)
end
-- END FACTORY RESET

local function dungeonMode(config)
    for _, mode in ipairs(dungeonModes) do if mode.id == (config or dungeon).mode then return mode end end
    return dungeonModes[1]
end
-- AUTO ISLAND KEYS: native recipes containing an island dungeon rune only.
do
    local catalog = require(storage.Indexer.KeyDungeons)
    local recipes = require(storage.Indexer.Recipes)
    local releases = require(shared.Release)
    local calendar = require(shared.Calendar)
    local choices = {}
    for _, recipe in pairs(recipes) do
        local output = type(recipe) == "table" and recipe.Craft
        local id = type(output) == "table" and output.Name
        local rune = false
        for material in pairs(type(recipe) == "table" and type(recipe.Items) == "table" and recipe.Items or {}) do
            if type(material) == "string" and material:match("^Dg.+Rune$") then rune = true end
        end
        if rune and output.Type == "Items" and catalog[id] and itemsInfo[id] then
            table.insert(choices, {id=id, order=tonumber(recipe.Order) or 100000,
                release=recipe.Release or catalog[id].Release, native=catalog[id]})
        end
    end
    table.sort(choices,function(a,b) if a.order~=b.order then return a.order<b.order end return a.id<b.id end)
    function state.pickIslandKey(options, current, stock, allowed)
        for _, option in ipairs(options) do
            if option.id == current and stock(option.id)>0 and allowed(option) then return current end
        end
        for _, option in ipairs(options) do
            if stock(option.id)>0 and allowed(option) then return option.id end
        end
    end
    function state.autoIslandKey(current)
        if not nativeGameData then return nil end
        return state.pickIslandKey(choices,current,function(id)
            return tonumber(nativeGameData.GetItemAmount(id)) or 0
        end,function(option)
            return option.native.CantOpen~=true and (not option.release or releases.IsOpen(option.release))
                and (not option.native.Season or calendar.SeasonOpen(option.native.Season))
        end)
    end
    function state.currentIslandKeyStock()
        -- Missing/unloaded inventory is unknown, never evidence of exhaustion.
        if player.GameplayPaused or player:GetAttribute("Loaded")==false then return nil end
        local items=clientData.Get("Inventory","Items")
        if type(items)~="table" or not catalog[dungeon.key] then return nil end
        local item=items[dungeon.key]
        if item==nil then return 0 end
        local amount=tonumber(type(item)=="table" and item.Amount or item)
        if not amount or amount~=amount or amount<0 or amount==math.huge then return nil end
        return amount
    end
    function state.keyRestartActive()
        local pending=state.nativeRestartPending
        if pending and pending.mode=="key" and pending.sent and pending.intent~="leave" and not pending.refused then return true end
        local message=tostring(storage:GetAttribute("DungeonMessage") or ""):lower()
        return message:find("restart",1,true)~=nil or message:find("reinici",1,true)~=nil
    end
    function state.keyStockExhausted(now)
        local remaining=state.currentIslandKeyStock()
        local sample=state.keyEmptySample
        if remaining==nil or remaining>0 or state.keyRestartActive() then state.keyEmptySample=nil return false end
        if not sample or sample.key~=dungeon.key then
            state.keyEmptySample={key=dungeon.key,at=now}
            return false
        end
        return now-sample.at>=3
    end
    function state.autoKeysNeedExit()
        return dungeon.enabled and dungeon.mode=="key" and dungeon.autoKeys
            and state.keyStockExhausted(os.clock())
    end
    function state.autoKeysCanReplay()
        local count=state.currentIslandKeyStock()
        return count~=nil and count>0
    end
    function state.keyReplayNeedsReturn(now)
        if not dungeon.enabled or not dungeon.autoKeys or dungeon.mode~="key" or not insideDungeon() then state.keyReplayWait=nil;return false end
        local completed=storage:GetAttribute("DungeonCompleted")==true or state.finishedMode=="key"
        if not completed then state.keyReplayWait=nil;return false end
        local room=storage:GetAttribute("CurrentRoom")
        local pending=state.nativeRestartPending
        local wait=state.keyReplayWait
        if not wait or wait.room~=room then wait={room=room,at=now};state.keyReplayWait=wait end
        if pending and pending.mode=="key" then
            if pending.refused or pending.intent=="leave" then return true end
            if pending.sent then return now-(pending.requestedAt or wait.at)>=45 end
            if not pending.closed and now<=(pending.deadline or 0) then return false end
        end
        return now-wait.at>=15
    end
    function state.keyRunBlocksExit()
        local quest=autoQuest.journey
        if state.recurringQuestPolicy.enabled(autoQuest) and state.recurringQuestPolicy.validJourney(quest) and quest.phase=="inside" then return false end
        if dungeon.mode~="key" or not insideDungeon() then return false end
        if state.keyReplayNeedsReturn(os.clock()) then return false end
        if not dungeon.autoLeave and not (dungeon.enabled and dungeon.autoKeys) then return true end
        if state.keyRestartActive() then return true end
        if storage:GetAttribute("DungeonCompleted")~=true and state.finishedMode~="key" then return true end
        return not state.keyStockExhausted(os.clock())
    end
    function state.requestDungeonExit()
        if state.keyRunBlocksExit() then return false end
        general:Fire({Event = "LeaveDungeon"})
        return true
    end
    function state.autoKeysStockText()
        if dungeon.mode~="key" or not dungeon.autoKeys or not nativeGameData then return nil end
        local total=0
        for _, option in ipairs(choices) do
            total+=math.max(0,tonumber(nativeGameData.GetItemAmount(option.id)) or 0)
        end
        local current=state.currentIslandKeyStock()
        current=current==nil and "?" or tostring(current)
        local name=itemsInfo[dungeon.key] and itemsInfo[dungeon.key].Name or dungeon.key
        local prefix=uiState.language=="PT" and "Estoque: " or uiState.language=="ES" and "Existencias: " or "Stock: "
        return "Auto Keys · "..tostring(name).." · "..prefix..current.." · Total: "..total
    end
end
-- FUTURE RAID ENTRY: native release gates and keys, including server overrides.
do
    local releaseRules = require(shared.Release)
    function state.raidKeyOptions(mode)
        local options = {}
        for index, id in ipairs(mode.keys or {}) do
            local info = itemsInfo[id]
            local owned = tonumber(nativeGameData and nativeGameData.GetItemAmount(id)) or 0
            local difficulty = ({"Normal", "Hard", "Nightmare", "Destruction"})[index]
            table.insert(options, {id = id, name = (mode.keyLabel == "item" and (info and info.Name or id) or difficulty) .. " · " .. owned})
        end
        return options
    end
    function state.raidCanEnter(mode, config)
        config=config or dungeon
        if not mode.keys then return true end
        if mode.minRank and (tonumber(clientData.Get("Rank")) or 0) < mode.minRank then
            return false, mode.minRankMessage
        end
        if not releaseRules.IsOpen(mode.release) then
            return false, "Aguardando liberação: " .. mode.name .. " · " .. releaseRules.Format(releaseRules.TimeLeft(mode.release))
        end
        if not table.find(mode.keys, config.key) then return false, "Escolha a chave ou dificuldade deste modo." end
        if not nativeGameData or nativeGameData.GetItemAmount(config.key) < 1 then return false, "Você não possui a chave ou passe selecionado." end
        return true
    end
end
-- END FUTURE RAID ENTRY
local function unlockedCastle(mode)
    local stat = mode.id == "heavenly" and "MaxHeavenFloor" or "MaxCastleFloor"
    local best = tonumber(clientData.Get("GeneralStats", stat)) or 0
    if best <= 0 then
        -- Recorde não encontrado no nome conhecido: procura a estatística do castelo pelo nome em GeneralStats.
        local stats = clientData.Get("GeneralStats")
        local token = mode.id == "heavenly" and "heaven" or "castle"
        if type(stats) == "table" then
            for key, value in pairs(stats) do
                local name, number = string.lower(tostring(key)), tonumber(value)
                if number and number == number and number > best and number <= 1000000 and name:find(token, 1, true)
                    and (name:find("floor", 1, true) or name:find("room", 1, true))
                    and (mode.id == "heavenly" or (not name:find("heaven", 1, true) and not name:find("infinite", 1, true)))
                    and not name:find("total", 1, true) and not name:find("count", 1, true) then
                    best = number
                end
            end
        end
    end
    return castleCheckpoints(best), best
end
-- WAVE CHECKPOINTS: Deserto/Castelo Infinito listam só waves já informadas pelo jogo como alcançadas.
local function waveListed(mode) return mode.id == "desert" or mode.id == "infcastle" end
-- Recorde salvo na conta: primeiro um campo da própria configuração nativa do modo que aponte para
-- uma estatística de GeneralStats; senão, a estatística de GeneralStats cujo nome identifica o modo.
-- A fonte encontrada aparece na dica da Dungeon para conferência.
local unlockedWaves
do
local function accountRecord(waveConfig, accept)
    local stats = clientData.Get("GeneralStats")
    if type(stats) ~= "table" then return 0, nil end
    if type(waveConfig) == "table" then
        for _, value in pairs(waveConfig) do
            local number = type(value) == "string" and tonumber(stats[value])
            if number and number == number and number > 0 then return math.floor(number), value end
        end
    end
    local best, source = 0, nil
    for key, value in pairs(stats) do
        local name, number = string.lower(tostring(key)), tonumber(value)
        if number and number == number and number > best and number <= 1000000 and accept(name)
            and not name:find("total", 1, true) and not name:find("count", 1, true) and not name:find("kill", 1, true) then
            best, source = math.floor(number), tostring(key)
        end
    end
    return best, source
end
state.waveSource = {}
function unlockedWaves(mode)
    local ok, waveConfig = pcall(function()
        local ui = player.PlayerScripts:FindFirstChild("NewUI", true)
        return require(ui.Screens.Party.Config).MODES[mode.id].Wave
    end)
    waveConfig = ok and waveConfig or nil
    local record, source = accountRecord(waveConfig, function(name)
        if not (name:find("wave", 1, true) or name:find("floor", 1, true) or name:find("room", 1, true)) then return false end
        if mode.id == "desert" then
            return name:find("desert", 1, true) ~= nil or (name:find("infinite", 1, true) ~= nil and not name:find("castle", 1, true) and not name:find("lab", 1, true))
        end
        return (name:find("infcastle", 1, true) or (name:find("infinite", 1, true) and name:find("castle", 1, true))) ~= nil
    end)
    local learned = dungeon.waveBest and dungeon.waveBest[mode.id] or 0
    local best = math.max(record, learned)
    state.waveSource[mode.id] = record >= learned and record > 0 and ("GeneralStats." .. source) or learned > 0 and "fim de partida" or nil
    local options = {{id = 0, name = "Inicio  /  Wave 1"}}
    local every = type(waveConfig) == "table" and tonumber(waveConfig.Every) or nil
    if every and every >= 1 and best >= every then
        for wave = every, math.min(best, every * 200), every do
            table.insert(options, {id = wave, name = "Wave " .. wave .. "  /  Checkpoint"})
        end
    end
    return options, best, every
end
end
-- DUNGEON RUNES: native party slots and old-equipment protocol.
do
local function installDungeonRunes()
    local config = dungeon.runes
    local pending, replayRoom, replaySelection
    local nativeEquip
    local recovery={blocked={}}
    -- RUNE POLICY
    local function runePlan(settings, room, catalog, owned, previous)
        local reuse = settings.reuseLast and settings.replayPending
        if not settings.enabled and not reuse then return {ready = true} end
        if not room or type(room.Items) ~= "table" then return {message = "Runas: aguardando os espaços do grupo."} end
        local selected = {}
        if reuse and type(previous) == "table" then
            for key, id in pairs(previous) do selected[tostring(key)] = id end
        end
        if settings.enabled and type(settings.slots) == "table" then
            for key, id in pairs(settings.slots) do selected[tostring(key)] = id end
        elseif not reuse then selected = settings.slots end
        if type(selected) ~= "table" or (reuse and not settings.enabled and type(previous) ~= "table") then
            return {message = "Últimas runas indisponíveis. Configure os espaços."}
        end
        local capacity = #room.Items
        if capacity == 0 then
            for _, id in pairs(selected) do
                if id ~= "" then
                    local amount = owned(id)
                    if amount == nil then return {message = "Runas: aguardando inventário carregar."} end
                    if amount > 0 then return {message = "Runas: aguardando os espaços do grupo."} end
                end
            end
        end
        local wanted, missing = {}, 0
        for slot = 1, capacity do
            if settings.blocked and settings.blocked[slot] then continue end
            local id = selected[tostring(slot)]
            if id ~= nil then
                if type(id) ~= "string" or (id ~= "" and (not catalog[id] or catalog[id].Type ~= "DungeonItem")) then
                    return {message = "Runa selecionada indisponível no catálogo."}
                end
                wanted[slot] = id
            end
        end
        -- Remove conflicting reservations first, so moving a rune between slots returns its stock.
        for slot = 1, capacity do
            local current = room.Items[slot]
            if wanted[slot] ~= nil and current and current ~= "" and catalog[current] and current ~= wanted[slot] then
                return {action = "RemoveItems", slot = slot, message = "Runas: liberando espaço " .. slot .. "."}
            end
        end
        for slot = 1, capacity do
            local id = wanted[slot]
            if id and id ~= "" and room.Items[slot] ~= id then
                local amount = owned(id)
                if amount == nil then return {message = "Runas: aguardando inventário carregar."} end
                if amount > 0 then
                    return {action = "AddItems", slot = slot, item = id, message = "Runas: equipando espaço " .. slot .. "."}
                end
                missing += 1
            end
        end
        return {ready = true, message = missing > 0 and ("Runas sem estoque em " .. missing .. " espaço(s). Iniciando com as disponíveis.") or nil}
    end
    -- END RUNE POLICY
    local function nativeLast()
        if type(config.restoreLast) == "table" then return table.clone(config.restoreLast) end
        local infos = storage:FindFirstChild("__Infos")
        local old = infos and infos:FindFirstChild("__DungeonItens")
        local result = {}
        for key, id in pairs(old and old:GetAttributes() or {}) do
            local slot = tonumber(key)
            if slot and slot >= 1 and slot <= 9 and slot == math.floor(slot) and type(id) == "string" and id ~= "" then
                result[tostring(slot)] = id
            end
        end
        if next(result) then return result end
        if config.lastKnown then return table.clone(config.last) end
    end
    local function roomKey(room)
        return tostring(room.Leader) .. ":" .. tostring(room.DungeonID or "") .. ":" .. tostring(storage:GetAttribute("World"))
    end
    local function runeStock(id)
        local inventory = clientData.Get("Inventory", "Items")
        if type(inventory) ~= "table" then return nil end
        local entry = inventory[id]
        if entry == nil then return 0 end
        local amount = tonumber(type(entry) == "table" and entry.Amount or entry)
        if not amount or amount ~= amount or amount < 0 or amount == math.huge then return nil end
        return amount
    end
    -- NATIVE EQUIP LAST: invoke only the verified Party.Rooms callback, never Weekly/visual callbacks.
    local function cancelNativeEquip()
        if nativeEquip and nativeEquip.running and nativeEquip.thread then pcall(task.cancel, nativeEquip.thread) end
        nativeEquip = nil
    end
    state.cancelRuneWork = cancelNativeEquip
    local function nativeLastCallback()
        if type(getconnections) ~= "function" or not debug or type(debug.info) ~= "function" then return nil end
        local ok, callback = pcall(function()
            local pg = player:FindFirstChildOfClass("PlayerGui")
            local menus = pg and pg:FindFirstChild("Menus")
            local party = menus and menus:FindFirstChild("UI_Party")
            for _, button in ipairs(party and party:GetDescendants() or {}) do
                if not button:IsA("GuiButton") or button.Name ~= "btn" or not button.Active then continue end
                if not button:GetFullName():find(".pa_cols.leader.pa_start.pa_st_h.btn", 1, true) then continue end
                for _, connection in ipairs(getconnections(button.Activated)) do
                    local fn = connection.Function
                    if connection.Enabled ~= false and type(fn) == "function" then
                        local success, source = pcall(debug.info, fn, "s")
                        if success and tostring(source):find(".NewUI.Screens.Party.Rooms", 1, true) then return fn end
                    end
                end
            end
        end)
        if ok then return callback end
    end
    local function runNativeLast(room, previous)
        if type(config.restoreLast) == "table" then state.runeLastMethod = "quest-restore" return true end
        if nativeEquip then
            if nativeEquip.done then return true end
            if nativeEquip.running then
                if os.clock()-nativeEquip.at<10 then return false, "Acionando Equipar último do jogo..." end
                if nativeEquip.thread then pcall(task.cancel,nativeEquip.thread) end
                nativeEquip.running,nativeEquip.done=false,true
                state.runeLastMethod="native-timeout-fallback"
                return true
            end
            local confirmed = true
            for slot, id in pairs(nativeEquip.expected) do
                if room.Items[slot] ~= id then confirmed = false break end
            end
            if confirmed then nativeEquip.done = true return true end
            if os.clock() - (nativeEquip.finishedAt or nativeEquip.at) < 10 then
                return false, "Equipar último: aguardando confirmação do jogo."
            end
            nativeEquip.done = true
            state.runeLastMethod = "native-confirmation-fallback"
            return true
        end
        if type(room.Items) ~= "table" or #room.Items == 0 then return true end
        local infos = storage:FindFirstChild("__Infos")
        local old = infos and infos:FindFirstChild("__DungeonItens")
        local hasHistory = false
        for _, id in pairs(old and old:GetAttributes() or {}) do
            if type(id) == "string" and id ~= "" then hasHistory = true break end
        end
        if not hasHistory or type(previous) ~= "table" then
            state.runeLastMethod = "saved-history"
            return true
        end
        local expected, budget = {}, {}
        for slot = 1, #room.Items do
            local id = previous[tostring(slot)]
            if id and id ~= "" and itemsInfo[id] and room.Items[slot] ~= id then
                if budget[id] == nil then budget[id] = runeStock(id) end
                if budget[id] == nil then return false, "Runas: aguardando inventário carregar." end
                if budget[id] > 0 then expected[slot], budget[id] = id, budget[id] - 1 end
            end
        end
        if not next(expected) then state.runeLastMethod = "already-equipped-or-no-stock" return true end
        local callback = nativeLastCallback()
        if not callback then state.runeLastMethod = "manual-fallback" return true end
        local context = {at = os.clock(), expected = expected, running = true}
        nativeEquip, state.runeLastMethod = context, "native-button"
        context.thread = task.spawn(function()
            local success, problem = pcall(callback)
            if nativeEquip ~= context then return end
            context.running, context.finishedAt = false, os.clock()
            if not success then
                context.done, context.problem = true, tostring(problem)
                state.runeLastMethod = "native-error-fallback"
            end
        end)
        return false, "Acionando Equipar último do jogo..."
    end
    -- END NATIVE EQUIP LAST
    -- A quest run overrides only the party equipment, never the user's saved switches/selection.
    function state.questRuneJob()
        local job = autoQuest.enabled and autoQuest.scope == "all" and autoQuest.journey
        if job and not job.bucket and job.mode == "portal" then return job end
    end
    local function prepareQuestRune(room, job)
        cancelNativeEquip()
        if state.panic then return false, "Pânico ativo: automações pausadas." end
        if not room or room.Leader ~= player.UserId or type(room.Items) ~= "table" then
            return false, "Runas: somente o líder pode configurar o grupo."
        end
        if room.Locked then return false, "Runas: grupo iniciando; aguardando confirmação." end
        local info = itemsInfo[job.rune]
        local rule = info and info.Dungeon
        if job.rune and (not rule or rule.Type ~= "WorldRune" or rule.World ~= job.map) then
            return false, "Missão: runa não corresponde à ilha exigida."
        end
        if #room.Items == 0 then return false, "Runas: aguardando os espaços do grupo." end
        if config.restoreLast == nil then
            config.restoreLast = nativeLast() or {}
            if not save() then config.restoreLast = nil return false, "Não foi possível salvar as runas. Início adiado." end
        end
        local target = {}
        for slot = 1, #room.Items do target[tostring(slot)] = slot == 1 and job.rune or "" end
        local key = roomKey(room) .. ":quest:" .. tostring(job.rune or "native")
        if replayRoom ~= key then pending, replayRoom, replaySelection = nil, key, nil end
        if pending then
            local current = room.Items[pending.slot]
            local confirmed = pending.action == "AddItems" and current == pending.item
                or pending.action == "RemoveItems" and current ~= pending.before
            if confirmed then pending = nil
            elseif os.clock() - pending.at < 5 then return false, "Missão: aguardando confirmação da runa equipada."
            else
                if (pending.attempts or 1) >= 3 then return false, "Missão: equipamento sem confirmação; início suspenso." end
                pending.at, pending.attempts = os.clock(), (pending.attempts or 1) + 1
                general:Fire({Event = "DungeonAction", Action = pending.action, Dungeon = room.Leader, Slot = pending.slot, Item = pending.item})
                return false, "Missão: aguardando confirmação da runa equipada."
            end
        end
        local result = runePlan({enabled = true, slots = target}, room, itemsInfo, runeStock)
        if result.ready then
            if job.rune and room.Items[1] ~= job.rune then return false, "Missão: sem estoque da runa necessária; início suspenso." end
            state.runeWarning = nil
            return true
        end
        if not result.action then return false, result.message end
        pending = {at = os.clock(), attempts = 1, action = result.action, slot = result.slot, item = result.item, before = room.Items[result.slot]}
        general:Fire({Event = "DungeonAction", Action = result.action, Dungeon = room.Leader, Slot = result.slot, Item = result.item})
        return false, "Missão: equipando uma runa da ilha exigida."
    end

    function state.prepareDungeonRunes(room)
        local questJob = state.questRuneJob()
        if questJob then recovery={blocked={}};return prepareQuestRune(room, questJob) end
        if state.panic then return false, "Pânico ativo: automações pausadas." end
        local reuse = false -- Automatic reuse of the previous loadout was removed.
        if not config.enabled and not reuse then cancelNativeEquip() pending = nil recovery={blocked={}} state.runeWarning = nil return true end
        if not room or room.Leader ~= player.UserId then return false, "Runas: somente o líder pode configurar o grupo." end
        if room.Locked then return false, "Runas: grupo iniciando; aguardando confirmação." end
        if player.GameplayPaused or not rootPart() then return false, "Runas: aguardando personagem." end
        local key = roomKey(room)
        if replayRoom ~= key then cancelNativeEquip() pending, replayRoom, replaySelection = nil, key, nil end
        if reuse and not replaySelection then replaySelection = nativeLast() end
        local selection={key,tostring(config.enabled),tostring(reuse)}
        for slot=1,9 do
            selection[#selection+1]=tostring(config.slots and config.slots[tostring(slot)])
            selection[#selection+1]=tostring(replaySelection and replaySelection[tostring(slot)])
        end
        local signature=table.concat(selection,"|")
        if recovery.signature~=signature then
            recovery={signature=signature,blocked={}}
            pending=nil
        end
        for slot,entry in pairs(recovery.blocked) do
            local current=room.Items and room.Items[slot]
            if entry.action=="AddItems" and current==entry.item
                or entry.action=="RemoveItems" and current~=entry.before then recovery.blocked[slot]=nil end
        end
        if pending then
            local current = room.Items and room.Items[pending.slot]
            local confirmed = pending.action == "AddItems" and current == pending.item
                or pending.action == "RemoveItems" and current ~= pending.before
            if confirmed then pending = nil
            elseif os.clock() - pending.at < 8 then
                return false, "Runas: aguardando confirmação do espaço " .. pending.slot .. "."
            else
                local remaining = pending.action == "AddItems" and runeStock(pending.item) or nil
                if pending.action == "AddItems" and remaining == nil then return false, "Runas: aguardando inventário carregar." end
                if pending.action == "AddItems" and remaining == 0 then
                    pending = nil
                else
                    if (pending.attempts or 1) >= 3 then
                        recovery.blocked[pending.slot]=pending
                        pending=nil
                    else
                        pending.attempts=(pending.attempts or 1)+1
                        pending.at=os.clock()
                        general:Fire({Event = "DungeonAction", Action = pending.action, Dungeon = room.Leader, Slot = pending.slot, Item = pending.item})
                        return false, "Runas: aguardando confirmação do espaço " .. pending.slot .. "."
                    end
                end
            end
        end
        if reuse then
            local equipped, message = runNativeLast(room, replaySelection)
            if not equipped then return false, message end
        end
        local result = runePlan({enabled = config.enabled, reuseLast = reuse, replayPending = reuse, slots = config.slots, blocked=recovery.blocked},
            room, itemsInfo, runeStock, replaySelection)
        if result.ready then
            pending=nil
            local skipped={}
            for slot=1,9 do
                local entry=recovery.blocked[slot]
                if entry then skipped[#skipped+1]=tostring(slot).." ("..tostring(entry.item or entry.before or "RemoveItems")..")" end
            end
            local warning=#skipped>0 and (
                uiState.language=="EN" and "Runes: starting with confirmed slots. Unconfirmed this run: "
                or uiState.language=="ES" and "Runas: iniciando con espacios confirmados. Sin confirmar en esta partida: "
                or "Runas: iniciando com os espaços confirmados. Sem confirmação nesta partida: ")..table.concat(skipped,", ") or nil
            state.runeWarning=warning or result.message
            return true
        end
        if not result.action then return false, result.message end
        pending = {at = os.clock(), attempts = 1, action = result.action, slot = result.slot, item = result.item, before = room.Items[result.slot]}
        general:Fire({Event = "DungeonAction", Action = result.action, Dungeon = room.Leader, Slot = result.slot, Item = result.item})
        return false, result.message
    end
    function state.rememberDungeonRunes(room)
        if state.questRuneJob() then
            if not room or not room.Items or (state.questRuneJob().rune and room.Items[1] ~= state.questRuneJob().rune) then return false, "Missão: aguardando confirmação da runa equipada." end
            pending, replayRoom, replaySelection = nil, nil, nil
            return true
        end
        if not room or room.Leader ~= player.UserId or type(room.Items) ~= "table" then return false, "Runas: aguardando dados do grupo." end
        if not config.enabled then return true end
        local last = {}
        for slot, id in ipairs(room.Items) do last[tostring(slot)] = itemsInfo[id] and id or "" end
        local before, known, replay = config.last, config.lastKnown, config.replayPending
        config.last, config.lastKnown, config.replayPending = last, true, false
        if not save() then
            config.last, config.lastKnown, config.replayPending = before, known, replay
            return false, "Não foi possível salvar as runas. Início adiado."
        end
        config.restoreLast = nil
        save()
        recovery={blocked={}}
        cancelNativeEquip() pending, replayRoom, replaySelection = nil, nil, nil
        return true
    end
    local ui = {}
    state.runesUI = ui
    -- Controles "sem visual" da janela antiga (escondida): só o que o código e a interface nova leem/acionam.
    ui.shortcut = state.controlCard("DungeonRunesShortcut", dungeonPage)
    ui.caption = state.controlLabel("DungeonRunesCaption", "", ui.shortcut)
    local open = state.controlButton("DungeonRunesOpen", "Configurar  ›", ui.shortcut)
    ui.panel = make("Frame", {Name = "DungeonRunesSettings", Visible = false}, window)
    local equip = state.controlRow("Auto Equipar Runas", "Confirma os espaços antes de iniciar pelo Auto Dungeon.", ui.panel)
    local copyOld = state.controlButton("CopyLastRunes", "Copiar últimas para seleção", ui.panel)
    local status = state.controlLabel("DungeonRunesStatus", "", ui.panel)
    equip.Name = "AutoEquipRunes"
    config.reuseLast=false
    local list = make("ScrollingFrame", {Name = "DungeonRuneSlots"}, ui.panel)
    local rowConnections, lastCount, lastConfirmed = {}, nil, nil
    local render
    -- RUNE CAPACITY: automatic nine-slot setup; server capacity alone controls equipment.
    local function countSlots()
        local room = partyClient.GetRoom("DungeonAction")
        if room and type(room.Items) == "table" then return math.max(9, #room.Items), #room.Items end
        return 9, nil
    end
    -- END RUNE CAPACITY
    local function options(selected)
        local result = {{id = "", name = "Sem runa"}}
        local entries = {}
        for id, info in pairs(itemsInfo) do
            if info.Type == "DungeonItem" then
                local owned = tonumber(nativeGameData and nativeGameData.GetItemAmount(id)) or 0
                if owned > 0 or id == selected then table.insert(entries, {id = id, name = (info.Name or id) .. " · " .. owned, image = info.Image}) end
            end
        end
        table.sort(entries, function(a, b) return a.name < b.name end)
        for _, entry in ipairs(entries) do table.insert(result, entry) end
        return result
    end
    render = function()
        for _, c in ipairs(rowConnections) do c:Disconnect() end
        table.clear(rowConnections)
        list:ClearAllChildren()
        local count, confirmed = countSlots()
        lastCount, lastConfirmed = count, confirmed
        status.Text = confirmed and ("Espaços liberados pelo grupo: " .. confirmed .. " · ajuste automático.")
            or "Configure até 9 runas. A quantidade equipada será automática."
        if confirmed and count > confirmed then status.Text ..= "\nEspaços extras aguardam capacidade do grupo." end
        for slot = 1, count do
            local key = tostring(slot)
            local id = config.slots[key]
            local info = id and itemsInfo[id]
            -- A interface nova ordena as linhas por posição (Y) e lê: arte (ImageLabel), botão do espaço (TextButton) e descrição (TextLabel que não é "—")
            local row = make("Frame", {Position = UDim2.fromOffset(2, (slot - 1) * 98)}, list)
            local image = info and type(info.Image) == "string" and info.Image or ""
            make("ImageLabel", {Name = "RuneArtwork", Image = image}, row)
            if image == "" then make("TextLabel", {Text = "—"}, row) end
            local pick = make("TextButton", {Text = "Espaço " .. slot .. " · " .. (info and info.Name or "Sem runa") .. (confirmed and slot > confirmed and " · planejado" or "")}, row)
            make("TextLabel", {Text = info and info.Desc or "Selecione uma runa do inventário."}, row)
            connectUI(pick, function()
                choose("Runa do espaço " .. slot, options(config.slots[key]), function(chosen)
                    config.slots[key] = chosen
                    cancelNativeEquip() pending, replayRoom, replaySelection = nil, nil, nil
                    save() render()
                end)
            end, nil, rowConnections)
        end
        toggleLook(equip, config.enabled)
    end
    connectUI(open, function() ui.panel.Visible = true render() end)
    connectUI(equip, function()
        config.enabled = not config.enabled cancelNativeEquip() pending, replayRoom, replaySelection = nil, nil, nil save() render()
    end)
    connectUI(copyOld, function()
        local previous = nativeLast()
        if not previous then status.Text = "Últimas runas indisponíveis. Configure os espaços." return end
        config.slots = table.clone(previous)
        cancelNativeEquip() pending, replayRoom, replaySelection = nil, nil, nil
        save() render()
    end)
    function state.refreshDungeonRunes(mode)
        ui.shortcut.Visible = mode.id == "portal"
        if mode.id ~= "portal" then ui.panel.Visible = false end
        ui.caption.Text = config.enabled and "Auto Equipar ativo." or "Auto Equipar desligado."
    end
    table.insert(cleanupCallbacks, function() cancelNativeEquip() for _, c in ipairs(rowConnections) do c:Disconnect() end end)
    task.spawn(function()
        while alive do
            task.wait(1)
            if not alive then break end
            if state.panic then continue end
            if ui.panel.Visible then
                local ok, problem = pcall(function()
                    local count, confirmed = countSlots()
                    if count ~= lastCount or confirmed ~= lastConfirmed then render() end
                    toggleLook(equip, config.enabled)
                end)
                if not ok then status.Text = "Runas: " .. tostring(problem) end
            end
        end
    end)
end
installDungeonRunes()
end
-- END DUNGEON RUNES
-- Key worker is scoped to dungeon instances; UI timers never emit input.
do
state.teamSwitchCycle=state.newTeamSwitchCycle()
function state.resetTeamSwitch() state.teamSwitchCycle=state.newTeamSwitchCycle();state.teamSwitchError=nil end
function state.sendTeamSwitchKey(name)
    if not state.teamSwitchKeys[name] then return false,state.utilityText("Tecla inválida.") end
    local ok,input=pcall(game.GetService,game,"VirtualInputManager")
    if not ok or not input then return false,state.utilityText("O executor não permite simular teclas.") end
    local down,problem=pcall(input.SendKeyEvent,input,true,Enum.KeyCode[name],false,game)
    if down then task.wait(0.05) end
    local released,releaseProblem=pcall(input.SendKeyEvent,input,false,Enum.KeyCode[name],false,game)
    return down and released,not down and tostring(problem) or not released and tostring(releaseProblem) or nil
end
task.spawn(function()
    while alive do
        task.wait(0.1)
        if not alive then break end
        if state.refillTeams and state.refillTeams.owns() then state.resetTeamSwitch();continue end
        local u=dungeon.utilities;local root=rootPart()
        local human=root and root.Parent:FindFirstChildOfClass("Humanoid")
        local ready=not state.panic and not state.stopped and not state.autoLeaving and not state.raidPaused
            and not state.eventTravel and not state.eventDestination and not player.GameplayPaused
            and human and human.Health>0 and os.clock()>=(state.entryUntil or 0) and Input:GetFocusedTextBox()==nil
        local key=state.stepTeamSwitch(state.teamSwitchCycle,os.clock(),u.switchTeams,insideDungeon(),ready,u)
        if key then
            if u.keyA==u.keyB then u.switchTeams=false;state.teamSwitchError=state.utilityText("Escolha teclas diferentes para A e B.")
            else
                local ok,problem=state.sendTeamSwitchKey(key)
                if not ok then u.switchTeams=false;state.teamSwitchError=state.utilityText("Falha ao trocar equipe: %s",tostring(problem)) end
            end
        end
    end
end)
end
local function refreshDungeon()
    local mode = dungeonMode()
    if mode.keys and not table.find(mode.keys, dungeon.key) then dungeon.key = dungeon.raidKeys[mode.id] or mode.keys[1] end
    toggleLook(dungeonToggle, dungeon.enabled)
    local selectedCard = modeCards:FindFirstChild(mode.id)
    state.dungeonUI.summary.Artwork.Image = selectedCard and selectedCard.Artwork.Image or ""
    state.dungeonUI.summary.ModeTitle.Text = mode.name
    state.dungeonUI.summary.ModeCaption.Text = mode.kind == "castle" and "Andares e checkpoints"
        or mode.kind == "wave" and "Ondas e checkpoints"
        or mode.kind == "difficulty" and "Selecione a dificuldade"
        or mode.kind == "key" and "Escolha sua chave ou passe" or "Entrada automática no modo"
    if mode.keys then
        local ok, permitted, reason = pcall(state.raidCanEnter, mode)
        if ok and not permitted then state.dungeonUI.summary.ModeCaption.Text = reason end
    end
    for _, item in ipairs(modeCards:GetChildren()) do
        if item:IsA("TextButton") then
            local selected = item.Name == mode.id
            item.SelectionBadge.Visible = selected
        end
    end
    local hasDiff, hasKey = mode.kind == "difficulty", mode.kind == "key"
    difficultyLabel.Visible, difficultyButton.Visible = hasDiff or hasKey, hasDiff or hasKey
    difficultyLabel.Text = hasKey and "CHAVE / PASSE" or "DIFICULDADE"
    difficultyButton.Text = hasKey and (itemsInfo[dungeon.key] and itemsInfo[dungeon.key].Name or "Selecionar chave...") or dungeon.difficulty
    if mode.id=="key" and dungeon.autoKeys then difficultyButton.Text="Auto Keys" end
    if mode.gate then
        difficultyLabel.Text = "ESCOLHA AUTOMÁTICA ENTRE SALAS"
        difficultyButton.Text = "Automático: " .. (dungeon.trickChoice or "Treat") .. "   · Alterar"
    end
    local hasCheck = mode.kind == "castle" or mode.kind == "wave"
    local listed = mode.kind == "castle" or waveListed(mode)
    checkpointField.Visible, checkpointLabel.Visible = mode.kind == "wave" and not listed, hasCheck
    checkpointButton.Visible = listed
    checkpointField.Text = tostring(dungeon.checkpoint)
    checkpointLabel.Text = mode.kind == "castle" and "ANDAR INICIAL  /  SOMENTE LIBERADOS"
        or listed and "WAVE INICIAL  /  SOMENTE LIBERADAS" or "Checkpoint inicial  /  0 = inicio"
    if mode.kind == "castle" then
        checkpointButton.Text = dungeon.checkpoint == 0 and "Inicio  /  Andar 1   v" or "Andar " .. dungeon.checkpoint .. "   v"
    else
        checkpointButton.Text = dungeon.checkpoint == 0 and "Inicio  /  Wave 1   v" or "Wave " .. dungeon.checkpoint .. "   v"
    end
    repeatGemsToggle.Title.Text = "Auto Replay"
    toggleLook(repeatGemsToggle, dungeon.repeatGems == true)
    repeatGemsToggle.Caption.Text = (mode.id == "portal" or mode.kind == "castle") and "Repete usando gemas após sair ou concluir." or "Reentra quando o modo permitir."
    if mode.kind == "wave" or mode.id == "bossrush" then repeatGemsToggle.Caption.Text = "Reinicia ao terminar; usa Tickets ou fragmentos do Labirinto." end
    if mode.id == "trial" then repeatGemsToggle.Caption.Text = "Vota para reiniciar na sala 1 quando a rodada terminar." end
    if mode.id == "hospital" then repeatGemsToggle.Caption.Text = "Aciona o replay nativo do Hospital após concluir." end
    if mode.keys or mode.gate or mode.entryWorld then repeatGemsToggle.Caption.Text = "Usa PLAY AGAIN ao concluir; mantém o custo de entrada do jogo." end
    if mode.id == "portal" then repeatGemsToggle.Caption.Text = "Usa RUN AGAIN quando disponível; o jogo verifica gratuidade ou 15 Tickets." end
    toggleLook(state.autoLeaveToggle, dungeon.autoLeave)
    trialPreview.Visible = mode.id == "trial"
    if not trialPreview.Visible then trialSettings.Visible = false end
    state.refreshDungeonRunes(mode)
    dungeonHint.Text = hasKey and "Selecione uma chave que voce possui. A ativacao no pedestal dentro da instancia ainda e manual."
        or hasCheck and "Usa apenas checkpoints ja liberados. Configure velocidade e saida na aba Misc."
        or "Auto Dungeon combate automaticamente dentro da partida."
    if mode.id=="key" and dungeon.autoKeys then
        dungeonHint.Text="Auto Keys: repeat the current key until empty, then leave and select the next. No keys: wait in the normal world."
    end
    if mode.keys then dungeonHint.Text = "Auto Dungeon inclui proteção de raid. Entrada e áreas de ataque aguardam validação no jogo." end
    if mode.gate then dungeonHint.Text = "Exige Trick or Treat Pass (reutilizável). Treat: baú/Mimic. Trick: elite com loot dobrado." end
    if waveListed(mode) then
        local _, best = unlockedWaves(mode)
        if best <= 0 then
            dungeonHint.Text = "A lista de waves aparece após a primeira partida neste modo com a hub (o jogo informa a wave máxima ao final)."
        else
            dungeonHint.Text = "Waves liberadas: " .. best .. " · fonte: " .. tostring(state.waveSource[mode.id])
        end
    end
    if not dungeon.enabled then dungeonStatus.Text = "Auto Dungeon desligado." end
    if state.refreshModeSelection then state.refreshModeSelection() end
end
connectUI(checkpointButton, function()
    local mode = dungeonMode()
    if waveListed(mode) then
        local options, best = unlockedWaves(mode)
        choose("Waves liberadas  /  " .. best, options, function(wave)
