connectUI(difficultyButton, function()
    local mode = dungeonMode()
    if mode.gate then
        choose("Escolha automática entre salas", {{id = "Treat", name = "Auto Treat · Baú (pode ser Mimic)"}, {id = "Trick", name = "Auto Trick · Elite com loot dobrado"}}, function(id)
            dungeon.trickChoice = id
