            dungeon.key = id
            if mode.keys then dungeon.raidKeys[mode.id] = id end
        else dungeon.difficulty = id end
        save() refreshDungeon()
    end)
end)
local nextRequest = os.clock() + 5
state.entryPace = {initialUntil = nextRequest, retryAt = 0}
do
    local sequence = dungeon.entrySequence
    if sequence and sequence.mode == dungeon.mode and sequence.world == tonumber(storage:GetAttribute("World"))
        and sequence.expires > workspace:GetServerTimeNow() then
        nextRequest, state.entryPace.initialUntil = 0, 0
    end
    dungeon.entrySequence = nil
end
-- ENTRY PACING: only the first action waits; confirmed stage changes are immediate.
function state.entryReady(action, now)
    local pace = state.entryPace
    if not action or now < pace.initialUntil then return false end
    return action ~= pace.lastAction or now >= pace.retryAt
end
function state.entrySent(action, now)
    state.entryPace.lastAction, state.entryPace.retryAt = action, now + 5
end
function state.entryWait(action, now)
    local pace = state.entryPace
    return math.max(0, math.ceil(math.max(pace.initialUntil, action == pace.lastAction and pace.retryAt or 0) - now))
end
-- END ENTRY PACING
-- Cancel lobby membership only after the user turns Auto Dungeon off.
do
    local api={lastEvent=nil,pending=nil}
    state.dungeonPartyCleanup=api
    local function questOwns(event)
        local request=questRuntime.modeRequest
        return autoQuest.enabled and (autoQuest.scope=="all" or autoQuest.scope=="recurring") and request
            and dungeonMode(request).event==event
    end
    function api.note(event)
        api.lastEvent=event
    end
    function api.cancel()
        if insideDungeon() then api.pending=nil;return end
        local now=os.clock()
        local pending={untilAt=now+20,deadline=now+120,events={}}
        for _,mode in ipairs(dungeonModes) do
            if not pending.events[mode.event] and not questOwns(mode.event) then
                local ok,room=pcall(partyClient.GetRoom,mode.event)
                if room or not ok or mode.event==dungeonMode().event or mode.event==api.lastEvent then
                    pending.events[mode.event]={nextAt=now,attempts=0}
                end
            end
        end
        api.pending=pending
        dungeon.entrySequence=nil
        state.modeEntryDestination=nil
        state.entryPending=nil
        state.entryUntil=0
    end
    function api.step()
        local pending=api.pending
        if not pending then return false end
        if dungeon.enabled or insideDungeon() or not alive then api.pending=nil;return false end
        if state.panic or player.GameplayPaused then return true end
        local now=os.clock()
        if now>=pending.deadline then
            api.pending=nil
            dungeonStatus.Text=state.utilityText("Auto Dungeon off: party exit unconfirmed. Toggle on/off to retry.")
            return false
        end
        local waiting=false
        for event,entry in pairs(pending.events) do
            if entry.done or questOwns(event) then continue end
            local ok,room=pcall(partyClient.GetRoom,event)
            if not ok then waiting=true;continue end
            if not room then
                if entry.seen then entry.done=true end
                continue
            end
            local signature=tostring(room.Leader)..":"..tostring(room.DungeonID)..":"..tostring(room.DungeonKey)
            -- Do not abandon a different group joined manually after the original one left.
            if entry.signature and signature~=entry.signature then entry.done=true;continue end
            entry.signature=signature
            entry.seen=true
            waiting=true
            if room.Locked==true then
                dungeonStatus.Text=state.utilityText("Auto Dungeon off: party locked for teleport; waiting for release.")
                continue
            end
            if now>=entry.nextAt then
                entry.attempts+=1
                entry.nextAt=now+(entry.attempts>=3 and 15 or 5)
                local sent,problem=pcall(function()
                    general:Fire({Event=event,Action="Leave",Dungeon=room.Leader})
                end)
                dungeonStatus.Text=sent and state.utilityText("Auto Dungeon off: leaving dungeon party...")
                    or state.utilityText("Party exit failed: %s",tostring(problem))
            end
        end
        if not waiting and now>=pending.untilAt then
            api.pending=nil
            dungeonStatus.Text=state.utilityText("Auto Dungeon off: no dungeon party.")
            return false
        end
        return true
    end
end

local lastEntrySignature
connectUI(dungeonToggle, function()
    dungeon.enabled = not dungeon.enabled
    state.target, state.map, state.searchPosition = nil, nil, nil
    generation += 1
    if dungeon.enabled then
        nextRequest = os.clock() + 5 lastEntrySignature = nil
        state.entryPace = {initialUntil = nextRequest, retryAt = 0}
    else
        state.dungeonPartyCleanup.cancel()
    end
    save()
    if state.rift and state.rift.testPersist then state.rift.testPersist() end
    refreshDungeon() refresh()
end)
connectUI(checkpointField, function()
    local number = tonumber(checkpointField.Text)
    if number and number == number and number >= 0 and number <= 1000000 then dungeon.checkpoint = math.floor(number) save() end
    refreshDungeon()
end, checkpointField.FocusLost)
refreshDungeon()
connect(dungeonStatus:GetPropertyChangedSignal("Text"), function()
    dungeonToggle.Caption.Text = dungeonStatus.Text
end)
-- AUTO LEAVE: only native completion flags or end-of-run offers permit exit.
do
    local replayModes = {portal = true, infernal = true, heavenly = true, trial = true, desert = true, infcastle = true, labyrinth = true, bossrush = true, hospital = true, manor = true, trickortreat = true, key = true, architect = true, dragon = true, eclipse = true}
    local waveModes = {trial = true, desert = true, infcastle = true, labyrinth = true, bossrush = true}
    function state.questOwnsRun(mode)
        local job = autoQuest.journey
        return autoQuest.enabled == true and (autoQuest.scope == "all" or autoQuest.scope == "recurring") and type(job) == "table"
            and (job.enterRequested == true or job.phase == "inside") and job.mode == mode
            and (mode == "portal" or mode == "ranktest" or state.recurringQuestPolicy.validJourney(job))
            and (not job.bucket or state.recurringRunMatches and state.recurringRunMatches(job))
    end
    function state.replayInFlight(mode)
        local pending = state.nativeRestartPending
        if pending and pending.mode == mode and pending.sent and pending.intent ~= "leave" and not pending.refused then return true end
        return mode == "portal" and dungeon.gemResetPending ~= nil
    end
    -- REPLAY EXIT GUARD: wait for the native offer and its restart countdown before fallback exit.
    function state.waitingForReplay(mode)
        local pending = state.nativeRestartPending
        if pending and pending.mode == mode and not pending.refused and pending.intent ~= "leave" then
            if pending.sent then return true end
            if not pending.closed and os.clock() <= (pending.deadline or 0) then return true end
        end
        local entry = state.entryPending
        return type(entry) == "table" and entry.inside == true and entry.completed == true
            and os.clock() < (state.entryUntil or 0)
    end
    function state.resolveFiniteDungeon(room)
        if type(room) == "table" and room.DungeonID ~= nil then return "portal" end
        return state.nativeFiniteMode or (dungeon.mode == "ranktest" and "ranktest" or "portal")
    end
    do
        local subscription = require(storage.BridgeNet2).ReferenceBridge("DUNGEON_EVENT"):Connect(function(packet)
            if not alive or type(packet) ~= "table" then return end
            if packet.Event == "StartTest" then state.nativeFiniteMode = "ranktest"
            elseif packet.Event == "StartedInstance" and type(packet.DungeonInfo) == "table" then
                state.nativeFiniteMode = "portal"
            end
        end)
        table.insert(cleanupCallbacks, function() subscription:Disconnect() end)
    end
    function state.shouldAutoLeave(mode, finished, replayExpired)
        if mode=="trial" and state.questTrialRefillPending and state.questTrialRefillPending() then return false end
        if state.questOwnsRun(mode) then return finished==true end
        if mode=="key" then
            if not finished then return false end
            if state.keyReplayNeedsReturn(os.clock()) then return true end
            if state.keyRestartActive() then return false end
            if dungeon.enabled and dungeon.autoKeys then return state.autoKeysNeedExit() end
            -- Disabling Auto Leave must also disable its key-dungeon fallback.
            return dungeon.autoLeave==true and state.keyStockExhausted(os.clock())
        end
        if finished == true and state.collectionPriority() ~= nil then return true end
        if state.questOwnsRun(mode) then return finished == true end
        if autoQuest.enabled and (autoQuest.scope == "all" or autoQuest.scope == "recurring") and autoQuest.journey then return false end
        local blocked = state.replayBlocked and state.replayBlocked[mode]
        if state.replayAllowed() and replayModes[mode] and not blocked
            and (state.replayInFlight(mode) or state.waitingForReplay(mode)) then return false end
        return dungeon.autoLeave == true and finished == true and (blocked or replayExpired or not (state.replayAllowed() and replayModes[mode] == true)) == true
    end
    local function currentMode()
        if state.rift.inRun() then return "rift" end
        local job = autoQuest.journey
        if job and state.questOwnsRun(job.mode) then return job.mode end
        if state.nativeRestartPending then return state.nativeRestartPending.mode end
        for _, entry in ipairs({{"InTimeTrial", "trial"}, {"InBossRush", "bossrush"}, {"InRush", "bossrush"},
            {"IsHeavenCastle", "heavenly"}, {"IsCastle", "infernal"}, {"InInfiniteMode", "desert"}, {"InInfinite", "desert"},
            {"InInfiniteCastle", "infcastle"}, {"InInfiniteC", "infcastle"}, {"InInfiniteLabyrinth", "labyrinth"}, {"InInfiniteL", "labyrinth"}, {"HLRaid", "hospital"}}) do
            if storage:GetAttribute(entry[1]) == true then return entry[2] end
        end
        for _, raid in ipairs(dungeonModes) do if raid.map and raid.map == storage:GetAttribute("DungeonMap") then return raid.id end end
        if storage:GetAttribute("DungeonMap") == "DarkDungeon" then
            return state.resolveFiniteDungeon(partyClient.GetRoom("DungeonAction"))
        end
        if state.trickGateWorld() then return "trickortreat" end
        return dungeon.mode
    end
    task.spawn(function()
        local endedAt, completedAt, lastRequest, attempts, lastMode = nil, nil, -math.huge, 0, nil
        while alive do
            task.wait(0.5)
            if not alive then break end
            if state.panic then continue end
            if not insideDungeon() then
                state.autoLeaving, state.finishedMode, state.replayBlocked = nil, nil, nil
                state.nativeFiniteMode = nil
                endedAt, completedAt, lastRequest, attempts, lastMode = nil, nil, -math.huge, 0, nil
                continue
            end
            local mode = currentMode()
            if lastMode ~= mode then endedAt, completedAt, lastRequest, attempts, lastMode = nil, nil, -math.huge, 0, mode end
            local finished = (not waveModes[mode] and storage:GetAttribute("DungeonCompleted") == true) or state.finishedMode == mode
            if mode=="key" and state.keyReplayNeedsReturn(os.clock()) then
                state.nativeRestartPending=nil
            end
            if finished then completedAt = completedAt or os.clock() else completedAt = nil end
            if state.keyRunBlocksExit() or not state.shouldAutoLeave(mode, finished, completedAt ~= nil and os.clock() - completedAt >= 25) then
                state.autoLeaving, endedAt, attempts = nil, nil, 0
                continue
            end
            state.autoLeaving = true
            if state.target then generation += 1 end
            state.target, state.searchPosition = nil, nil
            endedAt = endedAt or os.clock()
            if os.clock() - endedAt < 2 then dungeonStatus.Text = "Partida concluída. Preparando saída automática..." continue end
            local questExit = state.questOwnsRun(mode)
            if player.GameplayPaused or (not questExit and not rootPart()) then continue end
            if not questExit and attempts >= 3 then dungeonStatus.Text = "Auto Leave: saída sem confirmação. Confira a tela do jogo." continue end
            local interval = questExit and math.min(30, 5 * math.max(1, attempts)) or 5
            if os.clock() - lastRequest >= interval then
                lastRequest, attempts = os.clock(), attempts + 1
                local ok, problem = pcall(function()
                    if not state.nativeExitAfterRun or not state.nativeExitAfterRun(mode) then state.requestDungeonExit() end
                end)
                dungeonStatus.Text = ok and "Auto Leave: solicitando saída após o término..." or "Falha ao sair: " .. tostring(problem)
            end
        end
    end)
end
-- END AUTO LEAVE
-- NATIVE END CARDS: Dungeon RunAgain and Raid Vote use the same approved Auto Replay switch.
do
    local function modeFor(packet)
        local job=autoQuest.journey
        if job and job.bucket and state.questOwnsRun and state.questOwnsRun(job.mode) then return job.mode end
        if packet.Mode == "Dungeon" then return "portal" end
        local map = storage:GetAttribute("DungeonMap")
        for _, mode in ipairs(dungeonModes) do if mode.map and mode.map == map then return mode.id end end
        if state.trickGateWorld() then return "trickortreat" end
        return dungeon.mode
    end
    local function send(index, pending)
        general:Fire({Event = pending.nativeMode == "Dungeon" and "DungeonAction" or "RaidAction",
            Action = pending.nativeMode == "Dungeon" and "RunAgain" or "Vote", Index = index})
    end
    local function choiceId(choice)
        local buff=type(choice)=="table" and choice.Buff
        return type(buff)=="table" and buff.Id or type(choice)=="table" and choice.Id
    end
    local function choiceIndex(pending,action)
        if pending.nativeMode~="Dungeon" then return action=="leave" and 2 or 1 end
        local wanted=action=="leave" and "Leave" or "RunAgain"
        for index,choice in ipairs(pending.choices) do if choiceId(choice)==wanted then return index end end
    end
    function state.nativeRestartStep()
        local pending = state.nativeRestartPending
        if state.panic or not pending then return end
        if not insideDungeon() then state.nativeRestartPending = nil return end
        local room = storage:GetAttribute("CurrentRoom")
        local completed = storage:GetAttribute("DungeonCompleted")
        if completed == true then pending.observedCompleted = true end
        if (room ~= pending.room or (pending.sent and pending.closed and pending.observedCompleted and completed == false)) and completed ~= true then
            if state.finishedMode == pending.mode then state.finishedMode = nil end
            state.nativeRestartPending = nil
            return
        end
        if pending.sent or pending.closed or os.clock() > pending.deadline then return end
        local refillReplay=pending.mode=="trial" and state.questTrialRefillPending and state.questTrialRefillPending()
        if not state.replayAllowed() or state.questOwnsRun(pending.mode) and not refillReplay or state.autoLeaving or player.GameplayPaused then return end
        local index=choiceIndex(pending,"replay")
        if not pending.canVote or not index or not pending.choices[index] then return end
        -- The native offer/handler validates free entry, Tickets and raid keys. It is
        -- sent once; the older paid reset worker stays blocked for this end-of-run offer.
        pending.sent, pending.intent, pending.requestedAt = true, "replay", os.clock()
        send(index, pending)
        state.entryPending = {inside = true, root = rootPart(), room = room, completed = storage:GetAttribute("DungeonCompleted") == true}
        state.entryUntil = os.clock() + 15
        dungeonStatus.Text = "Replay nativo solicitado; aguardando confirmação do jogo."
    end
    function state.nativeExitAfterRun(mode)
        if state.keyRunBlocksExit() then return false end
        local pending = state.nativeRestartPending
        local index=pending and choiceIndex(pending,"leave")
        if state.panic or not pending or pending.mode ~= mode or not pending.canVote
            or not index or not pending.choices[index] or pending.sent or pending.closed or os.clock() > pending.deadline then return false end
        pending.sent, pending.intent = true, "leave"
        send(index, pending)
        return true
    end
    local subscription = require(storage.BridgeNet2).ReferenceBridge("TRIAL_EVENT"):Connect(function(packet)
        if not alive or type(packet) ~= "table" then return end
        if packet.Event == "ShowBuffSelection" and packet.Kind == "Restart"
            and (packet.Mode == "Dungeon" or packet.Mode == "Raid") then
            local previous = state.nativeRestartPending
            if previous and previous.nativeMode == packet.Mode and previous.room == storage:GetAttribute("CurrentRoom")
                and os.clock() < previous.deadline and not previous.closed then return end
            local mode = modeFor(packet)
            if state.replayBlocked then state.replayBlocked[mode] = nil end
            state.finishedMode = mode
            state.nativeRestartPending = {nativeMode = packet.Mode, mode = mode, room = storage:GetAttribute("CurrentRoom"),
                deadline = os.clock() + math.clamp(tonumber(packet.Time) or 15, 1, 180), choices = type(packet.Choices) == "table" and packet.Choices or {},
                observedCompleted = storage:GetAttribute("DungeonCompleted") == true,
                canVote = type(packet.Voters) == "table" and table.find(packet.Voters, player.UserId) ~= nil}
            if state.replayAllowed() and not state.questOwnsRun(mode) then state.autoLeaving = nil end
        elseif packet.Event == "BuffAutoVote" and state.nativeRestartPending then
            state.nativeRestartPending.sent = true
            state.nativeRestartPending.intent = packet.Index == 2 and "leave" or "replay"
        elseif packet.Event == "VoteRefused" and state.nativeRestartPending then
            -- A refused request may concern cost/eligibility. Do not repeat a paid request.
            state.nativeRestartPending.closed, state.nativeRestartPending.refused = true, true
            state.replayBlocked = state.replayBlocked or {}
            state.replayBlocked[state.nativeRestartPending.mode] = true
            dungeonStatus.Text = "Replay recusado pelo jogo; confira custo e requisitos."
        elseif (packet.Event == "BuffChosen" or packet.Event == "CloseBuffSelection") and state.nativeRestartPending
            and (not packet.Mode or packet.Mode == state.nativeRestartPending.nativeMode) then
            state.nativeRestartPending.closed = true
            local pending=state.nativeRestartPending
            local selected=pending.choices[tonumber(packet.Index)]
            if packet.Event == "BuffChosen" and (packet.Again == false
                or pending.nativeMode=="Dungeon" and choiceId(selected)=="Leave"
                or pending.nativeMode~="Dungeon" and packet.Index==2) then
                state.nativeRestartPending.intent = "leave"
            end
        end
    end)
    table.insert(cleanupCallbacks, function() subscription:Disconnect() end)
    state.voteNativeRestart = state.nativeRestartStep
    task.spawn(function()
        while alive do
            task.wait(0.5)
            if not alive then break end
            if state.panic then continue end
            local ok = pcall(state.nativeRestartStep)
            if not ok then dungeonStatus.Text = "Replay nativo aguardando dados do jogo." end
        end
    end)
end
-- END NATIVE END CARDS

-- GEAR TOMES AND LIMIT BREAK: native inventory, cap and item-use protocol.
do
    local config = state.gearTomes
    local extra = require(shared.ExtraFunctions)
    local limitBreak, loadAt = nil, 0
    function state.limitBreakText()
        if not limitBreak and os.clock() >= loadAt then
            loadAt = os.clock() + 10
            local module = storage.Indexer:FindFirstChild("LimitBreak")
            if module then local ok, value = pcall(require, module) if ok then limitBreak = value end end
        end
        if not limitBreak then return "Limit Break: aguardando dados nativos." end
        local ok, level, _, _, fraction = pcall(limitBreak.Progress, clientData.Get("Level"), clientData.Get("Rebirths"),
            clientData.Get("GeneralStats", "LimitBreak"), clientData.Get("LimitBreak", "Exp"))
        if not ok then return "Limit Break: aguardando dados nativos." end
        if level == nil then return "Limit Break: exige nível e rebirth máximos." end
        return "Limit Break: " .. tostring(level) .. " · " .. string.format("%.1f%%", math.clamp(fraction or 0, 0, 1) * 100)
    end
    local function stock()
        local items = clientData.Get("Inventory", "Items")
        if type(items) ~= "table" then return nil end
        local item = items.GearTome
        return tonumber(type(item) == "table" and item.Amount or item) or 0
    end
    local function eligibleGear()
        local equips = clientData.Get("Equips", "Acessorys")
        local inventory = clientData.Get("Inventory", "Acessorys")
        if type(equips) ~= "table" or type(inventory) ~= "table" then return nil end
        for _, id in pairs(equips) do
            local item = inventory[id]
            if type(item) == "table" then
                local needed = extra.AccMaxExp(player, tonumber(item.Level) or 0)
                if type(needed) == "number" and needed > 0 then return true end
            end
        end
        return false
    end
    local nextUse, attempts = 0, 0
    local observedPending, pendingSince, lastStock, stableSince
    local submitting = false
    local function observePending(owned)
        local now = os.clock()
        if config.pending ~= observedPending then
            observedPending, pendingSince = config.pending, now
            lastStock, stableSince = owned, now
        elseif owned ~= lastStock then
            lastStock, stableSince = owned, now
        end
    end
    local function clearPending(owned, outcome)
        local pending, previous = config.pending, config.lastUnconfirmed
        if not pending then return true end
        submitting = true
        config.pending = nil
        if outcome ~= "confirmed" then
            config.lastUnconfirmed = {before = pending.before, attempts = pending.attempts or 1}
        end
        local saved = save()
        if not saved then config.pending, config.lastUnconfirmed = pending, previous end
        submitting = false
        if saved then observePending(owned) end
        return saved
    end
    function state.gearTomeRecoveryReady()
        local owned = stock()
        observePending(owned)
        return not submitting and config.pending ~= nil and owned ~= nil
            and os.clock() - pendingSince >= 30
    end
    function state.recoverGearTomeUse(expected)
        if config.pending ~= expected or not state.gearTomeRecoveryReady() then return false end
        if not clearPending(stock(), "manual-review") then return false end
        attempts, nextUse = 0, os.clock() + 3
        state.gearTomeUseTurn = config.enabled == true
        return true
    end
    -- Pause replenishment while a use is outstanding, so stock deltas stay observable.
    if type(clientData.OnChange) == "function" then
        local connection = clientData.OnChange({"Inventory", "Items"}, function()
            if not alive or submitting then return end
            local owned = stock()
            if config.pending and owned and owned < config.pending.before then
                if clearPending(owned, "confirmed") then attempts = 0 end
            end
        end)
        if connection and type(connection.Disconnect) == "function" then table.insert(connections, connection) end
    end
    function state.gearTomeStep()
        if submitting then return end
        state.gearTomeUseTurn = config.enabled == true
        if state.panic then return end
        state.limitBreakStatus = state.limitBreakText()
        local owned = stock()
        if owned == nil then state.gearTomeStatus = "Gear Tome: aguardando inventário." return end
        observePending(owned)
        if config.pending then
            if owned < config.pending.before then
                if not clearPending(owned, "confirmed") then
                    state.gearTomeStatus = "Gear Tome: falha ao salvar; uso adiado." return
                end
                attempts = 0
            else
                local pending = config.pending
                local age = os.clock() - pendingSince
                local quiet = os.clock() - stableSince
                attempts = math.clamp(tonumber(pending.attempts) or 1, 1, 3)
                if config.enabled and age >= 30 * attempts and quiet >= 3 and attempts < 3
                    and not state.gearTomePurchasePending(autoBuy) then
                    if not clearPending(owned, "unconfirmed") then
                        state.gearTomeStatus = "Gear Tome: falha ao salvar; uso adiado." return
                    end
                    nextUse = os.clock() + 3
                    state.gearTomeStatus = "Gear Tome: aguardando nova tentativa." return
                end
                state.gearTomeStatus = attempts >= 3
                    and "Gear Tome: uso sem confirmação; revise o uso pendente."
                    or "Gear Tome: aguardando confirmação; nova tentativa programada."
                return
            end
        end
        if not config.enabled then state.gearTomeUseTurn = false state.gearTomeStatus = "Gear Tome: desligado." return end
        if player.GameplayPaused or not rootPart() then return end
        local eligible = eligibleGear()
        if eligible == nil then state.gearTomeUseTurn = false state.gearTomeStatus = "Gear Tome: aguardando equipamentos." return end
        if not eligible then state.gearTomeUseTurn = false state.gearTomeStatus = "Gear Tome: equipe gear abaixo do nível máximo." return end
        local amount = state.gearTomeAmount(owned, config.reserve, config.amount, eligible)
        if amount <= 0 then state.gearTomeUseTurn = false state.gearTomeStatus = "Gear Tome: aguardando estoque acima da reserva." return end
        if state.gearTomePurchasePending(autoBuy) then
            state.gearTomeStatus = "Gear Tome: aguardando confirmação da compra antes de usar." return
        end
        if os.clock() < nextUse then
            state.gearTomeStatus = "Gear Tome: aguardando intervalo de uso." return
        end
        local receipt = {before = owned, attempts = attempts + 1}
        submitting = true
        config.pending = receipt
        if not save() then
            config.pending = nil
            submitting = false
            state.gearTomeStatus = "Gear Tome: falha ao salvar; uso adiado." return
        end
        if state.panic or not config.enabled or stock() ~= owned then
            submitting = false
            clearPending(stock(), "cancelled-before-send")
            return
        end
        observePending(owned)
        nextUse = os.clock() + 3
        local ok, problem = pcall(general.Fire, general,
            {Event = "UseItem", Action = "Use", Name = "GearTome", Amount = amount})
        submitting = false
        state.gearTomeStatus = ok and "Gear Tome: uso solicitado; aguardando confirmação."
            or ("Gear Tome: " .. tostring(problem))
    end
    task.spawn(function()
        clientData.WaitForLoaded()
        while alive do
            task.wait(1)
            if not alive then break end
            if state.panic then continue end
            local ok, problem = pcall(state.gearTomeStep)
            if not ok then state.gearTomeStatus = "Gear Tome: " .. tostring(problem) end
        end
    end)
end
-- END GEAR TOMES AND LIMIT BREAK
-- Modo: trickortreat. Logica de entrada pelo portao de Pumpkin Hollow (Pass, gate, retorno ao mundo de origem).
-- Antes isto ficava no controlador comum (eventos/hospital-replay.lua) atras de `if mode.gate`. Agora o controlador pergunta ao modo:
-- state.modeHooks[mode.id].entryStep(mode, inside) -> true encerra a volta atual (era o `continue`), false segue para o proximo passo.
-- entryReset() zera o estado do portao quando a partida muda de contexto. O estado (gateUsed/gateAttemptAt) mora so aqui.
do
    local gateUsed, gateAttemptAt = false, nil
    state.modeHooks.trickortreat = {
        entryReset = function() gateUsed = false end,
        entryStep = function(mode, inside)
            if not inside and nativeGameData.GetItemAmount(mode.key) < 1 then
                dungeonStatus.Text = "Você precisa do Trick or Treat Pass, obtido em Pumpkin Hollow."
                return true
            end
            if inside and state.trickGateWorld()
                and storage:GetAttribute("DungeonCompleted") == true then
                local back = storage:GetAttribute("BackWorld")
                if type(back) == "string" and back:match("^World[123]$") and os.clock() >= nextRequest and rootPart() and not player.GameplayPaused then
                    if save() then
                        nextRequest = os.clock() + 15
                        general:Fire({Event = "WorldTeleport", World = back})
                    end
                end
                dungeonStatus.Text = "Trick or Treat concluído. Retornando ao mundo de origem..."
                return true
            end
            if gateUsed and not inside and gateAttemptAt and os.clock() - gateAttemptAt >= 5
                and not partyClient.GetRoom(mode.event) then gateUsed, gateAttemptAt = false, nil end
            if not inside and not gateUsed then
                if type(state.firePrompt) ~= "function" then
                    dungeonStatus.Text = "Trick or Treat: " .. state.translate("Interação de proximidade indisponível.")
                    return true
                end
                if not rootPart() or player.GameplayPaused then
                    dungeonStatus.Text = "Aguardando personagem..."
                    return true
                end
                local main = workspace:FindFirstChild("__Main")
                local world = main and main:FindFirstChild("__World")
                local gate, prompt
                for _, item in ipairs(world and world:GetDescendants() or {}) do
                    if item:IsA("ProximityPrompt") and item.Enabled and (item.Name == "TrickOrTreatGate"
                        or (item.ObjectText or ""):lower():find("trick or treat", 1, true)
                        or item:FindFirstAncestor("TrickOrTreatGate")) then
                        local part = item.Parent
                        if part and part:IsA("Attachment") then part = part.Parent end
                        if not part or not part:IsA("BasePart") then continue end
                        gate, prompt = part, item
                        break
                    end
                end
                local root = rootPart()
                if gate and gate:IsA("BasePart") and prompt and prompt.Enabled and root and type(state.firePrompt) == "function" then
                    if not state.entryReady("gate:trickortreat", os.clock()) then dungeonStatus.Text = "Gate retry in " .. state.entryWait("gate:trickortreat", os.clock()) .. "s…" return true end
                    if (root.Position - gate.Position).Magnitude > math.max(1, prompt.MaxActivationDistance - 2) then
                        state.modeEntryDestination = gate.Position + Vector3.new(0, 3, 3)
                        dungeonStatus.Text = "Indo ao Trick or Treat Gate em Pumpkin Hollow..."
                    else
                        state.modeEntryDestination, gateUsed = nil, false
                        gateAttemptAt = os.clock()
                        state.entrySent("gate:trickortreat", os.clock())
                        task.spawn(function()
                            local ok = pcall(state.firePrompt, prompt, math.max(prompt.HoldDuration, 0.1))
                            gateUsed = ok
                        end)
                        dungeonStatus.Text = "Gate interaction requested. Waiting for entry confirmation…"
                        nextRequest = os.clock() + 5
                    end
                    return true
                end
                local extra = workspace:FindFirstChild("__Extra")
                local spawns = extra and extra:FindFirstChild("__Spawns")
                local spawn = spawns and spawns:FindFirstChild("HLWorld")
                if spawn and root then
                    if state.entryReady("island:HLWorld", os.clock()) then
                        state.entrySent("island:HLWorld", os.clock())
                        nextRequest = os.clock() + 5
                        if (root.Position - spawn:GetPivot().Position).Magnitude > 65 then
                            general:Fire({Event = "IslandTeleport", Island = "HLWorld"})
                        end
                        local destination = spawn:GetPivot().Position
                        task.spawn(function() pcall(function() player:RequestStreamAroundAsync(destination, 3) end) end)
                    end
                    dungeonStatus.Text = "Mundo " .. tostring(storage:GetAttribute("World")) .. ": aguardando o gate em Pumpkin Hollow carregar..."
                    return true
                end
                dungeonStatus.Text = "Aguardando Pumpkin Hollow e seu gate no mundo atual..."
                return true
            end
            return false
        end,
    }
end
-- END MODO TRICKORTREAT (LOGICA)
-- Native Island Rift entry and end-of-run flow. All requests are server-validated.
do
    local api=state.rift
    local levels,release,maps
    local pending
    local function tr(pt,en,es) return uiState.language=="PT" and pt or uiState.language=="ES" and es or en end
    api.text=tr
    local function load()
        levels=levels or require(storage.Indexer:WaitForChild("IslandLevels"))
        release=release or require(shared.Release)
        maps=maps or require(storage.Indexer.MapInfo)
        assert(type(levels.Islands)=="function" and type(levels.Best)=="function" and type(levels.MaxStart)=="function","IslandLevels unavailable")
        return levels
    end
    function api.context()
        local native=load()
        local root=rootPart()
        local extra=workspace:FindFirstChild("__Extra")
        local radars=extra and extra:FindFirstChild("Radars")
        if not root or not radars then return nil,tr("Aguardando a ilha atual.","Waiting for the current island.","Esperando la isla actual.") end
        local selected,distance,key
        for id,island in pairs(native.Islands()) do
            local radar=radars:FindFirstChild(id)
            if radar and radar:IsA("BasePart") and island.World==tonumber(storage:GetAttribute("World")) and release.IsOpen(island.Release) then
                local d=(radar.Position-root.Position).Magnitude
                if not distance or d<distance then selected,distance,key=island,d,id end
            end
        end
        if not selected then return nil,tr("Nenhuma ilha liberada encontrada.","No unlocked island found.","No hay isla desbloqueada.") end
        local seasons=clientData.Get("Seasons")
        if type(seasons)~="table" then return nil,tr("Aguardando progresso da conta.","Waiting for account progress.","Esperando progreso de la cuenta.") end
        local best=native.Best({Seasons=seasons},selected)
        local choices=api.levels(best,native.MaxStart(best))
        if not choices then return nil,"Island Rift: invalid native level data." end
        return {key=key,island=selected,best=best,levels=choices}
    end
    function api.catalog()
        local native=load()
        local seasons=clientData.Get("Seasons")
        if type(seasons)~="table" then return nil,"Waiting for account progress." end
        local rank=tonumber(clientData.Get("Rank")) or 0
        local rows={}
        for key,island in pairs(native.Islands()) do
            local required=({0,7,20})[island.World]
            local unlocked=required~=nil and rank>=required and release.IsOpen(island.Release)
            rows[#rows+1]={key=key,name=island.Name,order=island.Order,world=island.World,
                best=native.Best({Seasons=seasons},island),island=island,unlocked=unlocked,
                image=maps[key] and maps[key].Image or ""}
        end
        table.sort(rows,function(a,b) return a.order==b.order and a.key<b.key or a.order<b.order end)
        return rows
    end
    function api.planRoute()
        local catalog,reason=api.catalog()
        if not catalog then return nil,reason end
        return api.routePlan(dungeon.rift,catalog)
    end
    local function routeStatus(phase,message,current)
        api.route=api.route or {}
        api.route.phase,api.route.status,api.route.current=phase,message,current
        dungeonStatus.Text=message
    end
    function api.prepareContinuation(phase)
        if not autoExecute then return false,tr("Ative Auto Execute em Misc para continuar a rota.","Enable Auto Execute in Misc to continue the route.","Activa Auto Execute en Misc para continuar la ruta.") end
        if not save() then return false,"Island Rift: could not save the route." end
        local ok,session=pcall(function()
            return assert(loadstring(readfile("VykronHub/AutoExecute.luau")))(player.UserId,false)
        end)
        if not ok or type(session)~="table" or not session.queued then return false,"Island Rift: teleport continuation unavailable." end
        if api.testContinuation then
            local armed,reason=api.testContinuation(phase)
            if not armed then return false,reason end
        end
        return true
    end
    function api.routeStep(context)
        local plan,reason=api.planRoute()
        if not plan then routeStatus("waiting",reason);return true end
        if plan.total==0 then routeStatus("selection",tr("Selecione as ilhas da rota.","Select route islands.","Selecciona las islas de la ruta."));return true end
        if plan.done then routeStatus("done",tr("Rota concluída: todas as ilhas atingiram a meta.","Route complete: all islands reached the target.","Ruta completada: todas las islas alcanzaron la meta."));return true end
        local selected=plan.next
        if not selected.unlocked then routeStatus("locked",tr("Ilha bloqueada: ","Island locked: ","Isla bloqueada: ")..selected.name,selected.key);return true end
        local world=tonumber(storage:GetAttribute("World"))
        if not world then routeStatus("waiting",tr("Aguardando o mundo normal carregar.","Waiting for the normal world to load.","Esperando que cargue el mundo normal."),selected.key);return true end
        local main=workspace:FindFirstChild("__Extra")
        local spawns=main and main:FindFirstChild("__Spawns")
        local spawn=spawns and spawns:FindFirstChild(selected.key)
        local root=rootPart()
        if not root then routeStatus("waiting","Island Rift: waiting for character.",selected.key);return true end
        local position=spawn and spawn:GetPivot().Position
        local arrived=world==selected.world and context and context.key==selected.key and position and (root.Position-position).Magnitude<=24
        if not arrived then
            local party=partyClient.GetRoom("IslandRiftAction")
            if party then
                routeStatus("party",tr("Preparando saída da party antes de viajar.","Leaving the party before travelling.","Saliendo del grupo antes de viajar."),selected.key)
                if party.Leader~=player.UserId or party.Locked then return true end
                if state.entryReady("rift:route-leave",os.clock()) then
                    state.entrySent("rift:route-leave",os.clock())
                    general:Fire({Event="IslandRiftAction",Action="Leave",Dungeon=party.Leader})
                end
                return true
            end
            if world~=selected.world then
                routeStatus("world",tr("Viajando para o mundo ","Travelling to world ","Viajando al mundo ")..selected.world,selected.key)
                if state.entryReady("rift:world",os.clock()) then
                    local ready,note=api.prepareContinuation("world")
                    if not ready then dungeonStatus.Text=note;return true end
                    if not dungeon.enabled or state.panic or api.inRun() then return true end
                    state.entrySent("rift:world",os.clock())
                    general:Fire({Event="WorldTeleport",World="World"..selected.world})
                end
            elseif position then
                routeStatus("island",tr("Indo para ","Travelling to ","Viajando a ")..selected.name,selected.key)
                state.target,state.map,state.searchPosition=nil,nil,nil
                generation+=1
                state.modeEntryDestination=position+Vector3.new(0,4,0)
            else routeStatus("waiting",tr("Aguardando o ponto da ilha: ","Waiting for island spawn: ","Esperando el punto de la isla: ")..selected.name,selected.key) end
            return true
        end
        routeStatus("ready",selected.name.." · "..selected.best.." / "..dungeon.rift.target,selected.key)
        return false
    end
    -- Native Boss Rush AFK can replay before Rift's end offer is processed.
    -- Disable only that restart flag; leave the user's other AFK options intact.
    local afkChangedAt
    function api.disableBossRushAFK()
        if not alive or state.stopped or state.panic or player.GameplayPaused
            or not dungeon.enabled or dungeon.mode~="rift" then return true end
        if clientData.Get("Settings","AfkResetB")~=true then return true end
        dungeonStatus.Text=tr("Auto Rift: desligando o AFK do Boss Rush para permitir a saída.","Auto Rift: disabling Boss Rush AFK to allow exit.","Auto Rift: desactivando AFK de Boss Rush para permitir la salida.")
        local now=os.clock()
        if afkChangedAt and now-afkChangedAt<2 then return false end
        local menu=require(storage.Indexer.SettingsMenu)
        local row=assert(menu.Rows and menu.Rows.AfkResetB,"Native Boss Rush AFK setting unavailable")
        local values=assert(menu.Resolve(row,false),"Native Boss Rush AFK resolver unavailable")
        assert(values.AfkResetB==false,"Native Boss Rush AFK value unavailable")
        local settingsModule=require(shared.Others.SettingsModule)
        afkChangedAt=now
        settingsModule.ChangeSettings("AfkResetB",false,"Update")
        general:Fire({Event="SettingsSet",Row="AfkResetB",Value=false})
        return false
    end
    function api.entryStep(mode,inside)
        if not dungeon.enabled or state.panic or player.GameplayPaused or not rootPart() then return true end
        if not api.disableBossRushAFK() then return true end
        if inside then return true end
        local ok,context,reason=pcall(api.context)
        if dungeon.rift.autoIslands then
            -- A destination in another world may have no radar in the current world.
            if api.routeStep(ok and context or nil) then return true end
        end
        if not ok or not context then dungeonStatus.Text=ok and reason or "Island Rift: "..tostring(context);return true end
        local level=dungeon.rift.autoIslands and api.routeLevel(dungeon.rift,context.levels) or api.select(dungeon.rift,context.levels)
        if not level then
            dungeonStatus.Text=tr("Checkpoint indisponível nesta ilha; selecione outro.","Checkpoint unavailable on this island; choose another.","Checkpoint no disponible en esta isla; elige otro.")
            return true
        end
        local party=partyClient.GetRoom(mode.event)
        if party and (party.Locked or party.Leader~=player.UserId) then
            dungeonStatus.Text=tr("Island Rift: aguardando líder ou teleporte.","Island Rift: waiting for leader or teleport.","Island Rift: esperando líder o teletransporte.")
            return true
        end
        local action=party and "Start" or "Create"
        local signature="rift:"..action..":"..context.key..":"..level
        if not state.entryReady(signature,os.clock()) or not rootPart() or player.GameplayPaused then return true end
        if not dungeon.enabled or state.panic then return true end
        if party and dungeon.rift.autoIslands then
            local ready,note=api.prepareContinuation("start")
            if not ready then dungeonStatus.Text=note;return true end
        end
        if not dungeon.enabled or state.panic or player.GameplayPaused then return true end
        local packet={Event=mode.event,Action=action}
        if party then packet.Dungeon=party.Leader;packet.Level=level end
        state.entrySent(signature,os.clock())
        state.dungeonPartyCleanup.note(mode.event)
        if party then
            api.lastEntry={island=context.key,level=level,best=context.best}
            api.route=api.route or {};api.route.current=context.key;api.route.phase="entering"
            state.entryPending={inside=false,root=rootPart(),room=storage:GetAttribute("CurrentRoom"),completed=false}
            state.entryUntil=os.clock()+15
        end
        general:Fire(packet)
        dungeonStatus.Text=tr("Island Rift: solicitando ","Island Rift: requesting ","Island Rift: solicitando ")..action.." · "..context.island.Name.." · Lv "..level
        return true
    end
    state.modeHooks.rift={entryStep=api.entryStep}
    function api.observe(packet)
        if not alive or type(packet)~="table" then return end
        if packet.Event=="ResetInfinite" then
            -- This is the native end offer, not DeletedInstance/Reason=Started.
            pending={packet=packet,at=os.clock(),deadline=os.clock()+20,sent=false}
            state.finishedMode="rift"
        elseif packet.Event=="Reseted" then
            pending=nil
            if state.finishedMode=="rift" then state.finishedMode=nil end
        elseif packet.Event=="ResetInfiniteEnd" then pending=nil end
    end
    local subscription=require(storage.BridgeNet2).ReferenceBridge("ISLAND_RIFT"):Connect(api.observe)
    table.insert(cleanupCallbacks,function() subscription:Disconnect() end)
    function api.step()
        if state.questPriorityActive and state.questPriorityActive() then return end
        if not api.disableBossRushAFK() then return end
        if not pending then return end
        if not api.inRun() then pending=nil;if state.finishedMode=="rift" then state.finishedMode=nil end;return end
        if pending.sent or state.panic or not dungeon.enabled or dungeon.mode~="rift" or player.GameplayPaused then return end
        if dungeon.rift.autoNext or dungeon.rift.autoIslands then
            if os.clock()-pending.at<2 then return end
            -- Return first: the native replay packet has no Level selector.
            -- The next lobby entry rereads the account's updated best for that island.
            if pending.lastAttempt and os.clock()-pending.lastAttempt<5 then return end
            pending.lastAttempt=os.clock()
            if dungeon.rift.autoIslands then
                local ready,note=api.prepareContinuation("exit")
                if not ready then dungeonStatus.Text=note;return end
            end
            pending.sent=state.requestDungeonExit()~=false
            dungeonStatus.Text=tr("Auto Next: retornando para escolher o maior checkpoint liberado.","Auto Next: returning to choose the highest unlocked checkpoint.","Auto Next: volviendo para elegir el mayor checkpoint desbloqueado.")
        elseif state.replayAllowed() and os.clock()<pending.deadline then
            local price=tonumber(pending.packet.Price)
            if price and (price~=price or price~=0) then dungeonStatus.Text="Island Rift: replay price is not free; waiting.";return end
            pending.sent=true
            general:Fire({Event="IslandRiftAction",Action="Reset"})
        end
    end
    task.spawn(function()
        while alive do
            task.wait(0.5)
            if not alive then break end
            local ok,problem=pcall(api.step)
            if not ok then dungeonStatus.Text="Island Rift: "..tostring(problem) end
        end
    end)
end


task.spawn(function()
    local wasInside = false
    local gateContext
    while alive do
        task.wait(0.5)
        if not alive then break end
            if state.panic then continue end
        local inside = insideDungeon()
        if inside ~= wasInside then
            state.keyEmptySample=nil
            state.target, state.map = nil, nil
            generation += 1
            nextRequest = os.clock() + (inside and 0 or 5)
            state.entryPace = {initialUntil = nextRequest, retryAt = 0}
            lastEntrySignature = nil
            wasInside = inside
            state.modeEntryReset()
        end
        if state.dungeonPartyCleanup.step() then continue end
        if inside and state.nativeRestartPending then continue end
        loadNative()
        local questMode = questRuntime.modeRequest
        local questJob = autoQuest.enabled and (autoQuest.scope == "all" or autoQuest.scope == "recurring") and autoQuest.journey
        if not inside and not questMode and autoQuest.enabled and state.recurringQuestPolicy.enabled(autoQuest) and state.recurringQuests.hasModePending then
            dungeonStatus.Text=questRuntime.recurringStatus or "Auto Quest: aguardando a tarefa específica antes de entrar."
            continue
        end
        if questJob and (inside or not questMode) then continue end
        if state.questPriorityActive and state.questPriorityActive() and not questMode
            and not (state.limitBreakerPortalRequested and state.limitBreakerPortalRequested()) then continue end
        if not dungeon.enabled and not questMode then continue end
        if questMode then
            local ok, allowed, reason = pcall(state.worldQuestEntryGuard, questJob, inside)
            if not ok or not allowed then dungeonStatus.Text = ok and reason or "Missão de Mundo: aguardando dados de entrada." continue end
        end
        if not inside and state.collectionPriority() then
            state.modeEntryDestination = nil
            dungeonStatus.Text = "Collection pending: " .. state.collectionPriority() .. ". Auto Dungeon will resume afterwards."
            continue
        end
        if not inside and not (state.questPriorityActive and state.questPriorityActive()) and state.guild.journey and state.guild.journey.phase == "return" then
            dungeonStatus.Text = "Concluindo o retorno da guilda antes de entrar no modo."
            continue
        end
        if events.active == "guild" and not inside then
            if state.guildPriorityActive and state.guildPriorityActive() then
                dungeonStatus.Text = "Auto Dungeon aguardando o chefe da guilda."
                continue
            end
            events.active = nil
        end
        if state.houseCollectionDue() and not inside then dungeonStatus.Text = "Auto Dungeon aguardando a rodada das casas." continue end
        local config = questMode or dungeon
        local mode = dungeonMode(config)
        if not questMode and not inside and mode.id=="key" and dungeon.autoKeys then
            local readyOk,ready=pcall(state.syncKeyAFK,true)
            if not readyOk or not ready then dungeonStatus.Text="Auto Keys: aguardando ativar Usar Dungeon Keys no AFK nativo." continue end
            local ok, selected = pcall(state.autoIslandKey, dungeon.key)
            if not ok then dungeonStatus.Text="Auto Keys: waiting for native key data." continue end
            if not selected then dungeonStatus.Text="Auto Keys: no available island keys. Waiting for stock." continue end
            if dungeon.key~=selected then
                local previous=dungeon.key
                dungeon.key=selected
                if not save() then dungeon.key=previous dungeonStatus.Text="Auto Keys: could not save selection." continue end
                refreshDungeon()
            end
        end
        local context = mode.id .. ":" .. tostring(storage:GetAttribute("World")) .. ":" .. tostring(dungeon.enabled) .. ":" .. tostring(questJob and questJob.id)
        if context ~= gateContext then
            gateContext = context
            state.modeEntryReset()
            if questMode then nextRequest = os.clock() + 5 lastEntrySignature = nil end
            if not inside and state.entryPace.context and state.entryPace.context ~= mode.id then
                nextRequest = os.clock() + 5 state.entryPace = {initialUntil = nextRequest, retryAt = 0}
            end
            state.entryPace.context = mode.id
        end
        if not nativeOK then dungeonStatus.Text = "Entrada indisponivel: " .. tostring(nativeProblem) continue end
        if not inside and state.leaving then dungeonStatus.Text = "Aguardando a saida da partida..." continue end
        if not inside and mode.entryWorld then
            local destination = mode.entryWorld
            if tonumber(storage:GetAttribute("World")) ~= destination then
                state.modeEntryDestination = nil
                if (tonumber(clientData.Get("Rank")) or 0) < ({0, 7, 20})[destination] then
                    dungeonStatus.Text = "World " .. destination .. " is locked: rank requirement not met."
                    continue
                end
                local action = "world:" .. mode.id .. ":" .. destination
                if not state.entryReady(action, os.clock()) then dungeonStatus.Text = "World " .. destination .. ": teleport in " .. state.entryWait(action, os.clock()) .. "s…" continue end
                state.entrySent(action, os.clock())
                nextRequest = os.clock() + 5
                dungeon.entrySequence = {mode = mode.id, world = destination, expires = workspace:GetServerTimeNow() + 90}
                local ready, session = pcall(function()
                    if not save() then return nil end
                    return assert(loadstring(readfile("VykronHub/AutoExecute.luau")))(player.UserId, false)
                end)
                if ready and session and session.queued then
                    general:Fire({Event = "WorldTeleport", World = "World" .. destination})
                    dungeonStatus.Text = "Travelling to World " .. destination .. ". Waiting for confirmation…"
                else dungeonStatus.Text = "Enable Auto Execute to continue after changing worlds." end
                continue
            end
        end
        if not inside and os.clock() < state.entryPace.initialUntil then
            dungeonStatus.Text = mode.name .. ": entering in " .. math.ceil(state.entryPace.initialUntil - os.clock()) .. "s…"
            continue
        end
        if not inside and mode.keys then
            local ok, permitted, message = pcall(state.raidCanEnter, mode, config)
            if not ok or not permitted then dungeonStatus.Text = ok and message or "Aguardando requisitos nativos do modo." continue end
        end
        local nativeMode = nativeModes[mode.id] or (mode.keys and nativeModes.key)
        if not nativeMode then dungeonStatus.Text = "Esse modo nao esta disponivel no menu desta versao." continue end
        local hooks = state.modeHooks[mode.id]
        if hooks and hooks.entryStep and hooks.entryStep(mode, inside) then continue end
        local repeatInside = mode.id == "portal" and inside and state.replayAllowed()
            and storage:GetAttribute("DungeonCompleted") == true
        local portalInfo
        if mode.id == "portal" and (not inside or repeatInside) then
            portalInfo = nativePartyShared.DungeonInfos()
            local world = storage:GetAttribute("World")
            local currentWorld = world and ("World" .. tostring(world)) or storage:GetAttribute("BackWorld")
            if not portalInfo or tostring(portalInfo.World) ~= currentWorld then
                dungeonStatus.Text = "Aguardando portal do " .. currentWorld .. "..."
                continue
            end
            if nativePartyShared.DungeonCompleted() then
                if not state.replayAllowed() then
                    dungeonStatus.Text = "Portal concluido. Aguardando o proximo; Auto Replay desligado."
                    continue
                end
                local portalId = tostring(portalInfo.ID)
                if dungeon.gemResetPending == portalId then
                    dungeonStatus.Text = "Reset com gemas solicitado. Aguardando confirmacao; sem repetir a cobranca."
                    continue
                end
                local schedule = nativeSchedule(nativeMode, workspace:GetServerTimeNow())
                if schedule.Open ~= true and not repeatInside then dungeonStatus.Text = "Aguardando abertura do portal para repetir." continue end
                local info = require(storage.Indexer.DungeonInfo)[portalInfo.Dungeon]
                local price = info and info.Rejoin and info.Rejoin.Gems
                if not price then dungeonStatus.Text = "Preco do reset indisponivel; nenhuma compra enviada." continue end
                if not nativeGameData.HasCurrency("Gems", price) then
                    dungeonStatus.Text = "Gemas insuficientes para repetir a dungeon."
                    continue
                end
                if os.clock() < nextRequest or not rootPart() or player.GameplayPaused then
                    dungeonStatus.Text = "Aguardando para solicitar reset com gemas..."
                    continue
                end
                -- Persist before sending: reruns must not pay again while completion is stale.
                dungeon.gemResetPending = portalId
                if dungeon.runes then dungeon.runes.replayPending = true end
                local persisted = save()
                if not persisted then
                    dungeon.gemResetPending = nil
                    dungeonStatus.Text = "Nao foi possivel salvar o pedido de reset; compra cancelada."
                    continue
                end
                nextRequest = os.clock() + (repeatInside and 1 or 5)
                lastEntrySignature = nil
                local paid, problem = pcall(function()
                    general:Fire({Event = "DungeonAction", Action = "BuyTicket", Type = "Gems"})
                end)
                dungeonStatus.Text = paid and "Reset com gemas solicitado. Aguardando liberacao..."
                    or "Falha no reset: " .. tostring(problem)
                continue
            end
            if dungeon.gemResetPending then dungeon.gemResetPending = nil save() end
            local room = partyClient.GetRoom(mode.event)
            if room and room.DungeonID and tostring(room.DungeonID) ~= tostring(portalInfo.ID) then
                dungeonStatus.Text = "O grupo pertence a outro portal. Saia dele para criar um novo."
                continue
            end
        end
        if mode.kind == "difficulty" then
            local valid = false
            for _, option in ipairs(mode.id == "trial" and trialDifficulties or rushDifficulties) do if option.id == config.difficulty then valid = true end end
            if not valid then dungeonStatus.Text = "Selecione uma dificuldade disponivel para esse modo." continue end
        end
        if waveListed(mode) and not inside then
            local valid = false
            for _, option in ipairs((unlockedWaves(mode))) do if option.id == config.checkpoint then valid = true end end
            if not valid then dungeonStatus.Text = "Escolha uma wave liberada da lista." continue end
        end
        if mode.kind == "castle" and not inside then
            local valid = false
            local options = unlockedCastle(mode)
            for _, option in ipairs(options) do if option.id == config.checkpoint then valid = true end end
            if not valid then dungeonStatus.Text = "Escolha um checkpoint liberado da lista (limite 1000)." continue end
        end
        -- CASTLE GEM REPLAY
        if mode.kind == "castle" and not inside then
            local checked, waiting = pcall(function()
                local nativeId = mode.id == "infernal" and "castle" or "heavenly"
                if not nativePartyShared.CastleCompleted(nativeId) then
                    if dungeon.castleGemResetPending then dungeon.castleGemResetPending = nil save() end
                    return false
                end
                if not state.replayAllowed() then
                    dungeonStatus.Text = "Castelo concluído nesta janela. Ative Auto Replay para repetir com gemas."
                    return true
                end
                local info = nativePartyShared.CastleOf(nativeId)
                local date = tonumber(storage:GetAttribute("DateTime"))
                local interval = balanceInfo.CastleEvent and balanceInfo.CastleEvent.OpenTime
                if not info or not info.Info or not info.Info.Rejoin or not date or not interval or interval <= 0 then
                    dungeonStatus.Text = "Aguardando preço e janela do castelo; nenhuma compra enviada."
                    return true
                end
                local key = mode.id .. ":" .. tostring(info.Prefix) .. tostring(math.floor(date / interval))
                if dungeon.castleGemResetPending == key then
                    dungeonStatus.Text = "Reset do castelo solicitado. Aguardando liberação; sem repetir a cobrança."
                    return true
                end
                if nativeSchedule(nativeMode, workspace:GetServerTimeNow()).Open ~= true then
                    dungeonStatus.Text = "Aguardando abertura do castelo para repetir."
                    return true
                end
                local rejoin = info.Info.Rejoin
                local price = nativeGameData.ToBigNum(rejoin.Gems)
                    * nativeGameData.ToBigNum(rejoin.Mult) ^ nativeGameData.ToBigNum(nativePartyShared.Stat(info.Stat))
                if not nativeGameData.HasCurrency("Gems", price) then
                    dungeonStatus.Text = "Gemas insuficientes para repetir o castelo."
                    return true
                end
                if os.clock() < nextRequest or not rootPart() or player.GameplayPaused then
                    dungeonStatus.Text = "Aguardando para repetir o castelo com gemas..."
                    return true
                end
                dungeon.castleGemResetPending = key
                if not save() then
                    dungeon.castleGemResetPending = nil
                    dungeonStatus.Text = "Não foi possível salvar o pedido; compra cancelada."
                    return true
                end
                nextRequest, lastEntrySignature = os.clock() + 5, nil
                general:Fire({Event = "CastleAction", Action = "BuyTicket", Type = "Gems", Castle = info.Request})
                dungeonStatus.Text = "Reset do castelo com gemas solicitado. Aguardando confirmação..."
                return true
            end)
            if not checked then dungeonStatus.Text = "Falha ao verificar repetição do castelo: " .. tostring(waiting) nextRequest = os.clock() + 5 continue end
            if waiting then continue end
        end
        -- END CASTLE GEM REPLAY
        local success, problem = pcall(function()
            local schedule = nativeSchedule(nativeMode, workspace:GetServerTimeNow())
            local open = repeatInside or schedule.Open == true
            if mode.id == "portal" and not repeatInside then
                local main = workspace:FindFirstChild("__Main")
                local folder = main and main:FindFirstChild("__Dungeon")
                open = open and folder and folder:FindFirstChild("Dungeon") ~= nil
            end
            local party = partyClient.GetRoom(mode.event)
            if mode.id=="key" and dungeon.autoKeys and not questMode and not inside and party
                and party.DungeonKey~=config.key then
                if party.Leader~=player.UserId or party.Locked then
                    dungeonStatus.Text="Auto Keys: waiting for the current party leader or teleport." return
                end
                if state.entryReady("autokeys:leave-party",os.clock()) then
                    general:Fire({Event="DungeonKeyAction",Action="Leave"})
                    state.entrySent("autokeys:leave-party",os.clock())
                end
                dungeonStatus.Text="Auto Keys: leaving the previous key party." return
            end
            local request, message = dungeonPlan(mode, config, {inside = inside and not repeatInside, open = open, room = party, userId = player.UserId})
            dungeonStatus.Text = message
            if not questMode and not dungeon.enabled then return end
            if request and request.Action == "Start" and mode.id == "portal" then
                local prepared, reason = state.prepareDungeonRunes(partyClient.GetRoom(mode.event))
                if not prepared then dungeonStatus.Text = reason return end
                if state.runeWarning then dungeonStatus.Text = message .. "\n" .. state.runeWarning end
            end
            local signature = request and request.Event .. ":" .. request.Action
            local ready = state.entryReady(signature, os.clock())
            if request and not ready then dungeonStatus.Text = "Aguardando " .. state.entryWait(signature, os.clock()) .. " s para entrar..." end
            if request and ready and rootPart() and not player.GameplayPaused then
                if mode.id == "portal" and request.Action == "Start" then
                    local remembered, reason = state.rememberDungeonRunes(partyClient.GetRoom(mode.event))
                    if not remembered then dungeonStatus.Text = reason return end
                end
                nextRequest = os.clock() + 5
                lastEntrySignature = signature
                state.entrySent(signature, os.clock())
                if request.Action == "Start" or request.Action == "Join" or request.Action == "TestEnter" then
                    state.entryPending = {inside = insideDungeon(), root = rootPart(), room = storage:GetAttribute("CurrentRoom"), completed = storage:GetAttribute("DungeonCompleted") == true}
                    state.entryUntil = os.clock() + 15
                end
                if questJob and (request.Action == "Start" or request.Action == "TestEnter" or request.Action == "Join") then
                    questJob.enterRequested = true
                    if not save() then questJob.enterRequested = nil dungeonStatus.Text = "Missão de Mundo: falha ao salvar a entrada." return end
                end
                -- Runes/native loading may yield while the user disables the toggle.
                if questJob and questJob.bucket and (request.Action=="Create" or request.Action=="SelectKey") then
                    questJob.partyRequested=true
                    if not save() then questJob.partyRequested=nil;return end
                end
                if not questMode and not dungeon.enabled then return end
                if not questMode then state.dungeonPartyCleanup.note(mode.event) end
                general:Fire(request)
            end
        end)
        if not success then dungeonStatus.Text = "Entrada interrompida: " .. tostring(problem) nextRequest = os.clock() + 5 lastEntrySignature = nil end
    end
end)
-- HOSPITAL REPLAY: use the native end-screen callback; Join is only a lobby entry action.
do
    local finishedAt, lastRequest, attempts = nil, -math.huge, 0
    local eclipseNextSent = false
    local labels = {REPLAY=true, ["PLAY AGAIN"]=true, ["TRY AGAIN"]=true, REPETIR=true,
        ["JOGAR NOVAMENTE"]=true, ["TENTAR NOVAMENTE"]=true, REINICIAR=true, ["VOLVER A JUGAR"]=true}
    local function visible(object)
        while object do
            if object:IsA("GuiObject") and not object.Visible then return false end
            if object:IsA("ScreenGui") and not object.Enabled then return false end
            object = object.Parent
        end
        return true
    end
    local function replayButton(eclipse)
        local playerGui = player:FindFirstChildOfClass("PlayerGui")
        if not playerGui then return nil end
        for _, object in ipairs(playerGui:GetDescendants()) do
            if (object:IsA("TextLabel") or object:IsA("TextButton")) and not object:IsDescendantOf(gui) then
                local text = object.Text:gsub("<[^>]+>", ""):match("^%s*(.-)%s*$"):upper()
                local party = eclipse and playerGui:FindFirstChild("Menus")
                party = party and party:FindFirstChild("UI_Party")
                local resultPane = eclipse and object:FindFirstAncestor("pa_res")
                local nextLabel = text == "NEXT" or text == "PRÓXIMO" or text == "PROXIMO" or text == "SIGUIENTE"
                local allowed = not eclipse and labels[text] or eclipse and nextLabel and resultPane
                    and party and object:IsDescendantOf(party)
                if allowed and visible(object) then
                    local button = object:IsA("GuiButton") and object or object:FindFirstAncestorWhichIsA("GuiButton")
                    if button and button.Active and visible(button) then return button end
                end
            end
        end
    end
    local function activate(button)
        local inspect = getconnections or env.getconnections
        if type(inspect) ~= "function" then return false, "Executor sem acesso ao botão nativo." end
        for _, signal in ipairs({button.Activated, button.MouseButton1Click}) do
            local fired, failure = false, nil
            for _, connection in ipairs(inspect(signal)) do
                if connection.Enabled ~= false and type(connection.Fire) == "function" then
                    local ok, problem = pcall(function() connection:Fire() end)
                    fired = fired or ok
                    if not ok then failure = tostring(problem) end
                end
            end
            if fired then return true end
            if failure then return false, failure end
        end
        return false, "Botão nativo sem callback disponível."
    end
    task.spawn(function()
        while alive do
            task.wait(0.5)
            if not alive then break end
            if state.panic then continue end
            local eclipse = storage:GetAttribute("DungeonMap") == "EclipseCourtRaid"
            if eclipse then
                local completed = storage:GetAttribute("DungeonCompleted") == true
                if not completed then
                    eclipseNextSent = false
                    finishedAt, lastRequest, attempts = nil, -math.huge, 0
                elseif state.replayAllowed() and not state.nativeRestartPending then
                    local now = os.clock()
                    finishedAt = finishedAt or now
                    if not eclipseNextSent and now - finishedAt >= 2 and now - lastRequest >= 5
                        and not player.GameplayPaused and rootPart() and not state.autoLeaving then
                        local button = replayButton(true)
                        if button then
                            lastRequest = now
                            local ok, problem = activate(button)
                            eclipseNextSent = ok
                            dungeonStatus.Text = ok and "Eclipse Court: aguardando votação de PLAY AGAIN."
                                or "Eclipse Court: " .. tostring(problem)
                        else dungeonStatus.Text = "Eclipse Court: aguardando NEXT na tela de resultados." end
                    end
                end
                continue
            end
            eclipseNextSent = false
            local main = workspace:FindFirstChild("__Main")
            local hospital = storage:GetAttribute("HLRaid") == true or storage:GetAttribute("DungeonMap") == "Hospital"
                or (main ~= nil and main:FindFirstChild("HLRaid") ~= nil)
            local button = hospital and replayButton() or nil
            local completed = hospital and (storage:GetAttribute("DungeonCompleted") == true or button ~= nil)
            if not completed or not state.replayAllowed() then
                finishedAt, lastRequest, attempts = nil, -math.huge, 0
                if state.replayBlocked then state.replayBlocked.hospital = nil end
                continue
            end
            local now = os.clock()
            finishedAt = finishedAt or now
            if now - finishedAt < 2 or player.GameplayPaused or not rootPart() or state.autoLeaving then continue end
            if attempts >= 3 or now - finishedAt >= 25 then
                state.replayBlocked = state.replayBlocked or {}
                state.replayBlocked.hospital = true
                dungeonStatus.Text = "Hospital: reinício sem confirmação. Confira o portal."
                continue
            end
            if not button then dungeonStatus.Text = "Hospital: aguardando botão nativo de replay." continue end
            if now - lastRequest < 5 then continue end
            lastRequest, attempts = now, attempts + 1
            local ok, problem = activate(button)
            dungeonStatus.Text = ok and "Hospital: aguardando confirmação do reinício." or "Falha no reinício: " .. tostring(problem)
            if ok then
                state.entryPending = {inside = true, root = rootPart(), room = storage:GetAttribute("CurrentRoom"), completed = storage:GetAttribute("DungeonCompleted") == true}
                state.entryUntil = now + 15
                state.target, state.searchPosition, state.map = nil, nil, nil
                generation += 1
            end
        end
    end)
end
-- END HOSPITAL REPLAY
do
local speedWindowUntil = 0
connect(require(shared:WaitForChild("WaveRunClient")).SpeedShown, function(_, duration)
    speedWindowUntil = os.clock() + (tonumber(duration) or 5)
end)
task.spawn(function()
    local activeMode, lastProgress, lastSpeedAt, lastExitAt, exitAttempts = nil, nil, -math.huge, -math.huge, 0
    while alive do
        task.wait(0.5)
        if not alive then break end
            if state.panic then continue end
        if state.questPriorityActive and state.questPriorityActive() then state.leaving=false;continue end
        local mode,ambiguous=state.activeSpeedMode(function(flag) return storage:GetAttribute(flag) end)
        local progress = mode and tonumber(storage:GetAttribute(mode.progress))
        if mode ~= activeMode or (progress and lastProgress and progress < lastProgress) then
            activeMode, lastSpeedAt, lastExitAt, exitAttempts = mode, -math.huge, -math.huge, 0
            speedWindowUntil=0
            state.leaving, state.target, state.map = false, nil, nil
        end
        lastProgress = progress
        if not mode then miscStatus.Text = ambiguous and "Modo ambíguo: aguardando indicadores sincronizarem; velocidade preservada." or "Aguardando um dos modos configurados..." continue end
        local config = misc[mode.id]
        local action, index = miscDecision(config, progress, mode)
        local prefix = mode.name .. " · " .. mode.unit .. " " .. tostring(progress or "?") .. "\n"
        if action == "leave" then
            state.leaving, state.target = true, nil
            miscStatus.Text = prefix .. (exitAttempts >= 3 and "Saida sem confirmacao. Confira a tela do jogo." or "Solicitando saida...")
            if exitAttempts < 3 and os.clock() - lastExitAt >= 10 then
                lastExitAt, exitAttempts = os.clock(), exitAttempts + 1
                local success, problem = pcall(function() state.requestDungeonExit() end)
                if not success then miscStatus.Text = prefix .. "Falha ao sair: " .. tostring(problem) end
            end
        elseif action == "speed" then
            state.leaving = false
            local desired = mode.values[index]
            if storage:GetAttribute(mode.attribute) == desired then
                miscStatus.Text = prefix .. "Velocidade: " .. desired .. "x"
            elseif not mode.everyone and storage:GetAttribute("InfiniteOwner") ~= player.Name then
                miscStatus.Text = prefix .. "A troca de velocidade exige ser o lider."
            elseif not mode.everyone and storage:GetAttribute("Intermission") ~= true and os.clock() >= speedWindowUntil then
                miscStatus.Text = prefix .. "Aguardando janela para aplicar " .. desired .. "x..."
            else
                miscStatus.Text = prefix .. "Solicitando " .. desired .. "x (depende dos requisitos do jogo)."
                if os.clock() - lastSpeedAt >= 5 then
                    lastSpeedAt = os.clock()
                    local success, problem = pcall(function() general:Fire({Event = mode.event, Action = "SpeedUp", Speed = mode.requests[index]}) end)
                    if not success then miscStatus.Text = prefix .. "Falha na velocidade: " .. tostring(problem) end
                end
            end
        else
            state.leaving = false
            miscStatus.Text = prefix .. (config.speedEnabled and "Sem troca programada para agora. Campos em 0 não alteram a velocidade." or "Velocidade automática desligada.")
        end
    end
end)
end -- speed controller scope
local mapInfo = require(storage.Indexer.MapInfo)
do
    local names = require(storage.Indexer.EnemyInfo)
    for _, info in pairs(require(storage.Indexer.WorldBosses)) do
        if type(info) == "table" and info.Boss and mapInfo[info.Map] then
            worldBossIds[info.Boss] = {world = mapInfo[info.Map].World, name = names[info.Boss] and names[info.Boss].Name or info.Boss}
        end
    end
    if names.PumpkinKing then worldBossIds.PumpkinKing = {world = nil, name = names.PumpkinKing.Name or "Pumpkin King"} end
end

-- PUMPKIN KING: optional arena event, using the shared movement/attack controller.
do
    local run = {nextAttempt = 0}
    local function clear(returnToFarm)
        if events.active ~= "pumpkinking" then return end
        events.active = nil
        state.target, state.worldBossTarget, state.searchPosition, state.eventTravel = nil, nil, nil, nil
        state.eventDestination = returnToFarm and run.origin or nil
        state.map = run.originMap
        generation += 1
        run.startedAt, run.arrived, run.sawBoss, run.lastSeen, run.origin, run.originMap = nil, nil, nil, nil, nil, nil
    end
    local function caption(text)
        state.kingStatus = text
        if state.kingRow then state.kingRow.Caption.Text = text end
    end
    local warnings = require(storage.BridgeNet2).ReferenceBridge("WARN_EVENT")
    local receipt = warnings:Connect(function(packet)
        if type(packet) ~= "table" then return end
        local announcedWorld = packet.World or packet.WorldId
        if announcedWorld ~= nil then
            local id = tonumber(tostring(announcedWorld):match("%d+"))
            if id and id ~= tonumber(storage:GetAttribute("World")) then return end
        end
        local kind = state.kingNotice(packet)
        if kind == "spawn" then
            state.pumpkinKing.untilAt, state.pumpkinKing.world = workspace:GetServerTimeNow() + 180, tonumber(storage:GetAttribute("World"))
        elseif kind == "ended" then
            state.pumpkinKing.untilAt = 0
            run.ended = true
        end
    end)
    table.insert(cleanupCallbacks, function() receipt:Disconnect() clear(false) end)
    task.spawn(function()
        while alive do
            task.wait(0.5)
            if not alive then break end
            if state.panic then continue end
            local ok, problem = pcall(function()
                if state.questPriorityActive and state.questPriorityActive() then clear(false);caption("Auto Quest: Pumpkin King pausado.");return end
                local config, now = state.pumpkinKing, workspace:GetServerTimeNow()
                if not config.enabled then clear(true) caption("Desligado.") return end
                if insideDungeon() or state.leaving or state.autoLeaving or state.rebirthing then
                    clear(false) caption("Pumpkin King: aguardando concluir a partida.") return
                end
                if state.houseCollectionDue() or state.kamishDue() then
                    clear(false) caption("Pumpkin King: aguardando coleta prioritária.") return
                end
                if state.guild.journey then caption("Pumpkin King: aguardando retorno da guilda.") return end
                local root = rootPart()
                if not root or player.GameplayPaused or player:GetAttribute("Mounted") or player:GetAttribute("Swimming") then
                    caption("Pumpkin King: aguardando personagem livre.") return
                end
                local boss = nearestWorldBoss(enemyFolder(), root.Position, "pumpkinking")
                if events.active == "pumpkinking" then
                    if run.ended then run.ended = nil config.untilAt = 0 clear(true) caption("Pumpkin King finalizado. Retomando rotina.") return end
                    if state.eventTravel then
                        if (root.Position - state.eventTravel.position).Magnitude <= 65 then
                            state.eventTravel, run.arrived = nil, now
                        elseif now - state.eventTravel.at >= 12 then
                            config.untilAt = 0 run.nextAttempt = now + 30 clear(true)
                            caption("Pumpkin King: entrada na arena sem confirmação.")
                        end
                        return
                    end
                    if boss then run.sawBoss, run.lastSeen = true, now end
                    if (run.sawBoss and not boss and now - (run.lastSeen or now) > 4)
                        or (not run.sawBoss and now - (run.arrived or run.startedAt or now) > 20) then
                        config.untilAt = 0 run.nextAttempt = now + 30 clear(true)
                        caption("Pumpkin King finalizado ou não encontrado. Retomando rotina.") return
                    end
                    if boss then caption("Pumpkin King: combatendo na World Arena.")
                    else
                        caption("Pumpkin King: procurando na World Arena.")
                        if now >= (run.streamAt or 0) then
                            run.streamAt = now + 5
                            local position = root.Position
                            task.spawn(function() pcall(function() player:RequestStreamAroundAsync(position, 1) end) end)
                        end
                    end
                    return
                end
                run.ended = nil
                if not state.kingDue() then
                    caption(state.isHalloweenNight() and "Pumpkin King: aguardando nascimento na arena." or "Pumpkin King: aguardando anúncio ou chefe ativo.") return
                end
                if events.active then
                    -- Preserve the original farm context while the ordinary event controller yields.
                    run.origin, run.originMap = run.origin or events.returnPosition or root.Position, run.originMap or events.returnMap or state.map
                    caption("Pumpkin King: aguardando liberar o movimento.") return
                end
                if now < run.nextAttempt then caption("Pumpkin King: nova tentativa em " .. math.ceil(run.nextAttempt - now) .. " s.") return end
                local extra = workspace:FindFirstChild("__Extra")
                local spawns = extra and extra:FindFirstChild("__Spawns")
                local arena = spawns and spawns:FindFirstChild("Arena")
                if not arena then caption("Pumpkin King: aguardando a World Arena carregar.") return end
                run.origin, run.originMap = run.origin or root.Position, run.originMap or state.map
                run.startedAt, run.arrived, run.sawBoss, run.lastSeen = now, now, boss ~= nil, boss and now or nil
                events.active = "pumpkinking"
                state.target, state.searchPosition, state.eventDestination, state.eventTravel = nil, nil, nil, nil
                generation += 1
                local position = arena:GetPivot().Position
                if (root.Position - position).Magnitude > 65 then
                    state.eventTravel = {position = position, at = now}
                    general:Fire({Event = "IslandTeleport", Island = "Arena"})
                end
                caption("Pumpkin King: entrando na World Arena.")
            end)
            if not ok then
                run.nextAttempt = workspace:GetServerTimeNow() + 30
                state.pumpkinKing.untilAt = 0
                clear(true)
                caption("Pumpkin King: falha ao consultar o evento; nova tentativa em 30 s.")
                warn("[VykronHub] Pumpkin King: " .. tostring(problem))
            end
        end
    end)
end
-- END PUMPKIN KING
-- OPEN RAID NAVIGATION: a streamed probe is not permission to travel to an unchecked floor.
function state.openRaidProbe(raid, spawns)
    local marker=raid.spawn and spawns and spawns:FindFirstChild(raid.spawn)
    if marker and marker:IsA("BasePart") then return marker.Position end
    local point=raid.anchor
    if point then return Vector3.new(point.x,point.y,point.z) end
    return nil
end
function state.openRaidPosition(raid, spawns)
    local marker=raid.spawn and spawns and spawns:FindFirstChild(raid.spawn)
    if marker and marker:IsA("BasePart") then return marker.Position end
    if not raid.anchor or not raid.model then return nil,"Aguardando ponto de chegada da raid." end
    local main=workspace:FindFirstChild("__Main")
    local world=main and main:FindFirstChild("__World")
    local island=world and world:FindFirstChild(raid.model)
    if not island or not island:IsA("Model") then return nil,"Aguardando carregar a ilha dos Giants." end
    local point=raid.anchor
    local params=RaycastParams.new()
    params.FilterType=Enum.RaycastFilterType.Include
    params.FilterDescendantsInstances={island}
    params.IgnoreWater=true
    params.RespectCanCollide=true
    local floor=workspace:Raycast(Vector3.new(point.x,600,point.z),Vector3.new(0,-1000,0),params)
    if not floor or not floor.Instance.CanCollide or floor.Normal.Y<0.8 or math.abs(floor.Position.Y-point.y)>12 then
        return nil,"Aguardando chão confirmado na ilha dos Giants."
    end
    -- Check both room above the character and nearby footing, using the current streamed geometry.
    for _,offset in ipairs({Vector3.zero,Vector3.new(3,0,0),Vector3.new(-3,0,0),Vector3.new(0,0,3),Vector3.new(0,0,-3)}) do
        local near=workspace:Raycast(floor.Position+offset+Vector3.new(0,12,0),Vector3.new(0,-16,0),params)
        if not near or not near.Instance.CanCollide or near.Normal.Y<0.8 or math.abs(near.Position.Y-floor.Position.Y)>3 then
            return nil,"Chegada dos Giants obstruída; aguardando nova leitura."
        end
        if workspace:Raycast(near.Position+Vector3.new(0,0.5,0),Vector3.new(0,9,0),params) then
            return nil,"Chegada dos Giants obstruída; aguardando nova leitura."
        end
    end
    return floor.Position
end
-- END OPEN RAID NAVIGATION
-- OPEN RAID AUTO TRAVEL: persist origin and phase before either world teleport.
do
local function raidTravelBlocked()
    return state.panic or insideDungeon() or state.leaving or state.rebirthing
        or events.active=="guild" or events.active=="kamish" or events.active=="pumpkinking"
        or state.kamishDue() or state.houseCollectionDue() or state.kingDue() or state.pumpkinCollectionDue()
        or (not (state.questPriorityActive and state.questPriorityActive()) and (state.guild.journey ~= nil or state.houses.busy or state.houses.fighting ~= nil))
end
function state.beginRaidJourney(kind, root, world)
    if state.raidTravel then return state.raidTravel.kind==kind end
    local raid=state.openRaids[kind]
    local now=workspace:GetServerTimeNow()
    local origin=events.active=="storm" and events.returnPosition or root.Position
    local originMap=events.active=="storm" and events.returnMap or state.map
    state.raidTravel={kind=kind,originWorld=world,originMap=state.map,
        originPosition={x=origin.X,y=origin.Y,z=origin.Z},
        phase=world==raid.world and "arrived" or "going",eventUntil=raid.untilAt or now+900,
        expiresAt=now+1800,attempts=0,nextAttemptAt=0}
    state.raidTravel.originMap=originMap
    if not save() then state.raidTravel=nil;raid.travelStatus="Falha ao salvar o percurso.";return false end
    return true
end
-- Retain an in-progress raid's original position when this revision replaces the hub.
if not state.raidTravel and previous and previous.events and previous.state then
    local old=previous.events
    local raid=state.openRaids[old.active]
    if raid and state.openRaidEnabled(raid.kind) and old.returnPosition and old.returnWorld then
        local now=workspace:GetServerTimeNow()
        local oldRaid=previous.state.openRaids and previous.state.openRaids[old.active]
        raid.untilAt=oldRaid and oldRaid.untilAt or now+900
        state.beginRaidJourney(old.active,{Position=old.returnPosition},old.returnWorld)
        if state.raidTravel then state.raidTravel.phase="arrived";save() end
    end
end
if state.raidTravel then
    local travel=state.raidTravel
    state.openRaids[travel.kind].untilAt=travel.eventUntil
end
local function raidTravelFire(world, travel, now)
    -- Count failures too, and persist attempts before the server can move this client.
    travel.attempts=(travel.attempts or 0)+1
    travel.nextAttemptAt=now+20
    if not save() then return false,"Falha ao salvar a viagem." end
    local armed, session=pcall(function()
        return assert(loadstring(readfile("VykronHub/AutoExecute.luau")))(player.UserId,false)
    end)
    if not armed or not session or not session.queued then return false,"Continuidade da sessão indisponível." end
    general:Fire({Event="WorldTeleport",World="World"..world})
    return true
end
function state.stepRaidJourney()
    if state.questPriorityActive and state.questPriorityActive() and state.raidTravel and not state.questWantsEvent(state.raidTravel.kind) then
        local travel=state.raidTravel
        if travel.phase~="returning" then state.raidTravel=nil;save();return end
    end
    if raidTravelBlocked() then return end
    local world=tonumber(storage:GetAttribute("World"))
    local root=rootPart()
    if not world or not root then return end
    local now=workspace:GetServerTimeNow()
    local travel=state.raidTravel
    if travel then
        local raid=state.openRaids[travel.kind]
        local done=raid.closed or raid.ended or not state.openRaidEnabled(raid.kind) or now>=travel.eventUntil or now>=travel.expiresAt
        if travel.phase=="going" and world==raid.world then
            travel.phase,travel.attempts,travel.nextAttemptAt="arrived",0,0
            raid.travelStatus=nil;save()
        end
        if done and events.active~=travel.kind and travel.phase~="returning" then
            travel.phase,travel.attempts,travel.nextAttemptAt="returning",0,0
            save()
        end
        if travel.phase=="arrived" then return end
        if travel.phase=="returning" and world==travel.originWorld then
            local pos=travel.originPosition
            state.map=travel.originMap
            if (root.Position-Vector3.new(pos.x,pos.y,pos.z)).Magnitude>15 then
                state.eventDestination=Vector3.new(pos.x,pos.y,pos.z)
            end
            state.target,state.searchPosition,state.eventTravel=nil,nil,nil
            raid.travelStatus=nil;state.raidTravel=nil;generation+=1;save()
            return
        end
        if now<(travel.nextAttemptAt or 0) then return end
        if (travel.attempts or 0)>=3 then
            raid.travelStatus="Viagem interrompida após 3 tentativas; confira a sessão e reative a raid."
            raid.retryAt=now+60
            state.raidTravel=nil;save()
            return
        end
        local destination=travel.phase=="returning" and travel.originWorld or raid.world
        raid.travelStatus=(travel.phase=="returning" and "Retornando ao Mundo " or "Indo para o Mundo ")..destination.."..."
        local ok,problem=raidTravelFire(destination,travel,now)
        if not ok then raid.travelStatus=problem end
        return
    end
    if (events.active and events.active~="storm") or state.eventDestination then return end
    for _,kind in ipairs(state.openRaidOrder) do
        local raid=state.openRaids[kind]
        if state.openRaidEnabled(raid.kind) and not raid.closed and raid.world~=world and now>=(raid.retryAt or 0)
            and (raid.untilAt or 0)>now then
            if state.beginRaidJourney(kind,root,world) and events.active=="storm" and state.yieldStormForRaid then
                state.yieldStormForRaid()
            end
            return
        end
    end
end
task.spawn(function()
    while alive do
        task.wait(1)
        if not alive then break end
        local ok,problem=pcall(state.stepRaidJourney)
        if not ok then warn("[VykronHub] Viagem de raid: "..tostring(problem)) end
    end
end)
end
-- END OPEN RAID AUTO TRAVEL
-- GIANTS HUNT: desired boss, native enemy IDs and bounded searches of World 3 islands.
do
function state.selectGiantsMode(mode)
    if not state.validGiantsMode(mode) then return false end
    local old=state.giantsMode
    state.giantsMode=mode
    if not save() then
        state.giantsMode=old
        state.openRaids.giants.huntStatus="Falha ao salvar o objetivo dos Giants."
        return false
    end
    state.giantsHunt=nil
    state.giantsReturnPending=events.active=="giants" and old=="legia" and mode~="legia" or nil
    state.openRaids.giants.huntStatus=nil
    if events.active=="giants" then
        state.target,state.searchPosition=nil,nil
        generation+=1
    end
    if state.onGiantsModeChanged then state.onGiantsModeChanged() end
    return true
end
function state.giantsSearchPoints(spawns)
    local points={}
    -- These are search candidates, not an asserted Giant22 -> island spawn mapping.
    for id,map in pairs(mapInfo) do
        local order=tonumber(map.Order)
        if tonumber(map.World)==3 and order and order>=22 and order<=25 then
            local marker=spawns and spawns:FindFirstChild(id)
            local position=marker and marker:IsA("BasePart") and marker.Position
            if position then table.insert(points,{id=id,name=map.Name,position=position,order=order}) end
        end
    end
    table.sort(points,function(a,b) return a.order<b.order end)
    return points
end
local function hold(hunt,raid,text)
    hunt.controlling=true
    raid.huntStatus=text
    if state.target then generation+=1 end
    state.target,state.worldBossTarget,state.searchPosition=nil,nil,nil
    return true
end
function state.stepGiantsHunt(root,spawns,now)
    local raid=state.openRaids.giants
    if state.giantsReturnPending and events.active=="giants" and raid.enabled and not raid.closed
        and not insideDungeon() and not state.panic and not state.collectionPriority()
        and tonumber(storage:GetAttribute("World"))==3 then
        local position,problem=state.openRaidPosition(raid,spawns)
        if not position then
            state.giantsHunt=state.giantsHunt or {}
            return hold(state.giantsHunt,raid,problem)
        end
        state.eventDestination=position+Vector3.new(0,3,0)
        state.giantsReturnPending,state.giantsHunt=nil,nil
        return true
    end
    if events.active~="giants" or not raid.enabled or raid.closed or raid.ended
        or state.giantsMode~="legia" or tonumber(storage:GetAttribute("World"))~=3
        or insideDungeon() or state.panic or state.collectionPriority() then
        state.giantsHunt=nil
        if state.giantsMode=="querah" and events.active=="giants" then
            raid.huntStatus="Insect Monarch: aguardando o chefe sem atacar invasores."
        else raid.huntStatus=nil end
        return false
    end
    local hunt=state.giantsHunt
    if not hunt or hunt.untilAt~=raid.untilAt then
        hunt={index=1,untilAt=raid.untilAt,points=state.giantsSearchPoints(spawns)}
        state.giantsHunt=hunt
    end
    local target=state.openRaidNearest(enemyFolder(),root.Position,"giants")
    local id=target and target:GetAttribute("Id")
    if target and (state.giantsInvaderIds[id] or raid.finalIds[id]) then
        hunt.controlling,hunt.travel,hunt.arrivedAt=false,nil,nil
        raid.huntStatus=state.giantsInvaderIds[id] and "Giant Monarch: invasor confirmado; seguindo o alvo."
            or id=="Querah" and "Insect Monarch apareceu; enfrentando o chefe disponível."
            or "Giant Monarch confirmado; enfrentando o chefe."
        return false
    end
    if state.eventDestination or state.eventTravel then return hold(hunt,raid,"Giant Monarch: aguardando chegada.") end
    if hunt.returning then
        local position,problem=state.openRaidPosition(raid,spawns)
        if not position then return hold(hunt,raid,problem) end
        if (root.Position-position).Magnitude>20 then state.eventDestination=position+Vector3.new(0,3,0) end
        hunt.returning,hunt.controlling,hunt.nextSweepAt=nil,false,now+30
        hunt.index,hunt.arrivedAt=1,nil
        raid.huntStatus="Busca concluída; aguardando invasores ou o chefe da raid."
        return false
    end
    if now<(hunt.nextSweepAt or 0) then hunt.controlling=false return false end
    if hunt.travel then
        if (root.Position-hunt.travel.position).Magnitude<=65 then
            hunt.travel,hunt.arrivedAt=nil,now
        elseif now-hunt.travel.at>=8 then
            hunt.travel,hunt.arrivedAt=nil,nil
            hunt.index+=1
        else return hold(hunt,raid,"Giant Monarch: viajando para procurar invasores.") end
    end
    local point=hunt.points[hunt.index]
    if not point then
        if #hunt.points==0 then
            hunt.points=state.giantsSearchPoints(spawns)
            if #hunt.points==0 then
                return hold(hunt,raid,"Aguardando os pontos nativos das ilhas do Mundo 3.")
            end
            point=hunt.points[1]
        else
            hunt.returning=true
            return hold(hunt,raid,"Giant Monarch: retornando à ilha da raid.")
        end
    end
    if hunt.arrivedAt then
        if now-hunt.arrivedAt>=4 then hunt.index+=1;hunt.arrivedAt=nil end
        return hold(hunt,raid,"Giant Monarch: procurando invasores em "..point.name..".")
    end
    if not hunt.streamBusy then
        hunt.streamBusy=true
        task.spawn(function()
            pcall(function() player:RequestStreamAroundAsync(point.position,1) end)
            hunt.streamBusy=nil
        end)
    end
    if (root.Position-point.position).Magnitude<=65 then
        hunt.arrivedAt=now
    else
        hunt.travel={position=point.position,at=now}
        general:Fire({Event="IslandTeleport",Island=point.id})
    end
    return hold(hunt,raid,"Giant Monarch: procurando invasores em "..point.name..".")
end
end
-- END GIANTS HUNT

do
-- EVENT POLICY
local function eventRemaining(now, interval)
    return interval - now % interval
end
local function announcedIsland(payload, maps)
    local explicit = payload.Island or payload.Map
    if type(explicit) == "string" and maps[explicit] then return explicit end
    local message = tostring(payload.Message or ""):gsub("<[^>]+>", ""):lower()
    local found
    for id, info in pairs(maps) do
        if info.World and (message:find(id:lower(), 1, true) or (type(info.Name) == "string" and message:find(info.Name:lower(), 1, true))) then
            if found then return nil end
            found = id
        end
    end
    return found
end
-- END EVENT POLICY
    local stormInfo = require(storage.Indexer.StormInfo)
    local interval, duration = tonumber(stormInfo.SpawnTime) or 1800, tonumber(stormInfo.Duration) or 900
    -- STORM LOCATION POLICY: replicated server coordinates remain available without streamed VFX.
    local function stormPosition(value)
        local kind = typeof(value)
        if kind == "CFrame" then return value.Position end
        if kind == "Vector3" then return value end
        if kind ~= "string" then return nil end
        local values = {}
        for token in value:gmatch("[^,%s]+") do
            local number = tonumber(token)
            if not number or number ~= number or math.abs(number) == math.huge then return nil end
            values[#values + 1] = number
        end
        if #values ~= 3 and #values ~= 12 then return nil end
        return Vector3.new(values[1], values[2], values[3])
    end
    local function stormMapAt(position, spawns)
        if not position or not spawns then return nil end
        local island, distance
        for id, info in pairs(mapInfo) do
            local spawn = tonumber(info.World) == tonumber(storage:GetAttribute("World")) and not info.NoWorld and spawns:FindFirstChild(id)
            if spawn then
                local offset = position - spawn:GetPivot().Position
                local horizontal = Vector3.new(offset.X, 0, offset.Z).Magnitude
                if not distance or horizontal < distance then island, distance = id, horizontal end
            end
        end
        if distance and distance <= 1650 then return island end
    end
    -- END STORM LOCATION POLICY
    -- STORM DETECTION: StormEffect is the active clone; Storm is also a storage template.
    local stormModels = setmetatable({}, {__mode = "k"})
    local function observeStorm(node)
        if (node.Name == "Storm" or node.Name == "StormEffect") and node:IsA("Model") then stormModels[node] = true end
    end
    for _, node in ipairs(workspace:GetDescendants()) do observeStorm(node) end
    table.insert(connections, workspace.DescendantAdded:Connect(observeStorm))
    local function visibleStorm(spawns)
        if not spawns then return nil end
        -- Rescan the native effects container: clones may be renamed after insertion.
        local extra = workspace:FindFirstChild("__Extra")
        local effects = extra and extra:FindFirstChild("__Effects")
        if effects then for _, child in ipairs(effects:GetChildren()) do observeStorm(child) end end
        local selected
        for model in pairs(stormModels) do
            if not model:IsDescendantOf(workspace) then stormModels[model] = nil continue end
            local native = model.Name == "StormEffect" and effects and model:IsDescendantOf(effects)
            local emitting = false
            for _, child in ipairs(model:GetDescendants()) do
                if child:IsA("ParticleEmitter") and child.Enabled then emitting = true break end
            end
            -- Native active marker survives disabled visual effects. Legacy Storm needs live emitters.
            if not native and not (model.Name == "Storm" and emitting) then continue end
            local island = stormMapAt(model:GetPivot().Position, spawns)
            if island and not selected then selected = island end
        end
        return selected
    end
    -- END STORM DETECTION
    local hadStormLocation = false
    local function currentStorm(spawns, now)
        local location = stormPosition(storage:GetAttribute("StormLocation"))
        if location then
            hadStormLocation = true
            local island = stormMapAt(location, spawns)
            events.stormSource = "StormLocation"
            return island
        end
        if hadStormLocation then
            -- Removal of the authoritative attribute ends the event; discard stale notices/VFX.
            events.stormUntil, events.visibleStormMap, events.stormSeenAt = 0, nil, nil
            events.stormSource = nil
            return nil
        end
        local visible = visibleStorm(spawns)
        if visible and not (events.stormEndedAt and now - events.stormEndedAt < 10) then
            events.visibleStormMap, events.stormSeenAt = visible, now
        elseif now - (events.stormSeenAt or -math.huge) > 10 then events.visibleStormMap = nil end
        local island = events.visibleStormMap or (events.stormUntil > now and events.stormMap)
        events.stormSource = events.visibleStormMap and "StormEffect" or (island and "StormAnnounce" or nil)
        return island
    end
    local function announcedBoss(payload)
        local id = payload.Boss or payload.Id or payload.Enemy
        if worldBossIds[id] then return worldBossIds[id].name end
        local message = tostring(payload.Message or ""):gsub("<[^>]+>", ""):lower()
        for key, info in pairs(worldBossIds) do
            if message:find(key:lower(), 1, true) or message:find(info.name:lower(), 1, true) then return info.name end
        end
    end
    local raidSubscription=require(storage.BridgeNet2).ReferenceBridge("ENEMY_EVENT"):Connect(function(packet)
        state.openRaidPacket(packet,workspace:GetServerTimeNow())
        if state.openRaidFinalDeath then state.openRaidFinalDeath(packet) end
        if state.openRaids[events.active] and state.openRaids[events.active].ended and state.finishOpenRaid then state.finishOpenRaid() end
    end)
    table.insert(cleanupCallbacks,function() raidSubscription:Disconnect() end)
    local warnings = require(storage.BridgeNet2).ReferenceBridge("WARN_EVENT")
    local subscription = warnings:Connect(function(payload)
        if type(payload) ~= "table" then return end
        local now = workspace:GetServerTimeNow()
        local message = tostring(payload.Message or ""):lower()
        local ended = message:find("has ended", 1, true) or message:find("has finished", 1, true) or message:find("terminou", 1, true)
        for _,raid in pairs(state.openRaids) do
            if payload.WType==raid.notice then
                raid.untilAt=not ended and now+900 or 0
                raid.closed,raid.closedAt=ended and true or nil,ended and now or nil
                raid.ended=ended and true or nil
                raid.travelStatus,raid.retryAt=nil,nil
                if not ended then
                    raid.queenShield,raid.hadMarkers,raid.finalUID=nil,nil,nil
                    if raid.kind=="giants" then state.giantsHunt=nil end
                    if state.raidClosures then state.raidClosures[raid.kind]=nil end
                end
            end
        end
        if payload.WType == "WorldBossAnnounce" then
            events.bossUntil = not ended and now + 300 or 0
            events.bossName = not ended and announcedBoss(payload) or nil
        elseif payload.WType == "StormAnnounce" or (message:find("storm", 1, true) and announcedIsland(payload, mapInfo)) then
            events.stormMap = announcedIsland(payload, mapInfo) or events.stormMap
            events.stormUntil = not ended and now + duration or 0
            events.stormEndedAt = ended and now or nil
            if ended then events.visibleStormMap = nil end
            if not ended then events.nextStormAt = now + interval end
        end
    end)
    table.insert(cleanupCallbacks, function() subscription:Disconnect() end)
    local function finish()
        local raid=state.openRaids[events.active]
        if events.active=="giants" then state.giantsHunt,state.giantsReturnPending=nil,nil;raid.huntStatus=nil end
        if raid and state.raidTravel and state.raidTravel.kind==events.active
            and (raid.closed or raid.ended or not state.openRaidEnabled(raid.kind) or workspace:GetServerTimeNow()>=(raid.untilAt or 0)) then
            state.raidTravel.phase,state.raidTravel.attempts,state.raidTravel.nextAttemptAt="returning",0,0
            save()
        end
        if raid then raid.ended=nil end
        if events.active == "boss" then events.bossUntil = 0 end
        state.eventDestination=nil
        if events.active and not state.raidTravel and not insideDungeon() and (not events.returnWorld or events.returnWorld==tonumber(storage:GetAttribute("World"))) then
            state.eventDestination = events.returnPosition
            state.map = events.returnMap
        end
        state.target, state.worldBossTarget, state.searchPosition, state.eventTravel = nil, nil, nil, nil
        events.active, events.returnPosition, events.returnMap, events.returnWorld = nil, nil, nil, nil
        generation += 1
    end
    state.finishOpenRaid=function()
        if state.openRaids[events.active] then finish() end
    end
    state.yieldStormForRaid=function()
        if events.active=="storm" then finish() end
    end
    table.insert(cleanupCallbacks, function()
        state.finishOpenRaid=nil
        state.yieldStormForRaid=nil
        state.eventDestination, state.eventTravel = nil, nil
    end)
    task.spawn(function()
        while alive do
            task.wait(1)
            if not alive then break end
            if state.panic then continue end
            local success, problem = pcall(function()
                if events.active == "pumpkinking" then return end
                local now = workspace:GetServerTimeNow()
                local root = rootPart()
                local boss = root and nearestWorldBoss(enemyFolder(), root.Position) or nil
                if boss then events.bossName = worldBossIds[boss:GetAttribute("Id")].name end
                local function clock(seconds)
                    seconds = math.max(0, math.ceil(seconds))
                    return string.format("%02d:%02d", math.floor(seconds / 60), seconds % 60)
                end
                local spawns = workspace:FindFirstChild("__Extra") and workspace.__Extra:FindFirstChild("__Spawns")
                local activeMap = currentStorm(spawns, now)
                events.currentStormMap = activeMap
                local stormStatus
                if activeMap then
                    stormStatus = mapInfo[activeMap].Name .. " · ativa"
                    if events.stormUntil > now and events.stormMap == activeMap then stormStatus ..= " · estimativa " .. clock(events.stormUntil - now) end
                elseif events.nextStormAt and events.nextStormAt > now then
                    stormStatus = clock(events.nextStormAt - now) .. " · previsão pelo último anúncio"
                else
                    stormStatus = "Aguardando sincronização do evento"
                end
                events.label.Text = "World Boss: " .. ((boss or events.bossUntil > now) and ((events.bossName or "Boss anunciado") .. " · ativo na arena") or "Aguardando nascimento") .. "\nStorm: " .. stormStatus .. "\nKamish: " .. state.kamish.status .. "\nGuild Boss: " .. (state.guildStatus or "Waiting for guild data…") .. "\n" .. (state.limitBreakStatus or "Limit Break: aguardando dados nativos.")
                for _,kind in ipairs(state.openRaidOrder) do
                    local raid=state.openRaids[kind]
                    local present=root and state.openRaidNearest(enemyFolder(),root.Position,kind,true)~=nil or false
                    state.openRaidObserve(raid,now,present)
                    raid.present=present
                    local text=not state.openRaidEnabled(raid.kind) and "Desligado."
                        or raid.travelStatus
                        or raid.huntStatus
                        or tonumber(storage:GetAttribute("World"))~=raid.world and ("Aguardando no Mundo "..raid.world..".")
                        or events.active==kind and (state.eventDestination and "Indo à ilha..." or root and state.openRaidNearest(enemyFolder(),root.Position,kind) and "Em combate." or "Aguardando próxima fase ou fim da raid.")
                        or state.openRaidAvailable(raid,storage:GetAttribute("World"),now,present) and "Raid detectada; aguardando prioridade."
                        or "Aguardando anúncio ou inimigos da raid."
                    raid.control.Caption.Text=text
                    events.label.Text ..= "\n"..raid.name..": "..text
                    -- Stream the native arrival point without moving or guessing event times.
                    if state.openRaidEnabled(raid.kind) and root and tonumber(storage:GetAttribute("World"))==raid.world and not insideDungeon()
                        and not present and not raid.streamBusy and now-(raid.streamAt or 0)>30 then
                        local probe=state.openRaidProbe(raid,spawns)
                        if probe then
                            raid.streamAt,raid.streamBusy=now,true
                            task.spawn(function()
                                pcall(function() player:RequestStreamAroundAsync(probe,1) end)
                                raid.streamBusy=nil
                            end)
                        end
                    end
                end
                worldBossToggle.Caption.Text = not (worldBoss.enabled and (not state.questPriorityAllows or state.questPriorityAllows("boss")) or state.questWantsEvent and state.questWantsEvent("boss")) and "Desligado." or "Independente do Auto Farm; aguarda nascer para viajar."
                if state.stormControl then
                    local waiting=uiState.language=="PT" and "Aguardando a próxima Storm."
                        or uiState.language=="ES" and "Esperando la próxima Storm." or "Waiting for the next Storm."
                    local active=uiState.language=="PT" and "Storm ativa: "
                        or uiState.language=="ES" and "Storm activa: " or "Storm active: "
                    state.stormControl.Caption.Text=not storm.enabled and "Desligado." or activeMap and (active..tostring(mapInfo[activeMap].Name)) or waiting
                end
                if state.questPriorityActive and state.questPriorityActive() and events.active and not state.questWantsEvent(events.active) then finish();return end
                if events.active == "guild" or events.active == "kamish" then return end
                local priority = state.collectionPriority()
                if priority then
                    if events.active then finish() end
                    state.eventDestination, state.eventTravel = nil, nil
                    return
                end
                local allowed = not insideDungeon() and not state.leaving and not state.rebirthing
                if not allowed or not root then
                    if events.active then finish() end
                    return
                end
                if player.GameplayPaused or player:GetAttribute("Mounted") or player:GetAttribute("Swimming") then return end
                if events.active then
                    if events.active=="giants" and state.stepGiantsHunt then
                        local raid=state.openRaids.giants
                        state.openRaidFinalDeath()
                        if not state.openRaidEnabled(raid.kind) or raid.closed or raid.ended or now>=(raid.untilAt or 0) then finish() return end
                        if state.stepGiantsHunt(root,spawns,now) then return end
                    end
                    if events.active=="storm" then
                        for _,kind in ipairs(state.openRaidOrder) do
                            local raid=state.openRaids[kind]
                            if state.openRaidAvailable(raid,storage:GetAttribute("World"),now,raid.present) then finish() return end
                        end
                    end
                    if events.active == "storm" and (worldBoss.enabled and (not state.questPriorityAllows or state.questPriorityAllows("boss")) or state.questWantsEvent and state.questWantsEvent("boss")) and (boss or events.bossUntil > now) then finish() return end
                    if state.eventTravel then
                        local travel = state.eventTravel
                        if (root.Position - travel.position).Magnitude <= 65 then
                            state.eventTravel, events.arrived = nil, now
                        elseif now - travel.at > 8 then
                            events.retryAt = now + 60
                            finish()
                        end
                        return
                    end
                    if state.openRaids[events.active] then
                        local raid=state.openRaids[events.active]
                        if state.openRaidFinalDeath then state.openRaidFinalDeath() end
                        if not state.openRaidEnabled(raid.kind) or raid.ended or raid.closed or tonumber(storage:GetAttribute("World"))~=raid.world
                            or now>=(raid.untilAt or 0) then
                            if now>=(raid.untilAt or 0) then raid.closed,raid.closedAt=true,now end
                            finish()
                        end
                    elseif events.active == "boss" then
                        if boss then events.sawBoss, events.lastSeen = true, now end
                        if not (worldBoss.enabled and (not state.questPriorityAllows or state.questPriorityAllows("boss")) or state.questWantsEvent and state.questWantsEvent("boss")) or (events.sawBoss and now - (events.lastSeen or now) > 4)
                            or (not events.sawBoss and now - (events.arrived or now) > 18) then finish() end
                    elseif not storm.enabled or not activeMap or (events.active == "storm" and activeMap ~= events.travelStormMap) then finish() end
                    return
                end
                if state.raidTravel and state.raidTravel.phase~="arrived" then return end
                if state.eventDestination or now < (events.retryAt or 0) or now < (state.entryUntil or 0) then return end
                local spawns = workspace:FindFirstChild("__Extra") and workspace.__Extra:FindFirstChild("__Spawns")
                local kind, island
                if (worldBoss.enabled and (not state.questPriorityAllows or state.questPriorityAllows("boss")) or state.questWantsEvent and state.questWantsEvent("boss")) and (boss or events.bossUntil > now) then
                    kind, island = "boss", "Arena"
                else
                    for _,candidate in ipairs(state.openRaidOrder) do
                        local raid=state.openRaids[candidate]
                        if (not state.raidTravel or state.raidTravel.kind==candidate)
                            and state.openRaidAvailable(raid,storage:GetAttribute("World"),now,raid.present) then
                            kind,island=candidate,raid.spawn or candidate
                            break
                        end
                    end
                    if not kind and storm.enabled and activeMap and (not state.questPriorityAllows or state.questPriorityAllows("storm")) then
                        kind,island="storm",activeMap
                        if tonumber(mapInfo[island].World)~=tonumber(storage:GetAttribute("World")) then return end
                    end
                end
                local raid=state.openRaids[kind]
                local spawn=island and spawns and spawns:FindFirstChild(island)
                local position,problem
                if raid then position,problem=state.openRaidPosition(raid,spawns)
                elseif spawn then position=spawn:GetPivot().Position end
                if not position then
                    if raid then raid.travelStatus=problem;raid.retryAt=now+5 end
                    return
                end
                if raid then
                    raid.travelStatus=nil
                    if state.beginRaidJourney and not state.beginRaidJourney(kind,root,tonumber(storage:GetAttribute("World"))) then return end
                end
                events.active, events.returnPosition, events.returnMap = kind, root.Position, state.map
                events.returnWorld=tonumber(storage:GetAttribute("World"))
                events.mapOrder = kind == "storm" and tostring(mapInfo[island].Order) or nil
                events.travelStormMap = kind == "storm" and island or nil
                events.sawBoss, events.lastSeen, events.arrived = false, nil, nil
                -- The pumpkin controller observes events.active and releases movement.
                state.target, state.searchPosition, state.map = nil, nil, events.mapOrder
                generation += 1
                if state.openRaids[kind] then
                    -- Native arrival markers, or a raycast-confirmed floor for Giants.
                    -- Reuse the hub's local movement path; never invent a remote request.
                    if (root.Position-position).Magnitude>15 then state.eventDestination=position+Vector3.new(0,3,0) end
                    events.arrived=now
                elseif (root.Position - position).Magnitude > 65 then
                    state.eventTravel = {position = position, at = now}
                    general:Fire({Event = "IslandTeleport", Island = island})
                else events.arrived = now end
            end)
            if not success then
                events.retryAt = workspace:GetServerTimeNow() + 60
                finish()
                events.label.Text = "Eventos: aguardando nova leitura."
                warn("[VykronHub] Eventos: " .. tostring(problem))
            end
        end
    end)
end


-- NATIVE INFERNAL AFK: snapshot user preferences and restore only owned settings.
do
    local menu, settingsModule, rows
    local function prepare()
        if rows then return end
        menu = require(storage.Indexer.SettingsMenu)
        settingsModule = require(shared.Others.SettingsModule)
        rows = {}
        local visited = {}
        local function scan(value)
            if type(value) ~= "table" or visited[value] then return end
            visited[value] = true
            if value.Id then rows[value.Id] = value end
            for _, child in pairs(value) do if type(child) == "table" then scan(child) end end
        end
        scan(menu)
        assert(rows.AfkCastle and rows.AfksSettings, "Native AFK settings unavailable")
    end
    local function read(id) return clientData.Get("Settings", id) == true end
    local function apply(id, enabled)
        local values = assert(menu.Resolve(rows[id], enabled), "Native AFK setting unavailable")
        for key, value in pairs(values) do settingsModule.ChangeSettings(key, value, "Update") end
        general:Fire({Event = "SettingsSet", Row = id, Value = enabled})
    end
    function state.syncQuestAFK(mode)
        prepare()
        local keys={"AfkCastle","AfkResetD","AfkResetC","AfkResetL","AfkResetB","AfkResetDu","AfkTrial","AfkKey","AfksSettings"}
        local original=autoQuest.nativeAFK
        if mode then
            if not original then
                original={};for _,key in ipairs(keys) do original[key]=read(key) end
                autoQuest.nativeAFK=original
                if not save() then autoQuest.nativeAFK=nil;return false end
            end
            -- Only Infernal floor traversal may stay native; all automatic
            -- entries/replays must yield to the exact quest-owned mode.
            for _,key in ipairs(keys) do
                local desired=mode=="infernal" and (key=="AfkCastle" or key=="AfksSettings")
                if rows[key] and read(key)~=desired then apply(key,desired) end
            end
            for _,key in ipairs(keys) do
                local desired=mode=="infernal" and (key=="AfkCastle" or key=="AfksSettings")
                if rows[key] and read(key)~=desired then return false end
            end
            return true
        elseif original then
            for _,key in ipairs(keys) do if rows[key] and read(key)~=original[key] then apply(key,original[key]) end end
            autoQuest.nativeAFK=nil
            if not save() then autoQuest.nativeAFK=original;return false end
        end
        return true
    end
    function state.syncKeyAFK(wanted)
        prepare()
        if not rows.AfkKey then return false end
        if wanted then
            if not state.keyAFKOriginal then
                state.keyAFKOriginal={AfkKey=read("AfkKey"),AfksSettings=read("AfksSettings")}
                if not save() then state.keyAFKOriginal=nil;return false end
            end
            if not read("AfkKey") then apply("AfkKey",true) end
            if not read("AfksSettings") then apply("AfksSettings",true) end
            return read("AfkKey") and read("AfksSettings")
        end
        local original=state.keyAFKOriginal
        if original then
            if read("AfkKey")~=original.AfkKey then apply("AfkKey",original.AfkKey) end
            if not original.AfksSettings and read("AfksSettings") then
                local another=false
                for key in pairs(rows) do if key~="AfksSettings" and key:sub(1,3)=="Afk" and read(key) then another=true;break end end
                if not another then apply("AfksSettings",false) end
            end
            state.keyAFKOriginal=nil
            if not save() then state.keyAFKOriginal=original;return false end
        end
        return true
    end
    function state.syncCastleAFK(forceRestore)
        prepare()
        local owned = state.castleAFK
        local quest=state.questPriorityActive and state.questPriorityActive() or state.recurringQuestPolicy.enabled(autoQuest)
        if not quest and autoQuest.nativeAFK then state.syncQuestAFK(nil) end
        local keyWanted=not forceRestore and not quest and not state.panic and not state.stopped
            and dungeon.enabled==true and dungeon.autoKeys==true and dungeon.mode=="key"
        if not state.syncKeyAFK(keyWanted) then owned.status="Auto Keys: aguardando confirmar Usar Dungeon Keys no AFK nativo.";return end
        if not forceRestore and quest then
            local mode=autoQuest.journey and autoQuest.journey.mode or "waiting"
            if state.limitBreakerStormRequested and state.limitBreakerStormRequested() then mode="waiting" end
            state.syncQuestAFK(mode);owned.status="Auto Quest: AFK limitado ao modo exigido ("..mode..").";return
        end
        local wanted = not forceRestore and not state.panic and ((dungeon.enabled == true and dungeon.mode == "infernal")
            or state.questOwnsRun and state.questOwnsRun("infernal"))
        if wanted then
            if not read("AfksSettings") then
                for _, key in ipairs({"AfkResetD", "AfkResetC", "AfkResetL", "AfkResetB", "AfkResetDu", "AfkTrial", "AfkKey"}) do
                    if read(key) then
                        owned.status = "Enable AFK Mode manually: other native key/restart actions are configured."
                        return
                    end
                end
            end
            if not owned.original then
                owned.original = {AfkCastle = read("AfkCastle"), AfksSettings = read("AfksSettings")}
                if not save() then owned.original = nil error("Could not save native AFK preferences") end
            end
            if not read("AfkCastle") or not read("AfksSettings") then apply("AfkCastle", true) end
            owned.status = "Native castle AFK enabled. Hub targets mobs only."
        elseif owned.original then
            local original = owned.original
            if read("AfkCastle") ~= original.AfkCastle then apply("AfkCastle", original.AfkCastle) end
            if not original.AfksSettings and read("AfksSettings") then
                local another = false
                for key in pairs(rows) do
                    if key ~= "AfkCastle" and key ~= "AfksSettings" and key:sub(1,3) == "Afk" and read(key) then another = true break end
                end
                if not another then apply("AfksSettings", false) end
            end
            owned.original = nil
            save()
            owned.status = "Native AFK preferences restored."
        else
            owned.status = read("AfkCastle") and read("AfksSettings") and "Native castle AFK is ON." or "Enable Infernal Castle Floors in game Settings > AFK Mode."
        end
    end
    task.spawn(function()
        while alive do
            local ok, problem = pcall(state.syncCastleAFK)
            if not ok then state.castleAFK.status = "Enable Infernal Castle Floors in game Settings > AFK Mode. " .. tostring(problem):sub(1,90) end
            task.wait(2)
        end
    end)
    table.insert(cleanupCallbacks, function() pcall(state.syncCastleAFK, true) end)
end
-- END NATIVE INFERNAL AFK

-- Death evidence is independent of distance/streaming: only native Dead or HP <= 0.
function state.kamishDeathConfirmed(enemy)
    if not enemy then return false end
    local ok,result=pcall(function()
        if enemy:GetAttribute("Id")~="NightmareKamish" then return false end
        if enemy:GetAttribute("Dead")==true then return true end
        local hp=tonumber(enemy:GetAttribute("HP"))
        if hp and hp==hp and hp<=0 then return true end
        local read,value=pcall(enemyState.HP,enemy)
        hp=read and tonumber(value) or nil
        if hp and hp==hp and hp<=0 then return true end
        return enemyState.Dead(enemy)==true
    end)
    return ok and result==true
end
function state.suspendKamish(cycle,outcome)
    cycle=cycle or state.kamishCycleAt(workspace:GetServerTimeNow())
    state.kamish.handledSpawn=cycle
    state.kamish.suspendUntil=cycle+1800-120
    state.kamish.lastOutcome=outcome
    state.kamish.observedBoss,state.kamish.observedCycle=nil,nil
    save()
end
-- KAMISH EVENT: twice-hourly reservation, native mode exit and arena arrival before :26 / :56.
do
    local run = {}
    local requestAt = -math.huge
    local function release()
        state.kamishTakingOver = nil
        if events.active == "kamish" then
            events.active = nil
            state.target, state.worldBossTarget, state.searchPosition = nil, nil, nil
            if not insideDungeon() and run.world == storage:GetAttribute("World") then
                state.eventDestination, state.map = run.position, run.map
            end
            generation += 1
        end
        run = {}
    end
    function state.kamishStep()
        local now = workspace:GetServerTimeNow()
        local boss = state.kamishBoss()
        local spawn = state.kamishWindow(now)
        local nextSpawn = state.kamishNextSpawn(now)
        local displaySpawn = spawn or nextSpawn
        local spawnMinute = state.kamishSpawnMinute(displaySpawn)
        local prepareMinute = state.kamishPrepareMinute(displaySpawn)
        if state.questPriorityActive and state.questPriorityActive() then release();state.eventDestination=nil;state.kamish.status="Auto Quest: Kamish pausado.";return end
        if not state.kamish.enabled or state.panic then
            state.kamish.status = state.panic and "Paused." or "Off. · next " .. state.kamishSpawnMinute(nextSpawn) .. " · " .. state.kamishClock()
            release() return
        end
        if state.kamishDeathConfirmed(state.kamish.observedBoss) then
            state.suspendKamish(state.kamish.observedCycle or run.spawn or spawn,"death_confirmed")
            release()
            state.kamish.status="Kamish defeated: waiting for the next 30-minute spawn."
            return
        end
        if not state.kamishDue() then
            release()
            state.kamish.status = now < (state.kamish.suspendUntil or 0)
                and ("Kamish suspended · next spawn " .. state.kamishSpawnMinute(nextSpawn) .. " · " .. state.kamishClock())
                or ("Spawn " .. state.kamishSpawnMinute(nextSpawn) .. " · " .. state.kamishClock() .. " · arena arrival " .. state.kamishPrepareMinute(nextSpawn))
            return
        end
        if boss then
            state.kamish.observedBoss=boss
            state.kamish.observedCycle=spawn or state.kamishCycleAt(now)
        end
        if state.keyRunBlocksExit() then
            release()
            state.kamish.status="Kamish: waiting for the current island key stock to finish."
            return
        end
        state.kamishTakingOver = true
        if insideDungeon() then
            local remaining=spawn and math.max(0,math.ceil(spawn-60-now)) or 0
            state.kamish.status = "Kamish: requesting mode exit now · target "..prepareMinute.." · "..remaining.."s · waiting for server confirmation."
            if now >= requestAt + 8 then
                requestAt = now
                state.requestDungeonExit()
            end
            return
        end
        if state.guild.journey then
            state.kamish.status = "Kamish priority: returning from the guild arena before travelling to the Kamish arena."
            return
        end
        if tonumber(storage:GetAttribute("World")) ~= 3 then
            state.kamish.status = "Kamish: travelling to World 3; arena arrival target " .. prepareMinute .. "."
            if now >= requestAt + 10 then
                requestAt = now
                if (tonumber(clientData.Get("Rank")) or 0) < 20 then
                    state.kamish.status = "Kamish: World 3 locked by rank requirement." return
                end
                local ok, session = pcall(function()
                    assert(save(), "Could not save teleport preferences")
                    return assert(loadstring(readfile("VykronHub/AutoExecute.luau")))(player.UserId, false)
                end)
                if ok and session and session.queued then general:Fire({Event = "WorldTeleport", World = "World3"})
                else state.kamish.status = "Kamish: unable to prepare Auto Execute for World 3 teleport." end
            end
            return
        end
        if events.active and events.active ~= "kamish" then
            state.kamish.status = "Kamish priority: waiting for "..tostring(events.active).." to release movement." return
        end
        local root = rootPart()
        if not root or player.GameplayPaused or player:GetAttribute("Mounted") or player:GetAttribute("Swimming") then
            state.kamish.status = "Kamish: waiting for a ready, unmounted character." return
        end
        if state.leaving or state.rebirthing then return end
        if events.active ~= "kamish" then
            if state.eventTravel or state.eventDestination then
                state.eventTravel,state.eventDestination=nil,nil
            end
            run = {position = root.Position, map = state.map, world = storage:GetAttribute("World"), spawn = spawn}
            events.active = "kamish"
            state.target, state.searchPosition, state.map = nil, nil, nil
            generation += 1
        end
        if boss then
            run.sawBoss, run.lastSeen = true, now
            state.target, state.worldBossTarget, state.searchPosition = boss, boss, nil
            state.kamish.status = "Nightmare Kamish alive: attacking."
            return
        end
        if run.sawBoss and now - (run.lastSeen or now) >= 5 then
            state.suspendKamish(run.spawn or spawn,"disappeared_unconfirmed")
            release()
            state.kamish.status = "Kamish disappeared; death unconfirmed. Other modes released for this cycle."
            return
        end
        if spawn and now >= spawn + 120 and not run.sawBoss then
            state.suspendKamish(spawn,"not_found")
            release()
            state.kamish.status = "Kamish not found for " .. spawnMinute .. "; waiting for the next 30-minute spawn."
            return
        end
        local main = workspace:FindFirstChild("__Main")
        local world = main and main:FindFirstChild("__World")
        local island = world and world:FindFirstChild("Eclipse Necropolis")
        local markers = island and island:FindFirstChild("Marcadores")
        local arena = markers and markers:FindFirstChild("KamishArena")
        local position = arena and arena:IsA("BasePart") and arena.Position or Vector3.new(-327, 19.3, -2153)
        if (root.Position - position).Magnitude > 15 then state.eventDestination = position + Vector3.new(0,3,0) end
        if now >= (run.streamAt or 0) then
            run.streamAt = now + 5
            task.spawn(function() pcall(function() player:RequestStreamAroundAsync(position, 1) end) end)
        end
        state.target, state.searchPosition = nil, nil
        local left = spawn and math.max(0, math.ceil(spawn - now)) or 0
        state.kamish.status = "Arena reserved · spawn " .. spawnMinute .. " · " .. string.format("%02d:%02d",math.floor(left/60),left%60)
    end
    task.spawn(function()
        while alive do
            local ok, problem = pcall(state.kamishStep)
            if not ok then release() state.kamish.status = "Kamish: " .. tostring(problem):sub(1,120) end
            if state.kamishToggle then state.kamishToggle.Caption.Text = state.kamish.status end
            task.wait(0.5)
        end
    end)
    table.insert(cleanupCallbacks, release)
end
-- END KAMISH EVENT

-- GUILD CONTROLLER: native state, permission checks and acknowledged arena entry.
do
    local run = {retryAt = 0, nextRefresh = 0, claimAt = 0, claimAudit = 0}
    local guildRelease = require(shared.Release)
    local native, info
    -- GUILD AVAILABILITY: a timer or pending summon alone does not own dungeon movement.
    function state.guildBossUsable(boss, now, endedKey, guildId, hpIsZero)
        if type(boss) ~= "table" or boss.Ended == true or type(boss.BossId) ~= "string" then return false end
        local endsAt = tonumber(boss.EndsAt)
        if not endsAt or endsAt ~= endsAt or endsAt == math.huge or endsAt <= now then return false end
        if boss.HpKnown == true and hpIsZero == true then return false end
        local key = state.guildBossKey(boss, guildId)
        return key ~= nil and key ~= endedKey
    end
    local function currentBoss(now)
        if not native then return nil end
        local boss = native.Boss()
        local zero = false
        if type(boss) == "table" and boss.HpKnown == true and boss.Hp ~= nil then
            local ok, result = pcall(function() return boss.Hp <= native.Big(0) end)
            zero = ok and result == true
        end
        if state.guildBossUsable(boss, now, run.endedBossKey, clientData.Get("Guild"), zero) then return boss end
        return nil
    end
    function state.guildPriorityActive()
        if state.questPriorityActive and state.questPriorityActive() then return false end
        local journey = state.guild.journey
        if not state.guild.enabled or not journey or journey.phase == "return" then
            if events.active == "guild" then events.active = nil end
            return false
        end
        local now = workspace:GetServerTimeNow()
        if journey.phase == "summon" or not currentBoss(now) then
            if events.active == "guild" then events.active = nil end
            return false
        end
        return events.active == "guild"
    end
    function state.guildRefresh()
        run.nextRefresh = 0
        if not state.guild.journey then run.retryAt = 0 end
    end
    local function getNative()
        if native then return native end
        local scripts = player:FindFirstChild("PlayerScripts")
        local ui = scripts and scripts:FindFirstChild("NewUI", true)
        local screens = ui and ui:FindFirstChild("Screens")
        local guilds = screens and screens:FindFirstChild("Guilds")
        local loaded = require(assert(guilds and guilds:FindFirstChild("State"), "Interface de guilda indisponível"))
        local definitions = require(storage.Indexer.GuildInfo)
        native, info = loaded, definitions
        state.guildEnemyIds = {}
        for _, id in ipairs(info.Bosses.Order or {}) do state.guildEnemyIds[info.Bosses[id].Enemy] = id end
        return native
    end
    local function clock(seconds)
        seconds = math.max(0, math.ceil(seconds))
        return string.format("%02d:%02d:%02d", math.floor(seconds / 3600), math.floor(seconds / 60) % 60, seconds % 60)
    end
    local function labelStatus(text)
        state.guildStatus = text
        if state.guildLabel then state.guildLabel.Text = text end
        if state.guildFarmRow then state.guildFarmRow.Caption.Text = text end
    end
    local function clearOwnedEvent()
        state.guildTarget = nil
        if events.active == "guild" then
            events.active = nil
            state.target, state.searchPosition, state.worldBossTarget = nil, nil, nil
            state.eventTravel, state.eventDestination = nil, nil
            generation += 1
        end
    end
    local function finishJourney(message)
        local journey = state.guild.journey
        clearOwnedEvent()
        state.guild.journey = nil
        if journey and not insideDungeon() and not events.active then state.map = journey.originMap end
        run.arenaGranted, run.searchStarted, run.lastEnemyAt = nil, nil, nil
        run.retryAt, run.returnQueued = workspace:GetServerTimeNow() + 60, nil
        save()
        labelStatus(message)
    end
    local function requestReturn(message)
        local journey = state.guild.journey
        if not journey then return end
        journey.phase, journey.returnMessage = "return", message
        journey.returnAttempts, journey.returnAt = journey.returnAttempts or 0, journey.returnAt or 0
        state.target, state.guildTarget, state.searchPosition = nil, nil, nil
        -- Libera outras automações durante o retorno/aguardo
        if events.active == "guild" then events.active = nil end
        generation += 1
        save()
    end
    local function returnStep(now)
        local journey, root = state.guild.journey, rootPart()
        if not journey or not root or player.GameplayPaused then return end
        if events.active == "guild" then events.active = nil end
        local world = tonumber(storage:GetAttribute("World"))
        if world ~= journey.originWorld then
            labelStatus("Retornando ao mundo " .. journey.originWorld .. "...")
            if now < (journey.returnAt or 0) then return end
            if (journey.returnAttempts or 0) >= 3 then finishJourney("Falha ao retornar ao mundo inicial. Retorno manual necessário.") return end
            journey.nextWorld = journey.originWorld
            if not save() then labelStatus("Retorno aguardando gravação do percurso.") return end
            local ok, session = pcall(function()
                return assert(loadstring(readfile("VykronHub/AutoExecute.luau")))(player.UserId, false)
            end)
            if not ok or not session or not session.queued then finishJourney("Continuidade indisponível. Retorne ao mundo inicial manualmente.") return end
            journey.returnAttempts, journey.returnAt = (journey.returnAttempts or 0) + 1, now + 20
            if not save() then return end
            general:Fire({Event = "WorldTeleport", World = "World" .. journey.originWorld})
            return
        end
        local p = journey.originPosition
        local destination = p and Vector3.new(p.x, p.y, p.z)
        if destination and (root.Position - destination).Magnitude > 8 then
            root.AssemblyLinearVelocity = Vector3.zero
            root.CFrame = CFrame.new(destination)
            state.lastFarmPosition = destination
        end
        local character = player.Character
        if character then character:SetAttribute("InGuild", journey.originInGuild == true) end
        if journey.petsVisible and player:GetAttribute("PetsArise") ~= true then
            state.pausableBridge(require(storage.BridgeNet2).ReferenceBridge("PET_EVENT")):Fire({Event = "ShowPets"})
        end
        finishJourney(journey.returnMessage or "Chefe finalizado. Farm anterior liberado.")
    end
    function state.guildNearest(position)
        if not run.arenaGranted or run.bossMissing or run.shareReached then return nil end
        local journey, folder = state.guild.journey, enemyFolder()
        local selected, distance
        local myGuild = clientData.Get("Guild")
        for _, enemy in ipairs(folder and folder:GetChildren() or {}) do
            if living(enemy, folder) and state.guildEnemyIds and state.guildEnemyIds[enemy:GetAttribute("Id")] == (journey and journey.bossId) then
                local d = (enemy.Position - position).Magnitude
                local owner = enemy:GetAttribute("GuildBoss")
                -- Native rendering hides other guilds' enemies using this attribute.
                local owned = type(myGuild) == "string" and myGuild ~= "" and owner == myGuild
                if (owned or owner == nil and d <= 1500) and (not distance or d < distance) then selected, distance = enemy, d end
            end
        end
        return selected
    end
    local function beginJourney(now, bossId, phase)
        local root = rootPart()
        local world = tonumber(storage:GetAttribute("World"))
        if not root or not world or world < 1 or world > 3 then return false end
        local origin = events.returnPosition or root.Position
        local character = player.Character
        state.guild.journey = {phase = phase, bossId = bossId, startedAt = now, originWorld = world,
            originPosition = {x = origin.X, y = origin.Y, z = origin.Z}, originMap = events.returnMap or state.map,
            originInGuild = character and character:GetAttribute("InGuild") == true or false,
            petsVisible = player:GetAttribute("PetsArise") == true, enterAttempts = 0, enterAt = 0}
        if not save() then state.guild.journey = nil run.retryAt = now + 30 labelStatus("Entrada cancelada: falha ao salvar o retorno.") return false end
        state.target, state.searchPosition, state.worldBossTarget = nil, nil, nil
        state.eventTravel, state.eventDestination = nil, nil
        state.pumpkinBusy, pumpkin.target, pumpkin.travel = nil, nil, nil
        state.houses.busy, state.houses.destination, state.houses.travel, state.houses.fighting = nil, nil, nil, nil
        events.active = phase == "enter" and "guild" or nil
        generation += 1
        return true
    end
    local subscription = require(storage.BridgeNet2).ReferenceBridge("GUILD_EVENT"):Connect(function(packet)
        if not alive or type(packet) ~= "table" then return end
        if packet.Event == "GuildArena" and state.guild.journey and state.guild.journey.phase ~= "return" then
            run.arenaReply = packet.Ok == true
            run.arenaGranted = packet.Ok == true
        elseif packet.Event == "GuildBoss" and type(packet.State) == "table" and packet.State.Ended ~= true then
            -- A newly announced boss can be joined without waiting for a failed
            -- earlier summoning attempt's backoff to expire.
            if not state.guild.journey then run.retryAt = 0 end
        elseif packet.Event == "GuildBoss" and type(packet.State) == "table" and packet.State.Ended == true then
            run.endedBossKey = state.guildBossKey(packet.State, clientData.Get("Guild"))
            if events.active == "guild" then events.active = nil end
            local capped = state.guild.cappedBoss
            if capped and state.guildBossKey(packet.State, clientData.Get("Guild")) == capped.key then
                state.guild.cappedBoss, run.shareReached = nil, nil
                save()
            end
        end
    end)
    table.insert(cleanupCallbacks, function() subscription:Disconnect() clearOwnedEvent() end)
    local warning = require(storage.BridgeNet2).ReferenceBridge("WARN_EVENT"):Connect(function(packet)
        local journey = state.guild.journey
        if not alive or not journey or journey.phase == "return" or not run.arenaGranted
            or type(packet) ~= "table" or not state.guildShareNotice(packet.Message) then return end
        local boss = native and native.Boss()
        local guildId = clientData.Get("Guild") or journey.bossGuild
        local key = state.guildBossKey(boss, guildId) or journey.bossKey
        local endsAt = boss and tonumber(boss.EndsAt) or journey.bossEndsAt
        if key and endsAt then state.guild.cappedBoss = {key = key, guildId = guildId, endsAt = endsAt} end
        run.shareReached = true
        run.arenaGranted = nil
        requestReturn("Limite de 25% atingido. Aguardando a guilda terminar o chefe.")
        labelStatus("Limite de 25% atingido. Retornando ao farm anterior...")
        if not state.panic and not insideDungeon() and not player.GameplayPaused then
            local ok, problem = pcall(returnStep, workspace:GetServerTimeNow())
            if not ok then labelStatus("Retorno da guilda aguardando nova tentativa: " .. tostring(problem)) end
        end
    end)
    table.insert(cleanupCallbacks, function() warning:Disconnect() end)
    local function claimStep(now)
        local row = state.guildClaimRow
        if not row then return end
        if not autoClaim.guild then row.Caption.Text = "Desligado." return end
        if not native.Guild then row.Caption.Text = "Entre em uma guilda para resgatar missões." return end
        if not guildRelease.IsOpen("BloodMoon") then row.Caption.Text = "Conteúdo ainda não liberado pelo jogo." return end
        if type(native.Live) ~= "table" then row.Caption.Text = "Aguardando informações da guilda..." return end
        local ids = state.guildClaimable(native.Missions())
        local signature = tostring(native.WeekNumber()) .. ":" .. table.concat(ids, ",")
        row.Caption.Text = #ids > 0 and ("Missões prontas para resgate: " .. #ids)
            or "Aguardando missões concluídas. Os farms ativos contribuem para os objetivos."
        if #ids == 0 then
            -- Native Claim All also handles eligible rewards left from the previous week.
            if now >= run.claimAudit then run.claimAudit = now + 60 native.Request("ClaimMissions") end
            return
        end
        if signature ~= run.claimSignature then run.claimSignature, run.claimAt, run.claimAttempts = signature, 0, 0 end
        if now < run.claimAt then return end
        run.claimAttempts = (run.claimAttempts or 0) + 1
        run.claimAt = now + math.min(60, run.claimAttempts * 15)
        native.Request("ClaimMissions")
        row.Caption.Text = "Resgate solicitado. Aguardando confirmação da guilda."
    end
    local function step()
        local now = workspace:GetServerTimeNow()
        local journey = state.guild.journey
        if journey and journey.phase == "return" then
            if insideDungeon() then finishJourney("Guilda suspensa. Partida atual liberada.") return end
            if not state.leaving and not state.autoLeaving and not state.rebirthing then returnStep(now) end
            return
        end
        if not state.guild.enabled and journey and journey.phase ~= "return" then requestReturn("Chefe desativado. Retomando o farm anterior.") end
        if not state.guild.enabled and not autoClaim.guild and not journey then labelStatus("Desligado.") return end
        -- Reward claims are independent of combat/return and may run during a dungeon.
        if not native then labelStatus("Consultando dados e permissões da guilda...") end
        getNative()
        if not player.GameplayPaused then
            if now >= run.nextRefresh then
                run.nextRefresh = now + 15
                local synced, syncProblem = pcall(function() native.Request("Snapshot") native.Request("Open") end)
                run.syncProblem = not synced and tostring(syncProblem) or nil
            end
            -- Claim failures must not abort summoning or arena combat.
            local claimed, claimProblem = pcall(claimStep, now)
            if not claimed and state.guildClaimRow then
                state.guildClaimRow.Caption.Text = "Resgate da guilda em espera: " .. tostring(claimProblem)
            end
        end
        if insideDungeon() or state.leaving or state.autoLeaving or state.rebirthing then
            if events.active == "guild" then events.active = nil end
            if journey and insideDungeon() then finishJourney("Guilda suspensa. Partida atual liberada.") end
            if state.guild.enabled then labelStatus("Aguardando concluir a partida ou ação atual.") end
            return
        end
        if journey and journey.phase == "return" then returnStep(now) return end
        if state.collectionPriority() then
            if journey then requestReturn("Collection has priority. Returning to the previous world…")
            else labelStatus("Waiting for Haunted Houses / Pumpkins collection.") end
            return
        end
        if player.GameplayPaused then labelStatus("Aguardando carregar o personagem e a área da guilda...") return end
        local boss = currentBoss(now)
        if not journey and events.active == "guild" then clearOwnedEvent() end
        local capped = state.guild.cappedBoss
        if capped then
            local guildId = clientData.Get("Guild")
            local key = state.guildBossKey(boss, guildId)
            if (type(guildId) == "string" and guildId ~= "" and guildId ~= capped.guildId)
                or now >= capped.endsAt or (key and key ~= capped.key) then
                state.guild.cappedBoss, run.shareReached = nil, nil
                save()
            else
                -- Limpa events.active para liberar outras automações enquanto aguarda a guilda terminar
                if events.active == "guild" then events.active = nil end
                if journey then requestReturn("Limite de 25% atingido. Aguardando a guilda terminar o chefe.")
                else labelStatus("Limite de 25% atingido. Aguardando a guilda terminar o chefe.") end
                return
            end
        end
        if journey then
            if not native.Guild then requestReturn("Guilda indisponível. Retomando o farm anterior.") return end
            if journey.phase == "summon" then
                if events.active == "guild" then events.active = nil end
                if boss then journey.bossId, journey.phase = boss.BossId, "enter" save()
                elseif now - (tonumber(journey.startedAt) or now) >= 20 then
                    finishJourney("Invocação sem confirmação. Nova tentativa após intervalo.")
                else labelStatus("Invocação solicitada. Aguardando o chefe...") end
                return
            end
            if not boss then
                clearOwnedEvent()
            else
                events.active = "guild"
            end
            local root = rootPart()
            if not root then labelStatus("Aguardando personagem para entrar na arena...") return end
            if boss and boss.BossId ~= journey.bossId then
                journey.bossId, journey.phase, journey.enterAttempts, journey.enterAt = boss.BossId, "enter", 0, 0
                run.arenaReply, run.arenaGranted, run.searchStarted = nil, nil, nil
                save()
            end
            local target = state.guildNearest(root.Position)
            if not boss then
                run.bossMissing = true
                run.endedAt = run.endedAt or now
                if now - run.endedAt >= 4 then requestReturn("Chefe encerrado. Retomando o farm anterior.") end
                return
            end
            run.endedAt = nil
            run.bossMissing = nil
            journey.bossKey = state.guildBossKey(boss, clientData.Get("Guild"))
            journey.bossEndsAt = tonumber(boss.EndsAt)
            journey.bossGuild = clientData.Get("Guild")
            if target and run.arenaGranted then
                if journey.phase ~= "combat" then journey.phase = "combat" save() end
                run.lastEnemyAt, run.arenaReply = now, nil
                run.searchStarted = nil
                state.guildTarget = target
                labelStatus((boss.Name or "Chefe da Guilda") .. " · combate · resta " .. clock((boss.EndsAt or now) - now))
                return
            end
            state.guildTarget, state.target = nil, nil
            if journey.phase == "combat" and now - (run.lastEnemyAt or now) > 25 then
                requestReturn("Chefe fora de alcance ou sem confirmação. Retomando o farm.") return
            end
            if run.arenaReply == false then requestReturn("Não foi possível entrar na arena da guilda.") return end
            if run.arenaGranted then
                run.searchStarted = run.searchStarted or now
                if now - run.searchStarted >= 45 then requestReturn("Arena confirmada, mas o chefe não carregou. Retomando o farm.") return end
                labelStatus("Arena confirmada. Localizando " .. (boss.Name or "Chefe da Guilda") .. "...")
                if not run.streamBusy and now >= (run.streamAt or 0) and type(player.RequestStreamAroundAsync) == "function" then
                    run.streamAt, run.streamBusy = now + 5, true
                    local destination = root.Position
                    task.spawn(function()
                        pcall(function() player:RequestStreamAroundAsync(destination, 1) end)
                        run.streamBusy = nil
                    end)
                end
                return
            end
            if now < (journey.enterAt or 0) then labelStatus("Aguardando entrada na arena ou carregamento do chefe...") return end
            if (journey.enterAttempts or 0) >= 3 then requestReturn("Não foi possível entrar na arena da guilda.") return end
            journey.enterAttempts, journey.enterAt = (journey.enterAttempts or 0) + 1, now + 15
            run.arenaReply = nil
            save()
            if state.panic then return end
            native.GoArena()
            labelStatus("Entrando na arena da guilda · tentativa " .. journey.enterAttempts .. "/3...")
            return
        end
        local level = native.Level()
        -- Match the native guild panel's daily quota and effective permissions.
        local summonsLeft, nextSummonAt = info.BossSummons(native.Live, now)
        local action, detail = state.guildDecision(state.guild, {inside = false, open = guildRelease.IsOpen("BloodMoon"),
            inGuild = native.Guild ~= nil, synced = type(native.Live) == "table", boss = boss,
            canStart = native.Can("StartBoss"), level = tonumber(level and level.Level) or 0,
            now = now, nextAt = summonsLeft > 0 and 0 or nextSummonAt}, info.Bosses)
        if not action then
            local status = {off = "Desligado.", release = "Conteúdo ainda não liberado pelo jogo.", no_guild = "Entre em uma guilda para usar esta opção.",
                sync = "Aguardando informações da guilda...", permission = "Seu cargo não tem permissão para invocar.", level = "A guilda ainda não tem o nível do chefe escolhido."}
            local nextAt = tonumber(nextSummonAt)
            labelStatus(detail == "cooldown" and (nextAt and ("Próxima invocação: " .. clock(nextAt - now)) or "Aguardando informações da guilda...") or status[detail] or "Aguardando chefe.")
            return
        end
        if now < run.retryAt then labelStatus("Nova tentativa em " .. clock(run.retryAt - now)) return end
        if beginJourney(now, detail, action == "summon" and "summon" or "enter") then
            run.arenaReply, run.arenaGranted, run.lastEnemyAt, run.endedAt, run.bossMissing = nil, nil, nil, nil, nil
            run.searchStarted = nil
            run.shareReached = nil
            if action == "summon" then
                labelStatus("Invocando " .. (info.Bosses[detail].Name or detail) .. ". Aguardando confirmação...")
                if state.panic then return end
                native.Request("StartBoss", {BossId = detail})
            else labelStatus("Chefe ativo encontrado. Preparando entrada na arena...") end
        end
    end
    task.spawn(function()
        clientData.WaitForLoaded()
        while alive do
            task.wait(1)
            if not alive then break end
            if state.panic then continue end
            if state.questPriorityActive and state.questPriorityActive() then
                if events.active=="guild" then events.active=nil;state.eventDestination=nil end
                labelStatus("Auto Quest: guilda pausada.");continue
            end
            local ok, problem = pcall(step)
            if not ok then
                run.retryAt = workspace:GetServerTimeNow() + 60
                if state.guild.journey then requestReturn("Guilda: operação interrompida. Retomando o farm.") end
                labelStatus("Guilda aguardando nova leitura: " .. tostring(problem))
                if autoClaim.guild and state.guildClaimRow then state.guildClaimRow.Caption.Text = "Resgate da guilda em espera: " .. tostring(problem) end
            end
        end
    end)
end
-- END GUILD CONTROLLER
-- Auto Claim: controles da janela antiga (só estado e texto de status). A lógica está em src/claim/auto-claim.lua.
do
    local rows = {}
    local entries = {
        {"daily", "Diárias"}, {"weekly", "Semanais"}, {"world", "Mundo"}, {"guild", "Missões da Guilda"},
        {"apex", "Auto Collect Apex"}, {"login", "Login diário"}, {"pass", "Passe"}, {"achievements", "Auto Conquistas"}, {"codes", "Auto Códigos"},
        {"candy", "Candy Road"}, {"cauldron", "Caldeirão"},
    }
    for _, entry in ipairs(entries) do
        local key = entry[1]
        local row = state.controlRow(entry[2], "Desligado.", claimPage)
        row.Name = "Claim_" .. key
        rows[key] = row
        if key == "guild" then state.guildClaimRow = row end
        toggleLook(row, autoClaim[key])
        connectUI(row, function() autoClaim[key] = not autoClaim[key] save() toggleLook(row, autoClaim[key]) end)
    end
    rows.spin = state.controlRow("Auto Spin Wheel", "Usa somente os giros disponíveis.", claimPage)
    rows.spin.Name = "Claim_spin"
    toggleLook(rows.spin, autoClaim.spin)
    connectUI(rows.spin, function() autoClaim.spin = not autoClaim.spin save() toggleLook(rows.spin, autoClaim.spin) end)
    state.claimRows = rows
end
-- Auto Claim: lógica (missões, recompensas, códigos, giro da roleta, passe, eventos). Escreve o status em rows[chave].Caption.
-- Os controles (rows) são criados em src/ui/antiga/auto-claim.lua.
do
    local rows = state.claimRows
    local stepCodes
    -- AUTO CODES: native Redeem All; no bundled list of expiring codes.
    do
    local function installAutoCodes()
        local active
        local key = "__REDEEM_ALL"
        local function onReply(packet)
            if not active or os.clock() > active.expires or type(packet) ~= "table" or type(packet.Message) ~= "string" then return end
            local text = packet.Message:gsub("<[^>]+>", ""):lower()
            if not (text:find("code", 1, true) or text:find("código", 1, true) or text:find("redeem", 1, true)) then return end
            local success = packet.WarnType == 4
            local noNew = text:find("already", 1, true) or text:find("no new", 1, true) or text:find("no code", 1, true)
            state.codeClaims[key] = {status = "deferred", nextAt = workspace:GetServerTimeNow() + ((success or noNew) and 900 or 180), attempts = 0}
            save()
            rows.codes.Caption.Text = success and "Redeem All confirmado. Novos códigos serão verificados automaticamente."
                or noNew and "Nenhum código novo disponível. Aguardando nova verificação."
                or "Resgate geral pendente: confira os requisitos do jogo."
            active = nil
        end
        local subscription = require(storage.BridgeNet2).ReferenceBridge("WARN_EVENT"):Connect(onReply)
        table.insert(cleanupCallbacks, function() subscription:Disconnect() end)
        stepCodes = function()
            if state.panic or not autoClaim.codes or player.GameplayPaused then return end
            local now = workspace:GetServerTimeNow()
            if active then
                if os.clock() <= active.expires then rows.codes.Caption.Text = "Resgatando todos os códigos disponíveis..." return end
                local attempts = (state.codeClaims[key] and state.codeClaims[key].attempts or 1)
                state.codeClaims[key] = {status = "deferred", nextAt = now + (attempts % 3 == 0 and 300 or 60), attempts = attempts}
                active = nil
                save()
                rows.codes.Caption.Text = "Redeem All sem confirmação; nova tentativa após a espera."
                return
            end
            local previous = state.codeClaims[key]
            if previous and previous.nextAt > now then return end
            local attempts = (previous and previous.attempts or 0) + 1
            state.codeClaims[key] = {status = "pending", nextAt = now + 30, attempts = attempts}
            if not save() then
                state.codeClaims[key] = previous
                rows.codes.Caption.Text = "Não foi possível salvar o resgate. Tentativa adiada."
                return
            end
            if state.panic then state.codeClaims[key] = previous save() return end
            active = {expires = os.clock() + 6}
            general:Fire({Event = "UseCode", All = true})
            rows.codes.Caption.Text = "Resgatando todos os códigos disponíveis..."
        end
    end
    installAutoCodes()
    end
    -- END AUTO CODES
    -- AUTO SPIN: native Spin receipts and animation duration replace the old 15/30-second wait.
    do
    local function installAutoSpin()
        local pending, busyUntil = nil, 0
        local subscription = general:Connect(function(packet)
            if type(packet) ~= "table" or packet.Event ~= "Spin" or type(packet.SpinInfo) ~= "table" then return end
            if not tonumber(packet.SpinInfo.Id) then return end
            local now = os.clock()
            busyUntil = now + (packet.Fast == true and 1.2 or 4) + 0.25
            if pending then pending.received = true end
        end)
        table.insert(cleanupCallbacks, function() subscription:Disconnect() end)
        local function stepSpin()
            if not autoClaim.spin then rows.spin.Caption.Text = "Desligado." return end
            if player.GameplayPaused then rows.spin.Caption.Text = "Aguardando carregamento..." return end
            local now, spins = os.clock(), tonumber(clientData.Get("Spins")) or 0
            if pending then
                if not pending.received and spins < pending.balance then
                    pending.received = true
                    -- If the receipt was missed, wait for the native duration from the first observed debit.
                    busyUntil = math.max(busyUntil, now + (clientData.Get("Settings", "FastSpin") == true and 1.2 or 4) + 0.25)
                end
                if pending.received then
                    if now < busyUntil then rows.spin.Caption.Text = "Giro solicitado. Aguardando conclusão." return end
                    pending = nil
                elseif now - pending.at < 6 then
                    rows.spin.Caption.Text = "Giro solicitado. Aguardando confirmação do jogo." return
                else pending = nil end
            end
            -- A manually started spin also keeps Auto Wheel from overlapping the native animation.
            if now < busyUntil then rows.spin.Caption.Text = "Giro solicitado. Aguardando conclusão." return end
            if spins < 1 then rows.spin.Caption.Text = "Sem giros disponíveis." return end
            pending = {balance = spins, at = now, received = false}
            rows.spin.Caption.Text = "Girando. Saldo anterior: " .. spins .. "."
            local ok, problem = pcall(function() general:Fire({Event = "SpinWheel"}) end)
            if not ok then rows.spin.Caption.Text = "Giro em espera: " .. tostring(problem) end
        end
        task.spawn(function()
            clientData.WaitForLoaded()
            while alive do
                task.wait(0.25)
                if not alive then break end
            if state.panic then continue end
                local ok, problem = pcall(stepSpin)
                if not ok then rows.spin.Caption.Text = "Giro em espera: " .. tostring(problem) end
            end
        end)
    end
    installAutoSpin()
    end
    -- END AUTO SPIN
    local pending, eventShared = {}, nil
    local battlePass, definitions, totalDays, achievementsCatalog
    -- PASS CATALOG: native reward schema, resolved in the executor's own context.
    local rewardCatalogs = {}
    local rewardModules = {Items = "ItemsInfo", Pets = "PetsInfo", Weapons = "WeaponsInfo", Mounts = "MountsInfo", Relics = "RelicsInfo", Acessorys = "Acessories", Arts = "WeaponArts", Skins = "SkinsInfo", Title = "TitleInfo"}
    local function passMissing(reward)
        local function exists(kind, id)
            local module = rewardModules[kind]
            if not module then return false end
            if not rewardCatalogs[kind] then
                local catalog = require(storage.Indexer[module])
                rewardCatalogs[kind] = kind == "Title" and catalog.Titles or catalog
            end
            return rewardCatalogs[kind][id] ~= nil
        end
        for kind, entries in pairs(reward) do
            if kind == "Inventory" and type(entries) == "table" then
                for itemKind, items in pairs(entries) do
                    for id, item in pairs(type(items) == "table" and items or {}) do
                        local name = type(item) == "table" and type(item.Info) == "table" and type(item.Info.Name) == "string" and item.Info.Name or id
                        if not exists(itemKind, name) then return itemKind .. "." .. tostring(name) end
                    end
                end
            elseif (kind == "Title" or kind == "Skins") and type(entries) == "table" then
                for id in pairs(entries) do if not exists(kind, id) then return kind .. "." .. tostring(id) end end
            end
        end
    end
    -- END PASS CATALOG
    -- ACHIEVEMENTS POLICY: same sequential goals and claimed tiers as the native screen.
    local function readyAchievements(catalog, read, toBigNum)
        local ready = {}
        for id, definition in pairs(catalog.ACHIEVEMENTS or {}) do
            local levels, path = definition.Levels or {}, definition.GFind
            local claimed = tonumber(read("Achievements", id)) or 0
            if not path or claimed ~= claimed or claimed < 0 or claimed % 1 ~= 0 then continue end
            claimed = math.min(claimed, #levels)
            local current = read(path[1], path[2]) or 0
            local last = claimed
            for index = claimed + 1, #levels do
                local goal = levels[index].Goal
                local reached
                if type(current) == "table" or type(goal) == "table" then
                    local ok, result = pcall(function() return toBigNum(current) >= toBigNum(goal) end)
                    reached = ok and result
                else
                    reached = (tonumber(current) or 0) >= (tonumber(goal) or math.huge)
                end
                if not reached then break end
                last = index
            end
            if last > claimed then table.insert(ready, tostring(id) .. ":" .. claimed .. ":" .. last) end
        end
        table.sort(ready)
        return ready
    end
    -- END ACHIEVEMENTS POLICY
    local function claim(key, signature, payload)
        local now, prior = os.clock(), pending[key]
        if prior and prior.signature == signature and now < prior.nextAt then rows[key].Caption.Text = "Aguardando confirmação do jogo." return end
        local attempts = prior and prior.signature == signature and prior.attempts + 1 or 1
        pending[key] = {signature = signature, attempts = attempts, nextAt = now + (attempts % 3 == 0 and 60 or 15)}
        general:Fire(payload)
        rows[key].Caption.Text = "Resgatando recompensas disponíveis..."
    end
    task.spawn(function()
        clientData.WaitForLoaded()
        while alive do
            task.wait(2)
            if not alive then break end
            if state.panic then continue end
            for _, key in ipairs({"daily", "weekly", "world", "login", "pass", "achievements", "apex", "codes", "candy", "cauldron"}) do
                if not autoClaim[key] then rows[key].Caption.Text = "Desligado." continue end
                if player.GameplayPaused then rows[key].Caption.Text = "Aguardando carregamento..." continue end
                local success, problem = pcall(function()
                    if key == "daily" or key == "weekly" or key == "world" then
                        definitions = definitions or require(storage.Indexer.QuestsInfo)
                        local kind = ({daily = "Daily", weekly = "Weekly", world = "Normal"})[key]
                        local ids = {}
                        for id, record in pairs(clientData.Get("Quests", kind) or {}) do
                            local definition = type(record) == "table" and definitions[kind][record.Name or id]
                            if definition and definition.NeedClaim == true and record.Completed == true then table.insert(ids, tostring(id)) end
                        end
                        table.sort(ids)
                        if #ids > 0 then claim(key, table.concat(ids, ":"), {Event = "ClaimAllQuests", Type = kind})
                        else pending[key] = nil rows[key].Caption.Text = "Aguardando missões concluídas." end
                    elseif key == "apex" then
                        state.apexClaim.step()
                    elseif key == "achievements" then
                        achievementsCatalog = achievementsCatalog or require(storage.Indexer.Achievements)
                        local ready = readyAchievements(achievementsCatalog, clientData.Get, function(value)
                            assert(nativeGameData and type(nativeGameData.ToBigNum) == "function", "Dados nativos ainda carregando.")
                            return nativeGameData.ToBigNum(value)
                        end)
                        if #ready > 0 then claim(key, table.concat(ready, "|"), {Event = "AchievementsAction", Action = "ClaimAll"})
                        else pending[key] = nil rows[key].Caption.Text = "Aguardando conquistas concluídas." end
                    elseif key == "codes" then
                        stepCodes()
                    elseif key == "login" then
                        totalDays = totalDays or #require(storage.Indexer.DailyRewards).DailyReward
                        local days = claimableDays(clientData.Get("DailyReward") or {}, totalDays)
                        if #days > 0 then claim(key, tostring(days[1]), {Event = "DailyReward", Item = days[1]})
                        else pending[key] = nil rows[key].Caption.Text = "Calendário em dia. Aguardando próximo login." end
                    elseif key == "pass" then
                        battlePass = battlePass or require(storage.Indexer.BattlePass)
                        local data = clientData.Get("BattlePass", "Battles", battlePass.CurrentPass) or {}
                        local info = battlePass.Passes[battlePass.CurrentPass] or {}
                        local ready = claimablePassRewards(data, info, passMissing)
                        if #ready > 0 then
                            claim(key, table.concat(ready, ":"), {Event = "BattlePass", Action = "ClaimAll"})
                        else pending[key] = nil rows[key].Caption.Text = "Aguardando recompensas liberadas no passe." end
                    elseif key == "candy" or key == "cauldron" then
                        if not eventShared then
                            local ui = player.PlayerScripts:FindFirstChild("NewUI", true)
                            eventShared = require(assert(ui, "Interface nativa indisponível").Screens.Event.Shared)
                        end
                        local cauldron = key == "cauldron"
                        local count = cauldron and eventShared.CauldronReady() or eventShared.ReadyCount()
                        if count > 0 then
                            local signature = eventShared.SEASON_ID .. ":" .. count .. ":" .. tostring(cauldron and select(3, eventShared.CauldronInfo()) or eventShared.Earned())
                            claim(key, signature, {Event = "SeasonAction", Action = cauldron and "CauldronClaimAll" or "ClaimAll"})
                        else pending[key] = nil rows[key].Caption.Text = "Aguardando requisitos do evento." end

                    end
                end)
                if not success then rows[key].Caption.Text = "Em espera: " .. tostring(problem) end
            end
        end
    end)
end
-- Apex claims native achievement rows and requirement-only free Apex rewards.
do
    local api={ids={ApexInferno=true,ApexDunes=true,ApexUltimate=true,ApexDeadly=true,
        ApexHeaven=true,ApexRush=true,ApexClock=true,ApexCourt=true,ApexLimit=true},confirmed=0}
    state.apexClaim=api
    local catalog,pending,recipes,recipeApi,release
    local retryAt,attempts={},{}
    local nextAt=0
    local function tr(pt,en,es) return uiState.language=="PT" and pt or uiState.language=="ES" and es or en end
    local function finite(value)
        local n=tonumber(value)
        return n and n==n and n>=0 and n<math.huge and n or nil
    end
    function api.ready(definitions,read)
        local ready={}
        for id in pairs(api.ids) do
            local definition=definitions.ACHIEVEMENTS and definitions.ACHIEVEMENTS[id]
            local levels=definition and definition.Levels
            local path=definition and definition.GFind
            if type(levels)~="table" or type(path)~="table" or not path[1] or not path[2] then continue end
            local claimed=finite(read("Achievements",id) or 0)
            local current=finite(read(path[1],path[2]) or 0)
            if not claimed or claimed%1~=0 or claimed>=#levels or not current then continue end
            local nextLevel=levels[claimed+1]
            local goal=type(nextLevel)=="table" and finite(nextLevel.Goal)
            if goal and current>=goal then ready[#ready+1]={id=id,before=claimed,goal=goal,current=current} end
        end
        table.sort(ready,function(a,b) return a.id<b.id end)
        return ready
    end
    function api.freeReady(definitions,allRecipes,native,open)
        local ready={}
        for id,recipe in pairs(allRecipes) do
            if type(recipe)~="table" or not (recipe.Release=="Apex" or recipe.Apex==true) then continue end
            local requirement=recipe.Requires
            if type(requirement)~="table" or (recipe.Release and not open(recipe.Release)) then continue end
            local linked=false
            for row in pairs(api.ids) do
                local definition=definitions.ACHIEVEMENTS[row]
                if definition and definition.GFind and definition.GFind[2]==requirement.Stat then
                    for _,level in ipairs(definition.Levels or {}) do
                        if tonumber(level.Goal)==tonumber(requirement.Min) then linked=true;break end
                    end
                end
                if linked then break end
            end
            if not linked or native.Crafted(id) then continue end
            local free=true
            local costs=native.CostList(recipe)
            if type(costs)~="table" then continue end
            for _,cost in pairs(costs) do if not cost.Req then free=false;break end end
            if free and native.Missing(recipe)==nil then ready[#ready+1]={id=id,kind="free"} end
        end
        table.sort(ready,function(a,b) return a.id<b.id end)
        return ready
    end
    function api.step()
        local row=state.claimRows.apex
        if not row then return end
        if not autoClaim.apex then row.Caption.Text=tr("Desligado.","Off.","Desactivado.");return end
        if state.panic or player.GameplayPaused then row.Caption.Text=tr("Coleta Apex pausada.","Apex collection paused.","Recogida Apex pausada.");return end
        local now=os.clock()
        if pending then
            local claimed=pending.kind=="free" and recipeApi.Crafted(pending.id) or finite(clientData.Get("Achievements",pending.id))
            if (pending.kind=="free" and claimed) or (pending.kind~="free" and claimed and claimed>pending.before) then
                api.confirmed+=pending.kind=="free" and 1 or claimed-pending.before
                attempts[pending.id],retryAt[pending.id]=nil,nil
                pending=nil;nextAt=now+0.35
            elseif now-pending.at<8 then
                row.Caption.Text=tr("Aguardando confirmação: ","Waiting for confirmation: ","Esperando confirmación: ")..pending.id;return
            else
                attempts[pending.id]=(attempts[pending.id] or 0)+1
                retryAt[pending.id]=now+(attempts[pending.id]>=3 and 60 or 10)
                pending=nil
            end
        end
        if now<nextAt then return end
        catalog=catalog or require(storage.Indexer.Achievements)
        local ready=autoClaim.achievements and {} or api.ready(catalog,clientData.Get)
        if storage.Indexer.Recipes then
            recipes=recipes or require(storage.Indexer.Recipes)
            recipeApi=recipeApi or require(player.PlayerScripts:FindFirstChild("NewUI",true).Screens.Recipes)
            release=release or require(storage.SharedModules.Release)
            for _,entry in ipairs(api.freeReady(catalog,recipes,recipeApi,release.IsOpen)) do ready[#ready+1]=entry end
        end
        for _,entry in ipairs(ready) do
            if now<(retryAt[entry.id] or 0) then continue end
            pending={id=entry.id,before=entry.before,kind=entry.kind,at=now}
            nextAt=now+0.35
            local ok,problem=pcall(function()
                if entry.kind=="free" then general:Fire({Event="CraftItem",Name=entry.id})
                else general:Fire({Event="AchievementsAction",Action="Claim",Id=entry.id}) end
            end)
            row.Caption.Text=ok and tr("Resgatando Apex: ","Claiming Apex: ","Recogiendo Apex: ")..entry.id
                or tr("Falha no resgate: ","Claim failed: ","Error al recoger: ")..tostring(problem)
            return
        end
        row.Caption.Text=#ready>0 and tr("Aguardando nova tentativa Apex.","Waiting to retry Apex.","Esperando reintento Apex.")
            or tr("Apex em dia. Resgates confirmados: ","Apex up to date. Confirmed claims: ","Apex al día. Recogidas confirmadas: ")..api.confirmed
    end
end
-- AUTO BUY UI: Auto Buy na janela antiga (escondida): só os controles que o código e a interface nova leem/acionam; sem visual.
-- O catálogo da loja, os recibos e o loop de compra estão em src/sellbuy/auto-buy.lua (roda logo depois deste arquivo e faz a primeira render()).
do
    local buyToggle = state.controlRow("Auto Buy", "Compra itens ativos; quantidade 0 = contínuo.", buyPage)
    buyToggle.Name = "AutoBuy"
    toggleLook(buyToggle, autoBuy.enabled)
    connectUI(buyToggle, function() autoBuy.enabled = not autoBuy.enabled save() toggleLook(buyToggle, autoBuy.enabled) end)
    for _, currency in ipairs({"Ticket", "SoulCandy"}) do
        local field = state.controlField("Reserve_" .. currency, tostring(autoBuy.reserves[currency]), buyPage)
        connectUI(field, function()
            local number = tonumber(field.Text)
            if number and number == number and number >= 0 and number <= 1000000000 then autoBuy.reserves[currency] = math.floor(number) save() end
            field.Text = tostring(autoBuy.reserves[currency])
        end, field.FocusLost)
    end
    local status = state.controlLabel("AutoBuyStatus", "Carregando lojas...", buyPage)
    local list = make("Frame", {Name = "BuyItems"}, buyPage)
    local rowConnections, captions = {}, {}
    -- view: o que o arquivo da lógica publica para as linhas (catálogo, tabela de busca e estoque do inventário).
    local view = {catalog = {}, lookup = {}, stock = function() return 0 end}
    -- A interface nova ordena as linhas por posição (Y): categorias (rótulos soltos) e itens (molduras com o nome do item) na ordem do catálogo.
    -- Cada item: imagem, três rótulos sem nome na ordem (nome, legenda, "Quantidade a comprar"), InventoryOwned, SelectItem e StockTarget.
    local function render()
        for _, connection in ipairs(rowConnections) do connection:Disconnect() end
        table.clear(rowConnections) table.clear(captions) list:ClearAllChildren()
        local y, category = 0, nil
        for _, entry in ipairs(view.catalog) do
            local item = entry.item
            if item.PriceType ~= autoBuy.currency then continue end
            if category ~= entry.category then
                category = entry.category
                make("TextLabel", {Text = category, Position = UDim2.fromOffset(12, y)}, list)
                y += 34
            end
            local settings = autoBuy.items[entry.key]
            local row = state.controlCard(entry.key, list, {Position = UDim2.fromOffset(2, y)})
            make("ImageLabel", {Image = item.Image or ""}, row)
            make("TextLabel", {Text = item.Name}, row)
            captions[entry.key] = make("TextLabel", {Text = ""}, row)
            -- O terceiro rótulo sem nome é o que a interface nova põe em cima da caixa de quantidade: tem que ser o da quantidade (o do inventário tem nome e é lido à parte).
            make("TextLabel", {Text = "Quantidade a comprar / 0 = contínuo"}, row)
            local inventoryLabel = state.controlLabel("InventoryOwned", "", row)
            state.setLocalizedText(inventoryLabel, "No inventário: " .. view.stock(entry))
            local selectButton = state.controlButton("SelectItem", "", row)
            local function refresh() selectButton.Text = settings.enabled and "✓ Ativo" or "Comprar" end
            connectUI(selectButton, function()
                state.toggleBuyItem(autoBuy, entry.key, workspace:GetServerTimeNow())
                save() refresh()
            end, nil, rowConnections)
            refresh()
            local field = state.controlField("StockTarget", tostring(settings.target), row)
            connectUI(field, function()
                local number = tonumber(field.Text)
                if number and number == number and number >= 0 and number <= 1000000 then
                    local previous = settings.target
                    -- Editing the remaining quantity does not cancel or resend a receipt.
                    -- Any subsequently confirmed units count toward this new remainder.
                    settings.target = math.floor(number)
                    local savedOK, problem = save()
                    if not savedOK then
                        settings.target = previous
                        status.Text = "Could not save purchase quantity: " .. tostring(problem)
                    end
                end
                field.Text = tostring(settings.target)
            end, field.FocusLost, rowConnections)
            y += 170
        end
    end
    for _, currency in ipairs({"Ticket", "SoulCandy"}) do
        local control = state.controlButton("BuyCurrency_" .. currency, currency == "Ticket" and "Tickets" or "Candy do evento", buyPage)
        connectUI(control, function() autoBuy.currency = currency save() render() end)
    end
    table.insert(cleanupCallbacks, function() for _, connection in ipairs(rowConnections) do connection:Disconnect() end end)
    state.buyUI = {status = status, list = list, captions = captions, view = view, render = render}
end
-- END AUTO BUY UI
-- Auto Buy: catálogo da loja nativa, recibos de compra e loop de compra (a cada 2 s). Escreve o status em AutoBuyStatus e o texto de cada item.
-- Os controles e as linhas de itens (BuyItems) são criados em src/ui/antiga/auto-buy.lua.
do
    local status, captions, view, render = state.buyUI.status, state.buyUI.captions, state.buyUI.view, state.buyUI.render
    local list = state.buyUI.list
    local catalog, lookup = {}, {}
    local shopData, loadProblem, catalogReady, retryAt = nil, nil, false, 0
    -- BUY CATALOG: retry failed initialization and publish only a complete catalog.
    local function loadBuyCatalog()
        if catalogReady or os.clock() < retryAt then return false end
        retryAt = os.clock() + 5
        local ok, result = pcall(function()
            local scripts = player:FindFirstChild("PlayerScripts")
            local ui = scripts and scripts:FindFirstChild("NewUI", true)
            local data = require(assert(ui, "Interface nativa indisponível").Screens.ItemShop.Data)
            local definitions = data.SHOPS or require(storage.Indexer.ShopInfo)
            local entries, byKey = {}, {}
            for shop, definition in pairs(definitions) do
                local supported = false
                for _, info in pairs(type(definition) == "table" and definition.Items or {}) do
                    if info.PriceType == "Ticket" or info.PriceType == "SoulCandy" then supported = true break end
                end
                if not supported then continue end
                for _, item in ipairs(data.Load(shop)) do
                    if item.PriceType == "Ticket" or item.PriceType == "SoulCandy" then
                        local key = shop .. ":" .. item.Id
                        local category = item.Real == "GearTome" and "Gear EXP" or item.Real:lower():find("potion") and "Poções" or ({Item = "Materiais e runas", Relic = "Relíquias", Weapon = "Armas", Mount = "Montarias"})[item.Kind] or "Outros"
                        local entry = {key = key, shop = shop, item = item, category = category}
                        entries[#entries + 1], byKey[key] = entry, entry
                    end
                end
            end
            assert(#entries > 0, "Nenhum item de tickets ou candy carregado")
            table.sort(entries, function(a, b)
                if a.item.PriceType ~= b.item.PriceType then return a.item.PriceType < b.item.PriceType end
                local order = {["Poções"] = 1, ["Materiais e runas"] = 2, ["Relíquias"] = 3, ["Armas"] = 4, ["Montarias"] = 5}
                if a.category ~= b.category then return (order[a.category] or 6) < (order[b.category] or 6) end
                return a.item.Name < b.item.Name
            end)
            return {data = data, entries = entries, lookup = byKey}
        end)
        if not ok then loadProblem = tostring(result) return false end
        shopData, catalog, lookup = result.data, result.entries, result.lookup
        view.catalog, view.lookup = catalog, lookup   -- a interface (src/ui/antiga/auto-buy.lua) monta as linhas a partir daqui
        for _, entry in ipairs(catalog) do
            if not autoBuy.items[entry.key] then autoBuy.items[entry.key] = {enabled = false, target = 0} end
        end
        loadProblem, catalogReady = nil, true
        return true
    end
    -- END BUY CATALOG
    loadBuyCatalog()
    local function stock(entry)
        local item = entry.item
        if item.Kind == "Item" then
            local record = clientData.Get("Inventory", "Items", item.Real)
            return tonumber(type(record) == "table" and record.Amount or record) or 0
        end
        local count = 0
        for id, value in pairs(clientData.Get("Inventory", item.Kind .. "s") or {}) do
            if id == item.Real or type(value) == "table" and (value.Name == item.Real or type(value.Info) == "table" and value.Info.Name == item.Real) then count += 1 end
        end
        return count
    end
    local function unconfirmedPurchase(entry, now)
        for key, receipt in pairs(autoBuy.unconfirmed) do
            local other = lookup[key]
            if key == entry.key or other and other.item.Kind == entry.item.Kind and other.item.Real == entry.item.Real then
                return true
            end
        end
        return false
    end
    view.stock = stock
    render()
    -- BUY RECEIPT POLICY: do not let a lost response block unrelated purchases forever.
    local function buyRetryDelay(attempts)
        return math.min(30 * 2 ^ math.min(math.max((tonumber(attempts) or 1) - 1, 0), 4), 300)
    end
    local function buyReceiptStatus(receipt, now, entry)
        if entry then
            local owned=stock(entry)
            local bought=tonumber(shopData.Bought(entry.shop,entry.item)) or 0
            if state.buyReceiptCredit(autoBuy.items[receipt.key],receipt,owned,bought)>0 then save() end
            if receipt.quantityVersion==2 then
                if (receipt.credited or 0)>=(receipt.expected or 1) then return "confirmed" end
                if state.buyContinuousReceiptSettled(autoBuy.items[receipt.key], receipt, now) then
                    -- Archive the acknowledged batch; never resend its unobserved remainder.
                    autoBuy.lastPartialReceipt = {key=receipt.key,at=receipt.at,expected=receipt.expected,
                        credited=receipt.credited,settledAt=now,reason="continuous-partial-acknowledged"}
                    return "confirmed"
                end
            elseif owned>receipt.stock or bought>receipt.bought then return "confirmed" end
        end
        if now - (tonumber(receipt.at) or 0) >= 30 then return "unknown" end
        return "waiting"
    end
    -- END BUY RECEIPT POLICY
    if type(clientData.OnChange) == "function" then
        local receiptConnection = clientData.OnChange({"Inventory", "Items"}, function()
            if not alive then return end
            pcall(function()
                local now = workspace:GetServerTimeNow()
                local receipt = autoBuy.pending
                if receipt then buyReceiptStatus(receipt, now, lookup[receipt.key]) end
                for key, previous in pairs(autoBuy.unconfirmed) do buyReceiptStatus(previous, now, lookup[key]) end
            end)
        end)
        if receiptConnection and type(receiptConnection.Disconnect) == "function" then table.insert(connections, receiptConnection) end
    end
    function state.reconcileBuyReceipts()
        if not catalogReady then if loadBuyCatalog() then render() else return false end end
        local now=workspace:GetServerTimeNow()
        for key,receipt in pairs(autoBuy.unconfirmed) do
            if buyReceiptStatus(receipt,now,lookup[key])=="confirmed" then
                local old=autoBuy.unconfirmed[key];autoBuy.unconfirmed[key]=nil
                if not save() then autoBuy.unconfirmed[key]=old end
            end
        end
        local receipt=autoBuy.pending
        if receipt and buyReceiptStatus(receipt,now,lookup[receipt.key])=="confirmed" then
            autoBuy.pending=nil;if not save() then autoBuy.pending=receipt end
        end
        return true
    end
    function state.buyLimitBreakerActive()
        local limit=autoQuest.splitQuests and autoQuest.limitBreakerEnabled or autoQuest.profile=="limitbreaker"
        if autoQuest.splitQuests then limit=autoQuest.limitBreakerEnabled==true end
        return limit and state.questPriorityActive and state.questPriorityActive() or false
    end
    function state.buyEffectiveReserve(currency)
        return math.max(tonumber(autoBuy.reserves[currency]) or 0,
            currency=="Ticket" and state.buyLimitBreakerActive() and 1000 or 0)
    end
    function state.buyTicketNotice(item,balance,cost)
        if not item or item.PriceType~="Ticket" or not state.buyLimitBreakerActive() then return nil end
        if balance==nil or balance-(tonumber(cost) or 0)>=1000 and balance>=1000 then return nil end
        return uiState.language=="PT" and "Compras com tickets pausadas: Limit Breaker ativo; é necessário manter 1.000 tickets após a compra."
            or uiState.language=="ES" and "Compras con tickets pausadas: Limit Breaker activo; hay que conservar 1.000 tickets después de comprar."
            or "Ticket purchases paused: Limit Breaker is active; keep 1,000 Tickets after the purchase."
    end
    function state.buyPriorityNotice()
        if not autoBuy.enabled or not catalogReady then return nil end
        local balance=tonumber(shopData.Have("Ticket"))
        for _,entry in ipairs(catalog) do
            if autoBuy.items[entry.key].enabled and entry.item.PriceType=="Ticket" then
                local notice=state.buyTicketNotice(entry.item,balance,tonumber(shopData.Total(entry.item,1,1)))
                if notice then return notice end
            end
        end
    end
    task.spawn(function()
        clientData.WaitForLoaded()
        while alive do
            task.wait(2)
            if not alive then break end
            if state.panic then continue end
            local success, problem = pcall(function()
                state.reconcileBuyReceipts()
                -- BUY PRIORITY NOTICE BEGIN
                local notice=state.buyPriorityNotice()
                -- A Ticket notice never blocks purchases with other currencies.
                -- BUY PRIORITY NOTICE END
                if not catalogReady then
                    if loadBuyCatalog() then render()
                    else status.Text = "Loja indisponível: " .. tostring(loadProblem) return end
                end
                local now = workspace:GetServerTimeNow()
                for key, text in pairs(captions) do
                    local entry = lookup[key]
                    local item, owned = entry.item, stock(entry)
                    local locked = shopData.Lock(entry.shop, item)
                    local settings=autoBuy.items[entry.key]
                    local _,lockReason=shopData.Lock(entry.shop,item)
                    local note=locked and tostring(lockReason or "Indisponível.") or ""
                    if settings.enabled then
                        local give=tonumber(item.PriceInfo.GiveAmount) or 1
                        if settings.target>0 and settings.target<give then note="Quantidade menor que o lote do item." end
                        if item.Kind=="Item" then
                            local valid,capacity=pcall(function() return require(shared.ExtraFunctions).GetMaxCapacity(player,item.Real) end)
                            if valid and tonumber(capacity) and tonumber(capacity)-owned<give then note="Inventário cheio; aguardando espaço." end
                        end
                        local balance=tonumber(shopData.Have(item.PriceType)) or 0
                        local cost=tonumber(shopData.Total(item,1,1)) or 0
                        if balance-state.buyEffectiveReserve(item.PriceType)<cost then note="Saldo insuficiente; aguardando." end
                    end
                    if unconfirmedPurchase(entry,now) then note="Aguardando confirmação; sem repetir cobrança." end
                    if settings.enabled and state.buyInfusionBlocked(item) then note=state.infusionText("Auto Buy aguarda a Infusão terminar.") end
                    if (settings.resetUntil or 0) > now then
                        note = "Reset: " .. math.ceil(settings.resetUntil-now) .. "s"
                    end
                    if not settings.enabled then note="Desligado." end
                    local ticketNotice=settings.enabled and state.buyTicketNotice(item,tonumber(shopData.Have(item.PriceType)),tonumber(shopData.Total(item,1,1)))
                    if ticketNotice then note=ticketNotice end
                    if text:GetAttribute("BuyBaseColor")==nil then text:SetAttribute("BuyBaseColor",text.TextColor3) end
                    text.TextColor3=ticketNotice and Color3.fromRGB(255,196,82) or text:GetAttribute("BuyBaseColor")
                    text.Text = tostring(item.Price)..(item.PriceType=="Ticket" and " tickets" or " candy").." · "..(settings.target==0 and "Compra contínua" or "Restam "..settings.target).." · "..note
                    local row=list:FindFirstChild(entry.key)
                    local inventoryLabel=row and row:FindFirstChild("InventoryOwned")
                    if inventoryLabel then state.setLocalizedText(inventoryLabel,"No inventário: "..owned) end
                    local field=row and row:FindFirstChild("StockTarget")
                    if field and not field:IsFocused() and field.Text~=tostring(settings.target) then field.Text=tostring(settings.target) end
                end
                for key, receipt in pairs(autoBuy.unconfirmed) do
                    if buyReceiptStatus(receipt, now, lookup[key]) == "confirmed" then autoBuy.unconfirmed[key] = nil save() end
                end
                if autoBuy.pending then
                    local receipt = autoBuy.pending
                    local outcome = buyReceiptStatus(receipt, now, lookup[receipt.key])
                    if outcome == "confirmed" then autoBuy.pending = nil save()
                    elseif outcome == "unknown" then
                        receipt.retryAt = now + buyRetryDelay(receipt.attempts)
                        autoBuy.unconfirmed[receipt.key], autoBuy.pending = receipt, nil
                        save()
                    else status.Text = "Compra solicitada. Aguardando confirmação; sem repetir cobrança." return end
                end
                if not autoBuy.enabled then status.Text = "Desligado. Marque itens e defina quantidades a comprar." return end
                if player.GameplayPaused then status.Text = "Aguardando carregamento..." return end
                local waitingRetry = false
                local waitingInfusion=false
                local waitingCraft=false
                local waitingTicket
                for _, entry in ipairs(catalog) do
                    local item, settings = entry.item, autoBuy.items[entry.key]
                    if not settings.enabled or shopData.Lock(entry.shop, item) then continue end
                    if state.buyInfusionBlocked(item) then waitingInfusion=true;continue end
                    if state.craftItemBusy and state.craftItemBusy(item) then waitingCraft=true;continue end
                    if state.gearTomeBlocksPurchase(item.Real) then continue end
                    if (settings.resetUntil or 0) > now then continue end
                    if unconfirmedPurchase(entry, now) then waitingRetry = true continue end
                    local owned, balance = stock(entry), tonumber(shopData.Have(item.PriceType)) or 0
                    local price = tonumber(shopData.Total(item, 1, 1))
                    local ticketNotice=state.buyTicketNotice(item,balance,price)
                    if ticketNotice then waitingTicket=ticketNotice;continue end
                    local give = tonumber(item.PriceInfo.GiveAmount) or 1
                    local target = state.buyTargetOperations(settings, give)
                    local bought = tonumber(shopData.Bought(entry.shop, item)) or 0
                    local reserve=state.buyEffectiveReserve(item.PriceType)
                    local amount = purchaseAmount(target, 0, balance, reserve, price, bought, item.PriceInfo.Limit, item.PriceInfo.CanMultiple, item.PriceInfo.OnlyOne)
                    if type(shopData.Amount) == "function" and price and price > 0 then
                        local batch = autoBuy.batch == "MAX" and "Max" or autoBuy.batch == "10x" and 10 or 1
                        local native = tonumber(shopData.Amount(entry.shop, item, batch, 1)) or 0
                        amount = math.max(0, math.min(1000, target, math.floor(native),
                            item.PriceInfo.CanMultiple == true and 1000 or 1,
                            item.PriceInfo.OnlyOne == true and 1 or 1000))
                        if item.PriceInfo.Limit then amount = math.min(amount, math.max(0, math.floor(item.PriceInfo.Limit - bought))) end
                        local available = math.max(0, balance - reserve)
                        local low, high = 0, amount
                        while low < high do
                            local middle = math.floor((low + high + 1) / 2)
                            local cost = tonumber(shopData.Total(item, middle, 1))
                            if cost and cost > 0 and cost <= available then low = middle else high = middle - 1 end
                        end
                        amount = low
                    else
                        amount = math.min(amount, autoBuy.batch == "MAX" and 1000 or autoBuy.batch == "10x" and 10 or 1)
                    end
                    if item.Kind == "Item" then
                        local extra = require(shared.ExtraFunctions)
                        local valid, capacity = pcall(extra.GetMaxCapacity, player, item.Real)
                        if valid and tonumber(capacity) then amount = math.min(amount, math.max(0, math.floor((tonumber(capacity) - owned) / give))) end
                    end
                    if amount < 1 then continue end
                    local attempts = 1
                    for key, receipt in pairs(autoBuy.unconfirmed) do
                        local prior = lookup[key]
                        if key == entry.key or prior and prior.item.Kind == item.Kind and prior.item.Real == item.Real then
                            attempts = math.max(attempts, (tonumber(receipt.attempts) or 1) + 1)
                            autoBuy.unconfirmed[key] = nil
                        end
                    end
                    autoBuy.pending = {key = entry.key, stock = owned, bought = bought, at = now, attempts = attempts,quantityVersion=2,expected=amount*give,credited=0,give=give}
                    local persisted = save()
                    if not persisted then autoBuy.pending = nil status.Text = "Falha ao salvar pedido. Nenhuma compra enviada." return end
                    general:Fire({Event = "ItemShopAction", Action = "Buy", Shop = entry.shop, Item = item.Id, Amount = amount, Rank = 1})
                    status.Text = "Comprando " .. amount .. " × " .. item.Name .. "." return
                end
                status.Text = waitingCraft and state.infusionText("Aguardando Craft: recursos compartilhados.") or waitingInfusion and state.infusionText("Auto Buy aguarda a Infusão terminar.")
                    or waitingTicket or notice
                    or waitingRetry and "Compra sem confirmação. Pedido preservado para evitar cobrança duplicada."
                    or "Aguardando saldo, liberação ou novos pedidos de compra."
            end)
            if not success then status.Text = "Compra em espera: " .. tostring(problem) end
        end
    end)
end
-- QUEST SHOPPING: one confirmed acquisition per catalog item, not one purchase per visit.
do
    local shops = require(storage.Indexer.ShopInfo)
    local nativeShop, nextBuy = nil, 0
    local loadShop,shopPoint
    local function coinsStamp(data)
        local ok,value=pcall(function() return data.Have("Coins") end)
        if not ok then return nil end
        if type(value)=="table" and value.first~=nil and value.second~=nil then return tostring(value.first)..":"..tostring(value.second) end
        if type(value)=="number" or type(value)=="string" then return tostring(value) end
    end
    local function owned(kind, id)
        local inventory = clientData.Get("Inventory", kind .. "s")
        if type(inventory) ~= "table" then return nil end
        for key, entry in pairs(inventory) do
            if key == id or (type(entry) == "table" and (entry.Name == id or type(entry.Info)=="table" and entry.Info.Name==id)) then return true end
        end
        return false
    end
    local function bought(shop, id)
        if nativeShop and type(nativeShop.Bought)=="function" then
            for _,item in ipairs(nativeShop.Load(shop)) do
                if item.Id==id then
                    local value=tonumber(nativeShop.Bought(shop,item))
                    if value then return value end
                end
            end
        end
        return tonumber(clientData.Get("ShopBought", shop, id)) or 0
    end
    function state.questPurchaseReceipt()
        local op = autoQuest.purchasePending
        if not op then return true end
        if owned(op.kind, op.id) == true or bought(op.shop, op.id) > (tonumber(op.beforeBought) or 0) then
            local key = op.kind .. ":" .. op.id
            local previous = autoQuest.purchasesDone[key]
            autoQuest.purchasesDone[key] = true
            autoQuest.purchasePending = nil
            if not save() then
                autoQuest.purchasesDone[key], autoQuest.purchasePending = previous, op
                return false
            end
            return true
        end
        local data=loadShop()
        local now=workspace:GetServerTimeNow()
        if not data or owned(op.kind,op.id)==nil then return false end
        if type(clientData.Get("ShopBought"))~="table" then questRuntime.purchaseStatus="Compra pendente: aguardando histórico da loja carregar.";return false end
        local stamp=coinsStamp(data)
        if not stamp then questRuntime.purchaseStatus="Compra pendente: saldo indisponível para conferir o pedido.";return false end
        if type(op.at)~="number" or type(op.beforeCoins)~="string" then
            op.at=now;op.beforeCoins=stamp;op.attempts=tonumber(op.attempts) or 1
            if not save() then questRuntime.purchaseStatus="Falha ao salvar a conferência da compra." end
            return false
        end
        if now-op.at<30 then return false end
        if stamp~=op.beforeCoins then
            questRuntime.purchaseStatus="Compra pendente: saldo alterado; aguardando inventário ou confirmação da loja. Sem repetir cobrança."
            return false
        end
        if (tonumber(op.attempts) or 1)>=3 then
            questRuntime.purchaseStatus="Compra sem confirmação após 3 tentativas: confira os requisitos da loja e o inventário."
            return false
        end
        if not autoQuest.enabled or not autoQuest.purchases or state.panic or insideDungeon() or player.GameplayPaused
            or state.questProfiles and not state.questProfiles.groups(autoQuest).islands then return false end
        local point=shopPoint(op.shop);local root=rootPart()
        if not point or not root then questRuntime.purchaseStatus="Compra pendente: aguardando vendedor carregar.";return false end
        if (root.Position-point).Magnitude>12 then
            questRuntime.destination=point+Vector3.new(0,3,4)
            questRuntime.purchaseStatus="Retornando ao vendedor para conferir a compra pendente."
            return false
        end
        local observation=op.observation
        if not observation or observation.stamp~=stamp then op.observation={stamp=stamp,at=now};return false end
        if now-observation.at<2 then return false end
        local item
        for _,entry in ipairs(data.Load(op.shop)) do if entry.Id==op.id then item=entry;break end end
        if not item or data.Lock(op.shop,item) or not data.Enough("Coins",data.Total(item,1,1)) then
            questRuntime.purchaseStatus="Compra pendente: saldo ou requisitos da loja ainda não permitem comprar.";return false
        end
        local oldAt,oldAttempts=op.at,op.attempts
        op.at=now;op.attempts=(tonumber(op.attempts) or 1)+1;op.observation=nil
        if not save() then op.at,op.attempts=oldAt,oldAttempts;questRuntime.purchaseStatus="Falha ao salvar; compra não reenviada.";return false end
        nextBuy=os.clock()+2
        general:Fire({Event="ItemShopAction",Action="Buy",Shop=op.shop,Item=op.id,Amount=1,Rank=1})
        questRuntime.purchaseStatus="Compra sem efeito confirmado; nova tentativa após conferir saldo e inventário."
        return false
    end
    loadShop=function()
        if nativeShop then return nativeShop end
        local scripts = player:FindFirstChild("PlayerScripts")
        local ui = scripts and scripts:FindFirstChild("NewUI", true)
        if not ui then return nil end
        nativeShop = require(ui.Screens.ItemShop.Data)
        return nativeShop
    end
    shopPoint=function(shop)
        local extra = workspace:FindFirstChild("__Extra")
        local interactions = extra and extra:FindFirstChild("__Interactions")
        local folder = interactions and interactions:FindFirstChild("Shops")
        for _, node in ipairs(folder and folder:GetChildren() or {}) do
            if node:GetAttribute("ShopId") == shop then
                if node:IsA("BasePart") then return node.Position end
                if node:IsA("Model") then return node:GetPivot().Position end
            end
        end
    end
    function state.questPurchaseBackfill(completed, world)
        local data = loadShop()
        if not data or autoQuest.purchasePending then return nil end
        local candidates = {}
        for map, info in pairs(mapInfo) do
            if info.WorldQuest and completed[info.WorldQuest] == true and tonumber(info.World) == world then
                table.insert(candidates, {map = map, order = tonumber(info.Order) or 0})
            end
        end
        table.sort(candidates, function(a, b) return a.order < b.order end)
        for _, entry in ipairs(candidates) do
            local shop, ids = state.questWeaponShop(entry.map, mapInfo, shops)
            if not shop then continue end
            for _, id in ipairs(ids) do
                local key = "Weapon:" .. id
                if autoQuest.purchasesDone[key] or owned("Weapon", id) or bought(shop, id) > 0 then continue end
                for _, item in ipairs(data.Load(shop)) do
                    if item.Id == id and item.PriceType == "Coins" and not data.Lock(shop, item)
                        and data.Enough("Coins", data.Total(item, 1, 1)) then return entry.map end
                end
            end
        end
    end
    function state.questShopStep(map, islandPosition)
        questRuntime.purchaseNeedsCoins=nil
        questRuntime.purchaseStatus=nil
        if state.panic or not autoQuest.enabled or not autoQuest.purchases or insideDungeon() then return false end
        state.questPurchaseReceipt()
        if autoQuest.purchasePending then
            questRuntime.purchaseStatus = questRuntime.purchaseStatus or ("Compra aguardando confirmação: " .. autoQuest.purchasePending.id .. ". Sem repetir cobrança.")
            return questRuntime.destination~=nil,questRuntime.purchaseStatus
        end
        local root = rootPart()
        if not root or player.GameplayPaused then return false end
        local data = loadShop()
        if not data then questRuntime.purchaseStatus = "Aguardando catálogo de compras da ilha." return false end
        local weaponShop, weaponsHere = state.questWeaponShop(map, mapInfo, shops)
        local candidates = {}
        for _, id in ipairs(weaponsHere or {}) do
            table.insert(candidates, {id = id, shop = weaponShop, kind = "Weapon"})
        end
        -- Boat shops are not numbered per island. Use an actual nearby seller.
        for shop, info in pairs(shops) do
            if shop:match("^BoatShop") then
                local point = shopPoint(shop)
                if point and (point - islandPosition).Magnitude <= 650 then
                    for id, item in pairs(info.Items or {}) do
                        if item.Type == "Mount" and item.PriceType == "Coins" then
                            table.insert(candidates, {id = id, shop = shop, kind = "Mount"})
                        end
                    end
                end
            end
        end
        local affordable, missing = {}, 0
        for _, entry in ipairs(candidates) do
            local key = entry.kind .. ":" .. entry.id
            local have = owned(entry.kind, entry.id)
            if have == nil then questRuntime.purchaseStatus = "Aguardando inventário para conferir compras." return false end
            if have or bought(entry.shop, entry.id) > 0 then
                if not autoQuest.purchasesDone[key] then autoQuest.purchasesDone[key] = true save() end
            end
            if autoQuest.purchasesDone[key] then continue end
            missing += 1
            for _, item in ipairs(data.Load(entry.shop)) do
                if item.Id == entry.id and item.PriceType == "Coins" and not data.Lock(entry.shop, item) then
                    local price = data.Total(item, 1, 1)
                    if data.Enough("Coins", price) then
                        entry.item, entry.price = item, price
                        table.insert(affordable, entry)
                    else
                        questRuntime.purchaseNeedsCoins=true
                    end
                    break
                end
            end
        end
        table.sort(affordable, function(a, b)
            if a.kind ~= b.kind then return a.kind == "Weapon" end
            if a.price ~= b.price then return a.price < b.price end
            return a.id < b.id
        end)
        local entry = affordable[1]
        if not entry then
            questRuntime.purchaseStatus = missing > 0 and "Compras pendentes: aguardando saldo ou liberação da loja." or nil
            return false
        end
        if os.clock() < nextBuy then return false end
        local destination = shopPoint(entry.shop)
        if not destination then
            if (root.Position - islandPosition).Magnitude > 80 then
                questRuntime.destination = islandPosition + Vector3.new(0, 4, 0)
                return true, "Indo à ilha para conferir a loja."
            end
            questRuntime.purchaseStatus = "Aguardando vendedor da ilha carregar."
            return false
        end
        if (root.Position - destination).Magnitude > 12 then
            questRuntime.destination = destination + Vector3.new(0, 3, 4)
            return true, "Indo comprar: " .. entry.id .. "."
        end
        local op = {shop = entry.shop, id = entry.id, kind = entry.kind, beforeBought = bought(entry.shop, entry.id),
            at=workspace:GetServerTimeNow(),beforeCoins=coinsStamp(data),attempts=1}
        autoQuest.purchasePending = op
        if not save() then autoQuest.purchasePending = nil return false, "Compra adiada: não foi possível salvar o pedido." end
        if state.panic then autoQuest.purchasePending = nil save() return false end
        nextBuy = os.clock() + 2
        general:Fire({Event = "ItemShopAction", Action = "Buy", Shop = entry.shop, Item = entry.id, Amount = 1, Rank = 1})
        questRuntime.purchaseStatus = "Compra solicitada: " .. entry.id .. ". Aguardando confirmação."
        return true, questRuntime.purchaseStatus
    end
    -- Acknowledge inventory changes immediately, before Auto Sell can remove a new copy.
    if type(clientData.OnChange) == "function" then
        for _, path in ipairs({{"Inventory", "Weapons"}, {"Inventory", "Mounts"}, {"ShopBought"}}) do
            local connection = clientData.OnChange(path, function()
                if alive and not state.panic and autoQuest.purchasePending then state.questPurchaseReceipt() end
            end)
            if connection and type(connection.Disconnect) == "function" then table.insert(connections, connection) end
        end
    end
end
-- END QUEST SHOPPING

do
    local definitions = require(storage.Indexer.QuestsInfo).Normal
    local enemies = require(storage.Indexer.EnemyInfo)
    local release = require(shared.Release)
    local extra = require(shared.ExtraFunctions)
    local enemyEvent = state.pausableBridge(require(storage.BridgeNet2).ReferenceBridge("ENEMY_EVENT"))
    local islands, catalog, added = {}, {}, {}
    for id, info in pairs(mapInfo) do
        if info.WorldQuest and definitions[info.WorldQuest] then table.insert(islands, {id = id, info = info}) end
    end
    table.sort(islands, function(a, b) return a.info.Order < b.info.Order end)
    local function append(id, island)
        if added[id] or not definitions[id] then return end
        local definition = definitions[id]
        if definition.NeedQuest then append(definition.NeedQuest, island) end
        added[id] = true
        local map = island.id
        for goal in pairs(definition.Goals or {}) do
            if goal:match("^Spawn") and mapInfo[goal:sub(6)] then map = goal:sub(6) end
            if goal == "ShadowsArised" or goal == "WeaponsBought" or goal == "MountsBought" then map = "SoloWorld" end
            local info = enemies[goal:match("^(.-)Defeated$")]
            if info then for _, candidate in ipairs(islands) do if candidate.info.Order == info.World then map = candidate.id break end end end
        end
        table.insert(catalog, {id = id, map = map, world = mapInfo[map].World, order = mapInfo[map].Order})
    end
    for _, island in ipairs(islands) do append(island.info.WorldQuest, island) end
    questRuntime.catalog = catalog
-- WORLD QUEST RUNTIME
do
    local function runeStock(id)
        local inventory = clientData.Get("Inventory", "Items")
        if type(inventory) ~= "table" then return nil end
        local item = inventory[id]
        return tonumber(type(item) == "table" and item.Amount or item) or 0
    end
    local function validRune(job)
        local info = job.rune and itemsInfo[job.rune]
        local rule = info and info.Dungeon
        if not rule or rule.Type ~= "WorldRune" or rule.World ~= job.map then return false end
        if (runeStock(job.rune) or 0) > 0 then return true end
        local room = partyClient.GetRoom("DungeonAction")
        if room and room.Leader == player.UserId then
            for _, id in ipairs(room.Items or {}) do if id == job.rune then return true end end
        end
        return false
    end
    local clock, attempts, started, wasInside, finishAt = -math.huge, 0, nil, false, nil
    local rankGate, tests
    local function message(value)
        questRuntime.worldStatus = value
        questStatus.Text = value
    end
    local function clearJob()
        autoQuest.journey, questRuntime.modeRequest = nil, nil
        state.autoLeaving = nil
        attempts, started, finishAt, wasInside = 0, nil, nil, false
        save()
    end
    if state.questProfiles then state.questProfiles.resetWorldRun=clearJob end
    local function canTest(records)
        rankGate = rankGate or require(shared.RankGate)
        tests = tests or require(storage.Indexer.DgTestInfo)
        local rank = tonumber(clientData.Get("Rank")) or 0
        local info = tests[rank + 1]
        if not info or rank >= balanceInfo.MaxPlayerRank then return false, "Limite de rank atingido." end
        if info.NeedAwaken and clientData.Get("Awaken") ~= true then return false, "Teste exige Awakening." end
        if info.NeedQuest and records[info.NeedQuest] == nil then return false, "Aguardando missão do teste: " .. info.NeedQuest end
        local allowed, reason, details = rankGate.CanRankUp({Rank = rank, GeneralStats = clientData.Get("GeneralStats")})
        if not allowed then return false, rankGate.Message(reason, details, rank + 1) end
        return true
    end
    function state.worldQuestEntryGuard(job, inside)
        if not job then return true end
        if job.bucket then return state.recurringEntryGuard(job,inside) end
        if inside then return false, "Missão de Mundo em andamento; aguardando conclusão." end
        if not autoQuest.enabled or (state.questProfiles and not state.questProfiles.groups(autoQuest).world or not state.questProfiles and autoQuest.scope ~= "all") then return false, "Missões de Mundo pausadas." end
        if state.collectionPriority() or events.active or state.leaving or state.rebirthing then
            return false, "Aguardando o evento prioritário."
        end
        if job.mode == "ranktest" then return canTest(clientData.Get("Quests", "Normal") or {}) end
        local info = nativePartyShared and nativePartyShared.DungeonInfos()
        if job.rune and not validRune(job) then return false, "Missão: sem estoque da runa necessária." end
        if not state.worldQuestPolicy.portalMatches(job, info, tonumber(storage:GetAttribute("World")))
            or tostring(info.ID) ~= tostring(job.portalId) then return false, "Aguardando o portal da ilha exigida pela missão." end
        return true
    end
    function state.worldQuestStep()
        if autoQuest.journey and autoQuest.journey.bucket then return false end
        questRuntime.worldStatus = nil
        local inside = insideDungeon()
        if not autoQuest.enabled or (state.questProfiles and not state.questProfiles.groups(autoQuest).world or not state.questProfiles and autoQuest.scope ~= "all") then
            questRuntime.modeRequest = nil
            if autoQuest.journey and not inside then clearJob() end
            return false
        end
        local activeJob = autoQuest.journey
        if inside and activeJob and (activeJob.enterRequested or activeJob.phase == "inside")
            and (activeJob.mode == "portal" or activeJob.mode == "ranktest") then
            if activeJob.phase ~= "inside" then activeJob.phase = "inside" save() end
            wasInside, questRuntime.modeRequest = true, nil
            if storage:GetAttribute("DungeonCompleted") == true or state.finishedMode == activeJob.mode then
                state.autoLeaving = true
                message("Mundo: partida concluída; retornando para conferir a missão.")
            else message("Mundo: " .. (activeJob.name or activeJob.id) .. " · concluindo a partida.") end
            return true
        end
        if not rootPart() or player.GameplayPaused or player:GetAttribute("Loaded") == false
            or storage:GetAttribute("World") == nil then
            message("Mundo: aguardando carregamento do personagem e da área.")
            return true
        end
        local records, completed = clientData.Get("Quests", "Normal"), clientData.Get("Quests", "Completed")
        if type(records) ~= "table" or type(completed) ~= "table" then
            message("Mundo: aguardando progresso das missões.") return true
        end
        local job = autoQuest.journey
        if job then
            if not state.worldQuestPolicy.goal(job.goal, mapInfo) then clearJob() return false end
            if inside then
                if not job.enterRequested then clearJob() return false end
                if job.phase ~= "inside" then job.phase = "inside" save() end
                wasInside = true
                questRuntime.modeRequest = nil
                if storage:GetAttribute("DungeonCompleted") == true then
                    state.autoLeaving = true
                    message("Mundo: partida concluída; retornando para conferir a missão.")
                else message("Mundo: " .. (job.name or job.id) .. " · concluindo a partida.") end
                return true
            end
            if wasInside or job.phase == "inside" then
                local record = records[job.id]
                local progress = record and record.Progress and record.Progress[job.goal]
                local count = type(progress) == "table" and tonumber(progress.Current) or 0
                local done = completed[job.id] == true or completed[job.definitionId] == true or (record and record.Completed == true)
                questRuntime.worldBackoff = os.clock() + ((done or count > (job.beforeProgress or 0)) and 10 or 60)
                if done then questRuntime.worldBackoff = os.clock() + 2 end
                clearJob()
                message(done and "Mundo: missão concluída; retomando configuração anterior."
                    or "Mundo: conferindo progresso da missão; preferências anteriores preservadas.")
                return true
            end
            local record = records[job.id]
            if completed[job.id] == true or completed[job.definitionId] == true or (record and record.Completed == true) then
                clearJob() return true
            end
            if state.collectionPriority() or events.active or state.leaving or state.rebirthing then
                questRuntime.modeRequest = nil
                message("Mundo: aguardando o evento prioritário.") return true
            end
            local allowed, reason = state.worldQuestEntryGuard(job, false)
            if not allowed then
                clearJob() message("Mundo: " .. tostring(reason)) return false
            end
            started = started or os.clock()
            if os.clock() - started > 150 then
                questRuntime.worldBackoff = os.clock() + 60
                clearJob() message("Mundo: entrada sem confirmação; nova avaliação após a espera.") return false
            end
            questRuntime.modeRequest = {mode = job.mode, enabled = true, checkpoint = 0, key = "", difficulty = dungeon.difficulty}
            message("Mundo: " .. (job.name or job.id) .. " · " .. dungeonStatus.Text)
            return true
        end
        -- Never take over a run that was started manually or by another automation.
        if inside or events.active or state.leaving or state.rebirthing
            or (state.houses.enabled and not state.houses.route.waitUntil) then return false end
        local jobs, claims = state.worldQuestPolicy.candidates(definitions, records, completed, mapInfo)
        if #claims > 0 and os.clock() - clock >= 5 then
            clock = os.clock()
            general:Fire({Event = "ClaimQuest", Type = "Normal", Id = claims[1]})
            message("Mundo: resgatando missão concluída.") return true
        end
        if #jobs == 0 then return false end
        if not autoExecute then message("Mundo: ative Auto Execute em Misc para continuar após o teleporte.") return false end
        if os.clock() < (questRuntime.worldBackoff or 0) then return false end
        loadNative()
        if not nativeOK then message("Mundo: aguardando interface nativa.") return false end
        local world = tonumber(storage:GetAttribute("World"))
        local portal = nativePartyShared.DungeonInfos()
        local reason = "Aguardando portal compatível ou runa da missão; continuando as missões das ilhas."
        for _, candidate in ipairs(jobs) do
            local open = not candidate.release or release.IsOpen(candidate.release)
            local available = false
            if candidate.mode == "portal" then candidate.rune = state.questWorldRune(candidate.map, itemsInfo, runeStock) end
            if open and candidate.mode == "ranktest" and candidate.rank > (tonumber(clientData.Get("Rank")) or 0) then
                available, reason = canTest(records)
            elseif open and state.worldQuestPolicy.portalMatches(candidate, portal, world) then
                local native = nativeModes.portal
                available = native and nativeSchedule(native, workspace:GetServerTimeNow()).Open == true
                if nativePartyShared.DungeonCompleted() and not state.replayAllowed() then available = false end
                if available then candidate.portalId = tostring(portal.ID) end
            end
            if available then
                local record = records[candidate.id]
                local progress = record and record.Progress and record.Progress[candidate.goal]
                candidate.beforeProgress = type(progress) == "table" and tonumber(progress.Current) or 0
                autoQuest.journey = candidate
                autoQuest.journey.phase = "entry"
                if not save() then autoQuest.journey = nil message("Mundo: não foi possível salvar a entrada.") return false end
                started, attempts, wasInside, finishAt = os.clock(), 0, false, nil
                questRuntime.modeRequest = {mode = candidate.mode, enabled = true, checkpoint = 0, key = "", difficulty = dungeon.difficulty}
                message("Mundo: preparando " .. candidate.name .. ".")
                return true
            end
        end
        -- Once island progression is finished, inspect the other eligible worlds
        -- at bounded intervals; only their actual portal can satisfy a dungeon goal.
        if questRuntime.islandsDone then
            local now = workspace:GetServerTimeNow()
            autoQuest.worldVisits = autoQuest.worldVisits or {}
            autoQuest.worldVisits[tostring(world)] = now
            for _, candidate in ipairs(jobs) do
                local nextWorld = candidate.world
                local needRank = ({0, 7, 20})[nextWorld or 0]
                local visited = nextWorld and tonumber(autoQuest.worldVisits[tostring(nextWorld)])
                if nextWorld and nextWorld ~= world and needRank and (tonumber(clientData.Get("Rank")) or 0) >= needRank
                    and (not visited or now - visited >= 300) then
                    autoQuest.worldVisits[tostring(nextWorld)] = now
                    if save() then
                        general:Fire({Event = "WorldTeleport", World = "World" .. nextWorld})
                        message("Mundo: verificando portal no mundo " .. nextWorld .. ".")
                        return true
                    end
                end
            end
        end
        message("Mundo: " .. tostring(reason))
        return false
    end
    local category = farmPage:FindFirstChild("FarmCategoryPROGRESSÃO")
    if category then
        local options = state.controlButton("AutoQuestObjectives", "Objetivos Quest", category)
        connectUI(options, function()
            if state.questProfiles and state.questProfiles.menu then state.questProfiles.menu();return end
            choose("Objetivos do Auto Quest", {{id = "islands", name = "Somente ilhas"}, {id = "recurring", name = "Diárias, semanais e passe"}, {id = "all", name = "Todas as missões"}}, function(id)
                autoQuest.scope = id
                questRuntime.filter,questRuntime.destination,questRuntime.combat=nil,nil,false
                state.target,state.searchPosition=nil,nil;generation+=1
                questRuntime.modeRequest = nil
                if not insideDungeon() then clearJob() end
                save()
            end)
        end)
    end
end
-- END WORLD QUEST RUNTIME
-- A coordinator over existing farm/mode/event controllers; user switches are never overwritten.
do
local api={demands={},backoff={},claimAt=0,captureAt=0}
state.recurringQuests=api
local policy=state.recurringQuestPolicy
local definitions=require(storage.Indexer.QuestsInfo)
local enemies=require(storage.Indexer.EnemyInfo)
local releases=require(shared.Release)
local extra=require(shared.ExtraFunctions)
local captures=state.pausableBridge(require(storage.BridgeNet2).ReferenceBridge("ENEMY_EVENT"))
local function persist()
    if api.testPersist then
        local ok,result=pcall(api.testPersist)
        if not ok or result==false then return false end
    end
    return save()
end
local function tr(pt,en,es) return uiState.language=="PT" and pt or uiState.language=="ES" and es or en end
local function message(text)
    questRuntime.recurringStatus=text
    questStatus.Text=text
end
function state.questWantsEvent(kind)
    if state.limitBreakerStormRequested and state.limitBreakerStormRequested() then return kind=="storm" end
    return policy.enabled(autoQuest) and not state.panic and api.demands[kind]==true
end
function state.questPriorityActive()
    return (state.questProfiles and autoQuest.enabled==true or policy.enabled(autoQuest)) and not state.panic and not state.stopped
end
function state.questPriorityAllows(kind)
    if kind=="storm" and state.limitBreakerStormEnabled and state.limitBreakerStormEnabled() then return true end
    return not state.questPriorityActive() or state.questWantsEvent(kind)
end
function state.limitBreakerStormEnabled()
    local limit=autoQuest.profile=="limitbreaker"
    if autoQuest.splitQuests then limit=autoQuest.limitBreakerEnabled==true end
    if not limit or not policy.enabled(autoQuest) or not storm or storm.enabled~=true or state.panic or state.stopped then return false end
    return true
end
function state.limitBreakerStormRequested()
    if not state.limitBreakerStormEnabled() then return false end
    local map=events.currentStormMap
    local info=map and mapInfo[map]
    return type(info)=="table" and tonumber(info.World)==tonumber(storage:GetAttribute("World"))
end
function state.questTicketStock()
    local inventory=clientData.Get("Inventory","Items")
    if type(inventory)~="table" then return nil,nil end
    local item=inventory.Ticket
    local stock=tonumber(type(item)=="table" and item.Amount or item) or 0
    local ok,capacity=pcall(extra.GetMaxCapacity,player,"Ticket")
    if not ok or type(capacity)~="number" or capacity~=capacity or capacity<=0 or capacity==math.huge then return stock,nil end
    return stock,capacity
end
function state.limitBreakerPortalEnabled()
    local limit=autoQuest.splitQuests and autoQuest.limitBreakerEnabled or autoQuest.profile=="limitbreaker"
    if autoQuest.splitQuests then limit=autoQuest.limitBreakerEnabled==true end
    return limit and policy.enabled(autoQuest) and dungeon.enabled==true and dungeon.mode=="portal"
end
function state.limitBreakerPortalRequested()
    if not state.limitBreakerPortalEnabled() or state.panic or state.stopped or state.autoLeaving or autoQuest.journey
        or state.limitBreakerStormRequested() then return false end
    local stock,capacity=state.questTicketStock()
    local reset=state.questReset
    local refill=(not autoQuest.splitQuests or autoQuest.resetQuests==true) and (not state.questProfiles or state.questProfiles.refill(autoQuest))
    local partial=autoQuest.ticketRefillPartial and reset and reset.canAffordReset and reset.canAffordReset(stock)
    if refill and not partial and stock~=nil and (not capacity or stock<capacity)
        and (stock<=0 or reset and (reset.shortage or reset.ticketShortage and reset.ticketShortage(stock))) then return false end
    return true
end
function state.limitBreakerPortalOwnsRun()
    return state.limitBreakerPortalRequested() and insideDungeon() and state.recurringRunMatches({mode="portal"})
end
local function nativeTrialWaiting()
    -- Recover completion evidence after reloading the Hub inside a finished Trial.
    if type(player.FindFirstChild)~="function" then return false end
    local gui=player:FindFirstChild("PlayerGui")
    local node=gui
    for _,name in ipairs({"Hud","UI_Dungeon","Root","mo_dg","mo_plate","NUI_Note"}) do
        node=node and node:FindFirstChild(name)
    end
    if not node or not node:IsA("TextLabel") then return false end
    local parent=node
    while parent and parent~=gui do
        if parent:IsA("GuiObject") and not parent.Visible or parent:IsA("ScreenGui") and not parent.Enabled then return false end
        parent=parent.Parent
    end
    local text=string.upper(node.Text)
    return text:find("NEXT RUN WHEN THE TIME TRIAL OPENS",1,true)~=nil
        or text:find("CORRIDA QUANDO",1,true)~=nil and text:find("ABERTO",1,true)~=nil
end
function state.questTrialRefillEnded()
    local job=autoQuest.journey
    local limit=autoQuest.splitQuests and autoQuest.limitBreakerEnabled or autoQuest.profile=="limitbreaker"
    if not limit or not policy.enabled(autoQuest) or not job or job.bucket~="TicketFarm" or job.mode~="trial"
        or not insideDungeon() or not state.recurringRunMatches(job) then return false end
    if storage:GetAttribute("DungeonCompleted")~=true and state.finishedMode~="trial" and not nativeTrialWaiting() then return false end
    loadNative()
    local native=nativeModes.trial
    if not nativeOK or not native or type(nativeSchedule)~="function" then return false end
    local ok,schedule=pcall(nativeSchedule,native,workspace:GetServerTimeNow())
    return ok and type(schedule)=="table" and schedule.Open==false
end
function state.questTrialRefillPending()
    if state.limitBreakerStormRequested() then return false end
    local job=autoQuest.journey
    if not policy.enabled(autoQuest) or state.panic or not job or job.bucket~="TicketFarm"
        or job.mode~="trial" or not insideDungeon() or not state.recurringRunMatches(job) then return false end
    if state.questTrialRefillEnded() then return false end
    local stock,maximum=state.questTicketStock()
    if state.refillTeams and state.refillTeams.needsRestart and state.refillTeams.needsRestart(job) then return false end
    return stock~=nil and maximum~=nil and stock<maximum
end
local function eligible(ref)
    return (tonumber(clientData.Get("Rank")) or 0)>=(tonumber(ref.rank) or 0)
        and (not ref.release or releases.IsOpen(ref.release))
end
local function jobRecord(job)
    if job.bucket=="TicketFarm" then
        local stock,maximum=state.questTicketStock()
        if not stock or not maximum then return nil,false end
        return {Name="TicketFarm",Progress={TicketFull={Current=stock,Max=maximum}}},true
    end
    local records=clientData.Get("Quests",job.bucket)
    if type(records)~="table" then return nil,false end
    return records[job.id],true
end
local function pendingGoal(job,record)
    if type(record)~="table" or record.Completed then return false end
    local p=record.Progress and record.Progress[job.goal]
    return type(p)=="table" and tonumber(p.Max) and tonumber(p.Current or 0)
        and tonumber(p.Current or 0)<tonumber(p.Max)
end
function state.recurringRunMatches(job)
    return policy.matches(job,function(key) return storage:GetAttribute(key) end)
end
local function requestFor(job)
    return {mode=job.mode,enabled=true,checkpoint=0,key=job.key or "",difficulty=job.difficulty or "Easy"}
end
local function clearJob()
    local job=autoQuest.journey
    if job and job.bucket=="TicketFarm" and state.refillTeams and not state.refillTeams.finish(job) then message(state.refillTeams.status);return false end
    if job and job.bucket and job.partyRequested and not insideDungeon() then
        local mode=dungeonMode({mode=job.mode})
        local room=partyClient.GetRoom(mode.event)
        if room and room.Leader==player.UserId and not room.Locked then
            general:Fire({Event=mode.event,Action="Leave"})
        end
    end
    autoQuest.journey=job and job.bucket=="TicketFarm" and policy.enabled(autoQuest) and autoQuest.ticketResume or nil
    autoQuest.ticketResume=nil;questRuntime.modeRequest=nil;state.autoLeaving=nil;api.enterAt=nil;api.exitAt=nil
    persist()
end
local function resumeWithPartialTickets(job,stock,capacity)
    if not job or job.bucket~="TicketFarm" or not stock or not capacity or stock>=capacity
        or autoQuest.resetPending or not state.questReset or not state.questReset.canAffordReset
        or not state.questReset.canAffordReset(stock) then return false end
    autoQuest.ticketRefillPartial=true
    state.questReset.shortage=false
    -- clearJob waits for the configured return team before releasing Trial ownership.
    if clearJob()==false then return true end
    message(tr("Trial encerrada: usando os Tickets coletados nas missões.","Trial ended: using collected Tickets for quests.","Trial finalizada: usando los Tickets obtenidos en misiones."))
    return true
end
function state.recurringEntryGuard(job,inside)
    if not policy.enabled(autoQuest) or not policy.validJourney(job) then return false,tr("Missões periódicas pausadas.","Recurring quests paused.","Misiones periódicas pausadas.") end
    if inside then return false,tr("Missão em andamento.","Quest run in progress.","Misión en curso.") end
    if state.rebirthing then return false,tr("Aguardando confirmação do renascimento.","Waiting for Rebirth confirmation.","Esperando confirmación del renacimiento.") end
    if player.GameplayPaused or state.panic or state.collectionPriority() or events.active then return false,tr("Aguardando atividade prioritária.","Waiting for priority activity.","Esperando actividad prioritaria.") end
    local record,loaded=jobRecord(job)
    if loaded and record and (record.Name or job.id)~=job.definitionId then return false,"Auto Quest: o objetivo mudou; conferindo a tarefa." end
    return loaded and pendingGoal(job,record),tr("Aguardando os dados da missão.","Waiting for quest data.","Esperando datos de la misión.")
end
local function modeKey(mode)
    local info=dungeonMode({mode=mode})
    local inventory=clientData.Get("Inventory","Items")
    if type(inventory)~="table" then return nil end
    if mode=="key" then return state.autoIslandKey and state.autoIslandKey(dungeon.key) end
    if info.keys then
        for _,id in ipairs(info.keys) do
            local value=inventory[id]
            if (tonumber(type(value)=="table" and value.Amount or value) or 0)>0 then return id end
        end
        return nil
    end
    return ""
end
function state.questFixedIslandOptions()
    local result={}
    local rank=tonumber(clientData.Get("Rank")) or 0
    for id,info in pairs(mapInfo) do
        local world=type(info)=="table" and tonumber(info.World)
        local required=({0,7,20})[world or 0]
        if type(id)=="string" and required and rank>=required and (not info.Release or releases.IsOpen(info.Release)) then
            result[#result+1]={id=id,world=world,order=tonumber(info.Order) or 9999,name=tostring(info.Name or id).." · "..world}
        end
    end
    table.sort(result,function(a,b) if a.world~=b.world then return a.world<b.world end;if a.order~=b.order then return a.order<b.order end;return a.name<b.name end)
    return result
end
function state.fixedFarmAnchor(id)
    if tonumber(storage:GetAttribute("World"))==3 and (id=="FateWorld" or tostring(id)=="28") then
        -- User-selected standing point on Grail Dominion's upper bridge.
        return Vector3.new(3191.45263671875,75.14868927001953,-3104.767822265625)
    end
end
function state.questIslandCenter(id,info,fallback)
    local fixed=state.fixedFarmAnchor(id)
    if fixed then return fixed-Vector3.new(0,4,0) end -- Caller adds the standing offset.
    api.islandCenters=api.islandCenters or {}
    local key=tostring(info.World)..":"..id
    local saved=api.islandCenters[key]
    if saved then return saved end
    local minX,maxX,minZ,maxZ,totalY,count
    totalY,count=0,0
    local folder=enemyFolder()
    for _,enemy in ipairs(folder and folder:GetChildren() or {}) do
        local map=enemy:GetAttribute("MapId")
        if enemy:IsA("BasePart") and (map==id or tostring(map)==tostring(info.Order)) then
            local p=enemy.Position
            minX=minX and math.min(minX,p.X) or p.X;maxX=maxX and math.max(maxX,p.X) or p.X
            minZ=minZ and math.min(minZ,p.Z) or p.Z;maxZ=maxZ and math.max(maxZ,p.Z) or p.Z
            totalY+=p.Y;count+=1
        end
    end
    if count>=2 then
        local center=Vector3.new((minX+maxX)/2,totalY/count,(minZ+maxZ)/2)
        api.islandCenters[key]=center
        return center
    end
    local main=workspace:FindFirstChild("__Main")
    local world=main and main:FindFirstChild("__World")
    local model=world and world:FindFirstChild("World "..tostring(info.Order))
    if model and model:IsA("Model") then
        local ok,cf=pcall(model.GetBoundingBox,model)
        if ok and cf then return Vector3.new(cf.Position.X,fallback.Y,cf.Position.Z) end
    end
    return fallback
end
local function farm(group)
    local root=rootPart()
    local spawns=workspace:FindFirstChild("__Extra")
    spawns=spawns and spawns:FindFirstChild("__Spawns")
    local world=tonumber(storage:GetAttribute("World"))
    if not root or not spawns or not world then return false end
    local fixed=autoQuest.splitQuests and state.limitBreaker.enabled(autoQuest) and autoQuest.fixedIslandEnabled and autoQuest.fixedIsland
    if autoQuest.fixedIslandEnabled and autoQuest.splitQuests and state.limitBreaker.enabled(autoQuest) then
        local info=fixed and mapInfo[fixed]
        if not info or info.Release and not releases.IsOpen(info.Release) then
            message(tr("Ilha fixa: selecione uma ilha disponível.","Fixed island: select an available island.","Isla fija: elige una isla disponible."));return true
        end
        if tonumber(info.World)~=world then
            local needRank=({0,7,20})[tonumber(info.World) or 0]
            if not needRank or (tonumber(clientData.Get("Rank")) or 0)<needRank then message(tr("Ilha fixa: mundo ainda bloqueado pelo rank.","Fixed island: world is still rank locked.","Isla fija: mundo bloqueado por rango."));return true end
            if not autoExecute then message(tr("Ilha fixa: ative Auto Execute para trocar de mundo.","Fixed island: enable Auto Execute to change worlds.","Isla fija: activa Auto Execute para cambiar de mundo."));return true end
            if os.clock()>=(api.fixedWorldAt or 0) then
                api.fixedWorldAt=os.clock()+20
                if persist() then general:Fire({Event="WorldTeleport",World="World"..info.World}) end
            end
            message(tr("Ilha fixa: viajando para ","Fixed island: traveling to ","Isla fija: viajando a ")..tostring(info.Name or fixed));return true
        end
    end
    local selected,position,distance
    for id,info in pairs(mapInfo) do
        if fixed and id~=fixed then continue end
        local spawn=info.World==world and spawns:FindFirstChild(id)
        if spawn and (not info.Release or releases.IsOpen(info.Release)) then
            local point=spawn:GetPivot().Position
            if not fixed and autoQuest.splitQuests and state.limitBreaker.enabled(autoQuest) then
                api.islandWait=api.islandWait or {}
                if os.clock()<(api.islandWait[id] or 0) then continue end

            end
            local d=(point-root.Position).Magnitude
            if not distance or d<distance then selected,position,distance={id=id,info=info},point,d end
        end
    end
    if not selected then
        api.islandWait={}
        if fixed then message(tr("Ilha fixa: aguardando o ponto da ilha carregar.","Fixed island: waiting for the island spawn to load.","Isla fija: esperando que cargue la isla."));return true end
        return false
    end
    local farmKey=group.activity..":"..selected.id
    if api.farmKey~=farmKey then
        api.farmKey=farmKey;state.target,state.map,state.searchPosition=nil,nil,nil;generation+=1
    end
    local filter={kind=group.filter,map=selected.id,order=selected.info.Order,info=enemies}
    questRuntime.filter=filter;questRuntime.island=selected.id
    if group.filter=="arise" then
        local inventory=clientData.Get("Inventory","Pets")
        if type(inventory)~="table" then return false end
        local count=0;for _ in pairs(inventory) do count+=1 end
        if count>=extra.GetTotalPets(player) then
            message(tr("Auto Quest: inventário de sombras cheio.","Auto Quest: shadow inventory full.","Auto Quest: inventario de sombras lleno."));return true
        end
        for _,enemy in ipairs(enemyFolder() and enemyFolder():GetChildren() or {}) do
            local id=enemy:GetAttribute("Id")
            if enemy:IsA("BasePart") and enemyState.Dead(enemy) and not enemyState.Arised(enemy)
                and questEnemyMatches(filter,id,enemy:GetAttribute("MapId"),enemies[id]) then
                questRuntime.destination=enemy.Position+Vector3.new(0,3,4)
                if (enemy.Position-root.Position).Magnitude<15 and os.clock()>=api.captureAt then
                    api.captureAt=os.clock()+3;captures:Fire({Event="EnemyCapture",Enemy=enemy.Name})
                end
                return true
            end
        end
    end
    questRuntime.combat=true
    local centered=autoQuest.splitQuests and state.limitBreaker.enabled(autoQuest)
    if centered then
        questRuntime.destination=state.questIslandCenter(selected.id,selected.info,position)+Vector3.new(0,4,0)
    end
    if not nearest(enemyFolder(),root.Position,nil,filter) then
        if not centered then questRuntime.destination=position+Vector3.new(0,4,0) end
        if not fixed and autoQuest.splitQuests and state.limitBreaker.enabled(autoQuest) then
            if api.scanIsland~=selected.id then api.scanIsland=selected.id;api.scanAt=os.clock() end
            if os.clock()-(api.scanAt or 0)>=3 then api.islandWait[selected.id]=os.clock()+12;api.scanIsland=nil end
        end
    else api.scanIsland=nil end
    return true
end
function state.recurringQuestStep()
    questRuntime.recurringStatus=nil
    api.demands={}
    if not policy.enabled(autoQuest) then
        api.stage=nil;api.hasModePending=false
        if autoQuest.journey and autoQuest.journey.bucket and not insideDungeon() then clearJob() end
        return false
    end
    if state.rebirthing then
        questRuntime.modeRequest=nil;questRuntime.combat=false;questRuntime.destination=nil
        message(tr("Auto Quest: aguardando confirmação do renascimento.","Auto Quest: waiting for Rebirth confirmation.","Auto Quest: esperando confirmación del renacimiento."));return true
    end
    if state.panic or player.GameplayPaused or not rootPart() then return false end
    if api.testPersist then
        local ok,result=pcall(api.testPersist)
        if not ok or result==false then return false end
    end
    local groups,claims,blocked=policy.scan(definitions,clientData.Get,autoQuest)
    api.groups,api.blocked=groups,blocked
    if state.limitBreakerStormRequested() then
        api.demands={storm=true};api.hasModePending=true
        questRuntime.filter=nil;questRuntime.destination=nil;questRuntime.modeRequest=nil;questRuntime.combat=false
        if insideDungeon() then
            state.autoLeaving=true
            if os.clock()>=(api.exitAt or 0) then api.exitAt=os.clock()+8;state.requestDungeonExit() end
            message(tr("Limit Breaker: saindo do modo para a Storm ativa.","Limit Breaker: leaving the mode for the active Storm.","Limit Breaker: saliendo del modo para la Storm activa."))
            return true
        end
        state.autoLeaving=nil
        if #claims>0 and os.clock()>=api.claimAt then
            api.claimAt=os.clock()+8
            local claim=claims[1];general:Fire({Event="ClaimQuest",Type=claim.bucket,Id=claim.id})
        end
        message(tr("Limit Breaker: permanecendo na ilha da Storm até o evento terminar.","Limit Breaker: staying on the Storm island until the event ends.","Limit Breaker: permaneciendo en la isla de la Storm hasta que termine el evento."))
        return true
    end
    api.hasModePending=false
    for _,group in ipairs(groups) do if group.kind=="mode" then api.hasModePending=true end end
    for _,item in ipairs(blocked) do
        local action=item.goal and policy.action(item.goal)
        if action and action.kind=="mode" then api.hasModePending=true end
    end
    local firstStage
    for _,group in ipairs(groups) do
        if group.kind=="farm" or group.kind=="mode" or group.kind=="event" then
            for _,ref in ipairs(group.refs) do if eligible(ref) then firstStage=policy.stage(group);break end end
            if firstStage then break end
        end
    end
    api.stage=firstStage
    for _,group in ipairs(groups) do
        if group.kind=="event" and firstStage==3 and not (autoQuest.journey and autoQuest.journey.bucket) then
            for _,ref in ipairs(group.refs) do if eligible(ref) then api.demands[group.activity]=true;break end end
        end
    end
    local job=autoQuest.journey
    if state.limitBreakerPortalEnabled() and job and job.bucket~="TicketFarm" then
        clearJob();job=autoQuest.journey
    end
    if firstStage and job and job.bucket and job.bucket~="TicketFarm" then
        local action=policy.action(job.goal)
        local superseded=action and policy.stage(action)>firstStage
        if autoQuest.splitQuests then
            local first=groups[1]
            local ownRank=state.limitBreaker.priority(autoQuest,{bucket=job.bucket,definitionId=job.definitionId})
            local best=math.huge
            for _,ref in ipairs(first and first.refs or {}) do best=math.min(best,state.limitBreaker.priority(autoQuest,ref)) end
            superseded=best<ownRank or not state.limitBreaker.selected(autoQuest,job.bucket,job.definitionId)
        end
        if superseded then
            questRuntime.modeRequest=nil
            if insideDungeon() then
                state.autoLeaving=true
                if os.clock()>=(api.exitAt or 0) then api.exitAt=os.clock()+8;state.requestDungeonExit() end
                message("Limit Breaker: retornando para respeitar a prioridade escolhida.");return true
            end
            clearJob();job=nil
        end
    end
    local stock,capacity=state.questTicketStock()
    if job and job.bucket=="TicketFarm" and job.phase=="inside" and not insideDungeon()
        and not (state.refillTeams and state.refillTeams.needsRestart and state.refillTeams.needsRestart(job))
        and resumeWithPartialTickets(job,stock,capacity) then return true end
    local ticketShortage=state.questReset and (state.questReset.shortage==true or state.questReset.ticketShortage and state.questReset.ticketShortage(stock))
    local spendingPartial=autoQuest.ticketRefillPartial and state.questReset and state.questReset.canAffordReset and state.questReset.canAffordReset(stock)
    local refill=not spendingPartial and (not autoQuest.splitQuests or autoQuest.resetQuests==true and ticketShortage) and (not state.questProfiles or state.questProfiles.refill(autoQuest)) and stock~=nil and (stock<=0 or ticketShortage) and (not capacity or stock<capacity)
    if refill and (not job or job.bucket~="TicketFarm") then
        api.demands={};api.hasModePending=true
        if not capacity then message("Auto Quest: aguardando capacidade nativa de Tickets para a Trial.");return true end
        if insideDungeon() then
            state.autoLeaving=true;questRuntime.modeRequest=nil
            if os.clock()>=(api.exitAt or 0) then api.exitAt=os.clock()+8;state.requestDungeonExit() end
            message("Auto Quest: retornando para repor Tickets na Trial.");return true
        end
        autoQuest.ticketRefillPartial=nil
        autoQuest.ticketResume=job
        local refillConfig=autoQuest.refillConfig or {}
        autoQuest.journey={bucket="TicketFarm",id="tickets",definitionId="TicketFarm",goal="TicketFull",mode="trial",name="Tickets",key="",difficulty=refillConfig.difficulty or "Easy",farmTeam=refillConfig.farmTeam,returnTeam=refillConfig.returnTeam,phase="entry",beforeProgress=stock}
        if not persist() then autoQuest.journey=job;autoQuest.ticketResume=nil;message("Auto Quest: falha ao salvar a reposição de Tickets.");return true end
        job=autoQuest.journey;api.enterAt=nil;api.exitAt=nil
    end
    if not job and state.limitBreakerPortalEnabled() and not insideDungeon() then state.autoLeaving=nil end
    if not job and state.limitBreakerPortalRequested() then
        api.demands={};api.hasModePending=false
        questRuntime.filter=nil;questRuntime.destination=nil;questRuntime.modeRequest=nil
        questRuntime.combat=state.limitBreakerPortalOwnsRun()
        if insideDungeon() and not questRuntime.combat then
            state.autoLeaving=true
            if os.clock()>=(api.exitAt or 0) then api.exitAt=os.clock()+8;state.requestDungeonExit() end
            message(tr("Limit Breaker: retornando para o Portal selecionado.","Limit Breaker: returning to the selected Portal.","Limit Breaker: regresando al Portal seleccionado."));return true
        end
        if #claims>0 and os.clock()>=api.claimAt then
            api.claimAt=os.clock()+8
            local claim=claims[1];general:Fire({Event="ClaimQuest",Type=claim.bucket,Id=claim.id})
        end
        message(tr("Limit Breaker: farm pelo Auto Dungeon · Portal. Reposição na Trial quando faltarem Tickets.","Limit Breaker: farming through Auto Dungeon · Portal. Trial refill when Tickets are insufficient.","Limit Breaker: farmeando con Auto Dungeon · Portal. Trial cuando falten Tickets."))
        return true
    end
    if job and job.bucket then
        if not policy.validJourney(job) then clearJob();return false end
        if job.bucket=="TicketFarm" and state.refillTeams and state.refillTeams.sync and not state.refillTeams.sync(job) then message(state.refillTeams.status);return true end
        local record,loaded=jobRecord(job)
        if not loaded then message(tr("Auto Quest: aguardando progresso.","Auto Quest: waiting for progress.","Auto Quest: esperando progreso."));return true end
        local inside=insideDungeon()
        if inside then
            if not job.enterRequested then return false end
            if not state.recurringRunMatches(job) then
                questRuntime.modeRequest=nil;state.autoLeaving=true
                if os.clock()>=(api.exitAt or 0) then api.exitAt=os.clock()+8;state.requestDungeonExit() end
                message(tr("Auto Quest: modo atual não corresponde ao objetivo; retornando para entrar em ","Auto Quest: current mode does not match the objective; returning to enter ","Auto Quest: el modo actual no corresponde; regresando para entrar en ")..job.mode)
                return true
            end
            if job.phase~="inside" then job.phase="inside";persist() end
            questRuntime.modeRequest=nil
            if job.bucket=="TicketFarm" and pendingGoal(job,record) and state.refillTeams then
                if state.refillTeams.needsRestart and state.refillTeams.needsRestart(job) then
                    state.autoLeaving=true
                    if os.clock()>=(api.exitAt or 0) then api.exitAt=os.clock()+8;state.requestDungeonExit() end
                    message(tr("Trial: retornando para aplicar a dificuldade ","Trial: returning to apply difficulty ","Trial: regresando para aplicar la dificultad ")..job.difficulty);return true
                end
                if not state.refillTeams.prepare(job) then message(state.refillTeams.status);return true end
            end
            local action=job.bucket=="TicketFarm" and {partial=true} or policy.action(job.goal)
            local done=storage:GetAttribute("DungeonCompleted")==true or state.finishedMode==job.mode
            local refillEnded=job.bucket=="TicketFarm" and state.questTrialRefillEnded()
            local fillingTickets=job.bucket=="TicketFarm" and pendingGoal(job,record) and not refillEnded
            if fillingTickets then state.autoLeaving=nil end
            if refillEnded or done and not fillingTickets or action.partial and not pendingGoal(job,record) then
                -- Finite modes finish normally; wave/floor objectives can return once their active target is met.
                state.autoLeaving=true
                if os.clock()>=(api.exitAt or 0) then
                    api.exitAt=os.clock()+8
                    if not done or not state.nativeExitAfterRun or not state.nativeExitAfterRun(job.mode) then state.requestDungeonExit() end
                end
                message(refillEnded and tr("Limit Breaker: Trial encerrada; saindo para usar os Tickets coletados.","Limit Breaker: Trial ended; leaving to use collected Tickets.","Limit Breaker: Trial finalizada; saliendo para usar los Tickets obtenidos.")
                    or tr("Auto Quest: retornando para conferir as missões.","Auto Quest: returning to check quests.","Auto Quest: regresando para comprobar misiones."))
            else
                local progress=record and record.Progress and record.Progress[job.goal]
                local current=progress and tonumber(progress.Current) or job.beforeProgress or 0
                if current~=(job.observedProgress or job.beforeProgress) then job.observedProgress=current;api.progressAt=os.clock() end
                api.progressAt=api.progressAt or os.clock()
                message(job.name.." · "..job.mode.." · "..current.."/"..tostring(progress and progress.Max or "?")..(os.clock()-api.progressAt>=90 and tr(" — sem progresso confirmado neste objetivo."," — no confirmed progress for this objective."," — sin progreso confirmado en este objetivo.") or ""))
            end
            return true
        end
        if job.phase=="inside" then
            if not pendingGoal(job,record) then clearJob();return true end
            job.phase="entry";job.enterRequested=nil;job.partyRequested=nil;job.beforeProgress=record.Progress[job.goal].Current
            state.autoLeaving=nil;api.enterAt=os.clock();api.progressAt=nil;persist()
        end
        state.autoLeaving=nil
        if not pendingGoal(job,record) then clearJob();return true end
        api.enterAt=api.enterAt or os.clock()
        if (record.Name or job.id)~=job.definitionId then clearJob();return true end
        if not autoExecute then message("Auto Quest: ative Auto Execute para entrar no modo exigido.");return true end
        if job.bucket=="TicketFarm" and state.refillTeams and not state.refillTeams.prepare(job) then message(state.refillTeams.status);return true end
        if state.syncQuestAFK then
            local ok,ready=pcall(state.syncQuestAFK,job.mode)
            if not ok or not ready then message("Auto Quest: aguardando suspender entradas AFK concorrentes.");return true end
        end
        local key=modeKey(job.mode)
        if not key then message("Auto Quest: sem a chave exigida para "..job.mode.."; mantendo este objetivo.");return true end
        job.key=key
        if job.mode=="key" then
            local catalog=require(storage.Indexer.KeyDungeons)
            job.expectedMap=catalog and catalog[key] and catalog[key].Map
        end
        loadNative()
        local mode=dungeonMode({mode=job.mode})
        local native=nativeModes[job.mode] or (mode.keys and nativeModes.key)
        if not nativeOK or not native or nativeSchedule(native,workspace:GetServerTimeNow()).Open~=true then
            if nativeOK and native and job.bucket=="TicketFarm" and resumeWithPartialTickets(job,stock,capacity) then return true end
            message("Auto Quest: aguardando abrir "..job.mode.."; não entrarei em outro modo.");return true
        end
        local party=partyClient.GetRoom(mode.event)
        if party and not job.partyRequested then message("Auto Quest: existe um grupo anterior; saia dele para iniciar "..job.mode..".");return true end
        questRuntime.modeRequest=requestFor(job)
        message(tr("Auto Quest: preparando ","Auto Quest: preparing ","Auto Quest: preparando ")..job.name.." · "..dungeonStatus.Text)
        return true
    end
    if job then return false end
    if insideDungeon() then
        state.autoLeaving=true;questRuntime.modeRequest=nil
        if os.clock()>=(api.exitAt or 0) then api.exitAt=os.clock()+8;state.requestDungeonExit() end
        message("Auto Quest: saindo da partida anterior para cumprir a prioridade das missões.");return true
    end
    if #claims>0 and os.clock()>=api.claimAt then
        api.claimAt=os.clock()+8
        local claim=claims[1]
        general:Fire({Event="ClaimQuest",Type=claim.bucket,Id=claim.id})
        message(tr("Auto Quest: resgatando ","Auto Quest: claiming ","Auto Quest: recogiendo ")..claim.name)
        return true
    end
    if events.active then message(tr("Auto Quest: evento em andamento — ","Auto Quest: event in progress — ","Auto Quest: evento en curso — ")..events.active);return true end
    if state.collectionPriority() or state.leaving or state.rebirthing or os.clock()<(state.entryUntil or 0) or state.raidTravel then return false end
    local waiting={}
    for groupIndex,group in ipairs(groups) do
        if autoQuest.splitQuests and groupIndex>1 then break end
        if firstStage and policy.stage(group)~=firstStage then continue end
        if group.kind=="event" then
            message(tr("Auto Quest: aguardando a raid exigida antes dos castelos e desertos.","Auto Quest: waiting for the required raid before castles and deserts.","Auto Quest: esperando la raid requerida antes de castillos y desiertos."));return true
        end
        if group.kind=="passive" or group.kind=="manual" then
            waiting[#waiting+1]=group.activity
            continue
        end
        local ref
        for _,candidate in ipairs(group.refs) do if eligible(candidate) then ref=candidate;break end end
        if not ref then waiting[#waiting+1]=group.activity..": rank/release";continue end
        if os.clock()<(api.backoff[group.activity] or 0) then waiting[#waiting+1]=group.activity..": retry";continue end
        local progress=0
        local signature={group.activity}
        for _,v in ipairs(group.refs) do progress+=v.current;signature[#signature+1]=v.bucket..":"..v.id..":"..v.goal..":"..v.maximum end
        signature=table.concat(signature,"|")
        if not api.monitor or api.monitor.signature~=signature or api.monitor.progress~=progress then api.monitor={signature=signature,progress=progress,at=os.clock()} end
        if os.clock()-api.monitor.at>90 then api.backoff[group.activity]=os.clock()+60;api.monitor=nil;continue end
        local prefix=ref.bucket.." · "..ref.name.." · "..ref.current.."/"..ref.maximum
        if group.kind=="farm" then
            message(prefix)
            if farm(group) then return true end
            message("Auto Quest: aguardando os inimigos da ilha para concluir esta etapa.");return true
        elseif group.kind=="mode" then
            local key=modeKey(group.mode)
            autoQuest.journey={bucket=ref.bucket,id=ref.id,definitionId=ref.definitionId,goal=ref.goal,mode=group.mode,
                name=ref.name,key=key or "",difficulty="Easy",phase="entry",beforeProgress=ref.current}
            if not persist() then autoQuest.journey=nil;message(tr("Auto Quest: falha ao salvar a entrada.","Auto Quest: could not save entry.","Auto Quest: error al guardar entrada."));return true end
            api.enterAt=os.clock();api.exitAt=nil;questRuntime.modeRequest=nil
            message(prefix);return true
        end
    end
    if #waiting>0 or #blocked>0 then
        local text=tr("Auto Quest: aguardando evento/requisito; expedições exigem ação manual.","Auto Quest: waiting for event/requirements; expeditions need manual action.","Auto Quest: esperando evento/requisito; expediciones requieren acción manual.")
        message(text.."\n"..table.concat(waiting,", "))
    end
    return firstStage~=nil or autoQuest.scope=="recurring"
end
end
-- Native team keybind receipts; manual Dungeon preferences remain independent.
do
local api={status=""};state.refillTeams=api
local function tr(pt,en,es) return uiState.language=="PT" and pt or uiState.language=="ES" and es or en end
function api.catalog()
    local teams=clientData.Get("Teams")
    local rows={}
    if type(teams)~="table" then return rows end
    for id,team in pairs(teams) do
        if type(id)=="string" and type(team)=="table" then
            local key=team.Key and tostring(team.Key) or ""
            key=state.teamSwitchKeys and state.teamSwitchKeys[key] or key
            rows[#rows+1]={id=id,name=(key~="" and key.." · " or "")..tostring(team.Name or id)}
        end
    end
    table.sort(rows,function(a,b) return a.name<b.name end);return rows
end
function api.owns()
    return autoQuest.refillTeamPending~=nil or autoQuest.journey and autoQuest.journey.bucket=="TicketFarm"
end
function api.isEquipped(id,team)
    local named=tostring(player:GetAttribute("TeamWorn"))==id
    -- TeamWorn can be absent after teleport; the native UI also checks actual equipment.
    local equipped=clientData.Get("Equips")
    local inventory=clientData.Get("Inventory")
    if type(equipped)~="table" or type(inventory)~="table" or type(team.Pets)~="table" or type(equipped.Pets)~="table" then return named end
    local extra=require(shared.ExtraFunctions)
    local maximum=tonumber(extra.GetMaxPets(player))
    if not maximum or maximum<=0 then return false end
    local function sameSet(expected,actual)
        local a,b={},{}
        for key,value in pairs(expected) do if type(value)=="string" then a[value]=true elseif value==true then a[key]=true end end
        for key,value in pairs(actual) do if type(value)=="string" then b[value]=true elseif value==true then b[key]=true end end
        for uid in pairs(a) do if not b[uid] then return false end end
        for uid in pairs(b) do if not a[uid] then return false end end
        return true
    end
    local pets={}
    if type(inventory.Pets)~="table" then return false end
    for _,uid in ipairs(team.Pets) do if #pets<maximum and inventory.Pets[uid] then pets[#pets+1]=uid end end
    if not sameSet(pets,equipped.Pets) then return false end
    if type(team.Relics)=="table" and #team.Relics>0 then
        if type(inventory.Relics)~="table" or type(equipped.Relics)~="table" then return false end
        local limit=tonumber(extra.GetMaxRelics(player));if not limit or limit<=0 then return false end
        local relics,seen={},{}
        for _,uid in ipairs(team.Relics) do
            local item=inventory.Relics[uid]
            local kind=type(item)=="table" and item.Name or uid
            if item and #relics<limit and not seen[kind] then relics[#relics+1]=uid;seen[kind]=true end
        end
        if not sameSet(relics,equipped.Relics) then return false end
    end
    for slot,field in pairs({Main="Weapon",Dual="DualWeapon",Third="ThirdWeapon"}) do
        local uid=team.Weapons and team.Weapons[slot]
        if uid and equipped[field]~=uid then return false end
    end
    for slot,field in pairs({Main="Title",Dual="DualTitle"}) do
        local title=team.Titles and team.Titles[slot]
        if title and equipped[field]~=title then return false end
    end
    for slot,uid in pairs(team.Acessorys or {}) do if uid~=false and (equipped.Acessorys or {})[slot]~=uid then return false end end
    if type(team.Talents)=="string" and clientData.Get("Passes","DualTalents")==true and equipped.Talents~=team.Talents then return false end
    return true
end
function api.sync(job)
    local config=autoQuest.refillConfig or {}
    local difficulty=config.difficulty or "Easy"
    if job.difficulty==difficulty and job.farmTeam==config.farmTeam and job.returnTeam==config.returnTeam then return true end
    local old={difficulty=job.difficulty,farmTeam=job.farmTeam,returnTeam=job.returnTeam}
    job.difficulty=difficulty;job.farmTeam=config.farmTeam;job.returnTeam=config.returnTeam
    if not save() then
        job.difficulty=old.difficulty;job.farmTeam=old.farmTeam;job.returnTeam=old.returnTeam
        api.status=tr("Falha ao salvar opções atualizadas da Trial.","Could not save updated Trial options.","No se pudieron guardar las opciones actualizadas de Trial.");return false
    end
    return true
end
function api.needsRestart(job)
    if not insideDungeon() then return false end
    local actual=storage:GetAttribute("TimeTrialDifficulty")
    return type(actual)=="string" and actual~=((autoQuest.refillConfig or {}).difficulty or job.difficulty)
end
function api.equip(id,phase)
    if not id or id=="" then
        local previous=autoQuest.refillTeamPending
        if previous then return api.equip(previous.id,previous.phase) end
        api.status="";return true
    end
    local teams=clientData.Get("Teams")
    if type(teams)~="table" or type(teams[id])~="table" then api.status=tr("Reposição: time selecionado não existe mais. Escolha outro.","Refill: selected team no longer exists. Choose another.","Reposición: el equipo elegido ya no existe. Elige otro.");return false end
    local pending=autoQuest.refillTeamPending
    if pending and (pending.id~=id or pending.phase~=phase) then
        -- No overlapping key presses; an old unconfirmed request can be superseded
        -- after its replication window instead of deadlocking a new selection.
        if workspace:GetServerTimeNow()-(pending.at or 0)<8 then
            api.status=tr("Reposição: aguardando a troca de time anterior.","Refill: waiting for the previous team switch.","Reposición: esperando el cambio de equipo anterior.");return false
        end
        local old=pending;autoQuest.refillTeamPending=nil
        if not save() then autoQuest.refillTeamPending=old;return false end
        pending=nil
    end
    if api.isEquipped(id,teams[id]) then
        if pending then
            autoQuest.refillTeamPending=nil
            if not save() then autoQuest.refillTeamPending=pending;api.status=tr("Falha ao salvar a confirmação do time.","Could not save team confirmation.","Error al guardar la confirmación del equipo.");return false end
        end
        api.status="";return true
    end
    local now=workspace:GetServerTimeNow()
    if state.panic or state.stopped or player.GameplayPaused or state.rebirthing or player:GetAttribute("KeyChanging")==true or Input:GetFocusedTextBox() then
        api.status=tr("Reposição: aguardando carregamento, renascimento ou fim da digitação para apertar a tecla.","Refill: waiting for loading, rebirth or text input to finish before pressing the key.","Reposición: esperando carga, renacimiento o fin de escritura antes de pulsar la tecla.");return false
    end
    if pending and now-(pending.at or now)<8 then
        api.status=tr("Reposição: aguardando confirmar time ","Refill: waiting to confirm team ","Reposición: esperando confirmar equipo ")..tostring(teams[id].Name or id);return false
    end
    if pending and (pending.attempts or 0)>=3 then
        api.status=tr("Reposição: time não confirmado após 3 tentativas; revise a seleção.","Refill: team unconfirmed after 3 attempts; review selection.","Reposición: equipo sin confirmar tras 3 intentos; revisa la selección.");return false
    end
    local key=teams[id].Key and tostring(teams[id].Key) or ""
    if not (state.teamSwitchKeys and state.teamSwitchKeys[key]) then
        local native
        for name,label in pairs(state.teamSwitchKeys or {}) do if label==key then native=name;break end end
        key=native
    end
    if not key or not state.sendTeamSwitchKey then
        api.status=tr("Reposição: o time selecionado não possui uma keybind numérica válida.","Refill: selected team has no valid numeric keybind.","Reposición: el equipo seleccionado no tiene una tecla numérica válida.");return false
    end
    local receipt={id=id,phase=phase,at=now,attempts=(pending and pending.attempts or 0)+1}
    autoQuest.refillTeamPending=receipt
    if not save() then autoQuest.refillTeamPending=pending;api.status=tr("Falha ao salvar troca de time; nenhum pedido enviado.","Could not save team switch; no request sent.","Error al guardar el cambio de equipo; no se envió solicitud.");return false end
    local ok,problem=state.sendTeamSwitchKey(key)
    if not ok then
        api.status=tr("Reposição: falha ao apertar a tecla do time: ","Refill: could not press team key: ","Reposición: no se pudo pulsar la tecla del equipo: ")..tostring(problem)
        return false
    end
    api.status=tr("Reposição: solicitando time ","Refill: requesting team ","Reposición: solicitando equipo ")..tostring(teams[id].Name or id)
    return false
end
function api.prepare(job)
    if not api.sync(job) then return false end
    local valid=false
    for _,option in ipairs(trialDifficulties) do if option.id==job.difficulty then valid=true end end
    if not valid then api.status=tr("Reposição: dificuldade da Trial indisponível. Escolha outra.","Refill: Trial difficulty unavailable. Choose another.","Reposición: dificultad de Trial no disponible. Elige otra.");return false end
    if job.returnTeam then
        local teams=clientData.Get("Teams")
        if type(teams)~="table" or type(teams[job.returnTeam])~="table" then api.status=tr("Reposição: selecione um time de retorno válido antes de entrar.","Refill: select a valid return team before entering.","Reposición: elige un equipo de retorno válido antes de entrar.");return false end
    end
    return api.equip(job.farmTeam,"farm")
end
function api.finish(job)
    if insideDungeon() then return false end
    if not api.sync(job) then return false end
    local pending=autoQuest.refillTeamPending
    -- A cancelled entry still reconciles the last native equip request first.
    if pending and pending.phase=="farm" then
        if not api.equip(pending.id,"farm") then return false end
    end
    return api.equip(job.returnTeam,"return")
end
function api.change(key,value)
    if key~="difficulty" and key~="farmTeam" and key~="returnTeam" then return false end
    local old,oldPending,oldJob=autoQuest.refillConfig,autoQuest.refillTeamPending,autoQuest.journey
    local config=table.clone(old or {});config[key]=value~="" and value or nil
    autoQuest.refillConfig=config
    local job=autoQuest.journey
    if job and job.bucket=="TicketFarm" then
        local pending=autoQuest.refillTeamPending
        local teams=clientData.Get("Teams")
        local missing=pending and type(teams)=="table" and not teams[pending.id]
        if pending and key~="difficulty" and ((pending.attempts or 0)>=3 or missing) then autoQuest.refillTeamPending=nil;pending=nil end
        if not pending then
            job=table.clone(job);job.difficulty=config.difficulty or "Easy";job.farmTeam=config.farmTeam;job.returnTeam=config.returnTeam;autoQuest.journey=job
        end
    end
    if not save() then autoQuest.refillConfig=old;autoQuest.refillTeamPending=oldPending;autoQuest.journey=oldJob;api.status=tr("Falha ao salvar opções da Trial.","Could not save Trial options.","Error al guardar las opciones de Trial.");return false end
    return true
end
task.spawn(function()
    while alive do
        task.wait(1)
        if not alive then break end
        local job=autoQuest.journey
        if job and job.bucket=="TicketFarm" and not insideDungeon() and (not autoQuest.enabled or autoQuest.refillTickets==false or autoQuest.splitQuests and not autoQuest.limitBreakerEnabled) then
            local ok,done=pcall(api.finish,job)
            if ok and done then
                local previous,previousResume=autoQuest.journey,autoQuest.ticketResume;autoQuest.journey=nil;autoQuest.ticketResume=nil
                if not save() then autoQuest.journey=previous;autoQuest.ticketResume=previousResume end
            elseif not ok then api.status=tostring(done) end
        end
    end
end)
end
-- Live profile changes use the existing quest entry/exit and saved preferences.
do
local api=state.questProfiles
function api.commit(profile,detail)
    if profile~="progression" and profile~="limitbreaker" and profile~="custom" then return false end
    local previous=table.clone(autoQuest)
    local inherited=api.groups(autoQuest)
    local previousProgression=api.progression(autoQuest)
    if autoQuest.splitQuests then
        if profile=="custom" then api.problem="Use os controles separados de Progressão e Limit Breaker.";return false end
        autoQuest.limitBreakerEnabled=profile=="limitbreaker"
    end
    autoQuest.profile=profile
    if profile=="progression" then
        if detail and detail~="islands" and detail~="world" and detail~="both" then autoQuest.profile=previous.profile;return false end
        autoQuest.progression=detail or autoQuest.progression or (api.profile(previous)=="progression" and previousProgression or "both")
    elseif profile=="custom" then
        local groups=type(detail)=="table" and detail or autoQuest.questGroups or inherited
        autoQuest.questGroups={};local any=false
        for _,key in ipairs({"islands","world","daily","weekly","pass"}) do autoQuest.questGroups[key]=groups[key]==true;any=any or autoQuest.questGroups[key] end
        if not any then autoQuest.profile=previous.profile;autoQuest.questGroups=previous.questGroups;api.problem="Selecione pelo menos um grupo de missões.";return false end
    end
    api.syncScope(autoQuest)
    if not save() then
        for key in pairs(autoQuest) do autoQuest[key]=nil end
        for key,value in pairs(previous) do autoQuest[key]=value end
        api.problem="Falha ao salvar o objetivo do Auto Quest.";return false
    end
    api.problem=nil
    questRuntime.islandsDone=nil
    questRuntime.filter,questRuntime.destination,questRuntime.combat=nil,nil,false
    questRuntime.modeRequest=nil;state.target,state.searchPosition=nil,nil;generation+=1
    if state.recurringQuests then state.recurringQuests.demands={} end
    if api.refresh then api.refresh() end
    return true
end
function api.transition()
    local job=autoQuest.journey
    if not job or api.owns(autoQuest,job) then return false end
    questRuntime.modeRequest=nil;questRuntime.combat=false
    if insideDungeon() then
        state.autoLeaving=true
        if os.clock()>=(api.exitAt or 0) then api.exitAt=os.clock()+8;state.requestDungeonExit() end
        questStatus.Text="Auto Quest: saindo da tarefa anterior para aplicar o novo objetivo.";return true
    end
    local mode=dungeonMode({mode=job.mode})
    local room=partyClient.GetRoom(mode.event)
    if room and room.Leader==player.UserId and not room.Locked then general:Fire({Event=mode.event,Action="Leave"}) end
    if not job.bucket and api.resetWorldRun then api.resetWorldRun();return true end
    if job.bucket=="TicketFarm" and state.refillTeams and not state.refillTeams.finish(job) then questStatus.Text=state.refillTeams.status;return true end
    local previousResume=autoQuest.ticketResume
    autoQuest.journey=nil;autoQuest.ticketResume=nil;state.autoLeaving=nil;api.exitAt=nil
    if not save() then autoQuest.journey=job;autoQuest.ticketResume=previousResume;api.problem="Falha ao salvar a troca de tarefa." end
    return true
end
function api.splitInit()
    if autoQuest.splitQuests then return end
    local groups=api.groups(autoQuest)
    autoQuest.progressionEnabled=autoQuest.enabled and (groups.islands or groups.world)
    autoQuest.limitBreakerEnabled=autoQuest.enabled and (groups.daily or groups.weekly)
    autoQuest.progression=api.progression(autoQuest);autoQuest.splitQuests=true
    autoQuest.missionOrder=autoQuest.missionOrder or {}
    for _,bucket in ipairs({"Daily","Weekly"}) do
        if not autoQuest.missionOrder[bucket] then
            local order={};for _,row in ipairs(state.limitBreaker.catalog(bucket)) do order[#order+1]=row.id end
            autoQuest.missionOrder[bucket]=order
        end
    end
    api.syncScope(autoQuest);save()
end
function state.limitBreaker.change(mutator)
    local previous=Http:JSONEncode(autoQuest)
    mutator(autoQuest);api.syncScope(autoQuest)
    if not save() then
        local old=Http:JSONDecode(previous)
        for key in pairs(autoQuest) do autoQuest[key]=nil end
        for key,value in pairs(old) do autoQuest[key]=value end
        api.problem="Falha ao salvar as opções do Limit Breaker.";return false
    end
    api.problem=nil
    questRuntime.modeRequest=nil;questRuntime.combat=false;state.target=nil
    if state.recurringQuests then state.recurringQuests.demands={} end
    if api.refresh then api.refresh() end
    return true
end
function state.limitBreaker.catalog(bucket)
    local definitions=require(storage.Indexer.QuestsInfo)[bucket] or {}
    local rows={}
    for id,definition in pairs(definitions) do
        if type(definition)=="table" and not definition.DontShow then
            local stage=5
            for goal in pairs(definition.Goals or {}) do
                local action=state.recurringQuestPolicy.action(goal)
                if action then stage=math.min(stage,state.recurringQuestPolicy.stage(action)) end
            end
            rows[#rows+1]={id=id,name=definition.Name or id,stage=stage,image=state.limitBreaker.icon(definition)}
        end
    end
    table.sort(rows,function(a,b)
        local x,y=state.limitBreaker.rank(autoQuest,bucket,a.id),state.limitBreaker.rank(autoQuest,bucket,b.id)
        if x~=y then return x<y end
        if a.stage~=b.stage then return a.stage<b.stage end
        return a.name<b.name
    end)
    return rows
end
function state.limitBreaker.move(bucket,id,target)
    local rows=state.limitBreaker.catalog(bucket);local order={};local current
    for index,row in ipairs(rows) do order[index]=row.id;if row.id==id then current=index end end
    if not current then return false end
    table.remove(order,current);table.insert(order,math.clamp(target,1,#order+1),id)
    return state.limitBreaker.change(function(q) q.missionOrder=q.missionOrder or {};q.missionOrder[bucket]=order end)
end

end

    local lastKey, sent = nil, {}
    local function request(key, payload)
        -- These actions are native/idempotent; a lost acknowledgement must not
        -- permanently suppress accepting, claiming, spawning or world travel.
        local now=os.clock()
        local previous=sent[key]
        if type(previous)=="number" and now-previous<8 then return end
        sent[key] = now
        general:Fire(payload)
    end
    task.spawn(function()
