                if not kind then questStatus.Text = prefix .. "Objetivo exige ação manual: " .. (goalInfo.Desc or goal) return end
                local filter = {kind = kind, enemy = goal:match("^(.-)Defeated$"), map = entry.map, order = entry.order, info = enemies}
                questRuntime.filter = filter
