-- REBIRTH AND ATTRIBUTE RUNTIME
task.spawn(function()
    clientData.WaitForLoaded()
    local pendingRebirth, pendingStats
    while alive do
        task.wait(1)
        if not alive then break end
            if state.panic then continue end
        local success, problem = pcall(function()
            local count = tonumber(clientData.Get("Rebirths")) or 0
            local level = tonumber(clientData.Get("Level")) or 1
            local maximum = tonumber(balanceInfo.MaxRebirth)
            assert(maximum and maximum == maximum and maximum >= 0 and maximum < math.huge, "Limite nativo de rebirth indisponível")
            state.rebirthLimit = maximum
            local ready, required = canRebirth(level, count, balanceInfo)
            local prefix = "Rebirth " .. count .. "/" .. maximum .. " · Nível " .. level
                .. (required and ("/" .. required) or "") .. "\n"
            refreshRebirth()
            if pendingRebirth and count ~= pendingRebirth.before then
                pendingRebirth, pendingStats = nil, nil
                state.rebirthing, state.target, state.searchPosition = false, nil, nil
                generation += 1
            end
            if pendingRebirth and os.clock() - pendingRebirth.at < 10 then
                state.rebirthing = rebirth.enabled and os.clock() - pendingRebirth.at < 10
                rebirthStatus.Text = prefix .. "Rebirth solicitado. Aguardando confirmação, sem repetir o pedido."
                return
            end
            -- RebirthPlayer is validated by the server against the current level/count.
            -- An unconfirmed request must not permanently block all future eligible rebirths.
            if pendingRebirth then pendingRebirth = nil end
            state.rebirthing = false
            if not rebirth.enabled and not rebirth.distribute then rebirthStatus.Text = prefix .. "Automações desligadas." return end
            if player.GameplayPaused then rebirthStatus.Text = prefix .. "Aguardando personagem..." return end
            local nativeRebirth = clientData.Get("Settings", "AutoRebirth") == true
            -- The native setting and a guild encounter restrict rebirth only. Stat allocation
            -- uses replicated data and remains independent of combat and the character root.
            if rebirth.enabled and ready and not pendingRebirth and not nativeRebirth and events.active ~= "guild" and rootPart() then
                pendingRebirth, pendingStats = {before = count, at = os.clock()}, nil
                state.rebirthing, state.target, state.searchPosition = true, nil, nil
                rebirthStatus.Text = prefix .. "Solicitando rebirth..."
                general:Fire({Event = "RebirthPlayer"})
                return
            end
            local current = {}
            for _, id in ipairs(rebirth.order) do current[id] = tonumber(clientData.Get("PlayerStats", id)) or 0 end
            if not rebirth.distribute then
                rebirthStatus.Text = prefix .. (nativeRebirth and "Auto Rebirth nativo ativo; distribuição da hub desligada."
                    or pendingRebirth and "Rebirth sem confirmação; distribuição desligada."
                    or "Distribuição de pontos desligada.")
                return
            end
            if pendingStats then
                if count ~= pendingStats.rebirths or (tonumber(current[pendingStats.id]) or 0) > pendingStats.before then
                    pendingStats = nil
                else
                    rebirthStatus.Text = prefix .. "Aguardando confirmação dos pontos em " .. (statsInfo[pendingStats.id] and statsInfo[pendingStats.id].Name or pendingStats.id) .. "."
                    return
                end
            end
            local id, amount = nextStatAllocation(rebirth, current, tonumber(clientData.Get("SkillPoints")) or 0, balanceInfo.MaxStats + 75 * count)
            if id then
                pendingStats = {id = id, before = tonumber(current[id]) or 0, amount = amount, rebirths = count}
                rebirthStatus.Text = prefix .. "Distribuindo " .. amount .. " pontos em " .. (statsInfo[id] and statsInfo[id].Name or id) .. "."
                general:Fire({Event = "StatsUp", Stats = id, Points = amount})
            else
                rebirthStatus.Text = prefix .. "Aguardando pontos livres ou novas metas."
            end
        end)
        if not success then state.rebirthing = false rebirthStatus.Text = "Rebirth/atributos em espera: " .. tostring(problem) end
    end
end)
-- END REBIRTH AND ATTRIBUTE RUNTIME

local release = require(shared.Release)
-- Escopo próprio: as variáveis da coleta (ilhas visitadas, falhas, bloqueios...) só existem aqui e não ocupam vaga no escopo principal.
do
local visitedPumpkinIslands, failedPumpkins, blockedPumpkinIslands = {}, setmetatable({}, {__mode = "k"}), {}
local nextPumpkinSweep = 0
local function releasePumpkinMovement()
    if state.pumpkinBusy then state.target, state.map = nil, nil end
    state.pumpkinBusy, pumpkin.target, pumpkin.travel = false, nil, nil
end
connectUI(pumpkinToggle, function()
    pumpkin.enabled = not pumpkin.enabled
    releasePumpkinMovement()
    visitedPumpkinIslands, nextPumpkinSweep = {}, 0
    state.pumpkinNextScan = 0
    save() refresh()
    if not pumpkin.enabled then pumpkinStatus.Text = "Desligado." end
end)
local function observePumpkinFolder(folder)
    if state.pumpkinFolder == folder then return end
    if state.pumpkinWatcher then state.pumpkinWatcher:Disconnect() end
    state.pumpkinFolder, state.pumpkinWatcher = folder, nil
    if folder then
        state.pumpkinWatcher = connect(folder.ChildAdded, function()
            nextPumpkinSweep, visitedPumpkinIslands, state.pumpkinNextScan = 0, {}, 0
        end)
    end
end

task.spawn(function()
    local function nearestIsland(position, islands)
        local selected, distance
        for _, island in ipairs(islands) do
            local value = (island.spawn.Position - position).Magnitude
            if not distance or value < distance then selected, distance = island, value end
        end
        return selected
    end
    while alive do
        task.wait(0.5)
        if not alive then break end
            if state.panic then continue end
        if state.questPriorityActive and state.questPriorityActive() then releasePumpkinMovement();continue end
        if not pumpkin.enabled then releasePumpkinMovement() continue end
        local now = os.clock()
        local prefix = "Coletadas: " .. pumpkin.collected .. "\n"
        if not state.isHalloweenNight() then
            releasePumpkinMovement()
            visitedPumpkinIslands, nextPumpkinSweep, state.pumpkinNextScan = {}, 0, 0
            pumpkinToggle.Caption.Text = "Suspenso até a Halloween Night. Coleta só no mundo atual."
            pumpkinStatus.Text = prefix .. "Aguardando Halloween Night. Outras funções liberadas."
            continue
        end
        if state.houseCollectionDue() or state.kamishDue() or state.kingDue() or state.guild.journey or insideDungeon() or state.leaving or state.rebirthing or now < (state.entryUntil or 0) then
            releasePumpkinMovement()
            pumpkinStatus.Text = prefix .. "Pausado: missão ou dungeon tem prioridade."
            continue
        end
        pumpkinToggle.Caption.Text = "Halloween Night: coleta prioritária só no mundo atual."
        if events.active or state.eventDestination then releasePumpkinMovement() continue end
        local root = rootPart()
        if not root or player.GameplayPaused or player:GetAttribute("Mounted") or player:GetAttribute("Swimming") then
            releasePumpkinMovement()
            pumpkinStatus.Text = prefix .. "Aguardando personagem livre para coletar."
            continue
        end
        if type(state.firePrompt) ~= "function" then
            releasePumpkinMovement()
            pumpkinStatus.Text = "Executor sem suporte a interacao de proximidade."
            continue
        end
        local currentExtra = workspace:FindFirstChild("__Extra")
        local folder = currentExtra and currentExtra:FindFirstChild("__Pumps")
        observePumpkinFolder(folder)
        local spawns = currentExtra and currentExtra:FindFirstChild("__Spawns")
        if not folder or not spawns or #folder:GetChildren() == 0 then
            releasePumpkinMovement()
            pumpkinStatus.Text = prefix .. "Nenhuma abóbora disponível no mundo atual."
            continue
        end
        local success, problem = pcall(function()
            local islands = {}
            local world = tonumber(storage:GetAttribute("World"))
            if pumpkin.lastWorld ~= world then pumpkin.lastWorld = world visitedPumpkinIslands, nextPumpkinSweep = {}, 0 end
            for name, info in pairs(mapInfo) do
                local spawn = spawns:FindFirstChild(name)
                if type(info) == "table" and info.NoWorld ~= true and info.World == world and spawn and spawn:IsA("BasePart") and release.IsOpenFor(info) then
                    table.insert(islands, {id = name, name = info.Name or name, spawn = spawn})
                end
            end
            local here = nearestIsland(root.Position, islands)
            if not here then releasePumpkinMovement() pumpkinStatus.Text = prefix .. "Aguardando ilhas do mundo atual." return end
            local hasPass = clientData.Get("Passes", "ShadowExchange") == true
            local travel = pumpkin.travel
            if travel then
                state.pumpkinBusy = true
                if (root.Position - travel.island.spawn.Position).Magnitude <= 60 then
                    visitedPumpkinIslands[travel.island.id] = true
                    if now - travel.at >= 1.5 then pumpkin.travel = nil end
                elseif now - travel.at > 7 then
                    blockedPumpkinIslands[travel.island.id] = now + 60
                    releasePumpkinMovement()
                end
                pumpkinStatus.Text = prefix .. "Viajando para " .. travel.island.name .. "..."
                return
            end
            local target = pumpkin.target
            if target then
                if target.model:GetAttribute(tostring(player.UserId)) ~= nil then
                    pumpkin.collected += 1
                    pumpkin.target = nil
                    return
                end
                local part, prompt = availablePumpkin(target.model, folder, player.UserId)
                if not part or now - target.at > 12 then
                    failedPumpkins[target.model], state.pumpkinRejected[target.model] = now + 60, now + 60
                    pumpkin.target = nil
                    return
                end
                state.pumpkinBusy = true
                pumpkinStatus.Text = prefix .. "Coletando em " .. target.island.name .. "..."
                if (root.Position - part.Position).Magnitude <= math.min(prompt.MaxActivationDistance, 12) and now >= target.nextPrompt then
                    if target.attempts >= 3 then
                        failedPumpkins[target.model], state.pumpkinRejected[target.model] = now + 60, now + 60
                        pumpkin.target = nil
                    else
                        target.attempts, target.nextPrompt = target.attempts + 1, now + 2
                        state.firePrompt(prompt)
                    end
                end
                return
            end
            if now < nextPumpkinSweep then
                releasePumpkinMovement()
                pumpkinStatus.Text = prefix .. "Rodada concluida. Nova busca em " .. math.ceil(nextPumpkinSweep - now) .. " s."
                return
            end
            local selected, distance
            for _, model in ipairs(folder:GetChildren()) do
                local part = availablePumpkin(model, folder, player.UserId)
                local markerWorld = tonumber(tostring(model:GetAttribute("World") or ""):match("%d+"))
                if part and (not markerWorld or markerWorld == world) and now >= (failedPumpkins[model] or 0) then
                    local island = nearestIsland(part.Position, islands)
                    if island and now >= (blockedPumpkinIslands[island.id] or 0) and (hasPass or island.id == here.id) then
                        local value = (part.Position - root.Position).Magnitude
                        if not distance or value < distance then selected, distance = {model = model, island = island, at = now, attempts = 0, nextPrompt = 0}, value end
                    end
                end
            end
            local destination = selected and selected.island
            if not destination then
                table.sort(islands, function(a, b) return (a.spawn.Position - root.Position).Magnitude < (b.spawn.Position - root.Position).Magnitude end)
                visitedPumpkinIslands[here.id] = true
                if hasPass then
                    for _, island in ipairs(islands) do
                        if not visitedPumpkinIslands[island.id] and now >= (blockedPumpkinIslands[island.id] or 0) then destination = island break end
                    end
                end
            end
            if not destination then
                nextPumpkinSweep, state.pumpkinNextScan, visitedPumpkinIslands = now + 30, now + 30, {}
                releasePumpkinMovement()
                pumpkinStatus.Text = prefix .. (hasPass and "Nenhuma disponivel. Aguardando nova rodada." or "Outras ilhas exigem o passe Shadow Exchange.")
                return
            end
            state.pumpkinBusy, state.target = true, nil
            if destination.id ~= here.id then
                pumpkin.travel = {island = destination, at = now}
                general:Fire({Event = "IslandTeleport", Island = destination.id})
                pumpkinStatus.Text = prefix .. "Viajando para " .. destination.name .. "..."
            else
                visitedPumpkinIslands[destination.id] = true
            end
            if selected then
                selected.at = now + (pumpkin.travel and 8 or 0)
                pumpkin.target = selected
            end
        end)
        if not success then
            releasePumpkinMovement()
            nextPumpkinSweep, state.pumpkinNextScan = now + 10, now + 10
            pumpkinStatus.Text = "Coleta interrompida: " .. tostring(problem)
        end
    end
end)
end
do
    local houses = state.houses
    local loadedAt, worldRequestAt = nil, 0
    local automaticChoices = setmetatable({}, {__mode = "k"})
    houses.cooldownSources = houses.cooldownSources or {}
    -- HOUSE RETURN POLICY: persist the origin and hold other farms until returning.
    local houseReturn = {}
    function houseReturn.world(value)
        local n = tonumber(value)
        return n and n == n and n >= 1 and n <= 3 and n == math.floor(n) and n or nil
    end
    function houseReturn.capture(route, currentWorld)
        if not houseReturn.world(route.originWorld) then route.originWorld = houseReturn.world(currentWorld) end
    end
    function houseReturn.plan(route, currentWorld)
        local origin = houseReturn.world(route.originWorld)
        if not origin or origin == houseReturn.world(currentWorld) then return false end
        if not route.returnWorld then
            route.returnWorld, route.returnAttempts, route.returnNextAt = origin, 0, nil
            route.resumeWaitUntil, route.waitUntil = route.waitUntil, nil
            route.returnProblem = nil
        end
        -- Existing Auto Execute follows nextWorld even if the Misc option is off.
        route.nextWorld = origin
        return true
    end
    function houseReturn.action(route, currentWorld, date)
        local target = houseReturn.world(route.returnWorld)
        if not target then return "invalid" end
        if target == houseReturn.world(currentWorld) then return "arrived" end
        if tonumber(route.returnNextAt) and date < route.returnNextAt then return "wait" end
        if (tonumber(route.returnAttempts) or 0) >= 3 then return "failed" end
        return "travel"
    end
    function houseReturn.complete(route, date, problem)
        route.waitUntil = route.resumeWaitUntil or date + 60
        route.resumeWaitUntil, route.returnWorld, route.returnNextAt, route.returnAttempts = nil, nil, nil, nil
        route.nextWorld, route.worldAttempts, route.target = nil, nil, nil
        route.returnProblem = problem
    end
    -- END HOUSE RETURN POLICY

    -- HOUSE ROUTE POLICY: unknown houses still count as work; no streamed-model assumptions.
    local function houseWorldHasWork(world, route, visited, date)
        for id, info in pairs(mapInfo) do
            local order = tonumber(info.Order)
            if tonumber(info.World) == world and not info.NoWorld and order and order >= 1 and order <= 29 and release.IsOpenFor(info) then
                local key = world .. ":" .. id
                if not route.islands[key] and (tonumber(visited[key]) or 0) <= date then return true end
            end
        end
        return false
    end
    local function chooseHouseAction(mode, available, previous)
        if #available == 0 then return nil end
        if mode == "AutoTreat" then return table.find(available, "Treat") and "Treat" or available[1] end
        if table.find(available, previous) then return previous end
        return available[math.random(#available)]
    end
    -- END HOUSE ROUTE POLICY

    -- HOUSE COOLDOWN: parse only the server's already-collected response.
    local function houseAlreadyCollected(message)
        local normalized = tostring(message or ""):gsub("<[^>]+>", ""):gsub("%s+", " "):lower()
        -- Both current (without "today") and previous server messages identify the same cooldown.
        return normalized:find("this house already answered you", 1, true) ~= nil
    end
    local function houseCooldown(message)
        if not houseAlreadyCollected(message) then return nil end
        message = tostring(message):gsub("<[^>]+>", ""):lower()
        local hours = tonumber(message:match("(%d+)%s*h"))
        local minutes = tonumber(message:match("(%d+)%s*m"))
        local seconds = tonumber(message:match("(%d+)%s*s"))
        local total = (hours or 0) * 3600 + (minutes or 0) * 60 + (seconds or 0)
        if (hours or minutes or seconds) and total > 0 and total <= 172800 then return total end
    end
    local function updateHouseTimer()
        local date = tonumber(storage:GetAttribute("DateTime"))
        if not houses.timer then return end
        if not date then houses.timer.Text = "Aguardando relógio do servidor" return end
        local nextAt, available, confirmed = nil, 0, false
        for key, untilAt in pairs(houses.visited) do
            if type(untilAt) == "number" then
                if untilAt <= date then available += 1
                elseif not nextAt or untilAt < nextAt then
                    nextAt, confirmed = untilAt, houses.cooldownSources[key] == "server"
                elseif untilAt == nextAt then confirmed = confirmed and houses.cooldownSources[key] == "server" end
            end
        end
        local text = available > 0 and "Casas para verificar: " .. available or ""
        if nextAt then
            local left = math.max(0, math.ceil(nextAt - date))
            text ..= (text ~= "" and "\n" or "") .. (confirmed and "Próxima liberação (confirmada): " or "Próxima liberação (estimada): ") .. string.format("%02d:%02d:%02d", math.floor(left / 3600), math.floor(left / 60) % 60, left % 60)
        end
        houses.timer.Text = text ~= "" and text or "Disponibilidade ainda não verificada."
    end
    -- END HOUSE COOLDOWN
    local reply = require(storage.BridgeNet2).ReferenceBridge("WARN_EVENT"):Connect(function(packet)
        local pending = houses.confirmation
        if not pending or type(packet) ~= "table" or os.clock() > pending.expires then return end
        local message = tostring(packet.Message or ""):gsub("<[^>]+>", ""):lower()
        if houseAlreadyCollected(message) then
            pending.unavailable = true
            local remaining, date = houseCooldown(message), tonumber(storage:GetAttribute("DateTime"))
            if remaining and date then
                pending.resetAt = date + remaining
                houses.visited[pending.key] = pending.resetAt
                houses.cooldownSources[pending.key] = "server"
            elseif date then houses.route.retryAt = date + 60 end
            houses.route.islands[pending.key], houses.route.target = true, nil
            save()
            updateHouseTimer()
        elseif message:match("^%s*" .. pending.choice:lower() .. "!") then
            pending.accepted = true
            houses.visited[pending.key] = pending.resetAt
            houses.cooldownSources[pending.key] = "estimate"
            houses.route.islands[pending.key], houses.route.target = true, nil
            save()
        end
    end)
    table.insert(cleanupCallbacks, function() reply:Disconnect() end)
    local function releaseMovement()
        if houses.busy or houses.fighting then state.target, state.searchPosition, state.map = nil, nil, nil end
        houses.busy, houses.destination, houses.travel, houses.fighting = false, nil, nil, nil
        houses.confirmation = nil
        houses.approach, houses.targetKey = nil, nil
        houses.fightStartedAt, houses.fightEmptySince = nil, nil
    end
    local function finish(message, retrySoon)
        releaseMovement()
        houses.completed = message
        local date = tonumber(storage:GetAttribute("DateTime"))
        local nextVisit
        if date then
            for _, untilAt in pairs(houses.visited) do
                if type(untilAt) == "number" and untilAt > date then nextVisit = math.min(nextVisit or untilAt, untilAt) end
            end
        end
        if date and houses.route.retryAt then nextVisit = math.min(nextVisit or houses.route.retryAt, houses.route.retryAt) end
        if date and retrySoon then nextVisit = math.min(nextVisit or date + retrySoon, date + retrySoon) end
        houses.route.waitUntil = date and (nextVisit or date + 60) or 0
        houses.route.nextWorld, houses.route.target = nil, nil
        local returning = houseReturn.plan(houses.route, storage:GetAttribute("World"))
        save()
        houses.refresh()
        houses.label.Text = returning and ("Rodada concluída. Voltando ao mundo " .. houses.route.returnWorld .. "...") or message
    end
    task.spawn(function()
        while alive do
            task.wait(0.5)
            if not alive then break end
            if state.panic then continue end
            if state.questPriorityActive and state.questPriorityActive() then releaseMovement();houses.label.Text="Auto Quest: coleta pausada.";continue end
            updateHouseTimer()
            if state.kamishDue() then
                releaseMovement()
                houses.label.Text = "Kamish: collection paused for arena priority."
                continue
            end
            if not houses.enabled then
                if houses.busy or houses.fighting then releaseMovement() end
                houses.label.Text = "Desligado."
                continue
            end
            if houses.route.waitUntil then
                releaseMovement()
                local date = tonumber(storage:GetAttribute("DateTime"))
                if not date or date < houses.route.waitUntil then
                    local left = date and math.max(0, math.ceil(houses.route.waitUntil - date))
                    houses.label.Text = (houses.route.returnProblem and (houses.route.returnProblem .. "\n") or "") .. "Aguardando próxima coleta" .. (left and string.format(" · %02d:%02d:%02d", math.floor(left / 3600), math.floor(left / 60) % 60, left % 60) or " · sincronizando servidor")
                    continue
                end
                houses.route, houses.completed = {worlds = {}, islands = {}}, nil
                loadedAt, worldRequestAt = nil, 0
                save()
            end
            if state.guild.journey or insideDungeon() or state.leaving or state.rebirthing or os.clock() < (state.entryUntil or 0) then
                releaseMovement()
                loadedAt = nil
                houses.label.Text = "Pausado: evento, partida ou rebirth em andamento."
                continue
            end
            local ok, problem = pcall(function()
                local now, root = os.clock(), rootPart()
                local date = tonumber(storage:GetAttribute("DateTime"))
                local currentWorld = tonumber(storage:GetAttribute("World"))
                if not root or not date or not currentWorld or player.GameplayPaused then return end
                if player:GetAttribute("Mounted") or player:GetAttribute("Swimming") then releaseMovement() return end
                if type(state.firePrompt) ~= "function" then finish("Interação de proximidade indisponível.") return end
                for key, untilAt in pairs(houses.visited) do
                    if type(untilAt) ~= "number" or untilAt <= date then houses.visited[key], houses.cooldownSources[key] = nil, nil end
                end
                local route = houses.route
                if route.returnWorld then
                    local decision = houseReturn.action(route, currentWorld, date)
                    if decision == "arrived" then
                        local origin = route.returnWorld
                        houseReturn.complete(route, date)
                        releaseMovement()
                        save()
                        houses.label.Text = "De volta ao mundo " .. origin .. ". Outras funções liberadas."
                    elseif decision == "invalid" or decision == "failed" then
                        houseReturn.complete(route, date, "Não foi possível voltar ao mundo inicial após as tentativas.")
                        releaseMovement()
                        save()
                    elseif decision == "wait" then
                        houses.busy = true
                        houses.label.Text = "Aguardando retorno ao mundo " .. route.returnWorld .. "..."
                    else
                        houses.busy = true
                        houses.destination, houses.travel = nil, nil
                        state.target, state.searchPosition = nil, nil
                        local armed, session = pcall(function()
                            if not save() then return nil end
                            return assert(loadstring(readfile("VykronHub/AutoExecute.luau")))(player.UserId, false)
                        end)
                        if not armed or not session or not session.queued then
                            houseReturn.complete(route, date, "Retorno indisponível: verifique o Auto Execute do instalador.")
                            releaseMovement()
                            save()
                            return
                        end
                        route.returnAttempts = (tonumber(route.returnAttempts) or 0) + 1
                        route.returnNextAt = date + 20
                        if not save() then
                            houseReturn.complete(route, date, "Retorno cancelado: não foi possível salvar o percurso.")
                            releaseMovement()
                            return
                        end
                        houses.label.Text = "Voltando ao mundo " .. route.returnWorld .. " onde a rodada começou..."
                        general:Fire({Event = "WorldTeleport", World = "World" .. route.returnWorld})
                    end
                    return
                end
                if not houseReturn.world(route.originWorld) then
                    houseReturn.capture(route, currentWorld)
                    save()
                end
                local pending = houses.confirmation
                if pending then
                    if pending.accepted or pending.unavailable then
                        if pending.accepted then houses.visited[pending.key] = pending.resetAt end
                        route.islands[pending.key], route.target, loadedAt = true, nil, nil
                        houses.confirmation, houses.destination, houses.busy = nil, nil, false
                        save()
                        houses.label.Text = pending.unavailable and "Casa já coletada. Seguindo para a próxima ilha..." or "Coleta confirmada. Seguindo para a próxima ilha..."
                        if pending.accepted and pending.choice == "Trick" then
                            houses.fighting, houses.fightPosition = now + 15, root.Position
                            houses.fightStartedAt, houses.fightEmptySince = now, nil
                            state.map = tostring(mapInfo[pending.id].Order)
                        end
                    elseif now >= pending.expires then
                        houses.confirmation = nil
                        local target = route.target
                        if target then target.attempts = (target.attempts or 0) + 1 end
                        if not target or target.attempts >= 2 then
                            route.islands[pending.key], route.target, loadedAt = true, nil, nil
                            route.retryAt = date + 60
                        end
                        houses.destination, houses.busy = nil, false
                        houses.label.Text = "Casa sem confirmação. Nova tentativa agendada."
                        save()
                    else houses.label.Text = "Aguardando confirmação da casa..." end
                    return
                end
                if route.nextWorld then
                    if currentWorld == route.nextWorld then
                        route.nextWorld, route.worldAttempts, route.target = nil, nil, nil
                        loadedAt, worldRequestAt = nil, 0
                        save()
                    else
                        if not houseWorldHasWork(route.nextWorld, route, houses.visited, date) then
                            route.worlds[tostring(route.nextWorld)] = true
                            route.nextWorld, route.worldAttempts = nil, nil
                            releaseMovement()
                            save()
                            return
                        end
                        houses.busy = true
                        houses.label.Text = "Continuando a coleta no mundo " .. route.nextWorld .. "..."
                        if now < worldRequestAt then return end
                        if (route.worldAttempts or 0) >= 2 then
                            route.worlds[tostring(route.nextWorld)] = true
                            route.nextWorld, route.worldAttempts = nil, nil
                            releaseMovement()
                            save()
                            return
                        end
                        if not save() then finish("Falha ao salvar o percurso. Viagem cancelada.") return end
                        local armed, session = pcall(function()
                            return assert(loadstring(readfile("VykronHub/AutoExecute.luau")))(player.UserId, false)
                        end)
                        if not armed or not session or not session.queued then
                            finish("Use o instalador atualizado: continuidade entre mundos indisponível.")
                            return
                        end
                        route.worldAttempts = (route.worldAttempts or 0) + 1
                        if not save() then finish("Falha ao salvar a troca de mundo.") return end
                        worldRequestAt = now + 20
                        general:Fire({Event = "WorldTeleport", World = "World" .. route.nextWorld})
                        return
                    end
                end
                -- HOUSE FIGHT: preserve the spawn grace and old deadline, but leave an empty area early.
                if houses.fighting then
                    local target, distance = nearest(enemyFolder(), houses.fightPosition, state.map)
                    local nearby = target ~= nil and distance ~= nil and distance <= 80
                    if nearby then houses.fightEmptySince = nil
                    else houses.fightEmptySince = houses.fightEmptySince or now end
                    local startedAt = houses.fightStartedAt or houses.fighting - 15
                    local quiet = not nearby and now - startedAt >= 3 and now - houses.fightEmptySince >= 1
                    if now < houses.fighting and not quiet then houses.label.Text = "Trick: combatendo perto da casa..." return end
                    releaseMovement()
                end
                -- END HOUSE FIGHT
                local extra = workspace:FindFirstChild("__Extra")
                local spawns = extra and extra:FindFirstChild("__Spawns")
                if not spawns then return end
                local target = route.target
                if target and target.world ~= currentWorld then
                    route.target, target, loadedAt = nil, nil, nil
                    houses.travel, houses.destination, houses.approach, houses.targetKey = nil, nil, nil, nil
                end
                if not target then
                    local pass = clientData.Get("Passes", "ShadowExchange") == true
                    local nearestIsland, distance
                    local candidates = {}
                    for id, info in pairs(mapInfo) do
                        local spawn = spawns:FindFirstChild(id)
                        local order = tonumber(info.Order)
                        if tonumber(info.World) == currentWorld and not info.NoWorld and order and order >= 1 and order <= 29 and spawn and release.IsOpenFor(info) then
                            local d = (root.Position - spawn:GetPivot().Position).Magnitude
                            if not distance or d < distance then nearestIsland, distance = id, d end
                            table.insert(candidates, {id = id, order = order})
                        end
                    end
                    table.sort(candidates, function(a, b)
                        if (a.id == nearestIsland) ~= (b.id == nearestIsland) then return a.id == nearestIsland end
                        return a.order < b.order
                    end)
                    for _, island in ipairs(candidates) do
                        local key = currentWorld .. ":" .. island.id
                        if not route.islands[key] and (tonumber(houses.visited[key]) or 0) <= date and (pass or island.id == nearestIsland) then
                            target = {id = island.id, world = currentWorld}
                            route.target, loadedAt = target, nil
                            save()
                            break
                        end
                    end
                    if not target then
                        route.worlds[tostring(currentWorld)] = true
                        local rank = tonumber(clientData.Get("Rank")) or 0
                        for world = 1, 3 do
                            if not route.worlds[tostring(world)] and rank >= ({0, 7, 20})[world] then
                                if houseWorldHasWork(world, route, houses.visited, date) then
                                    route.nextWorld, route.worldAttempts = world, 0
                                    save()
                                    return
                                end
                                route.worlds[tostring(world)] = true
                            end
                        end
                        finish("Rodada concluída nos mundos acessíveis. Outras funções liberadas.")
                        return
                    end
                end
                local key = currentWorld .. ":" .. target.id
                if houses.targetKey ~= key then
                    houses.targetKey, loadedAt = key, nil
                    houses.travel, houses.destination, houses.approach = nil, nil, nil
                end
                local spawn = spawns:FindFirstChild(target.id)
                if not spawn then
                    route.islands[key], route.target, loadedAt = true, nil, nil
                    save()
                    return
                end
                houses.busy = true
                state.target, state.searchPosition = nil, nil
                if houses.travel then
                    if (root.Position - houses.travel.position).Magnitude <= 65 then
                        houses.travel, loadedAt = nil, now
                        houses.approach = nil
                        local destination = spawn:GetPivot().Position
                        task.spawn(function() pcall(function() player:RequestStreamAroundAsync(destination, 3) end) end)
                    elseif now - houses.travel.at > 8 then
                        houses.travel, houses.destination = nil, nil
                        target.attempts = (target.attempts or 0) + 1
                        if target.attempts >= 2 then route.islands[key], route.target, loadedAt = true, nil, nil save() end
                    end
                    return
                end
                if not loadedAt then
                    local position = spawn:GetPivot().Position
                    if (root.Position - position).Magnitude > 65 then
                        if clientData.Get("Passes", "ShadowExchange") ~= true then
                            houses.destination = position + Vector3.new(0, 3, 0)
                            houses.label.Text = "Indo à casa da ilha atual..."
                            return
                        end
                        houses.travel = {position = position, at = now}
                        houses.destination = nil
                        general:Fire({Event = "IslandTeleport", Island = target.id})
                        houses.label.Text = "Visitando " .. tostring(mapInfo[target.id].Name) .. " · mundo " .. currentWorld .. "..."
                        return
                    end
                    loadedAt, houses.destination = now, root.Position
                    task.spawn(function() pcall(function() player:RequestStreamAroundAsync(position, 3) end) end)
                end
                local main = workspace:FindFirstChild("__Main")
                local world = main and main:FindFirstChild("__World")
                local folder = world and world:FindFirstChild("HauntedHouses")
                local model = folder and folder:FindFirstChild(target.id)
                local choice = houses.choice
                if model and (choice == "Auto" or choice == "AutoTreat") then
                    local available = {}
                    for _, name in ipairs({"Treat", "Trick"}) do
                        local candidate = model:FindFirstChild(name, true)
                        if candidate and candidate:IsA("ProximityPrompt") and candidate.Enabled then table.insert(available, name) end
                    end
                    if #available > 0 then
                        automaticChoices[model] = chooseHouseAction(choice, available, automaticChoices[model])
                        choice = automaticChoices[model]
                    end
                end
                local prompt = model and model:FindFirstChild(choice, true)
                local origin = prompt and prompt.Parent
                local position = origin and (origin:IsA("Attachment") and origin.WorldPosition or origin:IsA("BasePart") and origin.Position)
                if not prompt or not prompt:IsA("ProximityPrompt") or not prompt.Enabled or not position then
                    houses.label.Text = "Procurando casa em " .. tostring(mapInfo[target.id].Name) .. "..."
                    if now - loadedAt >= 8 then
                        route.islands[key], route.target, loadedAt = true, nil, nil
                        houses.destination = nil
                        save()
                    end
                    return
                end
                local reach = math.max(0.5, tonumber(prompt.MaxActivationDistance) or 0)
                local offset = math.min(2, reach * 0.25)
                houses.destination = position + Vector3.new(0, offset, offset)
                houses.label.Text = choice .. " · " .. tostring(mapInfo[target.id].Name) .. " · mundo " .. currentWorld
                if now < (houses.interactionRetryAt or 0) then return end
                local approach = houses.approach
                if not approach or approach.prompt ~= prompt or approach.root ~= root then
                    houses.approach = {prompt = prompt, root = root, at = now}
                    return
                end
                if now - approach.at < 0.4 then return end
                if (root.Position - position).Magnitude > math.max(0.5, reach - 1) then
                    approach.at = now
                    return
                end
                if not prompt.Enabled or storage:GetAttribute("World") ~= currentWorld or rootPart() ~= root then
                    houses.approach = nil
                    return
                end
                local resetIn = tonumber(storage:GetAttribute("DailyTimer"))
                houses.confirmation = {key = key, id = target.id, choice = choice, expires = now + prompt.HoldDuration + 8,
                    resetAt = resetIn and date + math.max(1, resetIn) or (math.floor(date / 86400) + 1) * 86400}
                local invoked, result = pcall(state.firePrompt, prompt, prompt.HoldDuration)
                if not invoked or result == false then
                    houses.confirmation, houses.approach = nil, nil
                    houses.interactionRetryAt = now + 2
                    houses.label.Text = "Interação não confirmada. Nova tentativa em 2 s."
                    return
                end
                houses.label.Text = "Aguardando confirmação da casa..."
            end)
            if not ok then finish("Coleta interrompida: " .. tostring(problem), 60) end
        end
    end)
end

connectUI(toggle, function()
    state.enabled = not state.enabled
    state.target, state.map = nil, nil
    generation += 1
    save()
    refresh()
end)
local dragging, dragInput, start, original, dragTarget
local function beginDrag(input, target)
    if target.Visible == false or state.resizeActive then return end
    if target == window and state.onResizeBorder and state.onResizeBorder(input.Position) then return end
    if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
    if dragging then return end
    dragging, dragInput, start, original, dragTarget = true, input, input.Position, target.Position, target
    if target == miniLogo then miniDragged = false end
end
connect(Input.InputChanged, function(input)
    if dragging and dragTarget.Visible == false then dragging, dragInput, dragTarget = false, nil, nil return end
    if dragging and (input == dragInput or (dragInput.UserInputType == Enum.UserInputType.MouseButton1 and input.UserInputType == Enum.UserInputType.MouseMovement)) then
        local delta = input.Position - start
        local size = gui.AbsoluteSize
        if size.X <= 0 or size.Y <= 0 then return end
        if delta.Magnitude > 4 and dragTarget == miniLogo then miniDragged = true end
        local half = dragTarget.AbsoluteSize / 2
        local x = math.clamp(original.X.Scale * size.X + original.X.Offset + delta.X, half.X + 8, math.max(half.X + 8, size.X - half.X - 8))
        local y = math.clamp(original.Y.Scale * size.Y + original.Y.Offset + delta.Y, half.Y + 8, math.max(half.Y + 8, size.Y - half.Y - 8))
        dragTarget.Position = UDim2.new(x / size.X, 0, y / size.Y, 0)
    end
end)
connect(Input.InputEnded, function(input)
    if dragging and input == dragInput then
        savePositions()
        dragging, dragInput, dragTarget = false, nil, nil
    end
end)
-- Mobile Resize uses the same persisted dimensions and viewport scale as edge resizing.
function state.mobileResizeBounds(axis, viewportWidth, viewportHeight, unit)
    unit = math.max(0.001, tonumber(unit) or 1)
    local minimum, maximum = axis == "width" and 480 or 360, axis == "width" and 1280 or 1250
    local available = math.max(1, ((axis == "width" and viewportWidth or viewportHeight) - 16) / unit)
    maximum = math.max(1, math.min(maximum, available))
    return math.min(minimum, maximum), maximum
end
-- WINDOW RESIZE: coordinates are screen pixels; the opposite edge stays fixed.
function state.resizeRect(rect, dx, dy, edge, bounds, unit)
    local l, t, r, b = rect.x, rect.y, rect.x + rect.w, rect.y + rect.h
    local minW, minH = math.min(480 * unit, bounds.w - 16), math.min(360 * unit, bounds.h - 16)
    local maxW, maxH = math.min(1280 * unit, bounds.w - 16), math.min(1250 * unit, bounds.h - 16)
    if edge:find("Left", 1, true) then l = math.clamp(l + dx, math.max(8, r - maxW), r - minW) end
    if edge:find("Right", 1, true) then r = math.clamp(r + dx, l + minW, math.min(bounds.w - 8, l + maxW)) end
    if edge:find("Top", 1, true) then t = math.clamp(t + dy, math.max(8, b - maxH), b - minH) end
    if edge:find("Bottom", 1, true) then b = math.clamp(b + dy, t + minH, math.min(bounds.h - 8, t + maxH)) end
    return {x = l, y = t, w = r - l, h = b - t}
end
do
    local active
    function state.cancelResize()
        if not active then return end
        active, state.resizeActive = nil, nil
        savePositions()
    end
    function state.onResizeBorder(point)
        local p, size = window.AbsolutePosition, window.AbsoluteSize
        return point.X < p.X + 12 or point.X > p.X + size.X - 12
            or point.Y < p.Y + 12 or point.Y > p.Y + size.Y - 12
    end
    local function begin(input, edge)
        if not gui.Enabled or not window.Visible or window.Interactable == false or active or dragging then return end
        if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
        local p, size = window.AbsolutePosition, window.AbsoluteSize
        active = {input = input, point = input.Position, edge = edge, unit = scale.Scale,
            rect = {x = window.Position.X.Scale * gui.AbsoluteSize.X + window.Position.X.Offset - size.X / 2,
                y = window.Position.Y.Scale * gui.AbsoluteSize.Y + window.Position.Y.Offset - size.Y / 2,
                w = size.X, h = size.Y}, viewport = gui.AbsoluteSize}
        state.resizeActive = true
    end
    state.beginResize = begin
    connect(Input.InputChanged, function(input)
        if not active then return end
        if not gui.Enabled or not window.Visible or window.Interactable == false then state.cancelResize() return end
        local size = gui.AbsoluteSize
        if size.X ~= active.viewport.X or size.Y ~= active.viewport.Y then state.cancelResize() return end
        if input ~= active.input and not (active.input.UserInputType == Enum.UserInputType.MouseButton1
            and input.UserInputType == Enum.UserInputType.MouseMovement) then return end
        local dx, dy = input.Position.X - active.point.X, input.Position.Y - active.point.Y
        local rect = state.resizeRect(active.rect, dx, dy, active.edge, {w = size.X, h = size.Y}, active.unit)
        uiState.width, uiState.height = rect.w / active.unit, rect.h / active.unit
        window.Size = UDim2.fromOffset(uiState.width, uiState.height)
        window.Position = UDim2.fromOffset(rect.x + rect.w / 2, rect.y + rect.h / 2)
    end)
    connect(Input.InputEnded, function(input) if active and input == active.input then state.cancelResize() end end)
end
-- END WINDOW RESIZE
-- Partes da interface nova, uma por bloco de cada aba (src/ui/abas/<aba>/...). Cada arquivo registra uma funcao aqui;
-- state.installNewHub (new-hub-view.lua) chama cada uma, na mesma ordem em que o codigo rodava antes, passando as variaveis que ela usa.
state.hubParts = {}
-- Shared Craft ownership, reservations and bounded automatic recovery.
do
local control={requested=nil,samples={},retries={},missing={}}
state.craftControl=control
function state.craftTouches(a,b)
    if type(a)~="table" or type(b)~="table" then return false end
    for id in pairs(a) do if b[id]~=nil then return true end end
    return false
end
function state.craftReceiptResources(receipt)
    local resources=table.clone(receipt.costs or {})
    if receipt.source then resources[receipt.source]=true end
    if receipt.output or receipt.id then resources[receipt.output or receipt.id]=true end
    return resources
end
function state.craftReserved(uid)
    local shadows=state.craft.shadows or {};local infusion=state.craft.infusion or {}
    if shadows.rankScope=="all" and state.shadowRuntime and state.shadowRuntime.running and state.shadowRuntime.kind=="rank" then return true end
    if (shadows.selected or {})[uid] or (shadows.rankSelected or {})[uid] or (infusion.selected or {})[uid] then return true end
    for _,receipt in ipairs({shadows.pending or {},infusion.pending or {}}) do
        if receipt.uid==uid then return true end
        for _,id in ipairs(receipt.ids or {}) do if id==uid then return true end end
    end
    return false
end
function state.craftSalePending(uid)
    local run=state.autoSellRuntime
    return run and run.pending and run.pending[uid]~=nil
end
function state.craftBuyBusy(resources)
    -- Sell/Buy owns its receipts internally. They must not reserve currencies
    -- against Craft or quest resets, even if an old purchase is unconfirmed.
    -- Keep the actual quest-reset transaction separate from those reservations.
    return state.questReset~=nil and state.questReset.pending~=nil and resources.Ticket~=nil
end
function state.craftItemBusy(item)
    local resources={[item.PriceType]=true}
    if item.Kind=="Item" then resources[item.Real]=true end
    local craft=state.craft
    if state.questReset and state.questReset.pending and resources.Ticket then return true end
    for _,receipt in ipairs({craft.pending or {},craft.shadows and craft.shadows.pending or {},craft.infusion and craft.infusion.pending or {}}) do
        if state.craftTouches(resources,state.craftReceiptResources(receipt)) then return true end
    end
    for _,receipt in pairs(craft.unconfirmed or {}) do
        if state.craftTouches(resources,state.craftReceiptResources(receipt)) then return true end
    end
    return false
end
function state.craftArchive(container,key,receipt,reason)
    local oldHistory=state.craft.history
    local history={{receipt=receipt,reason=reason}}
    for i,old in ipairs(oldHistory or {}) do if i>=20 then break end;history[#history+1]=old end
    state.craft.history=history;container[key]=nil
    if not save() then state.craft.history=oldHistory;container[key]=receipt;return false end
    return true
end
function state.craftRecoveryReady(key,receipt,signature,now)
    if now-(receipt.lastAttempt or receipt.at or now)<30 then return false end
    local sample=control.samples[key]
    if not sample or sample.receipt~=receipt or sample.signature~=signature then
        control.samples[key]={receipt=receipt,signature=signature,at=now,count=1};return false
    end
    sample.count+=1
    return sample.count>=3 and now-sample.at>=2
end
function state.craftAllowRetry(key)
    control.retries[key]=(control.retries[key] or 0)+1
    return control.retries[key]<=3
end
function state.craftSwitch(kind)
    if kind=="infusion" then
        if state.shadowRuntime and state.shadowRuntime.running or state.craft.shadows and state.craft.shadows.pending and state.craft.shadows.pending.mode=="native" then
            state.shadowCraftStop();control.readyAt=os.clock()+2
        end
    else
        if state.infusionRun and state.infusionRun.running then state.infusionStop() end
        if state.shadowRuntime and state.shadowRuntime.running and state.shadowRuntime.kind~=kind then
            state.shadowCraftStop();control.readyAt=os.clock()+2
        end
    end
    local shadows=state.craft.shadows and state.craft.shadows.pending
    local infusion=state.craft.infusion and state.craft.infusion.pending
    local waiting=kind=="infusion" and shadows or kind~="infusion" and (infusion or shadows and shadows.kind~=kind)
    if waiting or os.clock()<(control.readyAt or 0) then
        control.requested=kind;control.status="Finalizando operação anterior antes de trocar o modo."
        return false
    end
    control.requested=nil;control.status=nil
    return true
end
function state.craftStopRequested(kind)
    if control.requested==kind then control.requested=nil;control.status=nil end
end
function state.craftControllerStep(now)
    if state.panic or state.stopped or not alive or player.GameplayPaused then control.requested=nil;return end
    local pending=state.craft.shadows and state.craft.shadows.pending
    local infusion=state.craft.infusion and state.craft.infusion.pending
    -- A cancelled native session gets a settling window before the next owner.
    if control.requested and not pending and not infusion and os.clock()>=(control.readyAt or 0) then
        local requested=control.requested;control.requested=nil
        if requested=="infusion" then state.infusionStart() else state.shadowCraftStart(requested) end
    end
end
function state.craftPrune(entries,prefs,completed,run,now)
    local map={};for _,entry in ipairs(entries) do map[entry.uid]=entry end
    local previous,previousDone=table.clone(prefs.selected or {}),prefs.finished
    local finished=table.clone(prefs.finished or {});local changed=false
    for uid in pairs(finished) do if map[uid] and not completed(map[uid]) then finished[uid]=nil;changed=true end end
    for uid in pairs(previous) do
        local entry=map[uid]
        local key=tostring(prefs)..":"..uid
        if entry then
            control.missing[key]=nil
            if completed(entry) then
                prefs.selected[uid]=nil;finished[uid]=true;changed=true
            end
        else
            local since=control.missing[key] or now;control.missing[key]=since
            if now-since>=30 then
                prefs.selected[uid]=nil;changed=true
                run.status="Sombra removida da fila: não existe mais no inventário ("..uid..")."
            end
        end
    end
    if changed then
        prefs.finished=finished
        if not save() then prefs.selected=previous;prefs.finished=previousDone;run.running=false;run.status="Falha ao salvar a fila; operação pausada.";return false end
    end
    local n=0;for _ in pairs(finished) do n+=1 end;run.finished=n
    return true
end
function state.craftFocusWaiting(entries,prefs,uid)
    if not uid or not (prefs.selected or {})[uid] then return nil end
    for _,entry in ipairs(entries) do if entry.uid==uid then
        if entry.pet.InExp then return "Aguardando a sombra atual voltar da expedição: "..uid end
        if state.craftSalePending(uid) then return "Aguardando venda anterior da sombra: "..uid end
        return nil
    end end
    return "Conferindo sombra ausente antes de remover da fila: "..uid
end
end
-- SHADOW CRAFT RUNTIME: one native request, persisted receipt, then reconciliation.
do
local function infusionConflict(plan)
    if state.infusionRun and state.infusionRun.running then
        return state.infusionText("Pare a Infusão antes de iniciar Rank Up/Reroll.")
    end
    local receipt=state.craft.infusion and state.craft.infusion.pending
    if not receipt then return nil end
    if type(receipt.costs)~="table" or not plan or type(plan.costs)~="table" then
        return state.infusionText("Infusão pendente: aguardando confirmação dos recursos.")
    end
    for id in pairs(plan.costs) do
        if receipt.costs[id]~=nil then return state.infusionText("Infusão pendente usa os mesmos materiais; aguardando confirmação.") end
    end
    if plan.kind=="rank" then
        for _,uid in ipairs(plan.ids or {}) do
            if uid==receipt.uid then return state.infusionText("Esta fusão usa a sombra da Infusão pendente; aguardando confirmação.") end
        end
    end
    -- Stat rerolls change Stats; infusion receipts observe Enchants, not Stats.
    return nil
end
function state.shadowCraftData(fresh)
    if not state.shadowDependencies then
        state.shadowDependencies={pets=require(storage.Indexer.PetsInfo),balance=require(storage.Indexer.BalanceInfo),
            stats=require(storage.Indexer.ShadowStats),tiers=require(storage.Indexer.ShadowTier),extra=require(shared.ExtraFunctions),items=require(storage.Indexer.ItemsInfo)}
    end
    local deps=state.shadowDependencies
    deps.playerRank=tonumber((clientData.Get("Rank")))
    local inventory=clientData.Get("Inventory","Pets")
    local equips=clientData.Get("Equips","Pets")
    if type(inventory)~="table" or type(equips)~="table" then return deps,nil,"Aguardando inventário e equipadas sincronizarem." end
    local cache=state.shadowInventoryCache
    local now=os.clock()
    if not fresh and cache and cache.inventory==inventory and cache.equips==equips and now-cache.at<0.5 then return deps,cache.entries end
    local equipped={};for _,uid in pairs(equips) do if uid then equipped[tostring(uid)]=true end end
    local entries=state.shadowCraftEntries(inventory,equipped,deps.pets)
    state.shadowInventoryCache={inventory=inventory,equips=equips,at=now,entries=entries}
    return deps,entries
end
function state.shadowCraftCount(id)
    local item=clientData.Get("Inventory","Items",id)
    local n=type(item)=="table" and tonumber(item.Amount) or tonumber(item)
    return n and n==n and n>=0 and n<math.huge and n or 0
end
function state.shadowCraftCosts(plan,deps)
    local rows,missing={},{}
    for id,need in pairs(plan.costs) do
        local owned=state.shadowCraftCount(id)
        local info=deps.items and deps.items[id]
        local name=info and type(info.Name)=="string" and info.Name or id=="Ticket" and "Tickets" or id
        name=state.shadowCraftText(name)
        local deficit=math.max(0,need-owned)
        table.insert(rows,{id=id,name=name,need=need,owned=owned,missing=deficit})
    end
    table.sort(rows,function(a,b) return a.id<b.id end)
    for _,row in ipairs(rows) do if row.missing>0 then table.insert(missing,tostring(row.missing).." "..row.name) end end
    return rows,#missing>0 and state.shadowCraftText("Faltam %s.",table.concat(missing,", ")) or nil
end
function state.shadowCraftStop()
    if state.craftStopRequested then state.craftStopRequested("rank");state.craftStopRequested("reroll") end
    if state.shadowRuntime then state.shadowRuntime.running=false;state.shadowRuntime.status="Operação interrompida." end
    local prefs=state.craft.shadows
    if prefs and prefs.pending and prefs.pending.mode=="native" then
        general:Fire({Event="StatsShadow",Action="CancelAutoReroll"})
        prefs.pending=nil;save()
    end
end
-- Clearing a UI selection must not discard an already-sent fusion receipt.
function state.shadowCraftClear(kind)
    local prefs=state.shadowCraftPrefs()
    state.shadowCraftStop()
    local previous={selected=prefs.selected,rankSelected=prefs.rankSelected,rankScope=prefs.rankScope,rankName=prefs.rankName,rankFrom=prefs.rankFrom,detail=prefs.detail}
    previous.finished=prefs.finished
    if kind=="rank" then
        prefs.rankSelected={};prefs.rankScope="one";prefs.rankName=nil;prefs.rankFrom=0
    else prefs.selected={};prefs.finished={} end
    prefs.detail=nil
    if not save() then
        for key,value in pairs(previous) do prefs[key]=value end
        prefs.rankName=previous.rankName;prefs.detail=previous.detail
        state.shadowRuntime=state.shadowRuntime or {};state.shadowRuntime.status="Não foi possível salvar a seleção."
        return false
    end
    if state.shadowRuntime then state.shadowRuntime.finished=0 end
    return true
end
function state.shadowCraftStart(kind)
    if kind~="rank" and kind~="reroll" then return false end
    if state.stopped or not alive then return false end
    local prefs=state.shadowCraftPrefs()
    state.shadowRuntime=state.shadowRuntime or {}
    local run=state.shadowRuntime
    if state.craftSwitch and not state.craftSwitch(kind) then run.status=state.craftControl.status;return true end
    if run.running then return false end
    if state.infusionRun and state.infusionRun.running then
        run.status=state.infusionText("Pare a Infusão antes de iniciar Rank Up/Reroll.");return false
    end
    -- Explicitly starting the native target session supersedes the old single-roll
    -- tracker. Do not resend that request or credit it as a completed operation.
    if kind=="reroll" and prefs.stopMode~="limit" and prefs.pending and prefs.pending.kind=="reroll" and prefs.pending.mode~="native" then
        local old=prefs.pending
        general:Fire({Event="StatsShadow",Action="CancelAutoReroll"})
        prefs.lastReceipt={at=old.at,kind=old.kind,uid=old.uid,outcome="superseded-by-native-session"}
        prefs.pending=nil
        if not save() then prefs.pending=old;run.status="Não foi possível salvar a troca de sessão." return false end
    end
    if prefs.pending then
        local conflict=infusionConflict(prefs.pending)
        if conflict then run.status=conflict;return false end
        if kind=="rank" and prefs.pending.kind=="rank" then
            local deps=state.shadowCraftData(true)
            local allowed,msr,msrPlus=state.shadowCraftRankLimit(deps.balance,deps.playerRank)
            if prefs.pending.rank>allowed then
                if not deps.playerRank then run.status="Aguardando o rank do jogador sincronizar.";return false end
                run.status=state.shadowCraftText("Para evoluir para %s, seu jogador precisa de rank %s.",prefs.pending.rank>=msrPlus and "MSR+" or "MSR",prefs.pending.rank>=msrPlus and "HL+" or "HL")
                return false
            end
            run.kind,run.native,run.running,run.completed="rank",false,true,run.completed or 0
            run.status="Conferindo automaticamente a fusão pendente."
            return true
        end
        run.status="Operação anterior sem confirmação; aguardando inventário." return false
    end
    local ok,deps,entries,problem=pcall(state.shadowCraftData,true)
    if not ok then run.status="Dados nativos indisponíveis." return false end
    if not entries then run.status=problem return false end
    if kind=="reroll" and state.craftPrune and not state.craftPrune(entries,prefs,function(e) return state.shadowTargetsMet(e,prefs) end,run,workspace:GetServerTimeNow()) then return false end
    local plan,message
    if kind=="rank" then plan,message=state.shadowCraftPlan(entries,prefs,deps.balance,state.shadowCraftCount,deps.playerRank)
    else plan,message=state.shadowRerollPlan(entries,prefs) end
    if not plan then run.status=message return false end
    local conflict=infusionConflict(plan)
    if conflict then run.status=conflict;return false end
    if kind=="rank" then
        local _,missing=state.shadowCraftCosts(plan,deps)
        if missing then run.status=missing return false end
    end
    if not save() then run.status="Não foi possível salvar as preferências." return false end
    run.kind,run.completed,run.running,run.status=kind,0,true,"Preparando operação."
    run.lastResult=nil
    run.native=kind=="reroll" and prefs.stopMode~="limit"
    run.target=kind=="reroll" and {uid=plan.uid,name=plan.label or plan.name,stat=plan.stat} or nil
    return true
end
function state.shadowCraftReconcile(receipt,entries,count,now)
    if type(receipt.costs)~="table" or type(receipt.before)~="table" then return false end
    -- Incoming cores may hide the net debit. The requested stat changing on the
    -- exact surviving UID is independent result evidence; do not require both.
    if receipt.kind=="reroll" and type(receipt.old)=="number" and now-receipt.at>=1 then
        for _,entry in ipairs(entries) do
            local grade=tonumber((entry.pet.Stats or {})[receipt.stat])
            if entry.uid==receipt.uid and entry.pet.Name==receipt.name and grade and grade~=receipt.old then
                return true,entry.uid,"stat-change"
            end
        end
    end
    local debited,allDebited=false,true
    for key,price in pairs(receipt.costs) do
        if type(price)~="number" or type(receipt.before[key])~="number" then return false end
        if count(key)>receipt.before[key]-price then allDebited=false end
        debited=true
    end
    if not debited then return false end
    if receipt.kind=="reroll" then
        if not allDebited then return false end
        -- A reroll may legitimately produce the same grade. Debit plus a surviving UID
        -- is recorded as consumption, not a promise that the grade improved.
        for _,entry in ipairs(entries) do
            if entry.uid==receipt.uid and entry.pet.Name==receipt.name and now-receipt.at>=1 then return true,entry.uid end
        end
        return false
    end
    if type(receipt.ids)~="table" or #receipt.ids~=6 or type(receipt.beforeIds)~="table" then return false end
    local aliveInputs,output,remaining=0,nil,nil
    local inputs={};for _,uid in ipairs(receipt.ids) do inputs[uid]=true end
    for _,entry in ipairs(entries) do
        if inputs[entry.uid] then aliveInputs+=1;remaining=entry.uid end
        if entry.pet.Name==receipt.name and tonumber(entry.pet.Rank)==receipt.rank
            and (not receipt.beforeIds[entry.uid] or inputs[entry.uid]) then output=entry.uid end
    end
    return output~=nil and (aliveInputs==0 or aliveInputs==1 and remaining==output),output
end
function state.shadowCraftReview()
    local prefs=state.shadowCraftPrefs()
    if state.shadowRuntime and state.shadowRuntime.running then return false end
    local old=prefs.pending
    if not old then return false end
    prefs.lastReceipt={at=old.at,kind=old.kind,name=old.name,outcome="user-reviewed"}
    prefs.pending=nil
    if not save() then prefs.pending=old;return false end
    return true
end
local function nativeTargetsMet(pet,targets)
    local any=false
    for key,goal in pairs(targets) do
        if goal>0 then
            any=true
            if ((pet.Stats or {})[key] or 0)<goal then return false end
        end
    end
    return any
end
local function materialBusy(costs,plan)
    local conflict=infusionConflict(plan or {kind="reroll",costs=costs})
    if conflict then return true,conflict end
    if state.craft.pending and (not state.craftTouches or state.craftTouches(costs,state.craftReceiptResources(state.craft.pending))) then return true,"Aguardando confirmação de materiais do Craft." end
    for _,receipt in pairs(state.craft.unconfirmed) do
        if not receipt.source or costs[receipt.source] or state.craftTouches and state.craftTouches(costs,state.craftReceiptResources(receipt)) then return true,"Pendência de Craft usa os mesmos materiais; confira a troca antes de continuar." end
    end
    if state.craftBuyBusy and state.craftBuyBusy(costs) then return true,"Aguardando Auto Buy: recursos compartilhados." end
    return false
end
local function retryRank(receipt,entries,run,now)
    if state.panic or state.stopped or not alive or player.GameplayPaused then return end
    if type(receipt.ids)~="table" or #receipt.ids~=6 then return end
    local deps=state.shadowDependencies
    local allowed,msr,msrPlus=state.shadowCraftRankLimit(deps.balance,deps.playerRank)
    local seen,inputs={},{}
    for _,uid in ipairs(receipt.ids) do
        if seen[uid] then return end
        seen[uid]=true
        for _,entry in ipairs(entries) do
            if entry.uid==uid and entry.pet.Name==receipt.name and entry.eligible then
                local rank=tonumber(entry.pet.Rank)
                local expected=receipt.first and receipt.byRank and receipt.byRank[tostring(rank)]==uid or not receipt.first and rank==receipt.rank-1
                if expected then inputs[uid]=true end
                break
            end
        end
        if not inputs[uid] then run.status="Conferindo automaticamente a fusão pendente.";return end
    end
    -- Same six UIDs only: never substitute another group while a request is unresolved.
    -- A debit or partially transformed inventory must settle before another dispatch.
    if receipt.rank>allowed then
        if not deps.playerRank then run.status="Aguardando o rank do jogador sincronizar.";return end
        local prefs=state.craft.shadows
        local old=prefs.lastReceipt
        prefs.lastReceipt=table.clone(receipt);prefs.lastReceipt.outcome="blocked-player-rank";prefs.pending=nil
        if not save() then prefs.pending=receipt;prefs.lastReceipt=old;return end
        run.running=false;run.status=state.shadowCraftText("Para evoluir para %s, seu jogador precisa de rank %s.",receipt.rank>=msrPlus and "MSR+" or "MSR",receipt.rank>=msrPlus and "HL+" or "HL")
        return
    end
    for id,before in pairs(receipt.before) do
        if state.shadowCraftCount(id)<before then run.status="Aguardando resultado após consumo de materiais.";return end
    end
    if not run.running then return end
    if not state.shadowCraftAffordable(receipt,state.craft.shadows,state.shadowCraftCount) then
        run.running=false;run.status="Materiais insuficientes para esta operação.";return
    end
    local busy,why=materialBusy(receipt.costs,receipt);if busy then run.status=why;return end
    local delay=math.min(30,15+5*(receipt.retries or 0))
    if now-(receipt.lastAttempt or receipt.at)<delay then run.status="Conferindo automaticamente a fusão pendente.";return end
    local oldAttempt,oldRetries=receipt.lastAttempt,receipt.retries
    receipt.lastAttempt=now;receipt.retries=(receipt.retries or 0)+1
    if not save() then receipt.lastAttempt=oldAttempt;receipt.retries=oldRetries;run.running=false;run.status="Falha ao salvar o pedido; nada foi enviado.";return end
    if receipt.first then general:Fire({Event="UpgradePet",Pets=receipt.byRank,PetType=receipt.name,BuyType="Ticket"})
    else general:Fire({Event="UpgradePetV2",Pets=receipt.ids,PetType=receipt.name,RankUp=receipt.rank,Auto=false}) end
    run.status="Fusão reenviada com as mesmas seis cópias."
end
local function nativeRerollStep(now,prefs,run,entries)
    local receipt=prefs.pending
    if not run.running or state.panic or state.stopped or not alive or player.GameplayPaused then
        if receipt then general:Fire({Event="StatsShadow",Action="CancelAutoReroll"});prefs.pending=nil;save() end
        if state.panic or state.stopped or not alive or player.GameplayPaused then run.status="Operação pausada."
        else run.status=run.status or "Auto Reroll pausado." end
        return
    end
    if receipt then
        local current
        for _,entry in ipairs(entries) do if entry.uid==receipt.uid and entry.pet.Name==receipt.name then current=entry;break end end
        local changed=false
        if current then
            for key,grade in pairs(current.pet.Stats or {}) do
                local old=(receipt.lastStats or {})[key]
                if old~=grade then changed=true;run.lastResult={name=receipt.label or receipt.name,stat=key,before=old,after=grade} end
            end
            receipt.lastStats=table.clone(current.pet.Stats or {})
        end
        local cores=state.shadowCraftCount("ShadowUpgrader")
        if changed or receipt.lastCores and cores<receipt.lastCores then receipt.progressAt=now end
        receipt.lastCores=cores;receipt.progressAt=receipt.progressAt or receipt.at
        if current and nativeTargetsMet(current.pet,receipt.targets) then
            general:Fire({Event="StatsShadow",Action="CancelAutoReroll"})
            prefs.pending=nil;run.completed=(run.completed or 0)+1
            run.status="Metas atingidas; seguindo para a próxima shadow."
            if not save() then prefs.pending=receipt;run.completed-=1;run.running=false;run.status="Falha ao salvar o progresso." end
        elseif cores<4 then
            general:Fire({Event="StatsShadow",Action="CancelAutoReroll"})
            prefs.pending=nil;run.running=false;run.status="Shadow Cores insuficientes para continuar.";save()
        elseif not current or current.pet.InExp or state.craftSalePending and state.craftSalePending(receipt.uid) then
            general:Fire({Event="StatsShadow",Action="CancelAutoReroll"})
            prefs.pending=nil;save();run.status="Aguardando as shadows selecionadas ficarem disponíveis."
        elseif receipt.restartAt then
            if now>=receipt.restartAt then
                general:Fire({Event="StatsShadow",Action="AutoReroll",RequiredStats=table.clone(receipt.targets),Pet=receipt.uid})
                receipt.restartAt=nil;receipt.progressAt=now;run.restarts=(run.restarts or 0)+1
            end
            run.status="Retomando Reroll após interrupção nativa."
        elseif not current or current.pet.InExp then
            general:Fire({Event="StatsShadow",Action="CancelAutoReroll"})
            prefs.pending=nil;save();run.status="Aguardando as shadows selecionadas ficarem disponíveis."
        elseif now-receipt.progressAt>=12 then
            receipt.restarts=(receipt.restarts or 0)+1
            if receipt.restarts>3 then
                general:Fire({Event="StatsShadow",Action="CancelAutoReroll"})
                run.running=false;run.status="Reroll pausado: sem progresso após três reinícios. Confira o menu e os requisitos no jogo.";return
            end
            -- The game's own Stats menu cancels AutoReroll on Open/Order/Close.
            -- Cancel before restarting; never stack two native sessions.
            general:Fire({Event="StatsShadow",Action="CancelAutoReroll"})
            receipt.restartAt=now+2;run.status="Retomando Reroll após interrupção nativa."
        else run.status=state.shadowCraftText("Auto Reroll: %s; aguardando as metas.",receipt.label or receipt.name) end
        return
    end
    local busy,why=materialBusy({ShadowUpgrader=4})
    if busy then run.status=why return end
    if state.craftPrune and not state.craftPrune(entries,prefs,function(e) return nativeTargetsMet(e.pet,prefs.targets) end,run,now) then return end
    local waiting=state.craftFocusWaiting and state.craftFocusWaiting(entries,prefs,run.target and run.target.uid)
    if waiting then run.status=waiting;return end
    local candidate,total,met= nil,0,0
    for _,entry in ipairs(entries) do
        if prefs.selected[entry.uid] then
            total+=1
            if nativeTargetsMet(entry.pet,prefs.targets) then met+=1
            elseif not entry.pet.InExp and not (state.craftSalePending and state.craftSalePending(entry.uid)) and (not candidate or run.target and run.target.uid==entry.uid) then candidate=entry end
        end
    end
    local expected=0;for _,on in pairs(prefs.selected) do if on then expected+=1 end end
    if not candidate then
        if expected>0 and total==expected and met==expected or expected==0 and (run.finished or 0)>0 then run.running=false;run.status="Metas atingidas para todas as shadows selecionadas."
        else run.status="Aguardando as shadows selecionadas ficarem disponíveis." end
        return
    end
    if state.shadowCraftCount("ShadowUpgrader")<4 then run.running=false;run.status="Shadow Cores insuficientes para continuar." return end
    receipt={kind="reroll",mode="native",uid=candidate.uid,name=candidate.pet.Name,label=candidate.info.Name or candidate.pet.Name,
        targets=table.clone(prefs.targets),lastStats=table.clone(candidate.pet.Stats or {}),at=now,
        progressAt=now,lastCores=state.shadowCraftCount("ShadowUpgrader"),
        costs={ShadowUpgrader=4},before={ShadowUpgrader=state.shadowCraftCount("ShadowUpgrader")}}
    prefs.pending=receipt
    if not save() then prefs.pending=nil;run.running=false;run.status="Falha ao salvar o pedido; nada foi enviado." return end
    run.target={uid=receipt.uid,name=receipt.label,stat="AUTO"}
    general:Fire({Event="StatsShadow",Action="AutoReroll",RequiredStats=table.clone(receipt.targets),Pet=receipt.uid})
    run.status=state.shadowCraftText("Auto Reroll: %s; iniciado.",receipt.label)
end
function state.shadowCraftStep(now)
    local prefs=state.craft.shadows
    if not prefs then return end
    local run=state.shadowRuntime or {running=false,completed=0};state.shadowRuntime=run
    if not prefs.pending and not run.running then return end
    local deps,entries,problem=state.shadowCraftData(true)
    if not entries then run.status=problem return end
    if prefs.pending and prefs.pending.mode=="native" or run.running and run.native and not prefs.pending then
        nativeRerollStep(now,prefs,run,entries)
        return
    end
    if prefs.pending then
        local ok,output,evidence=state.shadowCraftReconcile(prefs.pending,entries,state.shadowCraftCount,now)
        if ok then
            local priorReceipt=prefs.pending
            local oldSelected,oldRankSelected,oldDetail=table.clone(prefs.selected),table.clone(prefs.rankSelected),prefs.detail
            if prefs.pending.kind=="reroll" then
                for _,entry in ipairs(entries) do
                    if entry.uid==output then
                        run.lastResult={name=entry.info.Name or entry.pet.Name,stat=prefs.pending.stat,
                            before=prefs.pending.old,after=(entry.pet.Stats or {})[prefs.pending.stat]}
                        break
                    end
                end
            end
            if prefs.pending.kind=="rank" and output then
                local selection=prefs.rankScope=="one" and prefs.rankSelected or prefs.selected
                for _,uid in ipairs(prefs.pending.ids) do selection[uid]=nil end
                selection[output]=true;prefs.detail=output
            end
            prefs.pending=nil;run.completed=(run.completed or 0)+1
            run.status=evidence=="stat-change" and "Resultado confirmado pela mudança do atributo." or "Consumo confirmado; inventário observado."
            if not save() then
                prefs.pending=priorReceipt;prefs.selected=oldSelected;prefs.rankSelected=oldRankSelected;prefs.detail=oldDetail
                run.completed-=1;run.running=false;run.status="Falha ao salvar a confirmação; operação pausada."
            end
        elseif state.craftRecoveryReady and now-prefs.pending.at>=30 then
            local receipt=prefs.pending
            local parts={}
            for _,e in ipairs(entries) do
                if e.uid==receipt.uid then parts[#parts+1]=e.uid..":"..tostring((e.pet.Stats or {})[receipt.stat]) end
                for _,uid in ipairs(receipt.ids or {}) do if e.uid==uid then parts[#parts+1]=uid..":"..tostring(e.pet.Rank) end end
            end
            for id in pairs(receipt.costs) do parts[#parts+1]=id..":"..state.shadowCraftCount(id) end;table.sort(parts)
            run.status="Revisando pendência antiga das sombras."
            if state.craftRecoveryReady("shadow",receipt,table.concat(parts,"|"),now) then
                if state.craftArchive(prefs,"pending",receipt,"unconfirmed-stable-inventory") then
                    if not state.craftAllowRetry("shadow:"..receipt.kind..":"..receipt.name) then run.running=false;state.craftControl.requested=nil;run.status="Operação pausada: três pedidos sem resposta. Confira o rank e requisitos no jogo."
                    else run.status="Pendência arquivada; recalculando as cópias e materiais.";run.nextAt=now+2 end
                else run.running=false;run.status="Falha ao salvar a recuperação; operação pausada." end
            end
        elseif prefs.pending.kind=="rank" and now-prefs.pending.at>=15 then
            retryRank(prefs.pending,entries,run,now)
            if not run.running then run.status=run.status or "Conferindo automaticamente a fusão pendente." end
        elseif now-prefs.pending.at>=15 then
            run.running=false;run.status="Sem confirmação. Não repetirei a operação; confira o inventário."
        else run.status=prefs.pending.kind=="reroll" and state.shadowCraftText("Reroll: %s · %s; aguardando resultado.",prefs.pending.label or prefs.pending.name,state.shadowCraftText(prefs.pending.stat)) or "Aguardando atualização do inventário; sem repetir o pedido." end
        return
    end
    if not run.running then return end
    if run.kind=="reroll" and state.craftPrune and not state.craftPrune(entries,prefs,function(e) return state.shadowTargetsMet(e,prefs) end,run,now) then return end
    if state.panic or state.stopped or not alive or player.GameplayPaused then run.status="Operação pausada." return end
    if prefs.stopMode=="limit" and (run.completed or 0)>=prefs.limit then run.running=false;run.status="Limite de tentativas atingido; as metas podem continuar pendentes." return end
    if now<(run.nextAt or 0) then return end
    -- Taking ownership pauses NEW material dispatch in the Craft worker. Let an
    -- already-sent material receipt reconcile before dispatching a shadow request.
    local plan,message
    if run.kind=="rank" then plan,message=state.shadowCraftPlan(entries,prefs,deps.balance,state.shadowCraftCount,deps.playerRank)
    else plan,message=state.shadowRerollPlan(entries,prefs) end
    if not plan then run.running=false;run.status=message return end
    local busy,why=materialBusy(plan.costs,plan)
    if busy then run.status=why return end
    if not state.shadowCraftAffordable(plan,prefs,state.shadowCraftCount) then
        local _,missing=state.shadowCraftCosts(plan,deps)
        run.running=false;run.status=missing or "Materiais insuficientes para esta operação." return
    end
    local receipt=table.clone(plan)
    run.target=plan.kind=="reroll" and {uid=plan.uid,name=plan.label or plan.name,stat=plan.stat} or nil
    receipt.at,receipt.before,receipt.beforeIds=now,{},{}
    for key in pairs(plan.costs) do receipt.before[key]=state.shadowCraftCount(key) end
    for _,entry in ipairs(entries) do receipt.beforeIds[entry.uid]=true end
    prefs.pending=receipt
    if not save() then prefs.pending=nil;run.running=false;run.status="Falha ao salvar o pedido; nada foi enviado." return end
    if not run.running or state.panic or state.stopped then prefs.pending=nil;save();return end
    run.nextAt=now+1.5
    if plan.kind=="reroll" then general:Fire({Event="StatsShadow",Action="RerollStat",Stat=plan.stat,Pet=plan.uid})
    elseif plan.first then general:Fire({Event="UpgradePet",Pets=plan.byRank,PetType=plan.name,BuyType="Ticket"})
    else general:Fire({Event="UpgradePetV2",Pets=plan.ids,PetType=plan.name,RankUp=plan.rank,Auto=false}) end
    run.status=plan.kind=="reroll" and state.shadowCraftText("Reroll: %s · %s; pedido enviado.",plan.label or plan.name,state.shadowCraftText(plan.stat)) or "Pedido enviado; aguardando confirmação."
end
end
-- END SHADOW CRAFT RUNTIME
do
local viewQueued=false
local function updateView()
    state.shadowInventoryCache=nil
    if viewQueued then return end
    viewQueued=true
    task.defer(function()
        viewQueued=false
        if alive and not state.stopped and state.refreshInfusionView then
            pcall(state.refreshInfusionView)
        end
    end)
end
if type(clientData.OnChange)=="function" then
    local ok,subscription=pcall(clientData.OnChange,{"Inventory","Pets"},updateView)
    if ok and subscription then
        if type(subscription)=="function" then table.insert(cleanupCallbacks,subscription)
        elseif type(subscription.Disconnect)=="function" then table.insert(cleanupCallbacks,function() subscription:Disconnect() end) end
    end
end
function state.infusionData()
    local deps,entries,problem=state.shadowCraftData(true)
    if not entries then return deps,nil,problem end
    if not deps.infusion then deps.infusion={catalog=require(storage.Indexer.ShadowEnchants),big=require(storage.InfiniteMath)} end
    for _,key in ipairs(state.infusionKeys) do
        local info=deps.infusion.catalog[key]
        if type(info)~="table" or not info.Level or not tonumber(info.Level.Max) then return deps,nil,"Dados de infusão indisponíveis." end
    end
    return deps,entries
end
local function bigCopy(value)
    return {first=value.first,second=value.second}
end
local function currency(deps)
    local raw=clientData.Get("Gems")
    if raw==nil then return nil end
    if type(raw)=="table" then raw=table.clone(raw) end
    return deps.infusion.big.new(raw)
end
function state.infusionCosts(plan,deps)
    local big=deps.infusion.big
    local gems=big.new(plan.gemsBase)*big.new(plan.gemsLevel)*big.new(plan.gemsLocks)
    local costs=plan.payment=="Ticket" and {Ticket=plan.tickets} or {[plan.item]=plan.items}
    return costs,gems
end
local function affordable(plan,deps)
    local costs,gems=state.infusionCosts(plan,deps)
    for id,need in pairs(costs) do
        if state.shadowCraftCount(id)<need then
            local info=deps.items and deps.items[id]
            return false,state.infusionText("Faltam %s para infundir.",tostring(need-state.shadowCraftCount(id)).." "..state.infusionText(info and info.Name or id))
        end
    end
    if plan.payment=="Gems" then
        local balance=currency(deps)
        if not balance then return false,"Dados de infusão indisponíveis." end
        if balance<gems then return false,"Gems insuficientes para infundir." end
    end
    return true
end
local function materialsBusy(costs)
    if state.questReset and state.questReset.pending and costs.Ticket then return true end
    if state.craft.pending and (not state.craftTouches or state.craftTouches(costs,state.craftReceiptResources(state.craft.pending))) then return true end
    if autoBuy then
        local function conflicts(receipt)
            if not receipt then return false end
            local lookup=state.buyUI and state.buyUI.view and state.buyUI.view.lookup
            local entry=lookup and lookup[receipt.key]
            if entry then return state.buyTouchesInfusion(entry.item,costs) end
            -- Old receipts without catalog metadata remain conservative for Ticket debits.
            local real=type(receipt.key)=="string" and receipt.key:match(":(.+)$")
            return costs.Ticket~=nil or real and costs[real]~=nil
        end
        if conflicts(autoBuy.pending) then return true end
        for _,receipt in pairs(autoBuy.unconfirmed or {}) do if conflicts(receipt) then return true end end
    end
    for _,receipt in pairs(state.craft.unconfirmed or {}) do
        if not receipt.source or costs[receipt.source] or costs[receipt.output] then return true end
        for id in pairs(receipt.costs or {}) do if costs[id] then return true end end
    end
    return false
end
function state.infusionStop()
    if state.craftStopRequested then state.craftStopRequested("infusion") end
    local run=state.infusionRun
    if run then run.running=false;run.recoverRequested=nil;run.recovery=nil;run.status="Infusão interrompida." end
    -- Each request is a single roll (AutoEnchant=false); no server loop remains.
end
function state.infusionStart()
    local prefs=state.infusionPrefs()
    local run=state.infusionRun or {confirmed=0,sent=0};state.infusionRun=run
    if run.running or state.stopped or state.panic or not alive or player.GameplayPaused then return false end
    if state.craftSwitch and not state.craftSwitch("infusion") then run.status=state.craftControl.status;return true end
    if prefs.pending then
        -- An explicit Start authorizes a fresh plan after reviewing an old,
        -- unresolved receipt. Reloading alone never resumes spending.
        run.running=true;run.recoverRequested=true;run.recovery=nil
        run.status="Revisando pendência antiga da infusão."
        return true
    end
    if state.craft.shadows and state.craft.shadows.pending or state.shadowRuntime and state.shadowRuntime.running then
        run.status="Pare Rank Up/Reroll antes de iniciar Infusão.";return false
    end
    local ok,deps,entries,problem=pcall(state.infusionData)
    if not ok or not entries then run.status=problem or "Dados de infusão indisponíveis.";return false end
    if state.craftPrune and not state.craftPrune(entries,prefs,function(e) return state.infusionTargetsMet(e,prefs) end,run,workspace:GetServerTimeNow()) then return false end
    local entry,plan,reason=state.infusionQueue(entries,prefs,deps.infusion.catalog,deps.balance)
    if not plan then run.status=reason;return false end
    local enough,why=affordable(plan,deps)
    if not enough then run.status=why;return false end
    if not save() then run.status="Falha ao salvar; nenhuma infusão foi enviada.";return false end
    run.running,run.confirmed,run.sent,run.status=true,0,0,"Infusão preparada."
    run.nextAt=0
    run.uid=entry.uid
    return true
end
function state.infusionReconcile(receipt,entry,deps,now)
    if not entry or entry.uid~=receipt.uid or entry.pet.Name~=receipt.name or now-receipt.at<0.75 then return false end
    if state.infusionSignature(entry.pet)~=receipt.signature then return true,"enchants" end
    -- A roll can produce exactly the same bonuses. Actual source debit is evidence,
    -- including material debit when a huge Gems balance cannot represent small changes.
    for id,need in pairs(receipt.costs) do
        if type(receipt.before[id])~="number" or state.shadowCraftCount(id)>receipt.before[id]-need then return false end
    end
    return next(receipt.costs)~=nil,"debit"
end
local function recoverPending(prefs,run,receipt,entry,now)
    if not run.recoverRequested then return end
    if state.panic or state.stopped or not alive or player.GameplayPaused then state.infusionStop();return end
    if now-receipt.at<30 then return end
    local keys={};for id in pairs(receipt.costs) do keys[#keys+1]=id end;table.sort(keys)
    local parts={entry and (entry.pet.Name..":"..state.infusionSignature(entry.pet)) or "missing"}
    for _,id in ipairs(keys) do parts[#parts+1]=id..":"..tostring(state.shadowCraftCount(id)) end
    local signature=table.concat(parts,"|")
    local sample=run.recovery
    if not sample or sample.receipt~=receipt or sample.signature~=signature then
        run.recovery={receipt=receipt,signature=signature,at=now,count=1};return
    end
    sample.count+=1
    if sample.count<3 or now-sample.at<2 then return end
    local previous=prefs.unconfirmed
    local history={receipt}
    for i,old in ipairs(previous or {}) do if i>=8 then break end;history[#history+1]=old end
    prefs.unconfirmed=history;prefs.pending=nil
    if not save() then
        prefs.pending=receipt;prefs.unconfirmed=previous;state.infusionStop()
        run.status="Falha ao salvar; nenhuma infusão foi enviada.";return
    end
    run.recoverRequested=nil;run.recovery=nil;run.nextAt=now+0.6
    run.recoveryAttempts=(run.recoveryAttempts or 0)+1
    if run.recoveryAttempts>=3 then
        run.running=false
        if state.craftControl then state.craftControl.requested=nil end
        run.status="Infusão pausada: três pedidos sem resposta. Confira os requisitos no jogo.";return
    end
    run.status="Pendência antiga arquivada; retomando pelas metas atuais."
end
function state.infusionStep(now)
    local prefs=state.craft.infusion
    if not prefs then return end
    local run=state.infusionRun or {running=false,confirmed=0,sent=0};state.infusionRun=run
    if not run.running and not prefs.pending then return end
    local deps,entries,problem=state.infusionData()
    if not entries then run.status=problem or "Dados de infusão indisponíveis.";return end
    local receipt=prefs.pending
    if receipt then
        if now-receipt.at>=30 then run.recoverRequested=true end
        local entry
        for _,e in ipairs(entries) do if e.uid==receipt.uid then entry=e;break end end
        local ok,evidence=state.infusionReconcile(receipt,entry,deps,now)
        if ok then
            prefs.pending=nil;run.confirmed=(run.confirmed or 0)+1
            run.recoveryAttempts=0
            run.recoverRequested=nil;run.recovery=nil
            run.status="Infusão confirmada.";run.evidence=evidence;run.nextAt=now+0.6
            if not save() then prefs.pending=receipt;run.confirmed-=1;run.running=false;run.status="Falha ao salvar; nenhuma infusão foi enviada." end
            updateView()
        else
            run.status=run.recoverRequested and "Revisando pendência antiga da infusão." or now-receipt.at>=15 and "Aguardando sincronização; sem duplicar a infusão." or "Aguardando resultado da infusão."
            recoverPending(prefs,run,receipt,entry,now)
        end
        return
    end
    if not run.running then return end
    if state.panic or state.stopped or not alive or player.GameplayPaused then run.running=false;run.status="Infusão pausada.";return end
    if now<(run.nextAt or 0) then return end
    if state.craft.shadows and state.craft.shadows.pending or state.shadowRuntime and state.shadowRuntime.running then run.status="Pare Rank Up/Reroll antes de iniciar Infusão.";return end
    if state.craftPrune and not state.craftPrune(entries,prefs,function(e) return state.infusionTargetsMet(e,prefs) end,run,now) then return end
    local waiting=state.craftFocusWaiting and state.craftFocusWaiting(entries,prefs,run.uid)
    if waiting then run.status=waiting;return end
    local entry,plan,reason=state.infusionQueue(entries,prefs,deps.infusion.catalog,deps.balance,run.uid)
    if not plan then
        if reason~="Aguardando as sombras selecionadas ficarem disponíveis." then run.running=false end
        run.status=(run.finished or 0)>0 and not next(prefs.selected) and "Todas as metas de infusão foram atingidas." or reason;return
    end
    if state.craftSalePending and state.craftSalePending(entry.uid) then run.status="Aguardando venda anterior da sombra: "..entry.uid;return end
    local costs,gems=state.infusionCosts(plan,deps)
    if materialsBusy(costs) then run.status="Aguardando confirmação dos materiais.";return end
    local enough,why=affordable(plan,deps)
    if not enough then run.running=false;run.status=why;return end
    run.uid=entry.uid
    if run.recoveryUID~=entry.uid then run.recoveryUID=entry.uid;run.recoveryAttempts=0 end
    receipt={uid=plan.uid,name=plan.name,payment=plan.payment,at=now,costs=costs,before={},
        enchants=table.clone(entry.pet.Enchants or {}),signature=state.infusionSignature(entry.pet),locks=plan.locks,
        gemsCost=bigCopy(gems)}
    for id in pairs(costs) do receipt.before[id]=state.shadowCraftCount(id) end
    prefs.pending=receipt
    if not save() then prefs.pending=nil;run.running=false;run.status="Falha ao salvar; nenhuma infusão foi enviada.";return end
    if not run.running or state.panic or state.stopped or not alive or player.GameplayPaused then prefs.pending=nil;save();return end
    run.sent=(run.sent or 0)+1
    local ok=pcall(function() general:Fire({Event="ShadowEnchant",Shadow=plan.uid,BuyType=plan.payment,Locks=table.clone(plan.locks),AutoEnchant=false}) end)
    run.status=ok and "Aguardando resultado da infusão." or "Falha ao enviar a infusão; aguardando sincronização."
    updateView()
end
end
-- Persist one explicit Craft owner, without serializing transient running flags.
do
local control=state.craftControl
local startShadow,stopShadow=state.shadowCraftStart,state.shadowCraftStop
local startInfusion,stopInfusion=state.infusionStart,state.infusionStop
local controllerStep=state.craftControllerStep
local dirty=false
local function persist(mode,uid)
    if state.craft.activeMode==mode and state.craft.activeUID==uid and not dirty then return true end
    state.craft.activeMode=mode;state.craft.activeUID=uid
    dirty=not save()
    if dirty then control.persistenceProblem="Falha ao salvar o modo Craft; operação pausada." end
    return not dirty
end
local function active(mode)
    if mode=="infusion" then return state.infusionRun and state.infusionRun.running end
    return state.shadowRuntime and state.shadowRuntime.running and state.shadowRuntime.kind==mode
end
local function remember(mode,accepted)
    if accepted or active(mode) then
        local uid=state.craft.activeMode==mode and state.craft.activeUID
        if accepted and uid then
            if mode=="infusion" and state.infusionRun and (state.craft.infusion.selected or {})[uid] then state.infusionRun.uid=uid
            elseif mode=="reroll" and state.shadowRuntime and (state.craft.shadows.selected or {})[uid] then state.shadowRuntime.target=state.shadowRuntime.target or {};state.shadowRuntime.target.uid=uid end
        end
        if persist(mode,state.craft.activeMode==mode and state.craft.activeUID or nil) then return accepted end
        stopShadow();stopInfusion();control.requested=nil;control.resumePending=nil
        state.craft.activeMode=nil;state.craft.activeUID=nil;dirty=true
        local run=mode=="infusion" and state.infusionRun or state.shadowRuntime
        if run then run.status=control.persistenceProblem end
        return false
    end
    if not control.requested and not (state.shadowRuntime and state.shadowRuntime.running) and not (state.infusionRun and state.infusionRun.running) then persist(nil,nil) end
    return false
end
function state.shadowCraftStart(kind)
    return remember(kind,startShadow(kind))
end
function state.infusionStart()
    return remember("infusion",startInfusion())
end
function state.shadowCraftStop()
    stopShadow()
    if alive and not state.stopped and not control.restoring then
        control.resumePending=nil
        if state.craft.activeMode=="rank" or state.craft.activeMode=="reroll" then persist(nil,nil) end
    end
end
function state.infusionStop()
    stopInfusion()
    if alive and not state.stopped and not control.restoring and not state.panic and not player.GameplayPaused then
        control.resumePending=nil
        if state.craft.activeMode=="infusion" then persist(nil,nil) end
    end
end
function state.craftPersistenceStep()
    if not alive or state.stopped or state.panic or player.GameplayPaused or control.resumePending then return end
    local mode=control.requested
    if not mode and state.infusionRun and state.infusionRun.running then mode="infusion" end
    if not mode and state.shadowRuntime and state.shadowRuntime.running then mode=state.shadowRuntime.kind end
    local uid
    if mode=="infusion" then uid=state.infusionRun and state.infusionRun.uid
    elseif mode=="reroll" then uid=state.shadowRuntime and state.shadowRuntime.target and state.shadowRuntime.target.uid end
    persist(mode,uid)
end
function state.craftControllerStep(now)
    if control.resumePending then
        if not alive or state.stopped or state.panic or player.GameplayPaused then return end
        local ok,_,entries=pcall(state.shadowCraftData,true)
        if not ok or not entries then control.status="Aguardando inventário para retomar o Craft salvo.";return end
        if not control.resumeAt then control.resumeAt=now+2;return end
        if now<control.resumeAt then return end
