    end
    api.shortage=false
    if state.questProfiles and (not state.questProfiles.resetAllowed(autoQuest) or not api.includes("Daily") and not api.includes("Weekly")) then
        api.status=tr("Auto Reset: desativado para os grupos deste objetivo.","Auto Reset: unavailable for this objective's groups.","Auto Reset: desactivado para los grupos de este objetivo.");return
    end
    if now<api.nextAt then return end
    local blockedMessage
    local interval=autoQuest.resetInterval or 0
    if api.interval~=interval or not autoQuest.resetDue or not autoQuest.resetDue.Daily or not autoQuest.resetDue.Weekly then
        api.interval=interval;autoQuest.resetDue={Daily=now+interval,Weekly=now+interval}
        if not save() then api.status=tr("Auto Reset: falha ao salvar; nenhum pedido novo enviado.","Auto Reset: could not save; no new request sent.","Auto Reset: error al guardar; ninguna solicitud nueva enviada.");return end
    end
    local order=autoQuest.resetLastBucket=="Daily" and {"Weekly","Daily"} or {"Daily","Weekly"}
    for _,bucket in ipairs(order) do
        if not api.includes(bucket) then api.emptyAt[bucket]=nil;continue end
        local status=api.board(clientData.Get("Quests",bucket),definitions[bucket],bucket)
        if status=="claim" then
            api.emptyAt[bucket]=nil
            if now>=(api.claimAt[bucket] or 0) then
