            end
            api.status=tr("Auto Reset: resgatando recompensas de ","Auto Reset: claiming rewards for ","Auto Reset: recogiendo recompensas de ")..bucket;return
        elseif (status=="empty" or status=="unavailable") and interval==0 or interval>0 and (status=="working" or status=="unavailable" or status=="empty") and now>=(autoQuest.resetDue[bucket] or now+interval) then
            local since=api.emptyAt[bucket] or now;api.emptyAt[bucket]=since
            local completionDelay=autoQuest.resetCompletionDelay or 1
            if interval==0 and now-since<completionDelay then api.status=tr("Auto Reset: conferindo se todas as recompensas foram resgatadas.","Auto Reset: checking that all rewards were claimed.","Auto Reset: comprobando que se recogieron todas las recompensas.");continue end
            local product=bucket=="Daily" and "DailyQuestReset" or "WeeklyQuestReset"
            local info=products and products[product]
            local price=info and tonumber(info.Promo==true and info.PromoV or info.Price)
            if not price or price<=0 or price~=price or price==math.huge then blockedMessage=tr("Auto Reset: preço nativo indisponível.","Auto Reset: native price unavailable.","Auto Reset: precio nativo no disponible.");continue end
            local owned=tickets(product.."PRODUCT")
            if owned<=0 and tickets("Ticket")<price then api.shortage=true;blockedMessage=tr("Auto Reset: faltam tickets para ","Auto Reset: insufficient Tickets for ","Auto Reset: faltan Tickets para ")..bucket.." ("..price..").";continue end
            if state.craftItemBusy and state.craftItemBusy({PriceType="Ticket",Kind="Item",Real=product.."PRODUCT"}) then
                blockedMessage=tr("Auto Reset: aguardando operação de Craft com Tickets.","Auto Reset: waiting for a Craft operation using Tickets.","Auto Reset: esperando una operación de Craft con Tickets.");continue
            end
            local signature,total=api.fingerprint(clientData.Get("Quests",bucket))
            local receipt={bucket=bucket,product=product,at=now,phase=owned>0 and "use" or "buy",itemBefore=owned,useBefore=owned>0 and owned or nil,price=owned>0 and 0 or price,costs=owned>0 and {} or {Ticket=price},forced=interval>0,beforeSignature=signature,beforeTotal=total,ticketBefore=tickets("Ticket"),attempts=1}
            local previousBucket=autoQuest.resetLastBucket;autoQuest.resetLastBucket=bucket
            if not persistPending(receipt) then autoQuest.resetLastBucket=previousBucket;return end
            if owned>0 then general:Fire({Event="UseItem",Action="Use",Amount=1,Name=product.."PRODUCT"})
            else general:Fire({Event="TicketShop",Type="Product",SubType="Products",Name=product}) end
            api.status=tr("Auto Reset: solicitando ","Auto Reset: requesting ","Auto Reset: solicitando ")..bucket.." ("..price.." Tickets).";return
        else
            api.emptyAt[bucket]=nil
            if status=="disabled" then blockedMessage=tr("Auto Reset: nenhuma missão selecionada em ","Auto Reset: no selected quests in ","Auto Reset: ninguna misión seleccionada en ")..bucket
            elseif status=="unavailable" then blockedMessage=tr("Auto Reset: nenhuma missão selecionada apareceu no quadro atual de ","Auto Reset: no selected quest appeared in the current board for ","Auto Reset: ninguna misión seleccionada apareció en el cuadro actual de ")..bucket end
            api.status=status=="working" and tr("Auto Reset: aguardando concluir as missões selecionadas.","Auto Reset: waiting for selected quests to finish.","Auto Reset: esperando completar las misiones seleccionadas.") or tr("Auto Reset: aguardando dados completos das missões.","Auto Reset: waiting for complete quest data.","Auto Reset: esperando datos completos de misiones.")
        end
    end
    if interval>0 and not blockedMessage then
        local nextDue=math.huge
        for _,bucket in ipairs({"Daily","Weekly"}) do if api.includes(bucket) then nextDue=math.min(nextDue,autoQuest.resetDue[bucket] or now+interval) end end
        api.status=tr("Auto Reset: próximo reset em ","Auto Reset: next reset in ","Auto Reset: próximo reinicio en ")..math.max(0,math.ceil(nextDue-now)).."s."
    end
    if blockedMessage then api.status=blockedMessage end
end
end
-- Local Infusion form, integrated into the existing Craft page only.
function state.installInfusionUI(H)
    local frame,labelAt,tr,outline=H.frame,H.labelAt,H.tr,H.outline
    local panels={}
    local queueOpen,queuePage=false,1
    local function panel(name,height,order)
        local f=frame(name,height,order);panels[#panels+1]=f;f.Visible=false
        local corner=f:FindFirstChildOfClass("UICorner");if corner then corner.CornerRadius=UDim.new(0,10) end
        return f
    end
    local function text(node,value)
        H.set(node,value)
        local foreground=node:FindFirstChild("InfusionText")
        if foreground then H.set(foreground,value) end
    end
    local function action(parent,name,y,callback)
        local b=H.button(parent,name,y,callback)
        local navigation=name=="Back" or name=="ChangeShadow" or name=="Selected" or name=="Clear"
            or name=="Previous" or name=="Next" or name=="Add"
        if navigation then
            b:SetAttribute("InfusionNavigation",true)
            local corner=b:FindFirstChildOfClass("UICorner") or make("UICorner",{},b)
            corner.CornerRadius=UDim.new(0,3)
        end
        local fg=make("TextLabel",{Name="InfusionText",Size=UDim2.new(1,-12,1,0),Position=UDim2.fromOffset(6,0),
            BackgroundTransparency=1,Text="",TextColor3=colors.text,Font=Enum.Font.GothamBold,TextSize=12,TextWrapped=true,ZIndex=b.ZIndex+4},b)
        local watched=setmetatable({},{__mode="k"})
        local function redraw()
            b.TextTransparency=1;b.TextStrokeTransparency=1;b.BackgroundTransparency=0;fg.ZIndex=b.ZIndex+5
            local border=b:FindFirstChildOfClass("UIStroke");if border then
                border.ApplyStrokeMode=Enum.ApplyStrokeMode.Border
                if navigation then border.Color=colors.accent;border.Transparency=0.2;border.Thickness=1 end
            end
            if navigation then
                fg.TextSize=13;fg.TextTransparency=0
                local hide=b:FindFirstChild("NUI_CutHide")
                if hide then
                    if not watched[hide] then
                        watched[hide]=true
                        table.insert(connections,hide:GetPropertyChangedSignal("Enabled"):Connect(function() if hide.Enabled then hide.Enabled=false end end))
                    end
                    hide.Enabled=false
                end
            end
            for _,child in ipairs(b:GetChildren()) do if child:IsA("GuiObject") and child~=fg then
                local visible=not navigation and child.Name=="NUI_CutFill"
                if not watched[child] then
                    watched[child]=true
                    table.insert(connections,child:GetPropertyChangedSignal("Visible"):Connect(function() if child.Visible~=visible then child.Visible=visible end end))
                end
                child.Visible=visible
                if visible then child.ZIndex=b.ZIndex+3 end
            end end
        end
        table.insert(connections,b:GetPropertyChangedSignal("TextTransparency"):Connect(function() if b.TextTransparency~=1 then redraw() end end))
        table.insert(connections,b:GetPropertyChangedSignal("TextStrokeTransparency"):Connect(function() if b.TextStrokeTransparency~=1 then redraw() end end))
        table.insert(connections,b.ChildAdded:Connect(redraw))
        if navigation then
            table.insert(connections,b:GetPropertyChangedSignal("BackgroundTransparency"):Connect(function() if b.BackgroundTransparency~=0 then redraw() end end))
        end
        redraw()
        return b
    end
    -- Clone the Hub's native pill toggle; keep its knob and rounded geometry.
    local function switchAction(parent,name,y,callback)
        local template=state.newHub.pages.DungeonMain.DungeonCard.Section.Row_AutoLeave.Toggle
        local b=template:Clone();b.Name=name
        b:SetAttribute("Bind",nil);b:SetAttribute("Id",nil);b:SetAttribute("InfusionSwitch",true)
        b.AnchorPoint=Vector2.new(0.5,0);b.Position=UDim2.new(0,0,0,y);b.Size=UDim2.fromOffset(36,20)
        b.Text="";b.TextTransparency=1;b.TextStrokeTransparency=1;b.ZIndex=5
        local fg=make("TextLabel",{Name="InfusionText",Text="",Visible=false,BackgroundTransparency=1,Size=UDim2.fromScale(1,1)},b)
        fg:SetAttribute("Decorative",true)
        b.Knob.Size=UDim2.fromOffset(16,16);b.Knob.ZIndex=6
        b.Parent=parent;connectUI(b,callback)
        local function hideNativeText()
            if b.TextTransparency~=1 then b.TextTransparency=1 end
            if b.TextStrokeTransparency~=1 then b.TextStrokeTransparency=1 end
            local stroke=b:FindFirstChildOfClass("UIStroke");if stroke then stroke.ApplyStrokeMode=Enum.ApplyStrokeMode.Border end
        end
        table.insert(connections,b:GetPropertyChangedSignal("TextTransparency"):Connect(hideNativeText))
        table.insert(connections,b:GetPropertyChangedSignal("TextStrokeTransparency"):Connect(hideNativeText))
        hideNativeText()
        return b
    end
    local function paintSwitch(b,on,enabled)
        b:SetAttribute("Enabled",on==true)
        b.BackgroundColor3=on and Color3.fromRGB(25,195,100) or Color3.fromRGB(218,56,62)
        b.BackgroundTransparency=enabled==false and 0.35 or 0
        b.Knob.Position=on and UDim2.new(1,-18,0.5,0) or UDim2.new(0,2,0.5,0)
        b.Knob.BackgroundColor3=Color3.fromRGB(255,255,255)
        b.Knob.BackgroundTransparency=enabled==false and 0.25 or 0
        b.Knob.Visible=true;b.InfusionText.Visible=false
    end
    local function editable()
        -- Selection and goals may change while stopped; the runtime keeps its
        -- immutable receipt and still blocks sending until it is reconciled.
        return not (state.infusionRun and state.infusionRun.running)
    end
    local refresh
    local function mutate(callback)
        if not editable() then return false end
        local old=state.infusionRestore(state.infusionPrefs())
        callback(state.infusionPrefs())
        if not save() then
            state.craft.infusion=old;state.infusionRun=state.infusionRun or {}
            state.infusionRun.status="Falha ao salvar; nenhuma infusão foi enviada."
            return false
        end
        if state.infusionRun then state.infusionRun.status=nil end
        return true
    end
    local function chooseOption(title,rows,callback)
        choose(title,rows,function(value)
            callback(value);state.newHubShow("Craft",false)
            if state.shadowCraftRefresh then state.shadowCraftRefresh("Infusion") end
        end,"Craft")
    end
    local function data()
        local ok,deps,entries,reason=pcall(state.infusionData)
        if not ok then return nil,nil,"Dados de infusão indisponíveis." end
        if not entries then return nil,nil,reason or "Dados de infusão indisponíveis." end
        return deps,entries,reason
    end
