    local back=action(header,"Back",16,function() if queueOpen then queueOpen=false;refresh(true) else H.open("Shadows") end end)
    back.Size=UDim2.fromOffset(80,40)
    local title=labelAt(header,"Title",8,28,true);title.Position=UDim2.fromOffset(104,8);title.Size=UDim2.new(1,-116,0,28);title.TextSize=16
    local subtitle=labelAt(header,"Description",36,30,false);subtitle.Position=UDim2.fromOffset(104,36);subtitle.Size=UDim2.new(1,-116,0,30)
    local card=panel("InfusionShadow",142,3)
    local cardTitle=labelAt(card,"Heading",6,24,true)
    local portrait=make("ImageLabel",{Name="Portrait",Position=UDim2.fromOffset(12,40),Size=UDim2.fromOffset(66,86),BackgroundTransparency=1,Image="",ScaleType=Enum.ScaleType.Fit,ZIndex=4},card)
    local name=labelAt(card,"Name",34,28,true);name.Position=UDim2.fromOffset(90,34);name.Size=UDim2.new(1,-170,0,28);name.TextSize=15
    local uidText=labelAt(card,"UID",62,20,false);uidText.Position=UDim2.fromOffset(90,62);uidText.Size=UDim2.new(1,-102,0,20)
    local rank=labelAt(card,"Rank",12,24,true);rank.Position=UDim2.new(1,-72,0,12);rank.Size=UDim2.fromOffset(60,24);rank.TextXAlignment=Enum.TextXAlignment.Right;rank.TextColor3=colors.accent
    local function pickShadow()
        if not editable() then return end
        local deps,entries=data();if not entries then return end
        local groups,rows={},{}
        for _,entry in ipairs(entries) do
            if not entry.pet.InExp and not state.infusionTargetsMet(entry,state.infusionPrefs()) then
                local key=entry.pet.Name
                if not groups[key] then groups[key]={info=entry.info,list={}} end
                table.insert(groups[key].list,entry)
            end
        end
        for key,g in pairs(groups) do rows[#rows+1]={id=key,name=(g.info.Name or key).." ("..#g.list..")",image=g.info.Image} end
        table.sort(rows,function(a,b) return a.name<b.name end)
        table.insert(rows,1,{id="!all",name=tr("Selecionar máximo • todos os tipos","Auto Select Max • all types","Seleccionar máximo • todos los tipos")})
        local function focus(p,uid)
            p.uid=uid;p.locksByUid=p.locksByUid or {};p.locks=p.locksByUid[uid] or {};p.locksByUid[uid]=p.locks
        end
        local function finish()
            queueOpen=false;state.newHubShow("Craft",false);state.shadowCraftRefresh("Infusion")
        end
        local function page(key,offset)
            local g=groups[key];if not g then return end
            local options={{id="!max",name=tr("Selecionar máximo deste tipo","Auto Select Max for this type","Seleccionar máximo de este tipo").." ("..#g.list..")"},
                {id="!done",name=tr("Concluir seleção","Finish selection","Terminar selección")}}
            for i=offset,math.min(offset+59,#g.list) do
                local e=g.list[i];local good,grade=pcall(deps.extra.GetRankInfo,e.pet.Rank)
                options[#options+1]={id=e.uid,name=(g.info.Name or key).." · "..(good and grade or tostring(e.pet.Rank)).." · "..e.uid:sub(-8),image=e.info.Image,selected=state.infusionPrefs().selected[e.uid]==true}
            end
            if offset>1 then options[#options+1]={id="!previous",name=tr("‹ Anterior","‹ Previous","‹ Anterior")} end
            if offset+60<=#g.list then options[#options+1]={id="!next",name=tr("Próxima ›","Next ›","Siguiente ›")} end
            choose(tr("Escolher sombra","Choose shadow","Elegir sombra"),options,function(id)
                if id=="!next" then page(key,offset+60);return end
                if id=="!previous" then page(key,math.max(1,offset-60));return end
                if id=="!done" then finish();return end
                if id=="!max" then
                    mutate(function(p) for _,e in ipairs(g.list) do p.selected[e.uid]=true end;focus(p,g.list[1].uid) end)
                    finish();return
                end
                mutate(function(p)
                    p.selected[id]=not p.selected[id] or nil
                    if p.selected[id] then focus(p,id)
                    elseif p.uid==id then local other=next(p.selected);if other then focus(p,other) else p.uid=nil;p.locks={} end end
                end)
                page(key,offset)
            end,"Craft")
        end
        choose(tr("Tipo de sombra","Shadow type","Tipo de sombra"),rows,function(key)
            if key=="!all" then
                mutate(function(p)
                    local first
                    for _,e in ipairs(entries) do if not e.pet.InExp and not state.infusionTargetsMet(e,p) then p.selected[e.uid]=true;first=first or e.uid end end
                    if first then focus(p,first) end
                end)
                finish();return
            end
            page(key,1)
        end,"Craft")
    end
    local change=action(card,"ChangeShadow",94,pickShadow);change.Position=UDim2.fromOffset(90,94);change.Size=UDim2.new(1,-102,0,34)
    local selectionPanel=panel("InfusionSelection",64,4)
