        p.selected={};p.uid=nil;p.locks={};p.locksByUid={};p.finished={}
        if not save() then p.selected=old.selected;p.uid=old.uid;p.locks=old.locks;p.locksByUid=old.locksByUid;p.finished=old.finished end
        queueOpen=false;queuePage=1;refresh(true)
