    local queueCards={}
    for i=1,8 do
        local f=make("Frame",{Name="Shadow"..i,Position=UDim2.fromOffset(12,86+(i-1)*112),Size=UDim2.new(1,-24,0,102),BackgroundColor3=colors.bg,BorderSizePixel=0},queue);outline(f)
        local art=make("ImageLabel",{Name="Portrait",Position=UDim2.fromOffset(8,16),Size=UDim2.fromOffset(48,72),BackgroundTransparency=1,Image="",ScaleType=Enum.ScaleType.Fit,ZIndex=4},f)
