        local status=labelAt(f,"Status",30,22,false);status.Position=UDim2.fromOffset(66,30);status.Size=UDim2.new(1,-78,0,22);status.TextSize=11
        local levels=labelAt(f,"Levels",54,40,false);levels.Position=UDim2.fromOffset(66,54);levels.Size=UDim2.new(1,-78,0,40);levels.TextSize=12
        queueCards[i]={frame=f,art=art,name=n,status=status,levels=levels}
    end
    local automation=panel("InfusionAutomation",84,5)
    local autoTitle=labelAt(automation,"Heading",6,24,true)
    local autoDescription=labelAt(automation,"Description",34,40,false);autoDescription.Size=UDim2.new(1,-104,0,40);autoDescription.TextSize=12
    local lastStart=-math.huge
    local function startStop()
        local now=os.clock()
        local ok,problem=pcall(function()
            if state.infusionRun and state.infusionRun.running or state.craftControl and state.craftControl.requested=="infusion" then
                if now-lastStart<0.6 then return end
                state.infusionStop()
            elseif state.infusionStart() then lastStart=now end
        end)
        if not ok then
            state.infusionStop();state.infusionRun=state.infusionRun or {}
            state.infusionRun.status="Dados de infusão indisponíveis.";state.infusionRun.error=tostring(problem)
