        local n=labelAt(tile,"Name",4,24,true);n.Position=UDim2.fromOffset(52,4);n.Size=UDim2.new(1,-64,0,24);n.TextSize=14
        local current=labelAt(tile,"Current",28,18,false);current.Position=UDim2.fromOffset(52,28);current.Size=UDim2.new(1,-64,0,18);current.TextSize=11
        local target=action(tile,"Target",11,function()
            if not editable() then return end
            local deps=data();local info=deps and deps.infusion.catalog[key];if not info then return end
            local p=state.infusionPrefs();local options={{id=0,name=tr("Ignorar","Ignore","Ignorar"),selected=p.targets[key]==0}}
            for level=1,info.Level.Max do options[#options+1]={id=level,name=tostring(level).." / "..info.Level.Max,selected=p.targets[key]==level} end
            chooseOption(state.infusionText(key),options,function(level) mutate(function(p) state.infusionSetTarget(p,key,level,deps.infusion.catalog) end) end)
        end)
        target.Position=UDim2.fromOffset(10,50);target.Size=UDim2.new(0.5,-16,0,30)
        local enabled=switchAction(tile,"Enabled",61,function()
            local deps=data();local info=deps and deps.infusion.catalog[key];if not info then return end
            mutate(function(p) state.infusionSetTarget(p,key,(p.targets[key] or 0)>0 and 0 or info.Level.Max,deps.infusion.catalog) end)
            if refresh then refresh(true) end
        end)
        enabled.Position=UDim2.new(0.61,0,0,61)
        local enabledTitle=labelAt(tile,"EnabledTitle",45,14,false);enabledTitle.Position=UDim2.new(0.61,-32,0,45);enabledTitle.Size=UDim2.fromOffset(64,14);enabledTitle.TextSize=10;enabledTitle.TextXAlignment=Enum.TextXAlignment.Center
        local lock=switchAction(tile,"Lock",61,function()
            mutate(function(p) p.locks[key]=not p.locks[key] or nil end)
            if refresh then refresh(true) end
        end)
        lock.Position=UDim2.new(0.86,0,0,61)
        local lockTitle=labelAt(tile,"LockTitle",45,14,false);lockTitle.Position=UDim2.new(0.86,-32,0,45);lockTitle.Size=UDim2.fromOffset(64,14);lockTitle.TextSize=10;lockTitle.TextXAlignment=Enum.TextXAlignment.Center
        rows[key]={icon=icon,name=n,current=current,target=target,enabled=enabled,lock=lock,enabledTitle=enabledTitle,lockTitle=lockTitle}
    end
    local hint=labelAt(goals,"Hint",766,94,false);hint.TextSize=14
    local payment=panel("InfusionPayment",156,7)
    local payTitle=labelAt(payment,"Heading",6,26,true)
    local gemsButton=action(payment,"Gems",40,function() mutate(function(p) p.payment="Gems" end);if refresh then refresh(true) end end)
    gemsButton.Size=UDim2.new(0.6,-18,0,36)
    local ticketButton=action(payment,"Ticket",40,function() mutate(function(p) p.payment="Ticket" end);if refresh then refresh(true) end end)
    ticketButton.Position=UDim2.new(0.6,0,0,40);ticketButton.Size=UDim2.new(0.4,-12,0,36)
    local costs=labelAt(payment,"Costs",84,64,false);costs.TextSize=12;costs.TextYAlignment=Enum.TextYAlignment.Top
    local activity=panel("InfusionActivity",166,8)
    local statusTitle=labelAt(activity,"Heading",6,25,true)
    local status=labelAt(activity,"Status",36,50,true);status.TextSize=14
    local attempts=labelAt(activity,"Attempts",88,25,false);attempts.TextSize=12
    local track=make("Frame",{Name="Progress",Position=UDim2.fromOffset(12,130),Size=UDim2.new(1,-24,0,10),BackgroundColor3=colors.bg,BorderSizePixel=0},activity);outline(track)
    local fill=make("Frame",{Name="Fill",Size=UDim2.fromScale(0,1),BackgroundColor3=colors.accent,BorderSizePixel=0},track)
    local footer=panel("InfusionStart",64,9)
    local start=action(footer,"StartStop",12,startStop);start.Size=UDim2.new(1,-24,0,40)
    local function paintButton(b,fill,foreground)
        b.BackgroundColor3=fill or Color3.fromRGB(12,53,66);b.BackgroundTransparency=0
        b.InfusionText.TextColor3=foreground or colors.text
        local stroke=b:FindFirstChildOfClass("UIStroke")
        if stroke then stroke.ApplyStrokeMode=Enum.ApplyStrokeMode.Border;stroke.Color=colors.accent;stroke.Transparency=0.2;stroke.Thickness=1 end
    end
    refresh=function(visible)
        for _,p in ipairs(panels) do p.Visible=visible end
        if not visible then return end
        queue.Visible=queueOpen
        local p=state.infusionPrefs();local run=state.infusionRun
        local deps,entries,problem=data()
        local entry
        local focus=run and run.running and run.uid or p.uid
        for _,e in ipairs(entries or {}) do if e.uid==focus then entry=e;break end end
        if not entry then for _,e in ipairs(entries or {}) do if p.selected[e.uid] then entry=e;break end end end
        local plan,reason
        if deps and entries then plan,reason=state.infusionPlan(entry,p,deps.infusion.catalog,deps.balance) end
        local summary={total=0,complete=0,available=0}
        local queueReason
        if deps and entries then local _,_,why,counts=state.infusionQueue(entries,p,deps.infusion.catalog,deps.balance);summary=counts;queueReason=why
        else for _,on in pairs(p.selected) do if on then summary.total+=1 end end end
        local remaining=summary.total
        local finished=0;for _ in pairs(p.finished or {}) do finished+=1 end
        summary.total+=finished;summary.complete+=finished
        if queueOpen and not next(p.selected) then queueOpen=false;queue.Visible=false end
        text(back,tr("‹ Voltar","‹ Back","‹ Volver"));text(title,state.infusionText("INFUSÃO DE SOMBRAS"))
        text(subtitle,state.infusionText("Metas, bônus e travas de infusão."))
        for _,b in ipairs({back,change,maxButton,selection,clear,queuePrev,queueNext,queueAdd,queueClear}) do paintButton(b) end
        text(selection,tr("Sombras selecionadas: ","Selected shadows: ","Sombras seleccionadas: ")..remaining.." >")
        text(clear,tr("Limpar lista","Clear list","Limpiar lista"))
        text(queueAdd,tr("Adicionar","Add","Añadir"));text(queueClear,tr("Limpar","Clear","Limpiar"))
        if queueOpen then
            for _,f in ipairs(panels) do f.Visible=f==header or f==queue end
            text(title,tr("SOMBRAS SELECIONADAS","SELECTED SHADOWS","SOMBRAS SELECCIONADAS"))
            local chosen,seen={},{}
            for _,e in ipairs(entries or {}) do if p.selected[e.uid] then chosen[#chosen+1]=e;seen[e.uid]=true end end
            for uid,on in pairs(p.selected) do if on and not seen[uid] then chosen[#chosen+1]={uid=uid,missing=true} end end
            local pages=math.max(1,math.ceil(#chosen/8));queuePage=math.clamp(queuePage,1,pages)
            local count=math.min(8,math.max(0,#chosen-(queuePage-1)*8))
            queue.Size=UDim2.new(1,-3,0,86+count*112)
            text(queueTitle,summary.complete.." / "..summary.total..tr(" concluídas"," complete"," completadas"))
            text(queuePrev,"< "..queuePage.." / "..pages);text(queueNext,tr("Próxima >","Next >","Siguiente >"))
            for i,row in ipairs(queueCards) do
                local e=chosen[(queuePage-1)*8+i];row.frame.Visible=e~=nil
                if e then
                    row.art.Image=not e.missing and e.info.Image or ""
                    text(row.name,not e.missing and (e.info.Name or e.pet.Name) or e.uid)
                    local done=false
                    if not e.missing and deps then local _,why=state.infusionPlan(e,p,deps.infusion.catalog,deps.balance);done=why=="Todas as metas de infusão foram atingidas." end
                    text(row.status,(e.missing and tr("Indisponível","Unavailable","No disponible") or done and tr("Meta atingida","Target reached","Meta alcanzada") or run and run.running and run.uid==e.uid and tr("Infundindo","Infusing","Infundiendo") or tr("Aguardando","Waiting","Esperando")).." • "..e.uid:sub(-8))
                    local values={}
                    for _,key in ipairs(state.infusionKeys) do values[#values+1]=state.infusionText(key)..": "..(not e.missing and ((e.pet.Enchants or {})[key] or 0) or "—") end
                    text(row.levels,table.concat(values," • "));row.levels.TextSize=10
                end
            end
            return
        end
        text(cardTitle,tr("SOMBRA SELECIONADA","SELECTED SHADOW","SOMBRA SELECCIONADA"))
        portrait.Image=entry and entry.info.Image or ""
        text(name,entry and (entry.info.Name or entry.pet.Name) or tr("Escolher sombra","Choose shadow","Elegir sombra"))
        text(uidText,entry and ("ID: "..entry.uid:sub(-8)) or "")
        local grade="—"
        if entry then local ok,n=pcall(deps.extra.GetRankInfo,entry.pet.Rank);if ok then grade=n end end
        text(rank,grade);text(change,tr("+ Adicionar sombras","+ Add shadows","+ Añadir sombras"))
        text(autoTitle,tr("AUTOMAÇÃO","AUTOMATION","AUTOMATIZACIÓN"))
        text(autoDescription,tr("Segue até todas as metas ou faltarem recursos.","Continues until all targets or insufficient resources.","Continúa hasta las metas o faltar recursos."))
        local running=run and run.running or state.craftControl and state.craftControl.requested=="infusion"
        local canEdit=editable()
        for _,b in ipairs({change,maxButton,gemsButton,ticketButton}) do b.Active=canEdit;b.InfusionText.TextTransparency=canEdit and 0 or 0.45 end
        text(toggle,running and "ON" or "OFF");paintSwitch(toggle,running,true)
        text(goalsTitle,tr("METAS DE INFUSÃO","INFUSION TARGETS","METAS DE INFUSIÓN"))
        text(maxButton,tr("Auto Max • metas ativadas","Auto Max • enabled targets","Auto Max • metas activas"))
        for key,row in pairs(rows) do
            local info=deps and deps.infusion.catalog[key]
            local current=entry and tonumber((entry.pet.Enchants or {})[key]) or 0
            local target=p.targets[key] or 0
            for _,b in ipairs({row.target,row.enabled,row.lock}) do b.Active=canEdit;b.InfusionText.TextTransparency=canEdit and 0 or 0.45 end
            row.icon.Image=info and info.Icon or ""
            text(row.name,state.infusionText(key))
            text(row.current,tr("Atual: ","Current: ","Actual: ")..current..(info and info.Unique and " • Unique" or ""))
            text(row.target,tr("Meta: ","Target: ","Meta: ")..(target>0 and tostring(target) or "—").."  v")
            text(row.enabled,target>0 and "ON" or "OFF")
            local manual=p.locksByUid and entry and p.locksByUid[entry.uid] or entry and entry.uid==p.uid and p.locks or {}
            local locked=manual[key] or target>0 and current>=target
            text(row.lock,manual[key] and tr("DESTRAVAR","UNLOCK","DESBLOQUEAR") or locked and tr("META OK","TARGET OK","META OK") or tr("TRAVAR","LOCK","BLOQUEAR"))
            row.lock.Active=canEdit and (current>0 or manual[key]==true)
            row.lock.InfusionText.TextTransparency=row.lock.Active and 0 or 0.45
            paintButton(row.target)
            text(row.enabledTitle,tr("Ativo","Enabled","Activo"))
            text(row.lockTitle,manual[key] and tr("Travado","Locked","Bloqueado") or locked and tr("Meta OK","Target OK","Meta OK") or tr("Travar","Lock","Bloquear"))
            paintSwitch(row.enabled,target>0,canEdit)
            paintSwitch(row.lock,locked,row.lock.Active)
        end
        text(hint,state.infusionText("Somente 1 UNIQUE por sombra. Ao selecionar outro, o anterior é desativado.").."\n"..tr("Meta = nível desejado. Ativo = buscar bônus. Travar = preservar o atual. Auto Max ajusta as metas ativadas.","Target = desired level. Enabled = roll this bonus. Lock = preserve its current level. Auto Max adjusts enabled targets.","Meta = nivel deseado. Activo = buscar bono. Bloquear = conservar el actual. Auto Max ajusta las metas activas."))
        text(payTitle,tr("PAGAMENTO E CUSTO POR TENTATIVA","PAYMENT AND COST PER ATTEMPT","PAGO Y COSTO POR INTENTO"))
        text(gemsButton,"Gems + "..tr("materiais","materials","materiales"));text(ticketButton,"Tickets")
        for _,b in ipairs({gemsButton,ticketButton}) do
            local active=b==gemsButton and p.payment=="Gems" or b==ticketButton and p.payment=="Ticket"
            paintButton(b,active and colors.accent or nil,active and colors.bg or colors.text)
        end
        local price="—"
        if plan then
            local c,g=state.infusionCosts(plan,deps);local lines={}
            if p.payment=="Gems" then lines[#lines+1]="Gems: "..tostring(g) end
            for id,n in pairs(c) do local info=deps.items and deps.items[id];lines[#lines+1]=state.infusionText(info and info.Name or id)..": "..state.shadowCraftCount(id).." / "..n end
            price=table.concat(lines,"\n")
        end
        text(costs,price);text(statusTitle,tr("ATIVIDADE","ACTIVITY","ACTIVIDAD"))
        local uniqueProblem=deps and state.infusionUniqueProblem(p,deps.infusion.catalog)
        local message=problem or uniqueProblem or run and run.status or queueReason or "Infusão preparada."
        text(status,state.infusionText(message))
        local total,reached=0,0
        for _,key in ipairs(state.infusionKeys) do local goal=p.targets[key] or 0;if goal>0 then total+=1;if entry and ((entry.pet.Enchants or {})[key] or 0)>=goal then reached+=1 end end end
        text(attempts,tr("Tentativas confirmadas: ","Confirmed attempts: ","Intentos confirmados: ")..tostring(run and run.confirmed or 0).."  •  "..summary.complete.." / "..summary.total..tr(" sombras"," shadows"," sombras"))
        fill.Size=UDim2.fromScale(summary.total>0 and summary.complete/summary.total or 0,1)
        text(start,running and tr("PARAR INFUSÃO","STOP INFUSION","DETENER INFUSIÓN") or tr("INICIAR INFUSÃO","START INFUSION","INICIAR INFUSIÓN"))
        paintButton(start,running and Color3.fromRGB(110,30,40) or colors.accent,running and colors.text or colors.bg)
    end
    state.refreshInfusionView=function()
        if header.Visible then refresh(true) end
    end
    table.insert(cleanupCallbacks,state.infusionStop)
    return {refresh=refresh}
end
-- SHADOW CRAFT VIEW: hierarchical Craft landing and live shadow controls.
function state.installShadowCraftUI(H)
    local page,frame,labelAt,button,set,tr,outline=H.page,H.frame,H.labelAt,H.button,H.set,H.tr,H.outline
    local open=H.open
    local selectGroup,selectRankGroup,changeScope,refreshView
    local queueOpen,queuePage=false,1
    local statKeys={"Power","UltDamage","Speed","AtkSpeed"}
    local function fullM(entry)
        for _,key in ipairs(statKeys) do if ((entry.pet.Stats or {})[key] or 0)<13 then return false end end
        return true
    end
    local function atTargets(entry,prefs)
        local any=false
        for _,key in ipairs(statKeys) do
            local goal=prefs.targets[key] or 0
            if goal>0 then any=true;if ((entry.pet.Stats or {})[key] or 0)<goal then return false end end
        end
        return any
    end
    state.craftCompactTabs=true
    local originalSet=set
    set=function(node,value)
        originalSet(node,value)
        local foreground=node:FindFirstChild("ShadowActionText")
        if foreground then originalSet(foreground,value) end
    end
    local function pick(title,options,callback) choose(title,options,callback,"Craft") end
    local function returnCraft()
        state.newHubShow("Craft",false)
        if refreshView then refreshView(state.craft.category) end
    end
    -- The installed angular skin can add opaque children over a control's native
    -- text. Keep form text on an explicit foreground surface; inputs own their text.
    local function surface(node,input)
        local text
        local watched=setmetatable({},{__mode="k"})
        if not input then
            text=make("TextLabel",{Name="ShadowActionText",Position=UDim2.fromOffset(6,0),Size=UDim2.new(1,-12,1,0),
                Text=node.Text,BackgroundTransparency=1,TextColor3=colors.text,TextSize=11,TextWrapped=true,
                Font=Enum.Font.GothamMedium,ZIndex=node.ZIndex+4,Active=false},node)
        end
        local function redraw()
            if not node.Parent then return end
            node.TextTransparency=input and 0 or 1
            local border=node:FindFirstChildOfClass("UIStroke");if border then border.ApplyStrokeMode=Enum.ApplyStrokeMode.Border end
            if text then text.Text=node.Text;text.TextTransparency=0;text.ZIndex=node.ZIndex+4 end
            for _,child in ipairs(node:GetChildren()) do
                if child:IsA("GuiObject") and child~=text then
                    -- The angular skin hides the native background with NUI_CutHide.
                    -- Its CutFill is the button body and must stay beneath our text.
                    local visible=not input and child.Name=="NUI_CutFill"
                    if not watched[child] then
                        watched[child]=true
                        table.insert(connections,child:GetPropertyChangedSignal("Visible"):Connect(function()
                            if child.Visible~=visible then child.Visible=visible end
                        end))
                    end
                    child.Visible=visible
                    if visible then
                        child.ZIndex=node.ZIndex+2
                        if node.Name=="SelectShadows" or node.Name=="ClearSelection" then child.ImageColor3=node.BackgroundColor3 end
                    end
                end
            end
        end
        table.insert(connections,node:GetPropertyChangedSignal("Text"):Connect(redraw))
        table.insert(connections,node:GetPropertyChangedSignal("TextTransparency"):Connect(function()
            if node.TextTransparency~=(input and 0 or 1) then redraw() end
        end))
        table.insert(connections,node.ChildAdded:Connect(function(child) if child~=text then redraw() end end))
        redraw()
    end
    local function action(parent,name,y,callback)
        local b=button(parent,name,y,callback);surface(b,false)
        if name=="SelectShadows" or name=="ClearSelection" then
