                    if editable() then
                        for _,e in ipairs(group.list) do if not atTargets(e,prefs) then prefs.selected[e.uid]=true end end
                        prefs.detail=group.list[1] and group.list[1].uid;save()
                    end
                    returnCraft();return
                end
                if uid=="!next" then listGroup(key,offset+60);return end
                if uid=="!previous" then listGroup(key,math.max(1,offset-60));return end
                if editable() then
