    local function queueState(entries,prefs,run)
        local list,seen={},{}
        local reached=0
        for _,entry in ipairs(entries or {}) do
            if prefs.selected[entry.uid] then
                seen[entry.uid]=true;table.insert(list,entry)
                if atTargets(entry,prefs) then reached+=1 end
