        set(start,modeRunning and tr("Parar","Stop","Detener") or category=="RankUp" and tr("Iniciar evolução","Start Rank Up","Iniciar evolución") or tr("Iniciar Reroll","Start Reroll","Iniciar Reroll"))
        start.BackgroundColor3=modeRunning and Color3.fromRGB(110,30,40) or colors.accent
