        set(tier,"Tier: "..(current and state.shadowCraftText("tier:"..current.Name) or "—"))
        set(killsText,nextGoal and (tostring(kills).." / "..nextGoal..tr(" abates"," kills"," bajas")) or entry and not nextTier and "MAX" or "—")
        fill.Size=UDim2.fromScale(nextGoal and math.clamp(kills/math.max(1,nextGoal),0,1) or entry and not nextTier and 1 or 0,1)
