        set(H.subheading,category=="RankUp" and tr("Seis cópias por grupo; equipadas e protegidas são preservadas.","Six copies per group; equipped and protected shadows are preserved.","Seis copias por grupo; equipadas y protegidas se conservan.")
            or tr("Selecione suas shadows e configure a operação.","Select shadows and configure the operation.","Selecciona shadows y configura la operación."))
        local summary=problem or run and run.status or tr("Nenhuma operação em andamento.","No operation in progress.","Ninguna operación en curso.")
        if category=="Reroll" then
            progressTrack.Visible=true
            if not (run and run.running) and queueTotal>0 and reached==queueTotal then summary=tr("Concluído — todas as metas atingidas","Complete — all targets reached","Completado — todas las metas alcanzadas") end
            set(activityHeading,tr("ATIVIDADE","ACTIVITY","ACTIVIDAD"))
            set(activitySummary,summary)
            set(progressLabel,tr("Progresso: ","Progress: ","Progreso: ")..reached..tr(" de "," of "," de ")..queueTotal..tr(" concluídas"," complete"," completadas"))
            progressFill.Size=UDim2.fromScale(queueTotal>0 and math.min(1,reached/queueTotal) or 0,1)
            local attribute
