                if (prefs.targets[key] or 0)>((active.pet.Stats or {})[key] or 0) then attribute=key;break end
            end end
            local names={Power=tr("Poder","Power","Poder"),UltDamage=tr("Dano Ultimate","Ultimate Damage","Daño Ultimate"),Speed=tr("Velocidade","Speed","Velocidad"),AtkSpeed=tr("Veloc. de ataque","Attack Speed","Veloc. de ataque")}
            set(activityRows.Shadow.label,tr("Sombra atual","Current shadow","Sombra actual"));set(activityRows.Shadow.value,active and (active.info.Name or active.pet.Name) or "—")
            set(activityRows.Attribute.label,tr("Meta pendente","Pending target","Meta pendiente"));set(activityRows.Attribute.value,attribute and names[attribute] or "—")
            local currentGrade=attribute and deps and deps.stats.Info.Letters[(active.pet.Stats or {})[attribute] or 0]
            local targetGrade=attribute and deps and deps.stats.Info.Letters[prefs.targets[attribute]]
            set(activityRows.Grade.label,tr("Nota atual → meta","Current grade → target","Nota actual → meta"));set(activityRows.Grade.value,attribute and ((currentGrade and currentGrade.Name or "—").." → "..(targetGrade and targetGrade.Name or "—")) or "—")
            set(activityRows.Cores.label,"Shadow Cores");set(activityRows.Cores.value,tostring(state.shadowCraftCount("ShadowUpgrader")))
        elseif isRank then
            progressTrack.Visible=false
            if not (run and run.running) and not prefs.pending then
                summary=problem or missing or planProblem or tr("Pronto para fundir o próximo grupo.","Ready to fuse the next group.","Listo para fusionar el próximo grupo.")
