            set(activityHeading,tr("ATIVIDADE DO RANK UP","RANK UP ACTIVITY","ACTIVIDAD DE RANK UP"));set(activitySummary,summary)
            set(progressLabel,tr("Fusões confirmadas: ","Confirmed fusions: ","Fusiones confirmadas: ")..tostring(run and run.kind=="rank" and run.completed or 0))
            local info=deps and deps.pets[plan and plan.name or prefs.rankName or ""]
            set(activityRows.Shadow.label,tr("Sombra","Shadow","Sombra"));set(activityRows.Shadow.value,info and info.Name or prefs.rankScope=="all" and tr("Todas elegíveis","All eligible","Todas elegibles") or "—")
            set(activityRows.Attribute.label,tr("Próxima fusão","Next fusion","Próxima fusión"));set(activityRows.Attribute.value,plan and (sourceName.." → "..nextName) or "—")
            set(activityRows.Grade.label,tr("Rank de destino","Target rank","Rank de destino"));set(activityRows.Grade.value,targetName)
            set(activityRows.Cores.label,tr("Cópias do grupo","Group copies","Copias del grupo"));set(activityRows.Cores.value,plan and "6 / 6" or "—")
        end
        set(H.globalStatus,summary)
        local form=(category=="Reroll" or isRank) and not queueOpen
        formTitle.Visible=form;formDescription.Visible=form
        progressPanel.Visible=category=="Reroll" and not queueOpen
        resources.Visible=category=="Reroll" and not queueOpen
        set(formTitle,isRank and tr("👑 RANK UP","👑 RANK UP","👑 SUBIR RANK") or tr("↻ REROLL DE ATRIBUTOS","↻ STAT REROLL","↻ REROLL DE ATRIBUTOS"))
        set(formDescription,isRank and tr("Combine seis cópias e alcance o rank desejado.","Fuse six copies to reach your target rank.","Combina seis copias y alcanza el rank objetivo.") or tr("Defina a meta de cada um dos quatro atributos.","Set a target for each of the four attributes.","Define una meta para cada atributo."))
        if form then
            nav.Size=UDim2.new(1,-3,0,64);back.Size=UDim2.fromOffset(80,40);back.Position=UDim2.fromOffset(10,12)
            details.Size=UDim2.new(1,-3,0,164)
            portrait.Position=UDim2.fromOffset(12,41);portrait.Size=UDim2.fromOffset(64,94)
            detailName.Position=UDim2.fromOffset(90,34);detailRank.Position=UDim2.fromOffset(90,62)
            detailName.Size=UDim2.new(1,-160,0,28)
            grid.Visible=true;grid.Position=UDim2.fromOffset(90,82);grid.Size=UDim2.new(1,-102,0,72)
            target.Position=UDim2.fromOffset(12,10);target.Size=UDim2.new(1,-24,0,62)
            for _,f in ipairs({nav,details,selectionPanel,controls,rankPreview,goals,activity,progressPanel,resources,reviewPanel}) do
                local corner=f:FindFirstChildOfClass("UICorner");if corner then corner.CornerRadius=UDim.new(0,10) end
            end
        end
        set(progressHeading,tr("PROGRESSO DO REROLL","REROLL PROGRESS","PROGRESO DEL REROLL"))
        set(progressCount,reached.." / "..queueTotal)
        formFill.Size=UDim2.fromScale(queueTotal>0 and math.min(1,reached/queueTotal) or 0,1)
        set(counters.Queued.title,tr("Na fila","Queued","En cola"));set(counters.Queued.value,#chosen)
        set(counters.Completed.title,tr("Concluídas","Completed","Completadas"));set(counters.Completed.value,reached)
        set(counters.Remaining.title,tr("Restantes","Remaining","Restantes"));set(counters.Remaining.value,math.max(0,queueTotal-reached))
        set(resourcesHeading,tr("RECURSOS DISPONÍVEIS","AVAILABLE RESOURCES","RECURSOS DISPONIBLES"))
        set(resourcesLabel,state.shadowCraftText("Shadow Cores"));set(resourcesAmount,state.shadowCraftCount("ShadowUpgrader"))
        if category=="Reroll" then
            -- The dedicated progress/resource cards replace repeated activity fields.
            progressLabel.Visible=false;progressTrack.Visible=false
            activityRows.Cores.label.Visible=false;activityRows.Cores.value.Visible=false
            activity.Size=UDim2.new(1,-3,0,304);start.Position=UDim2.fromOffset(12,246);start.Size=UDim2.new(1,-24,0,44)
        elseif isRank then
            progressLabel.Visible=true;activityRows.Cores.label.Visible=true;activityRows.Cores.value.Visible=true
            activity.Size=UDim2.new(1,-3,0,350);start.Position=UDim2.fromOffset(12,290);start.Size=UDim2.new(1,-24,0,44)
        end
    end
    refreshView=result.refresh
    state.shadowCraftRefresh=result.refresh
    task.spawn(function()
        while alive and page.Parent do
            if state.recurringQuests then state.recurringQuests.craftPaused=nil end
            if state.craftControllerStep then
                local ok,problem=pcall(state.craftControllerStep,workspace:GetServerTimeNow())
                if not ok then state.craftControl.requested=nil;state.craftControl.status=tostring(problem) end
            end
            local ok,problem=pcall(state.shadowCraftStep,workspace:GetServerTimeNow())
            if not ok then state.shadowCraftStop();state.shadowRuntime=state.shadowRuntime or {};state.shadowRuntime.status=tostring(problem) end
            local infOK,infProblem=pcall(state.infusionStep,workspace:GetServerTimeNow())
            if not infOK then state.infusionStop();state.infusionRun=state.infusionRun or {};state.infusionRun.status=tostring(infProblem) end
            if state.craftPersistenceStep then state.craftPersistenceStep() end
            if page.Visible then result.refresh(state.craft.category) end
            task.wait(0.5)
        end
    end)
    table.insert(cleanupCallbacks,state.shadowCraftStop)
    return result
end
-- Aba Craft da interface nova: receitas e trocas.
-- Usa os catalogos nativos e uma unica fila de operacoes salva e confirmada.
-- Recebe do nucleo (new-hub-view.lua): hub, CYAN, ROW, DIFF_ON, languageHooks, periodic, paint.
state.hubParts.craft = function(H)
    local hub, CYAN, ROW, DIFF_ON, languageHooks, periodic, paint = H.hub, H.CYAN, H.ROW, H.DIFF_ON, H.languageHooks, H.periodic, H.paint
        local rows, catalog, lookup, dependencies = {}, {}, {}, nil
        local rowConnections={}
        local nextLoad,nextSend,lastSignature = 0,0,""
        local lastRecipe=0
        local paintCards, refresh, shadowUI
        local preferenceWrites = 0
        local page=make("ScrollingFrame",{Name="Craft",Size=UDim2.fromScale(1,1),BackgroundTransparency=1,
            BorderSizePixel=0,Visible=false,CanvasSize=UDim2.new(),AutomaticCanvasSize=Enum.AutomaticSize.Y,
            ScrollBarThickness=3,ScrollBarImageColor3=CYAN,ScrollingDirection=Enum.ScrollingDirection.Y},hub.pages)
        make("UIListLayout",{Padding=UDim.new(0,10),SortOrder=Enum.SortOrder.LayoutOrder},page)
        make("UIPadding",{PaddingLeft=UDim.new(0,3),PaddingRight=UDim.new(0,8),PaddingBottom=UDim.new(0,14)},page)
        local tab=hub.nav.Tab_DungeonMain:Clone()
        tab.Name,tab.LayoutOrder="Tab_Craft",3
        tab:SetAttribute("Target","Craft");tab.Label.Text="Craft";tab.TextLabel.Text="⚒"
        for _,other in ipairs(hub.nav:GetChildren()) do
            if other:IsA("TextButton") and other.LayoutOrder>=3 then other.LayoutOrder+=1 end
        end
        tab.Parent=hub.nav
        hub.nav.UIGridLayout.CellSize=UDim2.new(1/6,-5,1,-8)
        for _,other in ipairs(hub.nav:GetChildren()) do
            if other:IsA("TextButton") and other:FindFirstChild("Label") then
                other.Label.TextScaled=true
                make("UITextSizeConstraint",{MinTextSize=7,MaxTextSize=10},other.Label)
            end
        end
        local function tr(pt,en,es) return uiState.language=="PT" and pt or uiState.language=="ES" and es or en end
        local function set(node,value) state.setLocalizedText(node,tostring(value)) end
        local function outline(node)
            make("UICorner",{CornerRadius=UDim.new(0,4)},node)
            make("UIStroke",{Color=CYAN,Transparency=0.5},node)
        end
        local function frame(name,height,order,parent)
            local f=make("Frame",{Name=name,Size=UDim2.new(1,-3,0,height),LayoutOrder=order,
                BackgroundColor3=ROW,BorderSizePixel=0},parent or page)
            outline(f);return f
        end
        local function labelAt(parent,name,y,height,bold)
            return make("TextLabel",{Name=name,Position=UDim2.fromOffset(12,y),Size=UDim2.new(1,-24,0,height),
                BackgroundTransparency=1,Text="",TextColor3=bold and colors.text or colors.muted,
                Font=bold and Enum.Font.GothamBold or Enum.Font.Gotham,TextSize=bold and 12 or 10,
                TextWrapped=true,TextXAlignment=Enum.TextXAlignment.Left,TextYAlignment=Enum.TextYAlignment.Center},parent)
        end
        local function button(parent,name,y,callback)
            local b=make("TextButton",{Name=name,Position=UDim2.fromOffset(12,y),Size=UDim2.new(1,-24,0,34),
                Text="",TextColor3=colors.text,TextSize=11,Font=Enum.Font.GothamMedium,
                BackgroundColor3=colors.bg,AutoButtonColor=false},parent)
            b.TextWrapped=true
            outline(b);connectUI(b,callback);return b
        end
        local hero=frame("CraftHeader",88,1)
        local heading=labelAt(hero,"Heading",8,26,true)
        local subheading=labelAt(hero,"Subheading",37,40,false)
        local menu=frame("Submenus",444,2)
        local menuButtons={}
        for i,group in ipairs({"Dust","Cores","Keys","Tokens","Gems"}) do
            local b=button(menu,group,10+(i-1)*86,function() state.craft.category=group paintCards() refresh() lastSignature="" save() end)
            b.Size=UDim2.new(1,-24,0,76)
            local title=labelAt(b,"Title",8,23,true)
            title.Position=UDim2.fromOffset(100,8);title.Size=UDim2.new(1,-134,0,23)
            local description=labelAt(b,"Description",32,36,false)
            description.Position=UDim2.fromOffset(100,32);description.Size=UDim2.new(1,-134,0,36)
            for n=1,3 do
                make("ImageLabel",{Name="Asset"..n,Size=UDim2.fromOffset(32,38),Position=UDim2.fromOffset(8+(n-1)*23,19),
                    BackgroundTransparency=1,Image="",ScaleType=Enum.ScaleType.Fit,ZIndex=n+1},b)
            end
            local arrow=labelAt(b,"Arrow",22,28,true)
            arrow.Position=UDim2.new(1,-28,0,22);arrow.Size=UDim2.fromOffset(18,28);arrow.TextColor3=CYAN;set(arrow,">")
            menuButtons[group]=b
        end
        local tokenTabs=frame("TokenFamilies",42,3)
        local tokenFamilyButtons={}
        for i,family in ipairs({"Gacha","Upgrade"}) do
            local b=button(tokenTabs,family,5,function() state.craft.tokenFamily=family paintCards() refresh() lastSignature="" save() end)
            b.Position=UDim2.new((i-1)/2,6,0,5);b.Size=UDim2.new(0.5,-12,0,32)
            set(b,family=="Gacha" and "Gacha Tokens" or "Upgrade Tokens")
            tokenFamilyButtons[family]=b
        end
        local toolbar=frame("Toolbar",126,9)
        local back=button(toolbar,"Back",8,function()
            local category=state.craft.category
            state.craft.category=shadowUI and ((category=="Dust" or category=="Cores") and "Materials" or "Recipes") or "Menu"
            paintCards();refresh();lastSignature="";save()
        end)
        back.Size=UDim2.fromOffset(78,30)
        local batchLabel=labelAt(toolbar,"BatchLabel",46,22,true)
        local batchButtons={}
        for i,mode in ipairs({"1x","10x","100x","1000x","MAX"}) do
            local b=button(toolbar,"Batch_"..mode,78,function() state.craft.batch=mode refresh() save() end)
            b.Position=UDim2.new((i-1)/4,8,0,78);b.Size=UDim2.new(0.25,-14,0,30)
            set(b,mode)
            batchButtons[mode]=b
        end
        local gemSelector=frame("GemSelector",64,10)
        local gemChoice=button(gemSelector,"ChooseGem",12,function()
            if not dependencies then return end
            local options={}
            for _,entry in ipairs(catalog) do
                if entry.kind=="Gem" then options[#options+1]={name=entry.name,id=entry.id,image=entry.image} end
            end
            choose(tr("Escolher gema","Choose gem","Elegir gema"),options,function(value)
                local chosen=type(value)=="table" and value.value or value
                if not lookup["Gem:"..tostring(chosen)] then return end
                -- Switching the visible recipe also stops hidden gem orders.
                for key,setting in pairs(state.craft.items) do
                    if key:sub(1,4)=="Gem:" and key~="Gem:"..chosen then setting.enabled=false end
                end
                state.craft.gemRecipe=chosen;save();paintCards();refresh()
                state.newHubShow("Craft",false)
            end)
        end)
        gemChoice.Size=UDim2.new(1,-24,0,40)
        gemChoice.TextXAlignment=Enum.TextXAlignment.Left
        make("UIPadding",{PaddingLeft=UDim.new(0,46),PaddingRight=UDim.new(0,10)},gemChoice)
        local gemPortrait=make("ImageLabel",{Name="GemPortrait",BackgroundTransparency=1,
            Position=UDim2.fromOffset(20,17),Size=UDim2.fromOffset(30,30),Image="",
            ScaleType=Enum.ScaleType.Fit,ZIndex=gemChoice.ZIndex+1},gemSelector)
        local globalStatus
        local tokenPanels={}
        for i,family in ipairs({"Gacha","Upgrade"}) do
            local panel=frame("TokenSelector_"..family,146,3+i)
            local title=labelAt(panel,"Title",8,24,true)
            local function selectSide(side)
                if not dependencies then return end
                local prefix="Token:"..family..":"
                if state.craft.pending and state.craft.pending.key:sub(1,#prefix)==prefix then return end
                for key in pairs(state.craft.unconfirmed) do if key:sub(1,#prefix)==prefix then return end end
                local options={}
                local choices=state.craftTokenOptions(dependencies,family,side)
                if #choices==0 then set(globalStatus,tr("Tokens indisponíveis ou sem máquinas elegíveis.","Tokens unavailable or no eligible machines.","Tokens no disponibles o sin máquinas elegibles.")) return end
                for _,option in ipairs(choices) do
                    local entry=option
                    options[#options+1]={name=entry.name,id=entry.id}
                end
                choose(tr("Selecionar token","Select token","Seleccionar token"),options,function(value)
                    local chosen=type(value)=="table" and value.value or value
                    if state.craft.tokens[family][side]==chosen then return end
                    -- Changing a pair never destroys an outstanding order/receipt.
                    for key,setting in pairs(state.craft.items) do
                        if key:sub(1,#prefix)==prefix then setting.enabled=false end
                    end
                    state.craft.tokens[family][side]=chosen
                    save();lastSignature=""
                    state.newHubShow("Craft",false)
                end)
            end
            panel.Size=UDim2.new(1,-3,0,252)
            local sides={}
            for i,side in ipairs({"source","destination"}) do
                local tile=frame(side=="source" and "SourceTile" or "DestinationTile",154,i,panel)
                tile.Position=UDim2.new((i-1)*0.5,12,0,42);tile.Size=UDim2.new(0.5,-24,0,154)
                local caption=labelAt(tile,"Caption",4,20,false)
                local art=make("ImageLabel",{Name="Asset",Size=UDim2.fromOffset(42,42),Position=UDim2.fromOffset(10,30),
                    Image="",BackgroundTransparency=1,ScaleType=Enum.ScaleType.Fit},tile)
                local name=labelAt(tile,"ItemName",27,46,true)
                name.Position=UDim2.fromOffset(58,27);name.Size=UDim2.new(1,-68,0,46);name.TextSize=11
                local stock=labelAt(tile,"Owned",78,26,true);stock.TextColor3=CYAN
                local change=button(tile,"Change",113,function() selectSide(side) end)
                change.Size=UDim2.new(1,-20,0,28);change.Position=UDim2.fromOffset(10,113)
                sides[side]={tile=tile,caption=caption,art=art,name=name,stock=stock,change=change}
            end
            local arrow=labelAt(panel,"Direction",92,32,true)
            arrow.Position=UDim2.new(0.5,-12,0,92);arrow.Size=UDim2.fromOffset(24,32);arrow.TextColor3=CYAN;set(arrow,"->")
            local ratio=labelAt(panel,"Ratio",207,34,true)
            ratio.TextSize=11;ratio.TextXAlignment=Enum.TextXAlignment.Center
            tokenPanels[family]={panel=panel,title=title,sides=sides,ratio=ratio}

        end
        local activity=frame("CraftActivity",88,10000)
        local activityTitle=labelAt(activity,"Title",8,24,true)
        globalStatus=labelAt(activity,"CraftStatus",34,46,false)
        if type(state.installShadowCraftUI)=="function" then
            shadowUI=state.installShadowCraftUI({page=page,frame=frame,labelAt=labelAt,button=button,set=set,tr=tr,outline=outline,
                heading=heading,subheading=subheading,globalStatus=globalStatus,activityTitle=activityTitle,menuButtons=menuButtons,
                open=function(category)
                    state.craft.category=category;paintCards();refresh();lastSignature="";save()
                end})
        end
        local function count(id)
            local value=clientData.Get("Inventory","Items",id)
            local n=type(value)=="table" and tonumber(value.Amount) or tonumber(value)
            return n and n==n and n>=0 and n<math.huge and n or 0
        end
        local function itemName(id)
            local info=dependencies.items[id] or dependencies.basic[id] or {}
            return info.Name or id
        end
        local function image(id)
            local info=dependencies.items[id] or {}
            local basic=dependencies.basic[id] or {}
            local result=info.Image or info.Icon or basic.Image or basic.Icon
            if type(result)=="string" and result~="" then return result end
            if dependencies.gacha and type(dependencies.gacha.TokenImage)=="function" then
                local ok,asset=pcall(dependencies.gacha.TokenImage,id)
                if ok and type(asset)=="string" and asset~="" then return asset end
            end
            if dependencies.upgrade and type(dependencies.upgrade.ItemImage)=="function" then
                local ok,asset=pcall(dependencies.upgrade.ItemImage,id)
                if ok and type(asset)=="string" then return asset end
            end
            return ""
        end
        local function settings(recipe)
            local value=state.craft.items[recipe.key]
            if not value then value={enabled=false,target=0,continuous=true};state.craft.items[recipe.key]=value end
            return value
        end
        local function isPending(key)
            return state.craft.pending and state.craft.pending.key==key or state.craft.unconfirmed[key]
        end
        local function discover()
            local scripts=player:FindFirstChild("PlayerScripts")
            local ui=scripts and scripts:FindFirstChild("NewUI",true)
            local screens=assert(ui,"Native interface unavailable").Screens
            dependencies={shop=require(screens.ItemShop.Data),items=require(storage.Indexer.ItemsInfo),
                basic=require(storage.Indexer.BasicInfos).CommonInfos,recipes=require(storage.Indexer.Recipes),
                extra=require(shared.ExtraFunctions),release=require(shared.Release),
                maxCraftRepeats=require(storage.Indexer.BalanceInfo).MaxCraftRepeats}
            -- One optional token family must not prevent Keys/Dust from loading.
            local ok,g=pcall(require,screens.Gacha.Shared)
            if ok then dependencies.gacha=g end
            local ok2,u=pcall(require,screens.Upgrader.Shared)
            if ok2 then dependencies.upgrade=u end
        end
        local function rebuildCatalog()
            local entries=state.discoverCraftCatalog(dependencies,state.craft.tokens,clientData)
            catalog,lookup=entries,{}
            for _,entry in ipairs(catalog) do lookup[entry.key]=entry settings(entry) end
            if not lookup["Gem:"..tostring(state.craft.gemRecipe)] then
                state.craft.gemRecipe=nil
                for _,entry in ipairs(catalog) do
                    if entry.kind=="Gem" then state.craft.gemRecipe=entry.id break end
                end
            end
        end
        local preferenceChanges, preferencesDirty = {}, false
        local function toggleSetting(setting, toggle)
            if not preferenceChanges[setting] then
                preferenceChanges[setting] = {enabled = setting.enabled, continuous = setting.continuous, needsReview = setting.needsReview}
            end
            setting.enabled = not setting.enabled
            if setting.enabled then setting.needsReview = nil end
            if setting.enabled and setting.target == 0 then setting.continuous = true end
            paint(toggle, setting.enabled)
            preferencesDirty = true
            if preferenceWrites > 0 then return end
            preferenceWrites = 1
            task.spawn(function()
                while preferencesDirty and alive do
                    preferencesDirty = false
                    local snapshot = {}
                    for value in pairs(preferenceChanges) do
                        snapshot[value] = {enabled = value.enabled, continuous = value.continuous, needsReview = value.needsReview}
                    end
                    if save() then
                        for value, committed in pairs(snapshot) do preferenceChanges[value] = committed end
                    else
                        for value, committed in pairs(preferenceChanges) do
                            value.enabled, value.continuous, value.needsReview = committed.enabled, committed.continuous, committed.needsReview
                        end
                        for key, row in pairs(rows) do paint(row.toggle, state.craft.items[key].enabled) end
                        set(globalStatus,tr("Falha ao salvar. Tente novamente.","Could not save. Please retry.","Error al guardar. Intenta otra vez."))
                        preferencesDirty = false
                    end
                end
                table.clear(preferenceChanges)
                preferenceWrites = 0
            end)
        end
        paintCards = function()
            for _,connection in ipairs(rowConnections) do connection:Disconnect() end
            table.clear(rowConnections)
            for _,row in pairs(rows) do row.card:Destroy() end
            table.clear(rows)
            for index,recipe in ipairs(catalog) do
                if recipe.category~=state.craft.category or recipe.kind=="Gem" and recipe.id~=state.craft.gemRecipe or recipe.kind=="Token" and recipe.family~=state.craft.tokenFamily then continue end
                local setting=settings(recipe)
                local card=frame("Recipe_"..index,322,20+index)
                local name=labelAt(card,"Name",8,46,true)
                set(name,state.craftRecipeLabel(recipe,itemName))
                make("ImageLabel",{Name="ResultIcon",Size=UDim2.fromOffset(36,36),Position=UDim2.fromOffset(recipe.source and 78 or 12,58),
                    BackgroundTransparency=1,Image=recipe.image or image(recipe.output),ScaleType=Enum.ScaleType.Fit},card)
                if recipe.source then
                    make("ImageLabel",{Name="SourceIcon",Size=UDim2.fromOffset(36,36),Position=UDim2.fromOffset(12,58),
                        BackgroundTransparency=1,Image=image(recipe.source),ScaleType=Enum.ScaleType.Fit},card)
                    local arrow=labelAt(card,"Direction",61,28,true)
                    arrow.Position=UDim2.fromOffset(50,61);arrow.Size=UDim2.fromOffset(26,28)
                    arrow.TextColor3=CYAN;set(arrow,"->")
                end
                local result=labelAt(card,"ResultName",58,38,false)
                result.Position=UDim2.fromOffset(recipe.source and 126 or 60,58)
                result.Size=UDim2.new(1,recipe.source and -138 or -72,0,38)
                set(result,recipe.name)
                local materials=labelAt(card,"Materials",106,54,false)
                materials.TextYAlignment=Enum.TextYAlignment.Top
                local auto=labelAt(card,"Auto",163,24,true)
                auto.Size=UDim2.new(1,-96,0,24)
                local toggle=make("TextButton",{Name="Toggle",Text="",Size=UDim2.fromOffset(42,22),
                    Position=UDim2.new(1,-56,0,163),BorderSizePixel=0,AutoButtonColor=false},card)
                make("UICorner",{CornerRadius=UDim.new(1,0)},toggle)
                make("Frame",{Name="Knob",Size=UDim2.fromOffset(18,18),AnchorPoint=Vector2.new(0,0.5),
                    BackgroundColor3=Color3.new(1,1,1),BorderSizePixel=0},toggle)
                make("UICorner",{CornerRadius=UDim.new(1,0)},toggle.Knob)
                connectUI(toggle,function() toggleSetting(setting, toggle) end,nil,rowConnections)
                local quantityLabel=labelAt(card,"QuantityLabel",194,20,false)
                local field=make("TextBox",{Name="Quantity",Text=tostring(setting.target),ClearTextOnFocus=false,
                    Size=UDim2.new(1,-24,0,30),Position=UDim2.fromOffset(12,217),BackgroundColor3=colors.bg,
                    TextColor3=CYAN,TextSize=13,Font=Enum.Font.GothamBold},card)
                outline(field)
                connectUI(field,function()
                    local n=tonumber(field.Text)
                    if n and n==n and n>=0 and n<=1000000000 and not isPending(recipe.key) then setting.target=math.floor(n) setting.continuous=setting.target==0 save() end
                    field.Text=tostring(setting.target)
                end,field.FocusLost,rowConnections)
                local stock=labelAt(card,"Stock",251,23,true)
                stock.TextColor3=CYAN
                local summary
                if recipe.kind=="Token" then
                    summary=labelAt(card,"CostSummary",278,44,false)
                    card.Size=UDim2.new(1,-3,0,372)
                end
                local status=labelAt(card,"Status",recipe.kind=="Token" and 327 or 277,35,false)
                if recipe.kind=="Gem" then
                    card.Size=UDim2.new(1,-3,0,382)
                    materials.Size=UDim2.new(1,-24,0,108);materials.TextSize=11
                    for _,node in ipairs({auto,toggle,quantityLabel,field,stock,status}) do
                        node.Position=node.Position+UDim2.fromOffset(0,60)
                    end
                end
                rows[recipe.key]={card=card,materials=materials,auto=auto,toggle=toggle,label=quantityLabel,
                    field=field,stock=stock,status=status,summary=summary}
            end
        end
        local function costs(recipe)
            if recipe.kind~="Key" then return recipe.costs end
            local native=recipe.native
            local materials=native.Items
            local ok,talent=pcall(dependencies.extra.FindTalent,player,"KeyMaster")
            if ok and talent~=false then materials=native.TalentCraft or materials end
            return type(materials)=="table" and materials or {}
        end
        local function blocked(recipe)
            local resources=table.clone(costs(recipe));resources[recipe.output]=true
            local pending=state.craft.shadows and state.craft.shadows.pending
            if pending and state.craftTouches(resources,state.craftReceiptResources(pending)) then
                return tr("Aguardando Rank Up/Reroll terminar.","Waiting for Rank Up/Reroll to finish.","Esperando a que termine Rank Up/Reroll.")
            end
            if state.craftBuyBusy and state.craftBuyBusy(resources) then return tr("Aguardando Auto Buy: recursos compartilhados.","Waiting for Auto Buy: shared resources.","Esperando Auto Buy: recursos compartidos.") end
            if state.craftInfusionBlocked(recipe,costs(recipe)) then
                return tr("Aguardando Infusão: recursos compartilhados.","Waiting for Infusion: shared resources.","Esperando Infusión: recursos compartidos.")
            end
            if recipe.release and not dependencies.release.IsOpen(recipe.release) then
                return tr("Ainda indisponível no jogo.","Not released in game yet.","Aún no disponible en el juego.")
            end
            if recipe.kind=="Shop" then
                local locked,reason=dependencies.shop.Lock("ExchangeShop",recipe.item)
                if locked then return tostring(reason or locked) end
            elseif recipe.kind=="Key" or recipe.kind=="Gem" then
                local requirement=recipe.native.Requires
                if requirement then
                    if type(requirement.Stat)~="string" or not tonumber(requirement.Min) then
                        return tr("Requisito não reconhecido.","Unrecognized requirement.","Requisito no reconocido.")
                    end
                    local progress=tonumber(clientData.Get("GeneralStats",requirement.Stat)) or 0
                    if progress<requirement.Min then return requirement.Text or (requirement.Stat.." "..progress.."/"..requirement.Min) end
                end
                if (recipe.native.OnlyOne or recipe.native.Unique) and clientData.Get("Uniques","Crafts",recipe.id) then
                    return tr("Receita única já fabricada.","Unique recipe already crafted.","Receta única ya fabricada.")
                end
            end
        end
        local function available(recipe)
            local maximum=math.huge
            local lines={}
            for id,need in pairs(costs(recipe)) do
                if type(need)~="number" or need~=need or need<0 or need==math.huge then return 0,"Unsupported ingredient" end
                if need==0 then continue end
                local owned=count(id)
                maximum=math.min(maximum,math.floor(owned/need))
                lines[#lines+1]=itemName(id)..": "..owned.." / "..need
            end
            table.sort(lines)
            return maximum,table.concat(lines,recipe.kind=="Gem" and "\n" or " · ")
        end
        refresh = function()
            set(heading,"CRAFT")
            set(subheading,tr("Receitas, materiais e trocas. Escolha um submenu.","Recipes, materials and exchanges. Choose a submenu.","Recetas, materiales e intercambios. Elige un submenú."))
