            set(menuButtons.Cores.Description,tr("Converta cores entre raridades.","Convert cores between rarities.","Convierte núcleos entre rarezas."))
            set(menuButtons.Keys.Description,tr("Receitas e requisitos nativos.","Native recipes and requirements.","Recetas y requisitos nativos."))
            set(menuButtons.Tokens.Description,tr("Escolha tokens de origem e destino.","Choose source and destination tokens.","Elige tokens de origen y destino."))
            if dependencies then
                local representatives={Dust={"EnchCommon","EnchRare","EnchMythical"},
                    Cores={"UpgRare","UpgLegendary","UpgMonarch"},Gems={"SmallWhiteGem","LargeRedGem","LargePurpleGem"},Keys={"SoloKey","EclipseSigilHard"},Tokens={"GenericToken","ClansToken"}}
                for group,ids in pairs(representatives) do
