                        asset.Visible=id~=nil
                        asset.Image=group=="Gems" and recipe and recipe.Icon or id and (image(id)~="" and image(id) or recipe and recipe.Icon or "") or ""
                    end
                end
            end
            tokenTabs.Visible=category=="Tokens"
            for family,b in pairs(tokenFamilyButtons) do
                local on=family==state.craft.tokenFamily
                b.BackgroundColor3=on and DIFF_ON or colors.bg
                b.UIStroke.Transparency=on and 0.1 or 0.5
            end
            toolbar.LayoutOrder=category=="Tokens" and 9 or 3
            set(back,tr("‹ Voltar","‹ Back","‹ Volver"))
            set(batchLabel,category=="Keys" and tr("Craft nativo: 1 unidade por confirmação","Native Craft: 1 unit per confirmation","Craft nativo: 1 unidad por confirmación")
                or tr("Lote por operação","Batch per operation","Lote por operación"))
            local batchChoices=state.craftBatchChoices(category)
            local selectedBatch=state.craftBatchMode(category,state.craft.batch)
            for _,b in pairs(batchButtons) do b.Visible=false end
            for i,mode in ipairs(batchChoices) do
                local b=batchButtons[mode]
                set(b,category=="Gems" and mode=="MAX" and tr("Fabricar máximo","Craft max","Fabricar máximo") or mode)
                b.Visible=true
                b.Position=UDim2.new((i-1)/#batchChoices,8,0,78)
                b.Size=UDim2.new(1/#batchChoices,-14,0,30)
                b.TextColor3=mode==selectedBatch and Color3.new(1,1,1) or colors.text
                b.BackgroundColor3=mode==selectedBatch and DIFF_ON or colors.bg
                b.UIStroke.Transparency=mode==selectedBatch and 0.1 or 0.5
            end
            for family,control in pairs(tokenPanels) do
                control.panel.Visible=category=="Tokens" and family==state.craft.tokenFamily
                set(control.title,tr("ESCOLHA SUA TROCA","SELECT YOUR EXCHANGE","ELIGE TU INTERCAMBIO"))
                local values=state.craft.tokens[family]
                local resolved={}
                for _,side in ipairs({"source","destination"}) do
                    local tile=control.sides[side]
                    set(tile.caption,side=="source" and tr("ORIGEM","SOURCE","ORIGEN") or tr("DESTINO","DESTINATION","DESTINO"))
                    set(tile.change,tr("Trocar","Change","Cambiar"))
                    local chosen
                    if dependencies then
                        for _,entry in ipairs(state.craftTokenOptions(dependencies,family,side)) do
                            if entry.id==values[side] then chosen=entry break end
                        end
                    end
                    resolved[side]=chosen
                    set(tile.name,chosen and itemName(chosen.currency) or tr("Selecionar","Select","Seleccionar"))
                    set(tile.stock,tr("Possui: ","Owned: ","Tienes: ")..(chosen and tostring(count(chosen.currency)) or "--"))
                    tile.art.Image=chosen and image(chosen.currency) or ""
                    tile.art.Visible=chosen~=nil
                end
                local from,to=resolved.source,resolved.destination
                if from and to and from.currency~=to.currency then
                    local rate=family=="Gacha" and dependencies.gacha.CONFIG.ExchangeRate or dependencies.upgrade.EXCHANGE_RATE
                    set(control.ratio,tostring(rate).." "..itemName(from.currency).." -> 1 "..itemName(to.currency))
                else set(control.ratio,tr("Selecione dois tokens diferentes.","Select two different tokens.","Selecciona dos tokens distintos.")) end
            end
            set(activityTitle,tr("ATIVIDADE DO CRAFT","CRAFT ACTIVITY","ACTIVIDAD DE CRAFT"))
            local activeOrders=0
            for _,setting in pairs(state.craft.items) do if state.craftOrderActive(setting) then activeOrders+=1 end end
            set(globalStatus,(activeOrders>0 and (tr("Pedidos ativos: ","Active orders: ","Pedidos activos: ")..activeOrders)
                or tr("Nenhum pedido ativo.","No active orders.","Ningún pedido activo.")).."\n"..
                tr("As quantidades são adicionais ao estoque atual.","Quantities are additional to current inventory.","Las cantidades son adicionales al inventario actual."))
            for key,row in pairs(rows) do
                local recipe=lookup[key]
                local setting=settings(recipe)
                local amount,materials=available(recipe)
                if recipe.source then
                    local cost=costs(recipe)[recipe.source]
                    set(row.materials,tostring(cost or "?").." "..itemName(recipe.source).." -> "..recipe.give.." "..itemName(recipe.output).."\n"..materials)
                else set(row.materials,materials) end
                set(row.auto,tr("Automatizar","Automate","Automatizar"))
                set(row.label,tr("Quantidade a produzir / 0 = contínuo","Quantity to produce / 0 = continuous","Cantidad a producir / 0 = continuo"))
                set(row.stock,tr("No inventário: ","In inventory: ","En inventario: ")..count(recipe.output))
                if row.summary and setting.continuous then
                    set(row.summary,tr("Modo contínuo: custo calculado por lote.","Continuous mode: cost calculated per batch.","Modo continuo: coste calculado por lote."))
                elseif row.summary then
                    local rate=costs(recipe)[recipe.source] or 0
                    set(row.summary,tr("Custo restante: ","Remaining cost: ","Coste pendiente: ")..(setting.target*rate).." "..itemName(recipe.source)
                        .."\n"..tr("Estoque esperado: ","Expected inventory: ","Inventario esperado: ")..(count(recipe.output)+setting.target).." "..itemName(recipe.output))
                end
                if not row.field:IsFocused() then row.field.Text=tostring(setting.target) end
                if row.toggle:GetAttribute("Enabled")~=setting.enabled then paint(row.toggle,setting.enabled) end
                local reason=recipe.problem or blocked(recipe)
                if state.panic then reason=tr("Pausado pelo pânico.","Paused by panic.","Pausado por pánico.")
                elseif isPending(key) then reason=tr("Aguardando confirmação. Pedido preservado.","Awaiting confirmation. Order preserved.","Esperando confirmación. Pedido conservado.")
                elseif setting.needsReview then reason=tr("Recursos debitados. Revise a quantidade antes de reativar.","Resources debited. Review the quantity before enabling again.","Recursos descontados. Revisa la cantidad antes de reactivar.")
                elseif not setting.enabled then reason=tr("Desligado.","Off.","Desactivado.")
                elseif setting.target==0 and not setting.continuous then reason=tr("Pedido concluído.","Order complete.","Pedido completado.")
                elseif recipe.kind=="Gem" and amount<1 and not reason then
                    local missing={}
                    for id,need in pairs(costs(recipe)) do
                        if count(id)<need then missing[#missing+1]=itemName(id).." "..count(id).."/"..need end
                    end
                    table.sort(missing)
                    reason=tr("Falta: ","Missing: ","Falta: ")..table.concat(missing," · ")
                elseif amount<1 and not reason then reason=tr("Materiais insuficientes. Veja os custos acima.","Insufficient materials. See costs above.","Materiales insuficientes. Consulta los costes.") end
                set(row.status,reason or (setting.continuous and tr("Contínuo: produz enquanto houver materiais e espaço.","Continuous: produces while materials and space are available.","Continuo: produce mientras haya materiales y espacio.")
                    or tr("Pronto para produzir.","Ready to produce.","Listo para producir.")))
            end
            if shadowUI then shadowUI.refresh(category) end
            activity.Size=UDim2.new(1,-3,0,category=="Gems" and 122 or 88)
            globalStatus.TextSize=category=="Gems" and 12 or 10
            globalStatus.Size=UDim2.new(1,-24,0,category=="Gems" and 76 or 46)
            if category=="Gems" then
                set(activityTitle,tr("ATIVIDADE DAS GEMAS","GEM CRAFT ACTIVITY","ACTIVIDAD DE GEMAS"))
                local row=selectedGem and rows[selectedGem.key]
                set(globalStatus,(selectedGem and selectedGem.name.."\n" or "")..(row and row.status.Text or tr("Escolha uma receita.","Choose a recipe.","Elige una receta.")))
            end
        end
        local function creditReceipt(recipe,receipt,bought)
            local evidence=true
            local operations=(receipt.expected or 1)/(receipt.give or 1)
            for id,need in pairs(receipt.costs or {}) do
                if need>0 and (not receipt.beforeInputs or not receipt.beforeInputs[id] or count(id)>receipt.beforeInputs[id]-need*operations) then evidence=false end
            end
            if not receipt.costs or not next(receipt.costs) then evidence=false end
            local setting=settings(recipe);local oldTarget=setting.target;local old=table.clone(receipt)
            local delta=state.craftReceiptCredit(setting,receipt,count(recipe.output),bought,evidence)
            if oldTarget==setting.target and old.credited==receipt.credited and old.observedStock==receipt.observedStock and old.observedGain==receipt.observedGain then return delta end
            if not save() then
                setting.target=oldTarget
                for key in pairs(receipt) do receipt[key]=nil end
                for key,value in pairs(old) do receipt[key]=value end
                recipe.problem=tr("Falha ao salvar confirmação; pedido preservado.","Could not save confirmation; request preserved.","Error al guardar confirmación; solicitud conservada.")
                return 0
            end
            return delta
        end
        local function reconcile(receipt)
            local recipe=lookup[receipt.key]
            if not recipe then return false end
            if receipt.quantityVersion~=2 then return count(recipe.output)>receipt.stock end
            local bought=recipe.kind=="Shop" and (tonumber(dependencies.shop.Bought("ExchangeShop",recipe.item)) or 0) or 0
            local setting = settings(recipe)
            creditReceipt(recipe,receipt,bought)
            if (receipt.credited or 0)>=(receipt.expected or 1) then return true end
            if state.craftReceiptDebited(recipe,receipt,count(recipe.source),workspace:GetServerTimeNow()) then
                state.craft.lastReceipt = {key=receipt.key,at=receipt.at,expected=receipt.expected,
                    credited=receipt.credited or 0,outcome="debited-output-unobserved"}
                -- A debit is not proof of delivery. Preserve finite quantities for review.
                if not setting.continuous then setting.enabled=false setting.needsReview=true end
                return true
            end
            return false
        end
        if type(clientData.OnChange)=="function" then
            local function observeReceipt(receipt)
                local recipe=receipt and lookup[receipt.key]
                if not recipe or receipt.quantityVersion~=2 then return false end
                local previousStock, previousCredit=receipt.observedStock,receipt.credited
                local bought=recipe.kind=="Shop" and (tonumber(dependencies.shop.Bought("ExchangeShop",recipe.item)) or 0) or 0
                creditReceipt(recipe,receipt,bought)
                return previousStock~=receipt.observedStock or previousCredit~=receipt.credited
            end
            local connection=clientData.OnChange({"Inventory","Items"},function()
                if not alive or not dependencies then return end
                local dirty=observeReceipt(state.craft.pending)
                for _,receipt in pairs(state.craft.unconfirmed) do
                    dirty=observeReceipt(receipt) or dirty
                end
                if dirty then save() end
            end)
            table.insert(cleanupCallbacks,function() connection:Disconnect() end)
        end
        local function step()
            local now=workspace:GetServerTimeNow()
            if not dependencies then
                if now<nextLoad then return end
                nextLoad=now+5
                local ok,problem=pcall(discover)
                if not ok then dependencies=nil set(globalStatus,tr("Catálogo indisponível: ","Catalog unavailable: ","Catálogo no disponible: ")..tostring(problem)) return end
            end
            local signature=state.craft.category..":"..state.craft.tokenFamily..":"..Http:JSONEncode(state.craft.tokens)
            if signature~=lastSignature or now>=nextLoad then
                nextLoad=now+10
                if not dependencies.gacha or not dependencies.upgrade then
                    local scripts=player:FindFirstChild("PlayerScripts")
                    local ui=scripts and scripts:FindFirstChild("NewUI",true)
                    if ui then
                        if not dependencies.gacha then local ok,value=pcall(require,ui.Screens.Gacha.Shared) if ok then dependencies.gacha=value end end
                        if not dependencies.upgrade then local ok,value=pcall(require,ui.Screens.Upgrader.Shared) if ok then dependencies.upgrade=value end end
                    end
                end
                local previousKeys={}
                for _,entry in ipairs(catalog) do previousKeys[#previousKeys+1]=entry.key end
                rebuildCatalog()
                local currentKeys={}
                for _,entry in ipairs(catalog) do currentKeys[#currentKeys+1]=entry.key end
                if signature~=lastSignature or table.concat(previousKeys,"|")~=table.concat(currentKeys,"|") then paintCards();lastSignature=signature end
            end
            local pending=state.craft.pending
            if pending then
                if reconcile(pending) then
                    if not state.craftArchive(state.craft,"pending",pending,"confirmed-or-debited") then refresh();return end
                elseif now-pending.at>=15 then
                    state.craft.unconfirmed[pending.key]=pending;state.craft.pending=nil
                    if not save() then state.craft.pending=pending;state.craft.unconfirmed[pending.key]=nil;refresh();return end
                else refresh() return end
            end
            for key,receipt in pairs(state.craft.unconfirmed) do
                if reconcile(receipt) then
                    state.craftArchive(state.craft.unconfirmed,key,receipt,"confirmed")
                elseif state.craftRecoveryReady then
                    local parts={}
                    for id in pairs(state.craftReceiptResources(receipt)) do parts[#parts+1]=id..":"..count(id) end;table.sort(parts)
                    if state.craftRecoveryReady("recipe:"..key,receipt,table.concat(parts,"|"),now) then
                        if state.craftArchive(state.craft.unconfirmed,key,receipt,"unconfirmed-stable-inventory") then
                            local setting=state.craft.items[key]
                            if setting and not state.craftAllowRetry("recipe:"..key) then
                                setting.enabled=false;setting.needsReview=true;save()
                                local recipe=lookup[key];if recipe then recipe.problem=tr("Três pedidos sem resposta; confira os requisitos no jogo.","Three requests without a result; check game requirements.","Tres solicitudes sin resultado; revisa los requisitos del juego.") end
                            end
                        end
                    end
                end
            end
            if preferenceWrites > 0 or state.panic or state.stopped or not alive or player.GameplayPaused then refresh() return end
            if now<nextSend then refresh() return end
            for offset=1,#catalog do
                local index=(lastRecipe+offset-1)%#catalog+1
                local recipe=catalog[index]
                local setting=settings(recipe)
                recipe.problem=nil
                if not state.craftOrderActive(setting) or isPending(recipe.key) then continue end
                local reason=blocked(recipe)
                if reason then recipe.problem=reason continue end
                -- Reject active exchange cycles and competing Auto Buy orders.
                if state.craftHasCycle(recipe,catalog,state.craft.items) then recipe.problem=tr("Trocas em ciclo: desligue a direção oposta.","Exchange cycle: disable the reverse direction.","Ciclo de intercambio: desactiva la dirección inversa.") continue end
                local buyConflict=false
                if autoBuy.enabled then
                    for key,v in pairs(autoBuy.items) do
                        if v.enabled and key:match(":"..recipe.output.."$") then buyConflict=true break end
                    end
                end
                if buyConflict then recipe.problem=tr("Auto Buy possui pedido para este item.","Auto Buy has an order for this item.","Auto Buy tiene un pedido de este artículo.") continue end
                local affordable=available(recipe)
                local ok,capacity=pcall(dependencies.extra.GetMaxCapacity,player,recipe.output)
                capacity=ok and tonumber(capacity)
                if not capacity then recipe.problem=tr("Capacidade indisponível.","Capacity unavailable.","Capacidad no disponible.") continue end
                local owned=count(recipe.output)
                local effectiveBatch=state.craftBatchMode(recipe.category,state.craft.batch)
                local batch=state.orderBatch(effectiveBatch)
                if recipe.kind=="Shop" then
                    local native=dependencies.shop.Amount("ExchangeShop",recipe.item,effectiveBatch=="1000x" and "Max" or batch,1)
                    batch=math.min(batch,tonumber(native) or 0)
                elseif recipe.kind=="Token" and effectiveBatch=="MAX" then batch=recipe.max end
                local amount=state.craftOperationAmount(state.craftOrderLimit(setting),owned,capacity,recipe.give,affordable,batch,recipe.max)
                local gemMax=false
                if recipe.kind=="Gem" and amount>=1 then
                    local nativeMax=state.craftOperationAmount(math.huge,owned,capacity,recipe.give,affordable,math.huge,recipe.max)
                    gemMax=effectiveBatch=="MAX" and amount==nativeMax
                    if not gemMax then amount=1 end
                end
                if amount<1 then
                    recipe.problem=capacity-owned<recipe.give and tr("Inventário cheio para este item.","Inventory full for this item.","Inventario lleno para este artículo.") or tr("Faltam ingredientes ou quantidade para um lote.","Missing ingredients or quantity for one batch.","Faltan ingredientes o cantidad para un lote.")
                    continue
                end
                local receipt={key=recipe.key,id=recipe.output,output=recipe.output,source=recipe.source or recipe.output,
                    stock=owned,balance=count(recipe.source or recipe.output),at=now,quantityVersion=2,
                    costs=costs(recipe),beforeInputs={},
                    expected=amount*recipe.give,credited=0,give=recipe.give,
                    bought=recipe.kind=="Shop" and (tonumber(dependencies.shop.Bought("ExchangeShop",recipe.item)) or 0) or 0}
                state.craft.pending=receipt
                for id in pairs(receipt.costs) do receipt.beforeInputs[id]=count(id) end
                if not save() then state.craft.pending=nil recipe.problem="Could not save operation receipt" break end
                if preferenceWrites > 0 or not state.craftOrderActive(setting) or state.panic
                    or state.stopped or not alive or player.GameplayPaused then
                    state.craft.pending=nil save() break
                end
                nextSend=now+1.5
                lastRecipe=index
                if recipe.kind=="Gem" then general:Fire({Event="CraftItem",Name=recipe.id,Max=gemMax and true or nil})
                elseif recipe.kind=="Key" then general:Fire({Event="CraftItem",Name=recipe.id})
                elseif recipe.kind=="Token" then
                    local packet={Event=recipe.family=="Gacha" and "GachaEx" or "UpgradeEx",Amount=amount}
                    packet[recipe.family=="Gacha" and "TargetGacha" or "TargetUpgrade"]=recipe.destination
                    packet[recipe.family=="Gacha" and "Gacha" or "Upgrade"]=recipe.origin
                    general:Fire(packet)
                else general:Fire({Event="ItemShopAction",Action="Buy",Shop="ExchangeShop",Item=recipe.id,Amount=amount,Rank=1}) end
                break
            end
            refresh()
        end
        table.insert(cleanupCallbacks,function()
            for _,connection in ipairs(rowConnections) do connection:Disconnect() end
        end)
        -- Native module loading runs independently from the shared UI refresh loop.
        task.spawn(function()
            while alive and page.Parent do
                local ok,problem=pcall(step)
                if not ok then set(globalStatus,tr("Craft em espera: ","Craft waiting: ","Craft en espera: ")..tostring(problem)) end
                task.wait(0.25)
            end
        end)
        table.insert(languageHooks,refresh)
end
