            BackgroundTransparency=1,Size=UDim2.fromScale(1,1),Font=Enum.Font.GothamBold,
            TextSize=12,TextColor3=colors.text,ZIndex=9,Active=false},b)
        local watched={}
        local function surface()
            b.TextTransparency=1;b.BackgroundTransparency=0
            local hide=b:FindFirstChild("NUI_CutHide")
            if hide then
                if not watched[hide] then
                    watched[hide]=true
                    table.insert(connections,hide:GetPropertyChangedSignal("Enabled"):Connect(function() if hide.Enabled then hide.Enabled=false end end))
                end
                hide.Enabled=false
            end
            for _,child in ipairs(b:GetChildren()) do
                if child:IsA("GuiObject") and child~=fg then
                    if not watched[child] then
                        watched[child]=true
                        table.insert(connections,child:GetPropertyChangedSignal("Visible"):Connect(function() if child.Visible then child.Visible=false end end))
                    end
                    child.Visible=false
                end
            end
        end
        table.insert(connections,b.ChildAdded:Connect(surface))
        table.insert(connections,b:GetPropertyChangedSignal("BackgroundTransparency"):Connect(function() if b.BackgroundTransparency~=0 then surface() end end))
        surface();speeds[value]={button=b,text=fg}
        connectUI(b,function() state.fastClickSetSpeed(value);updateFastClick() end)
    end
    updateFastClick=function()
        local t=state.fastClick
        H.paint(row.Toggle,t.enabled)
        local lang=uiState.language
        row.Caption.Text=t.problem and ((lang=="PT" and "Falha: " or lang=="ES" and "Error: " or "Error: ")..t.problem)
            or ((lang=="PT" and "Personagem " or lang=="ES" and "Jugador " or "Player ")..t.playerMultiplier.."×"
            ..(lang=="PT" and " · sombras sem alteração." or lang=="ES" and " · sombras sin cambios." or " · shadows unchanged."))
        for value,control in pairs(speeds) do
            local selected=t.playerMultiplier==value
            control.button:SetAttribute("Selected",selected)
            control.button.BackgroundColor3=selected and colors.accent or colors.bg
            control.text.TextColor3=selected and colors.bg or colors.text
        end
    end
