    connectUI(row.Toggle,function() state.fastClickCommitEnabled(not state.fastClick.enabled);updateFastClick() end)
    updateFastClick();table.insert(periodic,updateFastClick)

		local questButton = farm.Progress.Act_QuestObjectives
