-- Farm: grouped raid controls and independently collapsible category headers.
-- Recebe do nucleo (new-hub-view.lua): hub, link, bindText.
state.hubParts.farmCategories = function(H)
    local hub, link, bindText = H.hub, H.link, H.bindText
    local farm=hub.pages.Farm
    local events=farm.Events
    local raids=make("Frame",{Name="Raids",Size=UDim2.new(1,-1,0,450),
        BackgroundColor3=events.BackgroundColor3,BorderSizePixel=0,ClipsDescendants=true},farm)
    make("UICorner",{CornerRadius=UDim.new(0,7)},raids)
    make("UIStroke",{Color=colors.accent,Transparency=0.8,Thickness=1},raids)
    local ordered={
        {"Row_AutoDeduRaid","Dedu Raid"},{"Row_AutoWinterRaid","Winter Raid"},
        {"Row_AutoJungleRaid","Jungle Raid"},{"Row_AutoGiantsRaid","Giants Raid"},
        {"Row_AutoStorm","Storm"},{"Row_AutoGuildBoss","Guild Boss"},{"Row_AutoWorldBoss","World Boss"}}
    local y=50
    for index,item in ipairs(ordered) do
        local row=events:FindFirstChild(item[1])
        if row then
            row.Parent=raids
            row.LayoutOrder=index
            row.Position=UDim2.new(0,8,0,y)
            row.Size=UDim2.new(1,-16,0,54)
            state.setLocalizedText(row.Title,item[2])
            row.Title.Size=UDim2.new(1,-100,0,20)
            row.Caption.Size=UDim2.new(1,-100,0,30)
            y+=56
            if item[1]=="Row_AutoGiantsRaid" then y+=38 end
        end
    end
    -- Reuse the exact objective button and radio-card picker already used by Auto Quest.
    do
        local template=farm.Progress:FindFirstChild("Act_QuestObjectives")
        local giantRow=raids:FindFirstChild("Row_AutoGiantsRaid")
        if template and giantRow then
            local button=template:Clone()
            button.Name="Act_GiantsObjectives"
            for _,key in ipairs({"Action","MirrorText","QuestScopeLabel"}) do button:SetAttribute(key,nil) end
            button.Position=UDim2.new(0,45,0,giantRow.Position.Y.Offset+54)
            button.Size=UDim2.new(1,-62,0,28)
            button.Parent=raids
            local function refreshMode()
                state.setLocalizedText(button.Title,"Objetivo Giants: "..state.giantsModes[state.giantsMode])
            end
            state.onGiantsModeChanged=refreshMode
            refreshMode();bindText(button.Title)
            connectUI(button,function()
                local options={}
                for _,id in ipairs({"auto","legia","querah"}) do
                    table.insert(options,{id=id,name=state.giantsModes[id],selected=state.giantsMode==id})
                end
                choose("Objetivo da Giants Raid",options,function(id)
                    state.selectGiantsMode(id)
                    refreshMode()
                end)
                local picker=hub.pages.Chaves.Section_PICKER
                local note=picker:FindFirstChild("GiantsNotice")
                if not note then
                    note=make("TextLabel",{Name="GiantsNotice",Size=UDim2.new(1,-24,0,38),BackgroundTransparency=1,
                        TextWrapped=true,TextSize=11,Font=Enum.Font.GothamMedium,TextColor3=colors.muted,
                        LayoutOrder=4},picker)
                    state.setLocalizedText(note,"Outros jogadores podem influenciar o chefe. Giant Monarch procura invasores; Insect Monarch não os ataca.")
                    bindText(note)
                end
                note.Visible=true
            end)
            table.insert(cleanupCallbacks,function() state.onGiantsModeChanged=nil end)
        end
    end
    raids.Size=UDim2.new(1,-1,0,y+8)
    -- Keep the remaining event controls and their original handlers/relative order.
    local remaining={}
    for _,row in ipairs(events:GetChildren()) do
        if row:IsA("GuiObject") and row.Name:match("^Row_") then table.insert(remaining,row) end
    end
    table.sort(remaining,function(a,b) return a.Position.Y.Offset<b.Position.Y.Offset end)
    y=50
    for index,row in ipairs(remaining) do
        row.Position=UDim2.new(0,8,0,y)
        row.Size=UDim2.new(1,-16,0,54)
        row.LayoutOrder=index
        row.Title.Size=UDim2.new(1,-100,0,20)
        row.Caption.Size=UDim2.new(1,-100,0,30)
        y+=56
    end
    events.Size=UDim2.new(1,-1,0,y+8)
    uiState.farmCollapsed=uiState.farmCollapsed or {}
    local records={}
    local refreshing=false
    local function isContent(node)
        -- Full-height skin overlays follow the section; they cannot define its content height.
        return node:IsA("GuiObject") and node.Size.Y.Scale==0
            and not node.Name:match("^NUI_") and node:GetAttribute("Decorative")~=true
    end
    local function refresh()
        if refreshing then return end
        refreshing=true
        local top=0
        local factor=math.max(0.001,tonumber(scale and scale.Scale) or 1)
        for _,record in ipairs(records) do
            local section=record.section
            local expanded=46
            for _,child in ipairs(record.content) do
                if child.Parent==section and child.Visible then
                    local measured=child.Size.Y.Offset
                    if child.AutomaticSize==Enum.AutomaticSize.Y or child.AutomaticSize==Enum.AutomaticSize.XY then
                        measured=math.max(measured,(tonumber(child.AbsoluteSize.Y) or 0)/factor)
                    end
                    expanded=math.max(expanded,child.Position.Y.Offset+measured+8)
                end
            end
            local collapsed=uiState.farmCollapsed[section.Name]==true
            section:SetAttribute("CategoryCollapsed",collapsed)
            local height=collapsed and 46 or math.ceil(expanded)
            if section.Size.Y.Offset~=height then section.Size=UDim2.new(section.Size.X.Scale,section.Size.X.Offset,0,height) end
            record.arrow.Rotation=collapsed and 0 or 90
            if not state.responsiveWindow then
                section.Position=UDim2.fromOffset(0,top)
                top+=height+10
            end
        end
        if not state.responsiveWindow then farm.CanvasSize=UDim2.fromOffset(0,top+4) end
        refreshing=false
    end
    for index,spec in ipairs({{"Combat","COMBATE"},{"Progress","PROGRESSÃO"},{"Raids","RAIDS"},
        {"Events","EVENTOS"},{"GearTomeSettings","GEAR TOME"},{"Activity","STATUS E ATIVIDADE"}}) do
        local section=farm:FindFirstChild(spec[1])
        if section then
            local band=section:FindFirstChild("Band")
            if band then band:Destroy() end
            for _,child in ipairs(section:GetChildren()) do
                if section.Name=="GearTomeSettings" and child:IsA("TextLabel") and state.sourceText(child)=="GEAR TOME" then child:Destroy() end
            end
            local first=math.huge
            local content={}
            for _,child in ipairs(section:GetChildren()) do
                if isContent(child) then
                    table.insert(content,child)
                    first=math.min(first,child.Position.Y.Offset)
                end
            end
            local shift=first<50 and 50-first or 0
            for _,child in ipairs(content) do child.Position+=UDim2.fromOffset(0,shift) end
            section.AutomaticSize=Enum.AutomaticSize.None
            section.ClipsDescendants=true
            section.LayoutOrder=index
            local header=make("TextButton",{Name="CategoryHeader",Text="",AutoButtonColor=false,
                Position=UDim2.fromOffset(7,5),Size=UDim2.new(1,-14,0,36),BackgroundColor3=Color3.fromRGB(8,43,54),
                BorderSizePixel=0,ZIndex=3},section)
            make("UICorner",{CornerRadius=UDim.new(0,7)},header)
            local stroke=make("UIStroke",{Color=colors.accent,Thickness=1,Transparency=0.5},header)
            local title=make("TextLabel",{Name="Title",Text=spec[2],Position=UDim2.fromOffset(12,0),
                Size=UDim2.new(1,-54,1,0),BackgroundTransparency=1,Font=Enum.Font.GothamBold,
                TextSize=12,TextColor3=colors.text,TextXAlignment=Enum.TextXAlignment.Left,ZIndex=4},header)
            local badge=make("Frame",{Name="ArrowBadge",AnchorPoint=Vector2.new(1,0.5),Position=UDim2.new(1,-7,0.5,0),
                Size=UDim2.fromOffset(24,24),BackgroundColor3=Color3.fromRGB(4,28,38),BorderSizePixel=0,ZIndex=4},header)
            make("UICorner",{CornerRadius=UDim.new(1,0)},badge)
            local arrow=make("TextLabel",{Name="Chevron",Text="›",Size=UDim2.fromScale(1,1),BackgroundTransparency=1,
                Font=Enum.Font.GothamBold,TextSize=24,TextColor3=colors.accent,ZIndex=5},badge)
            bindText(title)
            table.insert(records,{section=section,header=header,arrow=arrow,content=content})
            connectUI(header,function()
                uiState.farmCollapsed[section.Name]=not (uiState.farmCollapsed[section.Name]==true)
                refresh()
                task.spawn(save)
            end)
            link(header.MouseEnter,function() stroke.Transparency=0.1 end)
            link(header.MouseLeave,function() stroke.Transparency=0.5 end)
            link(section:GetPropertyChangedSignal("Size"),refresh)
            for _,child in ipairs(content) do
                link(child:GetPropertyChangedSignal("AbsoluteSize"),refresh)
                link(child:GetPropertyChangedSignal("Visible"),refresh)
            end
        end
    end
    refresh()
    return refresh
end
-- Farm: Rebirth - atributos do StatsInfo nativo, metas, Auto Max e prioridade.
-- Recebe do nucleo (new-hub-view.lua): hub, shadow, invoke, link, bindText, paint, mirror, bindField, orderedChildren, textLabels, mirrorList, clearClones.
state.hubParts.farmRebirth = function(H)
    local hub, shadow, invoke, link, bindText, paint, mirror, bindField, orderedChildren, textLabels, mirrorList, clearClones = H.hub, H.shadow, H.invoke, H.link, H.bindText, H.paint, H.mirror, H.bindField, H.orderedChildren, H.textLabels, H.mirrorList, H.clearClones
		local page = hub.pages.FarmAttributes
        -- Show the actual worker status beside the controls instead of hiding it on Farm.
        page.Distribution.Size = UDim2.new(1, -1, 0, 157)
        page.StatList.Position += UDim2.fromOffset(0, 54)
        local distributionStatus = label("", 12, 98, 24, 50, page.Distribution, 10)
        distributionStatus.Name = "DistributionStatus"
        local sourceStatus = shadow("RebirthStatus")
        if sourceStatus then mirror(distributionStatus, sourceStatus) end
		local list, template = page.StatList, page.StatTemplate
		mirrorList(shadow("StatPriorityList"), function(group)
			clearClones(list, {})
			for index, row in ipairs(orderedChildren(shadow("StatPriorityList"))) do
				local id = row.Name
				local labels = textLabels(row)
				local card = template:Clone()
				card.Name, card.Visible, card.LayoutOrder, card.Position = "Stat_" .. id, true, index, UDim2.new()
				card.Band.Icon.Text = labels[1] and labels[1].Text or tostring(index)
				card.Band.Title.Text = labels[2] and labels[2].Text or id
				if labels[3] then
					mirror(card.TargetLabel, labels[3], nil, false, group)
					-- "Atual: 10 / 200 · Meta total:" (em qualquer idioma) → só o valor atual no quadro ATUAL.
					local source, valueLabel = labels[3], card.CurrentBox.Value
					local function update()
						valueLabel.Text = source.Text:match("^[^:]*:%s*(.-)%s*·") or source.Text
					end
					update()
					link(source:GetPropertyChangedSignal("Text"), update, group)
				end
				local target = row:FindFirstChild("Target_" .. id)
				if target then bindField(card.GoalBox.Target, target, group) end
				local maxButton = row:FindFirstChild("AutoMax_" .. id)
				local autoMaxRow = card.AutoMaxBox.Row_AutoMax
				local toggle = autoMaxRow.Toggle
				toggle:SetAttribute("Template", nil)
				bindText(autoMaxRow.Title)
				bindText(autoMaxRow.Caption)
				if maxButton then
					local function update()
                        paint(toggle, rebirth.autoMax[id] == true)
                        card.GoalBox.Target.TextEditable = rebirth.autoMax[id] ~= true
                    end
					update()
					link(maxButton:GetAttributeChangedSignal("AutoMaxEnabled"), update, group)
					connectUI(toggle, function()
                        state.setStatAutoMax(id, rebirth.autoMax[id] ~= true)
                        update()
                    end, nil, group)
				end
				for _, direction in ipairs({"MoveUp", "MoveDown"}) do
					local arrow = row:FindFirstChild(direction)
					if arrow then connectUI(card.Band[direction], function() invoke(arrow) end, nil, group) end
				end
				card.Parent = list
			end
		end)
end
-- Dungeon: Trial Cards - catalogo nativo TimeTrialBuffs, ordem salva, busca e abas.
-- Recebe do nucleo (new-hub-view.lua): hub, languageHooks, shadow, invoke, orderedChildren, textLabels, mirrorList, clearClones.
state.hubParts.dungeonCartas = function(H)
    local hub, languageHooks, shadow, invoke, orderedChildren, textLabels, mirrorList, clearClones = H.hub, H.languageHooks, H.shadow, H.invoke, H.orderedChildren, H.textLabels, H.mirrorList, H.clearClones
		local section = hub.pages.Cartas["Section_CARTAS (TIME TRIAL)"]
		local list = section.CardList
		local template = list.CardTemplate
        local catalogueOpen = false
        local rerender
        local catalogueBar = make("Frame", {Name = "CardCatalogueControls", Size = UDim2.new(1, -16, 0, 74), BackgroundTransparency = 1, LayoutOrder = 5}, section)
        local note = label("", 8, 38, 16, 34, catalogueBar, 11)
        local chooseCards = make("TextButton", {Name = "SelectTrialCards", Text = "", Size = UDim2.new(1, 0, 0, 34), BackgroundColor3 = colors.edge, TextColor3 = colors.text}, catalogueBar)
        local function refreshCardLabels()
            local language = uiState.language
            state.setLocalizedText(chooseCards, catalogueOpen and (language == "PT" and "Voltar às prioridades" or language == "ES" and "Volver a prioridades" or "Back to priorities")
                or (language == "PT" and "Selecionar cards" or language == "ES" and "Seleccionar cartas" or "Select cards"))
            state.setLocalizedText(note, language == "PT" and "Selecionados têm prioridade. Sem favorito oferecido, usa a ordem restante."
                or language == "ES" and "Los seleccionados tienen prioridad. Si no aparecen, usa el orden restante."
                or "Selected cards take priority. If none are offered, remaining order is used.")
        end
        connectUI(chooseCards, function() catalogueOpen = not catalogueOpen refreshCardLabels() if rerender then rerender() end end)
        refreshCardLabels()
        table.insert(languageHooks, refreshCardLabels)
        section.Search.LayoutOrder = 6
        list.LayoutOrder = 7
		mirrorList(shadow("TrialCardPriorityList"), function(group)
            rerender = function()
                local source = shadow("TrialCardPriorityList")
                if source then local marker = Instance.new("Folder") marker.Name = "RefreshCards" marker.Parent = source marker:Destroy() end
            end
			clearClones(list, {[template] = true})
			for index, row in ipairs(orderedChildren(shadow("TrialCardPriorityList"))) do
                local category = row:GetAttribute("TrialCategory") or "buffs"
                local selected = state.trialSelected[category][row.Name] == true
                local anySelected = next(state.trialSelected[category]) ~= nil
                if not catalogueOpen and anySelected and not selected then continue end
				local labels = textLabels(row)
				local card = template:Clone()
				card.Name, card.Visible, card.LayoutOrder = "Card_" .. row.Name, true, index
                card.Size = UDim2.new(1, 0, 0, 130)
                local select = make("TextButton", {Name = "SelectCard", Text = selected and "✓" or "+", Position = UDim2.new(1, -146, 0, 94), Size = UDim2.fromOffset(136, 28), BackgroundColor3 = selected and colors.action or colors.edge, TextColor3 = colors.text}, card)
                connectUI(select, function() state.toggleTrialSelection(category, row.Name) if rerender then rerender() end end, nil, group)
				local targets = {card.Rank, card.CardName, card.Effect, card.Extra}
				for i, label in ipairs(labels) do
					if targets[i] then
						targets[i].Text = label.Text
						if i >= 3 then targets[i].TextColor3 = label.TextColor3 end
					end
				end
				local icon = row:FindFirstChild("OriginalIcon")
				card.Icon.Image = icon and icon.Image or ""
				local arrows = {}
				for _, child in ipairs(row:GetChildren()) do
					if child:IsA("TextButton") then arrows[child.Text] = child end
				end
				for direction, glyph in pairs({MoveUp = "↑", MoveDown = "↓"}) do
					local arrow = arrows[glyph]
					local button = card[direction]
					if arrow then
						button.TextTransparency = arrow.Active and 0 or 0.7
						connectUI(button, function() invoke(arrow) end, nil, group)
					else button.Visible = false end
				end
				card.Parent = list
			end
		end)
end
-- Dungeon: Runas - espacos do grupo nativo; cada espaco abre o seletor com o estoque real.
-- Recebe do nucleo (new-hub-view.lua): hub, shadow, invoke, mirror, orderedChildren, mirrorList, clearClones.
state.hubParts.dungeonRunas = function(H)
    local hub, shadow, invoke, mirror, orderedChildren, mirrorList, clearClones = H.hub, H.shadow, H.invoke, H.mirror, H.orderedChildren, H.mirrorList, H.clearClones
		local section = hub.pages.Runas["Section_CONFIGURAR RUNAS"]
		local list = section.Slots
		local template = list.SlotTemplate
		mirrorList(shadow("DungeonRuneSlots"), function(group)
			clearClones(list, {[template] = true})
			for index, row in ipairs(orderedChildren(shadow("DungeonRuneSlots"))) do
				local pick, desc, art
				for _, child in ipairs(row:GetChildren()) do
					if child:IsA("TextButton") then pick = child
					elseif child:IsA("ImageLabel") then art = child
					elseif child:IsA("TextLabel") and child.Text ~= "—" then desc = child end
				end
				if pick then
					local slot = template:Clone()
					slot.Name, slot.Visible, slot.LayoutOrder = "Slot_" .. index, true, index
					slot:SetAttribute("Template", nil)
					mirror(slot.Label, pick, nil, false, group)
					if desc then mirror(slot.Sub, desc, nil, false, group) end
					local image = art and art.Image or ""
					slot.Frame.Artwork.Image = image
					slot.Frame.TextLabel.Visible = image == ""
					connectUI(slot, function() invoke(pick) end, nil, group)
					slot.Parent = list
				end
			end
		end)
end
-- Island Rifts route UI: scoped to this mode, native pill toggles and game artwork.
state.hubParts.rift=function(H)
    local api=state.rift
    local card=H.hub.pages.DungeonMain.DungeonCard
    local panel=make("Frame",{Name="IslandRiftSettings",LayoutOrder=card.Section.LayoutOrder+2,
        Size=UDim2.new(1,0,0,0),AutomaticSize=Enum.AutomaticSize.Y,BackgroundTransparency=1,Visible=false},card)
    make("UIListLayout",{Padding=UDim.new(0,10),SortOrder=Enum.SortOrder.LayoutOrder},panel)
    local function tr(pt,en,es) return uiState.language=="PT" and pt or uiState.language=="ES" and es or en end
    local function text(parent,name,value,x,y,w,h,size,bold)
        return make("TextLabel",{Name=name,Text=value,Position=UDim2.fromOffset(x,y),Size=UDim2.new(1,w,0,h),
            BackgroundTransparency=1,TextColor3=colors.text,Font=bold and Enum.Font.GothamBold or Enum.Font.Gotham,
            TextSize=size or 12,TextWrapped=true,TextXAlignment=Enum.TextXAlignment.Left},parent)
    end
    local function box(name,height,order)
        local f=make("Frame",{Name=name,LayoutOrder=order,Size=UDim2.new(1,-2,0,height),BackgroundColor3=colors.card,BorderSizePixel=0},panel)
        make("UIStroke",{Color=colors.accent,Transparency=0.5},f);return f
    end
    local function saveConfig()
        save()
        if api.testPersist then api.testPersist() end
    end
    local switches=box("Automation",120,1)
    local nextRow=card.Section.Row_AutoReplay:Clone()
    nextRow.Name="AutoNext";nextRow.Position=UDim2.fromOffset(8,2);nextRow.Size=UDim2.new(1,-16,0,56);nextRow.AutomaticSize=Enum.AutomaticSize.None;nextRow.Parent=switches
    local islandRow=nextRow:Clone();islandRow.Name="AutoIslands";islandRow.Position=UDim2.fromOffset(8,60);islandRow.Parent=switches
    -- Keep the previous test's handler paths available without duplicating visible controls.
    local function resetToggle(row)
        row.Toggle:SetAttribute("Bind",nil);row.Toggle:SetAttribute("Id",nil);row.Toggle:SetAttribute("MirrorCaption",nil)
        row.Desc.TextSize=10;row.Desc.TextTruncate=Enum.TextTruncate.None
        row.Desc.Size=UDim2.new(1,-112,0,28)
    end
    resetToggle(nextRow);resetToggle(islandRow)
    local fields=box("Levels",78,2)
    local choice=make("TextButton",{Name="Checkpoint",Position=UDim2.fromOffset(10,9),Size=UDim2.new(0.5,-15,0,60),
        BackgroundColor3=colors.bg,Text="",AutoButtonColor=false},fields)
    make("UIStroke",{Color=colors.accent,Transparency=0.5},choice)
    local checkpointTitle=text(choice,"Heading","",8,5,-16,18,10,true)
    local checkpointValue=text(choice,"Foreground","",8,25,-16,27,16,true);checkpointValue.TextColor3=colors.accent
    local targetFrame=make("Frame",{Name="Target",Position=UDim2.new(0.5,5,0,9),Size=UDim2.new(0.5,-15,0,60),BackgroundColor3=colors.bg,BorderSizePixel=0},fields)
    make("UIStroke",{Color=colors.accent,Transparency=0.5},targetFrame)
    local targetTitle=text(targetFrame,"Heading","",8,5,-16,18,10,true)
    local target=make("TextBox",{Name="Value",Text=tostring(dungeon.rift.target),Position=UDim2.fromOffset(8,25),Size=UDim2.new(1,-16,0,27),
        BackgroundTransparency=1,TextColor3=colors.accent,Font=Enum.Font.GothamBold,TextSize=16,ClearTextOnFocus=false,TextXAlignment=Enum.TextXAlignment.Left},targetFrame)
    local select=make("TextButton",{Name="SelectIslands",LayoutOrder=3,Size=UDim2.new(1,-2,0,44),Text="",BackgroundColor3=colors.card,AutoButtonColor=false},panel)
    make("UIStroke",{Color=colors.accent,Transparency=0.2},select)
    local selectText=text(select,"Foreground","",12,0,-24,44,12,true);selectText.TextColor3=colors.accent;selectText.TextXAlignment=Enum.TextXAlignment.Center
    local route=box("Route",42,4)
    local routeTitle=text(route,"Heading","",10,5,-20,25,12,true)
    local rows={}
    for i=1,4 do
        local f=make("Frame",{Name="Island"..i,Position=UDim2.fromOffset(8,36+(i-1)*66),Size=UDim2.new(1,-16,0,62),BackgroundColor3=colors.bg,BorderSizePixel=0,Visible=false},route)
        local image=make("ImageLabel",{Name="Artwork",Position=UDim2.fromOffset(6,7),Size=UDim2.fromOffset(46,46),BackgroundTransparency=1,ScaleType=Enum.ScaleType.Crop},f)
        local name=text(f,"IslandName","",60,5,-140,22,12,true)
        local status=text(f,"Status","",60,27,-140,18,10,false);status.TextColor3=colors.muted
        local count=text(f,"Progress","",0,7,-8,26,12,true);count.Position=UDim2.new(1,-80,0,7);count.Size=UDim2.fromOffset(72,26);count.TextXAlignment=Enum.TextXAlignment.Right
        local bar=make("Frame",{Name="Track",Position=UDim2.fromOffset(60,51),Size=UDim2.new(1,-70,0,4),BackgroundColor3=colors.card,BorderSizePixel=0},f)
        local fill=make("Frame",{Name="Fill",Size=UDim2.fromScale(0,1),BackgroundColor3=colors.accent,BorderSizePixel=0},bar)
        rows[i]={frame=f,image=image,name=name,status=status,count=count,fill=fill}
    end
    local activity=box("Activity",116,5)
    local activityTitle=text(activity,"Heading","",10,5,-20,24,12,true)
    local activityBody=text(activity,"Body","",10,35,-20,68,12,false)
    local oldContext,plan,problem,nextRefresh
    local function refreshData()
        if not api.planRoute then return end
        local ok,value,reason=pcall(api.planRoute)
        plan=ok and value or nil;problem=ok and reason or tostring(value)
        if api.context and not api.inRun() then local good,c=pcall(api.context);oldContext=good and c or nil end
    end
    local update
    local function openIslands()
        if not api.catalog then dungeonStatus.Text="Island Rifts: loading native data.";return end
        local ok,catalog,reason=pcall(api.catalog)
        if not ok or not catalog then dungeonStatus.Text=ok and reason or tostring(catalog);return end
        local options={{id="__DONE__",name=tr("Concluir seleção","Done","Terminar selección")},
            {id="__ALL__",name=tr("Selecionar todas liberadas","Select all unlocked","Seleccionar todas desbloqueadas")},
            {id="__CLEAR__",name=tr("Limpar seleção","Clear selection","Limpiar selección")}}
        for _,island in ipairs(catalog) do
            options[#options+1]={id=island.key,name=(dungeon.rift.islands[island.key] and "✓ " or "")..island.name.." · W"..island.world.." · "..island.best.."/"..dungeon.rift.target..(not island.unlocked and " · LOCKED" or ""),image=island.image,selected=dungeon.rift.islands[island.key]==true}
        end
        choose(tr("Selecionar ilhas","Select islands","Seleccionar islas"),options,function(id)
            if id=="__DONE__" then update(true);return end
            if id=="__CLEAR__" then dungeon.rift.islands={}
            elseif id=="__ALL__" then for _,island in ipairs(catalog) do if island.unlocked then dungeon.rift.islands[island.key]=true end end
            else
                for _,island in ipairs(catalog) do if island.key==id and (island.unlocked or dungeon.rift.islands[id]) then dungeon.rift.islands[id]=not dungeon.rift.islands[id] or nil end end
            end
            saveConfig();update(true);openIslands()
        end)
    end
    update=function(force)
        panel.Visible=dungeon.mode=="rift"
        if force or not nextRefresh or os.clock()>=nextRefresh then nextRefresh=os.clock()+1;refreshData() end
        state.setLocalizedText(nextRow.Title,"Auto Next");state.setLocalizedText(islandRow.Title,"Auto Islands")
        state.setLocalizedText(nextRow.Desc,tr("Avança para o maior nível liberado.","Advances to the highest unlocked level.","Avanza al mayor nivel desbloqueado."))
        state.setLocalizedText(islandRow.Desc,tr("Completa a meta e segue para a próxima ilha.","Reaches the target, then moves to the next island.","Alcanza la meta y pasa a la siguiente isla."))
        H.paint(nextRow.Toggle,dungeon.rift.autoNext);H.paint(islandRow.Toggle,dungeon.rift.autoIslands)
        checkpointTitle.Text=tr("CHECKPOINT ATUAL","CURRENT CHECKPOINT","CHECKPOINT ACTUAL")
        targetTitle.Text=tr("NÍVEL ALVO","TARGET LEVEL","NIVEL OBJETIVO")
        local level=dungeon.rift.level
        if oldContext then level=dungeon.rift.autoIslands and api.routeLevel(dungeon.rift,oldContext.levels) or api.select(dungeon.rift,oldContext.levels) or level end
        if api.inRun() and api.lastEntry then level=api.lastEntry.level end
        checkpointValue.Text=(dungeon.rift.maxLevel and not dungeon.rift.autoIslands and "MAX · " or "")..tostring(level or "—").."  >"
        selectText.Text=tr("SELECIONAR ILHAS","SELECT ISLANDS","SELECCIONAR ISLAS").."  ›  "..tostring(plan and plan.total or 0)
        routeTitle.Text=tr("ROTA DAS ILHAS","ISLAND ROUTE","RUTA DE ISLAS").."  ·  "..tostring(plan and plan.completed or 0).." / "..tostring(plan and plan.total or 0)
        local first=1
        if plan and #plan.rows>4 and plan.next then for i,value in ipairs(plan.rows) do if value.key==plan.next.key then first=math.max(1,i-1);break end end end
        local shown=0
        for i,row in ipairs(rows) do
            local island=plan and plan.rows[first+i-1]
            row.frame.Visible=island~=nil
            if island then
                shown+=1;row.image.Image=island.image;row.name.Text=island.name
                row.count.Text=island.best.." / "..dungeon.rift.target
                local complete=island.best>=dungeon.rift.target
                row.status.Text=complete and tr("CONCLUÍDA","COMPLETED","COMPLETADA") or not island.unlocked and tr("BLOQUEADA","LOCKED","BLOQUEADA") or plan.next==island and dungeon.rift.autoIslands and tr("EM ANDAMENTO","IN PROGRESS","EN PROGRESO") or tr("PENDENTE","PENDING","PENDIENTE")
                row.status.TextColor3=complete and Color3.fromRGB(40,220,120) or colors.muted
                row.fill.Size=UDim2.fromScale(math.clamp(island.best/dungeon.rift.target,0,1),1)
            end
        end
        route.Size=UDim2.new(1,-2,0,40+shown*66)
        activityTitle.Text=tr("ATIVIDADE","ACTIVITY","ACTIVIDAD")
        local progress=api.route
        local islandName=api.lastEntry and api.lastEntry.island or oldContext and oldContext.island.Name or "Island Rifts"
        if plan then for _,island in ipairs(plan.rows) do if api.lastEntry and island.key==api.lastEntry.island then islandName=island.name end end end
        local line=api.inRun() and (islandName.." · Rift "..tostring(level).."\n"..tr("Onda ","Wave ","Oleada ")..tostring(storage:GetAttribute("CurrentWave") or "—").." / 5") or not dungeon.enabled and tr("Auto Dungeon desligado.","Auto Dungeon is off.","Auto Dungeon desactivado.") or progress and progress.status or problem or tr("Configure a rota e ative Auto Dungeon.","Configure the route and enable Auto Dungeon.","Configura la ruta y activa Auto Dungeon.")
        local nextName=plan and plan.next and plan.next.name
        activityBody.Text=line..(nextName and ("\n"..tr("Próxima ilha: ","Next island: ","Próxima isla: ")..nextName) or "")
    end
    connectUI(nextRow.Toggle,function() dungeon.rift.autoNext=not dungeon.rift.autoNext;saveConfig();update(true) end)
    connectUI(islandRow.Toggle,function() dungeon.rift.autoIslands=not dungeon.rift.autoIslands;state.modeEntryDestination=nil;saveConfig();update(true) end)
    connectUI(select,openIslands)
    connectUI(target,function()
        local value=tonumber(target.Text)
        if value and value==value and value>=1 and value<=50 and value==math.floor(value) then dungeon.rift.target=value;saveConfig() end
        target.Text=tostring(dungeon.rift.target);update(true)
    end,target.FocusLost)
    connectUI(choice,function()
        if not api.context then return end
        local ok,context,reason=pcall(api.context)
        if not ok or not context then dungeonStatus.Text=ok and reason or tostring(context);return end
        local options={{id="__MAX__",name="Max · "..context.levels[#context.levels],selected=dungeon.rift.maxLevel==true}}
        for _,level in ipairs(context.levels) do options[#options+1]={id=level,name="Checkpoint "..level,selected=not dungeon.rift.maxLevel and dungeon.rift.level==level} end
        choose("Island Rifts · "..context.island.Name,options,function(level)
            dungeon.rift.maxLevel=level=="__MAX__"
            dungeon.rift.level=dungeon.rift.maxLevel and context.levels[#context.levels] or level
            dungeon.rift.autoNext=false;dungeon.rift.autoIslands=false;state.modeEntryDestination=nil;saveConfig();update(true)
        end)
    end)
    table.insert(H.periodic,update);table.insert(H.languageHooks,update)
    api.refreshUI=update;update(true)
end
-- Dungeon: modo selecionado e configuracao por modo.
-- Recebe do nucleo (new-hub-view.lua): hub, languageHooks, periodic, shadow, invoke, link, bindText, mirror, show, goBack.
state.hubParts.dungeonModos = function(H)
    local hub, languageHooks, periodic, shadow, invoke, link, bindText, mirror, show, goBack = H.hub, H.languageHooks, H.periodic, H.shadow, H.invoke, H.link, H.bindText, H.mirror, H.show, H.goBack
		local card = hub.pages.DungeonMain.DungeonCard
		local modeCards = shadow("DungeonModeCards")
		local grid = hub.pages.DungeonModes["Section_SELECIONAR MODO"].Grid
		-- The separate Eclipse entry uses the same mode-picker bindings as the other raids.
		do
			local template
			for _, item in ipairs(grid:GetChildren()) do
				if item:GetAttribute("ModeId") == "dragon" then template = item break end
			end
			if template and not grid:FindFirstChild("Mode_eclipse") then
				local item = template:Clone()
				item.Name, item.LayoutOrder = "Mode_eclipse", 16
				item:SetAttribute("ModeId", "eclipse")
				item:SetAttribute("Mode", "The Eclipse Court")
				for _, label in ipairs(item:GetDescendants()) do
					if label:IsA("TextLabel") and label.Text == "The Dragon Monarch" then label.Text = "The Eclipse Court" end
				end
				item.Parent = grid
			end
		end
        do
            local template=grid:FindFirstChild("Mode_eclipse")
            if template and modeCards:FindFirstChild("rift") and not grid:FindFirstChild("Mode_rift") then
                local item=template:Clone();item.Name="Mode_rift";item.LayoutOrder=17
                item:SetAttribute("ModeId","rift");item:SetAttribute("Mode","Island Rifts")
                for _,label in ipairs(item:GetDescendants()) do
                    if label:IsA("TextLabel") and label.Text=="The Eclipse Court" then label.Text="Island Rifts" end
                end
                item.Parent=grid
            end
        end
		local names = {}
		for _, item in ipairs(grid:GetChildren()) do
			local id = item:GetAttribute("ModeId")
			if id then
				names[id] = item:GetAttribute("Mode")
				connectUI(item, function()
					local original = modeCards and modeCards:FindFirstChild(id)
					if original then invoke(original) end
					goBack()
				end)
				item.MouseEnter:Connect(function() if dungeon.mode ~= id then item.UIStroke.Transparency = 0.3 end end)
				item.MouseLeave:Connect(function() if dungeon.mode ~= id then item.UIStroke.Transparency = 0.75 end end)
			end
		end
		local dropdown
		for _, d in ipairs(card:GetDescendants()) do
			if d.Name == "ModeDropdown" then dropdown = d end
			if d.Name == "ModeDropdown" or d.Name == "OpenModes" then connectUI(d, function() show("DungeonModes", true) end) end
		end
		-- Prévia da arte do modo: logo abaixo do título DUNGEON e acima do nome do modo.
		-- A imagem vem do cartão original (DungeonModeCards[id].Artwork), sem IDs novos.
		local function modeArt(id)
			local original = modeCards and modeCards:FindFirstChild(id)
			local art = original and original:FindFirstChild("Artwork")
			return art and art.Image ~= "" and art.Image or nil
		end
		for _, child in ipairs(card:GetChildren()) do
			if child:IsA("GuiObject") then child.LayoutOrder *= 10 end
		end
		local function round(object, radius)
			local c = Instance.new("UICorner")
			c.CornerRadius = UDim.new(0, radius)
			c.Parent = object
		end
		local preview = Instance.new("ImageButton")
		preview.Name, preview.LayoutOrder, preview.Size = "ModePreview", 15, UDim2.new(1, 0, 0, 118)
		preview.BackgroundColor3, preview.BorderSizePixel, preview.AutoButtonColor = colors.card, 0, false
		preview.Image, preview.ScaleType, preview.ClipsDescendants = "", Enum.ScaleType.Crop, true
		round(preview, 10)
		local previewStroke = Instance.new("UIStroke")
		previewStroke.Color, previewStroke.Thickness, previewStroke.Transparency = colors.accent, 1.5, 0.35
		previewStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
		previewStroke.Parent = preview
		local shade = Instance.new("Frame")
		shade.Name, shade.Size, shade.BackgroundColor3, shade.BorderSizePixel = "Shade", UDim2.fromScale(1, 1), Color3.new(0, 0, 0), 0
		local fade = Instance.new("UIGradient")
		fade.Rotation, fade.Transparency = 90, NumberSequence.new({NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.45, 0.85), NumberSequenceKeypoint.new(1, 0.15)})
		fade.Parent = shade
		shade.Parent = preview
		local previewTitle = Instance.new("TextLabel")
		previewTitle.Name, previewTitle.BackgroundTransparency = "ModeName", 1
		previewTitle.Position, previewTitle.Size = UDim2.new(0, 12, 1, -32), UDim2.new(1, -24, 0, 24)
		previewTitle.Font, previewTitle.TextSize, previewTitle.TextColor3 = Enum.Font.GothamBold, 16, Color3.new(1, 1, 1)
		previewTitle.TextXAlignment, previewTitle.TextTruncate = Enum.TextXAlignment.Left, Enum.TextTruncate.AtEnd
		previewTitle.TextStrokeTransparency, previewTitle.Text = 0.6, ""
		previewTitle.Parent = preview
		bindText(previewTitle)
		local previewEmpty = Instance.new("TextLabel")
		previewEmpty.Name, previewEmpty.BackgroundTransparency = "NoArt", 1
		previewEmpty.Size, previewEmpty.Position = UDim2.new(1, 0, 1, -36), UDim2.new()
		previewEmpty.Font, previewEmpty.TextSize, previewEmpty.TextColor3 = Enum.Font.Gotham, 12, colors.muted
		previewEmpty.Text, previewEmpty.Visible = "Sem imagem para este modo.", false
		previewEmpty.Parent = preview
		bindText(previewEmpty)
		preview.Parent = card
		connectUI(preview, function() show("DungeonModes", true) end)
		-- Miniatura dentro da pílula "Modo: ..." e nos cartões da lista de modos.
		local pill = card.Head.ModePill
		local thumb = Instance.new("ImageLabel")
		thumb.Name, thumb.AnchorPoint, thumb.Position, thumb.Size = "Thumb", Vector2.new(0, 0.5), UDim2.new(0, 4, 0.5, 0), UDim2.fromOffset(34, 22)
		thumb.BackgroundTransparency, thumb.ScaleType, thumb.Image, thumb.Visible = 1, Enum.ScaleType.Crop, "", false
		round(thumb, 5)
		thumb.Parent = pill
		-- Nomes longos ("The Dragon Monarch") encolhem dentro da pílula em vez de vazar.
		local fit = Instance.new("UITextSizeConstraint")
		fit.MaxTextSize, fit.MinTextSize = pill.Text.TextSize, 8
		fit.Parent = pill.Text
		pill.Text.TextScaled = true
		for _, item in ipairs(grid:GetChildren()) do
			local id = item:GetAttribute("ModeId")
			local image = id and modeArt(id)
			local glyph
			if image then
				for _, child in ipairs(item:GetChildren()) do
					if child:IsA("TextLabel") and child.Size.X.Scale == 0 and child.Size.X.Offset <= 40 then glyph = child end
				end
			end
			if glyph then
				local art = Instance.new("ImageLabel")
				art.Name, art.Position, art.Size = "Artwork", UDim2.fromOffset(8, 8), UDim2.fromOffset(88, 88)
				art.BackgroundTransparency, art.ScaleType, art.Image, art.ZIndex = 1, Enum.ScaleType.Fit, image, glyph.ZIndex
				round(art, 6)
				art.Parent = item
				glyph.Visible = false
			end
		end
        -- Mode cards reserve a square image and independent text space at every width.
        function state.layoutModeCards(width)
            local count = width >= 1140 and 3 or width >= 680 and 2 or 1
            local layout = grid:FindFirstChildOfClass("UIGridLayout")
            if layout then
                layout.CellSize = UDim2.new(1 / count, -8, 0, 112)
                layout.CellPadding = UDim2.fromOffset(10, 10)
            end
            for _, item in ipairs(grid:GetChildren()) do
                if item:GetAttribute("ModeId") then
                    local art = item:FindFirstChild("Artwork")
                    if art then
                        art.Position, art.Size, art.ScaleType = UDim2.fromOffset(8, 12), UDim2.fromOffset(88, 88), Enum.ScaleType.Fit
                    end
                    for _, child in ipairs(item:GetChildren()) do
                        if child:IsA("TextLabel") and child.Size.X.Scale > 0 then
                            local title = child.Name == "ModeTitle" or child.Size.Y.Offset == 18
                            child.Name = title and "ModeTitle" or "ModeKind"
                            child.Position = UDim2.fromOffset(108, title and 16 or 70)
                            child.Size = UDim2.new(1, -120, 0, title and 46 or 24)
                            child.TextScaled, child.TextWrapped = false, true
                            child.TextSize = title and 14 or 11
                            child.TextTruncate = Enum.TextTruncate.AtEnd
                            child.TextYAlignment = Enum.TextYAlignment.Center
                        end
                    end
                end
            end
        end
        state.layoutModeCards(uiState.width - 48)
        table.insert(periodic, function() state.layoutModeCards(uiState.width - 48) end)
		local function paintPreview(name)
			local image = modeArt(dungeon.mode)
			preview.Image, previewEmpty.Visible = image or "", image == nil
			previewTitle.Text = name
			thumb.Image, thumb.Visible = image or "", image ~= nil
			pill.Text.Position = image and UDim2.fromOffset(42, 0) or UDim2.new()
			pill.Text.Size = image and UDim2.new(1, -46, 1, 0) or UDim2.fromScale(1, 1)
		end
		local caption = shadow("SelectedDungeonMode") and shadow("SelectedDungeonMode"):FindFirstChild("ModeCaption")
		if caption then mirror(card.ModeDesc, caption) end
        if modeCards:FindFirstChild("rift") then state.hubParts.rift(H) end
        local afkNote = Instance.new("TextLabel")
        afkNote.Name, afkNote.LayoutOrder = "CastleAFKStatus", 85
        afkNote.Size, afkNote.BackgroundTransparency = UDim2.new(1,0,0,42), 1
        afkNote.TextColor3, afkNote.Font, afkNote.TextSize = colors.accent, Enum.Font.Gotham, 11
        afkNote.TextWrapped, afkNote.TextXAlignment = true, Enum.TextXAlignment.Left
        afkNote.Parent = card
		local heading = card.CfgHeading
		local diffHeading, checkHeading = shadow("DifficultyHeading"), shadow("CheckpointHeading")
		local function refreshMode()
            -- All visible mode fields read the same saved selection; text is never configuration.
            local mode = dungeonMode()
            if state.rift.refreshUI then state.rift.refreshUI() end
            afkNote.Visible = mode.id == "infernal"
            state.setLocalizedText(afkNote, state.castleAFK.status or "Enable Infernal Castle Floors in game Settings > AFK Mode.")
            local name = mode.name or names[mode.id] or mode.id
            state.setLocalizedText(card.Head.ModePill.Text, "Modo: " .. name)
            paintPreview(name)
            state.setLocalizedText(previewTitle, name)
            local dropdownLabel = dropdown and dropdown:FindFirstChild("Text")
            if dropdownLabel then state.setLocalizedText(dropdownLabel, name) end
            for _, item in ipairs(grid:GetChildren()) do
                local id = item:GetAttribute("ModeId")
                if id then
                    item.UIStroke.Transparency = id == mode.id and 0 or 0.75
                    item.UIStroke.Thickness = id == mode.id and 2 or 1.5
                end
            end
            local source = diffHeading and diffHeading.Visible and diffHeading or checkHeading and checkHeading.Visible and checkHeading or nil
            heading.Visible = source ~= nil
            if source then state.setLocalizedText(heading, state.sourceText(source)) end
            local choice = card:FindFirstChild("CfgChoice")
            local choiceButton = choice and choice:FindFirstChild("Button")
            if choiceButton then
                local text = mode.kind == "key" and (itemsInfo[dungeon.key] and itemsInfo[dungeon.key].Name or "Selecionar chave...") or dungeon.difficulty
                if mode.id=="key" and dungeon.autoKeys then text="Auto Keys" end
                if mode.gate then text = "Automático: " .. (dungeon.trickChoice or "Treat") .. "   · Alterar" end
                local label = choiceButton:FindFirstChild("Label") or choiceButton
                if label ~= choiceButton then choiceButton.Text = "" end
                state.setLocalizedText(label, type(text) == "string" and text ~= "" and text or "Selecione a dificuldade")
            end
        end
		state.refreshModeSelection = refreshMode
		refreshMode()
		table.insert(periodic, refreshMode)
		table.insert(languageHooks, refreshMode)
		for _, src in ipairs({diffHeading, checkHeading}) do
			if src then
				link(src:GetPropertyChangedSignal("Visible"), refreshMode)
				link(src:GetPropertyChangedSignal("Text"), refreshMode)
			end
		end
end
-- Compact, initially collapsed category directly beneath Auto Leave.
state.hubParts.dungeonUtilities=function(H)
    local u=dungeon.utilities
    local card=H.hub.pages.DungeonMain.DungeonCard
    local expandedHeight=300
    local panel=make("Frame",{Name="Utilities",LayoutOrder=card.Section.LayoutOrder+1,Size=UDim2.new(1,0,0,46),
        BackgroundColor3=Color3.fromRGB(8,26,34),BorderSizePixel=0,ClipsDescendants=true},card)
    -- dungeonModos already expanded orders by ten; preserve preview and selector order.
    make("UIStroke",{Color=colors.accent,Transparency=0.6},panel)
    local function label(parent,name,text,x,y,w,h,size)
        return make("TextLabel",{Name=name,Text=text,Position=UDim2.new(0,x,0,y),Size=UDim2.new(w[1],w[2],0,h),
            BackgroundTransparency=1,TextColor3=colors.text,TextSize=size or 12,Font=Enum.Font.GothamMedium,
            TextXAlignment=Enum.TextXAlignment.Left,TextWrapped=true,ZIndex=8},parent)
    end
    local function button(parent,name,text,x,y,w,h,callback)
        local b=make("TextButton",{Name=name,Text="",Position=UDim2.new(x[1],x[2],0,y),Size=UDim2.new(w[1],w[2],0,h),
            BackgroundColor3=Color3.fromRGB(8,43,54),BorderSizePixel=0,AutoButtonColor=false,ZIndex=5},parent)
        make("UIStroke",{Color=colors.accent,Transparency=0.5},b)
        local t=label(b,"Foreground",text,6,0,{1,-12},h,12);t.TextXAlignment=Enum.TextXAlignment.Center
        connectUI(b,callback)
        return b,t
    end
    local header,title=button(panel,"CategoryHeader","",{0,7},5,{1,-14},36,function()
        u.collapsed=not u.collapsed;panel:SetAttribute("CategoryCollapsed",u.collapsed);panel.Body.Visible=not u.collapsed
        panel.Size=UDim2.new(1,0,0,u.collapsed and 46 or expandedHeight)
        panel.CategoryHeader.Chevron.Rotation=u.collapsed and 0 or 90
        save()
    end)
    title.TextXAlignment=Enum.TextXAlignment.Left;title.Position=UDim2.fromOffset(12,0);title.Size=UDim2.new(1,-54,1,0)
    title.Font=Enum.Font.GothamBold
    local arrow=label(header,"Chevron","›",0,0,{0,24},36,24);arrow.Position=UDim2.new(1,-32,0,0);arrow.TextColor3=colors.accent
    local body=make("Frame",{Name="Body",Position=UDim2.fromOffset(0,46),Size=UDim2.new(1,0,0,254),BackgroundTransparency=1},panel)
    local switchTitle=label(body,"SwitchTitle","Switch Teams",12,0,{1,-80},36,13);switchTitle.Font=Enum.Font.GothamBold
    local switch=card.Section.Row_AutoLeave.Toggle:Clone();switch.Name="SwitchTeams";switch:SetAttribute("Bind",nil);switch:SetAttribute("Id",nil)
    switch.Position=UDim2.new(1,-12,0,18);switch.Parent=body
    local status=label(body,"SwitchStatus","",12,157,{1,-24},34,11);status.TextColor3=colors.muted
    local error=label(body,"ConfigurationError","",12,157,{1,-24},34,11);error.TextColor3=Color3.fromRGB(255,130,130);error.Visible=false
    local columns={label(body,"TeamLabel","",12,37,{0.2,-12},22,10),label(body,"KeyLabel","",0,37,{0.3,-4},22,10),label(body,"TimeLabel","",0,37,{0.5,-12},22,10)}
    columns[2].Position=UDim2.new(0.2,0,0,37);columns[3].Position=UDim2.new(0.52,0,0,37)
    local fields={};local keyLabels={}
    local function update()
        state.setLocalizedText(title,"UTILIDADES")
        state.setLocalizedText(columns[1],"Equipe");state.setLocalizedText(columns[2],"Tecla");state.setLocalizedText(columns[3],"Tempo ativo (s)")
        H.paint(switch,u.switchTeams)
        for _,side in ipairs({"A","B"}) do state.setLocalizedText(keyLabels[side],state.teamSwitchKeys[u["key"..side]].."  >") end
        local c=state.teamSwitchCycle
        local blocked=state.automationBlockReason and state.automationBlockReason("SwitchTeams",u.switchTeams)
        if state.teamSwitchError then
            status.Text=state.teamSwitchError
        elseif blocked then status.Text=blocked
        elseif not u.switchTeams then status.Text=state.utilityText("Troca de equipes desligada.")
        elseif not insideDungeon() then status.Text=state.utilityText("Aguardando entrar em uma dungeon.")
        elseif not c.side or c.paused then status.Text=state.utilityText("Troca de equipes pausada.")
        else status.Text=state.utilityText("Equipe %s · próxima troca em %ss",c.side,tostring(math.ceil(c.remaining))) end
        status.Visible=not error.Visible
    end
    connectUI(switch,function()
        if not u.switchTeams and u.keyA==u.keyB then state.teamSwitchError=state.utilityText("Escolha teclas diferentes para A e B.");update();return end
        u.switchTeams=not u.switchTeams;state.resetTeamSwitch();error.Visible=false;save();update()
    end)
    for index,side in ipairs({"A","B"}) do
        local y=61+(index-1)*44
        local badge=label(body,"Team"..side,side,12,y,{0.2,-20},34,14);badge.TextColor3=colors.accent;badge.Font=Enum.Font.GothamBold
        local _,text=button(body,"Key"..side,"",{0.2,0},y,{0.3,-8},34,function()
            local options={}
            for _,name in ipairs({"One","Two","Three","Four","Five","Six"}) do
                table.insert(options,{id=name,name=state.teamSwitchKeys[name],selected=u["key"..side]==name})
            end
            choose(state.utilityText("Tecla").." · "..side,options,function(name)
                local other=side=="A" and "B" or "A"
                if u["key"..other]==name then state.teamSwitchError=state.utilityText("Escolha teclas diferentes para A e B.");update();return end
                u["key"..side]=name;state.resetTeamSwitch();save();update()
            end,"Dungeon")
        end);keyLabels[side]=text
        local field=make("TextBox",{Name="Seconds"..side,Position=UDim2.new(0.52,0,0,y),Size=UDim2.new(0.48,-12,0,34),
            Text=tostring(u["seconds"..side]),ClearTextOnFocus=false,BackgroundColor3=colors.bg,TextColor3=colors.accent,
            TextSize=13,Font=Enum.Font.GothamBold,BorderSizePixel=0,ZIndex=8},body)
        make("UIStroke",{Color=colors.accent,Transparency=0.6},field);fields[side]=field
        table.insert(connections,field.FocusLost:Connect(function()
            local n=tonumber((field.Text:gsub(",",".")))
            if not n or n~=n or n<1 or n>3600 then
                field.Text=tostring(u["seconds"..side]);error.Text=state.utilityText("Use um tempo de 1 a 3600 segundos.");error.Visible=true
            else
                u["seconds"..side]=math.floor(n*10+0.5)/10;field.Text=tostring(u["seconds"..side]);error.Visible=false
                state.resetTeamSwitch();save()
            end
            update()
        end))
    end
    local hp=card.Section.Row_AutoLeave:Clone();hp.Name="Row_HighestHP";hp.Position=UDim2.fromOffset(0,196);hp.Size=UDim2.new(1,0,0,50)
    hp.AutomaticSize=Enum.AutomaticSize.None;hp.Toggle:SetAttribute("Bind",nil);hp.Toggle:SetAttribute("Id",nil);hp.Parent=body
    local hpIcon=hp:FindFirstChild("TextLabel");if hpIcon then hpIcon.Text="♥";hpIcon.TextColor3=colors.accent end
    hp.Desc.Size=UDim2.new(1,-112,0,26);hp.Desc.TextSize=10
    local function render()
        state.setLocalizedText(hp.Title,"Priorizar maior HP");state.setLocalizedText(hp.Desc,"Escolhe o maior HP e mantém o alvo até derrotá-lo.")
        H.paint(hp.Toggle,u.highestHP);update()
        local automation=body:FindFirstChild("Section_AUTOMACAO")
        if automation then
            local height,count=8,0
            for _,child in ipairs(automation:GetChildren()) do
                if child:IsA("GuiObject") and child.Visible and child.Size.Y.Scale==0 and not child.Name:match("^NUI_") then
                    height+=child.Size.Y.Offset;count+=1
                end
            end
            height+=math.max(0,count-1)*4
            automation.AutomaticSize=Enum.AutomaticSize.None;automation.Size=UDim2.new(1,-16,0,height)
            for _,mode in ipairs(miscModes) do if mode.id==state.speedSelectedMode then state.setLocalizedText(automation.Act_Mode.Label,mode.name) end end
            body.Size=UDim2.new(1,0,0,254+height+8);expandedHeight=46+254+height+8
            panel.Size=UDim2.new(1,0,0,u.collapsed and 46 or expandedHeight)
        end
    end
    local automation=H.hub.pages.Misc:FindFirstChild("Section_AUTOMACAO")
    if automation then automation.Position=UDim2.fromOffset(8,254);automation.Parent=body end
    connectUI(hp.Toggle,function() u.highestHP=not u.highestHP;state.highestHPLocked=nil;save();render() end)
    panel:SetAttribute("CategoryCollapsed",u.collapsed);panel.Body.Visible=not u.collapsed;panel.Size=UDim2.new(1,0,0,u.collapsed and 46 or expandedHeight);arrow.Rotation=u.collapsed and 0 or 90
    table.insert(H.periodic,render);table.insert(H.languageHooks,render);render()
end
-- Sell / Buy: Auto Buy - catalogo ItemShop/ShopInfo nativo; so Ticket/SoulCandy, metas e reservas.
-- Recebe do nucleo (new-hub-view.lua): hub, CYAN, languageHooks, periodic, shadow, invoke, link, mirror, bindField, orderedChildren, textLabels, mirrorList, clearClones.
state.hubParts.autoBuy = function(H)
    local hub, CYAN, languageHooks, periodic, shadow, invoke, link, mirror, bindField, orderedChildren, textLabels, mirrorList, clearClones = H.hub, H.CYAN, H.languageHooks, H.periodic, H.shadow, H.invoke, H.link, H.mirror, H.bindField, H.orderedChildren, H.textLabels, H.mirrorList, H.clearClones
		local section = hub.pages.SellBuy.Section_COMPRA
        local priorityNotice=make("TextLabel",{Name="BuyPriorityNotice",Size=UDim2.new(1,-24,0,0),
            AutomaticSize=Enum.AutomaticSize.Y,BackgroundColor3=colors.edge,BorderSizePixel=0,
            Text="",TextSize=15,Font=Enum.Font.GothamBold,TextColor3=Color3.fromRGB(255,196,82),TextWrapped=true,
            TextXAlignment=Enum.TextXAlignment.Left,LayoutOrder=1,Visible=false},section)
        make("UIPadding",{PaddingTop=UDim.new(0,10),PaddingBottom=UDim.new(0,10),
            PaddingLeft=UDim.new(0,10),PaddingRight=UDim.new(0,10)},priorityNotice)
        local function refreshPriorityNotice()
            local message=state.buyPriorityNotice and state.buyPriorityNotice()
            priorityNotice.Visible=message~=nil
            if message then state.setLocalizedText(priorityNotice,message) end
        end
        state.refreshBuyPriorityNotice=refreshPriorityNotice
        table.insert(periodic,refreshPriorityNotice)
        table.insert(languageHooks,refreshPriorityNotice)
        refreshPriorityNotice()
        local batchBar = make("Frame", {Name = "PurchaseBatch", Size = UDim2.new(1, -16, 0, 72), BackgroundTransparency = 1, LayoutOrder = 7}, section)
        local batchLabel = label("", 8, 0, 16, 26, batchBar, 12)
        local function refreshBatch()
            local mode = autoBuy.batch or "1x"
            state.setLocalizedText(batchLabel, uiState.language == "PT" and ("Lote por compra: " .. mode .. " · quantidade e reserva")
                or uiState.language == "ES" and ("Lote por compra: " .. mode .. " · cantidad y reserva")
                or ("Purchase batch: " .. mode .. " · quantity and reserve"))
            for _, control in ipairs(batchBar:GetChildren()) do
                if control:IsA("TextButton") then
                    state.styleTradeButton(control, control.Name == "Batch_" .. mode)
                end
            end
        end
        for index, mode in ipairs({"1x", "10x", "MAX"}) do
            local control = make("TextButton", {Name = "Batch_" .. mode, Text = mode, Position = UDim2.fromOffset((index - 1) * 82 + 4, 32), Size = UDim2.fromOffset(76, 30), BackgroundColor3 = colors.edge, TextColor3 = colors.text}, batchBar)
            state.styleTradeButton(control,autoBuy.batch==mode)
            connectUI(control, function() autoBuy.batch = mode save() refreshBatch() end)
        end
        refreshBatch()
        table.insert(languageHooks, refreshBatch)
		local list = section.BuyItems
		local catTemplate, itemTemplate = list.CategoryTemplate, list.ItemTemplate
		local selectorUpdates = {}
		local function paintBuy(button, key, group)
			local text, on, ready = state.buySelectionView(autoBuy.items[key])
			state.setLocalizedText(button, text)
			button.TextTransparency, button.BackgroundTransparency, button.Active = 0, 0, ready
			state.styleTradeButton(button, on, group)
		end
		local function refreshSelectors()
			for button, key in pairs(selectorUpdates) do if button.Parent then paintBuy(button, key) end end
		end
		table.insert(periodic, refreshSelectors)
		table.insert(languageHooks, refreshSelectors)
		mirrorList(shadow("BuyItems"), function(group)
			table.clear(selectorUpdates)
			clearClones(list, {[catTemplate] = true, [itemTemplate] = true})
			for index, node in ipairs(orderedChildren(shadow("BuyItems"))) do
				if node:IsA("TextLabel") then
					local category = catTemplate:Clone()
                    category.Name = "Category_" .. index
                    category:SetAttribute("Template", nil)
                    category.Size = UDim2.new(1, 0, 0, 28)
                    category.TextYAlignment = Enum.TextYAlignment.Center
					category.Visible, category.LayoutOrder = true, index
					mirror(category, node, nil, false, group)
					category.Parent = list
				elseif node:IsA("Frame") then
					local labels = textLabels(node)
					local card = itemTemplate:Clone()
					card.Name, card.Visible, card.LayoutOrder = "Item", true, index
                    card:SetAttribute("Template", nil)
					local image = node:FindFirstChildOfClass("ImageLabel")
					card.Icon.Image = image and image.Image or ""
					if labels[1] then mirror(card.ItemName, labels[1], nil, false, group) end
					if labels[2] then mirror(card.Caption, labels[2], nil, true, group) end
					if labels[3] then mirror(card.TargetLabel, labels[3], nil, false, group) end
					local select = node:FindFirstChild("SelectItem")
					local key = node.Name
					selectorUpdates[card.Select] = key
					paintBuy(card.Select, key, group)
					connectUI(card.Select, function()
						if not select or not invoke(select) then
							local settings = autoBuy.items[key]
							if not settings then return end
                            state.toggleBuyItem(autoBuy, key, workspace:GetServerTimeNow())
                            save()
						end
						paintBuy(card.Select, key)
					end, nil, group)
					if select then link(select:GetPropertyChangedSignal("Text"), function() paintBuy(card.Select, key) end, group) end
					local target = node:FindFirstChild("StockTarget")
					if target then bindField(card.Target, target, group) end
                    local inventorySource=node:FindFirstChild("InventoryOwned")
                    if inventorySource then
                        card.Size=UDim2.new(card.Size.X.Scale,card.Size.X.Offset,0,178)
                        local owned=make("TextLabel",{Name="InventoryOwned",Text="",BackgroundTransparency=1,
                            Position=UDim2.new(0,12,1,-28),Size=UDim2.new(1,-24,0,23),TextColor3=CYAN,
                            TextSize=11,Font=Enum.Font.GothamBold,TextXAlignment=Enum.TextXAlignment.Left},card)
                        mirror(owned,inventorySource,nil,false,group)
                    end
					card.Parent = list
                    local caption=card.Caption
                    local baseSize,baseHeight=math.max(14,caption.TextSize),card.Size.Y.Offset
                    local targetPos,labelPos=card.Target.Position,card.TargetLabel.Position
                    local function refreshWarningSize()
                        local warning=caption.TextColor3==Color3.fromRGB(255,196,82)
                        caption.TextSize=warning and 14 or baseSize
                        caption.AutomaticSize=Enum.AutomaticSize.Y
                        caption.TextWrapped=true
                        local extra=math.max(0,caption.TextBounds.Y-34)
                        card.Size=UDim2.new(card.Size.X.Scale,card.Size.X.Offset,0,baseHeight+extra)
                        card.Target.Position=targetPos+UDim2.fromOffset(0,extra)
                        card.TargetLabel.Position=labelPos+UDim2.fromOffset(0,extra)
                    end
                    link(caption:GetPropertyChangedSignal("TextColor3"),refreshWarningSize,group)
                    link(caption:GetPropertyChangedSignal("TextBounds"),refreshWarningSize,group)
                    refreshWarningSize()
				end
			end
		end)
		local currency = section.Currency
		local function refresh()
			for _, button in ipairs(currency:GetChildren()) do
				if button:IsA("TextButton") then state.styleTradeButton(button, button:GetAttribute("Currency") == autoBuy.currency) end
			end
		end
		refresh()
		table.insert(periodic, refresh)
end
-- Sell / Buy: abas de troca (navegacao fixa; a visibilidade nunca muda as configuracoes de automacao).
-- Recebe do nucleo (new-hub-view.lua): hub, CYAN, ROW, link, getCurrent (a aba atual muda em show(), por isso e uma funcao leitora).
state.hubParts.abasTrade = function(H)
    local hub, CYAN, ROW, link, getCurrent = H.hub, H.CYAN, H.ROW, H.link, H.getCurrent
        local page = hub.pages.SellBuy
        local sections = {Sell = {page.Section_VENDA, page.Section_ESPADAS}, Buy = {page.Section_COMPRA}}
        page.Position, page.Size = UDim2.fromOffset(0, 48), UDim2.new(1, 0, 1, -48)
        local bar = make("Frame", {Name = "TradeTabs", Size = UDim2.new(1, -7, 0, 40),
            BackgroundTransparency = 1, Visible = false}, hub.pages)
        local buttons = {}
        function state.refreshTradeTabs()
            bar.Visible = getCurrent() == "SellBuy" and page.Visible
        end
        local function selectTradeView(mode, persist)
            if not sections[mode] then mode = "Sell" end
            local focused = Input:GetFocusedTextBox()
            if focused and focused:IsDescendantOf(page) then focused:ReleaseFocus(false) end
            uiState.tradeMode = mode
            for key, group in pairs(sections) do
                for _, section in ipairs(group) do section.Visible = key == mode end
                local button = buttons[key]
                state.styleTradeButton(button, key == mode)
            end
            page.CanvasPosition = Vector2.zero
            state.refreshTradeTabs()
            if persist then save() end
        end
        for index, mode in ipairs({"Sell", "Buy"}) do
            local button = make("TextButton", {Name = "Trade_" .. mode, Text = mode,
                Position = UDim2.new((index - 1) * 0.5, index == 1 and 0 or 4, 0, 0),
                Size = UDim2.new(0.5, -4, 1, 0), BackgroundColor3 = ROW, BorderSizePixel = 0,
                TextColor3 = colors.text, TextSize = 14, Font = Enum.Font.GothamBold, AutoButtonColor = false}, bar)
            make("UICorner", {CornerRadius = UDim.new(0, 7)}, button)
            make("UIStroke", {Color = CYAN, Transparency = 0.6, Thickness = 1}, button)
            buttons[mode] = button
            connectUI(button, function() selectTradeView(mode, true) end)
        end
        link(page:GetPropertyChangedSignal("Visible"), state.refreshTradeTabs)
        selectTradeView(uiState.tradeMode or "Sell", false)
end
