state.hubParts.atalho = function(H)
    local hub, CYAN, languageHooks, shadow, link = H.hub, H.CYAN, H.languageHooks, H.shadow, H.link
		local keyValue = shadow("MinimizeKeyValue")
		local keyButton = hub.pages.Misc.Section_INTERFACE.Act_Keybind
		local function refreshKey()
			local key = keyValue and keyValue.Text or uiState.minimizeKey
			keyButton.Label.Text = state.translate("Minimizar / Restaurar: ") .. key
		end
		refreshKey()
		if keyValue then link(keyValue:GetPropertyChangedSignal("Text"), refreshKey) end
		table.insert(languageHooks, refreshKey)
		local language = shadow("LanguageSelector")
		if language then
			link(language:GetPropertyChangedSignal("Text"), function()
				for _, hook in ipairs(languageHooks) do pcall(hook) end
			end)
		end
		local fps = Instance.new("TextLabel")
		fps.Name, fps.AnchorPoint, fps.Position, fps.Size = "VykronHubFPS", Vector2.new(1, 0), UDim2.new(1, -12, 0, 8), UDim2.fromOffset(90, 22)
		fps.BackgroundColor3, fps.BackgroundTransparency, fps.TextColor3 = Color3.fromRGB(8, 26, 34), 0.2, CYAN
		fps.Font, fps.TextSize, fps.Text, fps.Visible = Enum.Font.GothamBold, 12, "FPS: --", false
		fps.Parent = gui
		local frames, since = 0, os.clock()
		link(RunService.RenderStepped, function()
			if not uiState.showFps then return end
			frames += 1
			local now = os.clock()
			if now - since >= 0.5 then
				fps.Text = "FPS: " .. math.floor(frames / (now - since) + 0.5)
				frames, since = 0, now
			end
		end)
		function state.applyLocalOption(key)
			fps.Visible = uiState.showFps == true
			if key == "compact" then
				if uiState.compact then
					uiState.compactWidth, uiState.compactHeight = uiState.width, uiState.height
					uiState.width, uiState.height = 480, 600
				else
					uiState.width = tonumber(uiState.compactWidth) or 500
					uiState.height = tonumber(uiState.compactHeight) or 820
				end
			end
		end
		state.applyLocalOption()
end
-- Misc: controles independentes de largura/altura da janela (mouse e toque).
-- Recebe do nucleo (new-hub-view.lua): hub, CYAN, OFF, ROW, languageHooks, periodic, link.
state.hubParts.tamanhoJanela = function(H)
    local hub, CYAN, OFF, ROW, languageHooks, periodic, link = H.hub, H.CYAN, H.OFF, H.ROW, H.languageHooks, H.periodic, H.link
		local page = hub.pages.Misc
		local section = make("Frame", {Name = "Section_MobileResize", LayoutOrder = 2,
			Size = UDim2.new(1, 0, 0, 240), BackgroundColor3 = colors.card, BorderSizePixel = 0}, page)
		for _, child in ipairs(page:GetChildren()) do
			if child ~= section and child:IsA("GuiObject") and child.LayoutOrder >= 2 then child.LayoutOrder += 1 end
		end
		make("UICorner", {CornerRadius = UDim.new(0, 10)}, section)
		make("UIStroke", {Color = colors.edge, Thickness = 1}, section)
		local title = label("Mobile Resize", 14, 8, 28, 24, section, 14, true)
		local note = label("Ajuste largura e altura por toque ou mouse.", 14, 34, 28, 30, section, 11)
		local controls, active = {}, nil
		local function limits(axis)
			return state.mobileResizeBounds(axis, gui.AbsoluteSize.X, gui.AbsoluteSize.Y, state.windowUnit or scale.Scale)
		end
		local function refreshSize()
			for axis, control in pairs(controls) do
				local lo, hi = limits(axis)
				local value = math.clamp(uiState[axis], lo, hi)
				local fraction = hi > lo and (value - lo) / (hi - lo) or 0
				control.fill.Size = UDim2.fromScale(fraction, 1)
				control.knob.Position = UDim2.fromScale(fraction, 0.5)
				control.value.Text = tostring(math.floor(uiState[axis] + 0.5))
			end
		end
		local function setSize(axis, value)
			local lo, hi = limits(axis)
			uiState[axis] = math.clamp(math.floor(value + 0.5), lo, hi)
			uiState.compact = false
			window:SetAttribute("SavedWidth", nil)
			fit()
			refreshSize()
		end
		local function finish()
			if not active then return end
			page.ScrollingEnabled = active.scrolling
			active = nil
			savePositions()
		end
		local function pointer(x)
			if not active then return end
			local c = controls[active.axis]
			local unit = math.max(0.001, scale.Scale)
			local trackWidth = c.hit.AbsoluteSize.X - 20 * unit
			if trackWidth <= 0 then return end
			local fraction = math.clamp((x - c.hit.AbsolutePosition.X - 10 * unit) / trackWidth, 0, 1)
			local lo, hi = limits(active.axis)
			setSize(active.axis, lo + fraction * (hi - lo))
		end
		for index, axis in ipairs({"width", "height"}) do
			local y = 68 + (index - 1) * 64
			label(axis == "width" and "Largura" or "Altura", 14, y, 140, 20, section, 12, true)
			local value = label("", 0, y, 14, 20, section, 12)
			value.Position, value.Size, value.TextXAlignment = UDim2.new(1, -96, 0, y), UDim2.fromOffset(82, 20), Enum.TextXAlignment.Right
			local minus = make("TextButton", {Name = axis .. "Minus", Text = "−", Position = UDim2.fromOffset(10, y + 21),
				Size = UDim2.fromOffset(36, 38), BackgroundColor3 = ROW, BorderSizePixel = 0, TextColor3 = colors.text, TextSize = 20}, section)
			local plus = minus:Clone()
			plus.Name, plus.Text, plus.Position, plus.Parent = axis .. "Plus", "+", UDim2.new(1, -46, 0, y + 21), section
			local hit = make("TextButton", {Name = axis .. "Slider", Text = "", BackgroundTransparency = 1, AutoButtonColor = false,
				Active = true, Position = UDim2.fromOffset(48, y + 21), Size = UDim2.new(1, -96, 0, 38)}, section)
			local track = make("Frame", {Position = UDim2.new(0, 10, 0.5, -3), Size = UDim2.new(1, -20, 0, 6),
				BackgroundColor3 = OFF, BorderSizePixel = 0}, hit)
			local fill = make("Frame", {Size = UDim2.fromScale(0, 1), BackgroundColor3 = CYAN, BorderSizePixel = 0}, track)
			local knob = make("Frame", {AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(18, 18),
				BackgroundColor3 = colors.text, BorderSizePixel = 0}, track)
			make("UICorner", {CornerRadius = UDim.new(1, 0)}, knob)
			controls[axis] = {hit = hit, fill = fill, knob = knob, value = value}
			connectUI(minus, function() finish() setSize(axis, uiState[axis] - 20) savePositions() end)
			connectUI(plus, function() finish() setSize(axis, uiState[axis] + 20) savePositions() end)
			link(hit.InputBegan, function(input)
				if active or dragging or state.resizeActive or not canInteract(hit) or state.collapsedHeight then return end
				if input.UserInputType ~= Enum.UserInputType.Touch and input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
				active = {axis = axis, input = input, scrolling = page.ScrollingEnabled}
				page.ScrollingEnabled = false
				pointer(input.Position.X)
			end)
		end
		local reset = make("TextButton", {Name = "RestoreMobileResize", Text = "Restaurar tamanho padrão",
			Position = UDim2.fromOffset(12, 200), Size = UDim2.new(1, -24, 0, 32), BackgroundColor3 = ROW,
			BorderSizePixel = 0, TextColor3 = colors.text, Font = Enum.Font.GothamMedium, TextSize = 12}, section)
		connectUI(reset, function()
			finish()
			uiState.width, uiState.height = state.responsiveWindow and state.responsiveDefaultSize(gui.AbsoluteSize.X, gui.AbsoluteSize.Y) or 500, state.responsiveWindow and select(2, state.responsiveDefaultSize(gui.AbsoluteSize.X, gui.AbsoluteSize.Y)) or 820
            uiState.compact = false
			state.windowUnit = nil
			window:SetAttribute("SavedWidth", nil)
			fit() refreshSize() savePositions()
		end)
		link(Input.InputChanged, function(input)
			if not active then return end
			if not canInteract(section) or state.collapsedHeight then finish() return end
			if input == active.input or (active.input.UserInputType == Enum.UserInputType.MouseButton1
				and input.UserInputType == Enum.UserInputType.MouseMovement) then pointer(input.Position.X) end
		end)
		link(Input.InputEnded, function(input) if active and input == active.input then finish() end end)
		link(RunService.RenderStepped, function()
			if active and (not canInteract(section) or state.collapsedHeight) then finish() end
		end)
		link(gui:GetPropertyChangedSignal("AbsoluteSize"), finish)
		table.insert(periodic, refreshSize)
		table.insert(languageHooks, refreshSize)
		refreshSize()
end
