-- Read-only explanations of existing controller gates; never changes priorities.
do
local collection={AutoHauntedHouses=true,AutoPumpkin=true,AutoPumpkinKing=true,AutoKamish=true,AutoGuildBoss=true}
local eventKinds={AutoWorldBoss="boss",AutoStorm="storm",AutoDeduRaid="dedu",AutoWinterRaid="winter",AutoJungleRaid="jungle",AutoGiantsRaid="giants"}
local automations={AutoFarmMobs=true,AutoQuest=true,AutoRebirth=true,AutoDistributeStats=true,AutoDungeon=true,
    RepeatDungeonWithGems=true,AutoLeaveAfterCompletion=true,AutoEquipRunes=true,EquipLastRunes=true,
    AutoTrialCards=true,AutoSellShadows=true,AutoSellSwords=true,AutoBuy=true,FastClick=true,
    AutoSpeed=true,AutoExitFloor=true,AutoDodge=true,AutoReconnect=true,AntiAFK=true,SwitchTeams=true,AutoResetQuests=true,TicketRefill=true,
    ShadowRankUp=true,ShadowReroll=true,ShadowInfusion=true,ShadowIndexDestroy=true,FixedIsland=true,LimitBreakerTravel=true}
local function tr(pt,en,es) return uiState.language=="PT" and pt or uiState.language=="ES" and es or en end
function state.automationPriorityName()
    local limit=autoQuest.splitQuests and autoQuest.limitBreakerEnabled or autoQuest.profile=="limitbreaker"
    return limit and "Limit Breaker" or "Auto Quest"
end
function state.automationBlockReason(id,enabled)
    if not enabled or type(id)~="string" then return nil end
    if not automations[id] and not collection[id] and not eventKinds[id] and not id:match("^Claim_") then return nil end
    if state.panic then return tr("Pausado: botão de pânico ativo.","Paused: Panic Button is active.","Pausado: botón de pánico activo.") end
    if state.stopped then return tr("Pausado: Hub encerrada.","Paused: Hub is stopped.","Pausado: Hub detenida.") end
    if player.GameplayPaused then return tr("Aguardando: carregamento do jogo.","Waiting: game is loading.","Esperando: carga del juego.") end
    local quest=state.questPriorityActive and state.questPriorityActive()
    local owner=state.automationPriorityName()
    local function priority(name)
        return tr("Pausado: prioridade de ","Paused: priority belongs to ","Pausado: prioridad de ")..name.."."
    end
    if (id=="FixedIsland" or id=="LimitBreakerTravel") and state.limitBreakerStormRequested and state.limitBreakerStormRequested() then
        return tr("Storm ativa: farm na ilha do evento. Viagens retomam ao terminar.","Storm active: farming the event island. Travel resumes when it ends.","Storm activa: farmeando en la isla del evento. Los viajes continúan al terminar.")
    end
    if id=="AutoQuest" then
        if autoQuest.splitQuests and autoQuest.limitBreakerEnabled then return priority("Limit Breaker") end
        if state.leaving or state.autoLeaving then return priority(tr("saída do modo","leaving the mode","salida del modo")) end
        if events and events.active then return priority(tostring(events.active)) end
        if insideDungeon() and not (autoQuest.journey and not autoQuest.journey.bucket) then
            return tr("Pausado: uma dungeon ou modo está em andamento.","Paused: a dungeon or mode is in progress.","Pausado: hay una mazmorra o modo en curso.")
        end
    end
    if quest then
        if (id=="AutoDungeon" or id=="RepeatDungeonWithGems") and state.limitBreakerStormRequested and state.limitBreakerStormRequested() then
            return priority("Storm")
        end
        if id=="AutoBuy" then return state.buyPriorityNotice and state.buyPriorityNotice() end
        if collection[id] then return priority(owner) end
        local kind=eventKinds[id]
        if kind and state.questPriorityAllows and not state.questPriorityAllows(kind) then return priority(owner) end
        if id=="AutoDungeon" and not questRuntime.modeRequest and not (state.limitBreakerPortalRequested and state.limitBreakerPortalRequested()) then return priority(owner) end
        if id=="RepeatDungeonWithGems" and not (state.questTrialRefillPending and state.questTrialRefillPending())
            and not (state.limitBreakerPortalRequested and state.limitBreakerPortalRequested()
                and (not insideDungeon() or state.limitBreakerPortalOwnsRun())) then return priority(owner) end
    end
    if id=="SwitchTeams" and state.refillTeams and state.refillTeams.owns() then
        return priority(tr("time da reposição na Trial","Trial refill team","equipo de reposición en Trial"))
    end
    if id=="AutoResetQuests" and autoQuest.splitQuests and not autoQuest.limitBreakerEnabled then
        return tr("Aguardando: ligue o Limit Breaker.","Waiting: enable Limit Breaker.","Esperando: activa Limit Breaker.")
    end
    if id=="AutoResetQuests" and autoQuest.journey and autoQuest.journey.bucket=="TicketFarm" then
        return priority(tr("reposição de Tickets na Trial","Ticket refill in Trial","reposición de Tickets en Trial"))
    end
    if id=="AutoDungeon" and not insideDungeon() and state.collectionPriority then
        local kind=state.collectionPriority()
        if kind then
            local names={houses="Haunted Houses",pumpkins="Pumpkins",pumpkinking="Pumpkin King",kamish="Nightmare Kamish"}
            return priority(names[kind] or tostring(kind))
        end
        if state.guild and state.guild.journey and state.guild.journey.phase=="return" then return priority("Guild Boss") end
    end
    if id=="AutoFarmMobs" and not farmEnabled() then
        if state.autoLeaving then return priority(tr("saída do modo","leaving the mode","salida del modo")) end
        if quest then return priority(owner) end
        if state.pumpkinBusy then return priority("Pumpkins") end
        if state.houses and state.houses.busy then return priority("Haunted Houses") end
        if state.kamishTakingOver then return priority("Nightmare Kamish") end
    end
    return nil
end
end
-- NEW HUB VIEW: the new Vykron Hub layout is the visible interface.
-- The original controls stay alive as the logic layer; every new control calls the
-- same registered handler (same save(), confirmations and status), so no game logic is duplicated.
do
local KEYS = {
	bc = "BackgroundColor3", bt = "BackgroundTransparency", bs = "BorderSizePixel", ap = "AnchorPoint",
	p = "Position", s = "Size", v = "Visible", z = "ZIndex", lo = "LayoutOrder", cd = "ClipsDescendants",
	as = "AutomaticSize", ro = "Rotation", ac = "Active", t = "Text", tc = "TextColor3", ts = "TextSize",
	f = "Font", xa = "TextXAlignment", ya = "TextYAlignment", tw = "TextWrapped", tsc = "TextScaled",
	tt = "TextTransparency", rt = "RichText", tr = "TextTruncate", lh = "LineHeight", abc = "AutoButtonColor",
	pt = "PlaceholderText", pc = "PlaceholderColor3", ctf = "ClearTextOnFocus", te = "TextEditable",
	ml = "MultiLine", im = "Image", st = "ScaleType", ic = "ImageColor3", it = "ImageTransparency",
	cs = "CanvasSize", acs = "AutomaticCanvasSize", sbt = "ScrollBarThickness", sbc = "ScrollBarImageColor3",
	sd = "ScrollingDirection", vsi = "VerticalScrollBarInset", sbit = "ScrollBarImageTransparency",
	cr = "CornerRadius", c = "Color", th = "Thickness", tp = "Transparency", asm = "ApplyStrokeMode",
	ljm = "LineJoinMode", of = "Offset", en = "Enabled", pa = "Padding", so = "SortOrder",
	fd = "FillDirection", ha = "HorizontalAlignment", va = "VerticalAlignment", cls = "CellSize",
	clp = "CellPadding", fdm = "FillDirectionMaxCells", sc = "StartCorner", pl = "PaddingLeft",
	pr = "PaddingRight", ptp = "PaddingTop", pb = "PaddingBottom", sca = "Scale", mxt = "MaxTextSize",
	mnt = "MinTextSize", n = "Name", ff = "FontFace",
}
function state.buildNewHub()
	local nodes = state.newHubLayout()
	local built, roots = {}, {}
	for index, node in ipairs(nodes) do
		local inst = Instance.new(node[1])
		for key, value in pairs(node[3]) do
			local property = KEYS[key]
			if property then pcall(function() inst[property] = value end) end
		end
		for key, value in pairs(node[4] or {}) do inst:SetAttribute(key, value) end
		built[index] = inst
	end
	for index, node in ipairs(nodes) do
		if node[2] == 0 then roots[built[index].Name] = built[index] else built[index].Parent = built[node[2]] end
	end
	return roots.Main, roots.OpenButton
end
end

function state.installNewHub()
	local shadowWindow, shadowMini = window, miniLogo
	local main, openButton = state.buildNewHub()
	assert(main and openButton, "Layout da hub nova incompleto")
	local hub = {main = main, open = openButton, pages = main.Pages, header = main.Header, nav = main.Nav, pageHeader = main.PageHeader}
    local explanationNames={Desc=true,Caption=true,Description=true,Hint=true,Note=true,Sub=true}
    local function readableExplanation(node)
        if not node:IsA("TextLabel") or not explanationNames[node.Name] then return end
        if node.TextSize>=14 then return end
        node.TextSize=14
        node.TextScaled=false
        node.TextWrapped=true
        node.TextTruncate=Enum.TextTruncate.None
        node.AutomaticSize=Enum.AutomaticSize.Y
        local row=node.Parent
        if row and row:FindFirstChild("Toggle") and row.Parent and row.Parent:FindFirstChildOfClass("UIListLayout") then
            row.AutomaticSize=Enum.AutomaticSize.Y
        end
    end
    for _,node in ipairs(main:GetDescendants()) do readableExplanation(node) end
    connect(main.DescendantAdded,function(node) task.defer(function()
        if node.Parent then readableExplanation(node) end
    end) end)
    state.refreshExplanationText=function()
        for _,node in ipairs(main:GetDescendants()) do readableExplanation(node) end
    end
    local removedRuneReuse=hub.pages.Runas:FindFirstChild("Section_CONFIGURAR RUNAS")
    if removedRuneReuse then
        local row=removedRuneReuse:FindFirstChild("Row_EquipLast")
        if row then row:Destroy() end
    end
    do
        local section = hub.pages.Misc.Section_INTERFACE
        local selector = section.Act_Language:Clone()
        selector.Name, selector.LayoutOrder = "Act_Layout", 7
        selector:SetAttribute("Action", "LayoutSelector")
        selector:SetAttribute("MirrorText", "LayoutSelector")
        selector:SetAttribute("KeybindLabel", nil)
        selector.Label.Text = "Trocar layout"
        selector.Parent = section
    end
    -- APEX CLAIM ROW: bind to the same persisted Auto Claim handler as other rewards.
    if state.claimRows and state.claimRows.apex then
        local section=hub.pages.AutoClaim.Section_RECOMPENSAS
        local row=section.Row_Claim_achievements:Clone()
        row.Name="Row_Claim_apex";row.LayoutOrder=7
        for _,child in ipairs(section:GetChildren()) do
            if child:IsA("GuiObject") and child.LayoutOrder>=7 then child.LayoutOrder+=1 end
        end
        row.Title.Text="Auto Collect Apex"
        row.Toggle:SetAttribute("Bind","Claim_apex");row.Toggle:SetAttribute("Id","Claim_apex")
        row.Toggle:SetAttribute("MirrorCaption","always")
        row.Parent=section
    end
    -- END APEX CLAIM ROW
	state.newHub = hub
	local handlers = state.uiHandlers
	local CYAN, OFF = Color3.fromRGB(0, 217, 255), Color3.fromRGB(55, 76, 88)
	local ROW, DIFF_ON = Color3.fromRGB(10, 33, 43), Color3.fromRGB(0, 120, 150)
	local languageHooks, periodic = {}, {}
	local shadowCache = {}
	local function shadow(name)
		local cached = shadowCache[name]
		if cached and cached:IsDescendantOf(shadowWindow) then return cached end
		cached = shadowWindow:FindFirstChild(name, true)
		shadowCache[name] = cached
		return cached
	end
	local function invoke(control, ...)
		local handler = control and handlers[control]
		if not handler then return false end
		local ok, problem = pcall(handler, ...)
		if not ok then warn("[VykronHub] " .. control.Name .. ": " .. tostring(problem)) end
		return ok
	end
	local function link(signal, callback, group)
		local c = signal:Connect(callback)
		table.insert(group or connections, c)
		return c
	end
	local function bindText(node)
		if node:IsA("TextBox") then state.bindLanguage(node, "PlaceholderText")
		elseif node:IsA("TextLabel") or node:IsA("TextButton") then state.bindLanguage(node) end
	end
	-- Toggles: verde ligado, vermelho desligado, cinza bloqueado; transição curta.
	local GREEN, RED, LOCKED = Color3.fromRGB(34, 197, 94), Color3.fromRGB(214, 64, 64), Color3.fromRGB(72, 82, 90)
	local Tween = game:GetService("TweenService")
	local FAST = TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
	local toggleLooks=setmetatable({},{__mode="k"})
	local function paint(toggle, on)
		local locked=toggle:GetAttribute("Locked")==true
		local previous=toggleLooks[toggle]
		if previous and previous.on==(on==true) and previous.locked==locked then return end
		if previous then for _,tween in ipairs(previous.tweens) do tween:Cancel() end end
		local look={on=on==true,locked=locked,tweens={}};toggleLooks[toggle]=look
		toggle:SetAttribute("Enabled", on == true)
		local color = toggle:GetAttribute("Locked") and LOCKED or (on and GREEN or RED)
		local knob = toggle:FindFirstChild("Knob")
		local spot = knob and (on and UDim2.new(1, -(knob.Size.X.Offset + 2), 0.5, 0) or UDim2.new(0, 2, 0.5, 0))
		if toggle:IsDescendantOf(game) then
			local background=Tween:Create(toggle, FAST, {BackgroundColor3 = color});look.tweens[#look.tweens+1]=background;background:Play()
			if knob then local movement=Tween:Create(knob, FAST, {Position = spot});look.tweens[#look.tweens+1]=movement;movement:Play() end
		else
			toggle.BackgroundColor3 = color
			if knob then knob.Position = spot end
		end
		if knob then knob.BackgroundColor3 = Color3.new(1, 1, 1) end
	end
	local function paintOption(button, selected)
		local stroke = button:FindFirstChildOfClass("UIStroke")
		if button.Name:match("^Diff_") then button.BackgroundColor3 = selected and DIFF_ON or ROW end
		if stroke then stroke.Transparency = selected and 0 or 0.6 end
		local fill = button:FindFirstChild("Fill", true)
		if fill then fill.Visible = selected end
	end
    -- Trade controls share the same restrained outlined finish as Back.
    function state.styleTradeButton(button, selected, group)
        button:SetAttribute("TradeSelected", selected == true)
        button:SetAttribute("Selected", selected == true)
        button.AutoButtonColor, button.BorderSizePixel = false, 0
        button.Font, button.TextSize = Enum.Font.GothamMedium, 12
        local corner = button:FindFirstChildOfClass("UICorner")
        if not corner then corner = make("UICorner", {}, button) end
        corner.CornerRadius = UDim.new(0, 5)
        local stroke = button:FindFirstChildOfClass("UIStroke")
        if not stroke then stroke = make("UIStroke", {}, button) end
        stroke.Color, stroke.Thickness, stroke.ApplyStrokeMode = CYAN, 1, Enum.ApplyStrokeMode.Border
        local function redraw(hovered)
            if not button.Parent then return end
            local active = button:GetAttribute("TradeSelected") == true
            button.BackgroundColor3 = active and Color3.fromRGB(9, 48, 61) or Color3.fromRGB(6, 29, 39)
            button.TextColor3 = active and CYAN or colors.text
            stroke.Transparency = active and 0 or 0.45
            if hovered then
                button.BackgroundColor3 = active and Color3.fromRGB(10, 65, 78) or Color3.fromRGB(10, 43, 53)
                stroke.Transparency = 0.1
            end
        end
        redraw(false)
        if not button:GetAttribute("TradeHoverBound") then
            button:SetAttribute("TradeHoverBound", true)
            link(button.MouseEnter, function() redraw(true) end, group)
            link(button.MouseLeave, function() redraw(false) end, group)
        end
    end
	local function mirror(dst, src, prefix, withColor, group)
		local function update()
            local text=(prefix or "") .. state.sourceText(src)
            if src.Name=="DungeonStatusText" and state.autoKeysStockText then
                local stockText=state.autoKeysStockText()
                if stockText then text=text.."\n"..stockText end
            end
            state.setLocalizedText(dst,text)
			if withColor then dst.TextColor3 = src.TextColor3 end
		end
		update()
        if src.Name=="DungeonStatusText" then table.insert(periodic,update) end
		link(src:GetPropertyChangedSignal("Text"), update, group)
		if withColor then link(src:GetPropertyChangedSignal("TextColor3"), update, group) end
		if prefix then table.insert(languageHooks, update) end
		return update
	end
	local function strip(text)
		-- "›" tem 3 bytes em UTF-8: não pode ficar dentro de uma classe [ ] do padrão.
		return (text:gsub("%s+›%s*$", ""):gsub("%s+v%s*$", ""))
	end
	local function bindField(box, src, group)
        -- Visible editors own their draft until FocusLost has committed it.
        -- The hidden engine field is never focused and may refresh meanwhile.
        local editing, committing = false, false
        local modeOwner
        box.ClearTextOnFocus = false
        box.Text = src.Text
        link(box.Focused, function() editing = true;modeOwner=src:GetAttribute("ModeOwner") end, group)
        link(src:GetPropertyChangedSignal("Text"), function()
            if not editing and not committing and not box:IsFocused() then box.Text = src.Text end
        end, group)
        connectUI(box, function(enter)
            local draft = box.Text
            if modeOwner and src:GetAttribute("ModeOwner")~=modeOwner then box.Text=src.Text;editing=false;modeOwner=nil;return end
            committing = true
            src.Text = draft
            invoke(src, enter)
            box.Text = src.Text
            committing, editing = false, false
            modeOwner=nil
        end, box.FocusLost, group)
    end

	-- ===================== Toggles espelhados =====================
	local toggleMirrors = setmetatable({}, {__mode = "k"})
	state.onToggleLook = function(row, enabled)
		for _, toggle in ipairs(toggleMirrors[row] or {}) do paint(toggle, enabled) end
	end
	local function shadowEnabled(row)
		local knob = row:FindFirstChild("State") and row.State:FindFirstChild("Knob")
		return knob ~= nil and knob.Position.X.Offset > 10
	end
    local pauseRows=setmetatable({},{__mode="k"})
    local function refreshPauseNotices()
        for toggle,entry in pairs(pauseRows) do
            if not toggle.Parent or not entry.desc.Parent then pauseRows[toggle]=nil;continue end
            local reason=state.automationBlockReason(entry.id,shadowEnabled(entry.row))
            toggle:SetAttribute("PauseReason",reason)
            if reason then
                entry.reason=reason
                entry.desc.Text=reason
                entry.desc.TextColor3=Color3.fromRGB(255,196,90)
                entry.desc.TextSize=14
                entry.desc.TextWrapped=true
                entry.desc.TextTruncate=Enum.TextTruncate.None
                entry.desc.AutomaticSize=Enum.AutomaticSize.Y
                toggle.Parent.AutomaticSize=Enum.AutomaticSize.Y
            elseif entry.reason then
                entry.reason=nil;entry.desc.Text=entry.baseText;entry.desc.TextColor3=entry.baseColor
                entry.desc.TextSize=math.max(14,entry.baseSize)
                entry.desc.TextWrapped=entry.baseWrapped
                entry.desc.TextTruncate=entry.baseTruncate
                entry.desc.AutomaticSize=entry.baseAutoSize
                toggle.Parent.AutomaticSize=entry.baseRowAutoSize
            end
        end
    end
    state.refreshAutomationPauseNotices=refreshPauseNotices
    table.insert(periodic,refreshPauseNotices)
    table.insert(languageHooks,refreshPauseNotices)
	local function bindToggle(toggle, row, group)
		toggleMirrors[row] = toggleMirrors[row] or {}
		table.insert(toggleMirrors[row], toggle)
		paint(toggle, shadowEnabled(row))
		connectUI(toggle, function() invoke(row) end, nil, group)
		local desc = toggle.Parent:FindFirstChild("Desc") or toggle.Parent:FindFirstChild("Caption")
		local caption = row:FindFirstChild("Caption")
		local entry
        if desc then
            entry={id=toggle:GetAttribute("Bind") or row.Name,row=row,desc=desc,baseText=desc.Text,baseColor=desc.TextColor3,
                baseSize=desc.TextSize,baseWrapped=desc.TextWrapped,baseTruncate=desc.TextTruncate,
                baseAutoSize=desc.AutomaticSize,baseRowAutoSize=toggle.Parent.AutomaticSize}
            pauseRows[toggle]=entry
        end
        local function copyCaption(text)
            if entry then entry.baseText=text end
            if not entry or not entry.reason then desc.Text=text end
        end
		local mode = toggle:GetAttribute("MirrorCaption")
		local from = toggle:GetAttribute("MirrorCaptionFrom")
		if desc and from and shadow(from) then
			local src = shadow(from)
			link(src:GetPropertyChangedSignal("Text"), function() copyCaption(src.Text) end, group)
		elseif desc and caption and mode then
			if mode == "always" then copyCaption(caption.Text) end
			link(caption:GetPropertyChangedSignal("Text"), function() copyCaption(caption.Text) end, group)
		end
	end

	state.hubParts.craft({hub = hub, CYAN = CYAN, ROW = ROW, DIFF_ON = DIFF_ON, languageHooks = languageHooks, periodic = periodic, paint = paint})

	-- ===================== Navegação (portada do Controller da hub nova) =====================
	local PAGE_INFO = {
		Farm = {"⚔️", "FARM", "Combate, progressão e eventos.", "Farm"},
		FarmAttributes = {"⚙", "ATRIBUTOS", "Metas e distribuição", "Farm"},
		FarmHouses = {"🏠", "CASAS", "Escolha de coleta", "Farm"},
        FarmQuests = {"📜", "LIMIT BREAKER", "Missões e prioridades", "Farm"},
        LimitBreakerMissions = {"📜", "MISSÕES", "Arraste para ordenar", "Farm"},
		FarmGuild = {"🏰", "GUILDA", "Seleção de chefe", "Farm"},
		DungeonMain = {"🛡️", "DUNGEON", "›   Principal", "DungeonMain"},
		DungeonModes = {"🛡️", "DUNGEON", "›   Selecionar Modo", "DungeonMain"},
		Chaves = {"🛡️", "DUNGEON", "›   Selecionar", "DungeonMain"},
		Runas = {"🛡️", "DUNGEON", "›   Runas", "DungeonMain"},
		Cartas = {"🛡️", "DUNGEON", "›   Cartas", "DungeonMain"},
		Craft = {"⚒", "CRAFT", state.craftCompactTabs and "Organize materiais e shadows" or "Receitas e trocas", "Craft"},
		SellBuy = {"💰", "SELL / BUY", "Venda e compra de itens.", "SellBuy"},
		AutoClaim = {"🎁", "AUTO CLAIM", "Recompensas e coletas.", "AutoClaim"},
		Misc = {"⚙️", "MISC", "Configurações gerais.", "Misc"},
	}
	local TAB_TO_SHADOW = {Farm = "Farm", DungeonMain = "Dungeon", SellBuy = "Sell / Buy", AutoClaim = "Auto Claim", Misc = "Misc"}
	local tabs, stack, current = {}, {}, nil
	for _, tab in ipairs(hub.nav:GetChildren()) do
		if tab:IsA("TextButton") then tabs[tab:GetAttribute("Target")] = tab end
	end
	local function setActiveTab(target)
		for name, tab in pairs(tabs) do
			local on = name == target
			tab.BackgroundTransparency = on and 0 or 1
			tab.BackgroundColor3 = on and DIFF_ON or ROW
			tab.UIStroke.Transparency = on and 0.1 or 1
			tab.Label.TextColor3 = on and Color3.new(1, 1, 1) or Color3.fromRGB(180, 200, 208)
		end
	end
	local left = hub.pageHeader.Left
	local function show(name, push)
		if not hub.pages:FindFirstChild(name) then return end
		if push and current and current ~= name then table.insert(stack, current) end
		for _, page in ipairs(hub.pages:GetChildren()) do
			if page:IsA("GuiObject") then page.Visible = page.Name == name end
		end
		local page = hub.pages[name]
		if page:IsA("ScrollingFrame") then page.CanvasPosition = Vector2.zero end
		current = name
        if name=="Craft" then uiState.tab="Craft" save() end
		local info = PAGE_INFO[name]
		if info then
			left.Icon.Text, left.Title.Text, left.Sub.Text = info[1], info[2], info[3]
			setActiveTab(info[4])
			local sub = name == "FarmAttributes" or name == "FarmHouses" or name == "FarmGuild" or name == "FarmQuests" or name == "LimitBreakerMissions"
			left.Title.Size = UDim2.fromOffset(sub and 110 or 65, 28)
		end
		hub.pageHeader.Back.Visible = #stack > 0
		if state.refreshTradeTabs then state.refreshTradeTabs() end
        if state.refreshResponsiveLayout then state.refreshResponsiveLayout() end
	end
	state.newHubShow = show
	local function goBack()
		local previous = table.remove(stack)
		if previous then show(previous, false) end
	end
	for target, tab in pairs(tabs) do
		connectUI(tab, function()
			table.clear(stack)
			show(target, false)
			if TAB_TO_SHADOW[target] then pcall(showPage, TAB_TO_SHADOW[target]) end
		end)
	end
	connectUI(hub.pageHeader.Back, goBack)

	-- ===================== Seletor comum (substitui o ChoicePicker original) =====================
	do
		local section = hub.pages.Chaves.Section_PICKER
		local list, template, search, empty = section.Options, section.Options.OptTemplate, section.Search, section.Empty
		local rows = {}
		local function filter()
			local query, visible = string.lower(search.Text), 0
			for _, item in ipairs(list:GetChildren()) do
				if item:IsA("TextButton") and item ~= template then
					item.Visible = query == "" or string.find(item:GetAttribute("Search") or "", query, 1, true) ~= nil
					if item.Visible then visible += 1 end
				end
			end
			empty.Visible = visible == 0
		end
		link(search:GetPropertyChangedSignal("Text"), filter)
		choose = function(titleText, options, callback, context)
            local note=section:FindFirstChild("GiantsNotice")
            if note then note.Visible=false end
			for _, c in ipairs(rows) do c:Disconnect() end
			table.clear(rows)
			for _, child in ipairs(list:GetChildren()) do
				if child:IsA("TextButton") and child ~= template then child:Destroy() end
			end
			section.Head.Title.Text = titleText
			search.Text = ""
			for index, option in ipairs(options) do
				local item = template:Clone()
				item.Name, item.LayoutOrder, item.Visible = "Option", index, true
				item:SetAttribute("Template", nil)
				item:SetAttribute("Search", string.lower(tostring(option.name)))
				item.Label.Text = tostring(option.name)
                if option.selected~=nil then paintOption(item,option.selected==true) end
				local icon = item:FindFirstChild("Frame")
				if icon and type(option.image) == "string" and option.image ~= "" then
					icon.TextLabel.Visible = false
					local image = Instance.new("ImageLabel")
					image.BackgroundTransparency, image.Size, image.Image = 1, UDim2.fromScale(1, 1), option.image
					image.ScaleType = Enum.ScaleType.Fit
					image.Parent = icon
				elseif icon then
					icon.TextLabel.Text = "◆"
				end
				item.Parent = list
				bindText(item.Label)
				connectUI(item, function()
					if search:IsFocused() then search:ReleaseFocus() end
					goBack()
					callback(option.id)
				end, nil, rows)
			end
			empty.Visible = #options == 0
			show("Chaves", true)
            if context=="Craft" then
                left.Icon.Text,left.Title.Text,left.Sub.Text="⚒","CRAFT","› Shadows"
                setActiveTab("Craft")
            end
		end
	end

	-- ===================== Idioma: só o tradutor da hub decide o texto =====================
	-- A tradução automática do Roblox (AutoLocalize) reescrevia textos por cima da escolha de idioma
	-- (ex.: "DUNGEON" → "MASMORRA", "Floor" → "Andar"); fica desligada em toda a interface da hub.
	do
		local function noAuto(node)
			if node:IsA("GuiBase2d") then pcall(function() node.AutoLocalize = false end) end
		end
		noAuto(gui)
		for _, node in ipairs(gui:GetDescendants()) do noAuto(node) end
		for _, node in ipairs(main:GetDescendants()) do noAuto(node) end
		noAuto(main)
		noAuto(openButton)
		for _, node in ipairs(openButton:GetDescendants()) do noAuto(node) end
		link(gui.DescendantAdded, noAuto)
		link(main.DescendantAdded, noAuto)
	end

	-- ===================== Acabamento visual (só aparência; a lógica continua na hub original) =====================
	local fitPages
	do
		local function ensure(parent, class, name)
			local found = parent:FindFirstChild(name or class)
			if found and found:IsA(class) then return found end
			local made = Instance.new(class)
			made.Name = name or class
			made.Parent = parent
			return made
		end
		-- Ícones que a fonte do Roblox não desenha (viravam quadradinhos) trocados por emojis.
		local function iconFor(label)
			local text, parent = label.Text, label.Parent
			local holder = parent and parent.Parent
			local where = (parent and parent.Name or "") .. "/" .. (holder and holder.Name or "")
			if text == "⟳" then return "🔄" end
			if text == "∿" then return "📊" end
			if text == "♛" then return where:find("Guild", 1, true) and "🏰" or where:find("Events", 1, true) and "📅" or "🏰" end
			if text == "↗" then
				if where:find("AutoMax", 1, true) then return "⏫" end
				if where:find("Distribute", 1, true) then return "📊" end
				return "📈"
			end
			if text == "⌨" or text == "♻" or text == "♾" then return text .. "️" end
		end
		for _, node in ipairs(main:GetDescendants()) do
			if node:IsA("TextLabel") and #node.Text <= 8 then
				local replacement = iconFor(node)
				if replacement then node.Text = replacement end
			end
		end
		-- Misc: saem "Sons da Interface" e a seção "ATALHOS".
		local misc = hub.pages.Misc
		local sounds = misc.Section_INTERFACE:FindFirstChild("Row_UISounds")
		if sounds then sounds:Destroy() end
		local shortcuts = misc:FindFirstChild("Section_ATALHOS")
		if shortcuts then shortcuts:Destroy() end
		uiState.uiSounds = false
		-- Botões de ação com cara de botão: fundo, borda, seta em pílula, hover e clique.
		local BTN, BTN_HOVER = Color3.fromRGB(13, 56, 70), Color3.fromRGB(20, 82, 100)
		local DANGER, DANGER_HOVER = Color3.fromRGB(70, 20, 26), Color3.fromRGB(98, 28, 36)
		local function styleButton(button, danger)
			button.AutoButtonColor = false
			button.BackgroundTransparency = 0
			button.BackgroundColor3 = danger and DANGER or BTN
			button:SetAttribute("PolishButton", danger and "danger" or "normal")
			ensure(button, "UICorner").CornerRadius = UDim.new(0, 8)
			local stroke = ensure(button, "UIStroke")
			stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
			stroke.Color, stroke.Transparency, stroke.Thickness = danger and Color3.fromRGB(230, 80, 80) or CYAN, 0.3, 1.2
			local shine = ensure(button, "UIGradient", "Shine")
			shine.Rotation = 90
			shine.Color = ColorSequence.new(Color3.new(1, 1, 1), Color3.fromRGB(170, 190, 198))
			ensure(button, "UIScale", "Press")
			local arrow = button:FindFirstChild("Arrow")
			if arrow and arrow:IsA("TextLabel") then
				arrow.AnchorPoint, arrow.Position, arrow.Size = Vector2.new(1, 0.5), UDim2.new(1, -6, 0.5, 0), UDim2.fromOffset(20, 20)
				arrow.BackgroundTransparency, arrow.BackgroundColor3 = 0, Color3.fromRGB(6, 30, 38)
				arrow.TextColor3, arrow.Font = CYAN, Enum.Font.GothamBold
				arrow.TextXAlignment, arrow.TextYAlignment = Enum.TextXAlignment.Center, Enum.TextYAlignment.Center
				ensure(arrow, "UICorner").CornerRadius = UDim.new(1, 0)
			end
		end
		local hovered = setmetatable({}, {__mode = "k"})
		local function attachHover(button)
			if hovered[button] then return end
			hovered[button] = true
			local danger = button:GetAttribute("PolishButton") == "danger"
			local stroke, press = button:FindFirstChildOfClass("UIStroke"), button:FindFirstChild("Press")
			local function set(over)
				button.BackgroundColor3 = over and (danger and DANGER_HOVER or BTN_HOVER) or (danger and DANGER or BTN)
				if stroke then stroke.Transparency = over and 0 or 0.3 end
				if press and not over then press.Scale = 1 end
			end
			button.MouseEnter:Connect(function() set(true) end)
			button.MouseLeave:Connect(function() set(false) end)
			button.MouseButton1Down:Connect(function() if press then press.Scale = 0.97 end end)
			button.MouseButton1Up:Connect(function() if press then press.Scale = 1 end end)
		end
		local actionButtons = {
			Act_QuestObjectives = true, Nav_Attributes = true, Act_Mode = true, Act_CopyLast = true, Act_Keybind = true,
			Act_Language = true, Act_Layout = true, ModeDropdown = true, OpenModes = true, Nav_Runas = true, Nav_Chaves = true, Nav_Cartas = true,
			Back = true, MoveUp = true, MoveDown = true,
		}
		for _, node in ipairs(main:GetDescendants()) do
			if node:IsA("TextButton") then
				local parentName = node.Parent and node.Parent.Name or ""
				if node.Name == "Act_Restore" then styleButton(node, true)
				elseif actionButtons[node.Name] or (node.Name == "Button" and (parentName == "CfgChoice" or parentName == "CfgCastle")) then
					styleButton(node, false)
				end
			end
		end
		for _, node in ipairs(main:GetDescendants()) do
			if node:IsA("TextButton") and node:GetAttribute("PolishButton") then attachHover(node) end
		end
		-- Clones de templates (atributos, cartas, itens) herdam o estilo; o hover é ligado quando entram na tela.
		link(main.DescendantAdded, function(node)
			if node:IsA("TextButton") and node:GetAttribute("PolishButton") then attachHover(node) end
		end)
		-- Divisórias mais visíveis: ciano, 2 px, sumindo nas pontas.
		local function styleDivider(line, vertical)
			line.BackgroundColor3, line.BackgroundTransparency, line.BorderSizePixel = CYAN, 0.35, 0
			if vertical then line.Size = UDim2.new(line.Size.X.Scale, 2, line.Size.Y.Scale, line.Size.Y.Offset)
			else line.Size = UDim2.new(line.Size.X.Scale, line.Size.X.Offset, 0, 2) end
			local fade = ensure(line, "UIGradient", "Fade")
			fade.Rotation = vertical and 90 or 0
			fade.Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.15, 0.1),
				NumberSequenceKeypoint.new(0.85, 0.1), NumberSequenceKeypoint.new(1, 1)})
		end
		for _, node in ipairs(main:GetDescendants()) do
			if node.ClassName == "Frame" and #node:GetChildren() == 0 and node.BackgroundTransparency < 1 then
				local size = node.Size
				if size.Y.Scale == 0 and size.Y.Offset <= 2 and (size.X.Scale > 0 or size.X.Offset >= 40) then styleDivider(node, false)
				elseif size.X.Scale == 0 and size.X.Offset <= 2 and size.Y.Offset >= 12 then styleDivider(node, true) end
			end
		end
		-- Divisória entre linhas de opção vizinhas do mesmo quadro.
		local function addRowDividers(container)
			local rows = {}
			for _, child in ipairs(container:GetChildren()) do
				if child:IsA("Frame") and child.Name:match("^Row_") then table.insert(rows, child) end
			end
			table.sort(rows, function(a, b)
				if a.LayoutOrder ~= b.LayoutOrder then return a.LayoutOrder < b.LayoutOrder end
				return a.Position.Y.Offset < b.Position.Y.Offset
			end)
			for index = 1, #rows - 1 do
				local line = Instance.new("Frame")
				line.Name, line.Position, line.Size = "RowDivider", UDim2.new(0, 40, 1, 0), UDim2.new(1, -52, 0, 2)
				line.ZIndex = rows[index].ZIndex
				line.Parent = rows[index]
				styleDivider(line, false)
			end
		end
		local seen = {}
		for _, node in ipairs(main:GetDescendants()) do
			local parent = node.Parent
			if node:IsA("Frame") and node.Name:match("^Row_") and parent and not seen[parent] then
				seen[parent] = true
				addRowDividers(parent)
			end
		end
		-- Status e Atividade: o quadro cresce até mostrar todas as linhas abaixo do título.
		local activity = hub.pages.Farm:FindFirstChild("Activity")
		if activity then
			activity.AutomaticSize = Enum.AutomaticSize.Y
			activity.ClipsDescendants = false
			ensure(activity, "UIPadding").PaddingBottom = UDim.new(0, 10)
			local list = activity:FindFirstChild("StatusList")
			if list then list.AutomaticSize = Enum.AutomaticSize.Y end
		end
		-- Atributos: cada opção no seu próprio quadro (posição, Atual, Meta e Auto Max separados).
		local attributes = hub.pages.FarmAttributes
		local statList, template = attributes.StatList, attributes.StatTemplate
		local layout = statList:FindFirstChildOfClass("UIListLayout")
		if layout then layout.Padding = UDim.new(0, 12) end
		statList.Position = UDim2.fromOffset(0, attributes.Distribution.Size.Y.Offset + 14)
		statList.AutomaticSize = Enum.AutomaticSize.Y
		local distStroke = attributes.Distribution:FindFirstChildOfClass("UIStroke")
		if distStroke then distStroke.Color, distStroke.Transparency, distStroke.Thickness = CYAN, 0.1, 1.5 end
		template.Size = UDim2.new(1, -1, 0, 146)
		template.BackgroundColor3 = Color3.fromRGB(9, 30, 40)
		local cardStroke = template:FindFirstChildOfClass("UIStroke")
		if cardStroke then cardStroke.Color, cardStroke.Transparency, cardStroke.Thickness = CYAN, 0.35, 1.2 end
		local badge = template.Band.Icon
		badge.Size, badge.Position = UDim2.fromOffset(22, 22), UDim2.fromOffset(9, 2)
		badge.BackgroundTransparency, badge.BackgroundColor3 = 0, CYAN
		badge.TextColor3, badge.Font, badge.TextScaled = Color3.fromRGB(4, 22, 30), Enum.Font.GothamBold, false
		badge.TextSize, badge.TextXAlignment, badge.TextYAlignment = 13, Enum.TextXAlignment.Center, Enum.TextYAlignment.Center
		ensure(badge, "UICorner").CornerRadius = UDim.new(1, 0)
		local function tile(name, x, caption)
			local box = Instance.new("Frame")
			box.Name, box.Position, box.Size = name, UDim2.new(x, x == 0 and 10 or 5, 0, 33), UDim2.new(0.5, -15, 0, 50)
			box.BackgroundColor3, box.BorderSizePixel = Color3.fromRGB(5, 20, 28), 0
			ensure(box, "UICorner").CornerRadius = UDim.new(0, 8)
			local stroke = ensure(box, "UIStroke")
			stroke.Color, stroke.Transparency = CYAN, 0.7
			local head = Instance.new("TextLabel")
			head.Name, head.BackgroundTransparency, head.Position, head.Size = "Caption", 1, UDim2.fromOffset(10, 4), UDim2.new(1, -20, 0, 14)
			head.Font, head.TextSize, head.TextColor3, head.TextXAlignment = Enum.Font.GothamBold, 10, colors.muted, Enum.TextXAlignment.Left
			head.Text = caption
			head.Parent = box
			box.Parent = template
			return box
		end
		local current = tile("CurrentBox", 0, "ATUAL")
		local value = Instance.new("TextLabel")
		value.Name, value.BackgroundTransparency, value.Position, value.Size = "Value", 1, UDim2.fromOffset(10, 20), UDim2.new(1, -20, 0, 24)
		value.Font, value.TextSize, value.TextColor3, value.TextXAlignment = Enum.Font.GothamBold, 15, Color3.new(1, 1, 1), Enum.TextXAlignment.Left
		value.Text = "—"
		value.Parent = current
		local goal = tile("GoalBox", 0.5, "META TOTAL")
		local box = template.Target
		box.Parent, box.Position, box.Size = goal, UDim2.fromOffset(8, 20), UDim2.new(1, -16, 0, 24)
		template.TargetLabel.Visible = false
		local maxBox = Instance.new("Frame")
		maxBox.Name, maxBox.Position, maxBox.Size = "AutoMaxBox", UDim2.fromOffset(10, 91), UDim2.new(1, -20, 0, 45)
		maxBox.BackgroundColor3, maxBox.BorderSizePixel = Color3.fromRGB(4, 16, 22), 0
		ensure(maxBox, "UICorner").CornerRadius = UDim.new(0, 8)
		maxBox.Parent = template
		local autoMax = template.Row_AutoMax
		autoMax.Parent, autoMax.Position, autoMax.Size = maxBox, UDim2.fromOffset(0, 3), UDim2.new(1, 0, 0, 39)
		for _, label in ipairs({current.Caption, goal.Caption}) do bindText(label) end
		-- Rolagem em toda página de posição fixa (a Farm não tinha): o canvas segue o conteúdo, inclusive no modo compacto.
		fitPages = function()
			local zoom = main:FindFirstChildOfClass("UIScale")
			for _, page in ipairs(hub.pages:GetChildren()) do
				if page:IsA("ScrollingFrame") and page.AutomaticCanvasSize == Enum.AutomaticSize.None then
					local function update()
                        if state.responsiveWindow then return end
						local factor = zoom and zoom.Scale > 0 and zoom.Scale or 1
						local bottom = 0
						for _, child in ipairs(page:GetChildren()) do
							if child:IsA("GuiObject") and child.Visible then
								bottom = math.max(bottom, child.Position.Y.Offset + child.AbsoluteSize.Y / factor)
							end
						end
						page.CanvasSize = UDim2.fromOffset(0, math.ceil(bottom + 14))
					end
					page.ScrollingDirection, page.ScrollBarThickness = Enum.ScrollingDirection.Y, math.max(page.ScrollBarThickness, 4)
					for _, child in ipairs(page:GetChildren()) do
						if child:IsA("GuiObject") then
							link(child:GetPropertyChangedSignal("AbsoluteSize"), update)
							link(child:GetPropertyChangedSignal("Visible"), update)
						end
					end
					if zoom then link(zoom:GetPropertyChangedSignal("Scale"), update) end
					update()
				end
			end
		end
	end

	-- ===================== Ligações declarativas (atributos do layout) =====================
	local function wire(node)
		if node:GetAttribute("Template") or node:GetAttribute("Retired") then return end
		local bind, action, field = node:GetAttribute("Bind"), node:GetAttribute("Action"), node:GetAttribute("Field")
		if node.Name == "Toggle" and bind then
			local row = shadow(bind)
			if row then bindToggle(node, row) else node:SetAttribute("Locked", true) node.Parent.Visible = false warn("[VykronHub] Controle original ausente: " .. bind) end
		elseif node.Name == "Toggle" and node:GetAttribute("Local") then
			local key = node:GetAttribute("Local")
			paint(node, uiState[key] == true)
			connectUI(node, function()
				uiState[key] = not uiState[key]
				paint(node, uiState[key])
				if state.applyLocalOption then state.applyLocalOption(key) end
				save()
			end)
		elseif action and node:IsA("GuiButton") then
			local control = shadow(action)
			if not control then node.Visible = false warn("[VykronHub] Ação original ausente: " .. action) return end
			connectUI(node, function() invoke(control) end)
			local mirrorName = node:GetAttribute("MirrorText")
			if mirrorName then
				local label = node:FindFirstChild("Label", true) or (node:IsA("TextButton") and node)
				local src = shadow(mirrorName)
				if label and src then
					local function update() state.setLocalizedText(label, strip(state.sourceText(src))) end
					update()
					link(src:GetPropertyChangedSignal("Text"), update)
				end
			end
			local tabOf = node:GetAttribute("TabOf")
			if tabOf then
				local function update() paintOption(node, control.TextColor3 == colors.accent) end
				update()
				link(control:GetPropertyChangedSignal("TextColor3"), update)
			end
		elseif field and node:IsA("TextBox") then
			local src = shadow(field)
			if src then bindField(node, src) else node.Parent.Visible = false end
		elseif node:GetAttribute("FieldText") and node:IsA("TextBox") then
			local src = shadow(node:GetAttribute("FieldText"))
			if src then link(node:GetPropertyChangedSignal("Text"), function() src.Text = node.Text end) end
		end
		local mirrorName = node:GetAttribute("Mirror")
		if mirrorName and node:IsA("TextLabel") then
			local src = shadow(mirrorName)
			if src then mirror(node, src, node:GetAttribute("MirrorPrefix"), node:GetAttribute("MirrorColor")) end
		end
		local showWith = node:GetAttribute("ShowWith")
		if showWith and node:IsA("GuiObject") then
			local src = shadow(showWith)
			if src then
				node.Visible = src.Visible
				link(src:GetPropertyChangedSignal("Visible"), function() node.Visible = src.Visible end)
			end
		end
		if node:IsA("TextButton") and node:GetAttribute("Target") and node.Name:match("^Nav_") then
			local target, open = node:GetAttribute("Target"), node:GetAttribute("OpenShadow")
			connectUI(node, function()
				if open then invoke(shadow(open)) end
				show(target, true)
			end)
		end
	end
    do
        local farm = hub.pages.Farm
        local section = farm.Events
        local source = section.Row_AutoPumpkin
        local row = source:Clone()
        row.Name = "Row_AutoPumpkinKing"
        row.Position = source.Position + UDim2.fromOffset(0, 41)
        row.Title.Text = "Auto Pumpkin King"
        row.Caption.Text = "Aguarda o chefe na World Arena; funciona sem Auto Farm Mobs."
        row.Toggle:SetAttribute("Bind", "AutoPumpkinKing")
        row.Toggle:SetAttribute("Id", "AutoPumpkinKing")
        row.Toggle:SetAttribute("MirrorCaption", "always")
        row.Toggle:SetAttribute("Enabled", false)
        for _, child in ipairs(section:GetChildren()) do
            if child:IsA("GuiObject") and child.Position.Y.Offset > source.Position.Y.Offset then child.Position += UDim2.fromOffset(0, 41) end
        end
        section.Size += UDim2.fromOffset(0, 41)
        farm.Activity.Position += UDim2.fromOffset(0, 41)
        row.Parent = section
        source.Toggle:SetAttribute("MirrorCaption", "always")
