	-- ===================== Listas dinâmicas espelhadas =====================
	local function orderedChildren(container, filterFn)
		local items = {}
		for _, child in ipairs(container:GetChildren()) do
			if child:IsA("GuiObject") and (not filterFn or filterFn(child)) then table.insert(items, child) end
		end
		table.sort(items, function(a, b)
			if a.LayoutOrder ~= b.LayoutOrder then return a.LayoutOrder < b.LayoutOrder end
			return a.Position.Y.Offset < b.Position.Y.Offset
		end)
		return items
	end
	local function textLabels(node)
		local labels = {}
		for _, child in ipairs(node:GetChildren()) do
			if child:IsA("TextLabel") then table.insert(labels, child) end
		end
		return labels
	end
	local function mirrorList(source, render)
		if not source then return end
		local group, pending = {}, false
		local function run()
			pending = false
			if not alive or not source.Parent then return end
			for _, c in ipairs(group) do c:Disconnect() end
			table.clear(group)
			local ok, problem = pcall(render, group)
			if not ok then warn("[VykronHub] lista: " .. tostring(problem)) end
		end
		local function schedule()
			if pending then return end
			pending = true
			task.defer(run)
		end
		link(source.ChildAdded, schedule)
		link(source.ChildRemoved, schedule)
		link(source.DescendantAdded, schedule)
		link(source.DescendantRemoving, schedule)
		run()
		table.insert(languageHooks, schedule)
		table.insert(cleanupCallbacks, function() for _, c in ipairs(group) do c:Disconnect() end end)
	end
	local function clearClones(container, keep)
		for _, child in ipairs(container:GetChildren()) do
			if child:IsA("GuiObject") and not keep[child] then child:Destroy() end
		end
	end

	state.hubParts.farmRebirth({hub = hub, shadow = shadow, invoke = invoke, link = link, bindText = bindText, paint = paint, mirror = mirror, bindField = bindField, orderedChildren = orderedChildren, textLabels = textLabels, mirrorList = mirrorList, clearClones = clearClones})

