	local function rankChips(sourceName, container)
		local template = container.ChipTemplate
		mirrorList(shadow(sourceName), function(group)
			clearClones(container, {[template] = true})
			for index, item in ipairs(orderedChildren(shadow(sourceName), function(c) return c:IsA("TextButton") end)) do
				local labels = textLabels(item)
                local nameLabel = item:FindFirstChild("RankName") or labels[1]
