				local chip = template:Clone()
				chip.Name, chip.Visible, chip.LayoutOrder = item.Name, true, index
				if nameLabel then mirror(chip.Label, nameLabel, nil, true, group) end
				local function update()
					local selected = item:GetAttribute("RankSelected")
                    if selected == nil then selected = markLabel and markLabel.Text == "✓" end
                    chip.Mark.Text = selected and "✓" or "○"
					paintOption(chip, selected)
				end
				update()
                link(item:GetAttributeChangedSignal("RankSelected"), update, group)
				if markLabel then link(markLabel:GetPropertyChangedSignal("Text"), update, group) end
				connectUI(chip, function() invoke(item) update() end, nil, group)
				chip.Parent = container
			end
		end)
	end
