	state.hubParts.responsivo({main = main, hub = hub, languageHooks = languageHooks, invoke = invoke, link = link, orderedChildren = orderedChildren, refreshFarmCategories = refreshFarmCategories})
    -- END RESPONSIVE VIEW

	-- ===================== Janela: troca para a hub nova =====================
