	shadowWindow.Visible, shadowMini.Visible = false, false
	link(hub.header.InputBegan, function(input) beginDrag(input, window) end)
	link(openButton.InputBegan, function(input) beginDrag(input, miniLogo) end)
	connectUI(openButton, function() if not miniDragged then toggleMinimize() end end)
	connectUI(hub.header.Close, destroy)
	-- Bordas e cantos: mesmo gesto da baseline (lado oposto ancorado, salvo ao soltar).
	local handles = {}
	for _, spec in ipairs({
		{"DragLeft", UDim2.new(0, 0, 0, 14), UDim2.new(0, 6, 1, -28)},
		{"DragRight", UDim2.new(1, -6, 0, 14), UDim2.new(0, 6, 1, -28)},
		{"DragTop", UDim2.new(0, 14, 0, 0), UDim2.new(1, -28, 0, 6)},
		{"DragBottom", UDim2.new(0, 14, 1, -6), UDim2.new(1, -28, 0, 6)},
		{"TopLeft", UDim2.new(0, 0, 0, 0), UDim2.fromOffset(14, 14)},
		{"TopRight", UDim2.new(1, -14, 0, 0), UDim2.fromOffset(14, 14)},
		{"BottomLeft", UDim2.new(0, 0, 1, -14), UDim2.fromOffset(14, 14)},
		{"BottomRight", UDim2.new(1, -14, 1, -14), UDim2.fromOffset(14, 14)},
	}) do
		local handle = Instance.new("TextButton")
		handle.Name, handle.Text, handle.Position, handle.Size = "Resize" .. spec[1], "", spec[2], spec[3]
		handle.BackgroundTransparency, handle.AutoButtonColor, handle.ZIndex = 1, false, 20
		handle.Parent = main
		table.insert(handles, handle)
		link(handle.InputBegan, function(input) if state.beginResize then state.beginResize(input, spec[1]) end end)
	end
	-- Header minus uses the same full-window minimization as the configured keybind.
    state.collapsedHeight = nil
    hub.header.Minimize.Text = "–"
    connectUI(hub.header.Minimize, toggleMinimize)
	setMinimized(false)

	-- ===================== Estado inicial e atualização periódica =====================
