-- Shared dodge registry, context, arena constraints and bounded diagnostics.
do
local api={profiles={},order={},revision=0,diagnostics={entries={},total=0,dropped=0}}
state.dodge=api
local diagnosticKeys={}
api.fallback={id="__native",label="Native telegraphs",arena={part="Floor",shape="rectangle",margin=3}}
function api.finite(value)
    return type(value)=="number" and value==value and value~=math.huge and value~=-math.huge
end
function api.vector(value)
    return typeof(value)=="Vector3" and api.finite(value.X) and api.finite(value.Y) and api.finite(value.Z)
end
function api.register(profile)
    assert(type(profile)=="table" and type(profile.id)=="string" and #profile.id>0 and #profile.id<=128 and profile.id~="__native","Invalid dodge profile id")
    for _,key in ipairs({"decode","observe","bounds","pick","beforeStep","detect","complete","decoded"}) do
        assert(profile[key]==nil or type(profile[key])=="function","Invalid dodge callback: "..key)
    end
    assert(profile.attacks==nil or type(profile.attacks)=="table","Invalid dodge attack catalog")
    assert(profile.arena==nil or type(profile.arena)=="table","Invalid dodge arena")
    assert(profile.scope==nil or profile.scope=="dungeon" or profile.scope=="farm","Invalid dodge scope")
    assert(profile.priority==nil or api.finite(profile.priority),"Invalid dodge priority")
    if profile.arena then
        assert(profile.arena.shape==nil or profile.arena.shape=="rectangle" or profile.arena.shape=="circle","Invalid arena shape")
        assert(profile.arena.part==nil or type(profile.arena.part)=="string" and #profile.arena.part>0 and #profile.arena.part<=128,"Invalid arena part")
    end
    api.profiles[profile.id]=profile;api.revision+=1
    api.order={}
    for _,value in pairs(api.profiles) do api.order[#api.order+1]=value end
    table.sort(api.order,function(a,b)
        local ap,bp=tonumber(a.priority) or 0,tonumber(b.priority) or 0
        return ap==bp and a.id<b.id or ap>bp
    end)
    return profile
end
function api.model(map,profile)
    local main=workspace:FindFirstChild("__Main")
    for _,name in ipairs({"__World","__Dungeon"}) do
        local folder=main and main:FindFirstChild(name)
        local model=folder and folder:FindFirstChild(map)
        if model then return model end
    end
end
function api.roomKey(map,profile)
    profile=profile or api.profiles[map] or api.fallback
    return storage:GetAttribute(profile.roomAttribute or "CurrentRoom")
end
function api.arena(map,profile)
    profile=profile or api.profiles[map] or api.fallback
    local model=api.model(map,profile)
    if not model then return nil end
    local room=api.roomKey(map,profile)
    local container=model
    if room~=nil then
        local number=tonumber(room)
        if not api.finite(number) then return nil end
        container=model:FindFirstChild((profile.roomPrefix or "Room_")..tostring(math.floor(number)))
    end
    local config=profile.arena or {}
    local part=container
    for segment in (config.part or "Floor"):gmatch("[^.]+") do part=part and part:FindFirstChild(segment) end
    if part and part:IsA("BasePart") then return part,config end
end
function api.resolveMap()
    local map=storage:GetAttribute("DungeonMap")
    if type(map)=="string" and #map>0 and #map<=128 then
        if api.profiles[map] then return map end
        if api.arena(map,api.fallback) then return map end
    end
    for _,profile in ipairs(api.order) do
        if profile.detect then
            local ok,match=pcall(profile.detect)
            if ok and match then return profile.id end
            if not ok then api.log(profile.id,{Event="ProfileDetect"},"detector error: "..tostring(match)) end
        end
    end
end
function api.profile(map)
    if not map then return nil end
    return api.profiles[map] or (api.arena(map,api.fallback) and api.fallback or nil)
end
function api.allowed(map)
    local profile=api.profile(map)
    if not profile or state.stopped then return false end
    if profile.scope=="farm" then return farmEnabled() end
    return (dungeon.enabled or state.questOwnsRun and autoQuest.journey and state.questOwnsRun(autoQuest.journey.mode)) and insideDungeon()
end
function api.enabled(map)
    return state.eclipseDodge==true and api.profile(map)~=nil
end
function api.complete(map)
    if storage:GetAttribute("DungeonCompleted")==true then return true end
    local profile=api.profile(map)
    if profile and profile.complete then
        local ok,result=pcall(profile.complete)
        if not ok then api.log(map,{Event="ProfileComplete"},"completion callback error: "..tostring(result)) end
        return not ok or result==true
    end
    return false
end
function api.pointAllowed(map,point)
    if not api.vector(point) then return false end
    local profile=api.profile(map)
    if not profile then return false end
    if profile.bounds then
        local ok,result=pcall(profile.bounds,point)
        if not ok then api.log(map,{Event="ProfileBounds"},"bounds callback error: "..tostring(result)) end
        return ok and result==true
    end
    local part,config=api.arena(map,profile)
    if not part then return profile.allowUnbounded==true end
    local localPoint=part.CFrame:PointToObjectSpace(point)
    local margin=api.finite(config.margin) and math.max(0,config.margin) or 3
    local x,z=part.Size.X/2-margin,part.Size.Z/2-margin
    if x<=0 or z<=0 or math.abs(localPoint.Y)>64 then return false end
    if config.shape=="circle" then
        return Vector3.new(localPoint.X,0,localPoint.Z).Magnitude<=math.min(x,z)
    end
    return math.abs(localPoint.X)<=x and math.abs(localPoint.Z)<=z
end
function api.log(map,packet,reason)
    if type(packet)~="table" then packet={} end
    local power=type(packet.Power)=="string" and packet.Power:sub(1,80) or ""
    local event=type(packet.Event)=="string" and packet.Event:sub(1,80) or ""
    reason=tostring(reason):sub(1,160)
    local key=tostring(map)..":"..event..":"..power..":"..reason
    local data=api.diagnostics;data.total+=1
    local row=diagnosticKeys[key]
    if row then row.count+=1;row.last=os.clock();return end
    if #data.entries>=64 then
        local old=table.remove(data.entries,1);diagnosticKeys[old.key]=nil;data.dropped+=1
    end
    local fields,n={},0
    for name,value in pairs(packet) do
        if type(name)=="string" and n<16 then fields[name:sub(1,80)]=typeof(value);n+=1 end
    end
    row={key=key,map=tostring(map),event=event,power=power,reason=reason,count=1,first=os.clock(),last=os.clock(),fields=fields}
    if api.finite(packet.Radius) then row.radius=packet.Radius end
    if api.finite(packet.Duration) then row.duration=packet.Duration end
    if type(packet.List)=="table" then
        row.kinds={}
        for i,value in ipairs(packet.List) do
            if i>16 then break end
            if type(value)=="table" then row.kinds[#row.kinds+1]=tostring(value.Kind):sub(1,40) end
        end
    end
    diagnosticKeys[key]=row;data.entries[#data.entries+1]=row
end
function api.exportDiagnostics()
    local path="VykronHub/Diagnostics/AutoDodge-"..player.UserId..".json"
    local ok,problem=pcall(function()
        if type(makefolder)=="function" then pcall(makefolder,"VykronHub");pcall(makefolder,"VykronHub/Diagnostics") end
        writefile(path,Http:JSONEncode({build=state.build,diagnostics=api.diagnostics}))
    end)
    return ok,ok and path or tostring(problem)
end
function api.validateZone(zone,now)
    if type(zone)~="table" or not api.vector(zone.origin) or not api.finite(zone.radius)
        or zone.radius<=0 or zone.radius>500 or not api.finite(zone.untilAt)
        or zone.untilAt<=now or zone.untilAt>now+120 then return false end
    if zone.startsAt~=nil and not api.finite(zone.startsAt) then return false end
    if zone.kind=="safe" then
        if type(zone.safePoints)~="table" or #zone.safePoints==0 or #zone.safePoints>32
            or not api.finite(zone.safeRadius) or zone.safeRadius<=0 then return false end
        if zone.safeRadius>500 then return false end
        for _,point in ipairs(zone.safePoints) do if not api.vector(point) then return false end end
    elseif zone.kind=="ring" then
        if not api.vector(zone.safeDirection) or zone.safeDirection.Magnitude<0.001
            or not api.finite(zone.safeCos) or zone.safeCos< -1 or zone.safeCos>1 then return false end
        local direction=Vector3.new(zone.safeDirection.X,0,zone.safeDirection.Z)
        if not api.finite(direction.Magnitude) or direction.Magnitude<0.001 then return false end
        zone.safeDirection=direction/direction.Magnitude
    elseif zone.kind=="cone" or zone.direction then
        if not api.vector(zone.direction) or zone.direction.Magnitude<0.001 or not api.finite(zone.length)
            or zone.length<=0 or zone.length>500 then return false end
        local direction=Vector3.new(zone.direction.X,0,zone.direction.Z)
        if not api.finite(direction.Magnitude) or direction.Magnitude<0.001 then return false end
        zone.direction=direction/direction.Magnitude
        if zone.kind=="cone" and (not api.finite(zone.cosAngle) or zone.cosAngle< -1 or zone.cosAngle>1) then return false end
    elseif zone.kind~=nil and zone.kind~="circle" then return false end
    return true
end
function api.decode(map,packet,now,serverNow)
    local profile=api.profile(map)
    if not profile then return nil end
    local ok,zones,problem=pcall(function()
        if packet.Event=="Telegraph" then
            return api.nativeZones(packet,now,serverNow,{margin=profile.nativeMargin or 2,padding=profile.nativePadding or 0.5})
        end
        if type(packet.Power)~="string" then return nil end
        if profile.ignore and profile.ignore[packet.Power] then return {} end
        if profile.decode then return profile.decode(packet,now,serverNow) end
        if profile.attacks then return api.definitionZones(packet,now,profile.attacks) end
    end)
    if not ok then api.log(map,packet,"decoder error: "..tostring(zones));return nil end
    if problem then api.log(map,packet,problem) end
    if not zones and (type(packet.Power)=="string" or packet.Event=="Telegraph") then api.log(map,packet,"unsupported attack; profile adjustment required") end
    if zones~=nil and type(zones)~="table" then api.log(map,packet,"invalid decoder result");return nil end
    return zones,problem
end
end
-- Shared hazard geometry and escape search; compatibility API names preserved.
do
local function flat(v) return Vector3.new(v.X,0,v.Z) end
    -- RAID GEOMETRY POLICY
    function state.raidDanger(position, zones, now)
        for _, zone in ipairs(zones) do
            if now < zone.untilAt and now >= (zone.startsAt or -math.huge) then
                local relative = flat(position - zone.origin)
                local distance = relative.Magnitude
                if zone.kind == "safe" then
                    if distance <= zone.radius then
                        local protected = false
                        for _, point in ipairs(zone.safePoints) do
                            if flat(position - point).Magnitude <= zone.safeRadius then protected = true break end
                        end
                        if not protected then return true end
                    end
                elseif zone.kind == "ring" then
                    if distance <= zone.radius then
                        if distance < 3 or relative.Unit:Dot(zone.safeDirection) < zone.safeCos then return true end
                    end
                elseif zone.kind == "cone" then
                    if distance <= zone.length and (distance < 2 or relative.Unit:Dot(zone.direction) >= zone.cosAngle) then return true end
                else
                    if zone.direction then
                        local projected = math.clamp(relative:Dot(zone.direction), 0, zone.length)
                        distance = (relative - zone.direction * projected).Magnitude
                    end
                    if distance <= zone.radius then return true end
                end
            end
        end
        return false
    end
    function state.raidPickEscape(position, enemy, zones, now, project)
        local selected, best
        local origins = {position}
        if enemy then table.insert(origins, enemy) end
        -- Wide rings: leave the whole announced radius before considering a narrow gap.
        -- Do not apply this rule to light-column attacks, which require their native Safe points.
        for _, zone in ipairs(zones) do
            if zone.kind=="ring" and now<zone.untilAt and now>=(zone.startsAt or -math.huge) then
                local radius=zone.radius+8
                for index=0,23 do
                    local angle=index*math.pi/12
                    local point=zone.origin+Vector3.new(math.cos(angle)*radius,0,math.sin(angle)*radius)
                    if flat(point-position).Magnitude<=160 then
                        local candidate=project(Vector3.new(point.X,position.Y,point.Z))
                        if candidate and not state.raidDanger(candidate,zones,now) then
                            local score=flat(candidate-position).Magnitude
                            if not best or score<best then selected,best=candidate,score end
                        end
                    end
                end
            end
        end
        if selected then return selected end
        -- Native safe columns are preferred to generic circles around the boss.
        for _, zone in ipairs(zones) do
            if now < zone.untilAt and now >= (zone.startsAt or -math.huge) then
                local points = zone.kind == "safe" and zone.safePoints or {}
                if zone.kind == "ring" then
                    points = {zone.origin + zone.safeDirection * 12, zone.origin + zone.safeDirection * 24, zone.origin + zone.safeDirection * 36}
                end
                for _, point in ipairs(points) do
                    if flat(point-position).Magnitude <= 140 then
                        local candidate = project(Vector3.new(point.X,position.Y,point.Z))
                        if candidate and not state.raidDanger(candidate,zones,now) then
                            local score = flat(candidate-position).Magnitude
                            if not best or score < best then selected,best=candidate,score end
                        end
                    end
                end
            end
        end
        if selected then return selected end
        for _, origin in ipairs(origins) do
            for _, radius in ipairs({4, 7, 10, 16, 24, 36, 48, 64, 80, 100, 128}) do
                for index = 0, 15 do
                    local angle = index * math.pi / 8
                    local candidate = origin + Vector3.new(math.cos(angle) * radius, 0, math.sin(angle) * radius)
                    if (candidate - position).Magnitude > 160 then continue end
                    local grounded = project(candidate)
                    if grounded and not state.raidDanger(grounded, zones, now) then
                        local rangePenalty = enemy and math.max(0, (grounded - enemy).Magnitude - 8) * 4 or 0
                        local score = (grounded - position).Magnitude + rangePenalty
                        if not best or score < best then selected, best = grounded, score end
                    end
                end
            end
        end
        return selected
    end
    -- END RAID GEOMETRY POLICY
end
-- Shared named-attack decoder: circles, beams, cones, dashes, points, rings and safe areas.
do
local function flat(v) return Vector3.new(v.X,0,v.Z) end
    local function scalar(value, fallback, lo, hi)
        local n=tonumber(value)
        return n and n==n and n~=math.huge and math.clamp(n,lo,hi) or fallback
    end
    function state.dodge.definitionZones(packet, now,definitions)
        local def=definitions[packet.Power]
        if not def then return nil end
        local zones={}
        local initial=typeof(packet.InitialPos)=="CFrame" and packet.InitialPos or nil
        local origin=typeof(packet.EndPos)=="Vector3" and packet.EndPos or initial and initial.Position
        local hit=scalar(packet.HitAt,def.hit,0,30)
        local radius=scalar(packet.Radius,def.radius or 8,0.5,200)
        local function add(zone)
            zone.power=packet.Power
            zone.untilAt=zone.untilAt or now+hit+scalar(packet.Life,def.life or 0.8,0.2,25)
            table.insert(zones,zone)
        end
        if def.kind=="safe" then
            local points={}
            if def.safeField~="Points" and typeof(packet.Safe)=="Vector3" then table.insert(points,packet.Safe)
            elseif def.safeField~="Safe" and type(packet.Points)=="table" then
                for _,p in ipairs(packet.Points) do if typeof(p)=="Vector3" then table.insert(points,p) end if #points>=32 then break end end
            end
            if not origin or #points==0 then return zones,"Safe-zone packet missing origin or safe positions." end
            add({kind="safe",origin=origin,radius=radius+3,safePoints=points,
                safeRadius=math.max(0.5,scalar(packet.SafeRadius,def.safeRadius,1,50)-1.5)})
        elseif def.kind=="points" then
            for index,p in ipairs(type(packet.Points)=="table" and packet.Points or {}) do
                if typeof(p)=="Vector3" then add({origin=p,radius=radius+2,
                    untilAt=now+hit+(index-1)*scalar(packet.Stagger,def.stagger or 0,0,2)+scalar(packet.Life,def.life or 0.8,0.2,25)}) end
                if index>=32 then break end
            end
        elseif def.kind=="ring" then
            if not origin then return zones,"Ring packet missing origin." end
            for _,ring in ipairs(type(packet.Rings)=="table" and packet.Rings or {}) do
                if typeof(ring.Dir)=="Vector3" and flat(ring.Dir).Magnitude>0.001 then
                    local at=hit+scalar(ring.Delay,0,0,25)
                    add({kind="ring",origin=origin,radius=scalar(packet.Length,def.length,5,200),
                        safeDirection=flat(ring.Dir).Unit,safeCos=math.cos(math.rad(math.max(5,scalar(packet.Gap,def.gap,10,160)/2-5))),
                        startsAt=now,untilAt=now+at+1.2})
                end
                if #zones>=16 then break end
            end
        elseif def.kind=="line" or def.kind=="cone" or def.kind=="dash" then
            if not initial or flat(initial.LookVector).Magnitude<0.001 then return zones,"Directional packet missing InitialPos." end
            local direction=flat(initial.LookVector).Unit
            local length=scalar(packet.Length,def.length,1,200)
            if def.kind=="dash" and typeof(packet.EndPos)=="Vector3" then
                local travel=flat(packet.EndPos-initial.Position)
                if travel.Magnitude>0.001 then direction,length=travel.Unit,travel.Magnitude end
            end
            add({kind=def.kind=="cone" and "cone" or nil,origin=initial.Position,direction=direction,length=length,
                radius=packet.Width and scalar(packet.Width,def.radius*2,1,100)/2+2 or radius+2,
                cosAngle=def.kind=="cone" and math.cos(math.rad(scalar(packet.Angle,def.angle,5,170)/2+5)) or nil})
        elseif origin then add({origin=origin,radius=radius+2})
        else return zones,"Area packet missing origin." end
        return zones
    end
end
-- Verified shared Telegraph envelope. Unknown kinds are recorded, never guessed.
do
local api=state.dodge
local function scalar(value,fallback,lo,hi)
    local n=tonumber(value)
    return api.finite(n) and math.clamp(n,lo,hi) or fallback
end
function api.nativeZones(packet,now,serverNow,settings)
    if type(packet.List)~="table" then return nil,"Telegraph missing List" end
    settings=settings or {}
    local margin=scalar(settings.margin,2,0,20)
    local padding=scalar(settings.padding,0.5,0,3)
    local age=api.finite(serverNow) and api.finite(tonumber(packet.At)) and math.clamp(serverNow-tonumber(packet.At),0,30) or 0
    local zones,problem={}
    for i,row in ipairs(packet.List) do
        if i>64 then break end
        if type(row)~="table" or (row.Kind~="Slam" and row.Kind~="Drop") then problem="unsupported Telegraph kind"
        elseif not api.vector(row.Position) or not api.finite(tonumber(row.Radius)) or tonumber(row.Radius)<=0
            or not api.finite(tonumber(row.Duration)) then problem="Telegraph missing valid Position, Radius or Duration"
        else
            local elapsed=math.max(age,scalar(row.Elapsed,0,0,30))
            local remaining=scalar(row.Delay,0,0,10)+scalar(row.Duration,1,0.1,10)+scalar(row.HoldImpact,0.28,0,3)-elapsed+padding
            if remaining>0 then zones[#zones+1]={origin=row.Position,radius=scalar(row.Radius,11,1,100)+margin,untilAt=now+remaining,power=packet.Power or "Telegraph"} end
        end
    end
    return zones,problem
end
end
-- Pure Architect event policy. Statue sequences and shield windows are not hazards.
do
local function number(v,fallback,lo,hi)
    local n=tonumber(v)
    return n and n==n and n~=math.huge and n~=-math.huge and math.clamp(n,lo,hi) or fallback
end
function state.architectSequence(packet,now)
    if type(packet)~="table" or packet.Power~="StatueSequence" or type(packet.Points)~="table" then return nil end
    local points={}
    for _,point in ipairs(packet.Points) do
        if typeof(point)~="Vector3" or #points>=12 then return nil end
        points[#points+1]=point
    end
    if #points==0 then return nil end
    local step=number(packet.Step,0.8,0.1,5)
    return {points=points,index=1,readyAt=now+#points*step+0.5,nextAt=0,waiting=false,accepting=false}
end
function state.architectZones(packet,now,serverNow)
    local zones={}
    if type(packet)~="table" then return zones end
    if packet.Power=="StatueSequence" or packet.Power=="SystemOverride" then return zones end
    local function add(point,radius,duration,direction,length)
        if typeof(point)=="Vector3" then
            zones[#zones+1]={origin=point,radius=radius,direction=direction,length=length,untilAt=now+duration,power=packet.Power or "Telegraph"}
        end
    end
    if packet.Event=="Telegraph" then
        return state.dodge.nativeZones(packet,now,serverNow,{margin=5,padding=0.5})
    end
    if packet.Power=="LaserGaze" and typeof(packet.InitialPos)=="CFrame" then
        local look=packet.InitialPos.LookVector
        local flat=Vector3.new(look.X,0,look.Z)
        if flat.Magnitude>0.001 then add(packet.InitialPos.Position,8,2.7,flat.Unit,55) end
    elseif packet.Power=="DeleteMark" then add(packet.EndPos,13,1.9)
    elseif packet.Power=="Judgement" or packet.Power=="DivineClap" or packet.Power=="CodeRain" then
        local duration=packet.Power=="Judgement" and number(packet.Hit,1,0.1,10)+0.9 or 2.1
        for i,point in ipairs(type(packet.Points)=="table" and packet.Points or {}) do
            if i>32 then break end
            add(point,packet.Power=="Judgement" and 16 or 13,duration+(i-1)*0.04)
        end
    end
    return zones
end
end
-- Architect mechanics remain separate; only hazard interpretation and bounds are registered here.
do
state.dodge.register({id="ArchitectDungeon",label="Architect",priority=30,nativeMargin=5,nativePadding=0.5,
    detect=function() return state.architectActive and state.architectActive() end,
    ignore={StatueSequence=true,SystemOverride=true},
    observe=function(packet) if state.observeArchitect then state.observeArchitect(packet) end end,
    decode=function(packet,now,serverNow)
        local supported={LaserGaze=true,DeleteMark=true,Judgement=true,DivineClap=true,CodeRain=true}
        if not supported[packet.Power] then return nil end
        return state.architectZones(packet,now,serverNow)
    end,
    bounds=function(point) return state.architectPointAllowed and state.architectPointAllowed(point)==true end,
    pick=function(position,zones,now,project)
        if state.architectFaithEscape then return state.architectFaithEscape(position,zones,now,project) end
    end,
    complete=function()
        return state.nativeRestartPending~=nil and state.nativeRestartPending.room==storage:GetAttribute("CurrentRoom")
    end})
end
-- Eclipse attack data; shared shape decoder owns geometry.
do
    local attacks = {
        MoonSlash={kind="line",hit=1.4,length=60,radius=5},
        ExcaliburMorgan={kind="line",hit=3,length=90,radius=10},
        AlterDash={kind="dash",hit=1.1,length=30,radius=7},
        CoronaBurst={kind="circle",hit=1.3,radius=13},
        CoronaBang={kind="circle",hit=1.6,radius=6},
        DragonRoar={kind="cone",hit=1.3,length=44,angle=70},
        BlackFlamePools={kind="points",hit=1,radius=7.5,life=8},
        EndlessInferno={kind="safe",safeField="Safe",hit=3,radius=45,safeRadius=10},
        BlackCoffin={kind="circle",hit=2,radius=7},
        KyokaSlash={kind="line",hit=1.2,length=56,radius=5},
        TengaiShinsei={kind="points",hit=2.2,radius=15,stagger=0.12},
        SusanooSlash={kind="line",hit=1.4,length=72,radius=7},
        BlackSunPulse={kind="safe",safeField="Points",hit=3,radius=45,safeRadius=8},
        MoonRings={kind="ring",hit=1.6,length=60,gap=50},
    }
    function state.eclipseZones(packet,now) return state.dodge.definitionZones(packet,now,attacks) end
    state.dodge.register({id="EclipseCourtRaid",label="Eclipse Court",attacks=attacks,allowUnbounded=true,priority=20,
        detect=function() return storage:GetAttribute("RaidTitle")=="THE ECLIPSE COURT" end,
        decoded=function(packet,zones,problem,now)
            state.eclipseDodgeInfo={power=packet.Power,zones=zones and #zones or 0,problem=problem,at=now}
        end})
end
-- Preserve the older native HallPower estimates as explicit per-mode adapters.
do
local function flat(v) return Vector3.new(v.X,0,v.Z) end
local function decode(packet,now,definitions)
    local info=definitions[packet.Power]
    if not info then return nil end
    local points={}
    if type(packet.Points)=="table" then
        for _,point in ipairs(packet.Points) do
            if typeof(point)=="Vector3" then points[#points+1]=point end
            if #points>=32 then break end
        end
    elseif typeof(packet.EndPos)=="Vector3" then points={packet.EndPos}
    elseif typeof(packet.InitialPos)=="CFrame" then points={packet.InitialPos.Position}
    elseif rootPart() then points={rootPart().Position} end
    local zones={}
    for index,point in ipairs(points) do
        local direction
        if info[3] and typeof(packet.InitialPos)=="CFrame" then
            direction=flat(packet.InitialPos.LookVector)
            direction=direction.Magnitude>0.001 and direction.Unit or nil
        end
        zones[#zones+1]={origin=point,radius=info[1],direction=direction,length=info[3],untilAt=now+info[2]+index*0.04}
    end
    return zones
end
local manor={BloodGeyser={6,3},BloodRain={7,3},CrimsonSlash={7,3,32},BatSwarm={9,3}}
state.dodge.register({id="BloodmoonManor",label="Bloodmoon Manor",priority=10,roomAttribute="ManorDoor",allowUnbounded=true,
    detect=function() return storage:GetAttribute("ManorDoor")~=nil end,
    decode=function(packet,now) return decode(packet,now,manor) end})
local dragon={GiantQuake={10,3},WhiteFlame={10,3},DragonFire={10,3},FlameBreath={10,4,48},
    NightmareBreath={12,4,48},KamishDive={12,3},Meteor={10,3},HiveCall={12,4},IceClones={12,4},EclipseFall={18,4}}
state.dodge.register({id="DragonMonarchRaid",label="Dragon Monarch",allowUnbounded=true,
    decode=function(packet,now) return decode(packet,now,dragon) end})
end
do
    -- A interface nova é a única. Se ela não montar, o hub segue rodando as automações sem janela (aviso no console).
    local hostWindow, hostMini, hostScale = window, miniLogo, scale
    local ok, problem = pcall(state.installNewHub)
    if not ok then
        warn("[VykronHub] Hub nova indisponível: " .. tostring(problem))
        window, miniLogo, scale = hostWindow, hostMini, hostScale
        if state.newHub and state.newHub.main then state.newHub.main:Destroy() end
        if state.newHub and state.newHub.open then state.newHub.open:Destroy() end
        state.newHub = nil
        window.Visible = false   -- o contêiner dos controles nunca aparece
    end
    state.layoutViews = {modernWindow = window, modernMini = miniLogo, modernScale = scale,
        expandedWidth = uiState.width, expandedHeight = uiState.height}
    function state.applyLayout(name)
        if not alive or not gui.Parent or not state.newHub then return false end
        local views = state.layoutViews
        local modernWindow, modernMini, modernScale = views.modernWindow, views.modernMini, views.modernScale
        modernWindow.Visible = true
        modernMini.Visible = false
        window, miniLogo, scale = modernWindow, modernMini, modernScale
        state.collapsedHeight = nil
        if state.newHub then
            local view = state.newHub
            view.pages.Visible, view.nav.Visible, view.pageHeader.Visible = true, true, true
            view.header.Minimize.Text = "–"
        end
        if name == "Horizontal" then
            if not state.responsiveWindow then
                if not state.compactLayoutActive and (state.layoutApplied or not uiState.portraitSize) then
                    uiState.portraitSize = {width = uiState.width, height = uiState.height}
                end
                state.compactLayoutActive = false
                if state.switchResponsiveView then state.switchResponsiveView(true) end
            end
        else
            if state.responsiveWindow then
                state.rememberResponsiveSize()
                if state.switchResponsiveView then state.switchResponsiveView(false) end
                local portrait = uiState.portraitSize
                uiState.width, uiState.height = portrait and portrait.width or 500, portrait and portrait.height or 820
            end
            if name == "Compact" then
                if not state.compactLayoutActive then views.expandedWidth, views.expandedHeight = uiState.width, uiState.height end
                state.compactLayoutActive = true
                uiState.width, uiState.height = 480, 600
            elseif state.compactLayoutActive then
                state.compactLayoutActive = false
                uiState.width, uiState.height = views.expandedWidth, views.expandedHeight
            end
        end
        if Input.TouchEnabled then modernMini.Visible = true end
        if state.refreshLayoutLabel then state.refreshLayoutLabel() end
        setMinimized(false)
        window.Visible, window.Interactable = true, true
        gui.Enabled = true
        state.windowUnit = nil
        window:SetAttribute("SavedWidth", nil)
        fit()
        state.applyMiniIcon()
        state.layoutApplied = true
        save()
        return true
    end
    state.applyLayout(uiState.layout or "NewHub")
    gui.Enabled = true
end

connect(gui.Destroying, destroy)
-- RAID GUARD: native attack announcements; visual bounds remain provisional until live validation.
do
local function installRaidGuard()
    local guard = {zones = {}, hunt = false, ownedHide = false, nextPrompt = 0}
    local api=state.dodge
    api.runtime=guard
    local seen=setmetatable({},{__mode="k"})
    local function activeMap() return api.resolveMap() end
    function api.cancel()
        guard.zones={};guard.nextPlan=0;state.raidPaused=nil
    end
    local function syncContext(map,root)
        local profile=api.profile(map)
        local model=api.model(map,profile)
        local room=api.roomKey(map,profile)
        local arena=api.arena(map,profile)
        if guard.map~=map or guard.root~=root or guard.model~=model or guard.room~=room
            or guard.arena~=arena or guard.revision~=api.revision then
            guard.zones,guard.hunt,guard.ownedHide={},false,false
            guard.nextPlan=0;guard.warnRoot=nil;guard.warnSerial=(guard.warnSerial or 0)+1
            state.raidPaused,state.manorHuntActive=nil,nil
            guard.map,guard.root,guard.model,guard.room,guard.arena,guard.revision=map,root,model,room,arena,api.revision
            seen=setmetatable({},{__mode="k"})
        end
        guard.context={map=map,root=root,room=room,model=model,profile=profile,zones=guard.zones}
        return profile,guard.context
    end
    function state.observeRaidPower(packet)
        if not alive or type(packet)~="table" then return end
        local map=activeMap()
        if not api.allowed(map) or api.complete(map) then return end
        local profile,context=syncContext(map,rootPart())
        if profile.observe then
            local ok,problem=pcall(profile.observe,packet,context)
            if not ok then api.log(map,packet,"observer error: "..tostring(problem)) end
        end
        if state.panic or player.GameplayPaused or not api.enabled(map) then api.cancel();return end
        if seen[packet] then return end
        seen[packet]=true
        local now=os.clock()
        local zones,problem=api.decode(map,packet,now,workspace:GetServerTimeNow())
        if zones then
            for _,zone in ipairs(zones) do
                if api.validateZone(zone,now) then
                    if #guard.zones>=96 then table.remove(guard.zones,1) end
                    table.insert(guard.zones,zone)
                else api.log(map,packet,"invalid or expired hazard geometry") end
            end
            guard.nextPlan=0
            guard.lastPower=packet.Power or packet.Event
        end
        if profile.decoded then
            local ok,detail=pcall(profile.decoded,packet,zones,problem,now)
            if not ok then api.log(map,packet,"diagnostic callback error: "..tostring(detail)) end
        end
    end
    local bridges = require(storage.BridgeNet2)
    -- HallPower is the actual renderer entry point. Preserve its result and restore on reload.
    guard.capture = false
    if type(hookfunction) == "function" then
        local ok = pcall(function()
            local renderer = require(storage.Effects.HallPower)
            assert(type(renderer) == "function", "HallPower indisponível")
            local original
            original = hookfunction(renderer, function(packet, ...)
                pcall(state.observeRaidPower, packet)
                return original(packet, ...)
            end)
            table.insert(cleanupCallbacks, function() pcall(hookfunction, renderer, original) end)
        end)
        guard.capture = ok
    end
    state.raidGuardCapture = guard.capture
    local manor = state.pausableBridge(bridges.ReferenceBridge("MANOR_EVENT"))
    local worldParams = RaycastParams.new()
    worldParams.FilterType = Enum.RaycastFilterType.Include
    local function prepareWorld()
        local main = workspace:FindFirstChild("__Main")
        local geometry = {}
        for _, name in ipairs({"__World", "__Dungeon"}) do
            local folder = main and main:FindFirstChild(name)
            if folder then table.insert(geometry, folder) end
        end
        worldParams.FilterDescendantsInstances = geometry
    end
    local function floorAt(candidate, current)
        local hit = workspace:Raycast(candidate + Vector3.new(0, 10, 0), Vector3.new(0, -24, 0), worldParams)
        if not hit or hit.Normal.Y < 0.6 or math.abs(hit.Position.Y + 3 - current.Y) > 10 then return nil end
        local destination = hit.Position + Vector3.new(0, 3, 0)
        if workspace:Raycast(current, destination - current, worldParams) then return nil end
        if workspace:Raycast(destination, Vector3.new(0, 3, 0), worldParams) then return nil end
        return destination
    end
    local shelterCache, shelterAt = {}, -math.huge
    local function nearestShelter(root, now)
        if now - shelterAt >= 1 then
            shelterAt, shelterCache = now, {}
            local main = workspace:FindFirstChild("__Main")
            local world = main and main:FindFirstChild("__World")
            for _, node in ipairs(world and world:GetDescendants() or {}) do
                if node:IsA("ProximityPrompt") and node.Name == "ManorHide" then table.insert(shelterCache, node) end
            end
        end
        local selected, destination, best
        for _, prompt in ipairs(shelterCache) do
            if not prompt.Parent or not prompt.Enabled then continue end
            local parent = prompt.Parent
            local position = parent:IsA("Attachment") and parent.WorldPosition or parent:IsA("BasePart") and parent.Position
            if not position then continue end
            local distance = (position - root.Position).Magnitude
            local number = tonumber(storage:GetAttribute("ManorDoor"))
            if number then
                local ancestor, roomName = prompt.Parent, "Room_" .. tostring(math.floor(number))
                while ancestor and ancestor.Name ~= roomName do ancestor = ancestor.Parent end
                if not ancestor then continue end
            elseif distance > 120 then continue end
            local hit = workspace:Raycast(position + Vector3.new(0, 10, 0), Vector3.new(0, -48, 0), worldParams)
            local safe = hit and hit.Normal.Y >= 0.6 and math.abs(hit.Position.Y + 3 - root.Position.Y) <= 16
                and hit.Position + Vector3.new(0, 3, 0) or nil
            if safe and (not best or distance < best) then selected, destination, best = prompt, safe, distance end
        end
        return selected, destination
    end
    local function move(root, destination)
        root.AssemblyLinearVelocity = Vector3.zero
        root.CFrame = living(state.target, enemyFolder()) and CFrame.lookAt(destination, state.target.Position + Vector3.new(0, 3, 0)) or CFrame.new(destination)
        state.lastFarmPosition = root.Position
    end
    for _, name in ipairs({"DUNGEON_EVENT", "ENEMY_EVENT"}) do
        local subscription = bridges.ReferenceBridge(name):Connect(function(packet)
            pcall(state.observeRaidPower, packet)
            if type(packet) == "table" and packet.Event == "ManorHunt" then
                if not dungeon.enabled or activeMap() ~= "BloodmoonManor" then return end
                syncContext(activeMap(),rootPart())
                if packet.Phase == "Warn" or packet.Phase == "Move" or packet.Phase == "Catch" then
                    guard.hunt, state.manorHuntActive, state.raidPaused = true, true, true
                    state.target, state.searchPosition, state.manorBusy = nil, nil, nil
                    generation += 1
                    -- One immediate shelter attempt per hunt; subsequent retries keep their normal delay.
                    if packet.Phase == "Warn" and guard.warnRoot ~= rootPart() then
                        guard.warnRoot = rootPart()
                        guard.warnSerial = (guard.warnSerial or 0) + 1
                        local serial, expectedRoot = guard.warnSerial, guard.warnRoot
                        task.spawn(function()
                            if not alive or state.panic or not dungeon.enabled or player.GameplayPaused
                                or not guard.hunt or serial ~= guard.warnSerial or activeMap() ~= "BloodmoonManor"
                                or rootPart() ~= expectedRoot or not expectedRoot
                                or player:GetAttribute("ManorHidden") == true then return end
                            prepareWorld()
                            shelterAt = -math.huge
                            local prompt, destination = nearestShelter(expectedRoot, os.clock())
                            if not prompt or not destination then
                                state.raidGuardStatus = "Caça ativa: nenhum esconderijo acessível foi carregado."
                                return
                            end
                            move(expectedRoot, destination)
                            state.raidGuardStatus = "Indo ao esconderijo da Countess..."
                            local parent = prompt.Parent
                            local position = parent and (parent:IsA("Attachment") and parent.WorldPosition or parent:IsA("BasePart") and parent.Position)
                            if position and prompt.Enabled and (expectedRoot.Position - position).Magnitude <= prompt.MaxActivationDistance
                                and os.clock() >= guard.nextPrompt and type(state.firePrompt) == "function" then
                                guard.nextPrompt = os.clock() + math.max(1, prompt.HoldDuration + 0.5)
                                guard.ownedHide = true
                                pcall(state.firePrompt, prompt, prompt.HoldDuration)
                            end
                        end)
                    end
                elseif packet.Phase == "End" then
                    guard.hunt, state.manorHuntActive, guard.warnRoot = false, nil, nil
                    guard.warnSerial = (guard.warnSerial or 0) + 1
                end
            end
        end)
        table.insert(cleanupCallbacks, function() subscription:Disconnect() end)
    end
    function state.raidGuardStep()
        local map,root,now=activeMap(),rootPart(),os.clock()
        if not api.allowed(map) or api.complete(map) then
            api.cancel();guard.hunt=false;state.manorHuntActive=nil
            return false
        end
        if state.panic or player.GameplayPaused or state.leaving or state.autoLeaving or state.rebirthing then api.cancel();return false end
        if not root or player:GetAttribute("Mounted") or player:GetAttribute("Swimming") then api.cancel();return false end
        local profile,context=syncContext(map,root)
        -- Manor's native shelter mechanic is a mode adapter, not a guessed hazard shape.
        if not api.enabled(map) and map~="BloodmoonManor" then api.cancel();return false end
        if map~="BloodmoonManor" then state.manorHuntActive=nil end
        prepareWorld()
        if map == "BloodmoonManor" then
            local hidden = player:GetAttribute("ManorHidden") == true
            if guard.hunt or state.manorHuntActive or hidden then
                state.raidPaused = true
                if state.target then generation += 1 end
                state.target, state.searchPosition = nil, nil
                if hidden then
                    state.raidGuardStatus = "Escondido da Countess. Aguardando fim da caça..."
                    if not guard.hunt and not state.manorHuntActive and guard.ownedHide and now >= guard.nextPrompt then
                        guard.nextPrompt = now + 2
                        manor:Fire({Event = "Leave"})
                    end
                    return true
                end
                local prompt, destination = nearestShelter(root, now)
                state.raidGuardStatus = prompt and "Indo ao esconderijo da Countess..." or "Caça ativa: nenhum esconderijo acessível foi carregado."
                if not prompt then return true end
                move(root, destination)
                local parent = prompt.Parent
                local position = parent:IsA("Attachment") and parent.WorldPosition or parent.Position
                if (root.Position - position).Magnitude <= prompt.MaxActivationDistance and now >= guard.nextPrompt and type(state.firePrompt) == "function" then
                    guard.nextPrompt, guard.ownedHide = now + math.max(1, prompt.HoldDuration + 0.5), true
                    pcall(state.firePrompt, prompt, prompt.HoldDuration)
                end
                return true
            end
        end
        if not api.enabled(map) then api.cancel();return false end
        local function project(candidate)
            local point=floorAt(candidate,root.Position)
            return point and api.pointAllowed(map,point) and point or nil
        end
        context.project=project
        context.move=function(destination)
            local point=api.vector(destination) and project(destination)
            if point and not state.raidDanger(point,guard.zones,now) then move(root,point);return true end
            return false
        end
        context.now=now
        if profile.beforeStep then
            local ok,controlled=pcall(profile.beforeStep,context)
            if not ok then
                api.log(map,{Event="ProfileStep"},"mechanic callback error: "..tostring(controlled))
                state.raidPaused=true;state.raidGuardStatus="Auto Dodge: profile callback failed.";return true
            end
            if controlled then state.raidPaused=true;return true end
        end
        state.raidPaused = nil
        for index = #guard.zones, 1, -1 do if guard.zones[index].untilAt <= now then table.remove(guard.zones, index) end end
        local enemy = not state.architectBusy and living(state.target, enemyFolder()) and state.target.Position or nil
        local attackPosition = enemy and enemy + Vector3.new(0, 3, 4)
        if not state.raidDanger(root.Position, guard.zones, now) and (not attackPosition or not state.raidDanger(attackPosition, guard.zones, now)) then return false end
        state.raidPaused=true
        if now < (guard.nextPlan or 0) then return true end
        guard.nextPlan = now + 0.15
        local safe
        if profile.pick then
            local ok,result=pcall(profile.pick,root.Position,guard.zones,now,project)
            if ok then safe=result else api.log(map,{Event="ProfilePick"},"escape callback error: "..tostring(result)) end
        end
        safe=api.vector(safe) and project(safe) or nil
        if safe and state.raidDanger(safe,guard.zones,now) then safe=nil end
        if not safe then safe=state.raidPickEscape(root.Position,enemy,guard.zones,now,project) end
        if safe then
            move(root, safe)
            state.raidGuardStatus = "Desviando da área anunciada..."
        else
            state.raidPaused = true
            state.raidGuardStatus = "Ataque anunciado: sem posição segura confirmada."
            api.log(map,{Power=guard.lastPower},"no confirmed safe destination inside arena")
        end
        return true
    end
end
installRaidGuard()
end
-- END RAID GUARD
-- Architect state machine. The existing Auto Dungeon preference owns this worker.
do
local runtime={serial=0,nextPrompt=0,seen=setmetatable({},{__mode="k"})}
state.architectRuntime=runtime
local function mapModel()
    local main=workspace:FindFirstChild("__Main")
    local world=main and main:FindFirstChild("__World")
    return world and world:FindFirstChild("ArchitectDungeon")
end
function state.architectActive()
    local explicit=storage:GetAttribute("DungeonMap")
    if explicit and explicit~="ArchitectDungeon" then return false end
    return insideDungeon() and mapModel()~=nil
end
local function context()
    local map=mapModel();local root=rootPart()
    local room=tonumber(storage:GetAttribute("CurrentRoom"))
    if runtime.map~=map or runtime.root~=root or runtime.room~=room then
        runtime.serial+=1;runtime.map=map;runtime.root=root;runtime.room=room
        runtime.sequence=nil;runtime.nextPrompt=0;runtime.problem=nil;runtime.busy=false
        runtime.approach=nil
    end
    return map,room,root,map and room and map:FindFirstChild("Room_"..tostring(room))
end
local function active()
    return alive and dungeon.enabled and state.architectActive() and storage:GetAttribute("DungeonCompleted")~=true
        and not (state.nativeRestartPending and state.nativeRestartPending.room==storage:GetAttribute("CurrentRoom"))
end
function state.architectPuzzleActive()
    if not active() then return false end
    local room=tonumber(storage:GetAttribute("CurrentRoom"))
    return room==2 or room==4 or room==6
end
local function floorOf(room) return room and room:FindFirstChild("Floor") end
-- Native visible faith circle. Keep the player's footprint away from its outer edge.
local function faithArea(room)
    local obra=room and room:FindFirstChild("Obra")
    local arena=obra and obra:FindFirstChild("AT2_Arena")
    local circle=arena and arena:FindFirstChild("AT2_Arena_metal")
    if not circle or not circle:IsA("BasePart") then return nil end
    local radius=math.min(circle.Size.X,circle.Size.Z)/2-3
    if radius<=0 then return nil end
    return circle,radius
end
function state.architectPointAllowed(point)
    if not state.architectActive() then return true end
    local map=mapModel();local n=tonumber(storage:GetAttribute("CurrentRoom"))
    local room=map and n and map:FindFirstChild("Room_"..n);local floor=floorOf(room)
    if not floor or not floor:IsA("BasePart") then return false end
    if n==6 then
        local circle,radius=faithArea(room)
        if not circle then return false end
        local offset=circle.CFrame:PointToObjectSpace(point)
        if Vector3.new(offset.X,0,offset.Z).Magnitude>radius then return false end
    end
    local p=floor.CFrame:PointToObjectSpace(point)
    return math.abs(p.X)<=math.max(0,floor.Size.X/2-3) and math.abs(p.Z)<=math.max(0,floor.Size.Z/2-3)
        and math.abs(p.Y)<=60
end
function state.architectFaithEscape(position,zones,now,project)
    if not active() or tonumber(storage:GetAttribute("CurrentRoom"))~=6 then return nil end
    local _,_,_,room=context()
    local circle,radius=faithArea(room)
    if not circle then return nil end
    local seeds={circle.Position}
    local attacks=room:FindFirstChild("Attacks")
    local positions=attacks and attacks:FindFirstChild("AttackPos")
    for _,marker in ipairs(positions and positions:GetChildren() or {}) do
        if marker:IsA("BasePart") then seeds[#seeds+1]=marker.Position end
    end
    for _,scale in ipairs({0.5,0.9}) do
        for i=0,23 do
            local angle=i*math.pi/12
            seeds[#seeds+1]=circle.Position+Vector3.new(math.cos(angle)*radius*scale,0,math.sin(angle)*radius*scale)
        end
    end
    local selected,best
    for _,seed in ipairs(seeds) do
        local candidate=Vector3.new(seed.X,position.Y,seed.Z)
        if not state.architectPointAllowed(candidate) or state.raidDanger(candidate,zones,now) then continue end
        local clearance=radius
        for _,zone in ipairs(zones) do
            if now<zone.untilAt then
                local offset=candidate-zone.origin
                clearance=math.min(clearance,Vector3.new(offset.X,0,offset.Z).Magnitude-zone.radius)
            end
        end
        local score=clearance-(candidate-position).Magnitude*0.04
        if not best or score>best then
            local grounded=project(candidate)
            if grounded and state.architectPointAllowed(grounded) and not state.raidDanger(grounded,zones,now) then
                selected,best=grounded,score
            end
        end
    end
    return selected
end
function state.architectEnemyAllowed(enemy)
    return not state.architectActive() or state.architectPointAllowed(enemy.Position)
end
local function ownMovement(root,point,room,look)
    local floor=floorOf(room)
    if not floor or not floor:IsA("BasePart") then return false end
    local height=floor.Position.Y+floor.Size.Y/2
    if room.Name=="Room_6" then
        local circle=faithArea(room)
        if not circle then return false end
        height=math.max(height,circle.Position.Y+circle.Size.Y/2)
    end
    local target=Vector3.new(point.X,height+3,point.Z)
    if not state.architectPointAllowed(target) then return false end
    root.AssemblyLinearVelocity=Vector3.zero
    root.CFrame=look and CFrame.lookAt(target,Vector3.new(look.X,target.Y,look.Z)) or CFrame.new(target)
    state.lastFarmPosition=target
    return true
end
function state.observeArchitect(packet)
    if not active() or type(packet)~="table" then return end
    local _,room=context()
    if room~=4 then return end
    if packet.Event=="UpdateLabel" and type(packet.Message)=="string" and packet.Message:find("Praise the God: round",1,true) then
        if runtime.sequence then runtime.sequence.accepting=true;runtime.sequence.readyAt=math.max(runtime.sequence.readyAt,os.clock()+0.1) end
        return
    end
    if packet.Power~="StatueSequence" then return end
    if runtime.seen[packet] then return end
    runtime.seen[packet]=true
    -- A new announcement supersedes every pending action of the old sequence.
    local sequence=state.architectSequence(packet,os.clock())
    if not sequence then runtime.problem="Sequência de estátuas incompleta.";return end
    runtime.serial+=1;runtime.sequence=sequence;runtime.nextPrompt=0;runtime.problem=nil;runtime.busy=false
end
local function matchingPrompt(room,point)
    local folder=room and room:FindFirstChild("Praise")
    local selected,best
    for _,v in ipairs(folder and folder:GetDescendants() or {}) do
        if v:IsA("ProximityPrompt") and v.Enabled then
            local p=v.Parent
            local position=p and p:IsA("Attachment") and p.WorldPosition or p and p:IsA("BasePart") and p.Position
            local d=position and (Vector3.new(position.X,0,position.Z)-Vector3.new(point.X,0,point.Z)).Magnitude
            if d and d<=4 and (not best or d<best) then selected,best=v,d end
        end
    end
    return selected
end
-- Check the avatar's volume, rather than assuming a fixed offset clears the pedestal.
function state.architectPraiseStand(room,prompt,point)
    local floor=floorOf(room)
    if not floor or not floor:IsA("BasePart") then return nil end
    local height=floor.Position.Y+floor.Size.Y/2+3
    local vertical=height-point.Y
    local range=prompt.MaxActivationDistance-0.75
    if range<=0 or vertical*vertical>=range*range then return nil end
    local reach=math.sqrt(range*range-vertical*vertical)
    if reach<4 then return nil end
    local toward=floor.Position-point
    toward=Vector3.new(toward.X,0,toward.Z)
    toward=toward.Magnitude<0.1 and Vector3.new(0,0,1) or toward/toward.Magnitude
    local side=Vector3.new(-toward.Z,0,toward.X)
    local filter=OverlapParams.new()
    filter.FilterType=Enum.RaycastFilterType.Include
    filter.FilterDescendantsInstances={room}
    filter.RespectCanCollide=true
    for _,angle in ipairs({0,25,-25,50,-50,75,-75}) do
        local radians=math.rad(angle)
        local direction=toward*math.cos(radians)+side*math.sin(radians)
        for _,distance in ipairs({reach,reach*0.85,reach*0.7}) do
            if distance<4 then continue end
            local position=point+direction*distance
            position=Vector3.new(position.X,height,position.Z)
            if state.architectPointAllowed(position)
                and #workspace:GetPartBoundsInBox(CFrame.new(position),Vector3.new(4,5,4),filter)==0 then
                return position
            end
        end
    end
end
function state.architectPriority(folder,position)
    if not active() then return nil,false end
    local room=tonumber(storage:GetAttribute("CurrentRoom"))
    if room~=7 and room~=8 then return nil,false end
    local boss,window,distance
    for _,enemy in ipairs(folder and folder:GetChildren() or {}) do
        if living(enemy,folder) and state.architectEnemyAllowed(enemy) then
            local id=enemy:GetAttribute("Id")
            if id==(room==7 and "GodStatue" or "TheArchitect") then boss=enemy end
            if room==8 and id=="SystemWindow" and enemy:GetAttribute("Shield")~=true then
                local d=(enemy.Position-position).Magnitude
                if not distance or d<distance then window,distance=enemy,d end
            end
        end
    end
    if window then return window,false end
    if boss and boss:GetAttribute("Shield")==true then return nil,true end
    return boss,false
end
function state.architectSummary()
    if not dungeon.enabled or not state.architectActive() then return nil end
    if state.raidPaused then return state.raidGuardStatus end
    if state.architectBusy and state.architectStatus then return state.architectStatus end
    return state.architectText("Arquiteto: combate na sala %s.",tostring(storage:GetAttribute("CurrentRoom") or "?"))
end
function state.architectStep()
    state.architectBusy=false
    if dungeon.enabled and state.architectActive() and state.nativeRestartPending
        and state.nativeRestartPending.room==storage:GetAttribute("CurrentRoom") then
        state.architectBusy=true;state.target=nil;state.searchPosition=nil
        state.architectStatus=state.architectText("Arquiteto: aguardando replay ou saída.")
        return true
    end
    if not active() then runtime.sequence=nil;return false end
    local map,number,root,room=context()
    if not root or state.panic or player.GameplayPaused or state.leaving or state.autoLeaving
        or player:GetAttribute("Mounted") or player:GetAttribute("Swimming") then return false end
    if not room then state.architectBusy=true;state.architectStatus=state.architectText("Arquiteto: aguardando carregar a sala.");return true end
    local puzzle=number==2 or number==4 or number==6
    if puzzle then
        state.architectBusy=true
        if state.target then generation+=1;state.target=nil end
        state.searchPosition=nil
    end
    if number==6 then
        local circle=faithArea(room)
        if not circle then
            state.architectStatus=state.architectText("Arquiteto: aguardando o círculo da prova de fé.");return true
        end
        if not state.architectPointAllowed(root.Position) then
            ownMovement(root,circle.Position,room)
            state.architectStatus=state.architectText("Arquiteto: retornando ao círculo da prova de fé.");return true
        end
    end
    -- Enter the current generated room before ordinary combat/search can select old markers.
    if not state.architectPointAllowed(root.Position) then
        local floor=floorOf(room)
        if floor and ownMovement(root,floor.Position,room) then
            state.architectBusy=true;state.architectStatus=state.architectText("Arquiteto: entrando na sala %s.",tostring(number));return true
        end
    end
    if not puzzle then return false end
    if number==2 then
        local worship=room:FindFirstChild("Worship");local target,best
        for _,v in ipairs(worship and worship:GetChildren() or {}) do
            if v:IsA("BasePart") then
                local d=(v.Position-root.Position).Magnitude
                if not best or d<best then target,best=v,d end
            end
        end
        if target then
            local door=room:FindFirstChild("UpDoor")
            ownMovement(root,target.Position,room,door and door.Position)
            state.architectStatus=state.architectText("Arquiteto: permanecendo na área de adoração.")
        else state.architectStatus=state.architectText("Arquiteto: aguardando área de adoração.") end
        return true
    elseif number==6 then
        -- Stay in this arena; Auto Dodge may move to safe points before this step.
        root.AssemblyLinearVelocity=Vector3.zero
        state.architectStatus=state.architectText("Arquiteto: prova de fé; aguardando o contador.")
        return true
    end
    local sequence=runtime.sequence;local now=os.clock()
    if runtime.problem then state.architectStatus=state.architectText(runtime.problem);return true end
    if not sequence then state.architectStatus=state.architectText("Arquiteto: aguardando uma nova sequência.");return true end
    if sequence.waiting then state.architectStatus=state.architectText("Arquiteto: sequência enviada; aguardando a próxima rodada.");return true end
    if not sequence.accepting or now<sequence.readyAt then state.architectStatus=state.architectText("Arquiteto: observando a sequência das estátuas.");return true end
    -- Keep the current position until the previous interaction has settled on the server.
    if runtime.busy or now<runtime.nextPrompt then return true end
    local prompt=matchingPrompt(room,sequence.points[sequence.index])
    if not prompt then state.architectStatus=state.architectText("Arquiteto: aguardando o prompt da estátua correta.");return true end
    local parent=prompt.Parent
    local point=parent:IsA("Attachment") and parent.WorldPosition or parent.Position
    -- Approach from the open interior of the room, never the statue marker's center.
    local approach=runtime.approach
    if not approach or approach.prompt~=prompt or now>=approach.untilAt then
        approach={prompt=prompt,stand=state.architectPraiseStand(room,prompt,point),untilAt=now+0.5}
        runtime.approach=approach
    end
    local stand=approach.stand
    if not stand then
        sequence.arrivedAt=nil;sequence.arrivedIndex=nil
        state.architectStatus=state.architectText("Arquiteto: aguardando espaço livre diante da estátua.")
        return true
    end
    local offset=root.Position-stand
    if Vector3.new(offset.X,0,offset.Z).Magnitude>1 then
        sequence.arrivedAt=nil;sequence.arrivedIndex=nil
        ownMovement(root,stand,room,point);return true
    end
    -- Teleport replication must reach the server before triggering, including repeated statues.
    if sequence.arrivedIndex~=sequence.index then
        sequence.arrivedIndex=sequence.index;sequence.arrivedAt=now;return true
    end
    local velocity=root.AssemblyLinearVelocity
    if velocity and Vector3.new(velocity.X,0,velocity.Z).Magnitude>2 then
        sequence.arrivedAt=now;return true
    end
    if now-sequence.arrivedAt<0.75 then return true end
    state.architectStatus=state.architectText("Arquiteto: repetindo estátua %s/%s.",tostring(sequence.index),tostring(#sequence.points))
    if type(state.firePrompt)~="function" then runtime.problem="Arquiteto: interação indisponível neste executor.";return true end
    local serial,index=runtime.serial,sequence.index
    runtime.busy=true
    task.spawn(function()
        if not active() or state.panic or player.GameplayPaused or serial~=runtime.serial or rootPart()~=root
            or tonumber(storage:GetAttribute("CurrentRoom"))~=4 or not prompt.Parent or not prompt.Enabled
            or (root.Position-point).Magnitude>prompt.MaxActivationDistance
            or Vector3.new(root.Position.X-stand.X,0,root.Position.Z-stand.Z).Magnitude>1 then runtime.busy=false;return end
        local ok,result=pcall(state.firePrompt,prompt,prompt.HoldDuration)
        if serial~=runtime.serial or sequence~=runtime.sequence then return end
        runtime.busy=false
        if not ok or result==false then
            runtime.problem="Arquiteto: interação sem confirmação; aguardando uma nova sequência."
            return
        end
        runtime.nextPrompt=os.clock()+math.max(1.25,prompt.HoldDuration+0.5)
        sequence.arrivedAt=nil;sequence.arrivedIndex=nil
        sequence.index=index+1
        sequence.waiting=sequence.index>#sequence.points
    end)
    return true
end
table.insert(cleanupCallbacks,function() runtime.serial+=1;runtime.sequence=nil;state.architectBusy=nil end)
end

-- MANOR INTERACTIONS: scope all searches and doors to the server's current room.
do
local function installManorInteractions()
    local run = {attempts = setmetatable({}, {__mode = "k"}), nextScan = 0, nextFire = 0}
    -- MANOR PROMPT POLICY
    function state.manorPromptKind(prompt, room)
        if not prompt or not room or not prompt.Enabled or not prompt:IsDescendantOf(room) or prompt.Name ~= "ManorPrompt" then return nil end
        local parent = prompt.Parent
        if not parent then return nil end
        if parent.Parent == room:FindFirstChild("Drawers") and prompt.ActionText == "Search" then return "search" end
        local hideSpots = room:FindFirstChild("HideSpots")
        if hideSpots and parent:IsDescendantOf(hideSpots) and prompt.ActionText == "Search"
            and prompt.ObjectText == "Silver Bell?" then return "search" end
        local butler = room:FindFirstChild("ManorButler")
        if butler and parent:IsDescendantOf(butler) and prompt.ActionText == "Give" and prompt.ObjectText == "Butler" then return "give" end
        if parent == room:FindFirstChild("LockedChest") and (prompt.ActionText == "Unlock"
            or prompt.ActionText == "Open" and prompt.ObjectText == "Unlocked Chest") then return "chest" end
        if parent.Parent == room and parent.Name == "ChoiceDoor" and prompt.ActionText == "Open" then return "choice" end
        if parent == room:FindFirstChild("UpDoor") and prompt.ActionText == "Open" then return "door" end
        return nil
    end
    function state.manorPickPrompt(room, position, attempts, now, getPosition, keyFound)
        local selected, scores = {}, {}
        local choiceWaiting = false
        for prompt, attempt in pairs(attempts) do
            if prompt.Parent and prompt:IsDescendantOf(room) and prompt.Parent.Name == "ChoiceDoor" and now - attempt.at < 4 then
                choiceWaiting = true
            end
        end
        for _, prompt in ipairs(room:GetDescendants()) do
            if not prompt:IsA("ProximityPrompt") then continue end
            local kind = state.manorPromptKind(prompt, room)
            if not kind then continue end
            if keyFound and kind == "search" and prompt.Parent.Parent == room:FindFirstChild("Drawers") then continue end
            local attempt = attempts[prompt]
            if kind == "chest" and attempt and attempt.action and attempt.action ~= prompt.ActionText then attempt = nil end
            local count = attempt and attempt.count or 0
            -- Give retries slowly if the bell is missing; a later successful search resets this wait.
            if kind == "give" and count >= 2 and now - attempt.at < 30 then continue end
            -- Failed/uncertain optional interactions never become an endless loop.
            if kind ~= "door" and kind ~= "give" and count >= 2 then continue end
            if kind == "choice" and choiceWaiting then continue end
            if attempt and now - attempt.at < (kind == "door" and 4 or 2) then continue end
            local point = getPosition(prompt)
            if not point then continue end
            -- Prefer a different ChoiceDoor instance after one unanswered attempt.
            -- No safe-door marker has been confirmed; distance is a fallback, not a safety guarantee.
            local score = (point - position).Magnitude + ((kind == "choice" or kind == "search") and count * 100000 or 0)
            if not scores[kind] or score < scores[kind] then selected[kind], scores[kind] = prompt, score end
        end
        return selected.search or selected.give or selected.chest or selected.choice or selected.door
    end
    -- END MANOR PROMPT POLICY
    local function point(prompt)
        local parent = prompt.Parent
        return parent and (parent:IsA("Attachment") and parent.WorldPosition or parent:IsA("BasePart") and parent.Position) or nil
    end
    -- MANOR SEARCH RECEIPT: exact successful message supplied by the player.
    function state.manorSearchReceipt(message, account)
        if type(message) ~= "string" or type(account) ~= "string" then return nil end
        local normalized = message:gsub("<[^>]+>", ""):gsub("’", "'"):gsub("%s+", " "):match("^%s*(.-)%s*$"):lower()
        local success = account:lower() .. " found the gravewarden's key! the locked chest can be opened."
        if normalized == success then return "key" end
        if normalized:find("the countess's silver bell is missing.", 1, true) then return "missing_bell" end
        return nil
    end
    function state.observeManorSearch(packet)
        if not alive or not dungeon.enabled or not insideDungeon() or storage:GetAttribute("ManorDoor") == nil
            or storage:GetAttribute("DungeonCompleted") == true or type(packet) ~= "table" then return end
        local result = state.manorSearchReceipt(packet.Message, player.Name)
        if not result then return end
        local main = workspace:FindFirstChild("__Main")
        local world = main and main:FindFirstChild("__World")
        local manor = world and world:FindFirstChild("BloodmoonManor")
        local number = tonumber(storage:GetAttribute("ManorDoor"))
        local room = manor and number and manor:FindFirstChild("Room_" .. tostring(math.floor(number)))
        if not room then return end
        if result == "key" then
            run.keyRoom = room
            run.pending, run.nextScan, run.nextFire = nil, 0, 0
            for candidate in pairs(run.attempts) do
                if candidate.Parent and state.manorPromptKind(candidate, room) == "chest" then run.attempts[candidate] = nil end
            end
        end
        -- A missing-bell instruction is not evidence of a successful search.
    end
    local receipt = require(storage.BridgeNet2).ReferenceBridge("WARN_EVENT"):Connect(function(packet)
        pcall(state.observeManorSearch, packet)
    end)
    table.insert(cleanupCallbacks, function() receipt:Disconnect() end)
    -- END MANOR SEARCH RECEIPT
    function state.manorInteractionStep()
        state.manorBusy = nil
        if not dungeon.enabled or not insideDungeon() or storage:GetAttribute("ManorDoor") == nil
            or storage:GetAttribute("DungeonCompleted") == true or state.manorHuntActive or state.raidPaused or player:GetAttribute("ManorHidden") == true then return false end
        local root, now = rootPart(), os.clock()
        if not root or player:GetAttribute("ManorOut") == true then return false end
        local main = workspace:FindFirstChild("__Main")
        local world = main and main:FindFirstChild("__World")
        local manor = world and world:FindFirstChild("BloodmoonManor")
        local number = tonumber(storage:GetAttribute("ManorDoor"))
        local room = manor and number and manor:FindFirstChild("Room_" .. tostring(math.floor(number)))
        if not room then
            state.manorStatus = "Bloodmoon: aguardando a sala atual carregar."
            return false
        end
        -- Living enemies take precedence over drawers/door. Never advance based on a dead target alone.
        if nearest(enemyFolder(), root.Position, nil, nil) then return false end
        state.manorBusy, state.target, state.searchPosition = true, nil, nil
        if run.room ~= room or run.root ~= root then
            if run.keyRoom ~= room or run.root and run.root ~= root then run.keyRoom = nil end
            run.room, run.root, run.nextScan, run.pending = room, root, 0, nil
        end
        if now < run.nextScan then return true end
        run.nextScan = now + 0.3
        local pending = run.pending
        if pending and pending.prompt.Parent and pending.prompt.Enabled and now - pending.at < pending.wait then
            state.manorStatus = "Bloodmoon: aguardando resultado da interação."
            return true
        end
        if pending and pending.kind == "search" and (not pending.prompt.Parent or not pending.prompt.Enabled) then
            -- The search ended, but its content is unknown. Allow native Give/Unlock to check again.
            for candidate in pairs(run.attempts) do
                local kind = candidate.Parent and state.manorPromptKind(candidate, room)
                if kind == "give" or kind == "chest" then run.attempts[candidate] = nil end
            end
        end
        run.pending = nil
        local prompt = state.manorPickPrompt(room, root.Position, run.attempts, now, point, run.keyRoom == room)
        if not prompt then
            state.manorBusy = nil
            state.manorStatus = "Bloodmoon: aguardando liberação da porta ou evento da sala."
            return false
        end
        if type(state.firePrompt) ~= "function" then
            state.manorBusy = nil
            state.manorStatus = "Bloodmoon: executor sem interação com prompts."
            return false
        end
        local position = point(prompt)
        local reach = math.max(1, prompt.MaxActivationDistance - 2)
        if (position - root.Position).Magnitude > reach then
            -- Approach the room's prompt, not the wall/closed door's far side.
            local horizontal = Vector3.new(root.Position.X - position.X, 0, root.Position.Z - position.Z)
            local offset = horizontal.Magnitude > 0.01 and horizontal.Unit * math.min(5, reach / 2) or Vector3.new(0, 0, 3)
            local destination = Vector3.new(position.X, root.Position.Y, position.Z) + offset
            root.AssemblyLinearVelocity = Vector3.zero
            root.CFrame = CFrame.new(destination)
            state.lastFarmPosition = destination
            state.manorStatus = "Bloodmoon: aproximando da interação da sala atual."
            return true
        end
        if now < run.nextFire then return true end
        local previous = run.attempts[prompt]
        if previous and previous.action and previous.action ~= prompt.ActionText then previous = nil end
        local kind = state.manorPromptKind(prompt, room)
        run.attempts[prompt] = {count = (previous and previous.count or 0) + 1, at = now, action = prompt.ActionText}
        run.pending, run.nextFire = {prompt = prompt, kind = kind, at = now, wait = kind == "choice" and 4 or 2}, now + math.max(2, prompt.HoldDuration + 0.5)
        state.manorStatus = "Bloodmoon: interagindo com " .. prompt.ObjectText .. "."
        task.spawn(function()
            if not alive or state.panic or not dungeon.enabled or state.raidPaused or state.manorHuntActive or player:GetAttribute("ManorHidden") == true
                or not prompt.Parent or not prompt.Enabled or run.room ~= room then return end
            if kind == "search" and run.keyRoom == room and prompt.Parent.Parent == room:FindFirstChild("Drawers") then return end
            pcall(state.firePrompt, prompt, prompt.HoldDuration)
        end)
        return true
    end
end
installManorInteractions()
end
-- END MANOR INTERACTIONS

-- Um unico controlador de movimento. Nao ataca quando desligado ou sem alvo confirmado.
do
    local cache
    function state.groundFarmPosition(position,root)
        if insideDungeon() or not root or not root.Parent then return position,false end
        local character=root.Parent
        local humanoid=character:FindFirstChildOfClass("Humanoid")
        if not humanoid then return position,false end
        local now=os.clock()
        if cache and cache.character==character and now-cache.at<0.25
            and (position-cache.request).Magnitude<0.5 then return cache.position,true end
        local params=RaycastParams.new()
        params.FilterType=Enum.RaycastFilterType.Exclude
        local excluded={character}
        local enemies=enemyFolder();if enemies then excluded[#excluded+1]=enemies end
        params.FilterDescendantsInstances=excluded
        params.RespectCanCollide=true
        local hit=workspace:Raycast(position+Vector3.new(0,4,0),Vector3.new(0,-100,0),params)
        if not hit or hit.Normal.Y<0.6 then return position,false end
        local height=math.max(0,humanoid.HipHeight)+root.Size.Y/2
        -- R6 HipHeight excludes the legs; R15 already includes the leg clearance.
        if humanoid.RigType==Enum.HumanoidRigType.R6 then
            local leg=character:FindFirstChild("Left Leg") or character:FindFirstChild("Right Leg")
            if not leg then return position,false end
            height+=leg.Size.Y
        end
        local grounded=Vector3.new(position.X,hit.Position.Y+height,position.Z)
        cache={character=character,request=position,position=grounded,at=now}
        return grounded,true
    end
    function state.placeFarmRoot(root,position,lookAt)
        local grounded,hasGround=state.groundFarmPosition(position,root)
        if hasGround and (root.Position-grounded).Magnitude<0.2 then
            -- Let gravity/contact settle instead of resetting Freefall every frame.
            local velocity=root.AssemblyLinearVelocity
            root.AssemblyLinearVelocity=Vector3.new(0,velocity.Y,0)
            return
        end
        root.AssemblyLinearVelocity=Vector3.zero
        root.CFrame=lookAt and CFrame.lookAt(grounded,Vector3.new(lookAt.X,grounded.Y,lookAt.Z)) or CFrame.new(grounded)
    end
end
connect(RunService.Heartbeat, function()
    if not alive or state.panic or state.leaving or state.autoLeaving or state.rebirthing or player.GameplayPaused or (os.clock() < (state.entryUntil or 0) and not state.manorHuntActive) then
        if state.dodge and state.dodge.cancel then state.dodge.cancel() end
        return
    end
    state.manorBusy = nil
    state.architectBusy=state.architectPuzzleActive and state.architectPuzzleActive() or false
    if state.raidGuardStep then
        local ok, controlled = pcall(state.raidGuardStep)
        if ok and controlled then return end
        if not ok then
            state.raidPaused = true
            state.raidGuardStatus = "Falha na proteção de raid: " .. tostring(controlled)
            if state.raidGuardProblem ~= tostring(controlled) then warn("[VykronHub] " .. state.raidGuardStatus) end
            state.raidGuardProblem = tostring(controlled)
            return
        end
        state.raidGuardProblem = nil
    end
    if state.architectStep then
        local ok,controlled=pcall(state.architectStep)
        if not ok then
            state.architectBusy=true;state.target=nil
            state.architectStatus=state.architectText("Arquiteto: recuperação do controlador.").." "..tostring(controlled)
            return
        elseif controlled then return end
    end
    if state.manorInteractionStep then
        local ok, controlled = pcall(state.manorInteractionStep)
        if not ok then
            state.manorBusy = nil
            state.manorStatus = "Bloodmoon: interação em espera. " .. tostring(controlled)
        elseif controlled then return end
    end
    if state.modeEntryDestination then
        local root = rootPart()
        if dungeon.enabled and (dungeonMode().gate or dungeon.mode=="rift" and dungeon.rift.autoIslands) and not insideDungeon() and root then
            root.AssemblyLinearVelocity = Vector3.zero
            root.CFrame = CFrame.new(state.modeEntryDestination)
        end
        state.modeEntryDestination = nil
        return
    end
    if state.eventTravel then return end
    if state.eventDestination then
        local root = rootPart()
        if root and not player:GetAttribute("Mounted") and not player:GetAttribute("Swimming") then
            root.AssemblyLinearVelocity = Vector3.zero
            root.CFrame = CFrame.new(state.eventDestination)
            state.lastFarmPosition = root.Position
            state.eventDestination = nil
        end
        return
    end
    if state.houses.busy then
        local root = rootPart()
        if root and state.houses.destination and not state.houses.travel then
            root.AssemblyLinearVelocity = Vector3.zero
            root.CFrame = CFrame.new(state.houses.destination)
            state.lastFarmPosition = root.Position
        end
        return
    end
    if state.pumpkinBusy then
        local root, target = rootPart(), pumpkin.target
        if root and target and not pumpkin.travel and not player:GetAttribute("Mounted") and not player:GetAttribute("Swimming") then
            local folder = workspace:FindFirstChild("__Extra") and workspace.__Extra:FindFirstChild("__Pumps")
            local part = availablePumpkin(target.model, folder, player.UserId)
            if part then root.AssemblyLinearVelocity = Vector3.zero root.CFrame = CFrame.new(part.Position + Vector3.new(0, 2, 2)) end
        end
        return
    end
    if player:GetAttribute("Swimming") and not player:GetAttribute("Mounted") and not insideDungeon() and not events.active then
        local island=autoQuest.enabled and questRuntime.combat and questRuntime.island or state.enabled and state.map
        local anchor=state.fixedFarmAnchor and state.fixedFarmAnchor(island)
        local root=rootPart()
        if anchor and root and (root.Position-anchor).Magnitude<250 then
            local safe,confirmed=state.groundFarmPosition(anchor,root)
            if confirmed then
                root.AssemblyLinearVelocity=Vector3.zero
                root.CFrame=CFrame.new(safe)
                state.lastFarmPosition=root.Position
            end
            return
        end
    end
    if autoQuest.enabled and (state.questPriorityActive and state.questPriorityActive() or not state.houses.enabled or state.houses.route.waitUntil ~= nil) and not events.active and not insideDungeon() then
        local root = rootPart()
        if questRuntime.destination and root and not player:GetAttribute("Mounted") and not player:GetAttribute("Swimming") then
            state.placeFarmRoot(root,questRuntime.destination)
            state.lastFarmPosition = root.Position
            return
        end
        if not questRuntime.combat then state.target = nil return end
    end
    if not farmEnabled() then return end
    local root, folder = rootPart(), enemyFolder()
    if root and state.lastFarmPosition and (root.Position - state.lastFarmPosition).Magnitude > 300 then
        state.target, state.map, state.lastFarmPosition = nil, nil, root.Position
        return
    end
    if not root then return end
    if player:GetAttribute("Mounted") or player:GetAttribute("Swimming") then return end
    if not living(state.target, folder) then
        if state.searchPosition and not state.leaving and os.clock() >= (state.entryUntil or 0) then
            if insideDungeon() then
                root.AssemblyLinearVelocity = Vector3.zero
                root.CFrame = CFrame.new(state.searchPosition)
            else state.placeFarmRoot(root,state.searchPosition) end
            state.lastFarmPosition = root.Position
        end
        return
    end
    local position = state.target.Position
    if insideDungeon() then
        root.AssemblyLinearVelocity = Vector3.zero
        root.CFrame = CFrame.lookAt(position + Vector3.new(0, 3, 4), position + Vector3.new(0, 3, 0))
    else
        local fixed=not events.active and state.fixedFarmAnchor and state.fixedFarmAnchor(state.target:GetAttribute("MapId"))
        state.placeFarmRoot(root,fixed or position+Vector3.new(0,3,4),position)
    end
    state.lastFarmPosition = root.Position
end)
task.spawn(function()
    local missingSince, searchAt, searchIndex, searchRoom, portalAt = nil, 0, 0, nil, 0
    function state.fastClickAttack(target,root)
        if not target or not root or busy or (root.Position-target.Position).Magnitude>9
            or player.GameplayPaused or player:GetAttribute("Mounted") or player:GetAttribute("Swimming")
            or state.eventTravel or state.eventDestination or state.autoLeaving
            or os.clock()<(state.attackRetryAt or 0) then return end
        if state.fastClick.enabled and os.clock()<(state.fastClick.attackAt or 0) then return end
        if not busy then
            if state.fastClick.enabled then state.fastClick.attackAt=os.clock()+state.fastClick.interval end
            busy = true
            local version = generation
            local fast=state.fastClick.enabled
            task.spawn(function()
                local stepOK, stepProblem = pcall(function()
                if alive and (not fast or state.fastClick.enabled) and not state.panic and farmEnabled() and not state.manorBusy and not state.architectBusy and not state.raidPaused and not state.manorHuntActive and player:GetAttribute("ManorHidden") ~= true and not state.leaving and not state.rebirthing and not state.pumpkinBusy and not state.houses.busy and os.clock() >= (state.entryUntil or 0) and not player.GameplayPaused and not player:GetAttribute("Mounted") and not player:GetAttribute("Swimming") and not state.eventTravel and not state.eventDestination and not state.autoLeaving and rootPart()==root and (root.Position-target.Position).Magnitude<=9 and version == generation and state.target == target and living(target, enemyFolder()) then
                    local success, problem = pcall(weapons.Click, {UserInputType = Enum.UserInputType.MouseButton1, KeyCode = Enum.KeyCode.ButtonX}, false)
                    if success then state.attacks += 1 state.attackProblem, state.attackRetryAt = nil, nil
                    else
                        local message = tostring(problem)
                        if state.attackProblem ~= message then warn("[VykronHub] Ataque em espera: " .. message) end
                        state.attackProblem, state.attackRetryAt = message, os.clock() + 3
                        state.target, state.searchPosition = nil, nil
                        status.Text = "Ataque em espera; nova tentativa em 3 s. Auto Dungeon permanece ligado."
                    end
                end
                end)
                busy = false
                if not stepOK and alive then
                    state.attackProblem, state.attackRetryAt = tostring(stepProblem), os.clock() + 3
                    state.target, state.searchPosition = nil, nil
                    status.Text = "Ataque em espera: " .. tostring(stepProblem):sub(1, 200)
                end
            end)
        end
    end
    local function gateInteraction(world, room, choice)
        local gate = world and world:FindFirstChild("TrickOrTreatGate")
        if not gate or not room then return nil end
        for _, kind in ipairs({"chest", "vote"}) do
            local indices = {}
            if kind == "chest" then
                for index = room, 1, -1 do table.insert(indices, index) end
            else indices = {room, room - 1} end
            for _, index in ipairs(indices) do
                local model = gate:FindFirstChild("Room_" .. index)
                local choices = model and model:FindFirstChild("Choice")
                local target = kind == "chest" and model and model:FindFirstChild("TreatChest")
                    or kind == "vote" and choices and choices:FindFirstChild(choice)
                local prompt = target and target:FindFirstChildWhichIsA("ProximityPrompt", true)
                local attempt = prompt and state.gateChestAttempts[prompt]
                local handled = kind == "chest" and attempt and (attempt.count >= 2 or (attempt.count >= 1 and room > index))
                if prompt and prompt.Enabled and prompt.Parent:IsA("BasePart") and not handled then return prompt end
            end
        end
    end
    local function farmStep()
        state.refreshEntryWait()
        if events.active then
            if state.openRaids[events.active] then
                if events.active=="giants" and state.giantsHunt and state.giantsHunt.controlling then
                    state.target,state.searchPosition=nil,nil
                    status.Text=state.openRaids.giants.huntStatus or "Giants: procurando invasores."
                    return
                end
                local root=rootPart()
                local target=root and state.openRaidNearest(enemyFolder(),root.Position,events.active)
                if target~=state.target then generation+=1 end
                state.target,state.worldBossTarget,state.map=target,nil,nil
                if not target or not farmEnabled() then
                    state.searchPosition=nil
                    status.Text=state.openRaids[events.active].name..": aguardando próxima fase ou fim da raid."
                    return
                end
            elseif events.active == "guild" then
                local root = rootPart()
                local target = root and state.guildNearest and state.guildNearest(root.Position)
                if state.target ~= target then generation += 1 end
                state.target, state.guildTarget, state.map = target, target, nil
                if not target or not farmEnabled() then state.searchPosition = nil return end
            elseif events.active == "kamish" then
                local boss = state.kamishBoss()
                if boss ~= state.worldBossTarget then generation += 1 end
                state.worldBossTarget, state.target, state.map = boss, boss, nil
                if not boss then state.searchPosition = nil return end
            elseif events.active == "boss" or events.active == "pumpkinking" then
                local root = rootPart()
                local boss = root and nearestWorldBoss(enemyFolder(), root.Position, events.active == "pumpkinking" and "pumpkinking" or nil) or nil
                if boss ~= state.worldBossTarget then generation += 1 end
                state.worldBossTarget, state.target, state.map = boss, boss, nil
                if not boss then state.searchPosition = nil return end
            else
                state.map = events.mapOrder
            end
        end
        if state.eventTravel or state.eventDestination then state.target, state.searchPosition = nil, nil return end
        if not farmEnabled() then
            state.searchPosition = nil missingSince = nil
            if state.enabled then
                status.Text = events.active and "Auto Farm aguardando o evento prioritário."
                    or state.autoLeaving and "Auto Farm aguardando a saída do modo."
                    or (state.houses.enabled and not state.houses.route.waitUntil) and "Auto Farm aguardando a coleta das casas."
                    or autoQuest.enabled and "Auto Farm aguardando o objetivo da Auto Quest."
                    or "Auto Farm aguardando liberação do combate."
            end
            return
        end
        if state.rebirthing then state.target, state.searchPosition = nil, nil status.Text = "Aguardando rebirth..." return end
        if state.pumpkinBusy or state.houses.busy or os.clock() < (state.entryUntil or 0) then state.target = nil state.searchPosition = nil missingSince = nil status.Text = "Aguardando coleta ou entrada..." return end
        if state.leaving then state.target = nil state.searchPosition = nil missingSince = nil status.Text = "Saindo da dungeon..." return end
        local root, folder = rootPart(), enemyFolder()
        if not root then state.target = nil status.Text = "Aguardando personagem..." return end
        if player.GameplayPaused then state.target = nil status.Text = "Aguardando o carregamento da área..." return end
        if player:GetAttribute("Mounted") or player:GetAttribute("Swimming") then status.Text = "Desmonte ou saia da agua para atacar." return end
        if state.architectBusy then
            if state.target then generation+=1 end
            state.target,state.searchPosition=nil,nil
            status.Text=state.architectStatus or state.architectText("Arquiteto: resolvendo a sala atual.")
            return
        end
        -- Infernal progression belongs exclusively to native AfkCastle; never move to or fire its portal.
        state.castleRecoveryStatus = nil
        if storage:GetAttribute("IsHeavenCastle") == true and storage:GetAttribute("IsCastle") ~= true then
            local main = workspace:FindFirstChild("__Main")
            local world = main and main:FindFirstChild("__World")
            local room = tonumber(storage:GetAttribute("CurrentRoom"))
            local now = os.clock()
            local cleared = state.castleAdvanceReady(room, storage:GetAttribute("DungeonMessage"), now)
            local portal, prompt, portalRoom, destination = castlePortal(world, root.Position, room, state.castlePortalUsed)
            local recovery = false
            if not cleared then
                local hasEnemy = state.castleHasEnemyEvidence(folder)
                local points = room and state.castleRecoveryPoints(world, room)
                local eligible = points ~= nil and portal ~= nil and prompt ~= nil and destination ~= nil
                    and portalRoom == room and storage:GetAttribute("DungeonCompleted") ~= true
                if eligible and not hasEnemy then
                    local scan = state.castleRecoveryStream
                    if not scan or scan.room ~= room or scan.root ~= root then
                        scan = {room = room, root = root, done = false}
                        state.castleRecoveryStream = scan
                        local destinations = {root.Position}
                        if #points > 0 then
                            for _, fraction in ipairs({0, 0.5, 1}) do
                                local point = points[math.max(1, math.floor((#points - 1) * fraction) + 1)]
                                table.insert(destinations, point)
                            end
                        else table.insert(destinations, destination) end
                        task.spawn(function()
                            for _, point in ipairs(destinations) do
                                if not alive or state.panic or not farmEnabled() or rootPart() ~= root
                                    or state.castleRecoveryStream ~= scan or tonumber(storage:GetAttribute("CurrentRoom")) ~= room then return end
                                local ok = pcall(function() player:RequestStreamAroundAsync(point, 1) end)
                                if not ok then scan.failed = true return end
                            end
                            if state.castleRecoveryStream == scan and tonumber(storage:GetAttribute("CurrentRoom")) == room then scan.done = true end
                        end)
                    end
                    recovery = state.castleRecoveryReady(room, root, now, false, true, scan.done == true)
                    if scan.failed then
                        state.castleRecoveryStatus = "Não foi possível carregar a sala; recuperação do portal suspensa."
                    elseif not scan.done then
                        state.castleRecoveryStatus = "Contador inconsistente: carregando a sala antes de conferir o portal..."
                    elseif not recovery then
                        local elapsed = state.castleRecovery and now - state.castleRecovery.emptyAt or 0
                        state.castleRecoveryStatus = "Sala sem inimigos detectáveis: conferindo portal em " .. math.max(0, math.ceil(8 - elapsed)) .. " s..."
                    end
                else
                    state.castleRecoveryReady(room, root, now, hasEnemy, eligible, false)
                    state.castleRecoveryStream = nil
                end
            else state.castleRecovery, state.castleRecoveryStream = nil, nil end
            if cleared or recovery then
                if state.target then generation += 1 end
                state.target, state.searchPosition = nil, nil
                missingSince, searchAt, searchIndex, searchRoom = nil, 0, 0, nil
                if not portal or not prompt or not destination then
                    status.Text = "Andar concluído: aguardando carregar o portal."
                    return
                end
                -- Move directly to the prompt, rather than waiting for generic enemy search movement.
                local reach = math.max(0.5, prompt.MaxActivationDistance * 0.5)
                local targetPosition = destination + Vector3.new(0, math.min(2, reach), 0)
                root.AssemblyLinearVelocity = Vector3.zero
                root.CFrame = CFrame.new(targetPosition)
                state.lastFarmPosition = targetPosition
                if type(state.firePrompt) ~= "function" then status.Text = "Interação do portal indisponível no executor." return end
                if os.clock() - portalAt >= (recovery and 8 or 3) then
                    local hold = math.max(prompt.HoldDuration, 0.1)
                    portalAt = os.clock()
                    state.entryUntil = os.clock() + hold + 0.5
                    task.spawn(function()
                        if not alive or state.panic or not farmEnabled() or player.GameplayPaused
                            or rootPart() ~= root or tonumber(storage:GetAttribute("CurrentRoom")) ~= room
                            or not prompt.Parent or not prompt.Enabled then return end
                        local nativeZero = state.castleAdvanceReady(room, storage:GetAttribute("DungeonMessage"), os.clock())
                        local scan = state.castleRecoveryStream
                        local recovered = recovery and scan and scan.done and scan.root == root and scan.room == room
                            and not state.castleHasEnemyEvidence(enemyFolder())
                            and state.castleRecoveryReady(room, root, os.clock(), false, true, true)
                        if not nativeZero and not recovered then return end
                        if not storage:GetAttribute("IsCastle") and not storage:GetAttribute("IsHeavenCastle") then return end
                        local parent = prompt.Parent
                        local point = parent:IsA("Attachment") and parent.WorldPosition or parent:IsA("BasePart") and parent.Position or destination
                        if (root.Position - point).Magnitude > prompt.MaxActivationDistance then return end
                        local ok, failure = pcall(state.firePrompt, prompt, hold)
                        if not ok or failure == false then
                            state.castlePortalProblem = not ok and tostring(failure) or "Interação recusada; aguardando nova tentativa."
                        else state.castlePortalProblem = nil end
                    end)
                end
