            end
        else state.castleRecovery, state.castleRecoveryStream = nil, nil end
        if not folder then state.target = nil status.Text = "Aguardando carregar os inimigos..." return end
        if os.clock() < (state.attackRetryAt or 0) then
            status.Text = "Ataque em espera; nova tentativa em " .. math.ceil(state.attackRetryAt - os.clock()) .. " s."
            return
        end
        local quest = autoQuest.enabled and (state.questPriorityActive and state.questPriorityActive() or not state.houses.enabled or state.houses.route.waitUntil ~= nil) and not events.active and not insideDungeon() and questRuntime.filter or nil
        if insideDungeon() or quest then state.map = nil end
        if quest and state.target and not questEnemyMatches(quest, state.target:GetAttribute("Id"), state.target:GetAttribute("MapId"), quest.info[state.target:GetAttribute("Id")]) then state.target = nil end
        do
            if state.target and state.target:GetAttribute("Id")=="EclipseAizenClone"
                and (storage:GetAttribute("RaidTitle")=="THE ECLIPSE COURT" or storage:GetAttribute("DungeonMap")=="EclipseCourtRaid") then
                state.target,state.searchPosition=nil,nil
                generation+=1
            end
            local architectTarget,architectWait
            if state.architectPriority then architectTarget,architectWait=state.architectPriority(folder,root.Position) end
            if architectWait and not architectTarget then
                if state.target then generation+=1 end
                state.target,state.searchPosition=nil,nil
                status.Text=state.architectText("Arquiteto: escudo ativo; aguardando as janelas.")
                return
            end
            local priority = state.halloweenClonePriority(folder,root.Position) or architectTarget or state.baizenClonePriority(folder, root.Position) or state.eclipseKnightPriority(folder, root.Position)
            local highest=dungeon.utilities.highestHP and insideDungeon() and not events.active
            if not priority and highest then priority=state.highestDungeonTarget(folder,root.Position) end
            if (priority or highest) and state.target ~= priority then
                if state.target and (enemyState.Dead(state.target) or tonumber(enemyState.HP(state.target))==0) then state.kills+=1 end
                generation += 1
                state.target, state.searchPosition, missingSince = priority, nil, nil
            end
        end
        if not living(state.target, folder) then
            if events.active == "guild" then state.target, state.searchPosition = nil, nil return end
            if state.target and (enemyState.Dead(state.target) or tonumber(enemyState.HP(state.target)) == 0) then state.kills += 1 end
            state.target = nearest(folder, root.Position, state.map, quest)
            if state.target and not quest and not state.map and not insideDungeon() then
                local mapId = state.target:GetAttribute("MapId")
                if mapId ~= nil then state.map = tostring(mapId) end
            end
        end
        local target = state.target
        if state.manorHuntActive or player:GetAttribute("ManorHidden") == true then
            state.target, state.searchPosition = nil, nil
            status.Text = state.raidGuardStatus or "Proteção de raid em andamento..."
            return
        end
        if state.manorBusy then status.Text = state.manorStatus or "Bloodmoon: verificando sala atual." return end
        if state.raidPaused then status.Text = state.raidGuardStatus or "Proteção de raid em andamento..." return end
        if state.houses.fighting and target and (target.Position - state.houses.fightPosition).Magnitude > 80 then
            state.target, state.searchPosition = nil, nil
            return
        end
            if dungeon.enabled and state.trickGateWorld() then
                local main = workspace:FindFirstChild("__Main")
                local prompt = gateInteraction(main and main:FindFirstChild("__World"), tonumber(storage:GetAttribute("CurrentRoom")), dungeon.trickChoice or "Treat")
                if prompt and (not target or prompt.ActionText == "Open") then
                    if state.target then generation += 1 end
                    state.target = nil
                    if type(state.firePrompt) ~= "function" then status.Text = "O executor não oferece interação com o gate." return end
                    if (root.Position - prompt.Parent.Position).Magnitude > prompt.MaxActivationDistance - 2 then
                        state.searchPosition = prompt.Parent.Position + Vector3.new(0, 3, 3)
                        status.Text = "Indo ao baú/voto do Trick or Treat Gate..."
                    elseif os.clock() - portalAt >= 4 then
                        state.searchPosition, portalAt = nil, os.clock()
                        state.entryUntil = os.clock() + prompt.HoldDuration + 0.5
                        task.spawn(function()
                            local ok = pcall(state.firePrompt, prompt, prompt.HoldDuration)
                            if ok and prompt.ActionText == "Open" then
                                local attempt = state.gateChestAttempts[prompt]
                                state.gateChestAttempts[prompt] = {count = (attempt and attempt.count or 0) + 1}
                            end
                        end)
                        status.Text = "Interagindo: " .. prompt.ActionText
                    end
                    return
                end
            end
        if not target then
            status.Text = "Aguardando mobs vivos no mapa atual..."
            if storage:GetAttribute("IsCastle") or storage:GetAttribute("IsHeavenCastle") then
                local remaining = state.castleCounter(storage:GetAttribute("DungeonMessage"))
                status.Text = remaining and ("Inimigos restantes: " .. remaining .. ". Aguardando confirmação do andar.")
                    or "Aguardando contador de inimigos do andar."
                if storage:GetAttribute("IsCastle") == true then status.Text = state.castleAFK.status or "Infernal Castle: waiting for native AFK to advance." end
            end
            local room = tonumber(storage:GetAttribute("CurrentRoom"))
            local castle = storage:GetAttribute("IsCastle") or storage:GetAttribute("IsHeavenCastle")
            local canSearch = storage:GetAttribute("IsCastle") ~= true and (castle or state.trickGateWorld() or (storage:GetAttribute("Dungeon") == true and type(storage:GetAttribute("DungeonMap")) == "string"))
                and storage:GetAttribute("DungeonCompleted") ~= true and not storage:GetAttribute("InTimeTrial")
                and (castle or not storage:GetAttribute("InfiniteDungeon")) and room ~= nil
            if not canSearch then state.searchPosition = nil missingSince = nil return end
            local now = os.clock()
            missingSince = missingSince or now
            if searchRoom ~= room then
                missingSince, searchRoom, searchIndex, searchAt = now, room, 0, -math.huge
                state.searchPosition = nil
            end
            if now - missingSince >= 0.4 and (not state.searchPosition or now - searchAt >= 1.25) then
                local main = workspace:FindFirstChild("__Main")
                local world = main and main:FindFirstChild("__World")
                world = state.trickGateWorld() or world
                local points = dungeonSearchPoints(world, room, castle)
                if #points > 0 then
                    searchIndex = searchIndex % #points + 1
                    state.searchPosition = points[searchIndex]
                    searchAt = now
                    local destination = state.searchPosition
                    if not state.searchStreamBusy then
                        state.searchStreamBusy = true
                        task.spawn(function()
                            pcall(function() player:RequestStreamAroundAsync(destination, 1) end)
                            state.searchStreamBusy = nil
                        end)
                    end
                else state.searchPosition = nil end
            end
            if state.searchPosition then status.Text = "Buscando NPCs distantes nas salas carregadas..." end
            if state.castleRecoveryStatus then status.Text = state.castleRecoveryStatus end
            return
        end
        state.searchPosition, missingSince = nil, nil
        status.Text = (target:GetAttribute("Id") == "EclipseAizenBoss" and "Baizen: seguindo a posição do marcador verdadeiro.\n" or "")
            .. "Alvo: " .. tostring(target:GetAttribute("Id")) .. "\nHP: " .. tostring(enemyState.HP(target)) .. "\nMobs derrotados: " .. state.kills
        state.fastClickAttack(target,root)
    end
    while alive do
        task.wait(0.2)
        if not alive then break end
            if state.panic then continue end
        local ok, problem = pcall(farmStep)
        if not ok then
            state.target, state.searchPosition = nil, nil
            state.farmLoopProblem = tostring(problem)
            status.Text = "Farm em recuperação: " .. state.farmLoopProblem:sub(1, 200)
            task.wait(1)
        else state.farmLoopProblem = nil end
    end
end)
state.fastClickRestore()
state.applyMiniIcon()
state.localizeTree(gui)
state.applyLanguage()
refresh()
print("[VykronHub] " .. state.build .. " · Pronto: Farm, Dungeon e Misc. Estado do farm: " .. tostring(state.enabled))
