local bootstrapSource = [====[
-- Continuidade da sessao atual do Roblox; nao usa a pasta autoexec.
local userId, resume = ...
if not game:IsLoaded() then game.Loaded:Wait() end
local player = game:GetService("Players").LocalPlayer
while not player do task.wait() player = game:GetService("Players").LocalPlayer end
if player.UserId ~= userId then return nil end
local env = getgenv()
local path = "VykronHub/" .. userId .. ".json"
local function enabled()
    local ok, data = pcall(function() return game:GetService("HttpService"):JSONDecode(readfile(path)) end)
    if not ok or type(data) ~= "table" or data.userId ~= userId then return false end
    local houses = data.houses
    local continuingHouses = type(houses) == "table" and houses.enabled == true and type(houses.route) == "table"
        and type(houses.route.nextWorld) == "number" and houses.route.nextWorld >= 1 and houses.route.nextWorld <= 3
    local guildReturn = type(data.guild) == "table" and type(data.guild.journey) == "table"
        and data.guild.journey.phase == "return" and type(data.guild.journey.nextWorld) == "number"
        and data.guild.journey.nextWorld >= 1 and data.guild.journey.nextWorld <= 3
    local route=data.raidTravel
    local raidContinuation=type(route)=="table" and type(route.originWorld)=="number"
        and route.originWorld>=1 and route.originWorld<=3
        and (route.phase=="going" or route.phase=="returning")
        and type(route.expiresAt)=="number" and route.expiresAt>workspace:GetServerTimeNow()
    return data.autoExecute == true or raidContinuation or continuingHouses or guildReturn
end
if not enabled() then return nil end
local previous = env.__AriseAutoSession
if previous and previous.version == 3 then return previous end
if previous and previous.connection then previous.connection:Disconnect() end
local queue = queue_on_teleport or queueonteleport or (syn and syn.queue_on_teleport)
if type(queue) ~= "function" then return nil end
local session = {version = 3, queued = false}
env.__AriseAutoSession = session
function session.arm()
    if session.queued or not enabled() then return end
    local auth=env.__VykronHubLicense
    if auth and not auth:isValid() then return end
    local source = string.format('local f = loadstring(readfile("VykronHub/AutoExecute.luau")); if f then f(%s, true) end', tostring(userId))
    local ok, problem = pcall(queue, source)
    session.queued, session.problem = ok, not ok and tostring(problem) or nil
end
session.arm()
session.connection = player.OnTeleport:Connect(function(state)
    if state == Enum.TeleportState.Failed then session.queued = false session.arm() return end
    if state ~= Enum.TeleportState.Started then return end
    if session.beforeTeleport then session.beforeTeleport() end
    session.arm()
end)
if resume and game.GameId == 7074860883 then
    local deadline = os.clock() + 120
    local ready = false
    repeat
        local shared = game:GetService("ReplicatedStorage"):FindFirstChild("SharedModules")
        local scripts = player:FindFirstChild("PlayerScripts")
        local ui = scripts and scripts:FindFirstChild("NewUI", true)
        ready = shared and shared:FindFirstChild("WeaponsModule") and ui and ui:FindFirstChild("Screens")
        if ready then break end
        task.wait(0.5)
    until os.clock() >= deadline or not enabled()
    if ready and enabled() then
        local ok, problem = pcall(function()
            assert(loadstring(readfile("VykronHub/Hub.luau")))()
        end)
        if not ok then warn("[VykronHub] Auto Execute: " .. tostring(problem)) end
    end
end
return session
]====]
writefile("VykronHub/Hub.luau", hubSource)
writefile("VykronHub/AutoExecute.luau", bootstrapSource)
assert(loadstring(hubSource))()
]=====]
local licensedBootstrap = [====[
local userId, resume, originGameId = ...
if not game:IsLoaded() then game.Loaded:Wait() end
local player = game:GetService("Players").LocalPlayer
while not player do task.wait() player = game:GetService("Players").LocalPlayer end
if player.UserId ~= userId then return nil end
originGameId = tostring(originGameId or game.GameId)
local env = getgenv()
local function enabled()
    local path = originGameId == "7074860883" and ("VykronHub/" .. userId .. ".json")
        or ("VykronHub/Profiles/" .. originGameId .. "_" .. userId .. ".json")
    local ok, data = pcall(function() return game:GetService("HttpService"):JSONDecode(readfile(path)) end)
    if not ok or type(data) ~= "table" or data.userId ~= userId then return false end
    local h = data.houses
    local guildReturn = originGameId == "7074860883" and type(data.guild) == "table" and type(data.guild.journey) == "table"
        and data.guild.journey.phase == "return" and type(data.guild.journey.nextWorld) == "number"
        and data.guild.journey.nextWorld >= 1 and data.guild.journey.nextWorld <= 3
    local route=data.raidTravel
    local raidContinuation=type(route)=="table" and type(route.originWorld)=="number"
        and route.originWorld>=1 and route.originWorld<=3
        and (route.phase=="going" or route.phase=="returning")
        and type(route.expiresAt)=="number" and route.expiresAt>workspace:GetServerTimeNow()
    raidContinuation=originGameId=="7074860883" and raidContinuation
    return data.autoExecute == true or raidContinuation or guildReturn or (originGameId == "7074860883" and type(h) == "table"
        and h.enabled == true and type(h.route) == "table" and type(h.route.nextWorld) == "number"
        and h.route.nextWorld >= 1 and h.route.nextWorld <= 3)
end
if not enabled() then return nil end
local old = env.__AriseAutoSession
if old and old.version == "multi-raid-2" and old.originGameId == originGameId then return old end
if old and old.connection then old.connection:Disconnect() end
local queue = queue_on_teleport or queueonteleport or (syn and syn.queue_on_teleport)
if type(queue) ~= "function" then return nil end
local session = {version = "multi-raid-2", originGameId = originGameId, queued = false}
env.__AriseAutoSession = session
function session.arm()
    if session.queued or not enabled() then return end
    local auth = env.__VykronHubLicense
    if auth and not auth:isValid() then return end
    local source = string.format('assert(loadstring(readfile("VykronHub/AutoExecute.luau")))(%s, true, %q)', tostring(userId), originGameId)
    local ok, problem = pcall(queue, source)
    session.queued, session.problem = ok, not ok and tostring(problem) or nil
end
session.arm()
session.connection = player.OnTeleport:Connect(function(status)
    if status == Enum.TeleportState.Failed then session.queued = false session.arm() return end
    if status == Enum.TeleportState.Started then
        if session.beforeTeleport then session.beforeTeleport() end
        session.arm()
    end
end)
if resume and env.__VykronHubResumeJob ~= game.JobId then
    env.__VykronHubResumeJob = game.JobId
    local ok, problem = pcall(function()
        assert(loadstring(readfile("VykronHub/Loader.luau")))(true)
    end)
    if not ok then warn("[VykronHub] Nao foi possivel abrir o loader: " .. tostring(problem)) end
end
return session
]====]
local start = assert(loadstring(originalSource, "VykronHubOriginal"))
-- Redirect only the two continuity files written by the original installer.
-- The original source itself is not edited.
local realWrite = writefile
local scope = setmetatable({writefile = function(path, content)
    if path == "VykronHub/AutoExecute.luau" then content = licensedBootstrap
    elseif path == "VykronHub/Hub.luau" then content = 'error("Abra pelo loader com uma key valida")' end
    return realWrite(path, content)
end}, {__index = getfenv(start)})
assert(type(setfenv) == "function", "Executor sem suporte ao adaptador licenciado")
setfenv(start, scope)
assert(license:isValid(), "Autorizacao expirada")
start()
